window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[9]=[{"i":21844,"n":"י' אברהם סגל לוי מלבוב","b":"ראב\"ד בלבוב-תכ\"א"},{"i":21845,"n":"יאבילוב, מרדכי צבי ממינסק","b":"עסקן מחכמי מינסק-תרם בזמן הגדול ממינסק. נקרא יחד עם גיסו - ר מרדכי סולומונוב בשם - \"די מאטקעס\"."},{"i":21846,"n":"יאגלניק, נחמן מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":21847,"n":"יאזלוויצר, יהודה מלבוב","f":"יהודה מיזלוביץ ולבוב","b":"חתם-תנה עם ר פנחס משה, ר חיים מאך מצוזמיר, ועוד. אולי בנו - ר יצחק יאזליוויץ שהתווכח עם כת הפרנקיסטים."},{"i":21848,"n":"יאחיה, נסים מתתיה","b":"תלמיד ר חזקיה מדיני בעל \"שדי חמד\", ונזכר ב\"מכתב לחזקיהו\"."},{"i":21849,"n":"יאחינסאהן, שמעון צבי","f":"יחיאל מיכל","k":"בעל יפאר ענוים"},{"i":21850,"n":"יאיון, יהודה מסלא-מרוקו","b":"מחכמי סלא-מרוקו, חתם על פס\"ד-תקצו עם ר מסעוד אנקאווא."},{"i":21851,"n":"יאיר","f":"רבינו מאיר","b":"מגדולי חכמי איטליה-שנת מ'"},{"i":21852,"n":"יאיר הכהן מליפאנטו","f":"שבתי","b":"רב בליפאנטו-שנות ה-ש'."},{"i":21853,"n":"יאיר הכהן מסעליש","f":"יחיאל","b":"רבה הראשון של סעליש(=סוליש) ומחוז אוגוטשא ור יהודה הכהן על מקומו אחריו. נכדו - ר חיים משה - רב בסעליש."},{"i":21854,"n":"יאיר מגויטיין","b":"רב בבודאשיץ,גויטיין-תק\"ל"},{"i":21855,"n":"יאיר ן, אברהם מאלגיר וצפת","bt":"תקנד","bp":"אלגיר","b":"רב באלגיר, עלה לארץ-תקצז והתישב בצפת. חתם על אגרת מצפת-תקצט."},{"i":21856,"n":"יאיר, צבי הירש מרייוויץ, ונ\"י","k":"בעל חמודי צבי","b":"רב בוייוויץ, ניו יורק-תשכב."},{"i":21857,"n":"יאכילזון, לוי יצחק מניו יורק","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":21858,"n":"יאלוב, שמואל ליב מארה\"ב","f":"משה","k":"בעל מנחת שמואל","bt":"תרנג","bp":"ראקישקי-ליטא","dt":"תשלד - יג אלול","b":"תלמיד ישיבות סלובודקא, קובנא, ראדין. חתן ר ישעיה הכהן מרקוס. נסמך מאת: ר יהודה ליב גורדון מלומזה, דודו - ר בצלאל הכהן מראקישקי. היגר לארה\"ב וכיהן כרב באנסאניא-תרעח, סירקוז-ארה\"ב-תרפד. פרסם מאמרים ב\"דברי תבונה\" - קובנה תרף, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"תבונה\" - קובנא תרפא. חתנו - ר ישראל דב לרנר - רב בצ'סטר-פנסילבניה."},{"i":21859,"n":"יאליץ, שמעון מקראקא","f":"ליב","b":"אביר הרועים,חכם הכולל,פרנס ומנהיג בקרקא ובועד דד\"א-ת\"ק"},{"i":21860,"n":"יאמי, אהרן מראסיין","dt":"תרטו","dp":"ראסיין","b":"אב\"ד פלאטל-פלך קובנא, רב בראסיין."},{"i":21861,"n":"יאמפלר, גרשון","dt":"תקסד - ב סיון","b":"מקובל,דרשן,מגדולי חכמי ברוד"},{"i":21862,"n":"יאנה, מכלוף","b":"פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ."},{"i":21863,"n":"יאנה, עטייה מג'רבה","b":"רב בג'רבא בשנות ה-תר."},{"i":21864,"n":"יאנובר, יוסף מפינסק","f":"אריה יהודה סלוצקר","dt":"תקפה - חוהמ פסח","b":"רב בפינסק"},{"i":21865,"n":"יאנובר, צבי חריף מפיורדא","dt":"תקמו - יא כסלו","b":"חריף,ראש ישיבה בפוזן-תקל\"ד,רב בפיורדא"},{"i":21866,"n":"יאנקו, מנדל","b":"רב במרגנטהיים-ת\"פ"},{"i":21867,"n":"יאס, שמואל","dt":"תפא - כא אלול","b":"מרביץ תורה,מגדולי פרג"},{"i":21868,"n":"יאסים, מרדכי מפישטשאנקא","f":"בצלאל","k":"בעל מאמר מרדכי","bt":"תרלד","b":"רב בפישצטקה(=פישטשאנקא)-פודוליה-תרס. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס. נסמך מאת: ר ליבוש לנדא בעל \"יד יהודה\", ר בנימין אריה וייס מטשרנוביץ בעל \"אבן יקרה\". חיבר \"מאמר מרדכי\" - בכת\"י, עם הסכמות."},{"i":21869,"n":"יאפאקג'י, חיים הלוי מירושלים","dt":"תריז - ב שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":21870,"n":"יאפו, יהודה ליב","k":"בעל שלומים לריב ציון","bp":"קובנא","dt":"1892","dp":"קובנא","b":"התפרנס ממסחר - אך השקיע רוב זמנו בלימוד תורה. חיבר גם \"מחשבת חודש\" על \"מלאכת מחשבת\" לר משה חפץ. חיבר \"יד יהודה\" - בכת\"י."},{"i":21871,"n":"יאפיל, אברהם מאלגיר","f":"מימון","bt":"תס","dt":"תקל - בערך","b":"אב\"ד אלגיר על מקום ר יהודה עייאש שעלה לירושלים. הסכים על ספרים בשנים תץ-תקטו, חתם על פסקי דין. תשובה ממנו ב\"אורח לצדיק\" להרב רודריגיס."},{"i":21872,"n":"יאפיל, מימון מאלגיר","k":"בעל פי צדיק","dt":"תפז","b":"רב, מקובל ור\"מ באלגיר-תן. חיבר גם \"נוה צדיקים\", ושיטות ופירושים שרובם אבדו. נזכר בשו\"ת מהר\"י עאייש, תשובה ממנו ב\"פרי צדיק\" ליוורנו תקיט. בנו - ר אברהם."},{"i":21873,"n":"יאפיל, משה","b":"רב-שנת ת\"ק"},{"i":21874,"n":"יאפין, שאול","dt":"תשג","b":"רב ברעדזיצא"},{"i":21875,"n":"יאפמאן, אליעזר חיים משידלובצה","b":"פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח."},{"i":21876,"n":"יאפעי, שמריה מתימן","f":"חלפון","k":"בעל אבקת רוכל","b":"מחמכי אנס-תימן סמוך לרצאבה ומעבר. חיבר \"אבקת רוכל\" - לקוטים לתורה בדרך הפרד\"ס - ולא ר סעדיה עזאני כפי שסברו תחילה. נזכר אצל חכמי דורו ובהם ר דוד בן שלום ג'מאל, ר סעדיה מנצורה. וחיבור אחר באות השם הוא מר סעדיה עזאני."},{"i":21877,"n":"יאפפא, יוסף מניו יורק","k":"בעל דיא לעבענס בילד","bt":"1853","bp":"מאהליב","b":"למד בגרמניה, עבר לאודסה. פרסם מאמרים ב\"אדעסקי\", \"ויעסטניק\", \"אדעסקי ליסטאק\", ועוד. עבר ללונדון ועבר בעתון \"ארבייטער פריינד\". היגר לניו יורק-1889 והיה עורך העתון \"ווארהייט\", \"פאלקס צייטונג\", ועוד. חיבר מאמרים, וסיפורים ובהם \"דיא לעבענס בילד\", \"דער גראף פון פאריז\", ועוד."},{"i":21878,"n":"יאפפע, יהודה ליב מטאמבוב","b":"תלמיד ביהמ\"ד לרבנים בוילנא, רב מטעם בליגאנסק סלאויאנסערבסק-תרלז, איוונובקה-פלך יקטרינסלב, טאמבוב-בסרביה, חברו ר יחיאל מרוגנשטרן מבאלגראד הקדיש לו את ספרו \"אילת השחר\". קיבל אישור מהממשלה ליסד בתי כנסת וקהלות בפלך בראנסק אראלער, קורסק, טאמבוב. קאזלוב באריסובלעבסק, קריסנוב-פלך טאמבוב"},{"i":21879,"n":"יאקא, יעקב מאיר הכהן","f":"אברהם","k":"בעל תרומות יעקב","bt":"תרכח","b":"רב בוונשזנסק(=ואזנאשענסק)-תרנח, מאלט(=מאליאט, מאלאט)-פלך וילנא-תרסא. נסמך מאת: הנצי\"ב, ר יצחק אלחנן מקובנא, ר ירוחם יהודה - הגדול ממינסק. חיבר גם \"כרם יעקב\" (חלק שני מספרו-\"תרומת יעקב\")."},{"i":21880,"n":"יאקובי, אברהם מארה\"ב","b":"רופא בגרמניה, היגר לארה\"ב. חיבר ספרים ברפואה."},{"i":21881,"n":"יאקובס, שמואל מקינגסטון-ג'מיקה","bp":"קינגסטון-ג'מאיקה","dt":"תרנג","dp":"ניו יורק","b":"רב בריצמונד-וירג'יניה - תריד, צ'רלסטון, ניו אורליאנס, רב קהילת \"שארית ישראל\" בניו יורק-תרלד, \"בני ישורון\"-תרלו."},{"i":21882,"n":"יאקובער, אליעזר מקראקא","b":"תלמיד ישיבת \"כתר תורה\". פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":21883,"n":"יאשיה הבבלי","b":"מגדולי הראשונים-שנת י'"},{"i":21884,"n":"יאשיה ן, שמואל הכהן מפאס","b":"מחכמי פאס-ד'תקסח, עבר לבגאנא-ספרד. נזכר אצל הראב\"ד בעל הקבלה."},{"i":21885,"n":"יאשיהו הקראי מוילנא","f":"יהודה","b":"שאלות ממנו לר יוסף שלמה רופא מקנדיא (יחד עם חבריו ר משה מיץ ור זרח בן יצחק נתן) - מובא ב\"ספר אלים\"."},{"i":21886,"n":"יאשלביץ, משה","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":21887,"n":"יבגי, אברהם","b":"חכם שלם-תקכ\"ב"},{"i":21888,"n":"יבגי, אברהם ממרוקו","f":"יעקב","b":"מחכמי מרוקו-שנות הת'."},{"i":21889,"n":"יבגי, אהרן","f":"יוסף","b":"מקובל, מחכמי מרוקו"},{"i":21890,"n":"יבגי, דוד מאלגיר","dt":"תרצג","b":"מחכמי טבריה, בשליחות בצפון אפריקה, והתישב כרב בג'יריוויל(=אל באייד)-אלגיר-תרן."},{"i":21891,"n":"יבגי, יעקב מפאס","b":"מחכמי פאס-תקיז."},{"i":21892,"n":"יבגי, ראובן ממרוקו","b":"מחכמי מרוקו הקדומים."},{"i":21893,"n":"יבזרוב, יהודה צבי","b":"דרשן לחיבת ציון רב בחסלוביץ"},{"i":21894,"n":"יבלונסקי, יהודה מאליטא","bt":"תרמב","dt":"תשא - אב","b":"רבה האחרון של אליטא על מקום ר אהרן מילבסקי. נספה בשואה."},{"i":21895,"n":"יבלונסקי, ישראל","f":"ניסן","b":"תשובה ממנו ב\"המאסף\" סט לואיס תרפח."},{"i":21896,"n":"יבלונסקי, ניסן מסלובודקה ושיקג","k":"בעל ניצני ניסן","bt":"תרלז","dt":"תרפח - כו שבט","b":"מרביץ תורה,מו\"צ ור\"מ בסלובודקה, שיקאגו-תרפב"},{"i":21897,"n":"יבלוקובסקי, ישראל","bt":"1893","bp":"מאריאמפול","dt":"1963","dp":"תל אביב","b":"עלה לארץ-1912. מורה בגימנסיה העברית בקובנא. חזר לארץ והיה מורה בגימנסיה הרצליה. הו\"ל \"ההיכל ששקע\" על הגימנסיה העברית בקובנא - תל אביב 1962."},{"i":21898,"n":"יבנה, יהודה לוי מירושלים","b":"מחכמי ירושלים, חתם על תקנה לשחרור תלמידי חכמים ממס בשנת שיז."},{"i":21899,"n":"יבנין, אברהם יונה מגרודנא","f":"יהושע או ישעיה","k":"בעל נימוקי מהרא\"י","bt":"תקצג","bp":"גרודנא","dt":"תרח - יא סיון","dp":"הורדנא","b":"מחכמי גרודנא. חתן ר בצלאל גינצבורג מגרודנא. חיבר גם חדושים על ספר המצוות לרמב\"ם. בניו ר נתן נטע בעל נטעי אור, ר שמואל בעל דברי חפץ, ר אריה ליב מביאליסטוק."},{"i":21900,"n":"יבנין, אריה ליב מביאליסטוק","f":"אברהם יונה מגרודנא","b":"מחכמי ביאליסטוק. מתורתו בספר אחיו ר נתן נטע - \"נטעי אור\"."},{"i":21901,"n":"יבנין, ישעיה מפאריטש","b":"רב בפאריטש. בנו - ר אברהם יונה בעל נמוקי מהרא\"י."},{"i":21902,"n":"יבנין, נתן נטע מהורדנא","f":"אברהם יונה מגרודנא","k":"בעל נטעי אור","b":"חיבר גם \"נר תמיד\", \"בנין ירושלים\", ועוד."},{"i":21903,"n":"יבנין, שמואל מוילנא","f":"אברהם יונה מגרודנא","k":"בעל דברי חפץ","b":"חיבר גם \"נחלת עולמים\" - מצבות גדולי ישראל בוארשא."},{"i":21904,"n":"יברכיהו, זכרי הלוי משלוניקי","dt":"תקעה","dp":"שלוניקי","b":"אב\"ד בשלוניקי."},{"i":21905,"n":"יגיד, משה מבוברקא","f":"חיים יהודה","k":"בעל מחצית השקל","bt":"תר","dt":"תרעה","dp":"ירושלים","b":"גביר מחכמי בוברקא. עלה לירושלים. חיבר \"מחצית השקל - צרור המור\" למברג תרלג."},{"i":21906,"n":"יגיכס, יעקב","f":"יוסף","bt":"1778","dp":"1848","b":"ביתו שימש בית ועד למשכילי וילנא ולסופריה. זקנו של ליאון יגיכס גרזובסקי."},{"i":21907,"n":"יגיכס-גרזובסקי, ליאון (טישקו)","bt":"1870","bp":"וילנא","dt":"1919","dp":"ברלין","b":"הצטרף למחתרת המהפכנית ברוסיה. חבר ועדת השלושה שריכזה עת פעילות המחתרת בוילנא. נשא לאישה את רוזה לוכסנבורג. הו\"ל ספרות מרכסיסטית אך אנגלס אסר עליו להפיצם ונאלץ להשמידם. נורה למות בבית סוהר בברלין."},{"i":21908,"n":"יגל, אברהם מרימיני-איטליה","f":"יצחק","dt":"רסח","dp":"בולוניה-איטליה","b":"מחכמי איטליה-רמא. חיבר פיוטים לפסח, שבועות, וקינה לתשעה באב."},{"i":21909,"n":"יגל, גמליאל מאיטליה","f":"חנניה","k":"ר' גמליאל ממונסיליצי","b":"מחכמי איטליה, רב ור\"מ בפארמה מתלמידי ר' מנחם עזריה מפאנו, חיבר \"שפתי רננות\" על פרק שירה"},{"i":21910,"n":"יגל, חנניה מאיטליה","k":"חנניה יגל ממונסיליצי","b":"מקובל,מגדולי חכמי איטליה,רב בפירארה-ת\"י,חיבר \"מספרים \"תהלות ה'\""},{"i":21911,"n":"יגל, יהושע","b":"מיסד הישיבה התיכונית בפרדס חנה. עורך \"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א, \"תורת ירושלים\"-\"תפארת ירושלים\" - ירושלים תרצו."},{"i":21912,"n":"יגל, פרץ מארה\"ב","f":"שבתי מסלונים","bp":"פיעסק-ליד סלונים","b":"תלמיד ישיבות סלובודקא, מיר, ראדין, מאטלש. נסמך מאת: ר אברהם צבי קאמאי ממיר, ר אליעזר יהודה פינקל ממיר, ר מאיר קרליץ מלכוביץ. חתן ר אליהו פרלמן מהאראדזיי(=גאראדיי)-פלך מינסק-בן הגדול ממינסק (נספתה בשואה עם בנו), ובזיוו\"ש חתן ר משה אליעזר רוטנברג הי\"ד מראוונא. רב בהרארדזיי-תרצב על מקום חותנו, ור\"מ בישיבת סלונים לצד אביו. ניצל מהשואה והגיע עם ישיבת סלונים לוילנא, יפן, שנחאי-סין, קנדה וכיהן כרב בקהלת \"עדת ישראל\" במונטריאול, ר\"מ בישיבת רבי יצחק אלחנן בניו יורק-תשה. חבר אגודת הרבנים באמריקה."},{"i":21913,"n":"יגל, שבתי מסלונים ורמת גן","r":"אדמו\"ר מפיטסבורג","bt":"תרלה","dt":"תשיח - י טבת","b":"תלמיד קיבוץ איישישוק, ישיבת וולוזין. מגדולי מרביצי תורה, ר\"מ בישיבת סלונים-תרסו, ניצל מהשואה דרך וילנא, עלה לארץ התישב ברמת גן והקים שם ישיבה. פרסם מאמרים ב\"השער\" - בני ברק תשח. חתנו - ר צבי מרקוביץ מסלונים."},{"i":21914,"n":"יגל-גליקו, אברהם מאיטליה","f":"חנניה","k":"בעל בית יער לבנון","b":"מחכמי מונסליצו(=מונציליצי)-איטליה-שן ורב בכמה מקומות באיטליה, פילוסוף, נפל בשבי, חיבר גם \"מושיע חוסים\", ועוד. (היו שחשבו שהוא המומר קאמילא יגל שהיה צנזור מטעם האפיפיור - אבל המומר היה אחד ממשפחתו, ור אברהם המשיך לחבר ספרים גם אחרי שפ - שאז היה המומר כבר צנזור)."},{"i":21915,"n":"ידיד יוסף מרדכי","bt":"1866","dt":"ה'תרצ 1930","bk":[["ימי יוסף",""],["ימי יוסף בתרא",""],["שארית יוסף",""],["תורת חכם",""]]},{"i":21916,"n":"ידיד, אליעזר רחמים הלוי","f":"יום טוב","k":"בעל מנחת אליעזר","bt":"תרמו","bp":"חלב","dt":"תרצד - כד אדר","dp":"ירושלים","b":"מקובל, עלה בילדותו לירושלים והיה מחכמיה, אחר תרפט עבר לחברון. חיבר \"מנחת אליעזר ואריה שאג\" ירושלים תרעה."},{"i":21917,"n":"ידיד, יום טוב הלוי","k":"בעל שמחת יום טוב","bt":"תרן","bp":"ארם צובא","dt":"תרפג - כח תמוז","dp":"ארם צובא","b":"עלה לארץ ישראל ולמד בישיבת \"בית אל\", בשנת תרעז חזר לארם צובא ולימד שם קבלה. חיבר \"שמחת יום טוב\" ירושלים תרפו."},{"i":21918,"n":"ידיד, יוסף הלוי מחלב וירושלים","f":"מרדכי הלוי","k":"בעל ברכת יוסף","bt":"תרכה-ז","bp":"ארם צובא","dt":"תרץ - ח אדר","dp":"ירושלים","b":"מחכמי אר\"ץ, עלה לצפת-תרן וכיהן שם בבית הדין של ר חיים סתהון בעל \"ארץ חיים\" ועמו - ר ישמעאל בן פנחס הכהן, בשנת תרסה ראב\"ד העדה הבוכרית ועדת ארם צובא בירושלים. מתלמידיו ר רפאל מנשה ענתבי. חיבר גם \"תורת חכם\".","bk":[["שארית יוסף [שו\"ת]",""],["ברכת יוסף – הל' ברכות",""],["ויחי יוסף – הל' גיטין וחליצה",""],["ימי יוסף – שו\"ת",""],["שארית יוסף – שו\"ת ודרושים",""],["תורת חכם",""],["ימי יוסף",""]]},{"i":21919,"n":"ידיד, יצחק הלוי ממצרים","f":"יום טוב","dt":"תרעז - י אלול","dp":"מצרים","b":"שו\"ב בפורט סעיד-מצרים. חיבר ספר בדיני שחיטה."},{"i":21920,"n":"ידיד, משה מביירות","b":"רב בביירות-לבנון בתחילת המאה ה-20."},{"i":21921,"n":"ידידיה"},{"i":21922,"n":"ידידיה בעל התוספות","f":"ישראל מבמברג","dt":"סה","b":"מגדולי הראשונים ובעלי התוספות, פוסק ומרביץ תורה בנירנברג, שפיירא, קולוניא. נזכר ברשב\"א."},{"i":21923,"n":"ידידיה האלכסנדרוני","k":"בעל חיי משה,פילון","b":"חיבר \"חיי משה\" - פרג תקצז."},{"i":21924,"n":"ידידיה הדיין מספרד","b":"מחכמי ספרד בדורו של הר\"ן"},{"i":21925,"n":"ידידיה הכהן מירושלים","f":"אריה יהודה ליב","dp":"ירושלים","b":"דיין בירושלים-תפד עם ר נסים חיים משה מזרחי ועם ר ישעיה אזולאי, עלה בשנת תמו עם אביו, היה נכדו של ר אפרים בן אהרן בעל \"שער אפרים\". תלמידו וחתנו של ר אברהם יצחקי והדפיס את ספרו של חותנו \"זרע אברהם\" עם הקדמה משלו וגם תשובה ממנו - קושטא תצב."},{"i":21926,"n":"ידידיה הכהן מליבאוי","f":"ישכר","b":"יסד את החברא קדישא בליבאוי-תקסג."},{"i":21927,"n":"ידידיה הכהן ממכנאס","b":"מחכמי מכנאס-תקצט."},{"i":21928,"n":"ידידיה הלוי מסיינה","f":"רפאל שלמה","k":"בעל סדר זמירות ולימו","b":"רב בסיינה, חיבר סדר זמירות ולימוד לחנוכת בית הכנסת בסיינה-ליוורנו תקמו, יחד עם ר יצחק חיים די מדינה."},{"i":21929,"n":"ידידיה הספרדי מליפאנטו","b":"רב בליפאנטו(=אפגטו)-יוון על מקום ר אברהם שמסולי - שנות הר'-ש'."},{"i":21930,"n":"ידידיה הרופא מתורכיה","b":"מחכמי טורקיה בזמן הרא\"ם"},{"i":21931,"n":"ידידיה ישראל מירושלים","dt":"תקצו - בערך","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":21932,"n":"ידידיה מרימיני","b":"רב ברימיני. חיבר שו\"ת בכת\"י - מוזכר ב\"באר עשק\"."},{"i":21933,"n":"ידידיה נסים מפיסא","k":"בעל ענה כסיל","b":"מחכמי פיסא. חיבר ספר ענה כסיל על ויכוח הקבלה לשד\"ל - ליוורנו תרטו."},{"i":21934,"n":"ידיץ, יעקב יוסף","f":"חיים","k":"בעל ספר הפתגמים"},{"i":21935,"n":"ידלר, בן ציון מירושלים","f":"יצחק זאב ידלר","k":"בעל בטוב ירושלים","bt":"תרלב","dt":"תשכב","b":"דרשן,מוכיח,רב פעלים לחזוק היהדות בירושלים"},{"i":21936,"n":"ידעיה ן, ברוך מאיטליה","f":"משה","k":"בעל קהלת יעקב","b":"מחכמי המזרח בזמן המהרי\"ט, רב בונציה, חיבר \"קהילת יעקב\"-שנט."},{"i":21937,"n":"יהודאי גאון סורא","f":"מר נחמן","b":"ראש ישיבת סורא-ד'תקי\"ז-תקכ\"א,פוסק,היה תחילה מחכמי פומבדיתא,ראש הגולה העבירו לסורא בגלל שלא נמצא גדול כמוהו,והמסורת בסורא היתה לא להעמיד בראש חכם מבחוץ,חיבר \"הלכות פסוקות\" ונלחם בקראות"},{"i":21938,"n":"יהודה"},{"i":21939,"n":"יהודה","f":"זאב","k":"בעל מנחת יהודה"},{"i":21940,"n":"יהודה","f":"משה בן דניאל מרומי","k":"בעל ספר השערים","b":"חיבר ספר השערים ובסופו סודות לר יוסף ן חיים - נכתב בשנת שכד ע\"י ר שלמה בן שמעון שואב. (באוצר ר חיים מיכל)."},{"i":21941,"n":"יהודה","f":"מר פרחון","b":"מתלמידי הרמב\"ם"},{"i":21942,"n":"יהודה","f":"שלמה פנחס","bt":"1727","bp":"כפר לעהרבורג-ליד אנשבאך","dt":"1793","b":"צייר החצר של המלך פרידריך. צייר מגילות אסתר."},{"i":21943,"n":"יהודה","f":"מור\"ח","k":"בעל ממתקי יהודה","b":"מצאצאי הנודע ביהודה ור\"י הלוי הורביץ מהמבורג. היה בירושלים תרכג-תרלה. חיבר ספר תהלים עם פירוש \"דגלי הודיה והמצוה\", \"ממתקי יהודה\"-תרכו."},{"i":21944,"n":"יהודה (יודא) מהורדנא","b":"רב בהורדנא-שנ על מקום ר מרדכי יפה בעל הלבוש ור יהושע בעל 'מגיני שלמה'. נזכר ב'גבורת אנשים'."},{"i":21945,"n":"יהודה (יודל) מיאס","f":"אהרן","dt":"תקצד","b":"נזכר על ידי ר ישראל מרוזין באחד ממכתביו."},{"i":21946,"n":"יהודה (יודל) מפמורן","f":"זאב","b":"רב בפמורן-תרך."},{"i":21947,"n":"יהודה - משפחה","b":"משפחה בבגדד וירושלים."},{"i":21948,"n":"יהודה אברהם הלוי מלבוב","f":"יצחק","b":"ר\"מ וראב\"ד בלבוב, חתם-תמא על תקנת ועד ארבע ארצות, יחד עם ר יעקב בא\"א מהר\"ד שליט מקראקא, ר יצחק כהנא מבריסק ופרמישלא, ר קלונימוס בן משה הקדוש מפוזנא, ר אליעזר מפרמישלא, ר מרדכי כהנא מוילנא."},{"i":21949,"n":"יהודה אברהם מגיידינג","f":"ר\"י מפרצווא","b":"רב בגיידינג-תץ. הסכים על באר טוב לר ישכר דב מפרשבורג."},{"i":21950,"n":"יהודה אהרן מקמרוב","f":"אייזיק מזלקווא","b":"רב בקמרוב-תק\"ל"},{"i":21951,"n":"יהודה איש מודנא","dt":"רע","b":"עק\"ה,מרביץ תורה בלומברדיה"},{"i":21952,"n":"יהודה אליסף מיאנינה","b":"מחכמי יאנינה-תעד."},{"i":21953,"n":"יהודה אריה","k":"בעל אמרי ברוך","b":"חיבר גם \"שערי אריה\". פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":21954,"n":"יהודה אריה הכהן מירושלים","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":21955,"n":"יהודה אריה הלוי מסטריזוב","k":"בעל דרישת אריה","b":"רב בסטריזוב-תקס\"ד"},{"i":21956,"n":"יהודה אריה ליב כץ מטיבלר-דראץ","b":"תלמיד החת\"ס, ור אלעזר פלקלס מפרג. רב בטיבאלד-דאראץ-תקץ. בניו ר יעקב יוסף אב\"ד אנאד, ור אשר."},{"i":21957,"n":"יהודה אריה ליב מבויסק","f":"יהושע האשקי","k":"בעל לב אריה","b":"נכד(-אבי אמו) ר מנשה כץ בילנקש מאוסטרהא. רב בבויסק. חיבר לב אריה - וילמשדורף תלד."},{"i":21958,"n":"יהודה אריה ליב מלבוב","f":"יחיאל מיכל מפרמישלא","dt":"תקע - כה תשרי","dp":"לבוב","b":"מ\"מ ומו\"צ בהורדנקא (לדעת בובר זו טעות ובלבול עם חכם אחר - ר יהודה ליב בן ישראל), לבוב. נזכר בהקדמה ל\"תועפות ראם\". הסכים בשו\"ת גאוני בתראי."},{"i":21959,"n":"יהודה אריה ליב מקראקא","f":"יהושע","b":"גביר מחכמי קראקא-תן."},{"i":21960,"n":"יהודה אריה ליב מקרזמיר","b":"רב בקרזמיר,קאליש-ת\"נ"},{"i":21961,"n":"יהודה אריה ליב משפולא","f":"ברוך מבוהמיה","k":"הסבא משפולא","bt":"תפה","dt":"תקעב - ו תשרי","b":"תלמיד ר פנחס מקוריץ, שהביאו לבעשט. הפיץ קופת צדקה בקהלות רבות - והמשיכה גם אחר פטירתו. היה במחלוקת עם ר נחמן מברסלב. מתורתו ב\"איש הפלא\". בניו ר יעקב, ר פסח, ור אברהם."},{"i":21962,"n":"יהודה אריה ליב שרה'ס","f":"יוסף ושרה","k":"ליב שרה'ס","r":"אב\"ד סטרופקוב","bt":"תפ-ץ","dt":"תקנא - ד אד\"ב","dp":"ילטשיקוב","b":"תלמיד הבעשט, והמגיד ממזריטש. עסק בפדיון שבויים. קירב את ר יצחק איזיק מקאליב לחסידות. מתורתו ואודותיו ב\"גבורת ארי\"."},{"i":21963,"n":"יהודה אריה מבאהפאלי","f":"מנחם נחום מבאהפאלי","b":"חתן ר ישראל-חתנו של ר משה צבי מסאווראן."},{"i":21964,"n":"יהודה אריה ממודנא","f":"יצחק","k":"בעל בית לחם יהודה","bt":"שלא","bp":"ונציה","dt":"תח - כז אדר","dp":"ונציה","b":"ספריו הנוספים של רי\"א מודינא [מודנה/ריא\"ם]: בחינת הקבלה; בית לחם יהודה; בית יהודה; גלות יהודה; לב האריה; מגן וחרב; מגן וצינה; מדבר יהודה; סוד ישרים; סור מרע; פי אריה; צרי לנפש; שולחן ערוך. חיבר פיוטים חלקם כונסו בספר תפילות ישרים. חיבר את הפיוט הנאמר בתפילת יום כיפור קטן \"יום זה יהי משקל כל חטאתי\". בספר \"ארי נוהם\" רי\"א מודינא מתנגד לחכמת הקבלה, וטוען שהזוהר אינו חיבור של רשב\"י – בשל כך רבנים שונים יצאו כנגדו [המשכילים השתמשו בספר זה כסיוע לדעותיהם הכוזבות]. יש להבדיל בין \"מגן וצינה\" שחיבר רי\"א מודינא, לבין \"מגן וצינה\" שחיבר רי\"א חבר - כהתנגדות ל\"ארי נוהם\" של רי\"א מודינא.","bk":[["ארי נוהם",""],["זקני יהודה [שו\"ת]",""]]},{"i":21965,"n":"יהודה אריה מפאקריי","f":"ראובן","b":"דיין בפאקריי, חתם-תרטז עם ר יצחק אליהו בן זאב, ור אריה זאב בן שלום."},{"i":21966,"n":"יהודה אריה מקרפנטרץ","f":"צבי הירש","k":"בעל אהלי יהודה","bp":"ז'אמוטש-ליטא","b":"רב ומדקדק בקרפנטרץ-תן. חיבר חיבר \"גזע יהודה\" - קיצור קונקורדנציה, \"יסוד לשון קדש\" - תפא, \"פני אריה\", \"חלק יהודה\"."},{"i":21967,"n":"יהודה בן יעקב אבינו ע\"ה","dt":"טו סיון"},{"i":21968,"n":"יהודה בן שמואל הלוי","bt":"1075","dt":"ד'תתקא 1141","bk":[["אדון חסדך",""],["בתולת בת יהודה",""],["דיואן אביר המשוררים יהודה בן שמואל הלוי",""],["הכוזרי",""],["כוזרי",""],["כל שירי רבי יהודה הלוי",""],["מי כמכה",""],["ספר הכוזרי",""],["רבי יהודה הלוי",""],["שירי יהודה הלוי",""]],"e":"ד'תתל\"א~-ד'תתק\"ב~"},{"i":21969,"n":"יהודה בעל התוספות","b":"מחכמי אשכנז-ה'. חיבר תוספות לב\"ק וב\"מ - והובאו ב\"שיטה מקובצת\", ופיוטים ובהם \"אנשי חסד נאספים\"."},{"i":21970,"n":"יהודה ברוך","f":"בצלאל","k":"בעל צידה ברוך","b":"ממשפחת המהרי\"ל. חיבר \"צידה בדרך\" פרג תקמו."},{"i":21971,"n":"יהודה ברוך משלוניקי - א","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ."},{"i":21972,"n":"יהודה ברוך משלוניקי - ב","dt":"תקכב","dp":"שלוניקי","b":"גביר מחכמי שלוניקי, עוזרו של הוזיר הגדול-תקח ופעל לביטול גזירת הגירוש על יהודי וינה, פעל גם לטובת יהודי ירושלים."},{"i":21973,"n":"יהודה ברצלוני","f":"ברזילי ברצלוני","b":"חיבר פירוש לתלמוד ופירוש ספר יצירה, וספר העתים ופירוש לשטרות (ונמצא בספריית ר חיים מיכל)."},{"i":21974,"n":"יהודה גבור הקראי","f":"אליהו","k":"בעל מנחת יהודה","b":"מחכמי הקראים-רסג. חיבר דיני שחיטה ומועדים, \"מועד קטן\" בחכמת הקבלה."},{"i":21975,"n":"יהודה גדליה משלוניקי","f":"משה","b":"מחכמי שלוניקי-שד(?), הו\"ל \"מדרש רבות\" שלוניקי שנד."},{"i":21976,"n":"יהודה גרשון מוילנא","f":"יעקב קופל","k":"בעל עבודת הגרשוני","b":"מצאצאי ר צבי הירש משוטלנד, ור יונה מלומבלא. מגיד מישרים ודיין בוילנא, חתם-תקמא על פסק דין. חיבר בכת\"י עבודת הגרשוני - עם הסכמות האב\"ד ר שמואל מוילנא, ור חיים מדרויע. נכדו - ר יונה גרשטין מוילנא."},{"i":21977,"n":"יהודה גרשון מראזלי","b":"רב בראזלי"},{"i":21978,"n":"יהודה דב בר מטלומטש","b":"דיין בטלומטש-תרכג. תלמיד ר צבי הירש תאומים מחורוסטקוב."},{"i":21979,"n":"יהודה דניאל משלוניקי","b":"גביר בשלוניקי. סייע עם שותפו - שמואל נאברו, בהדפסת \"לחם שלמה\" לר משה בולה-תקנה."},{"i":21980,"n":"יהודה האבל","f":"אליהו הדמי","k":"בעל אשכול הכופר","b":"מחכמי הקראים-שנות ה-ד'תתק. חיבר ספר מצוות בשם \"אשכול הכופר\"."},{"i":21981,"n":"יהודה הזקן","f":"שניאור","b":"מחכמי אשכנז-ראשית שנות ה-ה'. נזכר בסמ\"ק, וב\"ארחות חיים\" לר אהרן הכהן. חיבר קינה \"ציון הלא תשאלי לשלום ידידיך\"."},{"i":21982,"n":"יהודה החסיד","k":"בעל תקון קריאת שמע,שעלה לירושלים","bt":"שצח","bp":"שידלובצי (ליד גרודנא)","dt":"תסא - חשון","dp":"ירושלים","b":"עלה בראש חבורה גדולה לירושלים-תסא, רכש את החצר הסמוכה לבית כנסת הרמבן (לימים \"החורבה\") ומיד נפטר. חיבר \"תקון קריאת שמע\" חמ\"ד תס. אולי בנו - ר ישעיה סגל מירושלים."},{"i":21983,"n":"יהודה החסיד מדובנא","k":"ר' יהודה החסיד","dt":"תט","b":"נהרג על קדוש השם, מקובל, רב בדובנא על מקום ר מאיר כץ בעל גבורת אנשים, ור אברהם הלפרין על מקומו אחריו. נזכר בסליחות לכ' בסיון ('אמנים שלומי ישראל... יהודה ויצחק משה חסידים')."},{"i":21984,"n":"יהודה הכהן","f":"יעקב יוסף הכהן"},{"i":21985,"n":"יהודה הכהן","k":"מפפד\"מ","b":"מגדולי חכמי פפד\"מ-שס\"ה"},{"i":21986,"n":"יהודה הכהן הפייטן","b":"פייטן-שנות ה-ד'תת. מפיוטיו במחזור רומניה."},{"i":21987,"n":"יהודה הכהן מאלגיר","bt":"תך","dt":"תק - בערך","b":"מחכמי אלגיר, מדינאי ומקורב לשלטון באלגיר, תונס וטריפולי, וסייע להם ביחסים עם ארצות השפלה."},{"i":21988,"n":"יהודה הכהן מאלגיר","dt":"תקצג - בערך","b":"רב ומשורר בתלמסאן. חיבר קובץ פיוטים - בכת\"י, פיוטים ממנו ב\"שיר ידידות\" תלמסאן תרצב."},{"i":21989,"n":"יהודה הכהן מאשכנז","f":"משה","b":"פייטן-שנות ה-ה'. חיבר קינה \"ואתאונן ואקונן במרה\" על פרעות פרנקפורט-ה'א. תשובות ממנו ב\"אור זרוע קטן\"."},{"i":21990,"n":"יהודה הכהן מבלגרד","f":"חיים","b":"דיין בבלגרד-תקמח, יחד עם ר חיים שלמה עמאר, ור משה חזן."},{"i":21991,"n":"יהודה הכהן מדמשק וארץ ישראל","b":"מחכמי דמשק בזמן הרלב\"ח,עלה לא\"י"},{"i":21992,"n":"יהודה הכהן מטוליטולא","k":"בעל מדרש החכמה","b":"רב בטולידו(=טוליטולא), עבר לטוסקאנה ורומנייא. היה בקשרי אגרות עם המלך פרדריקו. חיבר \"מדרש החכמה\", ופירוש לתנ\"ך (היה אצל די רוסי)."},{"i":21993,"n":"יהודה הכהן מטוקאת","b":"מחכמי אנגורה, רב בטוקאת אצל ר יוסף בארקר."},{"i":21994,"n":"יהודה הכהן מטריפולי-לבנון","b":"גביר מחכמי טריפולי-לבנון. נהרג עק\"ה בידי המושל התורכי ונספד בידי ר ישראל נג'ארה."},{"i":21995,"n":"יהודה הכהן מירושלים","f":"אברהם שלמה","k":"בעל אהלי יהודה","dt":"תרי","dp":"תונס","b":"מקובל, מחכמי \"בית א-ל\" בירושלים-תרא, חיבר \"אהלי יהודה\" שלוניקי תקעא, \"אשמורת הבקר\". בשנת תרד חתם על הסכם שלום בקהלה, בשנת תרה חתם על כתב שליחות של ר מיכאל בדהב עבור ישיבת \"בית אל\". מחותנו היה ר אברהם חיים גגין. חתם על תקנות והסכמות שונות. בשנת תרז בשליחות חברון? לצפון אפריקה ושם נפטר. מתלמידיו בקבלה - ר נחום משאדיק ואחיו."},{"i":21996,"n":"יהודה הכהן מירושלים","f":"יוסף?","b":"מחכמי ירושלים בשנת רסט, פסקים ממנו בספר \"פסקי דינים לרבני ירושלים הקדמונים\". נזכר בשו\"ת הרלב\"ח. לדעת בניהו הוא זהה עם ר יהודה בן יוסף הכהן שחתם בצפת בשנת רסד."},{"i":21997,"n":"יהודה הכהן מירושלים","f":"חיים","b":"מחכמי ירושלים, בשנת תקסד בשליחות ברודוס ובשנת תקסח באדרינופול."},{"i":21998,"n":"יהודה הכהן מירושלים","b":"מחכמי ירושלים, תלמיד ה\"פרי חדש\", חיבר חידושים על ה\"לחם משנה\" לרמב\"ם, ונזכר ב\"מרכבת המשנה\" לר\"א אלפנדרי, ב\"גנת ורדים\", ובספר רבו \"מים חיים\". החיד\"א כתב שחיבר ספרים רבים בכת\"י. חתם על כתב שליחות-תסד ר אברהם רוויגו ור חיים חזן."},{"i":21999,"n":"יהודה הכהן מליסא וברלין","f":"יעקב מליסא","k":"בעל מראה כהן","dt":"תקנו","b":"ראש ישיבה בברלין, דיין בליסא."},{"i":22000,"n":"יהודה הכהן ממוצאט","dt":"תקפג - יב אלול","b":"רב במוצאט"},{"i":22001,"n":"יהודה הכהן ממכנאס","dp":"ירושלים","b":"מחכמי מכנאס בזמן ר משה בירדוגו. עלה לירושלים. סגי נהור."},{"i":22002,"n":"יהודה הכהן ממעליץ","b":"רב במלעיץ."},{"i":22003,"n":"יהודה הכהן ממצרים","b":"מדייני ורבני מצרים-ד'תתקן בזמן הרמב\"ם, דיין בבולביס. חתום על החרם נגד פרצות בטהרת המשפחה-ד'תתקמ\"ז"},{"i":22004,"n":"יהודה הכהן ממצרים","b":"מרבני מצרים-ת\"ה"},{"i":22005,"n":"יהודה הכהן מסלונים","f":"יצחק ממוציט","dt":"תקפג - יב אלול","dp":"וילנא","b":"רב בסלונים, נפטר בוילנא לצד גיסו(-בעל אחותו) ר עקיבא בן מרדכי."},{"i":22006,"n":"יהודה הכהן מסעליש","b":"רב בסעליש על מקום ר יאיר בן יחיאל הכהן ור חיים מאיר זאב הכהן על מקומו אחריו."},{"i":22007,"n":"יהודה הכהן מפאס","f":"יצחק","b":"רב בפאס-רצט, חתם על פס\"ד-שד עם ר אברהם ביטון, ר שמואל חאגיז, ור יצחק דון דון, ועם ר יצחק בן יוסף נהון."},{"i":22008,"n":"יהודה הכהן מפאס","k":"בעל ספר דרשות","b":"רב בפאס-שמט. חיבר ספר חדושים על התורה-בכת\"י, ספר דרשות לנפטרים ולמילה, ובסופו מפתח מאת ר משה בן עמרם אלקאיים לספר \"עקדת יצחק\". בסוף הספר - כתיבה מאת ר משה טולדנו בעל \"מלאכת הקדש\". חתנו - ר יעקב בן שמואל חגיז."},{"i":22009,"n":"יהודה הכהן מפאס","b":"מחכמי פאס-שנות ה-ד'תתק, אצלו למדו ר מימון ובניו הרמב\"ם ואחיו בהיותם בפאס. נהרג עק\"ה."},{"i":22010,"n":"יהודה הכהן מצפת","b":"מקובל בצפת-ש\"ס"},{"i":22011,"n":"יהודה הכהן מצרפת","b":"מגדולי חכמי צרפת,ד'תת\"פ,מובהק בהלכה"},{"i":22012,"n":"יהודה הכהן מקושטא","f":"מרדכי","b":"שר האוצר של הוזיר בזמן ש\"ץ, נתבקש להשפיע על הוזיר לשחרר את ש\"ץ ממאסרו. נתבקש ע\"י רבני קושטא לממן את המשלחת שנשלחה לחקור אודות נתן העזתי."},{"i":22013,"n":"יהודה הכהן משלוניקי","b":"מורשה קהלת שלוניקי לשליחת המס לקושטא-שנות ה-ת', עוזרו של אברהם אליעזר, נאלץ לברוח מהשלטונות."},{"i":22014,"n":"יהודה הלוי","k":"אבי המהרש\"א"},{"i":22015,"n":"יהודה הלוי"},{"i":22016,"n":"יהודה הלוי בערמן משלוניקי","f":"גרשון","dt":"שטו - יב אלול","dp":"שלוניקי","b":"מחכמי שלוניקי, אולי נכד ר יהודה מינץ."},{"i":22017,"n":"יהודה הלוי מויסוקי","b":"בן אחותו של המהרש\"א. רב בויסוקי. אחיו - ר\"י מיכל מירושלים בעל ש\"ש. בנו - ר שמואל הלוי מפוחוביץ."},{"i":22018,"n":"יהודה הלוי מורנקפורט","b":"הו\"ל ספרי קדמונים בונציה."},{"i":22019,"n":"יהודה הלוי מחיפה","f":"משה","dt":"תרפו - כז חשון","dp":"חיפה","b":"רב בחיפה-תרמז"},{"i":22020,"n":"יהודה הלוי מטיטואן-מרוקו","bt":"תק - לפני","b":"מו\"ץ בטיטואן-מרוקו עם ר יעקב מלכא ויסד שם ישיבה, היה גם באלגיר והיה במחלוקת עם ר יעקב ן נאים, ובגיבלרטר-תקמה ויסד שם ישיבה, היה גם בליוורנו. מכתב ממנו-תקף לר שמואל ן צור. חתם על פס\"ד-תקלא עם ר\"י מלכא, ר אפרים מונסונייגו, תשובות ממנו ב\"ויאמר יצחק\", \"ברית אבות\"."},{"i":22021,"n":"יהודה הלוי מירושלים","k":"יהודה הלוי מהיידלברג","b":"מגדולי חכמי אשכנז בירושלים-שכ\"ה"},{"i":22022,"n":"יהודה הלוי מירושלים","f":"אורי מהיידלברג","b":"מחכמי ירושלים שעלה מאשכנז, חבר בית הדין של ר זכריה זעבסיל, חתום על פסק דין משנת שכה."},{"i":22023,"n":"יהודה הלוי מליוורנו","k":"בעל הילולא רבא","b":"רב בליוורנו. חיבר \"הילולא רבא\" - נדפס בליוורנו ע\"י ר שלמה ועאנונו - שהוסיף בו מחדושיו."},{"i":22024,"n":"יהודה הלוי ממרוקו","f":"יוסף","b":"מחכמי מרוקו, חיבר ליקוטי ביאורים על רש\"י-שנא."},{"i":22025,"n":"יהודה הלוי ממרוקו - א","b":"מחכמי מרוקו הקדמונים."},{"i":22026,"n":"יהודה הלוי ממרוקו - ב","f":"יוסף","b":"משורר מחכמי מרוקו (אולי מסאלי), חתם על פס\"ד-תפו עם ר שמואל אזאווי, ר אהרן הצרפתי. נזכר אצל היעב\"ץ."},{"i":22027,"n":"יהודה הלוי מניישטטל","b":"רב בהאליטש,ראב\"ד בניישטטל"},{"i":22028,"n":"יהודה הלוי מספרד","f":"שמואל","k":"בעל הכוזרי","bt":"ד'תתס","bp":"טולדו","dt":"ד'תתק - בערך","dp":"ירושלים","b":"משורר, פילוסוף, למד בישיבת הרי\"ף בלוסנה. השתלם גם בשפות, רופא בטולדו, עבר לקורדובה, גרנדה, בערוב ימיו יצא לארץ ישראל,ולא ידוע אם הגיע, האגדה אומרת שנהרג בידי פרש ערבי בירושלים, חיבר את ספר \"כוזרי\" בערבית","bk":[["הכוזרי","מחשבה ומוסר - ראשונים"],["דיואן - שירה",""],["הכוזרי - אמונה",""],["ערבי פסחים – הגדה של פסח",""],["רבי יהודה הלוי - שירה",""],["ריה\"ל",""],["כוזרי",""]]},{"i":22029,"n":"יהודה הלוי מספרד","k":"בעל מנחת יהודה","b":"גדול בתורה ושירה,מחכמי קאשטיליה-ד'תתק\"פ"},{"i":22030,"n":"יהודה הלוי מסרייבו וירושלים","f":"מנחם","bt":"תקמג","bp":"סרייבו","dt":"תרלט - יז אב","dp":"יפו","b":"עלה עם אביו לירושלים, בשליחות בתורכיה ושהה שם 6 שנים, רבה הראשון של יפו-תקפה, וסייע שם לעולים, השפיע על הבארון די מנשה באלכסנדריה לסייע בהקמת תלמוד תורה ביפו."},{"i":22031,"n":"יהודה הלוי מעיר חדש","f":"משה בן שמואל מוערבא","k":"בעל וזאת ליהודה","dt":"תרלו","b":"תלמיד החת\"ס, הכתב סופר, ור מאיר סביטש משעכטיץ . חתן ר גבריאל שפיגלר. רב בעיר חדש. חיבר \"וזאת ליהודה\" ונדפס בסוף ספר בנו - ר משה שמעון הלוי מפרוינקירכן \"ישמח לב\""},{"i":22032,"n":"יהודה הלוי מפאס","f":"יוסף","b":"סופר בי\"ד בפאס עם ר יעקב מלכא בזמן היעב\"ץ. חתם על פס\"ד-תץ עם ר שלם אדרעי, ר בנימין ן שמחון."},{"i":22033,"n":"יהודה הלוי מקושטא","f":"יוסף","b":"מדפיס אצל ר יונה בן יעקב אשכנזי בקושטא-תע."},{"i":22034,"n":"יהודה הלוי מתונס","f":"נתן","k":"בעל מחנה לויה","b":"מרבני תונס,חיבר \"מחנה לויה\" על הלכות שמחות - ליוורנו תקעט."},{"i":22035,"n":"יהודה ה\"ן דוד ויוסף מפאס","b":"סופר שטרות מחכמי פאס, חתם על פס\"ד-תקלט עם ר משה אלבאז, ובשנת-תקנג עם ר שמואל אברהם ן זמרא."},{"i":22036,"n":"יהודה הנגיד ממצרים","f":"ישעיה","b":"רופא ונגיד במצרים-ד'תשע, על מקום ר שמואל בן פלטיאל, ור מבורך בן סעדיה על מקומו אחריו."},{"i":22037,"n":"יהודה הנשיא נגיד","f":"יאשיה הנשיא","k":"בעל מגדנים,וא\"י","b":"נגיד בארץ מצרים,וראש נשיא גלויות ישראל"},{"i":22038,"n":"יהודה הפייטן","f":"אברהם","b":"פייטן - שנות ה-ד'תתק. חיבר יוצרות."},{"i":22039,"n":"יהודה הפייטן","f":"בנימין","b":"פייטן-שנות ה-דתת."},{"i":22040,"n":"יהודה הפייטן","f":"מנחם","b":"פייטן באיטליה-שנות ה-ד'תת, מפיוטיו במחזור רומא - חותם \"יהודה ברבי מנחם חזק ואמץ בתורה ובמצות\"."},{"i":22041,"n":"יהודה הפייטן","f":"שלמה נתן","b":"פייטן, חיבר שיר על יג עיקרי האמונה."},{"i":22042,"n":"יהודה הפייטן","f":"שמואל","b":"פייטן-שנות ה-ד'תתק."},{"i":22043,"n":"יהודה הפייטן","f":"שמריה","b":"פייטן."},{"i":22044,"n":"יהודה זונדל מברוד","k":"רמר\"ז","dt":"תקסד - ל סיון","b":"מקובל,מגדולי חכמי ברוד"},{"i":22045,"n":"יהודה זונדל מסקאהל","b":"רב בסקאהל-תר\"כ"},{"i":22046,"n":"יהודה זונדל מקידאן","b":"רב בקידאן-תל ור הלל בעל \"בית הלל\" על מקומו אחריו. מראשוני המסכימים בזאמוט - הסכים על \"באר אברהם\"-תל (נדפס בפפד\"מ תמג)."},{"i":22047,"n":"יהודה זלקא מסטניסלב","f":"יחיאל מיכל","k":"בעל רביד הזהב","bt":"תק","dt":"תקעח - כה אדר","b":"רב בסטניסלב-תקל, לבוב. הדפיס \"רביד הזהב\" למברג תקסא."},{"i":22048,"n":"יהודה זעלקא","b":"רב במיץ-ש\"פ"},{"i":22049,"n":"יהודה חזקיה משלוניקי","b":"מחכמי שלוניקי-שנות התק'. הגיה \"הון רב\"-תקלו."},{"i":22050,"n":"יהודה יודא מלובלין","b":"מראשי קהילת לובלין. חתם על פסק דין-תקם בערך של ר שאול מרגליות אב\"ד לובלין."},{"i":22051,"n":"יהודה יודא סגל מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":22052,"n":"יהודה יודיל מטבריה","f":"יהושע זליג","dt":"תקסה - אחרי","b":"מתושבי טבריה-תקמח."},{"i":22053,"n":"יהודה יודל כ\"ץ מלנדסברג וברלין","f":"משה בן מאיר","dt":"תעה - ד תמוז","dp":"ברלין","b":"מחכמי ברלין. גיסו של ר יוסף בן משה בעל \"כתר יוסף\" - ברלין תס. מתורתו ב\"קול יהודה\" לר יהודה בן חנינא זליג. תשובה בענינו ב\"כנסת יחזקאל\" לר יחזקאל קצנלנבויגן מאה\"ו."},{"i":22054,"n":"יהודה יודל ליב מקאוולי ולבו","f":"משה ר הירשס מלובלין","k":"בעל קול יהודה - כת\"י","dt":"תנז?","b":"חתן - ר משה פנחס חריף (14713). מקובל, רב בלבוב-חוץ לעיר-תכח ועמו כיהן ר צבי הירש קלויזנר כרב תוך העיר, מינסק, רב בקאוולי-תמ. נזכר בהקדמת הט\"ז לפירושו לתורה. הסכים על \"לב אריה\", \"חלוקא דרבנן\"-תנה. בניו: ר משה זאב מרגליות, ר יוסף יאסקי ב\"ד דובנא בעל \"יסוד יוסף\", ר אריה ליב אב\"ד סלוצק, ר משה אב\"ד פוזנן (שמצאצאיו - בעל התניא). נינו רמא\"ז מרגליות בעל \"אגודת אזוב\" - מזכיר בספרו כי ראה שנדפס בשקלוב דף אחד מ\"קול יהודה\" לזקני וכו'. חתנו ר אהרן בן יעקב נכד ר שמואל שחור - שנשלח להדפיס את ספרו יד עם ספרו של בעל הט\"ז \"דברי דוד\" - ולא עלה בידו להדפיסו. (אולי הוא שהיה מלודמיר ונזכר אצל בובר) ולפי בובר - חתנו - ר אהרן בן נתן הכהן מלבוב. לפי אוצר הרבנים חתנו גם - ר יעקב יצחק לנדא דוקלא, ר אלכסנדר סנדר מסלוצק (2780). ראה גם יהודה ליב סגל מלבוב (שהיה באותו הזמן בלבוב ורבים מחליפים ביניהם)."},{"i":22055,"n":"יהודה יודל מהאלוסק","f":"מנחם מנדל","b":"רב בהאלוסק"},{"i":22056,"n":"יהודה יודל מטימקוביץ","f":"משה זאב וואלף","b":"רב בטימקוביץ-ת\"פ"},{"i":22057,"n":"יהודה יודל מלבוב","b":"רב בזולצבך,ספרא דמתא בקרקא-תפ\"ג"},{"i":22058,"n":"יהודה יודל מליעפלי","b":"תלמיד הגר\"א, והפך לחסיד בהשפעת הרב מוואלפא. תלמיד בעל התניא. רב בליעפלי."},{"i":22059,"n":"יהודה יודל ממוהילוב וצפת","f":"יוסף","b":"מחכמי קהלת הפרושים בצפת וירושלים. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":22060,"n":"יהודה יודל מפאטיק ובערזאן","f":"אברהם ר הירצקיס מלבו","b":"חתן ר אליעזר מזלוטשוב-הזקן. תלמיד הבעש\"ט, (והמגיד מזלוטשוב?). מחכמי פאטיק, עבר לבערזאן. מתורתו ב\"עיר חנוך\" ו\"שארית יהודה\"."},{"i":22061,"n":"יהודה יודל מפינסק וירושלים","dt":"תריב - יג אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":22062,"n":"יהודה יודל מקידאן","f":"פסח","b":"מו\"ץ בקידאן בזמן ר ראובן זקש. הסכים על ש\"ס סלאויטה."},{"i":22063,"n":"יהודה יודל מקניהניטש","b":"רב בקניהניטש במאה הי\"ט, נחשב לצדיק נסתר."},{"i":22064,"n":"יהודה יוסף הלוי מוידין","dt":"תקפא - י אד\"א","dp":"סופיה","b":"מחכמי וידין."},{"i":22065,"n":"יהודה יוסף הלוי מקושטא","b":"מדפיס-תעא בדפוס של יונה בן יעקב בקושטא."},{"i":22066,"n":"יהודה יעלה מאיטליה","f":"בנימין הרופא","k":"בעל פירוש לריף","b":"מחכמי איטליה. חיבר פירוש לרי\"ף - בכת\"י."},{"i":22067,"n":"יהודה יצחק אלעזר מירושלים","bt":"תרלז","bp":"שלוניקי","b":"עלה לירושלים-תרמב. מלמד בת\"ת ספרדים בירושלים, חזן ועסקן צבור."},{"i":22068,"n":"יהודה יצחק מחנטשין","f":"יעקב מצוזמיר וחנטשין","k":"בעל מציל נפשות","b":"דרשן בחנטשין-שנת ת'. הו\"ל ספר אביו \"פירוש על המסורה\" ו\"טעמי המסורה\" - עם הוספות ממנו."},{"i":22069,"n":"יהודה ישכר סגל מיאסי","b":"דיין ביאסי-תקפד, אצל ר יוסף דוד הכהן."},{"i":22070,"n":"יהודה ישראל הלוי מירושלים","dt":"תקצו - אחרי","dp":"ירושלים","b":"רב בירושלים-תקצו, חתם על מינוי ר יונה נבון."},{"i":22071,"n":"יהודה ישראל מירושלים","dt":"תקסד - א אב","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":22072,"n":"יהודה ליאונטין הכהן","f":"מאיר","b":"מראשוני חכמי התורה בצרפת ואשכנז-ד'תשן. מתלמידיו - רבנו גרשום מאור הגולה."},{"i":22073,"n":"יהודה ליאונטין מרומא","f":"משה","b":"מחכמי רומא-שנות ה-ד'תתק. שאל את ר יהודה בן קלונימוס בשם חכמי רומא ונזכר ב\"שבלי הלקט\". לדעת צונץ הוא הפייטן ר יהודה ליאון בן משה הענו שמפיוטיו סליחות במחזור רומא."},{"i":22074,"n":"יהודה ליב","f":"שמעון","k":"בעל יד יהודה,מפפד\"מ","dt":"תעד - יג תמוז","b":"מקובל, רופא, דיין בפפד\"מ, רב במיינץ-תמז. תשובה ממנו בעניני הלכה ורפואה ב\"שב יעקב\" לר יעקב פופרש מפפד\"מ. לדעת בריל - זהה עם ד\"ר ליאו סימוניס שחיבר הקדמה לביבליה של קלודיוס-1677."},{"i":22075,"n":"יהודה ליב","k":"בעל קיצור צדיק תמים","b":"חיבר \"קיצור ספר צדיק תמים\" בכת\"י (היה אצל ר יצחק רפאל פינצי ממנטובה)."},{"i":22076,"n":"יהודה ליב (אריה) משידלוב","f":"וולף","b":"רב בשידלוב-תקסג. (אולי הוא ר אריה ליב בן וולף שחתם שמו בספר \"בית יעקב\")"},{"i":22077,"n":"יהודה ליב (חיים) סגל מלבוב","f":"אליעזר הלוי מזולצבך","b":"תלמיד ר נפתלי אב\"ד גלוגא. דיין ור\"מ בלבוב, חתם-תסב בפנקס הקהלה, הסכים על \"מאמר מרדכי\", \"זרע ישראל\" (עם מהר\"ם מלובלין, ר יחזקאל קצנלנבוגן ואחרים), אחיו - ר יוסף הלוי מזולצבך בעל \"עדות ביהוסף\". (לדעת בובר - הוא זהה עם ר חיים יהודה ליב איטינגא-חתנו של ר שמחה רפפורט."},{"i":22078,"n":"יהודה ליב בן אהרן שמואל מקרמניץ","bt":"1580","dt":"ה'תז 1647","bk":[["זיז שדי",""]]},{"i":22079,"n":"יהודה ליב בן חנוך","bt":"1645","dt":"ה'תסה 1705","bk":[["חינוך בית יהודא",""]]},{"i":22080,"n":"יהודה ליב דרשן מפרג","f":"שלמה","dt":"תפ - תפג","dp":"פפד\"א","b":"חתן ר שמעיה בן אברהם ישכר בר מברלין. אב\"ד פילא(=שנידעמיהל)-תנה, גריידץ-פולין-תנט ור שמואל זנויל שפירא מלבוב על מקומו אחריו, עבר לפפד\"א בגלל המלחמות בפולין ולימד תורה לרבים. הסכים על ספרים רבים ובהם \"מקור חיים\"-תנז. מתורתו בספרי חכמי דורו. בניו ר מיכל חסיד-רב בברלין ופפד\"א, ר שלמה - דיין בליסא."},{"i":22081,"n":"יהודה ליב הדרשן מאוסטרהא","f":"משה מברוד","bp":"גליציה","dt":"תקכו - כה תשרי","dp":"אוסטרהא","b":"תלמיד ר אפרים מברוד, תלמיד הבעשט וממפיצי תורתו. רב ומ\"מ באוסטרהא, ובנו רב ייבי על מקומו אחריו, מתורתו בספר בנו רב ייב\"י. כשהגיע לאוסטרהא פגש כמה זקנים שהכירו את הט\"ז ובירר אצלם על מנהגי הט\"ז."},{"i":22082,"n":"יהודה ליב הכהן","f":"ישכר בר","dt":"יד תשרי תקסז","b":"רב מקובל-תקח, שלח את ר ישכר בר בן מרדכי לבגדד, כדי להעתיק את כתה\"י \"עץ חיים\" לר חיים ויטאל, בבית הנשיא ר משה מרדכי בבגדד.","bk":[["אור הגנוז - עה\"ת",""]]},{"i":22083,"n":"יהודה ליב הכהן מאלטונא","f":"אברהם","dt":"תפה - יז ניסן","dp":"אלטונא","b":"מחכמי בריסק, עבר לאלטונא."},{"i":22084,"n":"יהודה ליב הכהן מאניפולי","k":"בעל אור הגנוז","dp":"אניפולי","b":"מג\"מ באניפאלי-תקס. תלמיד המגיד ממזריטש, והיה בעל תפילה אצלו. נקבר ליד המגיד. חיבר גם \"וזאת ליהודה\". חתניו ר אהרן מאניפולי, ור משה אליקים בריעה מקוזניץ."},{"i":22085,"n":"יהודה ליב הכהן מירושלים","b":"מקובל,מופלא בדורו,מחכמי אשכנז בירושלים-ש\"ס"},{"i":22086,"n":"יהודה ליב הכהן מירושלים","f":"דוד","b":"מחכמי ירושלים, אולי תלמיד האר\"י."},{"i":22087,"n":"יהודה ליב הכהן מלובלין","f":"שלמה","dt":"תו","dp":"לובלין","b":"מראשי קהילת לובלין."},{"i":22088,"n":"יהודה ליב הכהן ממוסקבה","f":"אברהם","dt":"תרסד - ב טבת","dp":"מוסקבה","b":"חתן ר ר שמעון מבירז, ובזיוו\"ש חתן ר יהודה ליב מפוסוואל. רב בפרידריכשטט על מקום קרובו ר אורי ליפמן פרידמן, מוסקבה-תרנה."},{"i":22089,"n":"יהודה ליב הכהן מסאל","f":"בצלאל הכהן","r":"אב\"ד דסאהל","bt":"תקפח","dt":"תרמט - יח אב","b":"רב בסאל-תר\"ו","bk":[["בית יהודה אחרון – כת\"י",""],["שאגת ארי – גפ\"ת כת\"י",""],["שאגת ארי – גפ\"ת כת\"י , בית יהודה אחרון – כת\"י",""]]},{"i":22090,"n":"יהודה ליב הכהן מסטרי","f":"יואל מאנטוני וסטניסל","bt":"תפח","dt":"תקכט - יג סיון","b":"חתן ר מאיר חיות. רב בבאלחוב, סטריא-תקיב. חתנו - ר מאיר בן שמשון רולר. אחיו של ר יצחק בעל \"ברית כהונת עולם\"."},{"i":22091,"n":"יהודה ליב הלוי","f":"משלם זלמן הלוי","k":"ר' ליב הגדול","b":"בנו - ר מאיר"},{"i":22092,"n":"יהודה ליב הלוי מזולקוא","f":"חנוך הניך מזלקווא","b":"חתן ר חנוך הניך מזולקוא. רב בזלקווא-ת\"ק"},{"i":22093,"n":"יהודה ליב הלוי מלבוב","k":"בעל מערכי לב","b":"ר\"מ בלבוב-תע\"ט"},{"i":22094,"n":"יהודה ליב הלוי מליפסק","f":"יצחק דובער","k":"בעל אלופי יהודה","b":"רב בליפסק-תקם. תלמיד ר משה חנניה ליפמן מאפטא ופיעטריקוב, ובחסידות תלמיד ר לוי יצחק מברדיטשוב, ר ישראל המגיד מקוזניץ ועוד."},{"i":22095,"n":"יהודה ליב הלוי מקראקא","b":"רב בקרקא"},{"i":22096,"n":"יהודה ליב הלוי סטבניצר","f":"משה","dt":"תסג - ו כסלו","dp":"לבוב","b":"מחכמי רישא, לבוב."},{"i":22097,"n":"יהודה ליב הלוי-תלמיד הבעשט.","b":"מצאצאי הט\"ז. אביו של ר דוד האדמור מסטעפין."},{"i":22098,"n":"יהודה ליב השט\"ט מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":22099,"n":"יהודה ליב חסיד מירושלים","k":"ר' ליב חסיד מטלז","dt":"תקעג - ד תמוז","dp":"ירושלים","b":"תלמיד הגר\"א שהעיד עליו שהוא נשמה בלא גוף."},{"i":22100,"n":"יהודה ליב כץ מדומברובה","f":"צבי הירש","dt":"תקמח - בערך","b":"מקובל מחכמי דומברובא. בנו - האדמור ר צבי הירש משרת מרימנוב."},{"i":22101,"n":"יהודה ליב מאוסטרהא","dt":"תקלז - ז טבת","b":"ר\"מ באוסטרהא-ת\"צ,רב בסלוצק"},{"i":22102,"n":"יהודה ליב מאוסטרהא","f":"אשר ענזל מפינטשוב","dp":"פינסק","b":"נכד ר יצחק רפפורט מאוסטרהא. רב באוסטרהא-תפא, סלוצק-תפב, פינסק. הסכים על \"זרע ישראל\"-תפב, \"עולת אהרן\"-תצא. נספד ב\"דברי רב משולם\" לר אברהם משולם זלמן מפינסק. בניו: ר אשר ענזל בעל \"ברוך מבנים אשר\", ר דוד בעל \"אותות למועדים\", ר מרדכי מאוסטרהא. חתנו ר יצחק איזיק הכהן על מקומו אחריו באוסטרהא."},{"i":22103,"n":"יהודה ליב מאוסטרהא","f":"משה משלם","dt":"תעה - ה סיון","dp":"אוסטרהא","b":"ראש ומנהיג באוסטרהא. לא נודע עליו יותר."},{"i":22104,"n":"יהודה ליב מאוסטרהא","f":"יואל","dt":"תקצא - כט ניסן","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":22105,"n":"יהודה ליב מאוסטרהא","f":"יחזקאל","k":"בעל בית לחם יהודה","b":"שו\"ב באוסטרהא. חיבר \"בית לחם יהודה\"-זולקוא תנג, \"סדר הניקור\" - קראקא תר."},{"i":22106,"n":"יהודה ליב מאוסטרהא","f":"אברהם אבלי מקרמניץ","b":"דיין באוסטרהא. הסכים על \"רב ייב\"י\" ועוד."},{"i":22107,"n":"יהודה ליב מאוסטרהא","k":"ליב חזן","dt":"תקפג - טז ניסן","dp":"אוסטרהא","b":"דיין באוסטרהא, כנראה גיסו של ר ייב\"י."},{"i":22108,"n":"יהודה ליב מאוסטרהא","f":"אברהם מתתיהו מפינסק","dt":"תקצד - ט אד\"א","dp":"אוסטרהא","b":"דיין באוסטרהא - כאביו לפניו אצל ר חיים רפפורט. הסכים על מחזור אוסטרהא-תקעו, ועוד. נפטר בן קרוב ל-100."},{"i":22109,"n":"יהודה ליב מאוסטרהא וקראקא","k":"ר' יהודה ליב הדרשן","dt":"תט - ט כסלו","dp":"קראקא","b":"דרשן,מג\"מ באוסטרהא."},{"i":22110,"n":"יהודה ליב מאורשא","k":"בעל אבל כרמים","bt":"שפ","dt":"תן - בערך","b":"מ\"מ באורשא. חיבר \"אבל כרמים\" - הספד על ר חנוך הניך שיק - שקלוב תקסה."},{"i":22111,"n":"יהודה ליב מאיר","k":"בעל יד השלחן","bt":"תריט","dt":"תרצ - כט ניסן","b":"דיין בקרלסרוה-תר\"נ"},{"i":22112,"n":"יהודה ליב מאליסנדריה דילה פליה","f":"חיים","b":"רב באליסנדריאה דילה פאליה. תשובה אליו ב\"דבר שמואל\"."},{"i":22113,"n":"יהודה ליב מבאייא","b":"רב בבאייא-תר\"ל"},{"i":22114,"n":"יהודה ליב מבוצאץ","f":"יקותיאל","k":"בעל דברי חכמים","b":"רב בבוצאץ-תץ. חיבר \"דברי חכמים\" זולקוא תקיז."},{"i":22115,"n":"יהודה ליב מבוריסלוב","f":"יונה","b":"מו\"צ בבריסלאב"},{"i":22116,"n":"יהודה ליב מבילגורי","f":"פייבל מלעכוויץ","k":"יהודה ליב מבילגוריי","b":"רב בבילגוריי"},{"i":22117,"n":"יהודה ליב מברדיטשוב","f":"פנחס","b":"דיין בברדיטשוב אצל ר לוי יצחק"},{"i":22118,"n":"יהודה ליב מבריסק","b":"רב בבריסק. נזכר בשו\"ת מהר\"ם מלובלין. חתם ביריד ירוסלב-שן עם ר יהודה ליב אילנברג (לפי החכם הרכבי)."},{"i":22119,"n":"יהודה ליב מבריסק","f":"מנחם מנדל","b":"תלמיד ר יעקב עמדן, שהשיב לו-תקכו."},{"i":22120,"n":"יהודה ליב מבריסק","f":"מרדכי הירש","dt":"תרטו - כט תשרי","dp":"בריסק","b":"מצאצאי ר משה קאזס. גביר מחכמי בריסק."},{"i":22121,"n":"יהודה ליב מבריסק - ב","b":"תלמיד ר יעקב עמדין. מחכמי בריסק."},{"i":22122,"n":"יהודה ליב מגורזד","f":"ישכר בר מגורזד","b":"מצאצי בעל הט\"ז. רב בגורזד על מקום אביו, ובנו ר אליעזר על מקומו אחריו."},{"i":22123,"n":"יהודה ליב מגירבא","b":"רב בגירבא-ת\"ר"},{"i":22124,"n":"יהודה ליב מדמביץ","b":"רב בדמביץ-תריט. חתן ר יצחק אברמל."},{"i":22125,"n":"יהודה ליב מדננבורג","k":"בעל זכר יהודה","b":"אב\"ד דננבורג. תלמיד בעל התניא. כונה כ\"הבטלן מדדנבורג\"."},{"i":22126,"n":"יהודה ליב מהאטימסק (משכיל לאית","f":"אברהם","b":"אב\"ד האטימסק. אביו של ר אברהם משכיל לאיתן מנוברדוק. נכד - ר ישראל יפה משקלוב בעל \"אור ישראל\"."},{"i":22127,"n":"יהודה ליב מהוצנפלץ וניקלשבורג","f":"אלחנן מוינה","b":"רב בהוצנלפלץ(האצנפלאץ), דיין בניקלשבורג. הסכים על תהלים עם \"מאזני צדק\", \"שלשה שריגים\" לאחיו ר יוסף ישכר בער."},{"i":22128,"n":"יהודה ליב מהורדנא","f":"אליעזר מזאלבין","k":"בעל קול יהודה","b":"עוור מגיל שנה,מג\"מ בהורדנא-תק\"מ"},{"i":22129,"n":"יהודה ליב מהורדנא","f":"משלם זלמן","b":"מחכמי הורדנא, ממלא מקום ר ברוך רפפורט-תף שעבר לפיורדא עד למינוי ר יעקב טראפא."},{"i":22130,"n":"יהודה ליב מהורדנא","f":"יקותיאל זלמן","b":"מו\"צ בהורדנא, הסכים-תריט על 'שמן ששון' לר יצחק ששון."},{"i":22131,"n":"יהודה ליב מהורודושיץ","b":"רב בהורודושיץ"},{"i":22132,"n":"יהודה ליב מואיסדיסלב ולבוב","b":"דיין בלבוב, חתם-תפז על פסק דין, חתם בפנקס קהלת לבוב-תץ עם ר יקותיאל זלמן אפשטין, ר יהושע פאלק שור, ועוד."},{"i":22133,"n":"יהודה ליב מואלוטשיסק","b":"ראב\"ד בוואלאטשיסק-תק\"צ"},{"i":22134,"n":"יהודה ליב מואנדסבק","f":"יעקב","k":"בעל מנחת יהודה","dt":"תנג - ג אייר","dp":"ונדסבק","b":"הגיע מקרוטושין. מו\"ץ בואנדסבק-תלה. הסכים על \"קיצור ראשית חכמים\" המבורג תנה, הו\"ל \"מרפא לנפש\", ועוד."},{"i":22135,"n":"יהודה ליב מויזון ופיורדא","f":"העניך","b":"מדפיס בדפוס חיים בן צבי הירש בפיורדא - תקל."},{"i":22136,"n":"יהודה ליב מויליצקה","b":"תשובה אליו - עט\"ח-תקן."},{"i":22137,"n":"יהודה ליב מוילנא","f":"צבי הירש","b":"מקובל, דיין בוילנא. הסכים על ש\"ס וילנא-תקצה."},{"i":22138,"n":"יהודה ליב מוילנא","f":"משה אהרן מואשלישוק","b":"מחכמי וילנא, הסכים-תקמג על באור מהרש\"ד. אחיו - ר אשר-נפטר תקנג."},{"i":22139,"n":"יהודה ליב מוילנא","f":"שלמה זלקינד","dt":"תקפח-ט - ח ניסן","dp":"וילנא","b":"מחכמי וילנא."},{"i":22140,"n":"יהודה ליב מוילנא","f":"דב בער ר אלייעש","b":"גביר בוילנא, ניהל את ההקדש שהניח ר משה ריבקש בעל באר הגולה. הניח מצבה על קברו של ר משה ריבקש."},{"i":22141,"n":"יהודה ליב מוילנא","f":"יעקב","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":22142,"n":"יהודה ליב מוילנא","f":"אברהם","dt":"תקטו - כא אד\"א","dp":"וילנא","b":"מראשי קהלת וילנא. אחיו - ר ישכר בער מוילנא."},{"i":22143,"n":"יהודה ליב מוילנא","f":"שמואל","b":"דיין בוילנא-תקכט עד תקלח."},{"i":22144,"n":"יהודה ליב מוילנא","f":"דוד סו\"ד","dt":"תקעב - כט תמוז","dp":"וילנא","b":"מחכמי וילנא."},{"i":22145,"n":"יהודה ליב מוילנא","f":"שלום","dt":"תקעג - כ שבט","dp":"וילנא","b":"מחכמי וילנא, נפטר צעיר."},{"i":22146,"n":"יהודה ליב מוילנא והארקי","dt":"תק - לפני","dp":"וילנא","b":"רב בהארקי, ראב\"ד בוילנא-תף בזמן כהונת ר יהושע השל. מתורתו ב\"מצודת דוד\". (ראה גם ר יהודה ליב מטיקטין)."},{"i":22147,"n":"יהודה ליב מוילנא וסארהיי","f":"הגר\"א","dt":"תקעו - כה שבט","dp":"ניישטאט-טאווריג","b":"חתן ר אברהם בן יחזקאל מלזדייא. רב בסארהיי, וילנא. הו\"ל כמה מחיבורי אביו עם אחיו ר אברהם. נפטר בדרכו לדרוש ברופאים בקניגסברג. בניו: ר יחזקאל מסערהייא, ר טוביה, ר ישכר בעריש וילנר מוארשא. מחותן עם ר אברהם דנציג בעל \"חיי אדם\"."},{"i":22148,"n":"יהודה ליב מוינה","f":"נפתלי","dt":"תסח - ח חשון","dp":"אלטונא","b":"מחכמי וינה, אחרי גירוש וינה-תל הגיע להמבורג. דיין באה\"ו."},{"i":22149,"n":"יהודה ליב מזולקוא","f":"ישראל","k":"בעל נפש יהודה","bt":"תע","dt":"תקנב - יב אלול","dp":"זולקוא","b":"נכד בעל \"גאון צבי\". רב בזולקווא. חיבר גם \"מנחת יהודה\" זולקווא תקם, ועוד."},{"i":22150,"n":"יהודה ליב מזולקוא","f":"ישראל יצחק","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה, חתם-תעד על פסק ביחד עם כמה גדולים."},{"i":22151,"n":"יהודה ליב מזולקוא","f":"ישכר בער","dt":"תקא - ו חשון","dp":"זולקוא","b":"ראש מדינה בזולקוא, חתם-תנא על תקנת הקהלה וחתם גם בשנים תסד, תסה."},{"i":22152,"n":"יהודה ליב מזולקוא","f":"יהודה משה","b":"מחכמי זולקוא, חתם-תקיא ב\"לוחות העדות\" על החרם בזולקוא."},{"i":22153,"n":"יהודה ליב מזולקוא","f":"שמואל מזולקוא","b":"מחכמי זולקוא, חתם-תקיא ב\"לוחות העדות\" על החרם בזולקוא."},{"i":22154,"n":"יהודה ליב מזולקוא","f":"רמ\"י","b":"מחכמי זולקוא, חתם-תקם על תקנת הקהלה."},{"i":22155,"n":"יהודה ליב מזלישטשיק","b":"רב בזלישטשיק. תשובה אליו \"בית שלמה\"."},{"i":22156,"n":"יהודה ליב מזקליקוב","k":"בעל לקוטי מהרי\"ל","r":"אב\"ד זאקליקוב וזאוויחווסט","dt":"תקפו - יד אייר","b":"רב בזקליקוב, זאוויחווסאט. תלמיד ר אלימלך מליזנסק, והחוזה מלובלין. בזמן המחלוקת כנגד היהודי הקדוש מפשיחסא עמד בראש החולקים. חיבר \"לקוטי מהרי\"ל. בנו ר שמואל שמלקא-חסיד החוזה מלובלין.","bk":[["לקוטי מהרי\"ל",""]]},{"i":22157,"n":"יהודה ליב מחברון (סענר)","f":"זאב וולף","dt":"תרט - אחרי","b":"מראשוני חסידי חב\"ד בחברון. בשנת תרט היה זקן התושבים בחברון."},{"i":22158,"n":"יהודה ליב מטאליא","b":"רב בטאליא-תק\"נ"},{"i":22159,"n":"יהודה ליב מטופורוב","b":"רב בטופורוב - תשובה אליו \"שירי טהרה\"."},{"i":22160,"n":"יהודה ליב מטימישואר","b":"רב בטימישואר-תקה."},{"i":22161,"n":"יהודה ליב מטשנגר","dt":"תר - יד ניסן","b":"דומ\"צ בטשענגער"},{"i":22162,"n":"יהודה ליב מיאנוביץ","f":"ישראל ברוך מליאזני","k":"בעל שארית יהודה","b":"מו\"צ ביאנוביטש(=יאנוביץ)-תקס. אחיו של בעל התניא, והביא מתורת אחיו ב\"תורה אור\". מכתבים ממנו בתלמיד ישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":22163,"n":"יהודה ליב מירושלים","b":"מגדולי חכמי ירושלים-תק\"כ"},{"i":22164,"n":"יהודה ליב מירושלים","f":"צבי אפרים","dt":"תקו - טו אלול","dp":"ירושלים","b":"מחכמי הקהלה האשכנזית בירושלים."},{"i":22165,"n":"יהודה ליב מלבוב","f":"מנחם","dt":"שטז - ג אב","dp":"לבוב","b":"מרביץ תורה בלבוב"},{"i":22166,"n":"יהודה ליב מלבוב","dt":"ת - יב כסלו","b":"רב בלבוב"},{"i":22167,"n":"יהודה ליב מלבוב","f":"אשר למל","dt":"תיז - כו תשרי","dp":"לבוב","b":"מרביץ תורה בלבוב."},{"i":22168,"n":"יהודה ליב מלבוב","f":"ישראל מקראקא","dt":"תט - יג אדר","dp":"לבוב","b":"ר\"מ בלבוב. חתם עם בעל ווי העמודים ועם ר דוד בן מרדכי מלבוב על תשובה ב\"איתן האזרחי\". (אולי הוא ר יהודה ליב בן שמחה מקראקא? - תאריך פטירתם זהה!)"},{"i":22169,"n":"יהודה ליב מלבוב","f":"שלמה","dt":"תכד - ח אייר","dp":"לבוב","b":"ילד מחכמי לבוב. נהרג עק\"ה."},{"i":22170,"n":"יהודה ליב מלבוב","f":"אברהם","dt":"תי - יב כסלו","dp":"לבוב","b":"רב בלבוב."},{"i":22171,"n":"יהודה ליב מלבוב","f":"אורי","b":"דיין בלבוב, חתם-ת' על פס\"ד על מכירת קרקע."},{"i":22172,"n":"יהודה ליב מלבוב","b":"סופר קהלת לבוב, חתם-תד על תקנת הקהל."},{"i":22173,"n":"יהודה ליב מלבוב ופודהייץ","f":"משה מפודהייץ","k":"שפירא?","dt":"שעג - יא חשון","dp":"לבוב","b":"רב בפודהייץ(=פאדהאיטץ) על מקום אביו, ר\"מ בלבוב."},{"i":22174,"n":"יהודה ליב מלוביטש","b":"רב בלוביטש-תרלט."},{"i":22175,"n":"יהודה ליב מלובלין","f":"משה","k":"בעל פרי שבת","dt":"תקיח - ד ניסן","b":"רב בלובלין. חיבר גם \"דברי יהודה\", ועוד."},{"i":22176,"n":"יהודה ליב מלובלין","f":"משה אהרן שמואל","b":"מחכמי לובלין. חיבר פירוש למאמרי רבב\"ח בשם \"זיז שדי\" לובלין שצג."},{"i":22177,"n":"יהודה ליב מלובלין","f":"שמואל","k":"ליב מנליש","dt":"תז","dp":"לובלין","b":"מראשי קהילת לובלין"},{"i":22178,"n":"יהודה ליב מלונטשיץ","b":"רב בלונטשיץ"},{"i":22179,"n":"יהודה ליב מליניץ","f":"דב בער-שבחי הבעשט","k":"בעל תשואות חן","b":"נכד ר אלכסנדר משדה לבן-סופר הבעשט."},{"i":22180,"n":"יהודה ליב ממונקטש","dt":"תקמט - כ חשון","b":"רב במונקאטש"},{"i":22181,"n":"יהודה ליב ממינסק","f":"אברהם","dt":"תריא - י אדר","dp":"מינסק","b":"רב במינסק."},{"i":22182,"n":"יהודה ליב ממינקוביץ","b":"נזכר ב\"דעת קדושים\" לאדמור מנדבורנא."},{"i":22183,"n":"יהודה ליב מנמירוב","b":"רב בנימירוב"},{"i":22184,"n":"יהודה ליב מסטבוס","dt":"תשג","b":"רב בטרסטינא"},{"i":22185,"n":"יהודה ליב מסטנוב","b":"ר\"מ בסטאנוב"},{"i":22186,"n":"יהודה ליב מסימנא","b":"רב בסימנא-תר\"פ"},{"i":22187,"n":"יהודה ליב מפוזנא","f":"הענכש","k":"יהודה ליב ר הענכש","dt":"שץ","b":"אב\"ד פוזנא, נספד מאת ר אברהם רפפורט ב\"איתן האזרחי\"."},{"i":22188,"n":"יהודה ליב מפוזנא","b":"מנהיג בועד ארבע ארצות, חתם-תמז ביריד ירוסלב."},{"i":22189,"n":"יהודה ליב מפולין ואזמיר","dt":"תקכה","dp":"אזמיר","b":"מחכמי פולין, אזמיר."},{"i":22190,"n":"יהודה ליב מפיורדא","f":"שלמה זלמן","b":"מדפיס בדפוס חיים בן צבי הירש בפיורדא - תקל."},{"i":22191,"n":"יהודה ליב מפרג","f":"יהושע","k":"בעל מלחמה בשלום","b":"סופר בית הרב ר שמעון שפירא בפרג, חיבר \"מלחמה בשלום\" על מלחמת השבדים בפרג-תח - נדפס בבכורי העתים תקפד."},{"i":22192,"n":"יהודה ליב מפריצק","b":"רב בפאריצק"},{"i":22193,"n":"יהודה ליב מפרשבורג","f":"משה מקרוטושין","dt":"תקכב - טו אדר","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":22194,"n":"יהודה ליב מפרשבורג","f":"יוסף","b":"מחכמי פרשבורג, חתם-תקכה על תקנות החברא קדישא."},{"i":22195,"n":"יהודה ליב מפרשבורג וירושלים","f":"משה","dt":"תרנד - יא ניסן","dp":"ירושלים","b":"עלה לירושלים-תקצט."},{"i":22196,"n":"יהודה ליב מפשזדבורז","b":"רב בפשזדבורז-תקכ\"ד"},{"i":22197,"n":"יהודה ליב מצפת","f":"יעקב","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":22198,"n":"יהודה ליב מקאבלין","f":"דוד שמואל שמלקא","b":"רב בקאבלין-תק\"ל"},{"i":22199,"n":"יהודה ליב מקאליש","b":"רב בקאליש"},{"i":22200,"n":"יהודה ליב מקלינורדין","dt":"תרג - כ אייר","b":"מו\"צ בקליינוורדיין"},{"i":22201,"n":"יהודה ליב מקמינקא","f":"שמואל","b":"רב בקמינקא-תקנז."},{"i":22202,"n":"יהודה ליב מקמניץ","b":"רב בקמניץ, קרופיטש-תרך."},{"i":22203,"n":"יהודה ליב מקראקא","f":"שמחה בונם מייזל","dt":"תט - יג אדר","b":"מרביץ תורה בקרקא"},{"i":22204,"n":"יהודה ליב מקרלין וירושלים","f":"משה","dt":"תריב - יג אלול","dp":"ירושלים","b":"חתן ר אריה ליב הכהן. מחכמי ירושלים."},{"i":22205,"n":"יהודה ליב מקרעמניא","b":"רב בקרעמניא-תק\"י"},{"i":22206,"n":"יהודה ליב מראב","b":"רב בראב-תקמ\"ט"},{"i":22207,"n":"יהודה ליב מראקוב","f":"אליהו","dt":"תקמב - י ניסן","dp":"קראקא","b":"חתן ר אליקים גץ מראקוב. בנו - ר יהושע."},{"i":22208,"n":"יהודה ליב מראקוב וקראקא","f":"יצחק אייזיק מפרמישלא","dt":"תצב - ח ניסן","b":"נכד ר שמואל שמלקא-אב\"ד אוסטרהא.. תורה וגדולה במקום אחד, רב בראקוב, סטאשוב, שידלוב-תסא, קראקא-תעג (בערך). הסכים על \"ברית שלום\"-תעג, \"מסגרת השלחן\"-תעב, \"ברכת יעקב\"-תפ, ועוד. בניו - ר משה מלאנצוט, ר יצחק איזיק מטרנוב, ר יהושע משידלוב, ר דוד שמואל שמלקא על מקומו אחריו בקראקא, ר יוסף מפינטשוב. חתנו - ר בנימין בונם-פרנס ור\"מ בקראקא. נספד מאת ר עוזיאל מייזלש ב\"עץ הדעת טוב\"."},{"i":22209,"n":"יהודה ליב מרוזדול","b":"אב\"ד רוזדול, פגש את ר מאיר א\"ש בעל אמרי אש."},{"i":22210,"n":"יהודה ליב מרוסיה הלבנה","f":"שמחה בונם מקרקא","b":"רב מדינת רוסיה לבנה"},{"i":22211,"n":"יהודה ליב מריטשוואל","b":"רב בריטשוואל-תק\"ל"},{"i":22212,"n":"יהודה ליב משארגרד","dt":"תקסט - כג תשרי","b":"מקובל,רב בשארגראד"},{"i":22213,"n":"יהודה ליב משוורזען","f":"הלל","k":"בעל חכם לב","b":"מחכמי שוורזניץ(=שוערזנץ). חיבר \"חכם לב\" על תריג מצוות, ותורגם ללטינית בידי החכם קרל שולטענס - 1731."},{"i":22214,"n":"יהודה ליב משידלוב וקאלין","f":"יחיאל מיכל מגלוגא","b":"רב בקאלין-תק\"י"},{"i":22215,"n":"יהודה ליב משענלנאק","f":"שמשון מראויטש","b":"אב\"ד שענלנאק-שנות ה-תר'."},{"i":22216,"n":"יהודה ליב משקלוב","b":"סופר משקלוב, מחכמי מילניצה-תקצט."},{"i":22217,"n":"יהודה ליב סגל מגונצנהויזן","b":"ש\"ץ ונאמן בגונצנהויזן. חתם בקרונהיים-תקנו."},{"i":22218,"n":"יהודה ליב סגל מוילנא","f":"מרדכי","b":"דיין בוילנא, חתם-תץ עם ר יהודה מטיקטין."},{"i":22219,"n":"יהודה ליב סגל מלבוב","f":"יעקב","dt":"תנז - א תשרי","dp":"לבוב","b":"אב\"ד ור\"מ בלבוב, חתם-תנב על פסק דין, נזכר ב\"אדני פז\", \"ארבע שיטות-פנים מסבירות\", \"לקוטי שושנים\", \"שאגת אריה וקול שחל\" לנכדו ר נתן נטע מויזניץ, ועוד. ראה גם יהודה יוסל מקאוולי ולבוב (שהיה באותו הזמן בלבוב ורבים מחליפים ביניהם)."},{"i":22220,"n":"יהודה ליב סגל מפוזנא ווילנא","f":"אברהם","dt":"תקפו - כד סיון","dp":"וילנא","b":"מחכמי וילנא."},{"i":22221,"n":"יהודה ליב סזל מוילנא","f":"זיסקינד","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":22222,"n":"יהודה ליב פסח מיוזפוף","bt":"תקסב","dt":"תרכג - יג אב","b":"איש מופת,רב ביוזעפוף גדול,ליפסק"},{"i":22223,"n":"יהודה ליב ראובן מפרובישץ","f":"ישראל","b":"ש\"ץ ונאמן קהלת פרובישץ, חתם-תקסט על כתובת ר ישראל האדמור מרוזין."},{"i":22224,"n":"יהודה ליב רופא","k":"בעל קול יהודה","b":"גדול בתורה וחכמה-ת\"ה"},{"i":22225,"n":"יהודה ליב רופא מוינה","b":"רופא, ר\"מ ואב\"ד בוינה ור חיים מנחם מן על מקומו אחריו-שצז, נכדו(-בן בתו) - ר מנחם מנדל אוירבך בעל \"עטרת זקנים\" ומביא ממנו בספרו."},{"i":22226,"n":"יהודה ליבא מלודמיר","b":"רב בלודמיר-שפ."},{"i":22227,"n":"יהודה ליבוש מהרימלוב","b":"רב בהרימלוב. נכד ר סנדר חיים בעל \"תבואות שור\"."},{"i":22228,"n":"יהודה ליבוש מנעסכיז","f":"ישעיה","b":"רב בנעסכיז-ת\"ק"},{"i":22229,"n":"יהודה ליבוש מסוקולוב","b":"רב בסוקולוב-תרך."},{"i":22230,"n":"יהודה ליביש כץ מבולחוב וסטרי","bt":"תקכא","dt":"תקסב - יג ניסן","b":"אחיו של ר יצחק איזיק מקוריץ ושל בעל \"עיקר תוי\"ט\"."},{"i":22231,"n":"יהודה ליבש מגניוושוב","b":"רב בגניוושוב"},{"i":22232,"n":"יהודה ליבש מגריצא","dt":"תרכג - יא אדר","b":"רב בגריצא"},{"i":22233,"n":"יהודה ליוואי מפיררא","b":"מגדולי חכמי איטליה בפיררה,מנטובה-רע\"ב"},{"i":22234,"n":"יהודה ליוואי מפפד\"מ ומיינץ","b":"דיין בפפד\"מ, רבה הראשון של מיינץ-שצד - לאחר חידוש הקהילה-שמג (עד אז היו כפופים לרב של בינגן)."},{"i":22235,"n":"יהודה ליוואי מפרג","k":"ר' יהודה ליוואי הזקן","dt":"ר-רו - יג חשון","dp":"פרג","b":"מצאצאי דוד המלך. רב בפרג. בניו - ר יעקב מוורמייזא, ר חיים מוורמייזא, ר בצלאל מוורמייזא, ונכדו המהר\"ל מפרג."},{"i":22236,"n":"יהודה ליוואי משוערזניץ","f":"יעקב מרדכי מפוזנא","b":"רב בשווערזנץ(=שוורזנץ)-תק\"כ"},{"i":22237,"n":"יהודה לעווין מאוסטרהא","f":"נחמיה כץ","b":"רב באוסטרהא. ור יעקב רפפורט מביא ממנו ב\"מים חיים\". חתם על המגילה-תקנב."},{"i":22238,"n":"יהודה מאדרינופול","f":"יצחק","b":"מראשי קהלת אדרינופול, חתם-תקצה על בקשת עזרה לקהלה מקהלת רוסג'וק לאחר השריפה עם הרבנים ר יוסף בכמוהר\"ר מרדכי ור יקיר אשטרוק גירון, ועם משה אלפאסה, נסים יוסף פיזה, חיים עובדיה, ואהרן רודריג."},{"i":22239,"n":"יהודה מאוסטרהא","f":"צבי","dt":"תקץ - כט ניסן","dp":"אוסטרהא","b":"ספרא ודיינא באוסטרהא. הסכים על \"מאיר נתיבים\", ועוד. חתם על המגילה-תקנב. מבניו: ר יהושע מאוסטרהא."},{"i":22240,"n":"יהודה מאופראן-מרוקו","f":"נפתלי","b":"האחרון מ-50 הקדושים שנשרפו עק\"ה בכפר אופראן-מרוקו בגזירת השמד."},{"i":22241,"n":"יהודה מאיר מירושלים","b":"מחכמי ירושלים-תקפז, נזכר בשטר חזקה עם ר יהודה ן רובי."},{"i":22242,"n":"יהודה מאלזס","f":"יקר","b":"תלמיד ר יצחק בן אברהם הצרפתי. מגדולי הראשונים, מחכמי אלזס-ד'תתקפ."},{"i":22243,"n":"יהודה מאנטליפט","b":"רב באנטליפט"},{"i":22244,"n":"יהודה מאשכנז","k":"אבי רבינו גרשום","b":"מגדולי חכמי אשכנז הראשונים-ד'תש\"מ"},{"i":22245,"n":"יהודה מבלגרד","f":"דוד","b":"רב בבלגרד-שנות ה-ש'."},{"i":22246,"n":"יהודה מבריסק","f":"משה ר הללס מבריסק","b":"חתם-תלו בפנקס קהלת בריסק."},{"i":22247,"n":"יהודה מברצלונה","f":"שלמה","b":"משורר מחכמי ברצלונה - תחילת שנות ה-ה'. נזכר אצל ר אברהם בדרשי."},{"i":22248,"n":"יהודה מגלוגלא","f":"חנינא זליג מלונטשיץ","k":"בעל קול יהודה","b":"רב בגלוגא-תע. חיבר \"קול יהודה\". גיסו - ר זליג מקאליש."},{"i":22249,"n":"יהודה מדאשיב","bt":"תקיז","dt":"תקצח","b":"חתן ר ליב מסראסטיניץ. חסיד ר פנחס מקוריץ, ור נחמן מברסלב. אב\"ד מעדבידובקא ובנו ר ישעיה שלום על מקומו אחריו."},{"i":22250,"n":"יהודה מהמגרב","f":"חנין","k":"בעל עץ חיים","b":"חיבר \"עץ חיים\" ונדפס עם \"אשל אברהם\" לאברהם טובייאנה בליוורנו."},{"i":22251,"n":"יהודה מוילנא","f":"אליעזר חב\"ת","k":"יסו\"ד,היסו\"ד","bp":"וילנא","dt":"תקכב - כד אדר","dp":"וילנא","b":"חתן ר יהודה ליב בן ישראל חריף-חתנו של ר הלל מוילנא בעל \"בית הלל\". כונה יסו\"ד(=יהודה ספרא ודיינא). גביר עשיר בוילנא, ספרא ודיינא בוילנא - קיבל את התואר בזכות תרומותיו הגדולות ופעילותו לטובת הקהילה. בנה את ביהמ\"ד הנקרא \"קלויז יסוד\". עזר לקהלה במאבקה נגד המגיסטרט שהעביר החלטת גירוש ליהודי וילנא-תקב. השתתף בועידת הרבנים במיר-תקיא שבה דנו במחלוקת ר יעקב עמדין ור יהונתן איבשיץ ועמד לצדו של ר יהונתן. חתם על הכרוז לשיקום ביהכ\"נ של ר יוסף קארו בניקופול. חתנו - ר שמואל בן אביגדור - רבה האחרון של וילנא ובשנותיו הראשונות כיהן היסו\"ד בפועל כרב. בנו היחיד? (היה לו בן נוסף) נפטר בילדותו. התנה עם הח\"ק שלאחר פטירתו יקימו אהל על קברו (אם לא יעלה לירושלים - כפי שתכנן) ושלאחריו לא יוקמו יותר אהלים בבית הקברות - בפועל לא עמדו הח\"ק בתנאי זה. בנו - ר חנוך הניך מקלווריה."},{"i":22252,"n":"יהודה מוילנא","f":"אריה ליב","k":"יהודה קלאצס","dt":"תקנג - כד אייר","dp":"וילנא","b":"גביר מחכמי וילנא. נקבר לצד ר דוד קענדעס. חתנו - הגביר ר שמואל בן חיים קלצקי."},{"i":22253,"n":"יהודה מוילנא","f":"יוסף בן אליהו פעסעלע","dt":"תקסה-ט - ז אדר","dp":"וילנא","b":"נפטר בחיי אביו."},{"i":22254,"n":"יהודה מוילנא","f":"בנימין","b":"רב בוילנא, חתם-תפד עם ר צמח בן יעקב, ר משה בן יהודה ליב, ר שמריה בן יוסף א\"ש."},{"i":22255,"n":"יהודה מוילנא","f":"בנימין","b":"דיין בוילנא, חתם-תץ עם ר יהודה מטיקטין."},{"i":22256,"n":"יהודה מוילנא","f":"זלמן","b":"דיין בוילנא, חתם-תקח עם הראב\"ד ר יהושע השל."},{"i":22257,"n":"יהודה מוילנא","f":"אליעזר ליפמן","dt":"תקמח","dp":"וילנא","b":"מחכמי וילנא. נפטר ללא ילדים."},{"i":22258,"n":"יהודה מוילנא","f":"גבריאל","b":"דיין בוילנא-תקכג עד תקמג."},{"i":22259,"n":"יהודה מזולקוא","f":"ישראל הקדוש","dt":"שצב","dp":"זולקוא","b":"מחכמי זולקוא."},{"i":22260,"n":"יהודה מטולדו - ב","f":"אשר-נכד הרא\"ש","k":"בעל חקות שמים","dt":"קנא","b":"מרביץ תורה בטולדו בסיכון נפש. נהרג עק\"ה. נזכר בספר יוחסין לר אברהם זכות, התכתב עם הריב\"ש."},{"i":22261,"n":"יהודה מטרוויש","f":"אליעזר","k":"בעל מנחת יהודה","b":"תלמיד ר אליקים בן מנחם. מחכמי צרפת בטרוייש-שנת קעג. חיבר פירוש על רש\"י בשם \"מנחת יהודה\" ונדפס בשם \"דעת זקנים\"."},{"i":22262,"n":"יהודה מטרוויש","f":"נתן","k":"ריב\"ן","dt":"ד'תתסה","b":"חתן רש\"י. מבעלי התוספות בטריוש. בנו - ר יום טוב בעל התוספות."},{"i":22263,"n":"יהודה מיזלוביץ ולבוב","f":"ר\"י","b":"מראשי קהלת לבוב, חתם-תסא בפנקס זולקוא על תקנות קהלת זולקוא יחד עם ראשי ודייני קהלת לבוב. חתם-תנה עם ר פנחס משה, ר חיים מאך מצוזמיר, ועוד. אולי בנו - ר יצחק יאזליוויץ שהתווכח עם כת הפרנקיסטים."},{"i":22264,"n":"יהודה מירושלים","k":"יהודה מקורביל הספרדי","b":"דיין בירושלים-רפ\"ב"},{"i":22265,"n":"יהודה מירקאדו מניש","f":"משה עלי","k":"בעל קמח סולת","bp":"נישי-יון או שלוניקי","dp":"ירושלים","b":"מו\"צ במונסטיר, חזן ורב בניש-תקס בערך ור רחמים אברהם וינטורה על מקומו אחריו, בסוף ימיו עלה לירושלים. חיבר \"קמח סולת\". חתנו - יזרעאל אלקלעי שנהרג בדרכו."},{"i":22266,"n":"יהודה מלבוב","f":"שמעון","dt":"שצז - ז ניסן","dp":"לבוב","b":"מרביץ תורה, ראב\"ד בלבוב."},{"i":22267,"n":"יהודה מלבוב","f":"שמעיה","dt":"שצז - ז ניסן","dp":"לבוב","b":"ראב\"ד בלבוב."},{"i":22268,"n":"יהודה מלמד מפרשבורג","k":"בעל אומר מיהודה","b":"מלמד מחכמי פרשבורג-תקסז, בקי ב-12 שפות, שליח קהלת פרשבורג אל נפוליאון-תקעז, לאפשר לחיילים היהודים להתפלל ביוה\"כ בעיר. חיבר \"אומר מיהודה\" - ברינו תקן. חתנו - ר גומפרכט א\"ש מפרשבורג."},{"i":22269,"n":"יהודה ממגדור","f":"מנואל","b":"רב במגדור-תר\"ע"},{"i":22270,"n":"יהודה ממגנצא","f":"יצחק","b":"מגדולי חכמי מגנצא-ד'תת\"ס"},{"i":22271,"n":"יהודה ממגנצא","f":"קלונימוס","k":"הריב\"ק ממגנצא","dt":"ד'תתקכט","b":"פייטן מגדולי חכמי אשכנז-שנות ה-ד'תתק, מופיע בתוספות, רב במגנצא. נשא ונתן עם גדולי דורו ובהם: ר יקיר, ר יהודה בן משה מרומא, ר יצחק הלבן, ועוד. בנו - ר אלעזר מגרמיזא. חיבר פיוט \"תפלה ליחיד\", קינה על גזירות כט אדר."},{"i":22272,"n":"יהודה ממגנצא","b":"מגדולי חכמי מגנצא-ד'תתקצ\"ה"},{"i":22273,"n":"יהודה ממוסול וזאכו","f":"פנחס","bt":"שע","bp":"זאכו(כורדיסטאן)","dt":"תכ","b":"מקובל,דרשן,תלמיד ר' שמואל ברזני במוסל,רב ואב\"ד בזאכו,לא איפשר לפתוח חנויות בשבת"},{"i":22274,"n":"יהודה ממינצבורג","f":"משלם","b":"מגדולי הראשונים,מרביץ תורה במינצבורג"},{"i":22275,"n":"יהודה ממצרים","f":"יצחק מסעוד","k":"מתרגם ספר הזהר","bp":"דמשק","dp":"ירושלים","b":"מחכמי מצרים, בשנת שמד חתום על תשובה לקהילת רודוס. בשנת שמט עלה לירושלים, ולאחר מכן לצפת ולדמשק לעמדו בראש עדת הסיציליאנים. תרגם ספר הזהר"},{"i":22276,"n":"יהודה ממצרים","f":"טוביה","b":"מחכמי מצרים,דיין בבית דינו של הרמב\"ם"},{"i":22277,"n":"יהודה ממרוקו","f":"ישמעאל","b":"מחכמי מרוקו הקדומים,רב במראקש"},{"i":22278,"n":"יהודה מנחם ממצרים","b":"מחכמי מצרים-רפ - מקהלת המערבים, בזמן הרדב\"ז."},{"i":22279,"n":"יהודה מנחם מפדובה","f":"יקותיאל הכהן","b":"רב בפדובה - נזכר בספר זכרון נשמות גאוני פדובה."},{"i":22280,"n":"יהודה מנחם מפעצעל","b":"רב בפעצעל-תק\"ס"},{"i":22281,"n":"יהודה מסלונים","f":"משה יצחק","b":"שו\"ב בסלונים, חתם-תרסד על כרוז לטובת כולל רייסין בירושלים, עם ר אלחנן נתנאל ז\"ק מסלונים."},{"i":22282,"n":"יהודה מסלונים ווילנא","b":"רב בסלונים, וילנא. נזכר ב\"נשמת אדם\"."},{"i":22283,"n":"יהודה מסמבור","f":"משה מדרגגיטשין","dt":"תקסט - ו אייר","b":"רב בסאמבור"},{"i":22284,"n":"יהודה מסעוד מטיריא","b":"רב בטיריא-תטז-תכו. דיין אצלו - ר ישראל בן חיים בנבנישתי."},{"i":22285,"n":"יהודה מספרד","f":"סעדיה","b":"מחכמי ספרד חיבר פירוש לספר איוב"},{"i":22286,"n":"יהודה מספרד","f":"שלמה","b":"מחכמי ספרד,רופא,מתרגם,חיבר פירושים לתנ\"ך,כתב ספר על רפואה"},{"i":22287,"n":"יהודה מספרד","f":"קרשף","b":"תלמיד וחתן הרא\"ש. מחכמי ספרד."},{"i":22288,"n":"יהודה מעדנבורג","b":"רב בעדנבורג-ר\"י"},{"i":22289,"n":"יהודה מעיר חדש","f":"מאיר מדרזניץ","dt":"תקכה - כז שבט","b":"דיין בעיר חדש בזמן ר משה המבורגר. (ראה גם: דרזניץ, יהודה)"},{"i":22290,"n":"יהודה מעכו","f":"יוסף","b":"מחכמי עכו, בשנת ד תתקצד (1234) חתם על הסכמה לתקנת ר אברהם בן הרמבם."},{"i":22291,"n":"יהודה מפאנו ופדובה","b":"מגדולי חכמי איטליה-שנת ש'. רב בפאנו, פדובה. מסופר עליו ב\"מקוה ישראל\", ו\"זכרון נשמות מגאוני פדובה\". בנו ר משה על מקומו אחריו בפדובה (והיה רב גם לאשכנזים וגם לשאר קהלות)."},{"i":22292,"n":"יהודה מפלאצק","bp":"פלאצק","b":"תלמיד ר גרשון תנחום ממינסק."},{"i":22293,"n":"יהודה מפפד\"מ","f":"יצחק","b":"מחכמי פפד\"מ. חיבר מבוא ל\"הלכות גדולות\"-שח."},{"i":22294,"n":"יהודה מפרובאנס","f":"נתנאל","b":"מחכמי בוקאירי-פרובאנס-שנות ה-ד'תתק, משורר, נזכר אצל אלחריזי. מבניו: ר שמואל, ר יצחק השנירי הפייטן."},{"i":22295,"n":"יהודה מפרובינצה","f":"ברכיה","k":"בעל שיטת ריבב","b":"מגדולי הראשונים,מחכמי פרובינצה-ד'תתק\"צ"},{"i":22296,"n":"יהודה מפרובנס וספרד","f":"יקר","k":"בעל מעין גנים","bp":"נרבונא","b":"עבר מפרובאנס לברצלונה-ד'תתקל\"ג, רבו של הרמב\"ן, חיבר \"מעין גנים\" וכן פירוש על הירושלמי."},{"i":22297,"n":"יהודה מפריס - א","f":"יום טוב","b":"מגדולי בעלי התוספות-ד'תת\"ק. קרובו של הרשב\"ם."},{"i":22298,"n":"יהודה מפריס - ב","f":"יום טוב","b":"מגדולי חכמי צרפת-שנת ל', חתם עם הר\"ש משאנץ."},{"i":22299,"n":"יהודה מפרשבורג המכונה ליברמאן","f":"שלמה","b":"רב בפרשבורג-רמד, וחתם על זכרון עדות. כנראה נכדו של ר יהודה מפרשבורג - נינו של הראב\"ן."},{"i":22300,"n":"יהודה מפרשבורג המכונה ליברמן","f":"מרדכי בן שלמה מברונא","b":"מצאצאי הראב\"ן. רב בפרשבורג-ה'יב. מראשוני הרבנים הידועים לנו מפרשבורג."},{"i":22301,"n":"יהודה מצרפת","f":"שלמה נטע","b":"חיבר ספר על דעות הפלוסופים - בכת\"י (אצל די רוסי)."},{"i":22302,"n":"יהודה מקאליש","b":"רב בעלקיש-תכ\"ד,קאליש-תמ\"א"},{"i":22303,"n":"יהודה מקאליש","f":"ניסן","k":"בעל בית יהודה","b":"רב בקאליש-תך. חתנו - ר צבי הירש לנדא מאפטא (כך לפי בובר-זולקוא)."},{"i":22304,"n":"יהודה מקורביל","dt":"ד'תתקנ","b":"עק\"ה,מגדולי בעלי התוספות,מרביץ תורה בקורביל"},{"i":22305,"n":"יהודה מקורביל וירושלים","b":"נזכר במכתב הנוסע האלמוני כאחד חכמי ירושלים משנת רפב, שו\"ת ממנו במכון כתבי יד. עסק במסחר והיה שלחני."},{"i":22306,"n":"יהודה מקושטא","f":"שמשון","b":"דיין ביה\"ד האשכנזי בקושטא-תטו."},{"i":22307,"n":"יהודה מקושטא","f":"נתן ירוחם","b":"מחכמי קושטא - בשנים תק-תקן."},{"i":22308,"n":"יהודה מקושטא ואדרינופול","f":"משלם","b":"מחכמי אדרינופול וקושטא, נשלח-תכז אל נתן העזתי שרצה להגיע לאדרינופול עם הרופא דוד קוריאל ור יהודה בן משולם."},{"i":22309,"n":"יהודה מקידאן","b":"גביר מחכמי קידאן-שנות ה-תק'. חתנו - הגר\"א (בזיוו\"ר)."},{"i":22310,"n":"יהודה מקצלק ומיצט","f":"ליב ממינסק","b":"אב\"ד קלצק, מיצט. אביו של ר יעקב משקלוב בעל \"מורה צדק\". גיסו של בעל \"שאגת אריה\" (בתולדות אנשי השם - מופיע כאחיו של ה\"שאגת אריה\", אצל איזנשטט מופיע - זקנו של ה\"שאגת אריה\")."},{"i":22311,"n":"יהודה מראויטש (נומברג)","b":"חתן ר מאיר פוזנר בעל \"בית מאיר. רב בראויטש(=ריביטש)-תר. בניו - ר חיים ליפשיץ מלוסק ופלוצק, ר יחזקאל נומברג מלוטימורסק ולודז, ר שלמה מקאליש, ר ברוך בנדיט מבלשקי. (בניו נקראו - נומברג, מלבד ר חיים שנקרא ליפשיץ)."},{"i":22312,"n":"יהודה מרמלה","f":"שלה","b":"חבר בית הדין של הגאונים ברמלה בשנת ד תשפו (1026)."},{"i":22313,"n":"יהודה משברשין","b":"רב בשברשין-תכ\"ד"},{"i":22314,"n":"יהודה משה הלוי מליואדיה","b":"מראשי קהלת ליואדיה(=ליבדייא)-יון, חתם-תקפא על אגרת (הקהלה נחרבה זמן קצר אחר כך)"},{"i":22315,"n":"יהודה משה מזולקוא","f":"ברוך","k":"בעל באר היטב","b":"ראב\"ד בזולקוא. חיבר \"באר היטב\" על שו\"ע יו\"ד, ונמצא ברשימת ספרי שטרשון - \"לקוטי שושנים\"."},{"i":22316,"n":"יהודה משויינברט","f":"נתן","b":"מחכמי שויינברט. חתם על תקנה בפפד\"מ-שג בענין המחלוקת עם קהל שוואבן כנציג קהילת שויינברט."},{"i":22317,"n":"יהודה משומאני וירושלים","dt":"תרלח","b":"רב בשומאני,עלה לירושלים"},{"i":22318,"n":"יהודה משטיפי","f":"כרמי","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":22319,"n":"יהודה משינאווי","f":"שמחה מסטרי ולבוב","b":"נכד ר ליב צינץ מפינטשוב בן נפתלי הירץ מוינה. רב בשינאווע(=שינאווי), קאליש. בנו - ר צבי הירש מראקוב, חתנו - ר יהודה ליב ליפשיץ."},{"i":22320,"n":"יהודה משלוניקי","f":"שמואל","b":"דיין בשלוניקי-שמג."},{"i":22321,"n":"יהודה משלוניקי","f":"שמואל","b":"דיין בשלוניקי, פסק ממנו-תקנו ב\"באר החיים\" לר יעקב מנשה."},{"i":22322,"n":"יהודה משפירא","f":"קלונימוס","k":"ריב\"ק-בעל יחוסי תנאי","b":"מגדולי חכמי אשכנז, מרביץ תורה בשפייר-ד'תתקנ. חיבר \"יחוסי תנאים ואמוראים\" ונדפס בחלקו בתוך \"סיני\" - ירושלים תרצז. אחיו: ר דוד ממינצבורג, ור מאיר - ונקראו שלשתם \"רבני שפירא\" בשו\"ת מהר\"ם. מכונה ריב\"ק הבחור (משום שהיה ר יהודה בן קלונימוס ממגנצא - המבוגר ממנו). מתלמידיו - ר אלעזר מגרמיזא. חיבר פיוט."},{"i":22323,"n":"יהודה משצוצין","b":"מרביץ תורה בבאלטא ושצוצין-תר\"ע"},{"i":22324,"n":"יהודה נתן משלוניקי","b":"מחכמי שלוניקי. חיבר פירוש על איכה, ועוד - בכת\"י."},{"i":22325,"n":"יהודה פוליישי משלוניקי","f":"משה מטרינקי","dt":"רעה - יט ניסן","dp":"שלוניקי","b":"ממגורשי אפולייא-איטליה בשלוניקי."},{"i":22326,"n":"יהודה צבי מוירבינקא","k":"אדמור מוירבינקא","b":"מגדולי תלמידי ר צבי הירש מזידיטשוב. אדמור בוירבינקא-תקצח."},{"i":22327,"n":"יהודה צבי מזולקוא","b":"מחכמי זולקוא, חתם-תפד עם ראשי הקהלה."},{"i":22328,"n":"יהודה צבי מסקאל","b":"רב בסקאלה-תר\"כ"},{"i":22329,"n":"יהודה ציון משלוניקי","dt":"תקפח - טו ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי, נספד מאת ר יהודה ציון."},{"i":22330,"n":"יהודה ר\"ו מוילנא","f":"יעקב","dt":"תקסג - טו ניסן","dp":"וילנא","b":"מחכמי וילנא."},{"i":22331,"n":"יהודה שאראש-פאטאק","b":"תלמיד החת\"ס. רבי בשאראש-פאטאק-תקצז."},{"i":22332,"n":"יהודה שלום מרי שוכרי אל כחיל-א","bp":"בית רדם-ליד צנעא","b":"משיח שקר בתימן-תריט, יצאו נגדו חכמי צנעא ובראשם ר סלימאן בן סלימאן. נהרג ע\"י מלך תימן. לאחר כמה שנים-תרכז קם אדם שכינה שטען שהוא מרי שוכרי שקם לתחיה,"},{"i":22333,"n":"יהודה שלום מרי שוכרי אל כחיל-ב","dt":"תרלח","dp":"צנעא?","b":"משיח שקר בתימן-תרכז, לאחר שמשיח השקר באותו השם הוצא להורג, קם אדם שטען שהוא אותו מרי שוכרי שקם לתחיה, התכתב עם רבני ארץ ישראל שדחו את דבריו ומאז עזבוהו מאמיניו בתימן."},{"i":22334,"n":"יהודה תנחום מוילנא","f":"משה","b":"דיין בוילנא, חתם-תכד עם ר יצחק מפוזנא."},{"i":22335,"n":"יהודה, בנימין יחזקאל מירושלים","f":"שלמה יחזקאל","bt":"תרד","bp":"בגדד","dt":"תרעב - ג תמוז","dp":"ירושלים","b":"עלה בילדותו לירושלים, חתן ר אליעזר ברגמן מירושלים. גביר מחכמי ירושלים. התישב עם גיסו יהושע ילין בכפר מוצא שליד ירושלים, מנהל ישיבת \"חסד אל\", יסד ביכ\"נ חב\"ד בעזרת קרובו אליהו דוד ששון מבומבי. בניו: יצחק יחזקאל יהודה, הפרופ' אברהם שלום יהודה."},{"i":22336,"n":"יהודה, יחזקאל מכלכתא-הודו","f":"ראובן","b":"גביר בבגדד, עבר לכלכתא-הודו-תק בערך ויסד שם בתי כנסיות. וכן תרם לבנית ביכ|נ החורבה בירושלים."},{"i":22337,"n":"יהודה, יעקב צבי יחזקאל","f":"שמעון בן יחזקאל יהוד","bt":"תרלד","bp":"ירושלים","b":"מלמד בביה\"ס כי\"ח. משכיל, מורה באלכסנדריה, מתרגם בבית המשפט בירושלים. חיבר מילון משפטי - בכת\"י, ועוד."},{"i":22338,"n":"יהודה, יצחק יחזקאל מירושלים","f":"בנימין יחזקאל","k":"בעל ספר משלים","bt":"תרכד","bp":"ירושלים","b":"חתן ר שמעון אגסי. חוקר מחכמי ירושלים, אחיו של הפרופ' אברהם שלום. פעיל בועד העדה הבבלית בירושלים. פרסם מאמרים רבים ובהם במאסף \"ירושלים\" - ירושלים תרמב-תרעט."},{"i":22339,"n":"יהודה, פרג' חיים מבגדד ירושלים","f":"שלמה יחזקאל","k":"בעל ותתפלל חנה","bt":"תרו-ח","bp":"בגדד","dt":"תרנו - יז תשרי","dp":"בגדד","b":"מחכמי בגדד, עלה לירושלים והקים-תרסה יחד עם אחיו ר בנימין - עדה נפרדת לעולי בבל בירושלים - ועמדו בראש העדה. בשליחות בהודו-תרמב לאסוף כסף להקמת שכונת \"שמעון הצדיק\". הדפיס \"ותתפלל חנה\" ירושלים תרמט, ועוד. השתתף בהודו בחיבור \"יערת הדבש\" לר יחזקאל יעקב רחמים. חיבר גם \"מסכת אהל מועד\" ועוד. נפטר בדרכו חזרה מהודו."},{"i":22340,"n":"יהודה, שאול מירושלים","f":"שלמה יחזקאל","dt":"תרכד - כד שבט","dp":"ירושלים","b":"מחכמי ירושלים ומבוניה, ממיסדי הישוב החקלאי בקולוניא - מוצא - לפני תרך-תרכב."},{"i":22341,"n":"יהודה, שלמה יחזקאל מבגדד","f":"יחזקאל","bt":"תקעח","bp":"בגדד","dt":"תרלב - כב תשרי","dp":"ירושלים","b":"גביר מחכמי בגדד. חתן ר פרג' חיים עבדאלה יוסף. עלה לירושלים-תרטז, ירש מאביו רכוש בעיר כלכותא-הודו, הקים בכספו ישיבה בירושלים \"חסד אל\" וכיהן בראשה, וכן הקים ישיבת \"כנסת ישראל\" בראשות ר יצחק פרג. בניו ר שאול, ר פרג', ור בנימין, חתניו: ר יהושע ציון הלוי, ר יהושע ילין המזכירו בספרו \"זכרונות לבן ירושלים\". גיסו - הגביר דוד ששון מהודו."},{"i":22342,"n":"יהודה, שמעון מבגדד","f":"שלמה יחזקאל","k":"בעל גן שלמה","bt":"תריד-תרטו","bp":"בגדד","b":"עלה בילדותו לירושלים. תלמיד ר אליעזר בן טובו הלוי, ובישיבות \"חסד אל\" ו\"כנסת יחזקאל\". ראש ישיבת \"חסד אל\" בירושלים. חיבר גם \"כסא שלמה\" ועוד."},{"i":22343,"n":"יהונתן","f":"יהודה ליב","b":"רב-שנת ת\"צ"},{"i":22344,"n":"יהונתן (יוניסן) מרידיק","b":"רב ברידיק לפני תרעד."},{"i":22345,"n":"יהונתן בעל התוספות","f":"יצחק","b":"מחכמי אשכנז-שנות ה-ד'תתק, כנראה מובא בתוספות לעבודה זרה, ובמרדכי. אולי הוא אחיו של ר יוסף בן יוסף יצחק מוירצבורג. אולי הוא מחבר הפיוט \"יום שבת קדש הוא\"."},{"i":22346,"n":"יהונתן הכהן מלוניל","f":"דוד הכהן","k":"בעל פירוש על הריף","bt":"1140","dt":"אחרי ד'תתקעא","b":"ראש חכמי לוניל-ד'תתקנ\"ט. תלמיד הראב\"ד בעל ההשגות, היה בקשרי מכתבים עם הרמב\"ם ובהשתדלותו תורגמו מורה נבוכים ופירוש המשניות מערבית. חיבר פירוש על הריף ונדפס על חולין בשם \"עבודת הלויים\" פפדמ תרלא. עלה לא\"י בראש 300 רבנים מצרפת ומאנגליה-ד'תתקעא(1211). חיבר פירוש על הרי\"ף.","bk":[["רבינו יהונתן מלוניל","מפרשי רי\"ף"],["ר\"י מלוניל [עהש\"ס - על הרי\"ף]",""]]},{"i":22347,"n":"יהונתן מאויבן","k":"בעל קסת יהונתן","b":"ראב\"ד באויבן-ת\"מ"},{"i":22348,"n":"יהונתן מדראבנין","b":"רב בדראבנין"},{"i":22349,"n":"יהונתן מרוז'נוי-ליטא","f":"יוסף","k":"בעל ישועה בישראל","b":"מצאצאי ר יעקב בן שמואל קופלמן. מתמטיקאי ותוכן גדול ברוז'נוי-תע ולמרות עיוורנו יצא לגרמניה שם פגש את הביבליוגרף יוהאן כריסטוף וולף. חיבר \"ישועה בישראל\" - על הלכות קדוש החדש לרמב\"ם, ו\"משיבת נפש\" - פירוש ל\"צורת הארץ\" בכת\"י. הדיין ר יהודה ליב מפרנקפורט הציע לו להוציא לאור את \"צורת הארץ\" לר אברהם בן חייא הפסרדי ובכתב היד שמסר לו מצא כתב יד בשם \"ספר אשפירה\" ליוהן די סקרובוסקו בשתי גרסאות ואחת מהם ערוכה בידי הפילוסוף שלמה בן אברהם אביגדור."},{"i":22350,"n":"יהונתן משה דב הלוי וואלינער","f":"אפרים","bt":"תקס - בערך","bp":"סטנוב-פלך וואלין","dt":"תרה","b":"התאלמן בגיל צעיר, ואח\"כ תלמיד בישיבת וולוזין אצל ר חיים שהעריכו מאוד. בזיוו\"ש חתן ר שמואל באקשטר מלובטש-מחוז נוברדוק (חותנו התיעץ עם ר יצחק מוולוזין בענין השידוך וענה לו שרוצה לקיים \"את בתי נתתי לאיש - ולא למלאך\"). רב בלובטש - אך פרש לאחר זמן קצר. נפטר ללא ילדים. גיסו - ר אברהם דב מרגליות מרדישקוביץ. חיבר \"מרגניתא טבא\" ונדפס עם \"אהבת חסד\" לחפץ חיים שכנראה הכירו וכתב עליו בפתיחה. עליו גם ב\"עץ חיים\"-תולדות ישיבת וולוזין. מתלמידיו: ר דב בר יפה מפלונגיאן, ר אליהו חיים מייזל מלודז, ר אליעזר באקשטנסקי מפינסק, ר יעקב משה דירקטור מסטולוביטש ומוש."},{"i":22351,"n":"יהושע אברהם יהודה מאזמיר","f":"חיים אליעזר יהודה","k":"בעל עבודת משא","dt":"תרט - ח טבת","dp":"ירושלים","b":"רב באזמיר, עלה לירושלים, חיבר \"עבודת משא\" שלוניקי תרו. בנו - ר חייא - נפטר זמן קצר לפניו."},{"i":22352,"n":"יהושע אליהו הכהן מנריוב","b":"רב בנריוב-תרמג."},{"i":22353,"n":"יהושע בן נון","dt":"כו ניסן"},{"i":22354,"n":"יהושע בנימין מפיעסק","b":"חתן ר דוד גרינברג מקוברין. רב בפיעסק-תרע."},{"i":22355,"n":"יהושע הכהן מטשאווס","f":"עקיבא הכהן","b":"רב בטשאווס-תק\"צ"},{"i":22356,"n":"יהושע הכהן מירושלים","dt":"תקנו - י טבת","dp":"ירושלים","b":"מחכמי האשכנזים בירושלים."},{"i":22357,"n":"יהושע הכהן מניישטט","b":"רב בניישטט."},{"i":22358,"n":"יהושע הלוי מדוברומיל","f":"שמואל הלוי","b":"רב בדוברומיל-תע\"ג,טשכנווצה-תפ\"ח,סימיאטיטש-תצ\"ב,נאמן דד\"א"},{"i":22359,"n":"יהושע הלוי מוארשא","f":"יחזקאל הלוי","dt":"תרמה - ב שבט","b":"מגדולי חכמי וורשה"},{"i":22360,"n":"יהושע הלוי מונציה","f":"דוד","b":"רב ומשורר בונציה. הספד ממנו ב\"כוס תנחומין\" על ר שמואל אבוהב ור משה זכות ור משה לוי מוייא."},{"i":22361,"n":"יהושע הלוי מחודרוב","b":"אב\"ד חודרוב."},{"i":22362,"n":"יהושע הלוי מלודמיר","f":"משה מלודמיר","b":"נכד ר שלמה מקרלין. אחיו של ר שלמה מלודמיר. חתן ר מנחם מאניש מרגליות. בנו ר יוסף - חתן ר נח נפתלי מקוברין."},{"i":22363,"n":"יהושע הנגיד","f":"אברהם הנגיד","b":"דור חמישי לרמב\"ם, נגיד במצרים על מקום אביו. בנו - ר דוד מימון הנגיד מדמשק."},{"i":22364,"n":"יהושע הניך מברוד","f":"מנחם מנדל","b":"רב בברודי-תקמח - הסכים על \"אהל רחל\"."},{"i":22365,"n":"יהושע הפייטן","b":"פייטן בארץ ישראל בתקופת הגאונים, מוזכר אצל ר סעדיה גאון עם ראשוני הפייטנים."},{"i":22366,"n":"יהושע הרופא מבגדד","f":"נון","k":"הרבן מסעלייקיא","b":"רופא מחכמי בגדד אצל הכליף הרון אל רשיד-שנות ה-ד'ת'. מתלמידיו ברפואה: יחיא בן מאסוויא-יעאן מאשוע, יוסף יעקב בן איסאק קענדי. תרגם ספרים ברפואה מיונית לערבית."},{"i":22367,"n":"יהושע השל","f":"אליהו זאב","k":"בעל מעיני יהושע","b":"רב-שנת ת\"ר"},{"i":22368,"n":"יהושע השל","f":"ישראל מליטשיניץ","b":"שנת תר\"מ"},{"i":22369,"n":"יהושע השל","f":"יעקב מסוכטשוב וסוקול"},{"i":22370,"n":"יהושע השל אייזינקאפ","f":"ברוך אליאשזון","k":"השל אייזינקאפ","bt":"תקנט","bp":"יאנובה","dt":"תרלד - כה אדר","dp":"סייני","b":"חתן ר מרדכי רבינזון מוילנא. רב זאזמיר, וילקי, שוינצאן, סייני."},{"i":22371,"n":"יהושע השל הכהן מלודמיר","f":"אברהם","b":"רב בלודמיר-תקכ. קיבל הצעה לרבנות לודמיר על מקום אביו אך לא הסתייע."},{"i":22372,"n":"יהושע השל הלוי מקידאן","f":"אליקום גצל מקידאן","dt":"תפ - בערך","dp":"קידאן","b":"רב בקידאן על מקום אביו, ור פנחס בעל \"אבן הראשה\" על מקומו אחריו."},{"i":22373,"n":"יהושע השל הלוי מקרמניץ","dt":"ת - ו כסלו","b":"רב בקרמניץ"},{"i":22374,"n":"יהושע השל מאלפין","b":"רב באלפין-תרמב."},{"i":22375,"n":"יהושע השל מאפטא","f":"מאיר מקרמניץ","k":"בעל מצמיח ישועה","b":"רב באפטא-תקכ. חיבר גם \"ישועות יעקב\" נאוידואהר תקמב. נכדו - ר יהושע השל ממינסק בעל \"מצמיח ישועה\" (את הספר חיבר הוא או נכדו?)"},{"i":22376,"n":"יהושע השל מבאר","dt":"תקא - ד שבט","b":"רב בבאר"},{"i":22377,"n":"יהושע השל מברוד","f":"אפרים זלמן מזאמוש","k":"ר' יהושע העשל מברוד","b":"רב בברוד-ת\"ק"},{"i":22378,"n":"יהושע השל מדינוב","f":"אריה ליב האופה מברטש","dt":"תקעד - כג אייר","b":"תלמיד ר זושא מאניפולי, ר לוי יצחק מברדיטשוב, ר משה יהודה ליב מסאסוב ועוד. רב בדינוב-תקן. מתלמידיו ר צבי אלימלך מדינוב. תולדותיו ב\"נפלאות הרבי ר יהושיע\"."},{"i":22379,"n":"יהושע השל מוילנא","f":"שאול מבריסק וקראקא","dt":"תקט - כו אלול","dp":"וילנא","b":"מצאצאי מהר\"ם פדובה וממשפחת קצנלנבוגן. נכד ר יהושע השל מקראקא. חתן ר צבי הירש בן בנימין מירלש פרנקל מוילנא וגיסו של ר דוד פרנקל בעל \"קרבן העדה\". מגדולי חכמי דורו, רב בווילון, ברסלוי-תעג, וילנא-תפג על מקום ר ברוך רפפורט. אחיו ר אריה ליב - אב\"ד אמשטרדם. מתורתו ב\"מקום שמואל\". בזמן שהיה בוילנא היה מחלוקת כנגדו אך הוא נהנה מתמיכת המלך אוגוסט השני שציוה לציית לו. מכתב אליו מר יקותיאל הרופא מפדובה-תלמיד הרמח\"ל ובו סיפר לו אודות הרמח\"ל. מקורב לחכם הקראי ר שלמה בן אהרן בעל ספר \"אפריון\" שהזכיר בספרו חידה שחד לו ר יהושע השל. הסכים-תצו על \"גאון צבי\" לר צבי הירש הורביץ."},{"i":22380,"n":"יהושע השל מחאלוב","k":"בעל נחלת יהושע","dt":"תקסו - ח סיון","b":"רב בחאלוב"},{"i":22381,"n":"יהושע השל מיאנובה","b":"רב ביאנובה-תר\"כ,ממתנגדי שיטת המוסר"},{"i":22382,"n":"יהושע השל מלבוב","f":"צבי הירש בן זכריה","b":"מראשי קהלת לבוב יחד עם אביו, הסכים עם אביו על תנ\"ך אמשטרדם בועד לובלין-תלח."},{"i":22383,"n":"יהושע השל מלובלין","f":"שלמה מקורב","dt":"תקפז - י טבת","dp":"לובלין","b":"מחכמי לובלין. בן אב\"ד קורב, נכד-אבי אמו ר יהושע השל מקראקא."},{"i":22384,"n":"יהושע השל מלובלין","f":"מאיר ר איסר ר אבלש","dt":"תקפד","dp":"לובלין","b":"מחכמי לובלין."},{"i":22385,"n":"יהושע השל ממינסק וצפת","f":"מאיר","k":"בעל מצמיח ישועה","dp":"צפת?","b":"מצאצאי ר צבי הירש מלבוב-אחיו של ר ליב דער הויכער, ונכד(-אבי אמו) ר יהושע השל בן מאיר מאפטא. מחכמי וילנא, מגיד מישרים במינסק ראש ישיבה על מקום ר גרשון חריף (שהתמנה לרב הגליל), רב בביחוב, סמרגון. בספר \"עליות אליהו\" מסופר שפגש את הגר\"א ודיבר עמו בתורה. חיבר \"מצמיח ישועה\" נוידואר תקמה להגן על זקנו בעל \"ישועת יעקב\" מפני המשיגים עליו. עלה לירושלים בשיירה הראשונה של תלמידי הגרא בשנת תקסט. חתם בפנקס צפת אחרי ר סעדיה."},{"i":22386,"n":"יהושע השל מסויאדושץ","f":"איסר","b":"רב בסויאדושץ."},{"i":22387,"n":"יהושע השל מסטושין","b":"רב בסטושין"},{"i":22388,"n":"יהושע השל מפודקמין","b":"הגיע מפודקמין לכהן כאב\"ד סוקוליבקה-תרי."},{"i":22389,"n":"יהושע השל מפייזיר","b":"רב בפייזיר-ת\"ק"},{"i":22390,"n":"יהושע השל מקורטשין","b":"רב בקורטשין-תריד."},{"i":22391,"n":"יהושע השל משוואבך","b":"רב בשוובאך בזמן מחלוקת ר יונתן איבשיץ - ויצא כנגד חרם רבני פולין על מתנגדי ר יונתן ואיים למסור למלך צרפת שאזרחים פולנים מחרימים את אזרחי מיץ-צרפת."},{"i":22392,"n":"יהושע השל משיניבה","b":"רב בשיניבה, זמיגרוד-תקמג."},{"i":22393,"n":"יהושע זליג המגיד מסלונים","bt":"תקפט","bp":"רוז'נוי","dt":"תרסא","b":"מגדולי הדרשנים בליטא, דרשן במינסק-תרלד."},{"i":22394,"n":"יהושע זליג מברוסילוב","f":"יהודה ליב","b":"מו\"צ בברוסילאב"},{"i":22395,"n":"יהושע זליג מהורודץ","dt":"תרסג","b":"רב בהורודץ, וחתן נכדתו-ר יעקב חיים גרינברג על מקומו אחריו."},{"i":22396,"n":"יהושע זליג מלבוב","b":"אב ומו\"צ בלבוב, חתם-תנט על פסק דין, על קיום חזקה-תעח, ועוד."},{"i":22397,"n":"יהושע זליג משטקלישוק","b":"רב בשטקלישאק-פלך וילנא-תרם. חתנו - ר מאיר יצחק גולדברג מויטבסק."},{"i":22398,"n":"יהושע חיים יונה מקזאל (=קסאלי)","b":"דיין המדינה בפיימונטי-תכד. תשובה אליו ב\"דבר שמואל\"."},{"i":22399,"n":"יהושע יאיר ממנטובה","b":"חתם על פסק ר שמואל מארלי."},{"i":22400,"n":"יהושע יהודה (הורביץ) מפודקמין","f":"משה","b":"בנו ר יצחק אליהו הרצפלד מזלוזיץ."},{"i":22401,"n":"יהושע יהודה מפודקמין","f":"משה","b":"רב בפודקמין, צורטקוב. בנו ר ישכר מקלוש הוציא לאור את ספר אביו \"הלולא דפסחא\" למברג תקסד. היה זקנו של ר אליעזר אלימלך הורביץ מדולינא."},{"i":22402,"n":"יהושע יהודה מצורטקוב","f":"משה אשכנזי","b":"רב בטשארטקוב-תק\"צ"},{"i":22403,"n":"יהושע יוסף הכהן מטשמרונק","b":"תלמיד ר מרדכי יוסף מאיזביצא. אב\"ד טשמרונק. דרשה ממנו לשבת תשובה-תשיח בקובץ \"שפתי צדיקים\"."},{"i":22404,"n":"יהושע יוסף הלוי מונציה","f":"דוד","k":"בעל כוס תנחומין","b":"רב בונציה-שנות ה-ת'. חיבר \"כוס תנחומין\" ובו קינה על ר משה לוי מוייא - תסח."},{"i":22405,"n":"יהושע יחזקאל מברסלוי","k":"פיבל ברסלוי","dt":"תקעה - כא כסלו","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":22406,"n":"יהושע יעקב מלומנא","b":"רב בלומנא, דרבהיטור."},{"i":22407,"n":"יהושע יצחק","b":"מקובל-שנת תק\"ע"},{"i":22408,"n":"יהושע כלב מחלב","b":"מחכמי חלב-שנות ה-ת'. ממונה על התרומות לירושלים."},{"i":22409,"n":"יהושע מאוהניב","f":"חיים","b":"גביר באוהניב-תקלה, יצא לחופשי לאחר הלשנה."},{"i":22410,"n":"יהושע מאוסטרובא וסוסנוביץ","f":"שלמה יהודה ליב מלנט'","k":"אדמור מלנטשנא","bt":"תקעט","dt":"תרלג - כח ניסן","dp":"וארשא","b":"חתן ר צבי מנחם מייזלש מצויזמיר. אדמור חסידי לנטשנא בסוסנוביץ, רב ואדמור באוסטרובה. חתנו - ר יעקב יצחק רבינוביץ מביאלה על מקומו אחריו כאדמור. חיבר \"תולדות אדם\".","bk":[["תולדות אדם - תורה ומועדים",""]]},{"i":22411,"n":"יהושע מאלטשטט","dt":"תרמד","b":"רב באלטשטט."},{"i":22412,"n":"יהושע מברוד","f":"צבי","dt":"תקלא - כט אב","b":"מגדולי חכמי ברוד"},{"i":22413,"n":"יהושע מבריסק","f":"יוסף","b":"רב בבריסק-שצד, ואח\"כ אב\"ד בבריסק."},{"i":22414,"n":"יהושע מדינוב","dt":"תקצג - כג אייר","b":"רב בדינוב"},{"i":22415,"n":"יהושע מדיסנא","f":"יצחק איזיק מקרוז","b":"אב\"ד דיסנא. אחיו - ר אליעזר מקרוז, ר עוזר מבלבירשוק."},{"i":22416,"n":"יהושע מוארפלט","b":"רב בוארפלט-תקף, ור בנימין זאב טננבוים על מקומו אחריו."},{"i":22417,"n":"יהושע מוואלטש","b":"רב בוואלטש-תע\"ט"},{"i":22418,"n":"יהושע מוילנא","f":"שלום מוילנא","dp":"וילנא","b":"מחכמי וילנא. נכד ר נחום שמש. מו\"צ בוילנא-תקצא על מקום אביו. נוסח מצבתו בידי אד\"ם הכהן."},{"i":22419,"n":"יהושע מזולקוא","f":"ישכר בער","b":"מחכמי זולקוא, חתם-תם על תקנת הקהלה בענין הכנסת השמשים."},{"i":22420,"n":"יהושע מזימברובה","bp":"בלבירישוק","b":"תלמיד ר חיים מוולוזין. רב בלודוינובה, טיקטין, זימבורבה."},{"i":22421,"n":"יהושע מטאפאלטשין","b":"רב בטאפאלטשיין-ת\"ר"},{"i":22422,"n":"יהושע מטומשוב","f":"יוסף","bt":"תקמה","dt":"תרסו - יט תמוז","b":"חתן ר אריה ליב קנר. רב בטאמשוב(=טומשוב). בנו - אריה ליב מטומשוב."},{"i":22423,"n":"יהושע מירושלים","f":"סעדיה","b":"מחכמי ירושלים, בשנת רסט חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":22424,"n":"יהושע מלובלין","f":"ר\"י מוארשוי","dt":"תקפא - ו שבט","dp":"לובלין","b":"מחכמי לובלין. חתן בן הרב הגאון מלובלין (לא ידוע מי)."},{"i":22425,"n":"יהושע מליביטשוב","b":"רב בליביטשוב-תרנו."},{"i":22426,"n":"יהושע מלינסק","f":"עקיבא","b":"רב בלינסק."},{"i":22427,"n":"יהושע ממגנצא","f":"אבון הגדול","k":"ר' יהושע הגדול","b":"מגדולי חכמי מגנצא-ד'תש\"ס"},{"i":22428,"n":"יהושע ממיקולייב","b":"מקורב לתלמידי הבעשט, תלמיד ר פנחס מקוריץ."},{"i":22429,"n":"יהושע מפרניק","b":"רב בפרניק-ת\"ר"},{"i":22430,"n":"יהושע מקוזניץ","b":"רב בקאזניץ"},{"i":22431,"n":"יהושע מקוסוב","k":"פלאקסאווע (=בעל בכי)","dt":"תקסט","b":"רב בקוסוב. חברו של ר מנחם מנדל מקוסוב. בנו ר יצחק מיגלניצה."},{"i":22432,"n":"יהושע מקושטא","f":"ראובן","k":"בעל קול יהושע","b":"מחכמי קושטא. חיבר \"קול יהושע\" - קושטא תצב. אחיו - ר אברהם בעל \"בית אברהם\"."},{"i":22433,"n":"יהושע מקידאן","f":"יצחק","b":"דיין בקידאן. חתם-תקעד בערך בענין עגונה."},{"i":22434,"n":"יהושע מקראקא","b":"דיין בקרקא-שי\"ט"},{"i":22435,"n":"יהושע מקרסטיר","b":"רב בקרסטור(=קרסטיר)-תק\"ע"},{"i":22436,"n":"יהושע מרוזדול","b":"רב ברוזדול - תשובה אליו במהרש\"ם-תרמא."},{"i":22437,"n":"יהושע מרפיח","f":"עלי","b":"ראש הקהלה היהודית בחצור (אולי רפיח של ימינו) סמוך לזמן מסעי הצלב. חתם על שטר מעשה בית דין בשנת ד תתיב (1052) בשם יהושע החזן בר עלי החבר. מכתב ממנו ל\"נגיד הידוע מבורך\" ובו מתייחס למלחמת הצלבנים."},{"i":22438,"n":"יהושע משה מבגדד וגבעתיים","b":"מחכמי בגדד - שנות ה-תר', תלמיד ר שמעון אגסי. עלה לארץ וכיהן כרבה של גבעתיים."},{"i":22439,"n":"יהושע משה סגל","f":"אליהו","b":"תלמיד הישמח משה - תשובה אליו ב\"השיב משה\"."},{"i":22440,"n":"יהושע משומיאץ","b":"מגדולי חכמי דורו,רב בשומיאץ"},{"i":22441,"n":"יהושע משידלוב","f":"יהודה ליב מראקוב","b":"רב בשידלוב-תע\"ג"},{"i":22442,"n":"יהושע משיניבה","b":"רב בשיניבה - שו\"ב. תשובה אליו ב\"דבר משה\"."},{"i":22443,"n":"יהושע משרבוגרד","dt":"תרט - טו תמוז","b":"רב בשרבוגרד"},{"i":22444,"n":"יהושע משרת משה","bt":"ב' אלפים תו","dt":"ב' אלפים תקטז","bk":[["יהושע",""]]},{"i":22445,"n":"יהושע נחמן","b":"רב בשנת תק."},{"i":22446,"n":"יהושע סגל מלבוב","b":"דיין בלבוב, חתם-תג על פסק דין."},{"i":22447,"n":"יהושע סגל מלבוב","f":"יוסף","b":"מחכמי לבוב, חתם-תקלג בפנקס הקהלה."},{"i":22448,"n":"יהושע עלי מקושטא","b":"דיין בקושטא, ישב בדין-תקעה עם ר חיים אברהם בן שלום ור יעקב הלוי."},{"i":22449,"n":"יהושע פיבל מטרניגרד","f":"ישראל","k":"בעל קצוי ארץ","bp":"טרניגרד","dt":"תקלז - א תמוז","dp":"זולקוא","b":"נכד הקיקיון דיונה?. חתן דודו - ר יצחק מאיר תאומים מזולקוא. רב בטארניגרד, זולקוא. (באוצר הרבנים תאריך פטירתו - תקסז)."},{"i":22450,"n":"יהושע פלק בן יהודה ליב","k":"בעל עמק יהושע","dt":"תס - ה אייר","dp":"לבוב","b":"מגיד בלבוב, מתורתו ב\"שכל טוב\", ב\"אור יקרות\", \"סייעתא דשמיא\", \"פרי הלולים\", ועוד.","bk":[["עמק יהושע",""]]},{"i":22451,"n":"יהושע צבי מהוסקוב","f":"יעקב יונה","b":"רב בהוסקוב-תרמח."},{"i":22452,"n":"יהושע צבי מירושלים","dt":"תקסד - כד אלול","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":22453,"n":"יהושע צבי מקופיטשיניץ","b":"רב בקופיטשיניץ-תרמט."},{"i":22454,"n":"יהושע ציון הלוי ממרוקו וירושלי","f":"אברהם חיים","bt":"תרטז","bp":"פאס-מרוקו","dt":"תרנז - יא טבת","dp":"ירושלים","b":"עלה לירושלים-תרכז והיה מראשי \"בית אל\", וחתום באגרות ותעודות שונות. חיבר פירוש על \"עץ החיים\" - בכת\"י. בנו - ד\"ר אריאל"},{"i":22455,"n":"יהושע שלום מסרייבו","bt":"תרט","dt":"תרפה - יב אב","b":"רב ודיין בשאראיי-בושנא"},{"i":22456,"n":"יהושע שמואל מיאנוב","f":"צבי הירש מטומשוב","b":"חתן ר מנחם זאב ירוזלמסקי. אב\"ד קוצק, יאנוב, לודז."},{"i":22457,"n":"יהושע שמואל שמלקיש","f":"שמואל מפרג","b":"נכבד וקצין מגדולי דורו,מנהיג בפרעמישלא-ש\"ס"},{"i":22458,"n":"יהושע, גבריאל","f":"שבתי","bt":"תרז","bp":"שלוניקי","dt":"תרעא - ו חשון","dp":"ירושלים","b":"יסד בשלוניקי חברת \"חסד ואמת\", עלה לא\"י-תרל\"ז, דיין בירושלים, עסקן ציבור, ממייסדי ביה\"ח \"משגב לדך\""},{"i":22459,"n":"יהלום, צבי הירש הלוי מקידאן","b":"ר\"מ בקידאן-תר בזמן ר בנימין זאב \"ראש הברזל\". בנו - ר יהודה ליב משה סירקין יהלום בעל \"סערות תימן\"."},{"i":22460,"n":"יהלום-סירקין, יהודה ליב משה","f":"צבי הירש יהלום מקידא","k":"בעל סערות תימן","bt":"תקצא","dt":"תרמה - יז תשרי","b":"מכונה ר \"ליבציק חריף\". חתן ר בנימין וולף מקידאן-\"ראש הברזל\". רב בציטוויאן, ריטובה, סעלץ, ויסאקי(=וויסק, ויסוקי). חיבר \"סערות תימן\" - בכת\"י."},{"i":22461,"n":"יהלום-שטיין, בנימין זאב ממאלטש","f":"יהודה משה-סערות תימן","k":"יאהאלימשטין","dt":"תרמה - טז כסלו","dp":"בריסק","b":"רב במאלטש-תרל, עבר לבריסק. נספד ע\"י ר יוסף דב סולוביציק בבריסק."},{"i":22462,"n":"יהלום-שטיין, יוסף זלמן מזשבינק","f":"בנימין וולף ממאלטש","bt":"תרכט","b":"נכד ר יהודה ליב משה מויסאקי בעל \"סערות תימן\". אביו נפטר צעיר וגדל אצל חורגו ר זלמן סנדר כהנא שפירא מקריניק. חתן ר פנחס שיק מקוברין. רב בזאבינקה(=זשאבינקא)-פלך גרודנא-תרנח. נסמך מאת: ר צבי הירש רבינוביץ מקובנא, ר אליהו פינשטין מפרוזין, ר אליהו קלצקי מלובלין."},{"i":22463,"n":"יואב בן ירמיה ממטרסדורף","dt":"ה'תקע 1810","bk":[["אמרי יואב",""],["אמרי נועם",""],["חן טוב זבד טוב",""],["שערי בינה",""],["אמרי נועם (ר' יואב בר' ירמיה)",""]]},{"i":22464,"n":"יואב הפייטן","f":"דניאל","b":"פייטן-שנות ה-ק', סליחה ממנו במחזור רומא \"יודע ועד הוד פניך נחלה\"."},{"i":22465,"n":"יואב הפייטן מרומא","f":"בנימין","b":"פייטן ברומא-ה'מ. חיבר \"יה מלכי מנעה מבכי\"."},{"i":22466,"n":"יואב הפייטן מרומא","f":"נתן בן דניאל","k":"הקטן","b":"פייטן מחכמי רומא-שנות ה-ה'ק. מפיוטיו במחזור רומא."},{"i":22467,"n":"יואב מן הכנסת מרומא","f":"יחיאל","b":"פייטן מחכמי רומא-שנות ה-ק'. פיוטים ממנו במחזור רומא, חיבר רשות ליוה\"כ על יג עיקרים."},{"i":22468,"n":"יואב שאעא (שעאה) מיוון","b":"פייטן ביוון. מפיוטיו במחזור חלב."},{"i":22469,"n":"יואל (סירקיש) מבריסק","f":"יהודה אריה ליב-שאגת","b":"נכד בעל הב\"ח. תלמיד בעל תוי\"ט. מחכמי בריסק-שנת ת'."},{"i":22470,"n":"יואל בעל שם - הראשון","k":"בעל תולדות אדם","b":"נכד ר אליהו בעל שם מחלם. מקובל, איש מופת. רב בלויצק-תן, פינסק, אוסטרהא, לבוב. (ראה גם יואל הלפרין מאוסטרהא)"},{"i":22471,"n":"יואל הכהן מאוסטרהא - כץ","f":"יהודה ליב מאוסטרהא","dt":"תקמט - יא סיון","dp":"אוסטרהא","b":"בן הפרנס ר יהודה ליב בן יוסף מרדכי. חתן ר יואל ממזבוז. פרנס באוסטרהא-תקמב. בנו ר דוד פרנס באוסטרהא."},{"i":22472,"n":"יואל הלוי מבונא","f":"יצחק","b":"חתן הראב\"ן. תלמיד ר יצחק בן אשר-הריב\"א. פייטן, רב בבונא, קולנויא, רגנשבורג. מובא בתוספות. חיבר פיוט \"יבכיון מר מלאכי שלום\". בניו - ר אליעזר הלוי-ראבי\"ה, ר אורי - נשרף עק\"ה-ד'תתקעו."},{"i":22473,"n":"יואל הלוי מלבוב","f":"נתן","b":"דיין ור\"מ בלבוב, נזכר בשו\"ת מהר\"ם מלובלין."},{"i":22474,"n":"יואל הלוי מצפת","f":"יעקב","b":"מחכמי צפת ועמד בראש הקהלה האשכנזית בימי ר יוסף קארו. חתם בשנת שפה על תקנה לשחרור תלמידי חכמים ממס. מוזכר ב\"קורא הדורות\", ואצל ר\"י מטראני, וכן בספר \"חרבות ירושלים\" יחד עם שני אחיו ר יעקב הלוי ור שמואל הלוי."},{"i":22475,"n":"יואל זליג מרייגורד","b":"רב ברייגורד-תר\"מ"},{"i":22476,"n":"יואל חסיד מאמציסלב","k":"בעל חדושי מהריח","dt":"תקד - ב סיון","b":"רב באמציסלב"},{"i":22477,"n":"יואל חריף ממינסק","b":"מחכמי מינסק בזמן ה'גדול ממינסק'."},{"i":22478,"n":"יואל יצחק מסמיאטיץ","dt":"טשכנוב","b":"אב\"ד סמיאטיץ."},{"i":22479,"n":"יואל מאגיפאלו","b":"רב באניפאלו-תק\"ע"},{"i":22480,"n":"יואל מאוסטרהא","f":"נתנאל","dt":"תע - יב אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":22481,"n":"יואל מאוסטרהא","f":"דוד","dt":"תקט - ה תשרי","b":"פרנס באוסטרהא. ומצאצאיו גבאים ופרנסים, ובהם נכדו ששמו גם הוא יואל בן דוד."},{"i":22482,"n":"יואל מאוסטרהא","f":"זאב וולף","k":"יואל הינדילס","dt":"תקסט - א אב","dp":"אוסטרהא","b":"דיין באוסטרהא, מחכמי הקלויז הגדולה ובקי בקבלה מעשית. הסכים על \"עץ חיים\" קורץ תקמב, ועוד. בשריפה הגדולה- א אב תקסט ברחו מאות אנשים אל ביתו שהיה בית אבנים ואולי חשבו שיצילם בכח הקבלה המעשית שבידו - אך האש פגעה בהם ונשרפו כ-500 אנשים, ונקברו בקבר הנקרא \"מקום הנשרפים\"."},{"i":22483,"n":"יואל מאוסטרהא","f":"אשר צבי","b":"מחכמי אוסטרהא. הסכים על \"ילקוט הראובני\" - אוסטרהא תקסו."},{"i":22484,"n":"יואל מאוסטרליץ וברלין","b":"רב באוסטרליץ,דיין בברלין-ת\"ק"},{"i":22485,"n":"יואל מאורלא","f":"יעקב או משה מקופנהגן","b":"רב באורלא(=אורלוב). בנו - ר יעקב מסוכטושב וסוקולוב."},{"i":22486,"n":"יואל מאיטליה וירושלים","b":"מחכמי ירושלים-שפה. אחיו - ר שמואל הרופא, ר יעקב."},{"i":22487,"n":"יואל מבלאדוב - נכד הב\"ח","dt":"תסט - א טבת","dp":"אוסטרהא","b":"רב בבלאדוב(=ולאדאוי), אוסטרהא. היה מנכדי בעל הב\"ח, והחזיק אצלו את הש\"ס שעליו רשם זקנו את הגהותיו לש\"ס, ומשם נדפסו - וארשא תקפד, ואחר כך בכל השסי\"ם הנדפסים."},{"i":22488,"n":"יואל מברודי","b":"רב בברודי-תמ\"א"},{"i":22489,"n":"יואל מבריסק","f":"משה קאזעס","b":"מחכמי בריסק-תקמה."},{"i":22490,"n":"יואל מבריסק","f":"אברהם","b":"אב\"ד בבריסק-תקמו."},{"i":22491,"n":"יואל מויטקוב","b":"רב בויטקוב. חסיד חוליוב. נכדו - ר אליעזר אטינגר מזולקוא."},{"i":22492,"n":"יואל מזולקוא","f":"אברהם","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה, חתם-תעו על תקנה שלא יהיה אחד מקרובי הרב ממנהיגי הקהל. אחיו - ר ישעיה בעל \"באר היטב\"."},{"i":22493,"n":"יואל מטולטשין","b":"מג\"מ בטולטשין"},{"i":22494,"n":"יואל מטרנופול","b":"רב בטרנופול-תרלז - תשובה אליו מהרשם."},{"i":22495,"n":"יואל מטשאפלא","dt":"תקצב","b":"תלמיד ר מנחם מנדל מויבסק, ר שלמה מקרלין, ר מרדכי מלכוביץ ובנור נח. מראשוני החסידים בליטא. האריך ימים. מסופר עליו שזכה ל\"גילוי אליהו\"."},{"i":22496,"n":"יואל מללוב","b":"רב בלעלוב"},{"i":22497,"n":"יואל מנמירוב","dt":"תקמח","b":"תלמיד הבעשט, ואחריו מקורב לר יעקב יוסף מפולנאה. עלה לארץ-תקלה."},{"i":22498,"n":"יואל מסאקאלקא","dt":"זיטיל","b":"אב\"ד סאקאלקא."},{"i":22499,"n":"יואל מסמאליין","f":"משה","b":"חסיד ר אברהם מקאליסק, ועלה עמו לארץ. בשליחות הקהלה-טבריה? בחו\"ל."},{"i":22500,"n":"יואל מפרג","f":"משה גד","k":"בעל חדושי הלכות,הנכד","b":"רב בפרג-תפ."},{"i":22501,"n":"יואל מקמניץ","f":"יוסף בן חיים מקמניץ","b":"רב בקמניץ. בנו - ר שלמה אהרן זליג מיאלובקא וקאדני. אחיו ר צבי הירש מקמניץ."},{"i":22502,"n":"יואל מקראקא","dt":"תשג","b":"מגדולי חכמי קראקא-שנת ש'"},{"i":22503,"n":"יואל משברשין","f":"משה גד","k":"בעל מגיני זהב,הזקן","b":"נכד בעל הט\"ז. רב בשברשין-תמג. חיבר \"מגיני זהב\" להגן על השגות הש\"ך ב\"נקודות הכסף\" על זקנו הט\"ז. בניו - ר משה, ר גד, ספרו נדפס ע\"י נכדו - ר יואל בן גד."},{"i":22504,"n":"יואל משעגלאנקי","f":"מאיר","k":"בעל יתדות אוהלים","b":"אב\"ד שעגלאנקי-פרייסין. חיבר יתדות אוהלים - ברלין תקמח."},{"i":22505,"n":"יואל נפתלי הרץ מוילנא","f":"ישראל שמש קלויז יסוד","dt":"תריח - ב סיון","b":"ר\"מ בישיבת מייליס בוילנא מיום היוסדה-תקצ.., מ\"מ בקלויז יסו\"ד. הניח חדושים על משניות - בכת\"י."},{"i":22506,"n":"יואל פיבוש מאוסטרהא","f":"נפתלי הרץ","dt":"תעו - טז תמוז","dp":"אוסטרהא","b":"רב ומנהיג באוסטרהא. בניו: ר אהרן זליג מאוסטרהא בעל \"עולת אהרן\", ר נפתלי הרץ מאוסטרהא."},{"i":22507,"n":"יואל פיבוש מאוסטרהא","f":"יוסף אפרים מאוסטרהא","b":"חתן ר יוסף עלקשיר. פרנס באוסטרהא-תקכט. בנו צבי שמשון."},{"i":22508,"n":"יואל פיבוש מלבוב","f":"משה","b":"דיין בלבוב, חתם-תנז עם ר ישעיה קצנלנבוגן, ועוד. בנו - ר אהרן זליג בעל \"עולת אהרן\"."},{"i":22509,"n":"יואל צורף מלובלין","f":"משה","dt":"תה - יז שבט","dp":"לובלין","b":"מחכמי לובלין."},{"i":22510,"n":"יואל ש\"ץ מלייפה","k":"בעל רוח ניחוח","b":"חיבר \"רוח ניחוח\"."},{"i":22511,"n":"יואלסון, אברהם אליהו מלוצין","f":"אליהו מפרידריכשטט","b":"רב בלוצין. פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"המאסף\" - ירושלים תרנו, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":22512,"n":"יואלסון, אהרן מאיר מירושלים","f":"ברוך בנדיט","bt":"תקסז","dt":"תרמד - כב חשון","b":"נכד ר אליהו קאליקולר. חתן ר זאב יואלסון מקריצבורג (ומכאן שמו - יואלסון), ובזיוו\"ש חתן ר שמעון מנשה חייקין מחברון. בנו - ר אליהו מפרידריכשטט."},{"i":22513,"n":"יואלסון, אליהו מפרידריכשטט","f":"אהרן מאיר","bt":"תקפו","dt":"תרם - כ אב","b":"נכד ר אליהו קאליקולר. תלמיד ר סנדר מקופישוק. חתן ר יצחק כהנא, גביר תלמיד חכם. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":22514,"n":"יואלסון, אשר מפולדא","f":"יוסף","b":"תרגם ספר תרי עשר ללשון אשכנז - קרלסרוהא תקפז."},{"i":22515,"n":"יואלסון, יחזקאל מאלטונא","f":"יואל","bt":"תקמט","bp":"וילעהן(=פיהלענע)","dt":"תרמה - ח אדר","dp":"אלטונא","b":"תלמיד ר עקיבא איגר, מלמד בת\"ת באלטונא (בהמלצת רבו), דיין-תקצה, ראב\"ד על מקום ר עקיבא ורטהיימר יחד עם ר מאיר הכהן עד למינוי ר יעקב עטלינגר. מתלמידיו: ר ישעיה הולנדר, ר יעקב כץ, ר ליב אדלר, ר עקיבא ורטהיימר. חברם של ר משה מיכאל ליכטנשטין, ור מרדכי מיכאל יפה (למדו ביחד אצל ר עקיבא איגר). מנכדיו: ר יואל רוזנשטוק."},{"i":22516,"n":"יואלסון, יעקב מפפד\"מ","f":"אשר","k":"בעל אלומי יוסף","b":"סופר משכיל ומורה בפפד\"מ. חיבר ספרים בחינוך בלשון אשכנז ובהם \"שרשי הדת\", \"שירי ישורון\", ועוד, תרגם את התורה ללשון אשכנז."},{"i":22517,"n":"יוגנד, אריה ליב מסקאהל","k":"בעל פירוש לשוע","bp":"סקול","dt":"תש..","b":"חתן ר נפתלי מילר מגורליץ. חיבר ספר על שו\"ע - בכתב יד. רב בגורליץ על מקום חותנו. נספה בשואה."},{"i":22518,"n":"יודאסין, אלכסנדר","b":"רב בקריבורג,עלה לא\"י-תרצ\"ד"},{"i":22519,"n":"יודוביץ, מרדכי מנאפראד","dt":"תרעג - בערך","b":"תלמיד הכת\"ס. בעל אחוזה בנאפראד-תרמז. מחותן עם ר שמואל שמעלקא מסעליש ועם ר משה פנט מדעש."},{"i":22520,"n":"יודין, חיים נתן מהלאווטשין","f":"דובער ליב","bt":"תרלב","b":"למד בוילנא, קיבוץ לומדי תורה בואראנאווא, קובנא. חתן ר מנחם מנדל דון יחיא מקפוסט. רב בהולוביצין(=הלאווטשין)-פלך מוהילוב-תרסג. נסמך מאת: ר שלמה הכהן מוילנא, ר צבי הירש רבינוביץ מקובנא, ר משה דנישבסקי מסלובודקה, ר שבתי מדריססא."},{"i":22521,"n":"יודיקא (יהודית ציק)","k":"בעל נייע יוגנט","bt":"1898","bp":"גורז'ד","b":"היגרה עם הוריה ללונדון, וחזרו לגורז'ד, עברה במקומות רבים באירופה בזמן מלחה\"ע ה-I וחזרה לגורז'ד. חיברה שירים באידיש וגרמנית. פרסמה בעתונות היהודית בליטא. חיברה גם \"מענטש אין צייט\" עם מבוא מד\"ר אסתר אלישיב - קובנא 1936."},{"i":22522,"n":"יודל","f":"משה מדראגיטשין","b":"רב-שנת תק\"ע"},{"i":22523,"n":"יודל מטשודנוב","f":"יוסף מוכיח","b":"תלמיד הבעשט. קרובו של ר נחמן מקוסוב. הבעשט אמר עליו כי הוא גלגול שמואל הנביא."},{"i":22524,"n":"יודלביץ, אברהם אהרן מקאפוליא","f":"בנימין בינוש","k":"בעל עלים למבחן","bt":"תרי","bp":"נווארדוק-ליטא","dt":"תרץ - ה שבט","b":"מצאצאי מהר\"ם פאדובה. תלמיד דודו ר מאיר מארים שאפיט מקוברין, ישיבת וולוזין. רב בסעליב-תרלד, קוזניצא, קונסטנטינוב, טוראוו, קאפוליא(=קאפיל)-פלך מינסק, ניו יורק, מנצ'סטר-אנגליה-תרנח, בוסטון-תרסד (או בעיאן=בעיליק-ניו ג'רסי), ר\"מ בישיבת ר יצחק אלחנן בניו יורק ורב שם. נסמך מאת: ר יו\"ט ליפמן בעל \"עונג יו\"ט\". חיבר גם \"בית אב\", \"זהב שבא\", \"דרש אב\", \"תפוחי זהב\", \"אב בחכמה\", \"חיבת אב\", ועוד. פרסם גם בירחון \"מגד ירחים\" - סטמר תרפח, \"אהל מועד\" - איזביצא תרפח. בנו ר חיים רב בעקראן. היה מחלוקת על ספרו \"אב בחכמה\" בעניני חליצה - וחזר בו מדבריו שם. פרסם מאמרים ב\"הלבנון\" - סטמר תרפח\"פרח הלבנון\" - וארשא תרעח, \"המגיד\" - סטמר תרפח. עורך \"המצפה\" - נ\"י תרע. חתניו - ר שלמה שלוסברג מאנגליה. בניו: ר חיים מאיר מאנגליה, ור ירחמיאל מארה\"ב.","bk":[["בית אב [שו\"ת]",""],["אב בחכמה",""],["בית אב חמישאי",""],["בית אב קמא",""],["בית אב שביעאי",""],["בית אב תליתאי",""],["בית אב תנינא",""],["דרש אב",""],["יד ה’",""],["עלים למבחן",""],["תפוחי זהב",""],["אב בחכמה - ובו חמשה פסקים וסימנם חכמה, ח'ליצה, כ'לאים, מ'סית ומדיח, ה'עלם הוראה",""],["בית א\"ב - שו\"ת ובו ד' ספרי שו\"ת א. חיי אברהם - או\"ח. ב. כרם אב - כמה סוגיות בבבלי וירושלמי. ג. דעת אברהם - יו\"ד. ד. עזרת אברהם - אבן העזר",""],["דרש אב - על התורה",""],["יד ה' - אסתר",""],["יד צר - איכה",""]]},{"i":22525,"n":"יודלביץ, חיים מאיר מארים מאנגל","f":"אברהם אהרן מארה\"ב","bt":"תרלו","bp":"סעליב-רוסיה","b":"חתן ר אליהו משה לוין בעל \"יד אליהו\". דרשן, רב במנצסטר-תרנט, סויטהנד-אנגליה. מתורתו בספר אביו \"בית אב\". אחיו - ר ירחמיאל מארה\"ב."},{"i":22526,"n":"יודלביץ, יעקב שמואל","bt":"1883","bp":"פופיליאן","b":"למד הנדסה בגרמניה. היגר לדרום אפריקה, והיה שם מורה לעברית פרסם מאמרים בעתוני התקופה. עורך ה\"נייע היים\", ופעיל בתנועה הציונית בדרום אפריקה."},{"i":22527,"n":"יודלביץ, יצחק מאיר משאוולי","b":"מיסד ישיבה בשאוולי-תרעג, בעזרת הרב \"מטעם\" אהרן הלר משאוולי."},{"i":22528,"n":"יודלביץ, מרדכי דב","f":"שלמה","k":"בעל חיי היהודים","b":"חוקר, היסטוריון. חיבר \"חיי היהודים בזמן התלמוד\", ועוד."},{"i":22529,"n":"יודלביץ, נחום","f":"שלמה","bt":"1862","bp":"סלנט","b":"מצאצאי הרמ\"א, ומצד אמו ממשפחת ר שמואל סלנט. תלמיד ישיבת וולוזין. עסק במסחר והיה מחובבי ציון וציר בקונגרס הציוני. ממיסדי סיעת \"ירושלים\" בקיוב. עלה לארץ-1932 והקים ביח\"ר \"גביש\" לזכוכית. פרסם מאמרים בעתוני התקופה."},{"i":22530,"n":"יודלביץ, שמואל אהרן מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג."},{"i":22531,"n":"יודמן הרופא","f":"וולף ב\"ב","k":"מפפד\"מ","dt":"תקיג - כג אייר","dp":"פפד\"מ","b":"רופא מחכמי פפד\"מ."},{"i":22532,"n":"יודמן, אלעזר חיים משידלובצי","f":"יהודה ליב -מי מנוחות","k":"בעל חיים וחסד","b":"נכד ר יחיאל שכנא בן יהודה ליבוש גניוועשאווער משידלובצי, ונכד(-אבי אמו) ר מרדכי מאטיל מנאוורטשוב. רב בשידלאווצי(=שידלובצי)."},{"i":22533,"n":"יודמן, דוד משידלובצה","b":"פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח."},{"i":22534,"n":"יודן הכהן הפייטן מאיטליה","f":"מסתיה","b":"פייטן מאיטליה או יוון. פיוט ממנו במחזור רומא \"ארבעים יום הם ימי שבר\"."},{"i":22535,"n":"יודעזון, שמואל מטשרניקוב","b":"דיין בוורעשען,ראב\"ד בטשערניקוב-תר\"ז"},{"i":22536,"n":"יודקוביץ, אלכסנדר דן","f":"יעקב דוד","k":"בעל ארח מישור","b":"חיבר ארח מישור - לודז תרצד.","bk":[["ארח מישור","מפתח למאמרי חז\"ל"]]},{"i":22537,"n":"יודקוביץ, יעקב יהודה מגריצא","k":"בעל יד הקטנה","b":"רב בגריצא. חיבר \"יד הקטנה\" וארשא תרסט."},{"i":22538,"n":"יודקובסקי, אליעזר יהושע מסטוטש","f":"עובדיה","k":"אדמור מסטוטשין בנ\"י","b":"נכד ר יהודה האדמור מסטוטשין בנ\"י. אדמור מסטוטשין בנ\"י על מקום זקנו."},{"i":22539,"n":"יודקובסקי, חיים ליב מוארשא","dt":"תרצה - יב אייר","b":"חבר בועד הרבנים בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":22540,"n":"יוהלמן, דוד שלמה","f":"ליב","bt":"1869","bp":"פוסטאב-פלך וילנא","b":"תלמיד ישיבות ליטא. למד באוני' ברן, והצטרף לתנועה הציונית, עבר ללונדון וניהל משרד \"י.ט.א.\", פעל להסדרת הגירה יהודית לגלבסטון שבדרום ארה\"ב. עמד בראש ועד הסיוע מיהודי אנגליה לפליטי מלחה\"ע ה-I. בשליחות ברוסיה ואוקראינה בדבר עזרה ליהודים-1921, השתתף בויעדת \"אוזט\" במוסקבה-1926 ונבחר ליו\"ר הועד לתמיכה בהתישבות היהודית ברוסיה. יו\"ר הועד להוצאת התלמוד באידיש."},{"i":22541,"n":"יוהנס, אליהו מגורליץ","dt":"תש..","b":"נכד ר יצחק חריף. חתן ר חיים יהודה ליבוש המרלינג מלופטין. רב באזיפולי. נספה בשואה."},{"i":22542,"n":"יוהנס, דב בריש","f":"ישכר דב","b":"חן בעל \"מלא הרועים\". חתנו - ר אשר זליג אבי ר\"ש פירר."},{"i":22543,"n":"יוהנס, ישכר דב מיסלו","bt":"תרעח","bp":"יסלו","dt":"תשמה","dp":"ירושלים","b":"מצאצאי ר שאול וואהל. ניצל מהשואה ועלה לארץ. רב ברמת יצחק."},{"i":22544,"n":"יוהנתנזון, אהרן שקודער מוילנא","f":"צבי הירש מוילנא","k":"בעל כלי שיר","bp":"וילנא","dt":"תרכח - ח אב","dp":"יאנובה","b":"מצאצאי ר יונתן איבשיץ ומכאן שמו. תלמיד ישיבת וולוזין. מלמד לבני נכבדים בוילנא. סופר ומשורר. התישב ביאנובה. אחיו של ר יוסף איבשיץ מאמשטרדם."},{"i":22545,"n":"יוזאפ","b":"רב ברוגנסדורף-תק\"צ"},{"i":22546,"n":"יוזאפ"},{"i":22547,"n":"יוזאפס, מיכל מקראקא","k":"בעל סדר גיטין","b":"מגדולי חכמי דורו,דיין בקרקא-ת\"ל"},{"i":22548,"n":"יוזוק, שמעון אריה","b":"דיין בפתח תקוה. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":22549,"n":"יוזיפוביץ, אברהם","f":"רבצ'יק - רבינוביץ","bt":"1448","dt":"1519","b":"בנו של חוכר מקיוב. חוכר ואיש כספים של מלכי פולין וליטא. לפני 1495 היה ממונה עירוני בקובנא, גלה מקובנא בזמן גירוש יהודי קובנא, אך חזר אחרי כמה שנים והתנצר. הנסיך הגדול אלכסנדר מינה אותו ב-1505 למושל של סמולנסק והורודניצי של מינסק. קיבל תואר אציל מהמלך זיגמונד. חכר אחוזות וגבה מכס עבור אצילי פולין וליטא. רכב נכסים רבים והיה מלווה כספים לנסיך הגדול ולמלך. שר האוצר של מדינת ליטא-1509. הגן על עניני היהודים ובהשתדלותו בוטלו תקנות 1514 נגד היהודים. עמד בקשרי מסחר עם אחיו - היהודים - מיכאל ויצחק איזיק. אבי משפחת האצילים הפולנים \"אברמוביץ\"."},{"i":22550,"n":"יוזיפוביץ, מיכאל","dt":"1531","b":"אחיהם של אברהם - שר האוצר של ליטא שהתנצר ויצחק איזיק. חוכר המכס בבריסק, לוצק, גרודנא, וולדימיר. חוכר נכסים במוהילב, ויטבסק, קמניץ. הלווה כספים לאצילים ולמלך. מונה ע\"י המלך זיגמונד ל\"זקן ושופט\" של כל קהילות יהודי ליטא ומייצג היהודים בפני המלך. זכה לתואר \"אציל\"-1525 למרות יהדותו."},{"i":22551,"n":"יוזל מלודמיר","b":"ב\"ברכת טוב\" הביא מחדושיו."},{"i":22552,"n":"יוזפא הלוי","f":"יונה הדיין מהמבורג","k":"מאה\"ו","b":"תלמיד בעל \"כנסת יחזקאל\". הו\"ל חדושי הרשב\"א עם חדושים מרבו."},{"i":22553,"n":"יוזפא שמוקלער מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא."},{"i":22554,"n":"יוזפוב, ברוך בן ציון מדובנא","f":"יחיאל מיכל מקוריץ","k":"אדמור מדובנא","dt":"תרצז - ה ניסן","b":"שם אביו ירושלמיסקי. חתן ר מרדכי משומסק (זלוטשוב). עבר לדובנא-תרנג וכיהן כאדמור."},{"i":22555,"n":"יוזפוב, שמואל ממזבוז-בוטשאן","f":"ברוך בן ציון מדובנא","k":"אדמור ממזבוז","dt":"תשלח - ד טבת","b":"חתן ר משולם זושא השל ממזבוז (אפטא). רב ואדמור במזבוז-תרף על מקום חותנו, עבר ליעדניץ, בוטושאן. ניצל מהשואה, ואחריה עלה לארץ-תשו והתישב בחיפה. חיבר \"בית שמואל\"."},{"i":22556,"n":"יוזפוביץ, אברהם מליטא","f":"ראביי-ראבטשיק יוסף","bt":"רט","bp":"קיוב","dp":"1519","b":"המיר דתו. ראש העיר קובנא, שר הכספים בליטא. עזר ליהודים ופעל לביטול גזירת הגירוש נגד היהודים-רנה אשר בוטלה-רסג. אחיו - יצחק, מיכאל-שהיה ראש יהודי ליטא ורב הכולל."},{"i":22557,"n":"יוזפוביץ, מיכאל מבריסק","b":"רב הכולל בבריסק ומדינת ליטא-רעד, מקורב למלך זיגמונד הראשון. אחיו - אברהם, המיר את דתו ונתמנה לשר הכספים של ליטא."},{"i":22558,"n":"יוזפוביץ, קאפל","dt":"תשג","b":"רב בפאגיער"},{"i":22559,"n":"יוזפסברג, חיים יצחק מרידיק","k":"בעל חפץ חיים","bt":"תר","dt":"תרס","b":"רב ברידיק-תרלג, חתן ר יהודה זאב סגל. חיבר \"חפץ חיים\" למברג תרנא."},{"i":22560,"n":"יוזפסברג, שלמה מרידיק","f":"חיים יצחק","bt":"תרל","dt":"תשב","b":"חסיד בלז. רב ברידיק-תרס על מקום אביו. נספה בשואה."},{"i":22561,"n":"יוחאי ן, אלעזר מדמשק וטבריה","f":"שלמה","bt":"רס","bp":"דמשק","dt":"שלב","dp":"טבריה","b":"מחכמי תורכיה, נתחנך בישיבות צפת, עלה לארץ-ש' בערך והיה מחכמי צפת, עבר לטבריה, חמת, רב בטבריה לצד ר צמח ור אברהם קלעי על מקומו אחריו. עמד לדין אצל המבי\"ט בצפת. היה דיין גם בירושלים (לדעת פרומקין זו טעות) וחזר לצפת-שיז, ראש הרבנים בטבריה. נזכר ב\"אבקת רוכל\" יחד עם חברו ר יצחק קארו ור יוסף קארו חלק עליהם. פסל את המקוה בחלב והיה במחלוקת עם ר משה רל\"צ-רב הקהילה ונשלחה השאלה להכרעה בפני גדולי הדור. היה בקשר חלופי אגרות עם חכמי דורו וביניהם הרלבח המביט ר יוסף קארו."},{"i":22562,"n":"יוחאי ן, בנימין וטבריה","f":"שלמה","b":"מחכמי טבריה-שפז."},{"i":22563,"n":"יוחאי ן, פנחס מצפת","f":"יוחאי? או שלמה","b":"אחיו של הדיין ר אלעזר בן יוחאי מצפת. נזכר בשות מהר\"ם גאביזון."},{"i":22564,"n":"יוחיוטוב, גבריאל"},{"i":22565,"n":"יוחלסון, ולדימיר","bt":"1856","bp":"וילנא","dt":"1937","dp":"ניו יורק","b":"הצטרף למחתרת הסוציאליסטית, ברח לשוייץ, וחזר בשליחות ונאסר, בהיותו בסיביר התמסר לחקר לשונם של היוקהירים - שבט סיבירי. ופרסם את מחקריו במוסקבה. השתתף במשלחת מדעית באלסקה, ומזרח סיביר-1908. חיבר ספרים ברוסית ואנגלית."},{"i":22566,"n":"יוחנן (מאיטליה)","b":"תשובה אליו ממהר\"ם פדובה - שהוקירו ואהבו."},{"i":22567,"n":"יוחנן ברוך מיונה (קיקניש) מלבו","f":"שמחה","dt":"תכט - יז סיון","dp":"לבוב","b":"ממשפחת יונה הנביא (קיקניש) בלבוב. רב ורופא בלבוב. בנו - ר שמחה מנחם דוקטור. נזכרו שניהם בט\"ז וב\"פני יהושע\"."},{"i":22568,"n":"יוחנן הגאון","f":"זכריה","k":"אבו כתיר יחיא","dt":"ד'תש (940)","dp":"טבריה?","b":"מבעלי המסורה הקדומים, רבו של ר סעדיה גאון."},{"i":22569,"n":"יוחנן הכהן הפייטן","f":"יהושע","b":"פייטן קדמון. חיבר פיוט הנמצא במחזור יוון \"ארקא הרעיש איום\", ו\"אשען במעש אזרח\" - ומופיע בסדור רב עמרם גאון. לדעת צונץ ובעל \"עמודי העבודה\" הוא מחבר רוב הפיוטים במחזור רומניה ורומא."},{"i":22570,"n":"יוחנן הכהן ממצרים","b":"מחכמי מצרים-שנות ה-ת'."},{"i":22571,"n":"יוחנן הכהן משטיפי","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":22572,"n":"יוחנן הלוי מלבוב","f":"אהרן או דוד","dt":"תה - כט ניסן","dp":"לבוב","b":"ר\"מ בלבוב ובעוד מקומות. (שם אביו גם - דוד קשי' ארבך?)"},{"i":22573,"n":"יוחנן מאויבן","b":"דומ\"צ באויבן-תק\"ל"},{"i":22574,"n":"יוחנן מבלגרד וקרלסברג","f":"יצחק","bp":"קרלסבורג","dt":"תקמא","dp":"[טימישואר]","b":"תלמיד חכמי הספרדים בבלגרד. רב בקרלסבורג-תקיח וכל מדינת טרנסילבניה על מקום ר שלום זליג הכהן בן שאול ציון ור בנימין זאב ורצקנד על מקומו אחריו. עזב לאחר כשלש שנים, רב בטימישואר-תקלא, והתכתב עם \"הנודע ביהודה\"."},{"i":22575,"n":"יוחנן מהעלישוי","b":"רב בהעלישוי-ש\"מ"},{"i":22576,"n":"יוחנן מוידין ופליבנא","f":"אברהם","b":"רב עדת האשכנזים בוידין-שלה, רב קהלת ההונגרים בפליבנא."},{"i":22577,"n":"יוחנן מזולקוא","f":"אברהם","dt":"שצט - יז סיון","dp":"זולקוא","b":"מו\"צ ודרשן בזולקוא."},{"i":22578,"n":"יוחנן מטימישואר","b":"רב בטעמעשוואר-תק\"מ"},{"i":22579,"n":"יוחנן מטלומטש","b":"דיין בטלומטש-תרכג."},{"i":22580,"n":"יוחנן מירושלים","b":"מחכמי אשכנז, עלה לירושלים-רפב."},{"i":22581,"n":"יוחנן מלונדון","k":"ר' יוחנן מהעלישוי","b":"רב בלונדון-ת\"ס"},{"i":22582,"n":"יוחנן מפליבנא","f":"אהרן","b":"רב בפליבנא-שי, שאלה ממנו לרשד\"ם."},{"i":22583,"n":"יוטס, יעקב יצחק מלבוב","f":"מאיר ליבוש","k":"בעל אהלי יעקב","bt":"תקעו","bp":"למברג","dt":"תרמו","b":"בעל תואר דוקטור ומוסמך לרבנות. סירב לרבנות למברג והתפרנס ממסחר. חתן ר חיים יצחק בירנבוים, ובזיוו\"ש חתן ר יעקב שמואל רפפורט. חיבר\"אהלי יעקב\" למברג תרח, ועוד."},{"i":22584,"n":"יוטס, מאיר ליבוש מלבוב","f":"שלמה","bt":"תקנד","dt":"תרלו - כב שבט","dp":"לבוב","b":"נכד מהר\"י הלוי אחי הט\"ז, וגם מצאצאי ר משה מיזיס מלבוב. חתן נכדת ר מנחם מאניש חיות-חתנו של הש\"ך. תלמיד ר אריה ליב בעל תשובת גור אריה ויעלת חן מברוד. מחכמי לבוב. בנו - ר יעקב יצחק."},{"i":22585,"n":"יוטר, משה מארה\"ב","f":"שמואל","bt":"תרמה","dt":"תשכו","b":"תלמיד ישיבת ראדין, סלובודקא, מיר והיה תלמיד ר אליהו בראוך קאמאי ממיר. חתן ר לוי יצחק מעביל מטשערטערסק, רב בטשערטרסק-פלך מוהילוב-תרסח על מקום חותנו, ארה\"ב-תרפה. נסמך מאת: ר אליהו ברוך קאמאי, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\"."},{"i":22586,"n":"יוכט, אריה ליב","bt":"תרנ","dt":"תשט - ד תשרי","b":"מרביץ תורה,ר\"מ בביאליסטוק,עלה לא\"י,ר\"מ ברחובות,ר\"מ בתל אביב באור התלמוד"},{"i":22587,"n":"יולי ן, חביב ממכנאס","b":"מראשי קהלת מכנאס, חתם-תרי עם ר יהודה טולדנו."},{"i":22588,"n":"יולי ן, יוסף הלוי ממרוקו","b":"רב בפאס-תרם."},{"i":22589,"n":"יולי ן, שמואל הלוי ממכנאס","f":"ברוך","k":"בעל קול כלה - בכת\"י","b":"רב במכנאס, טנג'יר, גיברלטאר. תלמיד ר יעקב בירדוגו, חברו של ר יוסף בירדוגו, ר יוסף הכהן ממכנאס, וחתם עם ר שמואל הלוי-תקצד. חתן דודו ר יוסף בהלול. עלה לארץ והתישב בטבריה. בשליחות במצרים-תרלג. חיבר דרשות וחדושים בכת\"י. הדפיס \"הדר זקנים\"."},{"i":22590,"n":"יולי ן, שמואל הלוי ממכנאס-הזקן","b":"גביר ונגיד במכנאס-תק בערך. נכדו - ר שמואל ן יולי בעל הדר זקנים."},{"i":22591,"n":"יולס, אברהם אליעזר יהודה ליב","f":"ראה: יולס, יהודה ליב"},{"i":22592,"n":"יולס, אברהם יעקב מסמבור","f":"נחום מחירוב","k":"אדמור מסמבור","dt":"תשב","b":"חתן ר שמשון מבלשביץ. אדמור בסמבור, טורקא. נספה בשואה."},{"i":22593,"n":"יולס, אורי הכהן מסמבור","f":"אפרים צבי הירש","k":"אדמור מסמבור קומרנא","bt":"תקצג","bp":"למברג","dt":"תרע - א אד\"ב","b":"חתן ר שמשון טנא מקומרנא. מלמד בקומרנא, ישב בבלז-תרט אצל ר שלום האדמור ורשם את תורתו, תלמיד ר אברהם מסטרטין שהסמיכו כאדמור-תרכד. אדמור בקומרנא, רב ואדמור בסמבור-תרלח. נסע כאדמור אל ר אברהם יצחק מסדיגורא - ובעצתו עבר לסמבור. חיבר \"אמרות טהורות\" בתוך \"מספד תמרורים\" למברג תרעא. בבית מדרשו ישבו 80 לומדים ופרנסתם עליו.","bk":[["אמרות טהורות",""]]},{"i":22594,"n":"יולס, אליהו מפשמישל","f":"נחום מחירוב","k":"אדמור מסמבור דרוהובי","dt":"תש..","b":"חתן דודו ר שלום מסטרי. אדמור בדרוהוביטש, פשמישל."},{"i":22595,"n":"יולס, אליעזר ליפא מקניהניטש","f":"ישכר","k":"בעל הכשר כלים","bt":"תקף","dt":"תרם","b":"רבה של קניהניטש-תרח, רוזדוביץ. חיבר \"הכשר כלים\" למברג תרח, בנו הוציא לאור את ספרו של אביו \"אלביש ישע\" מונקטש תרעד (נרשם כמחבר - כנראה בטעות)."},{"i":22596,"n":"יולס, אליעזר ליפמן מוראוונה","b":"רב בווראוונה"},{"i":22597,"n":"יולס, אלעזר מסאסוב מונטריאול","f":"יהודה צבי מסמבור","k":"אדמור מסמבור בקנדה","bt":"תרסד","bp":"סמבור","dt":"תשלו - יא אב","dp":"מונטריאול","b":"נסמך מאת ר דוד הלוי הורביץ בעל \"הרי בשמים\", ר יעקב אלימלך פנט מדעש. חתן ר יעקב שמשון קנר האדמור מטשכויב. כיהן כאדמור מסמבור בבוקרשט. ניצל מהשואה ואחריה היגר למונטריאול-תשח וכיהן כאדמור מסאסוב. חיבר \"יד אלעזר\"."},{"i":22598,"n":"יולס, אפרים אליעזר מפילדלפיה","f":"שלום מסטרי","k":"בעל דברי אפרים אליעז","bt":"תרנא-ד","bp":"סטרי או סמבור","dt":"תשמט - כה חשון","b":"תלמיד זקנו - ר אורי מסמבור, ר\"י אנגל. נסמך מאת: ר דוד הורביץ מסטניסלב, ר נתן לוין מרישא, ר קופל רייך מבודפשט. חתן דודו ר יהודה צבי יולס האדמור מסמבור, ובזיוו\"ש חתן ר יחזקאל פולק-חתנו של בעל \"הרי בשמים\". סירב לאדמורות. דיין בסטרי-תרעו ור\"מ בישיבת אביו שם, בודפשט-תרעה אצל ר קופל רייך, רב ברייכנברג-בוהמיה, ניו יורק-תרפא, אב\"ד פילדלפיה. חיבר \"כתבי אחיעזר\" בתוך ספר אחיו ר ישעיה אשר \"שמן הראש\", חיבר \"דברי אפרים אליעזר\" ניו יורק תשמג."},{"i":22599,"n":"יולס, אפרים צבי הירש מלבוב","f":"יואל הכהן","bt":"תקן","dt":"תרך","b":"מחכמי למברג - סירב לרבנות. בנו הצדיק ר אורי מסמבור."},{"i":22600,"n":"יולס, דוד אלימלך מקלוש","f":"אליעזר ליפמן מקניהיט","k":"בעל שופריה דיעקב","bt":"תר","dt":"תרעד","b":"רב בקלוש-תרמג, זורובנא-תרסח, קלוש-תרעד. חיבר \"שופריה דיעקב\" למברג תרמז, ועוד."},{"i":22601,"n":"יולס, זוסמן ממינסק","f":"ישעיה זכריה ממינסק","b":"גביר במינסק, הו\"ל את ספרי אביו."},{"i":22602,"n":"יולס, זכריה ישעיה מלמברג","f":"מרדכי צבי","k":"בעל דובר מישרים","bt":"תקעד","bp":"למברג","dt":"תריב - כה אייר","dp":"מינסק","b":"חתן ר יעקב הלוי הורביץ ממינסק. רב בלמברג-תקץ, עבר למינסק והיה מחכמיה. בשליחות לאנגליה לפגוש את מונטיפיורי. חיבר \"דובר מישרים\" למברג תקצא (בעילום שמו), \"התורה והחכמה\" וילנא תרעג, ועוד. בנו - ר זוסמן.","bk":[["זכר ישעיהו",""],["התורה והחכמה",""],["עת לדבר",""]]},{"i":22603,"n":"יולס, חיים אלתר מלובטשוב","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו, \"הירדן\" - רישא תרץ."},{"i":22604,"n":"יולס, יהודה ליב מסטרי","f":"יעקב צבי מדינוב","bt":"תקפה","dt":"תרנג","b":"נתייתם בילדותו וגדל אצל ה\"בני ישכר\"-ידידו של אביו. רב בסטרי והיה ראש חסידי זידיטשוב שם. הו\"ל את ספרי אביו (הראשון שבהם - קהלות יעקב - בהיותו בגיל 14). גיסו - ר אברהם ליבר טרויגאט מטורנא. מחותן עם האדמור מזידיטשוב."},{"i":22605,"n":"יולס, יהודה ליב מקראקא","dt":"תפז","b":"הגיע מקראקא לכהן כרב ברוהטין, רב באפטא."},{"i":22606,"n":"יולס, יהודה ליב משעבעש","bt":"תקעט","dt":"תרסה - כ ניסן","b":"אב\"ד שעבעש-תרי. חיבר שו\"ת בכת\"י - היה מוכן להדפסה ואבד. תלמידו ר יצחק וייס מנאדי-אידא רשם מחדושיו."},{"i":22607,"n":"יולס, יהודה צבי הכהן מסמבור","f":"אורי מסמבור","k":"אדמור מסמבור סוקולוב","bt":"תריב או תרכא","dt":"תרעט - יא שבט","b":"רב ואדמור בסוקולוב, סמבור על מקום אביו."},{"i":22608,"n":"יולס, יוסף יצחק מברוזדוביץ","f":"ישכר","k":"בעל שערי ציון","bt":"תקף","dt":"תרן","b":"חתן ר אברהם בריזדוביצר. רב בברוזדוביץ. חיבר \"שערי ציון\" למברג תרעב."},{"i":22609,"n":"יולס, יעקב צבי מדינוב","f":"נפתלי מדינוב","k":"בעל מלא הרועים","r":"יחד עם בנו ר' אליעזר יהודה ליבוש מסטריא","bt":"תקלח","bp":"פשמישל","dt":"תקפה - ט ניסן","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ ור מנחם מנדל מרימנוב, ועוד. רב בדינוב, גולוגוב, הוסקוב. חיבר \"חנוך בית יהודה\" וארשא תרכט, \"קהילת יעקב\" פשמישל תרסט. בנו ר יהודה ליביש מסטרי, חתנו ר אברהם ליבר טרויגאט מטורנא.","bk":[["מלוא הרועים על הש\"ס",""],["אמת ליעקב – עה\"ת",""],["בית ועד לחכמים",""],["חינוך בית יהודה",""],["ישרש יעקב - קבלה",""],["פרשת דרכים זוטא",""],["קהלת יעקב – אוצר שמות",""],["שמן ששון - תהלים",""],["זכרון יעקב ויהודה",""],["מלא הרועים",""]],"e":"תקל\"ח-תקפ\"ה"},{"i":22610,"n":"יולס, ישכר מניזנוב","f":"יקותיאל אבא","k":"בעל הכשר כלים","bt":"תקן","dt":"תרך","b":"רב ברדיחוב, ניזנוב. חיבר קונטרס \"הכשר כלים\" שיצא לאור על ידי בנו ר אליעזר ליפא."},{"i":22611,"n":"יולס, ישעיה אשר הכהן מסטרי","f":"שלום מסטרי","k":"אדמור מסמבור סטרי","bt":"תרנג","bp":"ניישטט","dt":"תשג - ב טבת","b":"חתן ר מנשה אייכנשטין מרישא, ובזיוו\"ש חתן ר ישראל רוקח מבוריסלב. רב בסטרי והקים ישיבה שם בשם \"נוה שלום\", בזמן מלחה\"ע ה-I גלה לאנשבאך. נספה בשואה. חיבר \"שמן הראש\" סטרי תרצג. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"יבנה\" - לבוב תרפט."},{"i":22612,"n":"יולס, ישעיה זכריה הכהן","k":"בעל זכר ישעיהו","bp":"מינסק או למברג","b":"מצאצאי הב\"ח, והפני יהושע. חתן הגביר ר יעקב הורביץ מדוקשיץ. מחכמי לבוב, מינסק-תקצד, נתפרסם כ\"העילוי מלמברג\". חיבר גם \"עת לדבר\" לבוב תקצד, \"דובר מישרים\" לבוב תקצא. חתם בשם \"פלאי\". נשא ונתן עם החת\"ס, ר עקיבא איגר, ועוד. בנו - ר זוסמן ממינסק. חברו של ר דב בער יצחק מקרוסנא ושל ר שמואל בן ר עקיבא איגר מפוזנא, ור אברהם דווארעצער."},{"i":22613,"n":"יולס, מנחם מנדל מרישא","f":"ישכר מניזנוב","b":"מחכמי רישא-תרעא. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד, \"הירדן\" - רישא תרץ."},{"i":22614,"n":"יולס, מרדכי מברוד","f":"יצחק קרקובר מברזאן","k":"החסיד מוהרם מבראד","dt":"תקג"},{"i":22615,"n":"יולס, מרדכי מניזנוב והוסיאטין","f":"ישכר","b":"רב בניזנוב, קרופיטש-תריט, הוסיאטין-תרלח, פיסטין-תרנא. (סידר משם גט שעורר נגדו את גדולי הרבנים שיצאו נגדו בקונטרס)."},{"i":22616,"n":"יולס, מרדכי מקרקא","f":"יחיאל בן יצחק מוינה","b":"פרנס ומנהיג בקראקא. חתנו - ר ישכר בר מקראקא בן הרבי ר השל (ויש אומרים שר דוד כתבן הוא שהיה חתנו של ר ישכר בער)."},{"i":22617,"n":"יולס, נחום מחירוב","f":"אורי מסמבור","k":"אדמור מסמבור חירוב","bt":"תרטז [או תרכא]","dt":"תרף","b":"חתן נכדת המאור ושמש. אדמור מסמבור בחירוב ופשמישל."},{"i":22618,"n":"יולס, קלונימוס קלמן מסמבור","f":"נחום מחירוב","k":"אדמור מסמבור","bt":"תרם","dt":"תשג - יא חשון","b":"חתן ר שמשון מבלשביץ. אדמור בסמבור על מקום אביו. נספה בשואה."},{"i":22619,"n":"יולס, שלום מסטרי","f":"אורי מסמבור","k":"בעל שפתי שלום","bt":"תרטז או תרכו","dt":"תרפה - י אב","dp":"ירושלים","b":"חסיד סדיגורא-בויאן. חתן ר אליעזר יצחק טייכר מזמושץ, בזיוו\"ש חתן ר מאיר מזבורוב (שושלת זלוטשוב). רב בניישטט-תרמד, מושציסק-תרנא, סטרי-תרסד. עלה לירושלים-תרפה. חיבר \"שפתי שלום\" בתוך ספר בנו \"שמן הראש\". פרסם מאמרים ב\"אור תורה\" - לבוב תרפו, \"ועד חכמים\". בניו: ר אפרים אליעזר, ר ישעיה אשר. חתניו: ר גדליה גוטליב מלודמיר, ר חיים אברהם קליגהויפט, ר ישראל מושקוביץ מטירקא,","bk":[["דברי שלום",""],["שפתי שלום",""]]},{"i":22620,"n":"יום טוב","f":"משה מבריסטול","b":"מגדולי הראשונים"},{"i":22621,"n":"יום טוב בן אברהם אשבילי; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","bk":[["דקדוקי סופרים לפרש\"י",""],["מפתח",""],["סיפורי גלגולים ורוחות",""],["שיטת הקדמונים",""],["ספר הפרדס ותרומות הפרדס",""],["כתבי הריטב\"א",""],["ספר התדיר",""]]},{"i":22622,"n":"יום טוב הכהן מאדרינופול","b":"רב בקהלת קאטלוניה באדרינופול-רע, היה במחלוקת עם ר שמואל סבע - ור תם ן יחיא מקושטא הכריע ביניהם."},{"i":22623,"n":"יום טוב הכהן מניקופול","b":"רב בניקופול-שנות ה-ש', ור יעקב נעמיאש על מקומו אחריו-שטז."},{"i":22624,"n":"יום טוב הכהן מקאסטוריה","f":"אברהם","b":"רב בקאסטוריה(=קאשטוריאה)-שנות ה-ת' בזמן ר מנחם רוסו."},{"i":22625,"n":"יום טוב הכהן משלוניקי","dt":"תפו","dp":"שלוניקי","b":"רב בשלוניקי. מגיה בדפוס"},{"i":22626,"n":"יום טוב הלוי מטיטואן","b":"מחכמי טיטואן-מרוקו, חתם על פס\"ד-תקצה עם ר\"י ן ואליד, ועם ר יצחק נהון-תרט. נזכר ב\"הלכתא למשיחא\", \"תקפו של יוסף\"."},{"i":22627,"n":"יום טוב הלוי מירושלים","dt":"תקעב - ו אב","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":22628,"n":"יום טוב ליפמן חיים מזמברב","b":"רב בזאמברב"},{"i":22629,"n":"יום טוב ליפמן מאיישישוק","f":"משה שלמה","k":"בעל כבוד יום טוב","b":"רב באיישישוק-תקע."},{"i":22630,"n":"יום טוב ליפמן מוינה","b":"מגדולי חכמי ווינה עד הגירוש-ת\"ל,ראב\"ד בפרשבורג-ת\"נ"},{"i":22631,"n":"יום טוב ליפמן מוינה ופרשבורג","f":"עזריאל מוינה","b":"רב בוינה, ולאחר הגירוש, רב בפרשבורג-תפא בערך ואולי תנה, סידר את תקנות החברא קדישא וחיבר תפילות מיוחדות לחבריה. הסכים בשנת תנד על \"ויקהל משה\" לר משה בן מנחם מפרג."},{"i":22632,"n":"יום טוב ליפמן מזולקוא","f":"נתן","b":"מחכמי זולקוא, חתם-תנו על תקנה שלא יהיה אחד מקרובי הרב ממנהיגי הקהלה."},{"i":22633,"n":"יום טוב ליפמן מקרוז","b":"רב בקרוז-תקן בערך. נינו ר זבולון ליב בן יום טוב ליפמן כיהן גם הוא כרב בקרוז'."},{"i":22634,"n":"יום טוב מכיאו וקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":22635,"n":"יום טוב מפליזא","f":"ריב\"ן","b":"נכד רש\"י. מבעלי התוספות בלותיר,פליזא, פריס-ד'תתק. בנו - ר יהודה מפאריס."},{"i":22636,"n":"יום טוב מקוריץ","b":"תלמיד ר פנחס מקוריץ. נזכר בכתבי תלמידי ר פנחס."},{"i":22637,"n":"יום טוב נתן משלוניקי","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-שה."},{"i":22638,"n":"יונג, אברהם צבי הירש מברטי-אוי","b":"תלמיד ישיבת ר משה פרלס בבוניהאד(=באניהאד), וחברו של ר אברהם יצחק גליק בעל \"באר יצחק\". מחכמי בערטי-אויפלו-הונגריה. נזכר בספרי חכמי דורו ובהם שו\"ת מהר\"ם שיק, \"בית שערים\", ועוד."},{"i":22639,"n":"יונג, שלום מוערבאץ","b":"חתן ר אברהם פראגר מטאפלשאן. רב בווערבוץ(=וערבאץ)-תרם. הניח חדושים לתורה בכת\"י."},{"i":22640,"n":"יונגווריטה, גדליה מאושפיצין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"כתר תורה\" - אושפיצין תרצט."},{"i":22641,"n":"יונגוירט, גדליה מאושפיצין","b":"מחכמי אושפיצין-תרצט."},{"i":22642,"n":"יונגוירט, יונה מטרמבובלה","b":"רב בטרמבובלה - תשובה אליו בשו\"מ."},{"i":22643,"n":"יונגוירט, יונה מנרול","f":"יהושע","b":"רב בנרול, ברודי-תקע."},{"i":22644,"n":"יונגוירט, יונה מסקלט","b":"רב בסקלט-תרא."},{"i":22645,"n":"יונגוערטה","k":"ראה: יונגווריטה","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":22646,"n":"יונגריז אשר אנשל בן שמואל הלוי","bt":"1806","dt":"ה'תרלג 1873","bk":[["מנוחת אשר",""]]},{"i":22647,"n":"יונגרייז - משפחה","b":"מקור השם בר אשר אנשל וינר מפרג שנאלץ לברוח ומהר\"ם מינץ אמר לו לשנות שמו ל-\"בן פורת\" (=יונגרייז) משום מעשה שהיה."},{"i":22648,"n":"יונגרייז, אברהם בנימין מדיארמט","f":"שמואל דוד","dt":"תרצא - ב סיון","b":"רב בפעהר יארמוט(=דיארמט)-תרמט על מקום אביו וראש ישיבה כ-39 שנה. חתן דודו ר משה יונגרייז מקאשוי"},{"i":22649,"n":"יונגרייז, אברהם יחיאל מסנט פטר","f":"משה נתן נטע מטיסא","bt":"תרלה","dt":"תשד - כב סיון","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר זאב ברוין מסנט פעטער ועבר לשם. נספה בשואה. בנו ר אשר אנשל רב בקוזניץ"},{"i":22650,"n":"יונגרייז, אברהם מטשנגער","f":"אשר אנשיל-מנחת אשר","k":"בעל בית אברהם","dt":"תרסד - יט סיון","b":"חתן ר אברהם יצחק גליק מטאלטשווא. רב בטשענגער-תרלד על מקום אביו וראש ישיבה שם ובנו ר אשר אנשיל על מקומו אחריו. בניו גם - ר ישראל מנאדיוואר, ר ישעיה מזערינד, חתנו - ר יהושע שאטין."},{"i":22651,"n":"יונגרייז, אברהם מסעגרין","f":"ישראל מנאדאודוואר","bp":"בסקביץ","dt":"תשנב - א טבת","dp":"ניו יורק","b":"תלמיד הדעת סופר, ור מנחם מנדל שיק מסיקסא, ר יואל פלנר מאויהל, ר צבי דיק מאויהל, ועוד. חתן ר צבי הרש קאהן מדרעטשקע. רב בסעגדין-תרצב, ניצל מהשואה ועבר לניו יורק וכיהן שם כרב-תשז."},{"i":22652,"n":"יונגרייז, אהרן הלוי מזשעליז","f":"שמואל חיים מוואמאש","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יהושע בוקסבוים מגאלאנטא ור משה פורהאנד ממאקווא. חתן ר שמחה נתן גרינבורג מקעזמרק. רב בזשעליז-תרצב. נספה בשואה."},{"i":22653,"n":"יונגרייז, אלעזר אריה מטשנגר","f":"אשר אנשל מטשנגר","b":"חתן ר נתן צבי בריסק מסאלאנטא. רב הצעיר בטשנגר לצד אביו."},{"i":22654,"n":"יונגרייז, אריה ליבוש מסיקסא","f":"שלמה ממאד","dt":"תשד","b":"נכד ר שמואל זאב יונגרייז מביאר-נאדי באיאם. חתן ר מנחם מנדל שיק מסיקסא. רב בסיקסא על מקום חותנו."},{"i":22655,"n":"יונגרייז, אשר אנשיל הלוי מזילא","f":"מרדכי בן שרגא פייש","k":"בעל משנה התלמוד-תרעג","dt":"תש..","b":"חתן הגביר ר אברהם פולק מהרמאנשטדט - אחיו של בעל \"שם משמעון\". רב בזילאה-תרע. נספה בשואה. חיבר גם \"חזון ישעיה\", ועוד."},{"i":22656,"n":"יונגרייז, אשר אנשיל מדיאנדיאש","f":"משה נתן נטע מטיסא","k":"בעל זכור ושמור","bt":"תרלה","bp":"טיסא-פירעד","dt":"תשב - ו טבת","b":"תלמיד השב\"ס, ור שרגא צבי טננבוים ממעזא-טשאטה. חתן ר אהרן שוורץ מטיסא-פירעד. רב בדיאנדיאש-תרנט על מקום דוד אשתו - ר דוד שפיגלר. בנו ר יוסף דב על מקומו אחריו, בנו - ר משה נתן מטאקאי, חתנו - ר יעקב נייפלד רב בבודווא-סילאש ודיאנדיאש. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":22657,"n":"יונגרייז, אשר אנשיל מזילאה","f":"מרדכי הלוי מנייפעסט","dt":"תשד - יא סיון","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר אברהם פולק מסעבען ועבר לשם-תרס. רב בזילאה-תרע. נספה בשואה."},{"i":22658,"n":"יונגרייז, אשר אנשיל מטשנגר-הזק","f":"שמואל מטשעטשע","k":"בעל מנחת אשר","bt":"תקסו","dt":"תרלד - ה כסלו","dp":"טשענגר","b":"תלמיד החת\"ס, מהר\"ם א\"ש, ר יעקב קופל קנטשטט מוורבוי בעל היעב\"ץ. חתן ר מאיר אלמאש-פופר ממטרסדורף. הצטיין בחכמת הרפואה ועזר לאלפים, רב בטשענגער-תקצ\"ד. נפטר באמצע שיעור שנתן כשהגיע למלים \"כשעלה משה למרום\". בניו: ר אברהם על מקומו אחריו, ר משה נתן נטע מטיסא פירד, ר שמואל זאב מבאום(=באיאם), הגביר ר קופל, ר יונתן מטיסא-פריעד (שהיה חזן). חתניו: ר יהושע ברוך רייניץ מצ'צ'וביץ, ר דוד מיארמוט, ר יעקב שיק מנאגי-אודבור.","bk":[["מנחת אשר",""]]},{"i":22659,"n":"יונגרייז, אשר אנשיל מטשענגר","f":"אברהם מטשענגר","dt":"תשד","b":"חתן ר דוד ליב זלצר מהומנא. רב בטשענגער-תרסז על מקום אביו. נטה לחסידות. נספה בשואה. בנו - ר אלעזר אריה מטשנגר."},{"i":22660,"n":"יונגרייז, אשר אנשיל ממזאקוושד","f":"יהושע פאלק מסאנטוב","bt":"תרלו","dt":"תשד","b":"חתן ר משה יונגרייז מקאשוי. רב בנאגי-שאלא-תרנח, מעזאקוושד(=מעזאקיוועשד)-תרסו."},{"i":22661,"n":"יונגרייז, אשר אנשיל מפעהר-יארמ","f":"שמואל דוד מפעהר ירמו","bt":"תרכד","dt":"תרצד - ט אדר","b":"חתן ר יעקב שיק ממישקולץ. רב בפאבינהאז, דיין בפעהר-ירמוט(=יארמוט)-תרסח. בניו - ר שמואל דוד מנירמעדיאש, ר משה נתן, ר אהרן. חתנו - ר אליעזר פיש מקאטשארד."},{"i":22662,"n":"יונגרייז, אשר אנשיל מקוזניץ","dt":"תשד - כב סיון","b":"רב בקאזינץ(=שאיאקאזינץ). חתן ר משה חיים גרינפלד מסנט-פעטר."},{"i":22663,"n":"יונגרייז, אשר אנשל משאיא קוזני","f":"אברהם יחיאל מסט פעטע","b":"רב בשאיא קאזניץ."},{"i":22664,"n":"יונגרייז, ברוך ראובן שלמה מירו","f":"משה","b":"תלמיד דודו - ר שמאול דוד יונגרייז. רב בירושלים. בניו - ר אברהם, ר דוד מירושלים."},{"i":22665,"n":"יונגרייז, דוד הלוי מירושלים","f":"ראובן שלמה","k":"בעל אור דוד","r":"ראב\"ד העדה החרדית בירושלם","bt":"תרנח","dt":"תשלב","b":"נכד ר משה מקאשוי. תלמיד ר יצחק ירוחם דיסקין ור ירוחם פישל פרלא. חתן ר אשר דב דיליאן. מאנשי העדה החרדית בירושלים, דיין בירושלים-תש, ומלמד בישיבת פורת יוסף. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג. מעורכי \"שערי תורה\" - ירושלים תשה.","bk":[["אור דוד - על התורה, תשובות וסוגיות",""],["מועד דוד - מועדים (נדפס בתוך ספר אור דוד)",""],["נרות המערכה - על ענייני המנורה (נדפס בתוך ספר אור דוד)",""],["אור דוד, ראב\"ד ירושלים",""],["אור דוד - על התורה",""],["תשובות וסוגיות",""]]},{"i":22666,"n":"יונגרייז, דוד יחזקאל מאגראם","f":"שמואל בנימין מפילעק","b":"רב באגראם (זגרב)."},{"i":22667,"n":"יונגרייז, חיים הלוי ממעהריש","f":"שמואל בנימין מפילעק","b":"דיין במעהריש-אוסטרוי."},{"i":22668,"n":"יונגרייז, חיים יוסף","f":"שמואל דוד","b":"חתן ר יצחק גליק מסנט פעטער. נפטר ללא ילדים ואחיו ר אברהם בנימין חלץ לאלמנתו."},{"i":22669,"n":"יונגרייז, יהושע פאלק מסאנטוב","f":"שרגא פייש מטשעט","bt":"תרח","dt":"תרפט - יט כסלו","dp":"סנטוב","b":"תלמיד הכת\"ס, ודודו ר אשר אנשיל הלוי יונגריז מטשענגר ואחיו ר שמואל דוד מפעהר-יארמוט. רב בשאלא-תרמז, שטינמאנגר-תרנה, סנטוב-תרנח, מעזאקיוועשד. נזכר ב\"נטע שורק\", \"לבושי מרדכי\", \"יד יצחק\". בניו: ר אשר אנשל מעזאקיוועשד,"},{"i":22670,"n":"יונגרייז, יונתן בנימין","f":"אשר אנשל","b":"חזן."},{"i":22671,"n":"יונגרייז, יוסף דב הלוי מדיאנדי","f":"אשר אנשל מדיאנדיאש","dt":"תשד","b":"רב בדיאנדיאש-תשב על מקום אביו."},{"i":22672,"n":"יונגרייז, יחזקאל הלוי מפרשוב","f":"יצחק צבי מקאשוי","dt":"תשד","b":"חתן ר נח ברוך פישר מפרשוב (ר נח ברוך פיץ). דומ\"צ בפרעשוב לצד חותנו, ואח\"כ לצד ר משה חיים לאו. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":22673,"n":"יונגרייז, יחזקאל שרגא מאיקריטו","f":"אשר אנשיל מקיוועשעד","dt":"תשד","b":"רב באיקריטו"},{"i":22674,"n":"יונגרייז, יעקב יוסף מניר-מאדע","f":"יצחק צבי מקאשוי","dt":"תשד","b":"רב בנירמאדע-תרפז."},{"i":22675,"n":"יונגרייז, יעקב מאיר הלוי מרימא","f":"שרגא פייש הלוי מטשעט","dt":"תרמב - ב שבט","dp":"פילעק","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלאש-יארמוט. חתן ר אהרן ביכלר מפילעק ועבר לשם. רב ברימא-סאמבאט. אלמנתו נישאה בזיוו\"ש לר מאיר טננבוים מפוטנאק."},{"i":22676,"n":"יונגרייז, יעקב צבי מיארמוט","f":"אשר אנשל מיארמוט","b":"נכד ר אשר אנשל בעל מנוחת אשר. דומ\"צ בפעהער יארמוט."},{"i":22677,"n":"יונגרייז, יעקב קופל מכפר אפא","f":"אשר אנשיל-מנחת אשר","b":"גביר ועושה צדקות בכפר אפא."},{"i":22678,"n":"יונגרייז, יעקב שרגא מנגרד-ברצל","f":"משה מקאשוי","dt":"תשד","b":"חתן אחיו ר יצחק צבי יונגרייז מקאשוי. רב בפאבינהאז-תרסח, נאגראד-בערצל."},{"i":22679,"n":"יונגרייז, יעקב שרגא מניו יורק","f":"שמואל בנימין מפילעק","b":"רב בפילעק-ברוקלין."},{"i":22680,"n":"יונגרייז, יצחק הלוי ממרטינסבר","f":"ישראל מנאדאודוואר","dt":"תשד","b":"תלמיד הדעת סופר. חתן ר ישראל זילברשטין מוויצען. אב\"ד מרטינסברג(=דיאר-סט-מרטין)-תשא. נספה בשואה."},{"i":22681,"n":"יונגרייז, יצחק צבי מקאשוי","f":"משה מקאשוי","bt":"תרל","dt":"תרפג - טו טבת","b":"תלמיד דודו - ר שמואל דוד יונגרייז, ובעל \"ייטב לב\". חתן ר דוד זלצר ממונקטש. רב בניר-מעדיאש-תרמט, קאשוי-תרסו על מקום אביו וראש ישיבה. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז. נזכר ב\"נטע שורק\", \"לבושי מרדכי\"."},{"i":22682,"n":"יונגרייז, ישעיה","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":22683,"n":"יונגרייז, ישעיה הלוי מזרינד","f":"אברהם מטשאנגר","k":"בעל משנה תלמוד","b":"רב בזערינד-תרס, גרוויד. חיבר גם \"חזון ישעיהו\", ועוד."},{"i":22684,"n":"יונגרייז, ישעיה פאלק מסנטוב","f":"שרגא פייש יונגרייז","dt":"תרפט - יט כסלו","b":"רב בשאללא-תרנ\"ה,שטיינמנגר,סנטוב"},{"i":22685,"n":"יונגרייז, ישראל הלוי מנאדודואר","f":"אברהם מטשענגר","bt":"תרמב","bp":"טשענגר","dt":"תשד - טו תמוז","dp":"אושוויץ","b":"תלמיד השב\"ס, וזקנו ר אברהם יצחק גליק מטאלטשווא. חתן ר יעקב שיק מנאדאודוואר. רב בבאסקביץ(=בסקביץ), העלישויא, נאדאודוואר-תרעה על מקום חותנו. נספה בשואה. הו\"ל ספר מהרם בנעט על יו\"ד עם הערותיו. בניו: ר יצחק מגיארסנטמרטן-נספה בשואה עם משפחתו, ר אברהם מארה\"ב, ר ישראל, חתניו - ר משה יעקב פריד מקינסנטמרטן-נספה בשואה עם משפחתו, ר יצחק שמואל קצבורג מאזד, ר יעקב מאעסטרא."},{"i":22686,"n":"יונגרייז, מאיר מפילעק","f":"שרגא פייש מטשעטשא","b":"רב בפילעק, רימא-סאמבאט-תרנ."},{"i":22687,"n":"יונגרייז, מאיר נפתלי מטיסא-פיר","f":"משה נתן נטע מטיסא","b":"מחכמי טיסא-פירעד."},{"i":22688,"n":"יונגרייז, מרדכי מנייפעסט","f":"שרגא פייש מטשעטשע"},{"i":22689,"n":"יונגרייז, משה חיים מניר-מאדע","dt":"תשד","b":"רב בנירמאדע"},{"i":22690,"n":"יונגרייז, משה מקאשוי","f":"שרגא פייש מטשעטשע","bt":"תרב-ד","bp":"טשעטשע","dt":"תרסו - ד סיון","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבלאש-ירמוט. חתן ר נח יעקב לעווי מהרטיאן, רב בבלאש-יארמוט לצד רבו, קאשוי-תרלג ובנו ר יצחק צבי על מקומו אחריו. בניו גם: ר שמואל בנימין מפילעק, ר יצחק שרגא מנאגארד-בערצעל. חתניו: ר יוסף אלימלך כהנא מאונגוואר, ר אברהם בנימין הלוי מיארמוט, ר יהודה רוזנר מסעקעליהיד בעל \"אמרי יהודה\"."},{"i":22691,"n":"יונגרייז, משה נתן הלוי מטיסא","f":"אשר אנשל","k":"בעל מנוחת משה","bt":"תקצב","bp":"מטרסדורף","dt":"תרמט - כז אלול","b":"תלמיד הדברי חיים מצאנז. רב ביארמוט, טיסא-פירעד-תרכח, סירב לרבנות פעסט על מקום בעל מחנה חיים. חיבר גם \"תורת משה נתן\". בניו - ר אברהם יחיאל מסנט פעטר, ר אשר אנשל מדיאנדיאש ור שמואל חיים מוואמאש-מיקאלא, חתניו - ר אהרן משה מנדלבוים מואשאר-האלי, ר מנחם מנדל למברגר מטיסא-פאלגאר, ר זאב בלאס מדברצין ולאחר שנפטר חתנו בזיוו\"ש ר יונתן בנימין הורביץ מביסטריץ וירושלים.","bk":[["מנוחת משה – ענינים",""],["תורת משה נתן – עה\"ת",""]]},{"i":22692,"n":"יונגרייז, משה נתן נטע הלוי מטו","f":"אשר אנשל מטשענגער","dt":"תשד","b":"רבה האחרון של טוקאי-תרפט, מעזא-קיוועשעד, טיסא-פירעד. נספה בשואה."},{"i":22693,"n":"יונגרייז, משה נתן נטע מהערנד","f":"שמואל חיים מוואמאש","dt":"תשד - ד סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר. חתן ר יוסף אלימלך כהנא מאונגוואר. רב בערנאד-זשאדני. נספה בשואה."},{"i":22694,"n":"יונגרייז, נתן מפרשבורג","b":"רב וגבאי בישיבת פרשבורג. יצא בקול קורא נגד ר שמואל בטלהיים על מאמר שפרסם כנגד הישיבה."},{"i":22695,"n":"יונגרייז, עמרם הלוי מאזור","f":"אשר אנשל מדיאנדיאש","k":"בעל תפארת עמרם","dt":"תשלג - י טבת","b":"תלמיד הדעת סופר. חתן ר דב בר קליין באויהל. ניצל מהשואה ואחריה רב בדיאנדיאש על מקום אביו, רב בבודאפשט-תש\"ח, עלה לארץ-תשיג, רב באזור-תשי\"ד. חיבר \"בן יכבד אב\" בסו\"ס \"ברכת אשר\" לבנו ר אשר."},{"i":22696,"n":"יונגרייז, פאלק סגל מסנטוב","f":"שרגא פייש מטשאצא","bt":"תריח","dt":"תרפט - יט כסלו","b":"תלמיד ר שמואל דוד יונגרייז. רב בשטיינמנגר(=סאמבאטהעלי)-תרנח, נאדי-שאלוי, סאנטוב(=סאנטוי) וראש ישיבה. פרסם מאמרים ב\"תל תלפיות\". בנו - אב\"ד מעזא-קאוועשר."},{"i":22697,"n":"יונגרייז, שמואל בנימין מפוטנוק","dt":"תשד","b":"רב בפוטנוק"},{"i":22698,"n":"יונגרייז, שמואל בנימין מפילעק","f":"משה מקאשוי","bt":"תרלג","dt":"תשד - כב סיון","dp":"אושוויץ","b":"חתן ר מאיר טננבוים מפילעק, רב בפילעק-תרנח על מקום חותנו. פרסם מאמרים ב\"וילקט יוסף\". נזכר ב\"יד יצחק\"."},{"i":22699,"n":"יונגרייז, שמואל דוד מניר-מדיאש","f":"אשר אנשל מיארמוט","dt":"תשד","b":"חתן ר יצחק צבי יונגרייז מקאשוי. אב\"ד נירמעדיאש."},{"i":22700,"n":"יונגרייז, שמואל דוד מפעהער","f":"שרגא פייש הלוי מטשעט","k":"בעל שות מהרשדה","bt":"תקצז-ח","bp":"טשעטשע","dt":"תרנב-ד-כב-ד טבת","dp":"פעהער-יארמוט","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלאש-ירמוט. חתן דודו ר אשר אנשיל יונגרייז מטשענגער, ועבר לשם-תרכא. רב בפעהער-יארמוט(=פהר גיורמוט)-תרכח וראש ישיבה על מקום קרובו ר משה נתן שעבר לטיסא-פירעד, ובנו ר אברהם בנימין על מקומו אחריו. נסע לאדמור ממונקטש ולאדמור מסיגט בעל \"ייטב לב\" ונפטר בדרכו לשם."},{"i":22701,"n":"יונגרייז, שמואל הלוי מקאשוי","f":"יצחק צבי","bt":"תרנג","dt":"תרצח - ט אד\"ב","b":"דיין בקאשוי-תרפג, היו שרצו למנותו כרב על מקום אביו אך היה מחלוקת על כך ולבסוף נבחר ר שאול בראך. פרסם מאמרים ב\"החיים\" - אונגואר תרפב, \"עמק הלכה\" - באטארקס תרפא."},{"i":22702,"n":"יונגרייז, שמואל זאב מבאיאם","f":"אשר אנשיל-מנחת אשר","dt":"תרס-ט - ז אד\"א","b":"רב בבאיאם-תרלט. נחשב ע\"י אביו לגאון."},{"i":22703,"n":"יונגרייז, שמואל חיים סגל","f":"משה נתן נטע מטיסא","b":"רב בוואמושמיקאלא-תר\"ע. חתן ר אהרן שמואל אסאד מסערדאוהל. בניו - ר משה נתן מזשאדאני, ר אהרן מזשעליע."},{"i":22704,"n":"יונגרייז, שמואל מטשעטשא","f":"יצחק הלוי מפאפא","k":"בעל תורת עדות","bt":"תקכח","dt":"תקץ - כא כסלו","b":"חתן ר אשר אנשל וינר ממישקולץ. תלמיד ר ירמיה ממטרסדורף, ר לעמל גלאגוי מאיזנשטט, ר וולף בוסקוביץ. רב באבראהאם, טשעטשע-תקסב ובנו ר שרגא פייש על מקומו אחריו, עוד מבניו: ר אשר אנשל מטשענגר, ר שמעון מבעטשקא. (באוצר הרבנים נרשם תאריך פטירתו - תקפט - יא כסלו)."},{"i":22705,"n":"יונגרייז, שמואל מפרשוב","dt":"תשג","b":"רב בפרעשוב"},{"i":22706,"n":"יונגרייז, שמעון הלוי מבעטשקא","f":"שמואל מטשעטשא","dt":"תרמב - א אלול","b":"רב בבעטשקא. חיבר ספרים בהלכה ואגדה - בכת\"י."},{"i":22707,"n":"יונגרייז, שרגא פייש מטשעטשע","f":"שמואל מטשעטשא","bt":"תקסח","bp":"טשעטשע","dt":"תרלז - ד טבת","dp":"טשעטשע","b":"תלמיד החת\"ס. חתן ר יהושע פאלק סודיץ מסעטשין. רב בטשעטשע על מקום אביו. מחדושיו בסוף \"תפארת אשר\" ניו יורק תשלו. בניו: ר שמואל דוד מפעהר-דיארמאט, ר משה מקאשוי, ר פאליק מסאנטוי, ר מאיר מפילעק."},{"i":22708,"n":"יונגרלייב, ישראל דוד מראדויל","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":22709,"n":"יונגרלייב, מאיר נחום מוישנוביץ","f":"אלכסנדר שמואל","bt":"תרכח","b":"מצאצאי ר מיכל מזלוטשוב, ר ברוך ממזבוז, ר פנחס מקוריץ, ועוד. רב בווישנוביץ-ווהלין-תרמח. נסמך מאת: ר אורי פישל טוביש מיאסע, ר יצחק אטינגר מלמברג. חתנו - ר חיים יצחק"},{"i":22710,"n":"יונגרמן, יחיאל מיכל מדולינא","f":"דוד זאב","bt":"תרסו","bp":"דולינא","dt":"תשמח","b":"גביר מעשירי פולין. עבר לקלויזנבורג. ניצל מהשואה ושהה בטריטוקיה שבדית בבודפשט. עסק בהצלה. עלה לארץ-תשיב."},{"i":22711,"n":"יונה","f":"שאול","b":"חתן הגביר ר יעקב יעקיל לנדא (הנקרא ר יעקיל רעכילס). בניו - הגביר ר שמואל רבינוביץ מויטבסק, הגביר ר יעקב אברהם מהורדנא."},{"i":22712,"n":"יונה (מנחם) נחום הכהן","f":"מאיר הכהן","b":"אחיו של ר שבתי בעל הש\"ך. חתן ר אהרן שמואל קיידנובר. רב בסוכטשוב-תמט. הסכים על \"פנים מאירות\"-תעה. בניו - ר פנחס הכהן (16921), ר שלום שכנא בעל מאה ברכות. חתנו - ר יצחק-אביו של ר מתתיה הכהן (15783)."},{"i":22713,"n":"יונה אבד צפת","b":"מחכמי צפת, עלה בשנת שנ? בערך. ברח בשנת שמד מצפת לירושלים יחד עם ר שמעון בק, הוא מוזכר בשות מהריט צהלון בדין חלוקת המס בירושלים נגד פסקו של ר בצלאל אשכנזי. ר יוזפא נורילינגן מזכירו ב\"יוסף אומץ\" כאבד צפת. בשות מהריט נזכר אודות בתו שהיתה נשואה לר ליברמן וכשטבע דנו החכמים בהתרת עגינותה."},{"i":22714,"n":"יונה בן אברהם גרונדי","bt":"1200","dt":"ה'כ 1260","bk":[["יראה",""],["אגרת התשובה",""],["ארבע כתות",""],["חידושי רבינו יונה",""],["חידושי תלמידי רבינו יונה",""],["חיי עולם",""],["ילקוט שערים לרבנו יונה",""],["סוד התשובה",""],["ספר היראה",""],["ספר היראה עם ביאור מקור היראה",""],["פירוש",""],["שערי תשובה",""]]},{"i":22715,"n":"יונה דיין מלובלין","b":"מחברי הח\"ק בלובלין. חתם-תפו בפנקס הח\"ק."},{"i":22716,"n":"יונה הכהן מזורובנא","b":"אב\"ד זורובנה-תר."},{"i":22717,"n":"יונה הכהן משלוניקי","f":"מיכאל","b":"מגיה בדפוס שלוניקי-תעב."},{"i":22718,"n":"יונה הלוי","b":"רב-שנת ת\"כ"},{"i":22719,"n":"יונה הלוי מהמבורג","f":"חיים","dt":"תצ - כב אייר","dp":"אלטונא","b":"דיין בהמבורג. בניו: ר חיים, ר שמעון מאלטונא, ר יוזפא - שהו\"ל חדושי הרשב\"א. חתנו - ר שמואל היילבוט."},{"i":22720,"n":"יונה הלוי מוילנא","f":"יהודה גרשון","k":"בעל פירוש לתוספתא","bp":"וילנא","dt":"תקסח - יט תשרי","b":"דיין בוילנא. עסק בחקר התוספתא, והחל להוציא לאור תוספתא עם הגהות ופירוש משלו, ועם הגהות הגר\"א ע\"פ כתה\"י המקורי. הספיק להוציא פירוש לסדר זרעים - וילנא תקנט. נכדו - ר יהודה גרשטיין."},{"i":22721,"n":"יונה הלוי מקיטוב","f":"אברהם","b":"רב בקיטוב. חתן ר משה מקיטוב-תלמיד הבעשט."},{"i":22722,"n":"יונה הספרדי הזקן","f":"יהודה","b":"השליח הראשון של ארץ ישראל הידוע לנו מאז חתימת התלמוד. מיוצאי ספרד שעלה לירושלים או לרמלה, ונשלח לבני הגולה עם אגרת בה מסופר על רכישת הר הזיתים ועוד עניני ירושלים, האגרת אינה חתומה וכנראה נחתמה על ידי ראש הישיבה. באגרת מאת הגאון שלמה בן יהודה (1025-1051) נזכר מר אזהר ב\"ר יונה ויתכן והוא בנו של ר יונה הספרדי. יתכן שאחת מארצות שליחותו היתה ספרד."},{"i":22723,"n":"יונה יהושע מלוברטוב","b":"חתן ר יצחק הורביץ מאה\"ו. רב בלוברטוב-תקל בערך."},{"i":22724,"n":"יונה יוסף","f":"משה","b":"חתן ר שאול רפפורט מביחוב. רב-שנת תר. נכדו - ר אהרן רייכנשטין מבראינסק."},{"i":22725,"n":"יונה יוסף","f":"קלונימוס קלמן","b":"מצאצאי ר יונה בעל איסור והיתר הארוך ונכד ר יונה מאוסטרהא. חתן ר אפרים נפתלי הירש(3112). בנו ר אפרים נפתלי הירש-זקנו של ר השל מקראקא."},{"i":22726,"n":"יונה יצחק מלובלין","f":"מאיר","dt":"תקפח - ה טבת","dp":"לובלין","b":"מחכמי לובלין."},{"i":22727,"n":"יונה מאוסטרהא","f":"אברהם-חתן ר ייב\"י","b":"נכד ר ייב\"י. מחכמי אוסטרהא."},{"i":22728,"n":"יונה מאוסטרהא","k":"יונהלע דער גיטער","dp":"בוהיסלוב","b":"תלמיד הבעש\"ט, והמגיד ממזריטש, חברו של ר ליב בן שרה שהגיע אליו מפעם לפעם. צדיק באוסטרהא, ובית מדרשו היה קיים עד השואה. עסק בפדיון שבויים. בנו (או מצאצאיו) ר אריה יהודה ליב - לייביש פראדל'ס מאוסטרהא. נכדו ר פנחס בן יונה - אדמור באוסטרהא. מכונה - יונה'לה הטוב מאוסטרהא."},{"i":22729,"n":"יונה מאשכנז","k":"בעל איסור והיתר הארו","b":"מרביץ תורה ברגנשבורג. אולי תלמידו של ר\"י איסרלין בעל \"תרומת הדשן\". חיבר \"איסור והיתר הארוך\" - פיררה שמו. בנו - ר קלונימוס קלמן, ונכדו ר יונה מאוסטרהא."},{"i":22730,"n":"יונה מבוריסלב","f":"ישעיה","b":"מו\"צ בבוריסלאב"},{"i":22731,"n":"יונה מברודי","dt":"תצג - ז אב","b":"דיין בברודי"},{"i":22732,"n":"יונה מהיבנוב","b":"רב בהובאנוב"},{"i":22733,"n":"יונה מוילקומיר","dt":"תקפו","dp":"וילנא","b":"מחכמי וילקומיר. גיסו - ר אברהם ברוידא בעל \"בית ועד\"."},{"i":22734,"n":"יונה מוינה ורגנשבורג","b":"מגדולי חכמי אשכנז,ווינה-קע\"ז,דיין ברגנסבורג"},{"i":22735,"n":"יונה מטורלא","f":"משה בנימין זאב","k":"בעל עלה דיונה","b":"רב בטארלא-תמ. חיבר חדושים לש\"ס ומהם נדפס בשם \"עלה דיונה\" פפד\"מ תנד."},{"i":22736,"n":"יונה מלובלין (אוסטרהא)","f":"קלונימוס קלמן","b":"מגדולי חכמי לובלין-שנת ש'. אולי הוא שהיה נכד ר יונה בעל איסותר והיתר הארוך, והיה רב באוסטרהא ומדינת רוסיה."},{"i":22737,"n":"יונה מלומבלא(=לובמלא)","f":"הלל מוילנא","b":"בן הרב של וילנא-נפטר תסו. אב\"ד לומבלא-תץ. חתנו - ר צבי הירש משוטלנד(17166)."},{"i":22738,"n":"יונה מפלאצק","b":"תלמיד הבעשט, והמגיד ממזריטש, ולימים - בגיל 75 - תלמיד ר שניאור זלמן מלאדי."},{"i":22739,"n":"יונה מפראגא","dt":"תרלט - כא אייר","b":"רב בפרגה"},{"i":22740,"n":"יונה מפרשבורג","f":"שאול","b":"רב קדום בפרשבורג, נהרג בפרעות מסעי הצלב-ד'תתן-תתנו עם כל בני הקהלה. נזכר בקינה, ובאזכרת העיר נירנברג בשם יונה בן שאול - כנראה אותו הרב."},{"i":22741,"n":"יונה מקאמון","b":"בשליחות חסידי רוסיה לאיסוף כספים לארץ ישראל, הגיע בעצמו לארץ כמה פעמים עם הכסף."},{"i":22742,"n":"יונה מקומרנא","f":"פנחס","b":"רב בקומרנא, חתם-שצה בפנקס קהלת לבוב."},{"i":22743,"n":"יונה מקמינקא","b":"תלמיד הבעשט. אחיו של ר ברוך מקמינקא."},{"i":22744,"n":"יונה משה מסאבאטיטש","b":"רב בסאבאטיטש-תק\"מ"},{"i":22745,"n":"יונה משלוניקי","f":"יוסף","k":"בעל קול יונים","b":"מחכמי שלוניקי. אחיו של ר אליהו בעל \"קול תרועה\"."},{"i":22746,"n":"יונה, דוד משלוניקי","f":"שבתי יונה-שי למורא","bp":"שלוניקי","b":"תלמיד ר שמואל הכהן משלוניקי. רב בשלוניקי-תיג, שירון. הדפיס ספר אביו \"שי למורא\" עם חדושים ממנו. (אולי זה שהיה רב בשירון היה רב אחר)."},{"i":22747,"n":"יונה, זכריה מתימן","b":"עבר מתימן לג'רבא, סופר ומוהל"},{"i":22748,"n":"יונה, יוסף מטריפולי","bt":"תרם","dt":"תשי - בערך","b":"רב ודיין בטריפולי, ואב\"ד-תרף. הסכים על \"יוסף חן\" לר יוסף רובין - טריפולי תרפח."},{"i":22749,"n":"יונה, יצחק מטריפולי","bt":"תץ","dt":"תקס - בערך","b":"רב בטריפולי, נזכר בפנקס בי\"ד טריפולי, וב\"סגולות ורפואות\" - כת\"י."},{"i":22750,"n":"יונה, שלמה מיכאל מאיטליה","b":"רב באליסנדריה-איטליה והתידד עם החיד\"א בביקורו שם, רב בטורינו. התכתב עם החיד\"א ואף חיבר שיר לכבודו. גיסו - ר יחיאל חיים טרוויש מוירצלי."},{"i":22751,"n":"יונס, שלמה נפתלי הרץ - שנ\"ה","bt":"1840","bp":"דיסנא-פלך וילנא","dt":"1896","dp":"ראשון לציון","b":"מחובבי ציון, עבר לגלובוק וקירב אליו את אליעזר בן יהודה שהיה לחתנו. התישב במוסקבה ופרסם מאמרים ל\"המליץ\", ועוד. ויסד את אגודת \"בני ציון\". עלה לארץ-1892 והצטרף לחתנו אליעזר בן יהודה בהוצאת עתונו \"הצבי\". נאסר עם חתנו בגלל מאמר נגד החסידים, וזוכו במשפט. עבר לראשון לציון."},{"i":22752,"n":"יונתן בנימין הכהן מסעליש","f":"משה אריה","k":"בעל נפש יונתן","dt":"תרצד - יג ניסן","b":"דומ\"צ בסעליש-פלך אונגואר. בנו - ר אליעזר ליפמן קאהן מניו יורק."},{"i":22753,"n":"יונתן מוולוזין","b":"רב בווהלין, וולוזין - בזמן ר אליעזר יצחק פריד."},{"i":22754,"n":"יונתן מפינסק","b":"ספרא ודיינא בפינסק-תר. גיסו של ר אליהו מקליקול. נכדיו - ר משה מישל לוריא מקראקינקובא, ר שאול מפוניבז."},{"i":22755,"n":"יונתנזון, אהרן מוילנא","f":"צבי הירש","k":"בעל כלי שיר","bt":"1820","bp":"וילנא","dt":"1868","dp":"קובנא","b":"מורה בוילנא ובין תלמידיו יל\"ג. עבר לאודסה-1845, שקוד-1847. חיבר שירים ומשלים."},{"i":22756,"n":"יונתנזון, צבי","f":"אהרן","k":"בעל שירי ציון","bt":"1841","bp":"וילנא","b":"עבר לשקוד, יאנובה, וילנא, קובנא. פרסם מאמרים בכתבי עת ועסק במסחר במוסקבה ומינסק. חיבר שירים. פרסם \"פרקי זכרונות\" ב\"הצפירה\". תורם למוסדות צדקה."},{"i":22757,"n":"יוסט, יצחק מרדכי","k":"בעל דברי ימי ישראל","bt":"תקנג","bp":"ברנבורג","dt":"תרכא - ו כסלו","b":"היסטוריון, בעל תואר ד\"ר לפילוסופיה, בקי בחכמת ישראל והעמים. מחנך, מיסד בית חנוך ליתומות בפפד\"מ-תקצח. פרסם מאמרים בכתבי עת בשפות שונות."},{"i":22758,"n":"יוסט, מיכאל מפעסט","b":"מצאצאי ר מיכאל זלצר הראשון. רב בפעסט."},{"i":22759,"n":"יוסט, ניסן מדזיקוב","f":"שמואל","bt":"תרלח","bp":"דזיקוב","dt":"תשד","b":"משורר מלחין וגבאי בחצר האדמור מויזניץ, ונלוה אליו בבקורו בארץ-תרצט. נספה בשואה. עליו בספר בנו ר מאיר - \"אמרי מאיר\" אמשטרדם תשט."},{"i":22760,"n":"יוסט, שמואל מדזיקוב","f":"דוד","bp":"זמיגרוד","dt":"תרפה","b":"משמש בקודש בדזיקוב."},{"i":22761,"n":"יוסטמן, חיים יצחק מוארשא","k":"בעל חיי יצחק","b":"תלמיד בעל חדושי הרי\"ם."},{"i":22762,"n":"יוסטמן, חנוך הניך גד מפילץ","f":"פנחס מנחם אלעזר מפיל","k":"אדמור מצנסטחוב","bt":"תרמד","dt":"תשג - סוכות","dp":"טרבלינקה","b":"נכד האדמור מגור בעל חדושי הרי\"ם. אב\"ד פילץ, וירשוב - בחיי אביו האדמור. רב ואדמור בצנסטחוב, וילון. הקים רשת ישיבות \"שפתי צדיק\". בזמן השואה חזר לצנסטחוב. נספה בשואה. בניו: ר יהושע השל חזקיהו מלודז, ר אברהם בונם, ר דוד אליהו, ר אריה ליב."},{"i":22763,"n":"יוסטמן, יהושע השל חזקיה מלודז","f":"חנוך הניך גד מצנסטחו","dt":"תשג","b":"מצאצי בעל חדושי הרי\"ם. רב בלודז."},{"i":22764,"n":"יוסטמן, מרדכי מיכאל מסאווין","f":"חיים איזיק","k":"בעל שושנת מרדכי","bt":"תרכ","bp":"וארשא","b":"תלמיד ר ברוך ואגנשטין מוארשא בעל \"נתיב חיים\", ישיבת וולוזין. רב בסאווין-פלך לובלין-תרמג. הניח חבורים בכת\"י. נסמך מאת: ר יהושע מקוטנא, ר חיים אלעזר מקאליש, דודו ר גרשון חנוך הניך מראדזין."},{"i":22765,"n":"יוסטמן, פנחס מנחם מנדל מפילץ","f":"בנימין אליעזר","k":"אדמור מגור בפילץ","bt":"תרט","dt":"תרפא - י כסלו","b":"נכד האדמור מגור בעל \"חדושי הרי\"ם\". חתן דודו ר אברהם מרדכי אלתר בן חדושי הרי\"ם, ובזיוו\"ש חתן ר נחמיה רוטנברג בן ר אהרן אליהו-אחיו של \"חדושי הרי\"ם\". תלמיד זקנו האדמור מגור, האדמור ר חנוך הניך מאלכסנדר, וגיסו ר יהודה אריה ליב מגור בעל \"שפת אמת\". רב ואדמור בפילץ-תרסה לאחר פטירת גיסו השפת אמת, וירשוב, צנסטחוב. חיבר \"שפתי צדיק\".","bk":[["צוואה מאת אדמו\"ר",""],["שפתי צדיק – תורה וחג השבועות",""]]},{"i":22766,"n":"יוסי הפייטן","f":"יוסי","b":"פייטן קדמון, נזכר אצל ר סעדיה גאון. חיבר סדר העבודה \"אזכיר גבורת ה'\"."},{"i":22767,"n":"יוסי יודיא מפורטוגל","b":"תוכן בפורטוגל-שנות ה-ר', והמציא מכשיר האצטרולב לניווט בים עבר המלך יואן מפורטוגל."},{"i":22768,"n":"יוסיפיא הגר מצרפת","k":"יהוסיפיא הגר","b":"פייטן מחכמי צרפת-שנות ה-ד'תתק. חיבר רשות לנשמת. נזכר אצל ר משה די ריאטי ב\"מקדש מעט\"."},{"i":22769,"n":"יוסל מוילנא","f":"ביינוש","b":"בעל הקברות בוילנא-תקמג - אבי משפחה שבמשך דורות התגוררו ליד בית העלמין בוילנא והיו שומריו."},{"i":22770,"n":"יוסלביץ, אברהם יוסף מלוביטש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":22771,"n":"יוסלביץ, ברקו","bt":"1765","bp":"קראטינגה","dt":"1809","b":"פקיד באחוזת היבשוף הוילנאי מסלסקי. סוחר בפרגה. בזמן מרד קושצ'ושקו בפולין תכנן עם חברו יוסף אהרונוביץ להקים לגיון יהודי. קושצ'ושקו מינה אותו למפקד הגדוד היהודי בחיל המורדים, לאחר דיכוי המרד עבר לאוסטריה והציע לאוסטרים להקים גדוד יהודי למלחמה נגד הצרפתים ולאחר שהצעתו נדחתה הצטרף לצבא הצרפתי עם בנו והיה מפקד בקרבות רבים, עם הקמת דוכסות וארשא חזר לפולין. נפל בקרב עם האוסטרים-1809."},{"i":22772,"n":"יוסלביץ, יוסף מסובאלק","f":"ישראל אריה","k":"בעל חקר הלכה","bt":"תרלט","bp":"לובטש-פלך נובו-ראדאק","dt":"תרצה - יט שבט","b":"תלמיד ישבת סלובודקא וכונה בשם \"העלוי מלובטש\". חתן ר אברהם חיים שס מזאסלע. מגדולי חכמי דורו, רב באבל-ליד דוינסק-תרסז, טרסטינא-תרעב, סמיאטיש-תרפא, סובאלק-תרפו. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"שערי ציון\" - ירושלים תרפא."},{"i":22773,"n":"יוסלביץ, משה","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":22774,"n":"יוסלזון, יצחק מאיר מדבלין","f":"אברהם יהודה","bt":"תריא","bp":"יאנישוק-פלך קובנא","b":"תלמיד ישיבת מיר, קוברין, איישישוק, ר משה מוילקומיר. נסמך מאת: ר משה מוילקומיר, ר יצחק אלחנן מקובנא. רב בזמלן-פלך קובנא-תרלו, דובלין(=דבלין)-אירלנד. חיבר \"בית יצחק\", \"אהל יצחק\" - בכת\"י. חתניו: ר מיכל אשר מאטלין, ר בן ציון, ר דוד יאפעץ"},{"i":22775,"n":"יוסף","f":"אברהם ר יוספש מטיסמנ","b":"חתן ר מנחם מנדל מרגליות. נכדו - ר אברהם מטיסמניץ - השני."},{"i":22776,"n":"יוסף","f":"עובדיה","k":"רבינו יוסף הקדוש"},{"i":22777,"n":"יוסף","f":"יצחק הדיין","k":"ר' יוסף החכם"},{"i":22778,"n":"יוסף","f":"טוביה","b":"מגדולי הראשונים,ספר כלבו מיוחס לו-שנת פ'"},{"i":22779,"n":"יוסף","f":"עובדיה הדיין","k":"ר' יוסף הדיין"},{"i":22780,"n":"יוסף","f":"צבי הירש רם","k":"בעל מורה צדק","b":"נכד ר אביגדור חריף מבוליחוב. חיבר \"מורה צדק\" זולקוא תקמא, ועוד."},{"i":22781,"n":"יוסף","f":"שמואל מפוזנא","b":"נכד ר יעקב בעל נחלת יעקב."},{"i":22782,"n":"יוסף","f":"יצחק איזיק מויטבסק"},{"i":22783,"n":"יוסף","f":"יצחק בן שלום מניישטט","b":"בנו - ר שלום שכנא מלובלין."},{"i":22784,"n":"יוסף (ברגלוני)","f":"יהודה בן יוסף","b":"ממשפחה מספרד. חיבר מאמר על עיקרים הצריכים לידיעת התלמוד בערבית. ותורגם לעברית."},{"i":22785,"n":"יוסף (גץ) מלבוב","f":"אליקים גץ","k":"חתן המהר\"ם מלובלין","dt":"תיב - ב תשרי","dp":"לבוב","b":"חתן המהר\"ם מלובלין. אב\"ד בלבוב חוץ לעיר בזמן כהונת ר מאיר בן אברהם ז\"ק בתוך העיר, תשובה ממנו-תט ב\"איתן האזרחי\". בניו: ר זאב וולף, ר אריה ליב. חתניו: ר משה בן דוד סגל, ר נחמן רפפורט מדובנא, ונכדו ר שמחה הכהן רפפרוט נבחר לכהן על מקומו בלבוב - באמצע כיהן החכם צבי."},{"i":22786,"n":"יוסף (יוסקא) יעקב מאלסק","f":"אליעזר ליפא מאלסק","k":"בעל אהל יעקב","b":"רב באלסק. חתן ר אברהם אבלי מדרוהוביטש. חיבר \"אהל יעקב\" למברג תקנד."},{"i":22787,"n":"יוסף (קיקניש) מלבוב","f":"יחיאל","dt":"שפט - א אב","dp":"לבוב","b":"ר\"מ וראב\"ד בלבוב, נזכר בשו\"ת הב\"ח עם הדיינים ר אשר זליג בן הקדש ר מאיר פיהם, ור יקותיאל זלמן בן אלעזר."},{"i":22788,"n":"יוסף אבד אוסטרהא","b":"נכדו של בעל הב\"ח, עלה לירושלים, מוזכר באגרת משנת תנט בין תלמידי החכמים בירושלים."},{"i":22789,"n":"יוסף אברהם משלוניקי","k":"בעל דרשות על התורה","b":"מחכמי שלוניקי. חיבר \"דרשות על התורה\" שלוניקי תריב."},{"i":22790,"n":"יוסף אהרן מאוסטרובא","b":"רב באוסטרובה,וולאדובה-ת\"ר"},{"i":22791,"n":"יוסף אהרן מלעשנוב","b":"רב בלעשנוב-תרלט."},{"i":22792,"n":"יוסף איזיק מיברוב","b":"מחכמי יאוורוב(=יברוב), חתם-תנד על קיום תקנת זולקוא בועד זוירז, ובין החותמים בעל הט\"ז, ר אברהם רבי וואלפש, ועוד."},{"i":22793,"n":"יוסף אלחנן הלוי מסערהיי","f":"מאיר חסיד","k":"בעל עינות מים","bt":"תקע","bp":"סייני","b":"רב בפיליאווי-תקצה, ראייגרד-תריג, סערדהייא-תרטז-ליד סייני. היה בעל דרך יחודית בעיון ובגיל 22 זכה להסכמה מבעל \"חמדת שלמה\", ומר אריה ליב צונץ. חיבר \"ברכות המים\" ומתוכו נדפס קיצור בשם \"עינות מים\" וארשא תרטו."},{"i":22794,"n":"יוסף אליהו הלוי מחברון","dt":"תרו - אחרי","b":"מחכמי חברון, בשנת תקן בשליחות לתורכיה, הדפיס בשלוניקי את \"יד רמה\" לר מאיר הלוי אבולעפיה. בשנת תקצח בשליחות נוספת ובשנת תרו חתם עם גדולי חברון"},{"i":22795,"n":"יוסף אליהו מזלוטשוב","b":"רב בזלוטשוב, שריגארד"},{"i":22796,"n":"יוסף אליעזר","dt":"תריט - טו תמוז","b":"רב במזארק"},{"i":22797,"n":"יוסף אלכסנדר מדרביאן","b":"רב בדרביאן, וחתנו ר ישראל איסר לוין על מקומו אחריו."},{"i":22798,"n":"יוסף אמציהו הקראי מדמשק","b":"נשיא קהלת הקראים בדמשק-תקמה."},{"i":22799,"n":"יוסף אפרים מאוסטרהא","f":"נפתלי הרץ","dt":"תקלד - ח טבת","dp":"אוסטרהא","b":"נכד ר יואל פיבש מאוסטרהא. ואחינו של ר אהרן זליג בעל \"עולת אהרן\" פרנס באוסטרהא-תצו. חתם בפנקס ח\"ק. מבניו: ר חיים הפרנס מאוסטרהא, ר יואל פיבש פרנס מאוסטרהא, ר נפתלי הרץ, משה, אליעזר."},{"i":22800,"n":"יוסף אריה הכהן","b":"רב בקהילות ברומניה-תרך. בנו - ר טודרוס מראש פינה."},{"i":22801,"n":"יוסף אריה הכהן מצפת","b":"רב בצפת-תרמח. הסכים על \"בית שלמה\" ירושלים תרמט."},{"i":22802,"n":"יוסף אשכנזי הכהן","b":"קרובו של בעל \"ברכת טוב\" שמביא מתורתו בספרו."},{"i":22803,"n":"יוסף אשכנזי ממזבוז","b":"תלמיד הבעשט. וחתן חורגו של הבעשט."},{"i":22804,"n":"יוסף אשר אנטשיל מראווא","f":"יהונתן","k":"בעל לקוטי מהרי\"א","b":"רב בראווא. חיבר \"לקוטי מהרי\"א\" למברג תרל."},{"i":22805,"n":"יוסף אשר מלובלין","f":"משה יוסף","dt":"שצה - כג תמוז","dp":"לובלין","b":"מחכמי לובלין."},{"i":22806,"n":"יוסף אשר מתיריא","b":"דיין בתירייא-תקו."},{"i":22807,"n":"יוסף בכור אביגדור מקושטא","f":"אברהם","b":"מחכמי קושטא - בשנים תק-תקן."},{"i":22808,"n":"יוסף בכר נחמה יוסף משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"בתי אבות\" לר יוסף דוד-תקפה."},{"i":22809,"n":"יוסף בן משה מפרמישלה","dt":"ה'תסב 1702","bk":[["צפנת פענח חדש",""]]},{"i":22810,"n":"יוסף בן מתתיהו","bt":"ג'תשצ\"ז","dt":"ג'תתס\"א","bk":[["יוסיפון",""]],"e":"ג'תשצ\"ז~-ג'תתס\"א~"},{"i":22811,"n":"יוסף בן שלמה מפוזנה","f":"שלמה קאליפרי","k":"בעל יסוד יוסף","bt":"שסא","bp":"פוזנא","dt":"תנו","b":"למד בשדה לבן(=ביאלא-צערקוב) בשנת תח וניצל מהפוגרום. רב בפוזנא-ת\"כ, חתן ר נפתלי מפוזנא. בנו ר יצחק. רב ודרשן בפוזנא. חיבר \"יסוד יוסף\" - נדפס, ו\"שדה בוכים\" - בכת\"י.","bk":[["יסוד יוסף",""]]},{"i":22812,"n":"יוסף בנימין זאב וולף מזולקוא","f":"אריה יהודה-לוית חן","k":"בעל אור יקרות","dt":"תקכז","b":"חתן ר חנוך הניך מזולקוא. רב בשיניבה(=שינאווי)-תק, זולקווא. חיבר \"אור יקרות\" - זולקוא תצב (נדפס עם ספר אביו \"לוית חן\"). בנו - ר נפתלי הרץ מזולקוא. חתנו - ר צבי הירש בן משה מזולקוא ובוסק."},{"i":22813,"n":"יוסף בנימין מזבנא","b":"רב בזבנא."},{"i":22814,"n":"יוסף בעל השמועות","b":"מחכמי הראשונים, כתב בספר כל חדוש ששמע מחכמים בשם אומרם, נזכר אצל רבנו ירוחם."},{"i":22815,"n":"יוסף בער","dt":"תשג","b":"רב בווידאמע"},{"i":22816,"n":"יוסף בר מהמבורג","f":"יוזפא בן דניאל מואנד","bt":"תקכה","dt":"תקעה","dp":"ואנדסבק","b":"מחכמי המבורג, ברח לאלטונא בזמן מלחמת נפוליאון, דרשן בהמבורג-תקעד."},{"i":22817,"n":"יוסף ברוך ממצרים","b":"רב במצרים-שנת ת'."},{"i":22818,"n":"יוסף ברוך מפלורינה","b":"רב בפלורינה-שנות ה-ת'."},{"i":22819,"n":"יוסף ברצילון מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":22820,"n":"יוסף בר\"ש בר\"א מברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":22821,"n":"יוסף גדליה זאב מבילקמין","b":"רב בבילקמין-תקצט. מחותן עם ר משה ענסר."},{"i":22822,"n":"יוסף גרשון מדוואהרט","b":"אדמור בדוואהרט לאחר פטירת אביו, והיה גם נוסע לר מנחם מנדל מקוצק - שהיה מרבה בשבחו."},{"i":22823,"n":"יוסף גרשון מליסיעץ","k":"בעל חדושי הגרשוני","b":"רב בליסיעץ-תר\"מ"},{"i":22824,"n":"יוסף דב בריש הכהן מקשונז","f":"אריה ליב בעל הקצות","dt":"תרג - יט אדר","b":"רב בקשונז, ווידיסלב - בנו ר מרדכי על מקומו אחריו. חתן ר שמואל אריה זנויל ליב צאלין."},{"i":22825,"n":"יוסף דב הכהן","k":"בעל דברי יוסף","b":"רב בווינה-תר\"ס"},{"i":22826,"n":"יוסף דוד הכהן מזוולוב ויאס","f":"אפרים","k":"בעל דרכי האמונה","bt":"תקי","dt":"תקפח - כא אייר","dp":"יאסי","b":"תלמיד החוזה מלובלין, ר משה ליב מסאסוב, ועוד. בידידות עם רד\"ש איבשיץ. רב בטיסמניץ, זוולוב-תקע, יאסי-תקעד על מקום האוהב ישראל. חיבר \"דרכי האמונה\" יאסי תריז."},{"i":22827,"n":"יוסף דוד מאיר","dt":"תשג","b":"רב בסאסוב-לבוב"},{"i":22828,"n":"יוסף דוד מבריסק","b":"מחכמי בריסק-תטו."},{"i":22829,"n":"יוסף דוד מדרהיטשין","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":22830,"n":"יוסף דוד משלוניקי - ב","dt":"תרכז - כז אלול","dp":"שלוניקי","b":"רב הכולל בשלוניקי לצדו של ר אשר קובו."},{"i":22831,"n":"יוסף הושטט ממינשטר","f":"משה","k":"בעל לקט יושר","b":"תלמיד בעל \"תרומת הדשן\". גדול בתורה במינסטר-ר\"י. קרובו של ר אברהם קצנלנבוגן מאויבן - שכתב אליו להצדיק עצמו במחלוקת כנגדו."},{"i":22832,"n":"יוסף החזן","f":"יפת המלמד","b":"שליח קהילת ירושלים בתקופת הגאונים למצרים לבקשת עזרה. בגניזה נמצא קטע ממכתב שנשלח לר אפרים בן שמריהו העזתי בענין שליחותו."},{"i":22833,"n":"יוסף החזן מוירצבורג","f":"נתן","bp":"טרני","b":"פייטן בוירצבורג-שנות ה-ד'תתק. חיבר מערבית ויוצרות, ואולי הוא הנזכר אצל הראב\"ן."},{"i":22834,"n":"יוסף הירושלמי","f":"תנחום הירושלמי","k":"בעל ערוגת הבשם","bt":"כב (1262)","b":"מחכמי ארץ ישראל. חיבר דיואן ובין השירים קינה בשם \"ערוגת הבושם\" על מות ר יצחק בן דוד הנגיד שנפטר בחיי אביו וכן קינה על פטירת אביו וקהל חכמים בעכו בידי הערבים אשר כבשו את העיר. ועוד."},{"i":22835,"n":"יוסף הירש","k":"בעל דברי יוסף","dt":"תשכו - א שבט","b":"ראב\"ד בקרקא,עבר לארה\"ב"},{"i":22836,"n":"יוסף הירש","dt":"תשג","b":"רב בדאברין"},{"i":22837,"n":"יוסף הירש מטורקא","b":"רב בטורקא-תרפח."},{"i":22838,"n":"יוסף הכהן","f":"שמואל שמלקא כץ","b":"רב-שנת תק\"מ"},{"i":22839,"n":"יוסף הכהן","b":"תלמיד הרמב\"ם - ספר מורה נבוכים נכתב לכבודו. חיבר פירוש על שיר השירים."},{"i":22840,"n":"יוסף הכהן","f":"גוריון","k":"בעל יוסיפון","b":"חיבר ספר הקדמוניות וספר יוסיפון. אחיו של נקדימון הנזכר במסכת תענית."},{"i":22841,"n":"יוסף הכהן","f":"שניאור","k":"בעל מנחת כהן","b":"חיבר תקון סופרים להגהת ספרי תורה בשם \"מנחת כהן\" קושטא שנח."},{"i":22842,"n":"יוסף הכהן (אשכנזי) מירושלים","f":"מרדכי","k":"בעל דברי יוסף","bp":"ירושלים","b":"תלמיד דודו ר יצחק הכהן (תלמידו ר משה גלנטי), ותלמיד בעל \"בית יעקב\". מחכמי ירושלים, חיבר: \"דברי יוסף\" ונציה תע. ועוד. בשליחות חברון ואחר כך בשליחות צפת וכתב פנקס שליחות. בהיותו בעיר אולינא ביון תיקן תקנות בקהילה, (מובא ב\"פרח מטה אהרן\"), וכנראה התערב בסכסוך שהיה בין גולי פטראץ ואנשי לאריסה. בשנת תסו הגיע לאירופה להדפסת ספריו נפגש עם ר משה חאגיז באמשטרדם והדפיס עבור ר משה את ספר זקנו \"זבח השלמים\" ועוד. בשנת תסט היה בוינה ופגש את ר דוד אופנהיים שהסכים על ספרו. ר י.מ. טולידנו פרסם את פנקס שליחותו וכן פנקס השליח שקדם לו ר משה הלוי הנזיר שאותו העתיק ר יוסף והשתמש בו בשליחותו שלו. בסוף ימיו רב באנגורה"},{"i":22843,"n":"יוסף הכהן הפייטן","f":"חיים","b":"פייטן. חיבר \"ציון במשפט לכי\"."},{"i":22844,"n":"יוסף הכהן הרואה אלבציר","f":"אברהם","k":"בעל ספר הנעימות","b":"מחכמי הקראים הקדומים. סגי נהור. בקי בפילוסופיה, אולי בן זמנו של ר סעדיה גאון. חיבר \"שרשי הדת\" - נזכר אצל רבנו בחיי ב\"חובות הלבבות\", \"מחכימת פתי\", ועוד."},{"i":22845,"n":"יוסף הכהן הרופא מאוויניון","f":"יהושע בן מאיר","k":"בעל דברי הימים למלכי","bt":"רנו","bp":"אוויניון","b":"רב ורופא ממשפחה ממגורשי ספרד. הגיע לגינובא(=גנואה)-איטליה בגיל חמש. חיבר גם \"עמק הבכא\" מיץ תריב - עם הגהות שד\"ל ור מאיר לעטריס שהוסיפו הקדמה."},{"i":22846,"n":"יוסף הכהן מאיטליה","b":"תשובה אליו ב\"דבר שמואל\"."},{"i":22847,"n":"יוסף הכהן מארץ ישראל","f":"שלמה","b":"מגאוני ארץ ישראל בסוף תקופת הגאונים. אביו היה ראש הישיבה ברמלה. בשנת תתנד היה ר יוסף ברמלה, והוא נאסר ונשלח לדמשק בגלל מלחמתו בקראים."},{"i":22848,"n":"יוסף הכהן מגנואה","b":"רב בגנואה-רצג, עסק בפדיון שבויים שנשבו במלחמת ונציה תורכיה-רצב."},{"i":22849,"n":"יוסף הכהן מג'רבה","f":"יצחק","k":"בעל יוסף בסדר","b":"מחכמי ג'רבא."},{"i":22850,"n":"יוסף הכהן מג'רבה וטריפולי","f":"נסים","dt":"תריח","dp":"ג'רבה","b":"מחכמי ג'רבה, רב ודיין בטריפולי-תקעב כ-10 שנים, חזר לג'רבה וכיהן כדיין-תקפב. נזכר ב\"ממלכת כהנים\" לר שושן הכהן ירושלים תשלז."},{"i":22851,"n":"יוסף הכהן מדבדו-מרוקו","b":"מו\"ץ בדבדו-מרוקו, חתם בפס\"ד-תקסא."},{"i":22852,"n":"יוסף הכהן מדימנאט-מרוקו","b":"דיין בדימנאט-מרוקו-תעד עם ר שלמה עמאר וחתם עם ר משה ישראל מרודוס שביקר שם."},{"i":22853,"n":"יוסף הכהן מהורודנקה","b":"רב בהורודנקה."},{"i":22854,"n":"יוסף הכהן מוייצען וירושלים","f":"מאיר","b":"דיין בוייצען. מחכמי ירושלים. חתם על המכתב לר דוד אופנהיימר-תעז."},{"i":22855,"n":"יוסף הכהן מורידבורג","f":"משה הכהן (14773)","b":"רב בוארידבורג-תכג."},{"i":22856,"n":"יוסף הכהן מחלב","b":"מראשי קהלת הספרדים בחלב-שנות ה-ש'."},{"i":22857,"n":"יוסף הכהן מטיטואן","b":"רב במדיונא-מרוקו, טיטואן-שנות ה-תק'."},{"i":22858,"n":"יוסף הכהן מטיריא","b":"רב בטיריא-ש'-ת' - בזמן ר גבריאל גליקו."},{"i":22859,"n":"יוסף הכהן מטריפולי-לבנון","f":"שמואל מטריפולי","dt":"שן","b":"רב בטריפולי-לבנון על מקום אביו. בניו - ר שמואל, ר ישעיה. נספד ע\"י ר ישראל נג'ארה."},{"i":22860,"n":"יוסף הכהן מיוזיל-היסאר","b":"מראשי קהלת יוזיל-היסאר-ליד אזמיר-שנות ה-ת'."},{"i":22861,"n":"יוסף הכהן מירושלים","b":"תלמיד ר יעקב ביבאס בעל \"שארית יעקב\", הו\"ל את ספרי רבו."},{"i":22862,"n":"יוסף הכהן מליפאנטו","f":"יעקב","b":"מחכמי ליפאנטו-יוון - שנות ה-ש'."},{"i":22863,"n":"יוסף הכהן מסאלי","f":"שמעוני","b":"מחכמי סאלי-מרוקו, חתם על פס\"ד-תצב."},{"i":22864,"n":"יוסף הכהן מפאס","f":"אליהו","b":"מחכמי פאס-תקמג, מליצה לכבודו אצל ר חיים דוד סירירו."},{"i":22865,"n":"יוסף הכהן מפאס","b":"חתן ר אברהם גביזון. מחכמי פאס בזמן הגירוש (ולא ידוע אם היה בעצמו מספרד), חברו של ר אברהם עוזיאל."},{"i":22866,"n":"יוסף הכהן מפאס","dt":"שעא - ח חשון","dp":"פאס","b":"מחכמי מרוקו, נהרג עק\"ה עם ר מאיר צבאע, נספד בידי ר וידאל הצרפתי. חתם בספר התקנות-שסב."},{"i":22867,"n":"יוסף הכהן מפאס","dt":"תקלח - טו אייר","dp":"האלזאוייא-מרוקו","b":"מחכמי פאס, גלה בהאלזאווייא. נספד בידי ר אליהו הצרפתי."},{"i":22868,"n":"יוסף הכהן מפיורדא","f":"שמואל","b":"רב בפיורדא-תנ. בניו - ר שמואל מאמדור בעל \"חדושי מר שמואל\", ר נתן נטע."},{"i":22869,"n":"יוסף הכהן מפלינסק","f":"יואל","k":"בעל דרוש לחיי הכהן","b":"מחכמי פלינסק (פלונסק?)"},{"i":22870,"n":"יוסף הכהן מצור","f":"יעקב הסופר","k":"יוסף הכהן הרביעי בחב","b":"סופר הקהלה בצור בזמן הגאונים, היה רביעי בישיבה בימי הצלבנים. חתם על שטר הרשאה בצור בשנת ד' תשעא ועל שטר פיצוי בשנת ד' תשפ. ועוד"},{"i":22871,"n":"יוסף הכהן מצנסטחוב","f":"יחיאל מיכל מזאלושין","b":"נכד ר שמואל לסקר מלוסק. מחותן עם ר עקיבא איגר. גיסו - ר משה מזאלושין."},{"i":22872,"n":"יוסף הכהן מצפת","b":"מקובל מחכמי צפת מתלמידי האר\"י."},{"i":22873,"n":"יוסף הכהן מקורפו וצפת","f":"אברהם","k":"בעל מושעות אל","b":"מחכמי צפת, עלה מקורפו. חיבר פירוש להושענות - \"מושעות אל\" קוריגישמי שנח ואחר כך בונציה שסד, וטעם למוסף \"תכנת שבת\" - ונציה. אולי זהה עם ר יוסף הכהן שחתם בשנת שמז ובשנת שנד על תקנת שחרור תלמידי חכמים ממס, וכן אולי זהה עם ר יסוף הכהן שחתם עם חכמי ירושלים בשטר צוואה בשנת שן ומבוא בשו\"ת ר בצלאל אשכנזי."},{"i":22874,"n":"יוסף הכהן מקושטא","b":"ממונה על החזקות בקושטא-שס עם חבריו ר משה משלם הלוי, ר יום טוב ן יעיש ועוד. אולי הוא שהיה גם בשנות ה-ת'."},{"i":22875,"n":"יוסף הכהן מקלוש","f":"יחיאל מיכל","bt":"תפ","dt":"תקלא","b":"רב בקלוש. נכדו של התוי\"ט, אביו של בעל הקצות."},{"i":22876,"n":"יוסף הכהן מקלעא דלגריר-מרוקו","b":"מו\"ץ בקלעא דלגריר-מרוקו-שנות ה-תק'. נזכר ב\"ויאמר יצחק\" לר יצחק ן ואליד."},{"i":22877,"n":"יוסף הכהן מרשיד-מצרים","b":"גביר ברשיד-שנות ה-ת', חוכר המכס אצל יצחק נבארו שר האוצר, ובנו אברהם הכהן על מקומו אחריו."},{"i":22878,"n":"יוסף הכהן משלוניקי","b":"מגיה בדפוס גדיליה בשלוניקי--רפב."},{"i":22879,"n":"יוסף הכהן משלוניקי - א","f":"נסים","b":"דיין בשלוניקי-שס בערך - בזמן ר אהרן ן חסון."},{"i":22880,"n":"יוסף הכהן משלוניקי - ב","b":"מחכמי שלוניקי-תכו, היחיד שיצא נגד ש\"ץ ושקיים את תפילות וקינות תשעה באב-תכו כסדרם - למרות הכרזת ש\"ץ על ביטול הצום. (היו שני חכמים בשם זה האחד נפטר לפני תיז, והשני חברו של ר דוד קונפורטי)."},{"i":22881,"n":"יוסף הכהן משלוניקי - ג","b":"דיין בשלוניקי-תקלו."},{"i":22882,"n":"יוסף הלוי","f":"הרז\"ה"},{"i":22883,"n":"יוסף הלוי","b":"תלמיד החת\"ס. רשם מתורת רבו, בשנים תקפה-תקפט, ונדפסו ב\"חת\"ס החדש עה\"ת\"."},{"i":22884,"n":"יוסף הלוי","f":"חזקיה יהודה","k":"מפפד\"מ","dt":"רצד - א תמוז","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":22885,"n":"יוסף הלוי מאדרינופול","k":"בעל מצרף","bt":"1827","b":"מלומד ובקי בשפות. בשליחות באתיופיה בעזרת ר נתן אדלר מלונדון - לבדוק את מצב היהודים. חיבר גם ספר חנוך עם באור \"באר יוסף\", \"מצרף לשון\", ועוד."},{"i":22886,"n":"יוסף הלוי מאדרינופול","f":"ישראל","b":"רב קהלת האשכנזים בסופיה-שנות ה-ש'."},{"i":22887,"n":"יוסף הלוי מאדרינופול ופאריס","f":"אהרן","k":"בעל באר יוסף","bt":"תקפז","bp":"אדרינופול","dt":"תרעז - טו שבט","b":"חוקר, בלשן, ארכיאולוג, מזרחן. חוקר ופעיל למען יהודי אתיופיה. תלמידו - ר אברהם דאנון חיבר שיר לכבודו \"על השמונים מזמור\"."},{"i":22888,"n":"יוסף הלוי מאלגיר","f":"נחמן","b":"רב באלגיר - ר-רן בערך, נסע לארץ ושלח סדר מסעיו לרשב\"ש ונדפס מקצתו בספרי מסעות."},{"i":22889,"n":"יוסף הלוי מוידין","f":"אברהם","b":"דיין בוידין-תקפג עם ר אברהם הכהן ור שם טוב בן ציון."},{"i":22890,"n":"יוסף הלוי מזייתון ולאריסה","b":"רב בזייתון-ליד לאריסה, עבר ללאריסה-תמה לאחר כיבושה בידי ונציה, והיה מראשי קהלת פליטי פטרץ וזייתון בלאריסה."},{"i":22891,"n":"יוסף הלוי מזלושיץ","f":"יעקב","k":"בעל הפלאות נדרים","b":"רב בזאלושיץ(=זלושיץ)."},{"i":22892,"n":"יוסף הלוי מירושלים","f":"יצחק","b":"מחכמי ארץ ישראל, עלה בשנת רן בערך מאירופה עבר לקנדיא? חתם בשנת רסט על תקנת שחרור תלמידי חכמים ממס, נזכר בפסקי הרא\"ם, ובספר \"זקן אהרן\" לר אליהו קפסלי. כתב יד חדושים על חולין במכון לכתב ידי."},{"i":22893,"n":"יוסף הלוי מירמליניץ","f":"נפתלי הירץ איטנגא","b":"רב ביארמליניץ-תק\"צ"},{"i":22894,"n":"יוסף הלוי ממגניסיאה","b":"רב במגניסיאה-שנות ה-ש'."},{"i":22895,"n":"יוסף הלוי ממכנאס","dp":"ירושלים","b":"מו\"ץ במכנאס, עלה לירושלים. חתם על פס\"ד-תריב עם ר יוסף בירדוגו, ר ראובן סירירו, ר עמור אביטבול, ועוד."},{"i":22896,"n":"יוסף הלוי ממצרים","b":"מחכמי קהיר-מצרים-שנות ה-ת', עבר לאלכסנדריה."},{"i":22897,"n":"יוסף הלוי ממצרים","f":"בנימין","bp":"קהיר","b":"דיין בקהיר, רב באלכסנדריה-תנג על מקום ר יהודה חביליו (שעלה לחברון)."},{"i":22898,"n":"יוסף הלוי מסופיה","f":"ישראל","b":"רב בסופיה-שנות ה-ש'."},{"i":22899,"n":"יוסף הלוי מסעטשין","b":"רב בסעטשין"},{"i":22900,"n":"יוסף הלוי מפאס - א","f":"יהודה","b":"משורר מחכמי פאס הקדומים, נזכר אצל ר יעקב ן צור-היעב\"ץ."},{"i":22901,"n":"יוסף הלוי מפאס - ב","b":"מחכמי פאס-שנות ה-ש'-ת'. נזכר אצל היעב\"ץ."},{"i":22902,"n":"יוסף הלוי מפרג","f":"יצחק בן שלמה","k":"בעל גבעת המורה","bp":"ליטא","b":"מחכמי המחקר בפרג-שעא. לימד פילוסופיה לכמה מחכמי פרג ובהם בעל \"תוי\"ט\". חיבר פירוש ל\"מורה נבוכים\" בשם \"גבעת המורה\" ובו ביקר כמה מדברי הרמב\"ם, והיה מחלוקת כנגדו ונאלץ להתנצל. חיבר גם \"כתנת פסים\" ובו עוסק בקשר בין עיקרי האמונה והתורה לבין שבעת המדעים."},{"i":22903,"n":"יוסף הלוי מפרג","f":"מאיר מרדכי דוד משידל","dt":"תש..","dp":"שידלוב","b":"חתן דודו ר יחיאל אלתר פרלגר מאיוואנצק-חתן ר יעקב מאפטא. אדמור בשידלוב, אוייאנצק(=איוונצק). חתנו ר אלימלך אריה רבינוביץ בן יחזקאל מרדמוסק על מקומו אחריו בשידלוב."},{"i":22904,"n":"יוסף הלוי מצפת","b":"רב בצפת-שנות ה-תק'-תר'. חתם-תרכב עם ר רפאל מאמאן ור יהודה שבתי ענתבי."},{"i":22905,"n":"יוסף הלוי מקאזיווע","dt":"תריד - ט חשון","b":"רב בקאזיווע"},{"i":22906,"n":"יוסף הלוי מקושטא","f":"אברהם","b":"מחכמי קושטא-שנות ה-ש'."},{"i":22907,"n":"יוסף הלוי מקושטא","b":"דיין בקושטא-תקעה, ממונה על איסור והיתר עם ר יוסף מימון ור חיים פינטו."},{"i":22908,"n":"יוסף הלוי מקליבלנד","b":"רב בקליבלנד-תרטו. תשובה ממנו ב\"מלחמות אלקים\" לר ישכר דב איללאווי,ובתשובתו מספר כי היה שליח בעל כרכו באספת הרבנים המשכילים בעיניהם בקליבלנד-תרטו, ושם קבלו עליהם למראית עין את האמונה במסורת חז\"ל, אולם רק כלפי חוץ - ובאמת \"קבלו ולא קיימו\" וכו'."},{"i":22909,"n":"יוסף הלוי משלוניקי","f":"שמואל","dt":"רפט - ח אב","dp":"שלוניקי","b":"מוהל מחכמי שלוניקי מקהלת אשכנזים. אחיו של ר חיים משלוניקי."},{"i":22910,"n":"יוסף הלוי משלוניקי","f":"שלמה","dt":"רצט - טו אד\"א","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר יצחק ור יעקב. נפטר צעיר."},{"i":22911,"n":"יוסף הלוי משלוניקי","b":"תלמיד ר אליה גוארטל משלוניקי. מחכמי שלוניקי."},{"i":22912,"n":"יוסף הלוי משלוניקי - א","f":"יצחק","dt":"שעח - טו אלול","dp":"שלוניקי","b":"רב בשלוניקי. אחיו של ר שלמה הלוי הזקן. חתם ראשון-שעח על ההסכמה לקביעת יום יד אלול לתענית ציבור בגלל הרוגי דולייא. בנו - ר אברהם בעל שו\"ת, חתנו - אחיינו ר יוסף בן שלמה הלוי הזקן. (לפי רוזניס - אחיו של ר יצחק בעל \"חשק שלמה\")."},{"i":22913,"n":"יוסף הלוי משלוניקי - ב","b":"דיין בשלוניקי-תקלו."},{"i":22914,"n":"יוסף הלוי סגל מסופיה","f":"יחיאל מסופיה","b":"מראשי קהלת האשכנזים בסופיה על מקום אביו - בדור שלאחר הגירוש."},{"i":22915,"n":"יוסף המקנא מצרפת","k":"בעל תשובות המינים","b":"מגדולי חכמי ישראל בצרפת-ד'תתק\"פ"},{"i":22916,"n":"יוסף המשביר הקראי","f":"שמואל","dt":"תס","b":"רב עדת הקראים בהעליץ-גליל פאקוטיה. חיבר גם \"פארת יוסף\", \"שבר יוסף\" ומכאן כינויו \"המשביר\", סייע לתלמידו - ר מרדכי בן ניסן הקראי בחיבור ספרו \"דוד מרדכי\" והוא תשובה לחכם הנוצרי יעקב טריגלנד."},{"i":22917,"n":"יוסף הנגיד מגרנדה","f":"שמואל הנגיד","k":"יוסף אבן נרגלה","bt":"ד'תשצא","dt":"ד'תתכד","b":"גדול בתורה חכמה ועושר, משנה למלך בגרנדה על מקום אביו-ד'תתטו, מרביץ תורה, בעל חסד. נהרג עק\"ה."},{"i":22918,"n":"יוסף הנגיד ממצרים","dp":"מצרים","b":"נגיד במצרים על מקום ר שמואל (עמנואל) בן חנניה, ור נתן הכהן שולאל על מקומו אחריו."},{"i":22919,"n":"יוסף הנקדן","f":"קלונימוס","b":"נקדן מחכמי המסורה באשכנז-ד'תתקצח וכתב אז חומש. חיבר פיוטים ובהם \"אדיר במרום מלך עליון\" המופיע במחזור צרפת, וקינה על קדושי פולדא."},{"i":22920,"n":"יוסף הספרדי מירושלים","f":"אליעזר","k":"בעל צפנת פענח","b":"מגדולי המדקדקים,מחכמי ירושלים-שנת ש'. חיבר \"צפנת פענח\" על ראב\"ע - בכת\"י"},{"i":22921,"n":"יוסף העניכש (הנכ'ס) מזולקוא","f":"חנוך הניך מזולקוא","b":"פרנס בזולקוא. בניו - ר נצתן, ר משה ר יוסקיש אשכנזי."},{"i":22922,"n":"יוסף הפייטן","f":"שם טוב בן ישוע","b":"פייטן ובקי בחכמת העיבור-קפח, חיבר שיר על מלאכת העיבור, ונדפס עם חדושים מאת הרופא ר דניאל פרחיה משלוניקי."},{"i":22923,"n":"יוסף הפייטן מאלגיר","f":"אבא","b":"פייטן מחכמי והראן-שנות ה-ק', חיבר סליחה \"אקום להודות לאל\". שאלה ממנו לרשב\"ץ."},{"i":22924,"n":"יוסף הפייטן מיוון","f":"יצחק","b":"פייטן בביון-שנות ה-ד'תת, מפיוטיו במחזור רומניה."},{"i":22925,"n":"יוסף הפייטן מצרפת","f":"יעקב","b":"פייטן בצרפת בזמן רש\"י. מפיוטיו במחזורי יון, קנדיא, פולין. חיבר \"ויושע ה' אום למושעות\"."},{"i":22926,"n":"יוסף הפייטן מצרפת","f":"מאיר","b":"פייטן מחכמי צרפת או אשכנז-שנות ה-תתק'. חיבר קינה \"ארמון נוטש עוזב טוב\" על שריפת התלמוד בפאריס."},{"i":22927,"n":"יוסף הפייטן מקרקשונא","f":"שלמה","b":"פייטן קדום, מפיוטיו \"אודך כי אנפת בי\", רש\"י הביא מפיוט זה בפירושו ביחזקאל, חיבר גם פיוט לחנוכה."},{"i":22928,"n":"יוסף הצדיק בן יעקב אבינו","dt":"א תמוז"},{"i":22929,"n":"יוסף הקטן מפאס","f":"שמואל הקטן","k":"בעל כתבי יוסף","b":"מחכמי פאס. הו\"ל ספר הישר - ונציה שפה, ובהקדמה מספר שהספר הזה הוא מירושלים בזמן החורבן והגיע לספרד ומשם לפאס."},{"i":22930,"n":"יוסף הרופא מקושטא","b":"רופא בקושטא-שנות ה-ת', מקורב למלכות. בנו - ר יעקב בעל \"שמן הטוב\"."},{"i":22931,"n":"יוסף זאב","b":"מו\"צ בסאספאלו-תר\"נ"},{"i":22932,"n":"יוסף זאב ממיפה","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":22933,"n":"יוסף זאב ממיפה=אמיופה ומז'ייק","bt":"תרמט","dt":"תשא","b":"רב באמיופה, רבה האחרון של מאזשייקה(=מז'ייק)."},{"i":22934,"n":"יוסף זונדל מבירז וקרוק","f":"יצחק מפומפיאן","k":"בעל זיר יצחק","dt":"תרנו","dp":"בירז","b":"רב בקרוק, יאנובה-תרכא, רב בבירז-תרכו כ-30 שנה ליד ר אשר ניסן לוינזון, ור פנחס לינטופ-רב קהילת החסידים, ואחרי פטירתו פרצה מחלוקת בקהלה. חיבר \"זיר יצחק\" וילנא תרלו. נכדו של ר אורי שרגא פיבוש רבה של ירושלים בשנים תטו-תכה. אביו ר יצחק מפומפיאן נפטר בירושלים בשנת תרלז. בראש ספרו מכתב מדודו זקנו - ר יוסף זונדל סלנט."},{"i":22935,"n":"יוסף זוסמן מואנדסבק","b":"מחכמי ואנדסבק - תק-תר בערך."},{"i":22936,"n":"יוסף זכריה מנדל מקראקא","f":"אריה ליב מפינטשוב","dt":"תקצה","b":"דיין בקראקא."},{"i":22937,"n":"יוסף זלמן (זלמוני) מאובן","b":"רב באובן-שנות ה-ש', ור דוד בן יעקב הכהן על מקומו אחריו."},{"i":22938,"n":"יוסף זלמן ממונקטש","b":"דומ\"צ במונקאטש"},{"i":22939,"n":"יוסף זעבל מטרנוב","f":"משלם פיבל","b":"רב בטרנוב. הוציא לאור \"לקוטים מרבנו בחיי\" למברג תרלו."},{"i":22940,"n":"יוסף חיים בן אליהו מבגדאד","f":"אליהו עבדאלה","k":"בעל בן איש חי","r":"ראש גולת בבל","bt":"ה'תקצד-ח","dt":"ה'תרסט","dp":"בגדד","b":"מספריו הנוספים של ה\"בן איש חי\" [בא\"ח, ר' יוסף חיים מבגדאד]: אבן שלמה; אדרת אליהו; אורח חיים; אות חיים; אם המלך; אמרי בינה; בן יהוידע; בן איש חיל; בניהו; ברכת אבות; ברכת חיים; גדולת חיים; דברי חיים; דעת ותבונה; דרושי חיים; חוקי הנשים [\"קאנון אל נסא\"]; חיים והשלום; חסדי אבות; כתר מלכות; מוסיף חיים; מים חיים; מלאך הברית; מקבצאל; משל ונמשל [משלים מלוקטים מספריו ע\"י רב\"צ חזן]; נחמת ציון; נפלאים מעשיך; סוד ישרים [שו\"ת בקבלה, נדפס בספרו רב פעלים]; עוד יוסף חי [הלכות, במתכונת הבא\"ח]; עטרת תפארת; קרן ישועה; רב ברכות; רב פעלים [שו\"ת]; שבת מלכתא; שיח חיים; שערי חיים; שפתי חיים; תורה לשמה [שו\"ת, בספר זה המחבר חתם בשם 'יחזקאל כחלי']; תיקון תפילה; תשובה מחיים. חיבר פיוטים רבים, מהם נדפסו בספריו, בסידורים ומחזורים לקהילת בבל, וכן בספרי פזמונים. פיוטו הידוע ביותר הוא \"ואמרתם כה לחי\".","bk":[["בן איש חי [הלכות",""],["בן איש חי - דרוש על התורה",""],["בן איש חיל",""],["בן יהוידע – אגדות הש\"ס",""],["בניהו – על אגדות הש\"ס",""],["הוד יוסף - שו\"ת",""],["רב ברכות",""],["רב פעלים – שו\"ת",""],["תורה לשמה – שו\"ת",""],["אבן שלמה",""],["אדרת אליהו",""],["אמרי בינה",""],["בן איש חי",""],["בן יהוידע",""],["בניהו",""],["דעת ותבונה",""],["נפלאים מעשיך",""],["סדר היום",""],["עוד יוסף חי",""],["רב פעלים",""],["שובי שובי השולמית",""],["שני אליהו",""],["תורה לשמה",""],["בן איש חי","הלכה ומנהג - אחרונים"],["רב פעלים (א",""],["רב פעלים","שו\"ת - אחרונים"],["תורה לשמה","שו\"ת - אחרונים"]],"e":"תקצ\"ה-תרס\"ט"},{"i":22941,"n":"יוסף חיים הכהן מאלגיר וירושלים","f":"יהודה","k":"בעל מנחת כהן","bt":"תריא","bp":"מוגאדיר (מרוקו)","dt":"תרפא - כב אלול","dp":"ירושלים","b":"מוצאו במוגאדור-מרוקו, רב בג'יריויל(=אל באייאד)-אלגיר. עלה לירושלים-תרכו ועמד בראש ישיבת \"טובי ישבעו\", היה אב\"ד ונשיא עדת המערבים. השתתף בקובץ \"המאסף\", חיבר \"מנחת כהן\" ירושלים תרסב. הניח בכת\"י שו\"ת עם חכמי דורו. הסכים על \"בני לוי\" תונס תרסד. כנראה הוא ר יהודה ממרוקו וירושלים שהיה בשליחות באלגיר. פרסם מאמרים ב\"המאסף\". מתלמידיו - חתנו ר עמרם אבורביע, ר יוסף שלוש."},{"i":22942,"n":"יוסף חיים הלוי מברוד","dt":"תקלח - טז תשרי","b":"רב בברוד"},{"i":22943,"n":"יוסף חיים מאישצא","b":"רב באישצא-תרכז."},{"i":22944,"n":"יוסף חיים מהולשיץ","k":"בעל משנת יוסף חיים","b":"מחכמי אוסטרהא, רב בהולשיץ-תקלז, אה\"ו. חיבר \"משנת יוסף חיים\" - בכתב יד. נזכר ב\"נודע ביהודה\" בדבר היתר עגונה בת ר שמואל שמלקא כץ מאוסטרהא - בזמן השריפה-תקלז וכתב קונטרס להיתר, וכנגדו כתב ר פיבש י\"ץ קונטרס לאיסור ושלחו דבריהם ל\"נודע ביהודה\" בפרג."},{"i":22945,"n":"יוסף חיים מספריסלב","dt":"תרלד - יא אייר","b":"רב בספריסלב"},{"i":22946,"n":"יוסף חיים מצפת","dt":"שעח","dp":"צפת","b":"מחכמי צפת, שליח במנטובה בשנת שע."},{"i":22947,"n":"יוסף חיים מקאליש","f":"אלכסנדר סנדר","b":"רב בקאליש-תק\"י"},{"i":22948,"n":"יוסף חיים משלוניקי","b":"מחכמי שלוניקי-שנות ה-ת'."},{"i":22949,"n":"יוסף חייניש מלבוב","f":"אברהם חייניש","dt":"תיח - כט טבת","dp":"לבוב","b":"ראב\"ד בלבוב. חתם-תכא עם ר אברהם גראפין (לפי בובר יש בלבול בינו לר יוסף בן אברהם חיות מלבוב)."},{"i":22950,"n":"יוסף חייקיס (חאווקיס) מאליק","b":"תלמיד הבעשט. דודו ורבו של ר אברהם חיים מזלוטשוב. מתורתו ב\"אורח לחיים\", ו\"אדני פז\". בנו ר בנימין וולף מלודמיר."},{"i":22951,"n":"יוסף חסיד הכהן","b":"מגדולי חכמי צפת-ש\"מ"},{"i":22952,"n":"יוסף יאסקי הלוי מיאס","f":"אריה ליב הלוי","dt":"תקסז - שבט","b":"רב ביאס"},{"i":22953,"n":"יוסף יאסקי מאולינוב","f":"יחיאל מיכל","k":"בעל אהל מועד","b":"רב באולינוב-תק\"י"},{"i":22954,"n":"יוסף יאסקי מאוסטרהא","f":"שמואל חעלמיר מאוסטרה","dt":"תקעב - כה שבט","dp":"אוסטרהא","b":"פרנס באוסטרהא, וגבאי בביהכ\"נ הגדולה. מבניו: ר צבי הירש."},{"i":22955,"n":"יוסף יאסקי מדובנא","f":"יהודה יידל-קול יהודה","k":"בעל יסוד יוסף","dt":"תסו - כט ניסן","dp":"דובנא","b":"נכד ר יוסף יוסקי מלובלין-נכד המהר\"ל מפרג. מקובל, רב בגליל מינסק, דובנא על מקום ר שמחה בן נחמן רפפורט ור שמואל בן שלום שכנא מקראקא על מקומו אחריו, (יש אומרים שר נחמן ליפשיץ רפפורט על מקומו אחריו - כנראה טעות). חתניו - ר ישראל בן שלום ז\"ק מבירז, ר אהרן סגל - אבי משפחת שטרשון."},{"i":22956,"n":"יוסף יאסקי מזולקוא","f":"נפתלי הרץ מלבוב","b":"מחכמי זולקוא, חתם-תיט על תקנה בזולקוא."},{"i":22957,"n":"יוסף יאסקי מזלאטוי","b":"רב בזלאטווי"},{"i":22958,"n":"יוסף יאסקי מלבוב","b":"רב וואדיסלב-תל\"ב"},{"i":22959,"n":"יוסף יאסקי מלובלין","f":"צבי הירש סבא","b":"נכד המהר\"ל. מגדולי חכמי דורו, רב בלובלין-תנ. בנו - ר צבי הירש סבטקא, ר שמואל מגניזין."},{"i":22960,"n":"יוסף יהודה לוי מאיטליה","b":"מחכמי איטליה, חיבר שיר-תצח לכבוד ר אליהו מנחם פואה שתרם בצוואתו להקמת בית מדרש."},{"i":22961,"n":"יוסף יהודה ליב המגיד מבאלטא","b":"תלמיד ר יעקב יוסף מפולנאה, והמגיד ממזריטש. ישב בגומבין, בילוצ'ורקוב, ברח בפרעות ההיידמאקים והגיע לבאלא ונהיה מגיד. נפל בשבי הקוזקים וניצל בנס. רב בשדה חדש. חיבר ספר שאבד. בנו ר שמעון מקונסטנטין-ליד לודז'."},{"i":22962,"n":"יוסף יהודה ליב מרחמיסטריבקא","b":"ראש העדה החסידית בטבריה-תרלה. מחדושיו בקובץ \"הפוסק\"."},{"i":22963,"n":"יוסף יהודה ליב משנדישוב","f":"ישראל איסר הלוי","k":"בעל אספת יהודה","b":"נכד ר דוד טבלי קלויזנר מבריסק, חיבר \"אספת יהודה\"-פפדא תקכג ובו אסיפה מכתבי זקנו."},{"i":22964,"n":"יוסף יהודה מאפטא וקראקא","b":"תלמיד הדברי חיים מצאנז. אב\"ד אפטא, קראקא."},{"i":22965,"n":"יוסף יהודה מבקשביץ","b":"רב בבקשביץ-תקלב"},{"i":22966,"n":"יוסף יהודה מפלטשין","b":"רב בפלטשין-תרכו."},{"i":22967,"n":"יוסף יהושע השל מלבוב","f":"בנימין","dt":"תיג - כד אד\"א","dp":"לבוב","b":"מרביץ תורה בלבוב."},{"i":22968,"n":"יוסף יוזביל שפרינץ","f":"שמואל","b":"חתם על פסק דין בפפד\"מ-שכד."},{"i":22969,"n":"יוסף יוזל מבינגא","b":"רב בבינגא-ת\"כ"},{"i":22970,"n":"יוסף יוזל מלעסלא","f":"זאב וולף מפרג","k":"בעל תפארת יוסף","b":"אב\"ד לעסלא. חיבר גם \"עטרת יוסף\" ובנו - ר מאיר מגלוגא הו\"ל את ספרו."},{"i":22971,"n":"יוסף יוזל מראסיין","f":"שלמה זלמן","dt":"תריב","dp":"ראסיין","b":"דיין בראסיין אצל ר דובער רבינוביץ."},{"i":22972,"n":"יוסף יוזפ מאויבר-וישעווא","b":"רב באויברווישעווע-תק\"פ"},{"i":22973,"n":"יוסף יוזפ מאוסטרהא","f":"פרץ","dt":"תעז - אחרי","b":"רב באוסטרהא-תפג. מרוזני ומנהיגי ועד ארבע ארצות. הסכים על \"דמשק אליעזר\" - יסניץ תפג, חתם רביעי עם מנהיגי ועד ארבע ארצות. אולי אביו הוא ר פרץ בן צבי מאוסטרהא. ב-תעז נרשם בפנקס ח\"ק ששלחו דבר להראש ר יוזפ ר פרץ'ס."},{"i":22974,"n":"יוסף יוזפא הכהן מאוסטרהא","f":"ישכר בר","dt":"תץ - יג אייר","dp":"אוסטרהא","b":"מחכמי אוסטרהא ומראשי הח\"ק על מקום אביו."},{"i":22975,"n":"יוסף יוזפא הכהן מדרמשטט","b":"רב בדרמשטט-ת\"כ"},{"i":22976,"n":"יוסף יוזפא כץ מווישיווה","b":"תלמדי ר משולם איגרא בטיסמניץ. חסיד ר מנחם מנדל מקוסוב. רבה הראשון של אויבר-ווישווה-תקף יחד עם ר חנוך זונדל פוגל (ושניהם לא נזכרו בפנקס הקהלה כרבנים - וכנראה שלא היה להם מינוי רשמי). מקורב לאדמורי קוסוב."},{"i":22977,"n":"יוסף יוזפא מאוסטרהא","f":"שמואל ר יעקב'ס מאוסט","k":"אברהם יוסף יוזפא,אוסטרר","dt":"תקכב - כא סיון","dp":"אוסטרהא","b":"גיסו של ר בצלאל הכהן מאוסטרהא. רב בלויצק על מקום אביו שעבר לאוסטרהא ובנו ר יוסף יואל על מקומו אחריו, עבר לאוסטרהא בעקבות אביו ופרש מהרבנות בגלל שהיה עשיר גדול, פרנס ומו\"צ באוסטרהא ופרנס מדינת ואהלין. עוד מבניו: ר יצחק איזיק פרנס באוסטרהא, ר נחמן פרנס באוסטרהא, ואולי גם ר אליעזר ליפמן שחתם \"מרדכי באב\"ד היילפרין\". כנראה שנוסף לו השם אברהם (בסוף ימיו היה חותם אברהם יוסף יוזפא). בנו - ר אהרן נפטר בחייו, ונכדתו שגדלה עמו נשאה לר אברהם משלם זלמן-בנו של החכם צבי (היה מחותן גם עם ר יעקב עמדן)."},{"i":22978,"n":"יוסף יוזפא מהמבורג","f":"דניאל","dt":"תקנב - כג אב","dp":"ואנדסבק","b":"חתן ר יוסף שיסר מואנסדבק. מחכמי ביהמ\"ד החדש בהמבורג-תקטז, דיין בואנדסבק-תקיא. חתם בהמבורג-תקמט על החרם כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג, היה אחד הדיינים - נציג ואנדסבק בהסכם קהלות אה\"ו-תקל - יחד עם היעב\"ץ ור ישעיה יפה. מתורתו ב\"אמתחת בנימין\". (באוצר הרבנים תאריך פטירתו כג אדר)."},{"i":22979,"n":"יוסף יוסל מוואין ובריסק","f":"דב בער","k":"בעל פורת יוסף","b":"נכד ר יהושע-אב\"ד קראקא. אב\"ד בוויאין(=ואיין)-ליד בריסק-תע, רב בבריסק. חיבר גם \"עטרת יוסף\" על ההגדה. בנו - ר אברהם יצחק מבריסק. בעל \"ארבע כוסות\" ו\"פשר דבר\"."},{"i":22980,"n":"יוסף יוסל מקאידנוב וירושלים","f":"יצחק","dt":"תרכג - יג אב","dp":"ירושלים","b":"רב בקאדינוב, עלה לירושלים."},{"i":22981,"n":"יוסף יוסלה הצדיק מראדוילישוק","b":"רבה הראשון של ראדוילישוק-ליד קובנא."},{"i":22982,"n":"יוסף יוסקא הלוי מרובנא","f":"יצחק מקונסטנטין","k":"בעל יסוד יוסף","dt":"תקס - יז אלול","b":"תלמיד המגיד ממזריטש, והמגיד מזלוטשוב. חתן ר אהרן מרובנא-תלמיד הבעשט. נפטר ללא ילדים. חיבר גם \"לקוטי יוסף\". בן אחיו ר משה אב\"ד איווניצא.","bk":[["יסוד יוסף – דרוש קבלה",""],["ליקוטי יוסף - חידושי סוגיות",""]]},{"i":22983,"n":"יוסף יוסקא מואלטשיסק","f":"מרדכי מקרמניץ","b":"נכד המגיד מזלטושוב. חתן ר משה חיים אפרים מסדילקוב בעל \"דגל מחנה אפרים\"."},{"i":22984,"n":"יוסף יוסקה","f":"אברהם דב","b":"נכד ר יעקב יוסף בעל \"תולדות יעקב יוסף\"."},{"i":22985,"n":"יוסף יוסקה בן יהודה יודל מדובנה","bt":"1659","dt":"ה'תסו 1706","bk":[["נעימה קדושה",""]]},{"i":22986,"n":"יוסף יעקב בן דובר","f":"דב בר","k":"בעל לבית יעקב","bt":"תר או תרח","bp":"טארוועג-קובנה","dt":"תרסב -ח-כד תמוז","b":"כונה ר יעקב זאגערער. תלמיד ישיבת וולוזין, ור ישראל סלנטר. רב בווילון-ליד קובנה-תרכח והקים שם ישיבה בשיטת המוסר. רב ביורבורג, זאגר חדש, וילנא-תרמג, היה דרשן נערץ בוילנא ונענה להצעת רבנות בניו יורק בגלל חובות שצבר. רב הכולל בניו יורק-תרמח בהמלצת ר יצחק אלחנן מקובנא, והיה במחלוקת עם תקיפים ובעל חזקה שהפריעו לו בנסיונותיו לארגון הקהלות בנ\"י. חיבר גם \"תולדות יעקב יוסף\", ועוד. תשובותיו בספרי חכמי דורו, ובהם \"אור שמח\", \"בנין שלמה\", ועוד. בהלוויתו ליווהו כמאה אלף יהודים, והוקמה ישיבה על שמו -ישיבת ר יעקב יוסף. נזכר ב\"במחיצתם של גדולי הדור\" לר יעקב מארק, נזכר גם ע\"י ר יונה לנדא ב\"דער איד\". חיבר גם \"תולדות יעקב יוסף\", ועוד. תשובותיו בספרי חכמי דורו, ובהם \"אור שמח\", \"בנין שלמה\", ועוד.","bk":[["לבית יעקב",""],["תולדות יעקב יוסף בניו יארק",""]]},{"i":22987,"n":"יוסף יעקב משלוניקי","dt":"תרמה","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":22988,"n":"יוסף יצחק הלוי מברודשין","b":"ראש ישיבה בברודשין."},{"i":22989,"n":"יוסף יצחק מגווזדיץ","b":"רב בגווזדיץ-תריח."},{"i":22990,"n":"יוסף ישועה","b":"מוזכר אצל ר יצחק אבוהב בספרו \"נהר פישון\" והביא חדוש ממנו."},{"i":22991,"n":"יוסף ישראל מוילנא","f":"פסח משניפישוק","dt":"תקפח - ב אדר","dp":"וילנא","b":"מחכמי וילנא."},{"i":22992,"n":"יוסף ישראל מפורלי","f":"אברהם","k":"בעל תולדות אדם","b":"רב בפורלי - מדינת רומאניה של האפיפיור. חיבר \"תולדות האדם\" בכת\"י ובו חלק \"חיי עולם\" המוזכר בספר המרדכי - הלכות קטנות תפלין."},{"i":22993,"n":"יוסף כץ (שפירא) מזולקוא","f":"יעקב מקראקא-באר מים","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":22994,"n":"יוסף כץ מאוסטרהא","f":"צבי סגל ש\"ץ מאוסטרהא","dt":"תקסב - יב אב","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":22995,"n":"יוסף כץ מזולקוא","f":"יעקב הקדוש","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":22996,"n":"יוסף כץ קראקוויר מזולקוא","f":"יעקב","b":"מחכמי זולקוא, חתם בפנקס הקהלה."},{"i":22997,"n":"יוסף ליב מאיזשאק","b":"רב באיזשאק-תקצ\"ד"},{"i":22998,"n":"יוסף ליב מהוסטומץ","b":"רב בהוסטומץ"},{"i":22999,"n":"יוסף ליב מעיר חדש","b":"ראב\"ד בעיר חדש-תר\"ב"},{"i":23000,"n":"יוסף מאדרינופול","f":"חיים","k":"בעל פירוש על אבות","b":"רב באדרינופול-שנות ה-ש'. חיבר פירוש למסכת אבות-שטו."},{"i":23001,"n":"יוסף מאויבן","k":"בעל זמירות ובקשות","b":"מגדולי אויבן-ת\"פ"},{"i":23002,"n":"יוסף מאויבן ופרג","b":"מרביץ תורה באויבן,פרג,אזמיר-תי\"ח"},{"i":23003,"n":"יוסף מאוסטרהא","f":"אלקנה הלוי","dt":"תקנז - יד שבט","dp":"אוסטרהא","b":"שמש הקהלה באוסטרהא. מבניו: ר ישראל איסר, ר יחזקאל."},{"i":23004,"n":"יוסף מאוסטרהא","f":"משה אריה המגיד ממזרי","dt":"תקפב","dp":"אוסטרהא","b":"בן הרב המגיד ממזריטש קטן. מחכמי אוסטרהא."},{"i":23005,"n":"יוסף מאוסטרוב","k":"בעל גלילי כסף","b":"דרשן,רב באסטרוב,פאריזאווא,ראב\"ד בסלונים-ת\"ר"},{"i":23006,"n":"יוסף מאופראן","f":"מימון","dt":"ד'קרנות המזבח","dp":"אופראן-ליד מוגדור","b":"מחכמי מרוקו הקדומים. נהרג עק\"ה ונקבר במערת חמישים הצדיקים."},{"i":23007,"n":"יוסף מאורליאנש -","f":"יצחק","b":"מבעלי התוספות בזמן רבנו תם, ונזכר אצלו."},{"i":23008,"n":"יוסף מאיישישוק וקריניק","dp":"קריניק","b":"תלמיד ר חיים מוולוזין. רב באיישישוק, בוליצע, קריניק."},{"i":23009,"n":"יוסף מאיר אברהם","b":"רב בטורוץ-תק\"נ,אנעווע"},{"i":23010,"n":"יוסף מאיר מגלינא","b":"מחכמי ברוד, רב בגלינא. חתנו - ר משה מינץ מפעסט. גיסו של ר משה יהושע השל שור בעל \"ים התלמוד (היו נשואים לשתי אחיות) והסכים על ספרו. נזכר בשו\"ת מהר\"ם מינץ."},{"i":23011,"n":"יוסף מאלגיר","bt":"ש","dt":"שס - בערך","b":"מחכמי אלגיר. שאלות ממנו מר אברהם ן טוואה ונזכר ב\"חוט המשולש\"."},{"i":23012,"n":"יוסף מאלמאשד","f":"ליב","dt":"תרטו - ז שבט","dp":"יארמוט","b":"רב באלמאשד(=אלמאש)."},{"i":23013,"n":"יוסף מאמשטרדם","b":"דיין באמסטרדם-ת\"פ"},{"i":23014,"n":"יוסף מאמשטרדם","f":"מנשה בן ישראל","dt":"ת - בערך","b":"הגיע מאמשטרדם ללמוד בלובלין ונפטר שם בגיל 20."},{"i":23015,"n":"יוסף מאפאטשני"},{"i":23016,"n":"יוסף מארץ ישראל","f":"יעקב הכהן","dt":"תקמו - ה סיון","dp":"אוסטרהא","b":"בשליחות קהילת החסידים בוואהלין - נפטר בשליחותו."},{"i":23017,"n":"יוסף מאשכנז","k":"ר' יוסף הארוך","b":"מגדולי מקובלי אשכנז-שנת ר'. חיבר פירוש לספר יצירה."},{"i":23018,"n":"יוסף מבאטאראטש","b":"דיין ושו\"ב וראש ישיבה בבאטאראטש - לפני השואה."},{"i":23019,"n":"יוסף מבאטושן","dt":"תרמח - ז ניסן","b":"רב בבאטושן"},{"i":23020,"n":"יוסף מבאייה","f":"מרדכי","b":"רב בבאייה-תקל על מקום ר פישל ור זקיל איבשיץ על מקומו אחריו."},{"i":23021,"n":"יוסף מבאלי דליטא","f":"חיים","b":"מוזכר ב\"כתנות עור\" כי חיבר פירוש לאסתר."},{"i":23022,"n":"יוסף מבורגוניא","b":"מחכמי ארץ ישראל על פי תלמיד הרמבן שביקר בארץ בשנת כז (1267) שראה את קברו בתחתית הכרמל."},{"i":23023,"n":"יוסף מביאלא","f":"יעקב","k":"ראה: הורביץ,יו","dt":"תקסג - כט אב","b":"רב בביאלא"},{"i":23024,"n":"יוסף מביאלה ולובלין","f":"יעקב מלוצק-כוכבי יעק","dt":"תקמג - כט תמוז","dp":"לובלין","b":"רב בלוצק, לובלין. נזכר ב\"תורת הקנאות\" ליעב\"ץ."},{"i":23025,"n":"יוסף מבינגשבורג","f":"נפתלי הרץ","b":"דיין בבינגשבורג-תתקנח, חתם עם ר יעקב יאקב מהמבורג על זכרון עדות - צוואת ר ליב כתריאל מינדן מהמבורג עבור אחייניו ר יצחק איזיק טרויב ור שלמה זלמן טריוב מקידאן."},{"i":23026,"n":"יוסף מבלגרד","f":"שלמה","b":"רב בבלגרד-שנות ה-ש'."},{"i":23027,"n":"יוסף מברדיטשוב","f":"מרדכי","k":"בעל מסורה ברורה","b":"חיבר מסורה ברורה-תקעח."},{"i":23028,"n":"יוסף מברוד","dt":"תקעא","b":"רב בבראדי-תקכ\"ו"},{"i":23029,"n":"יוסף מברזין וירושלים","f":"משה","dt":"תרכו - ג חשון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23030,"n":"יוסף מבריסק","f":"משה מפרמישלא","b":"נכד ר מיכאל יוזפוביץ (כנראה). רב בבריסק-שי."},{"i":23031,"n":"יוסף מברלין","f":"שלמה מליסא","k":"בעל יוסף אומץ","b":"אחיינו של ר יחיאל מיכל חסיד מברלין. תלמיד ה\"פני יהושע\" בברלין וכשעבר למיץ החליט עם 3 תלמידים לעבור עמו למיץ - והדפיסו \"מגילת תענית\" עם פירוש ר אברהם מקראקא - ברלין תצד - כדי לגייס כסף לנסיעתם."},{"i":23032,"n":"יוסף מברלין","f":"מורי בישיץ מפרג","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":23033,"n":"יוסף מברסלוי ולובלין","f":"דוד","dt":"תכט - ו ניסן","dp":"לובלין","b":"רב בברסלוי."},{"i":23034,"n":"יוסף מגרנוב","f":"יצחק יעקב מגרנוב","k":"אדמור מגרנוב","b":"חתן ר ישעיה שור מיאס בעל \"כליל תפארת\"."},{"i":23035,"n":"יוסף מדיאלטיטש","dt":"תריט - ד שבט","b":"תלמיד ר מרדכי מלכוביץ, בנו ר נח, ור משה מקוברין."},{"i":23036,"n":"יוסף מדמשק","f":"אליעזר בן יוסף הספרד","k":"בעל צפנת פענח","b":"מחכמי דמשק-שנות ה-ק' בזמן ר דוד בן יהושע הנגיד. חיבר פירוש לאבן עזרא-ספר הישר בשם \"צפנת פענח\" ונקרא גם \"אהל יוסף\"."},{"i":23037,"n":"יוסף מדרוהוביטש","b":"תלמיד הבעשט. אביו של ר ישראל נחמן מדרוהוביטש בעל \"פקודת המלך\"."},{"i":23038,"n":"יוסף מדרעזויצע","b":"רב בדרעזוויצע-תר\"מ"},{"i":23039,"n":"יוסף מהמבורג וברלין","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":23040,"n":"יוסף מואלקוניק","f":"מנחם מנדל מאלשאן","b":"אב\"ד ואלקוניק. אחיהם של - ר אברהם יצחק מוישנובה, ר משה מאלשאן."},{"i":23041,"n":"יוסף מוארשא","dt":"תרלב - כ אדר","b":"דומ\"צ בוורשה"},{"i":23042,"n":"יוסף מוילמשדורף ופיורדא","f":"יעקב","b":"מדפיס בדפוס חיים בן צבי הירש בפיורדא - תקל."},{"i":23043,"n":"יוסף מוילנא","f":"משה?","b":"חתן ר אברהם בלונקיש. רב-שנת ש\"נ. בניו - ר יהושע בעל \"מגיני שלמה\", הקדוש ר מרדכי מטומשוב, חתנו - ר שמואל שחור הורביץ."},{"i":23044,"n":"יוסף מוילנא","f":"אליהו ר\"ת","dt":"תעח - יב שבט","dp":"וילנא","b":"מראשי קהילת וילנא."},{"i":23045,"n":"יוסף מוילנא","f":"צמח","dt":"תקפג - טו סיון","dp":"וילנא","b":"מחכמי וילנא."},{"i":23046,"n":"יוסף מוילנא","f":"הלל מוילנא","b":"מראשי קהלת וילנא, חתם-תסח בפנקס הקהלה."},{"i":23047,"n":"יוסף מוילנא","f":"יעקב","b":"רב בוילנא, חתם-תמד על פסק דין עם ר שמואל בן מאיר, ר אהרן בן אברהם הלי הער, ר אריה לבי בן שמחה לבית אהרן."},{"i":23048,"n":"יוסף מוילנא","f":"אליעזר","b":"רב בוילנא, חתם-תסא עם ר הלל בן נפתלי הרץ מוילנא וקידאן."},{"i":23049,"n":"יוסף מוילנא","f":"מרדכי","b":"גביר מראשי קהלת וילנא, חתם-תנט על תקנות עם אחיו - ר עזריאל."},{"i":23050,"n":"יוסף מוילנא","f":"יצחק","b":"דיין בוילנא, חתם-תכד עם ר יצחק מפוזנא."},{"i":23051,"n":"יוסף מוילנא","f":"יהודה ליב","b":"חתן ר זלקינדמוילנא. מראשי קהלת וילנא. אחיו - ר שאול שישקעס. נקבר ליד ר אליהו פעסעלעס."},{"i":23052,"n":"יוסף מוילנא","f":"יואל","dt":"תקעג - יח כסלו","dp":"וילנא","b":"מחכמי וילנא."},{"i":23053,"n":"יוסף מוילקומיר","k":"בעל עקרי עבודה","bt":"תקסא","dt":"תרכא - כח כסלו","b":"מו\"צ בווילנה"},{"i":23054,"n":"יוסף מוילקומיר","f":"ישראל איסר","k":"בעל עיקרי הקרבנות","b":"רב בוילנא. תלמידו ר רפאל נתן נטע רבינוביץ ערך מכתביו את ספרו \"עיקרי הקרבנות\"- בפטרבורג תרכג (נדפס וילנא תרע)."},{"i":23055,"n":"יוסף מועקשנא","k":"בעל פורת יוסף","b":"הסכים על מאמר של ר יהודה יודל ברוידא ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":23056,"n":"יוסף מוערבוי","f":"אשר","b":"רב בוערבוי. ישב כדיין בבחירת ר אברהם וינר לרב בעיר חדש - עם ר יוסף צבי סגל מל\"ב מוערבוי, ור אליעזר מהלברשטט ושאכטיץ."},{"i":23057,"n":"יוסף מזאבלודוב","dt":"תריח - טו אדר","b":"רב בסקאקלקע, זאבלודוב. החזיק באוצר ספרים חשוב, ונזכר לשבח בהקדמת \"פתחי תשובה\" שהשתמש בספריו, מתורתו בספרי ר אברהם דב פלהאם."},{"i":23058,"n":"יוסף מזאמושץ","b":"רב בזאמוטשט-ת\"ק"},{"i":23059,"n":"יוסף מזבורוב","k":"בעל לקוטי יוסף","b":"רב בזבורוב. חיבר \"לקוטי יוסף\" למברג תרף."},{"i":23060,"n":"יוסף מזוויהל","f":"אברהם מוזויהל","b":"רב בזוויהל-תקכב על מקום אביו. אחיהם של ר שמשון מוילנא, ר ישראל?"},{"i":23061,"n":"יוסף מזולקוא","f":"משה","b":"מחכמי זולקוא, חתם-תקיא על החרם הגדול הנדפס ב\"לוחות העדות\"."},{"i":23062,"n":"יוסף מזולקוא","f":"יהודה ליב","b":"מחכמי זולקוא, חתם-תקם על תקנה שלא לתת שכירות למשרתי הקהלה ללא כתב מהקהל."},{"i":23063,"n":"יוסף מזוראניץ","b":"תלמיד הבעשט, והמגיד ממזריטש. אולי הוא ר יוסף מלמד מחמלניק."},{"i":23064,"n":"יוסף מזלוטשוב","b":"מחכמי זלוטשוב - תשובה אליו \"תפארת צבי\"."},{"i":23065,"n":"יוסף מזלישטשיק","b":"רב בזלישטשיק-תר\"ב"},{"i":23066,"n":"יוסף מזמיגראד (מרגליות)","f":"בנימין זאב יעקב","b":"בנו של אב\"ד זרנובצא וואלברום. נכד ר משה המבורגר מבנדין-גיסו של ר אלימלך מליזנסק. תלמיד ר יחיאל מיכל המגיד מזלוטשוב. מגיד מישרים בזמיגראד. עלה לארץ בסוף ימיו, וחתם בטבריה על אגרת-תקמט. אחיו ר אברהם מרדכי מפינטשוב."},{"i":23067,"n":"יוסף מזשמיגרד","f":"יעקב בנימין זאב","k":"הנכד","dt":"תקמט - אחרי","dp":"חברון","b":"מג\"מ בזמיגרוד-תקץ. (האם הוא נכד ר יוסף מזמיגרוד שנפטר בחברון?)"},{"i":23068,"n":"יוסף מחבר","f":"יעקב","b":"מחכמי חברון בזמן הגאונים. נמצא מכתב הממוען לשלה החזן המומחה ובו מאת עבדו יוסף בן יעקב המומחה החברוני בן סעדיה החבר בסנהדרין גדולה, המכתב מהמאה העשירית."},{"i":23069,"n":"יוסף מחברון","f":"סעיד","b":"מחכמי חברון-תלב, חתם עם רבני חברון על כתב שליחות ר חייא דיין."},{"i":23070,"n":"יוסף מחומסק ודראהיטשען","f":"יצחק מחומסק","k":"חומסקער עילוי","b":"מראשוני התלמידים בישיבת מיר. רב בדראהיטשען, ונכדו ר יהודה דוד גולדמן על מקומו אחריו (ואח\"כ בארה\"ב)."},{"i":23071,"n":"יוסף מחמלניק","dt":"תקנד - כט אב","b":"רב בפרגה"},{"i":23072,"n":"יוסף מטבריה","f":"יעקב","dt":"תקמב - ה סיון","dp":"אוסטרהא","b":"מחכמי טבריה, נמנה על קהילת החסידים, בשליחות באירופה ונפטר שם."},{"i":23073,"n":"יוסף מטבריה","f":"סימון","b":"רב בטבריה - בשנות ה-תק', שאלה ממנו ב\"חקרי לב\"."},{"i":23074,"n":"יוסף מטבריה","f":"צבי הירש כץ","b":"מחסידי טבריה-תקנה."},{"i":23075,"n":"יוסף מטבריה","f":"קהת","b":"מחכמי טבריה, מכתב ממנו-תרמצב אל פקידים ואמרכלים באמשטרדם."},{"i":23076,"n":"יוסף מטוטשין","dt":"תקמד - כה תמוז","b":"רב בטוטשין"},{"i":23077,"n":"יוסף מטיבערוב","f":"ישראל מלישניניץ","bt":"תקעב - אחרי","dt":"תרנו - אחרי","b":"מקורב לר ישראל מרוזין. מתורתו ב\"שמועות טובות\". תולדותיו ב\"צבי לצדיק - סאווראן\"."},{"i":23078,"n":"יוסף מטיקטין","b":"דיין בטיקטין"},{"i":23079,"n":"יוסף מט'ליק","dt":"תרכח - ח אייר","b":"רב בט'ליק,טשאטה"},{"i":23080,"n":"יוסף מטעפלפאלי","b":"רב בטעפלפאלי-תק\"מ"},{"i":23081,"n":"יוסף מטרוויש","f":"יהודה החזן","k":"בעל ידידות","b":"נכד ר ברוך. מגדולי חכמי צרפת בטרוייס(=טרוויש) בזמן ר שמואל מאיברא-שנות ה-ד'תתק. נזכר ב\"מנחת יהודה\" שחיבר ספר דקדוק בשם \"ידידות\"."},{"i":23082,"n":"יוסף מטשהרין","b":"מו\"ץ בטשהרין. פרסם מאמרים ב\"מכילתא דרבנן\" - אודסה תרמו."},{"i":23083,"n":"יוסף מטשיטש","b":"רב ברישא, טשיטש."},{"i":23084,"n":"יוסף מטשערקוב וצפת","dt":"תקצז","dp":"צפת","b":"מחכמי צפת. נהרג ברעידת האדמה-תקצז."},{"i":23085,"n":"יוסף מיאנוב","f":"ישאל","b":"רב ביאנוב-תקפג. חתן בעל \"אריה דבעי עילאי\""},{"i":23086,"n":"יוסף מיאקובשטט","f":"מרדכי","bt":"תקעא","dt":"תרנח","b":"שו\"ב ומו\"ץ ביאקובשטט כ-50 שנה. הניח חיבור בכת\"י."},{"i":23087,"n":"יוסף מיונגהיים","b":"מחכמי אשכנז. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":23088,"n":"יוסף מימפולא - א","f":"המגיד מזלוטשוב","dt":"תקעב - כד טבת","b":"חתן ר מנחם מאן מויטקוב - רבו של אביו. פגש בילדותו את הבעשט. מנשיאי א\"י ו\"כולל וואהלין\". אחד מ\"חמשה חומשי תורה\" - כפי שכונו בני המגיד מזלוטשוב."},{"i":23089,"n":"יוסף מימפולא - ב","k":"ר' יוסף מיאמפלי"},{"i":23090,"n":"יוסף מיפו","bt":"תרמב","dt":"תרצב - ט כסלו","b":"מרביץ תורה ביפו"},{"i":23091,"n":"יוסף מירושלים","f":"גדליה בן עמנואל","b":"מחכמי ירושלים, ראש בית הדין בשנים רכז-ח. י. הקר פרסם בספר \"שלם\" מכתב שלו לר משה הכהן בקנדיא."},{"i":23092,"n":"יוסף מירושלים","f":"רא\"ג","b":"מחכמי ירושלים-תסה, חתם אז על מכתב רבני ירושלים כנגד אנשי ר יהודה החסיד."},{"i":23093,"n":"יוסף מירושלים","f":"אברהם","dt":"תקעט - יו אב","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23094,"n":"יוסף מירושלים","f":"מרדכי","dt":"תרה - יט שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23095,"n":"יוסף מירושלים ומצרים","f":"יוסף","b":"מחכמי ירושלים בשנת תמ. דיין אצל ר משה גלנטי וחתום על פסקים, עבר למצרים והיה מקורב לר מרדכי הלוי בעל \"גינת ורדים\". מתשובותיו בספר \"גינת ורדים\" ו\"זרע אברהם\" ו\"חוט המשולש\"."},{"i":23096,"n":"יוסף מלאסק","f":"שמעון מלאסק","b":"מחכמי לאסק. נכד(-אבי אביו) ר איצק גאלדעס מלאסק. בניו - ר אברהם אליעזר דמשק מלאסק, ר זאב וולף. חתניו: ר חננאל מלוטימורסק, ר ישעיה הכהן מסטושין."},{"i":23097,"n":"יוסף מלבוב","f":"שמואל","dt":"שנו - כט אייר","dp":"לבוב","b":"ר\"מ בלבוב."},{"i":23098,"n":"יוסף מלבוב","f":"יצחק","dt":"תכ - כא תשרי","dp":"לבוב","b":"מרביץ תורה, דיין בלבוב, חתם-ת על מכירת קרקע, על קיום חתימות-תיב, ועוד."},{"i":23099,"n":"יוסף מלבוב","f":"יחיאל","dt":"שצב - ו חשון","dp":"לבוב","b":"רב בלבוב."},{"i":23100,"n":"יוסף מלבוב","f":"מנחם מאניש","dp":"לבוב","b":"ר\"מ וראב\"ד בלבוב. חתם-תצט על פס\"ד, על העתק פס\"ד-תקכח בזמן ר חיים רפפורט, ועוד הרבה. אחיו - ר יצחק מלבוב."},{"i":23101,"n":"יוסף מלבוב","f":"ברוך","dt":"תעז - כט טבת","dp":"לבוב","b":"דיין בלבוב."},{"i":23102,"n":"יוסף מלבוב","f":"מאיר","b":"מחכמי לבוב, חתם-שצט עם ר מאיר א\"ש הלוי."},{"i":23103,"n":"יוסף מלבוב","f":"אלכסנדר מאופלה ש\"ץ","k":"יוסף ר סענדרש","b":"דיין בלבוב, חתם-תג בפנקס הקהלה."},{"i":23104,"n":"יוסף מלבוב","f":"נתן נטע","b":"מנהיג בלבוב, חתם-תקד על כרוז ותקנה, ועוד."},{"i":23105,"n":"יוסף מלוב","f":"שמואל בן אפרים","b":"סופר מאזור הר נפוסה-לוב - בשנים ד'תתקס-תתקע. העתיק מסכת כריתות. עליו ב\"עזים נתיבה\" תשמח."},{"i":23106,"n":"יוסף מלובלין","b":"רב בלובלין-ת\"ר"},{"i":23107,"n":"יוסף מלובלין","k":"יוסף לובלינער","b":"תלמיד החוזה מלובלין, ור שמחה בונם מפשיסחא. נקרא גם \"יוסף הגדול\"."},{"i":23108,"n":"יוסף מלובלין","f":"אריה ליב דיין","k":"הו\"ל קיצור אלשיך","b":"מחכמי לובלין."},{"i":23109,"n":"יוסף מלובלין","f":"שמעון דאקטאר מקראקא","dt":"תקסו - א אלול","dp":"לובלין","b":"נפטר צעיר."},{"i":23110,"n":"יוסף מלובלין וייסלינג וביחוב","f":"אריה ליב (קלויזנר)","k":"בעל חותם ה'","b":"נכד ר זכריה מנדל קלויזנר מבלז. רב בייסלינג, ביחובא, דיין בלובלין-תק. (מצאצאי - \"ר ליב דער הויכער\")."},{"i":23111,"n":"יוסף מלובמעלא","b":"רב בלובמעלא-תקי\"ב"},{"i":23112,"n":"יוסף מלוניל","k":"ר' יוסף בעל שמועות","b":"מגדולי חכמי לוניל-שנת מ'"},{"i":23113,"n":"יוסף מליאון ונציה","b":"רב בונציה. הסכמה ממנו בשו\"ת מהריט\"ץ."},{"i":23114,"n":"יוסף מלידא ופרשבורג","f":"ישעיה","b":"נכד ר אפרים רעדש. רב בליסא, עבר לפרשבורג."},{"i":23115,"n":"יוסף מליובאויטש","f":"ישכר דב","b":"תלמיד בעל התניא, בנו ר דב בער, ונכדו ר מנחם מנדל. נחשב לאחד מחשובי החסידים והיה \"משולח\" לאסוף את כספי הכולל. כונה \"הרב הקדוש\" על ידי החסידים."},{"i":23116,"n":"יוסף מלייטציץ","f":"יצחק","dt":"תרכח","dp":"ירושלים","b":"רב בלייטציץ, עלה לירושלים ונמנה על חכמיה"},{"i":23117,"n":"יוסף מלינאווסכי הקראי","f":"מרדכי","k":"בעל חזוק אמונה","b":"תלמיד ר יצחק בן אברהם מטרוקי בעל \"חזוק אמונה\". מחכמי הקראים בטרוקי-שנד, השלים את ספר רבו \"חזוק אמונה\". חיבר קיצור הלכות שחיטה, פירושים, וסדר מנהגי תפלות לקראים בליטא ופולין, ופיוטים."},{"i":23118,"n":"יוסף מליסא","b":"תלמיד החת\"ס. קיבל סמיכה ותואר חבר מהחת\"ס."},{"i":23119,"n":"יוסף מליסקווע","k":"בעל עטרת יוסף","b":"מקובל,רב בליסקווע-תק\"כ"},{"i":23120,"n":"יוסף מלמד מחמלניק","b":"תלמיד הבעשט."},{"i":23121,"n":"יוסף מלעשנוב","f":"שלמה זלמן מביאלא","b":"רב בלעשנוב(=לשנוב)-תק\"כ"},{"i":23122,"n":"יוסף מלקנבך","b":"רב בלקנבך-ת\"צ"},{"i":23123,"n":"יוסף ממאריאמפול","f":"יהודה","b":"רב במאריאמפול."},{"i":23124,"n":"יוסף ממגנצא","b":"מחכמי מגנצא(=מיינץ). חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":23125,"n":"יוסף ממונסטיר","f":"משה","b":"מחכמי מונסטיר(=מונאשטיר) ומראשי העדה-שנות ה-ת'."},{"i":23126,"n":"יוסף ממינסק","f":"זכריה מנדל","dt":"שבט","dp":"לובלין","b":"רב במינסק, סלוצק ועוד קהילות. נזכר ב\"מראות הצובאות\" לר משה זאב מטיקטין. בנו ר זכריה מנדל מלובלין"},{"i":23127,"n":"יוסף ממיקולייב","f":"דוד ממיקולייב","b":"בנו של אחד מחסידיו הראשונים של הבעשט. חתן ר זאב וולף קיצעס ממזבוז. אביו של ר עקיבא ממיקולייב."},{"i":23128,"n":"יוסף ממצרים","f":"מנשה","b":"דיין ברשיד-שנות ה-ת' אצל ר דוד גרשון, יחד עם ר שמואל נחמיאש ור יוסף סורמאני."},{"i":23129,"n":"יוסף ממרוקו","f":"עמרון או עמראן","b":"גביר ומשורר מחכמי מרוקו, תמך בר אברהם ן עזרא בהיותו במרוקו, שחיבר שיר הספד עליו לאחר פטירתו."},{"i":23130,"n":"יוסף ממרסיליה","b":"מחדושיו ב\"מטה משה\"."},{"i":23131,"n":"יוסף ממרשיליא","b":"מחכמי צרפת שעלה לירושלים, מוזכר באגרת ר יצחק חילו משנת צג (1333), לדעת כרמולי הוא הנזכר בשות הרן סימן לח."},{"i":23132,"n":"יוסף מנדיל מטיווה","b":"רב בטיווה(=תבץ)-שנות ה-ש'."},{"i":23133,"n":"יוסף מנוברדוק ובריסק","b":"מחכמי נוברדוק, ראב\"ד בבריסק."},{"i":23134,"n":"יוסף מנחם","bt":"תרכ","dt":"תרצ","b":"רב במסלאתה-טריפולי"},{"i":23135,"n":"יוסף מנחם הלוי מקורפו","k":"בעל אגדת פרחים","dt":"תרמז - לפני","b":"מו\"ץ בקורפו. קינה לזכרו מאת ר מימון וינטורה - אלכסנדריה תרמז."},{"i":23136,"n":"יוסף מניקולא","b":"מחכמי איטליה-רנ. נזכר ב\"שלטי הגבורים\", \"מנחת יהודה\" לר יהודה בן אלעזר, ופסקים ממנו ב\"אוצרות חיים\"."},{"i":23137,"n":"יוסף מניקלשבורג","b":"דיין בבלגרד-תצ\"ז"},{"i":23138,"n":"יוסף מנמירוב","k":"בעל ויכוחא רבא","b":"תלמיד ר לוי יצחק מברדיטשוב."},{"i":23139,"n":"יוסף מנעשוויז","b":"מרביץ תורה בנעשוויז-תרמ\"ג"},{"i":23140,"n":"יוסף מנשה מבלגרד","b":"בשליחות קהלת בלגרד-תסא באמשטרדם יחד עם ר יוסף מתתיה - כדי לסייע בעדם בפדיון שבויים."},{"i":23141,"n":"יוסף מסוואלק וירושלים","f":"אברהם","dt":"תרל - יד טבת","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23142,"n":"יוסף מסטניסלבציק","b":"רב בסטניסלבציק-תרלד."},{"i":23143,"n":"יוסף מסטעפין","f":"חיים משה מסטעפין","b":"בן האדמור מסטעפין. חתן ר יצחק יעקב מגראנוב (זלוטשוב)."},{"i":23144,"n":"יוסף מסטרליסק","b":"רב בסטרליסק"},{"i":23145,"n":"יוסף מסמרגון","f":"אהרן","dt":"תרך - טז ניסן","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23146,"n":"יוסף מסמרגן","b":"רב בסמרגן-תק\"נ"},{"i":23147,"n":"יוסף מסעניץ","b":"רב בשארוואר,סעניץ-תק\"י"},{"i":23148,"n":"יוסף מעשאוו","f":"דוד","k":"בעל מבין חידות","b":"מחכמי האג-הולנד-תקכה."},{"i":23149,"n":"יוסף מפאס","f":"שמואל","k":"בעל כתונת יוסף","b":"רב בפאס בזמן בעל \"מדבר יהודה\". חיבר \"כתונת יוסף\", הגיע לליוורנו כדי להדפיס את ספריו."},{"i":23150,"n":"יוסף מפדובה","f":"חיים","b":"נזכר בספר זכרון נשמות גאוני פדובה."},{"i":23151,"n":"יוסף מפדובה","k":"בעל פירוש להגדה","b":"חיבר פירוש להגדה - ונציה שסא. הו\"ל ספרים ומדרשים עם הגהותיו יחד עם הסופר ר מאיר מפדובה."},{"i":23152,"n":"יוסף מפודואליטשיק","f":"מרדכי מקרמניץ","b":"רב בפודוואליטשיק-ת\"ר"},{"i":23153,"n":"יוסף מפולין","f":"משה","k":"בעל כתונת יוסף","b":"חיבר \"כתנת יוסף\", \"כתנת פסים\" ועוד."},{"i":23154,"n":"יוסף מפילוב","b":"תלמיד ר מנחם מנדל מקוצק, וחדושי הרי\"ם."},{"i":23155,"n":"יוסף מפינטשוב","f":"יעקב","k":"בעל ראש יוסף","b":"תלמיד ר צבי הירש מלובלין. חתן ר משה קרמר מוילנא-זקנו של הגר\"א ועבר לשם, רב בפינטשוב-תם, אב\"ד קוסוב(=קאסאווי)-תמח, סעלץ וראש ישיבה, המבורג-תסב, עבר לברלין והדפיס שם את ספרו \"ראש יוסף\"-תעו. בנו - ר יעקב בעל \"זרע ישראל\"."},{"i":23156,"n":"יוסף מפינטשוב (שידלוב)","f":"יהודה ליב מראקוב","b":"חתן ר אברהם מרדכי הלפרין מזולקווא. רב בפינטשוב-תק."},{"i":23157,"n":"יוסף מפינסק","b":"מקובל,רב בפינסק-קרלין-ת\"ר"},{"i":23158,"n":"יוסף מפיסטין","b":"רב בפיסטין, בוארשא - תשובה אליו טוט\"ד."},{"i":23159,"n":"יוסף מפלאטא","dt":"תקלה - ז חשון","b":"רב בפלאטא"},{"i":23160,"n":"יוסף מפליזא","f":"יום טוב מפליזא","b":"מגדולי בעלי התוספות,מחכמי צרפת-ד'תתק\"ס"},{"i":23161,"n":"יוסף מפלניקרוב וארץ ישראל","b":"עלה לארץ, חתם-תקמט על מכתב."},{"i":23162,"n":"יוסף מפמורן","b":"רב בפמורן-תריח."},{"i":23163,"n":"יוסף מפרג","b":"מגדולי חכמי פרג-ש\"ס"},{"i":23164,"n":"יוסף מפרג","dt":"שצז","b":"גדול חכמי דורו,רבה של פרג"},{"i":23165,"n":"יוסף מפרג","f":"ישכר","k":"בעל יוסף דעת","b":"רב בפרג. תלמיד ר מרדכי יפה, והמהר\"ל. חיבר \"יוסף דעת\" פרג שסט, חיבר פירוש על \"בחינת עולם\" ו\"עול\"י עין\" על עין יעקב."},{"i":23166,"n":"יוסף מפרמישלא","f":"משה","k":"בעל כתנת פסים","dt":"תסג","b":"דרשן,דיין בפרמישלא-תמ\"ה,עבר לברלין. רב בפרמישלא בזמן בעל \"מגן אברהם\". חיבר \"כתנת פסים\", \"כתר יוסף\", \"צפנת פענח\" ועוד."},{"i":23167,"n":"יוסף מפרנעלא","b":"רב בפרנעלא-תק\"צ"},{"i":23168,"n":"יוסף מפרשבורג","b":"סופר, שוחט ושמש בפרשבורג, חתם-תקפו על צוואת ר דוד לביאוס."},{"i":23169,"n":"יוסף מצפת","f":"משה מסווירז","k":"וירניק מפיסטין","b":"סבו של המגיד מזלוטשוב. עלה לצפת."},{"i":23170,"n":"יוסף מצפת","f":"יוסף ברוך בנדיט","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי."},{"i":23171,"n":"יוסף מצרפת","f":"ברוך","b":"מחכמי צרפת-שנות ה-ד'תתק, עלה לירושלים עם אחיו ר מאיר-ד'תתקעא. חיבר פיוט \"אבואה בתחנון\", נזכר בתוספות על התורה."},{"i":23172,"n":"יוסף מצרפת משרטר","f":"נתן","k":"בעל יוסף המקנא","b":"מחכמי צרפת-שנות ה-ק', אולי הוא ר יוסף משרטרס - גיסו של ר יוסף בן נתן מעטאמפ הנזכר בסמ\"ג. חיבר פיוט \"אלקים בעלונו אדונים זולתך\" על גזירות יורק-אנגליה-1191, חיבר \"יוסף המקנא\" ובו תשובות לטענות הנוצרים ונקרא גם ספר הנצחון. ר צדוק הכהן מפאריס חיבר עליו ספר בצרפתית."},{"i":23173,"n":"יוסף מקאם","b":"מגדולי הראשונים בצרפת בעיר קאם-ד'תתק\"ס"},{"i":23174,"n":"יוסף מקאמין","b":"רב בקאמין-תר\"מ"},{"i":23175,"n":"יוסף מקוברין וקידאן","b":"מחכמי קידאן בזמן גזירות תח ותט (כך בספר ליטא - לפי פין בשנת תנח). חיבר \"סליחות\" לזכר המאורעות - ונהגו לאמרם בכל הקהילות בליטא וזאמוט."},{"i":23176,"n":"יוסף מקולבסוב","b":"רב בקולבסוב-תק\"מ"},{"i":23177,"n":"יוסף מקוסוב והמבורג","f":"יעקב מפינצ'ב","k":"בעל ראש יוסף","b":"חתן ר משה קרמר מוילנא?. תלמיד ר צבי הירש מלובלין. רב בקוסובה, סלץ. ברח להמבורג-תסב בזמן פלישת השבדים לליטא ופולין. חיבר \"ראש יוסף\" - אמשטרדם תס."},{"i":23178,"n":"יוסף מקושטא","f":"שלום","b":"ממונה על החזקות בקושטא-שס עם חבריו ר משה משלם הלוי, ר יום טוב ן יעיש ועוד."},{"i":23179,"n":"יוסף מקושטא","f":"שאלתיאל","b":"דיין בקושטא-תקסו עם ר שמואל חיים ור אברהם בן דוד"},{"i":23180,"n":"יוסף מקינון - א","b":"מגדולי חכמי צרפת הראשונים,מרביץ תורה בקינון-שנת כ'"},{"i":23181,"n":"יוסף מקינון - ב","f":"נתנאל","b":"מגדולי חכמי צרפת-ד'תתק\"פ. בניו: ר משה הפרחי, ר נתנאל הפרחי ור יעקב הפרחי."},{"i":23182,"n":"יוסף מקלוש","f":"יצחק","b":"רב בקלוש-תרכב."},{"i":23183,"n":"יוסף מקלן","f":"יצחק לוי","b":"מחכמי קלן. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":23184,"n":"יוסף מקלצק","b":"מו\"צ בקלצק-תר\"י"},{"i":23185,"n":"יוסף מקמינקא","f":"ישכר בער","k":"בעל רמוני זהב,קאמינקער","dt":"תקנב - אחרי","b":"רב בקאמינקא-תקל, תלמיד הבעש\"ט. אמו הצדקת ריבעלע מסטנוב \"די פרימע ריבעלע\". חתן ר דוד מרבינו, ובזיוו\"ש חתן גיסו ר בן ציון קמינקא. לפי המסורת הוא אשר קירב את גיסיו \"האחים הקדושים מקמינקא\" אל הבעשט. בנו ר צבי-חתן ר גדליה מליניץ. אחיו - ר יצחק-סופר סתם מפולנאה."},{"i":23186,"n":"יוסף מקמניץ","f":"חיים מקמניץ","b":"רב בקמניץ על מקום אביו, ובנו ר צבי הירש על מקומו אחריו. בנו גם - ר יואל."},{"i":23187,"n":"יוסף מקראקא","f":"משלם פיבש מקרקא","dt":"תח - יט אלול","b":"דיין בקראקא, גבאי צדקה של א\"י, נפטר בדרכו לארץ. אחיו - ר שמואל מפרמישלא."},{"i":23188,"n":"יוסף מקראקא","dt":"תרפד - ח תשרי","b":"ראב\"ד בקרקא"},{"i":23189,"n":"יוסף מקראקא","b":"רב בקרקא"},{"i":23190,"n":"יוסף מקראקא","f":"ישעיה מנדל ר אביגדור","dt":"שצא - כ אדר","dp":"קראקא"},{"i":23191,"n":"יוסף מקראקא","b":"חתן ר משה אוירבך מקראקא. פו\"מ בקראקא. בנו - ר ישראל איסרל מקראקא-אביו של הרמ\"א."},{"i":23192,"n":"יוסף מקרמניץ","f":"משה הקדוש","k":"בעל ביאור לסמ\"ג","b":"תלמיד הרמ\"א, ר ישראל בן ר שכנא, ר יצחק הכהן, ר מרדכי מרדוש מאוסטרהא, מהרש\"ל. פסק במחלוקת המקוה ברוויגו להתיר. חיבר ביאור לסמ\"ג."},{"i":23193,"n":"יוסף מראסיין","f":"אליקום","dt":"תרם - יב אייר","dp":"ראסיין","b":"שו\"ב בראסיין."},{"i":23194,"n":"יוסף מראשקוב","f":"שבתי מראשקוב","k":"אדמור מראשקוב","dt":"תקף - ה אדר","b":"מחשובי תלמידי ר פנחס מקוריץ, ומוזכר בכתבי תלמידיו."},{"i":23195,"n":"יוסף מרדוויל","f":"אליעזר","b":"פרוש,רב בראדוויל-תר\"נ"},{"i":23196,"n":"יוסף מרדכי הלוי מירושלים","f":"אשר אברהם הלוי","bt":"תרלה-ח","bp":"ירושלים","dt":"תשז - טו אלול","b":"לאחר שנתייתם גדל אצל ר יוסף רפאל עוזיאל-הראב\"ד בירושלים. חתן הגביר ר יצחק רפאל יצחק. ר\"מ בביהמ\"ד לרבנים של חברת \"העזרה\" על מקום ר בן ציון עוזיאל - שעבר ליפו, ראב\"ד בירושלים. פסק דין ממנו בענין צוואת השר בנין נדפס ב\"פני דוד\" לר דוד פאפו."},{"i":23197,"n":"יוסף מרדכי מסאבטיטש","b":"רב בסאבאטיטש-תקי\"ג"},{"i":23198,"n":"יוסף מרוהטין","b":"רב ברוהטין-תריג."},{"i":23199,"n":"יוסף מרומסיסוק וירושלים","f":"יהודה","dt":"תרל - טו שבט","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23200,"n":"יוסף מריהרדק","b":"רב ברייהרדק-תר\"ע"},{"i":23201,"n":"יוסף משה אברהם מלאזדיי","k":"בעל צוואה","dt":"תקפג - יד אייר","b":"מ\"מ ומו\"צ בלאזדיי-פלך סובאלק. מכתביו נדפס \"צוואה\" - וארשא תרה."},{"i":23202,"n":"יוסף משה המגיד ממזבוז","b":"תלמיד הבעשט. חתם עם הבעשט על גביית עדות שנשלחה לר מאיר מקונסטנטין וחתם - יוסף משה. מתורתו ב\"תולדות יעקב יוסף\"."},{"i":23203,"n":"יוסף משה מאפושטג","b":"רב ניאולוגי באפושטג-1768 כיובל שנים."},{"i":23204,"n":"יוסף משה מקומרנא","f":"אליעזר מאוסטרהא","dt":"תקסא - בערך","b":"רב בקומרנא."},{"i":23205,"n":"יוסף משה מקרוסנא","f":"חיים מקרוסנא","k":"אדמור מקרוסנא","b":"מתלמידי ר פנחס מקוריץ. קיבל כתב רבנות מר מנחם נחום מטשרנוביל ור יעקב שמשון משפיטובקא. הניח חבורים בכת\"י."},{"i":23206,"n":"יוסף משה מרימנוב","b":"ראב\"ד רימנוב."},{"i":23207,"n":"יוסף משה משארוואר","f":"אפרים פישל","b":"רב בשארוואר-תק\"צ"},{"i":23208,"n":"יוסף משה משלוניקי","dt":"תקי","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":23209,"n":"יוסף משה משלוניקי","dt":"תרא","dp":"שלוניקי","b":"דיין בשלוניקי."},{"i":23210,"n":"יוסף משוואקשנא","f":"טוביה","b":"רב בשוואקשנא. מתורתו ותורת בנו-ר טוביה - בספר נכדו - ר יוסף רבינוביץ-דיין בקובנא בעל \"בית יוסף האחרון\" - בכת\"י."},{"i":23211,"n":"יוסף משטראויץ","b":"רב בשטראוויץ-תר\"ל"},{"i":23212,"n":"יוסף משידלוב","b":"רב בשידלוב, בריגל."},{"i":23213,"n":"יוסף משידלובצא","k":"בעל שארית יוסף","b":"תלמיד ר מנחם מנדל מקוצק. אב\"ד שידלובצא."},{"i":23214,"n":"יוסף משלוניקי"},{"i":23215,"n":"יוסף משלוניקי","f":"שלמה יחיאל","k":"בעל בני יוסף","dt":"תפד","dp":"שלוניקי","b":"רב ודרשן בשלוניקי-תמ."},{"i":23216,"n":"יוסף משלוניקי","f":"פרחיה הכהן משלוניקי","b":"מחכמי שלוניקי, חתם על הסכמות הקהל-שמד."},{"i":23217,"n":"יוסף משלוניקי","f":"דוד","k":"בעל צמח דוד","dt":"תקלא","dp":"שלוניקי","b":"נכד ר יוסף דוד-מהרי\"ד וחיבר הקדמה לספרו \"יקרא דשכבי\" יחד עם בן דודו - ר מיכאל יוסף. רב בשלוניקי."},{"i":23218,"n":"יוסף משלוניקי","f":"שמואל יוסף משלוניקי","dt":"תרסד","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של הדיין בנבנישתי שמואל משלוניקי."},{"i":23219,"n":"יוסף מתימן","f":"מצליח","k":"בעל ספר הזכרון","b":"מחכמי תימן-תק\"נ"},{"i":23220,"n":"יוסף מתתיה מבלגרד","b":"בשליחות קהלת בלגרד-תסא באמשטרדם יחד עם ר יוסף מנשה - כדי לסייע בעדם בפדיון שבויים."},{"i":23221,"n":"יוסף נחום ממצרים","b":"מחכמי אל-מנצורה-מצרים-שנות ה-ת'."},{"i":23222,"n":"יוסף נחמיה","b":"רב בסטאשוב"},{"i":23223,"n":"יוסף נתנאל מקושטא","b":"מראשי הקהלה האשכנזית בקושטא-שנה, עם ר שמריה הלוי."},{"i":23224,"n":"יוסף סגל מלבוב","f":"ירוחם בן יוסף מבלז","b":"חתם בלבוב-שפג על תקנות קהלת זולקווא, חתמו עמו - ר אברהם בן ישראל יחיאל רפפורט שרנצל, ר בנימין בן אליעזר מלבוב, ר אברהם בן יואל קצנלנבוגן."},{"i":23225,"n":"יוסף סגל מלבוב","f":"נתן נטע","b":"מראשי קהלת לבוב, חתם-תקד על תקנה."},{"i":23226,"n":"יוסף ספראוידליוער מפיסטין","f":"משה מסווירז הי\"ד","dp":"ארץ ישראל","b":"חברו של הבעשט. עלה לארץ."},{"i":23227,"n":"יוסף עוזיאל מאזמיר","dt":"תקיב - יז ניסן","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":23228,"n":"יוסף עזרא משלוניקי","k":"בעל משא מלך","b":"מחכמי שלוניקי-שן. חיבר שו\"ת, ו\"משא מלך\" - על הלכות מסים."},{"i":23229,"n":"יוסף עזריאל מגוליגור","b":"רב בגוליגור-תר\"כ"},{"i":23230,"n":"יוסף עלי מירושלים","b":"מחכמי ירושלים ומראשי העדה בזמן פרעות אבן פארוך."},{"i":23231,"n":"יוסף פייטן קדום","f":"אברהם אבן נ\"א ק\"ר","b":"חיבר שיר היחוד."},{"i":23232,"n":"יוסף פרידל","f":"שמרל מווארחיבקא","dt":"תקנא","b":"בנו של תלמיד הבעשט שעמד בראש עדת חסידים."},{"i":23233,"n":"יוסף פרנק משטיפי","b":"מראשי קהלת שטיפי שנות ה-ר'-ש'."},{"i":23234,"n":"יוסף פרץ מטריקאלה","b":"רב בטריקאלה-סוף שנות ה-ש', ור דניאל \"איש חמודות\" על מקומו אחריו."},{"i":23235,"n":"יוסף פרץ מלאריסה","b":"תלמיד ר מרדכי קלעי משלוניקי. מרביץ תורה בלאריסה-שנות ה-ש'-ת'."},{"i":23236,"n":"יוסף צבי הירש ממרגלין ופוהרליץ","f":"שלמה זלמן מפרישטיק","k":"בעל עוללות הבציר","b":"דרשן בפרישטיק-תקכ, רב במארגאלין(=מרגלין), באנאוויץ(=באנוביץ), פוהרליץ-תקמט על מקום ר ברוך. אחיינו של ר יהודה ליב מפרשיסחא."},{"i":23237,"n":"יוסף צבי מל\"ב מוערבוי","b":"רב בוורבוי(=וערבוי)-תקן. ישב כדיין בבחירת ר אברהם וינר לרב בעיר חדש - יחד עם ר אליעזר מהלברשטט, ור יוסף בן אשר מוערבוי."},{"i":23238,"n":"יוסף קלונימוס הלוי מסופיה","b":"רב בעדת האשכנזים בסופיה-שנות ה-ת'. דיין-תלט עם ר ישראל אהובי ור משה בן מיכאל הכהן."},{"i":23239,"n":"יוסף קלמן מקרלין וקאסוויע","f":"שלמה","k":"בעל מבוא המסורה","b":"רב בקאסוב(=קוסוב?), קרלין. חיבר גם \"שער המסורה\"."},{"i":23240,"n":"יוסף רבינוביץ משערשוב","f":"חיים מוולוזין","b":"תלמיד ר דוד משארשוב בעל \"חומות ירושלים\", פנה לחסידות והיה מקורב לאדמור מלכוביץ, בנו ר אליהו."},{"i":23241,"n":"יוסף רפאל הלוי מטימישואר","bt":"תקנו","dt":"תרכה - יד אדר","dp":"טימישואר","b":"רב בקהלה הספרדית בטימישואר-תקנו ב-50 שנה."},{"i":23242,"n":"יוסף שאול הלוי מירושלים","f":"מאיר","dt":"תרכו - ג חשון","dp":"ירושלים","b":"מצאצאי הנודע ביהודה. מחכמי ירושלים. חתן ר ישראל משקלוב. גבאי בת\"ת \"עץ חיים\". נפטר במגפת הכולירה בירושלים-תרכו."},{"i":23243,"n":"יוסף שאול משלוניקי","b":"תלמיד ר נסים חיים שלום מרגונטו. רב בשלוניקי-שנות ה-תק' עם ר רפאל אלעזר נחמיאש ור יוחנן קלעי."},{"i":23244,"n":"יוסף שוחט מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":23245,"n":"יוסף שלום ממעהרין","k":"בעל יד אבישלום","b":"חיבר \"יד אבישלום\" תפ."},{"i":23246,"n":"יוסף שלום מקושטא","f":"יהודה","b":"מחכמי קושטא בזמן ר יוסף טרני, השלים את תשובותיו וחתם \"המסיים יוסף שלום אי\"ש\", הוספה ממנו גם ב\"תמים דעים\" על הרי\"ף לר תם ן יחיא."},{"i":23247,"n":"יוסף שלמה גרשון מליפאנטו","b":"רב בליפאנטו-שנות ה-ש'."},{"i":23248,"n":"יוסף שלמה הקראי מקושטא","k":"בעל פתח התיבה (תקוה)","b":"ראש העדה הקראית בקושטא-תקכח. חיבר \"פתח התיבה-תקוה\" קושטא תקסד."},{"i":23249,"n":"יוסף שלמה זלמן מפרג","k":"בעל מנחת עני","b":"רב בפרג-תק\"ל"},{"i":23250,"n":"יוסף שלמה מהאזינפוט","f":"מנחם","k":"שלמה הזנפוטר","dp":"האזינפוט","b":"תלמיד הגר\"א, בקי בחכמת הקבלה. רב בהאזינפוט(=האזנפוט)-תקלט, חתנו - ר יחיאל מיכל בן אריה על מקומו אחריו. חתנו - ר ברוך דון יחיא מדיסנא, ר מיכל."},{"i":23251,"n":"יוסף שלמה עלי מקאבאלה","b":"רב הקהלה הספרדית בקאבאלה-שנות ה-ש'."},{"i":23252,"n":"יוסף שמואל ישראל מקראקא","f":"צבי הירש","k":"בעל מסורת הש\"ס,ופפד\"מ","bt":"ת - לפני","bp":"קרמניץ","dt":"תסד - א כסלו","dp":"פפד\"מ","b":"חתן ר שלמה בן ר נתן שפירא בעל \"מגלה עמוקות\". דיין בקראקא-תו, פפד\"מ-תן ור שמואל שאטין על מקומו אחריו באופן זמני עד למינוי ר נפתלי הכהן. חיבר הגהות על הש\"ס, ונדפסו הגהותיו על רש\"י ותוס' במהדורות פפד\"מ-תפא, ואמשטרדם. בנו ר יהודה אריה ליב ממטרסדורף - ערך את הגהות אביו והוסיף להם. (בגלל מחלוקת יצא צו בפקודת הקיסר שאסר את ההפצה של הש\"ס - בשנת תקיב עדיין לא נפתרה המחלוקת). נזכר בספרי חכמי דורו - בשמות שונים - ישראל, יוסף, חיים, ישעיה. חתנו - ר יהושע השל לבוב מטריר.","bk":[["מסורת הש\"ס [הוספות]",""],["מסורת הש\"ס",""]]},{"i":23253,"n":"יוסף שמואל מאונסדורף","f":"משה","b":"גביר באונסדורף. רכש את חלקת הקבר הסמוכה לר יצחק חיות מאונסדורף."},{"i":23254,"n":"יוסף שמואל משלוניקי","dt":"תקנו - יא סיון","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":23255,"n":"יוסף ששון מברושא","b":"שוחט בברושא-שנות ה-ת', היה מחלוקת בענינו בקהלה ודנו בענין רבני קושטא."},{"i":23256,"n":"יוסף תנחום טירמוס מסודארג-ליטא","f":"דוד מאנטאקליא","b":"מגיה בדפוס ראם בוילנא, ידידו של ר שמואל סלנט. נזכר בהקדמת הנצי\"ב לספרו העמק שאלה. הערותיו והגהותיו לחדושי הריטב\"א הלכות נדרים נדפסו בש\"ס וילנא, וכן להלכות בכורות."},{"i":23257,"n":"יוסף, עובדיה מירושלים","bp":"בגדד","b":"\"ראשון לציון\" על מקום הרב נסים. פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":23258,"n":"יוסף, שמואל","bt":"1881","bp":"קראטינגה","b":"היגר לניו יורק והיה פרופ' לסוציולוגיה. פרסם ספרים באנגלית בנושאי יהדות והגירה."},{"i":23259,"n":"יוסקא מאוזיראן","b":"רב באוזיראן-תר\"מ"},{"i":23260,"n":"יוסקוביץ, אברהם איסר","f":"שלמה מנחם","k":"בעל פרחים נוגים-תשט","bt":"1909","bp":"פיונטניצה-ליד לומז'ה","dt":"1942","dp":"וילנא","b":"תלמיד ישיבת לומז'ה. ביהמ\"ד למורים \"תרבות\" בוילנא. מורה ומשורר. מרצה ברדיו וילנא על מוסיקה יהודית. פרסם מאמרים ב\"אידישע שטימע\". נספה בשואה. פרסם הערות על שו\"ת \"אבני נזר\" ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו."},{"i":23261,"n":"יוסקוביץ, יעקב זאב מפאביאניץ","k":"בעל אמבוהא דספרי","b":"תלמיד ר מאיר דן פלוצקי בעל \"כלי חמדה\", מקורב לר מנחם זמבא. פרסם מאמרים ב\"אור המאיר\" - וארשא תרצו, \"אסיפת חכמים\" - אושפצין תרצד, \"הכוכב\" - מונקטש-נ\"י תרצה, \"עמק הלכה\" - וארשא תרפו. עורך \"יבנה\" - פאביאניץ תרפד, \"קול תורה\" - פאביאניץ תרפו."},{"i":23262,"n":"יוסקוביץ, יעקב מלודז","k":"בעל רשמי שאלה","b":"פרסם מאמרים ב\"דגל התורה\" - וארשא תרפב."},{"i":23263,"n":"יוסקוביץ, שלמה מוארשא","f":"משה זאב","bt":"תרמה","bp":"פאביניץ","b":"חתן האדמור מגור. תלמיד חותנו זקנו בעל \"שפת אמת\". ממיסדי ישיבת \"דרכי נועם\" בגור (יחד עם ר פנחס מנחם אלתר מקאליש), ממיסדי ונשיא ה\"מתיבתא\" בוארשא, נשיא \"אגודת ישראל\" בוארשא. עלה לירושלים-תש. פרסם מאמרים ב\"הלפיד\" - וארשא תרצז. חתנו - האדמור רה\"צ מאמשינוב"},{"i":23264,"n":"יועץ הפייטן","f":"מלכיאל","b":"פייטן-שנות ה-ק', חיבר קינה על קדושי וישבורק - בשנת ה'ל."},{"i":23265,"n":"יופיטר, אריה ליב מקניהניטש","dt":"תרע","b":"רב בקניהניטש, בורשטין."},{"i":23266,"n":"יופיטר, יוסף מזלישטשיק","b":"רב בזלישטשיק."},{"i":23267,"n":"יופיטר, מאיר מנשה מאזיפולי","b":"רב באזיפולי."},{"i":23268,"n":"יוקל מוילקוביסק","b":"רב בוילקוביסק, ור צבי הירש רפפורט על מקומו אחריו."},{"i":23269,"n":"יוקר, משה יוסף מקראקא","b":"הגיע מקראקא לאדא-הונגריה כמלמד בבית ר מרדכי וובר, התקרב לחסידות צאנז. רב ברזפניק."},{"i":23270,"n":"יוקרלס, בנימין זאב מפרשבורג","b":"רב בפרשבורג-תפ\"ו"},{"i":23271,"n":"יורדאן, שמואל זנויל מסטמר","f":"זאב","bt":"תרכא","dt":"תרצב - ז תמוז","dp":"סטמר","b":"תלמיד ר יעקב טננבוים מפוטנק בעל \"נהרי אפרסמון\". ובעל תואר דוקטור. חתן ר מאיר רוזנפלד ממישקולץ. רב הקהלה הניאולוגית בפוגאראש-תרן. רב קהילת סטטוס קוו בסטמר-תרסג. פרסם מאמרים בכתב העת הרבנים \"אהל יצחק\" - סטמר תרסג-תרעד. פעיל ציוני ופעל להקמת חינוך עברי בסטמר מרשת \"תרבות\". חיבר מונגרפיה בגרמנית על האמורא ר יוחנן."},{"i":23272,"n":"יורקנסקי, אברהם מסוורזשנה","b":"אב\"ד סוורזשנה(=סווערזשנע)-ליד סטויפץ. בן משפחת קצנלנבוגן. חתנו - ר שמשון גרוזובסקי ממינסק."},{"i":23273,"n":"יושיניאש, יצחק משלוניקי","dt":"תקפט - ז סיון","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":23274,"n":"יושת ן, יוסף מאלגיר","bt":"ד'תתך","dt":"ד'תתץ","b":"רב באלגיר, שאלות ממנו לרי\"ף ונזכר בשו\"ת תשב\"ץ, בבעל המאור על הרי\"ף המכנהו - ר יוסף יושתו ממדינת ג'ייאן - ולדעת שציפנסקי הכוונה לעיר מג'אנא-אלגיר ליד בני חאמאד."},{"i":23275,"n":"יזדי, אברהם מאיר","k":"בעל לקוטי שושנים","b":"רב ביזד(פרס), חיבר \"ליקוטי שושנים\""},{"i":23276,"n":"יזדי, ישראל מירושלים","f":"אברהם","k":"בעל ישמח ישראל","b":"עלה לירושלים."},{"i":23277,"n":"יזפי ן, ש' ממרוקו","b":"מחכמי מרוקו, חיבר דרשות - בכת\"י."},{"i":23278,"n":"יחזקאל","f":"אייזיק חריף","b":"רב-שנת ש'"},{"i":23279,"n":"יחזקאל אברהם מטרנוב","b":"מגדולי תלמידי ר מנחם מנדל מויזניץ, ונפטר בחיי רבו."},{"i":23280,"n":"יחזקאל אליהו מבגדד","b":"ראב\"ד בבגדד-תר\"ס"},{"i":23281,"n":"יחזקאל דעס גלעזערס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":23282,"n":"יחזקאל הכהן מוידז","b":"רב בווידז"},{"i":23283,"n":"יחזקאל הכהן מצפת","b":"רב בצפת-תר\"כ"},{"i":23284,"n":"יחזקאל הלוי מברויסק","k":"חתן הגר\"א","dt":"תקעב - כג שבט","b":"רב בברויסק"},{"i":23285,"n":"יחזקאל הלוי מהורדנא","b":"חתן ר הלל פריד מהורדנא. רב בהורדנא על מקום חותנו."},{"i":23286,"n":"יחזקאל הלוי מטרנטשין","f":"יוסף","k":"בעל תורת יחזקאל","bt":"תקכד","bp":"מיקולאש","dt":"תקצט - ב אייר","b":"תלמיד בעל \"מחצית השקל\" בבוסקוביץ. חתן ר יצחק חיות מאונסדורף. רב באונסדורף-תקעח על מקום ר יקותיאל זלמן וולף בעל \"עמק המלך\", טרנטשין-תקפד. מקורב לחת\"ס שעמד לצדו בזמן מחלוקת שהיה כנגדו בקהלה. חתנו - ר נתן צבי בלומגרונט מאלעשא."},{"i":23287,"n":"יחזקאל הלוי מפוזנא וקרוטושין","f":"מאיר מזאמושט","dt":"תנט - טו טבת","b":"חתן ר יצחק מפוזנא בעל \"באר יצחק\". דיין בפוזנא-תלו, רב בזלאטאווי-תנא, קורוטשין-תנג. בנו - ר משה יצחק הלוי, חתנו - ר אברהם אבלי-חותנו של ר דב בעריש הכהן."},{"i":23288,"n":"יחזקאל יאנובר מגריווא","dt":"תרנא - א תשרי","b":"בן למשפחת מתנגדים, מגדולי תלמידי הצמח צדק, ר אליהו יוסף מדרובין, ואחר כך חסיד האדמור מהרש\"ז מקפוסט. הגיע לגריווא עם ר משה ישראל מדריסא והפכו את העיר לחסידית."},{"i":23289,"n":"יחזקאל יוסף","bt":"1834","dt":"ה'תרסה 1905","bk":[["כתנת יוסף",""]]},{"i":23290,"n":"יחזקאל מאויוואר","b":"רב באויוואר-תרל\"ז"},{"i":23291,"n":"יחזקאל מגרינקישוק","b":"אב\"ד גרינקישוק. אחיו - ר אביגדור מבייסגולה."},{"i":23292,"n":"יחזקאל מדקשיץ","f":"אהרן מהורדנא","b":"רב בדקשיץ"},{"i":23293,"n":"יחזקאל מוונגרוב","b":"רב בוונגרוב-תר\"ע. מתלמידיו - ר ראובן יהודה נייפלד מנאוידוואהר."},{"i":23294,"n":"יחזקאל מוילנא","f":"ליב","b":"שליח קהלת וילנא יחד עם ר אבלי בן מנשה בזמן המחלוקת בקהלה עם רוזני וילנא."},{"i":23295,"n":"יחזקאל מזאגר וירושלים","f":"זאב","b":"מחכמי ירושלים."},{"i":23296,"n":"יחזקאל מטלז","b":"רב בטלז וגליל זאמוט בשנות תק.., ור יהודה ליב זיו על מקומו אחריו."},{"i":23297,"n":"יחזקאל מיאשון","f":"מאיר","k":"בעל מראה יחזקאל","b":"רב ביאשון-ליטא?"},{"i":23298,"n":"יחזקאל מיכל הכהן מרוזלא","b":"רב ברוזלא-תרכא."},{"i":23299,"n":"יחזקאל מלאזדיי","b":"אב\"ד לאזדיי. מחותנו של הגר\"א."},{"i":23300,"n":"יחזקאל מנחם מנדל מויזניץ","dp":"קולבסוב","b":"רב בויזניץ-תרך, קולבסוב."},{"i":23301,"n":"יחזקאל מפוקרוי ושאוולי","f":"אליהו מקרוז'-גיס הגר","b":"רב בשאוולי-תר."},{"i":23302,"n":"יחזקאל מקוזמיר","f":"אריה ליביש מקוזמיר","b":"תלמיד החוזה מלובלין - כמו אביו. המיר דתו וכינה עצמו סטניסלב הוגה והיה צנזור, ב\"כתר כהונה\"-צדרבוים מביא שחזר ליהדות בסוף ימיו."},{"i":23303,"n":"יחזקאל מקוזמיר","f":"צבי הירש","b":"מגדולי החסידות."},{"i":23304,"n":"יחזקאל מקוזניץ","b":"רב בקוזניץ-תק\"צ (האם הוא האדמור שלפי אלפסי נפטר בתקפא?)."},{"i":23305,"n":"יחזקאל מקוזניץ","k":"אדמור בפולין","dt":"תרע..","b":"נכד בעל \"פני יהושע\". כיהן כאדמור ונסע בכפרי פולין. נפטר בנסיעתו לחסידיו לפני מלחה\"ע ה-I."},{"i":23306,"n":"יחזקאל מקוזניץ","f":"שמחה","k":"אדמור מקוזניץ זואלין","dt":"תקפא - יח אדר","b":"נינו של בעל פני יהושע. נכד(-אבי אמו) ר יחזקאל מרגליות מאוסטרובצא. חתן הגביר ר בער מפשיסחא. תלמיד היהודי הקדוש מפשיסחא וכותב דברי תורתו ב\"כתר היהודי\". נסע גם אל המגיד מקוזניץ. אדמור בקוזניץ ובזוואלין. חתנו ר יהושע אשר מפוריסוב ונכד ר יעקב דוד מקוזניץ."},{"i":23307,"n":"יחזקאל מקלם","b":"רב בקלם-שנות התק.. ור אליקים גצל הורביץ על מקומו אחריו."},{"i":23308,"n":"יחזקאל מקלעוואן","b":"חתן ר יעקב מרדכי באב\"ד. רב בקלעוואן-תק."},{"i":23309,"n":"יחזקאל משה הלוי מבגדד","f":"משה","bt":"תרו","b":"מאנשי ביהמ\"ד \"זילכה\"(=זאלכה) בבגדד. ראב\"ד בבגדד."},{"i":23310,"n":"יחזקאל עזרא יהושע הלוי","k":"בעל ערוגות הבשם","b":"מחכמי בבל, תלמיד ר עבדאללה סומך, עלה לירושלים בשנת תרם. חיבר \"ערוגות הבושם\" ירושלים תרסג, ועוד."},{"i":23311,"n":"יחזקאל עזרא יחזקאל מבגדד","f":"מולא רחמים","k":"היע\"ר - עצי היער","bt":"תרלא-ו","bp":"בגדד","dt":"תרסח - א אד\"א","dp":"ירושלים","b":"מחכמי בבל, עלה לירושלים בשנת תרסד, חיבר \"עצי היער\" בגדד תרעא. (היע\"ר הם ראשי תיבות שמו). תשובות שלו נדפסו בספר \"רב פעלים\" לר יוסף חיים."},{"i":23312,"n":"יחזקאל צבי מטרנופול","f":"ישראל אברהם","b":"דיין אצל המנחת חינוך בטרנופול-תרל."},{"i":23313,"n":"יחזקאל שאול רופא מטבריה","b":"בשליחות קהלת טבריה-תרם בערך."},{"i":23314,"n":"יחזקאל, דוד צאלחיעקב","dt":"תרס - כג אדר","b":"ראש ישיבה בבגדאד, חיבר פיוטים"},{"i":23315,"n":"יחזקיה הכהן","f":"אפרים-שער אפרים","bt":"תח","dt":"תלח","b":"מחכמי אויבן, נספה במגיפה."},{"i":23316,"n":"יחיא גאון מרמלה","f":"ישועה","b":"חבר בית הדין ברמלה בשנת ד' תש\"ץ (1030). מעשה בית דין חתום ממנו (אסף מקורות ומחקרים)"},{"i":23317,"n":"יחיא הלוי מצנעא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":23318,"n":"יחיא ה\"ן דוד ויוסף מתאפילאלת","b":"מחכמי תאפילאלת-מרוקו-תר. בנו - ר שלמה."},{"i":23319,"n":"יחיא יצחק הלוי מתימן","f":"משה","bt":"תרכז","dt":"תרצב","b":"רב בצנעא ומנהיג יהודי תימן"},{"i":23320,"n":"יחיא ן, אברהם מכלוף","dp":"מיסור(מרוקו)","b":"מצדיקי מרוקו"},{"i":23321,"n":"יחיא ן, גדליה הזקן מפורטוגל","f":"שלמה","dp":"טולדו","b":"רופא למלך פרדיננד מפורטוגל, מלך קשטיליה-קלג ונתמנה לראש על היהודים בקשטיליה."},{"i":23322,"n":"יחיא ן, גדליה מפורטוגל","f":"דוד","k":"בעל שבעה עינים","bt":"קצז","dt":"רמח - ג תשרי","dp":"ניגרופונטי-קושטא","b":"גדול בתורה במדעים וברפואה, רופא מלך פורטוגל, עבר לקושטא-רמא, עלה לצפת."},{"i":23323,"n":"יחיא ן, גדליה מקושטא ושלוניקי","f":"תם","bp":"קושטא","dp":"קושטא","b":"רב ורופא בשלוניקי, קושטא-שח. החזיק בספריה גדולה. נספד בידי ר סעדיה לונגו. בניו - ר תם - רב ומשורר, ר משה. (יש בלבול בינו לבין ר גדליה בן תם שנפטר בשנת רפח - זקנו?)."},{"i":23324,"n":"יחיא ן, גדליה משלוניקי - א","f":"תם בן דוד","k":"בעל שבעה עינים","dt":"רפח","dp":"קושטא או פרס","b":"רופא ורב ק\"ק ליסבון בשלוניקי-שנות ה-ר'-ש', עבר לקושטא. מתורתו ב\"דרך תמים\" שי\"ל ע\"י בנו ר תם בתוך \"תמת ישרים\". נהרג בהיותו רופא המלך בזמן המלחמה בפרס, נספד ע\"י ר סעדיה לונגו. חיבר \"שבעה עינים\" (לפי רוזניס - יש מחליפים בינו לר גדליה בן דוד שעלה לצפת)"},{"i":23325,"n":"יחיא ן, גדליה משלוניקי - ג","f":"משה בן גדליה בן תם","bp":"פלושטריא-ליד שלוניקי","dt":"שנד - לפני","b":"מחכמי שלוניקי, יסד בית מדרש למשוררים בשלוניקי. נפטר בחיי אביו, ונספד ע\"י ר סעדיה לונגו."},{"i":23326,"n":"יחיא ן, גדליה ניגרו השני-הנכד","f":"שלמה","b":"נכד ר גדליה בן שלמה הרופא. מדקדק, משורר, רופא ואיצטנגין בחצר המלך יואן מפורטוגל,"},{"i":23327,"n":"יחיא ן, דוד - דון ניגרו","f":"דון שלמה נשיא","k":"בעל תהלה לדוד","bt":"ר","bp":"ליסבון","dt":"רסד-פד","dp":"קושטא","b":"מגדולי חכמי פורטוגל ואציליה, תלמיד ר' יוסף הנשיא חיון, דרשן,מדקדק, מפרש, דרשן בליסבון-רלד, ברח לשלוניקי, קושטא, ונזכר בשו\"ת הרא\"ם. חיבר גם \"קב ונקי\", \"לשון למודים\". בנו ר תם ן יחיא. הגיה את ספר האלפס שנדפס בקושטא-רסט. (יש אומרים שהוא המכונה דון ניגרו וי\"א שהכוונה לר דוד בן גדליה)."},{"i":23328,"n":"יחיא ן, דוד מספרד","f":"דון גדליה","k":"דון דוד נגרו","dt":"קפו - תשרי","dp":"טולדו","b":"מחכמי ספרד, רב כולל לכל קהילות קסטיליה מטעם המלך. נקבר בין הרא\"ש ובין ר מנחם ן זרח בעל \"צדה לדרך\"."},{"i":23329,"n":"יחיא ן, דוד מפורטוגל ואיטליה","f":"יוסף","bt":"רכב או רסה","bp":"ליסבון","dt":"שג","dp":"אימולה","b":"מחכמי ורבני פורטוגאל, תלמודי, מדקדק, משורר, ברח מפורטוגאל-רנ\"ה, עבר לאיטליה, רב דיין סופר ומרביץ תורה בנאפולי, רפ\"ו-ש', חזר לאימולה. עסק בפדיון שבויים שנשבו במלחמת ונציה תורכיה."},{"i":23330,"n":"יחיא ן, יהודה","f":"דוד","k":"(חתימתו) ניב\"י","b":"מחכמי פורטוגל-קן, פייטן, מקורב למלכות, בדור הרשב\"ץ, חיבר שו\"ת, קינות לתשעה באב, ועל גזירות-קנא בספרד, חיבר קינה \"יהודה וישראל דעו מר לי מאוד\"."},{"i":23331,"n":"יחיא ן, יוסף מליסבון","f":"יהודה","b":"מחכמי ליסבון-פורטוגל-שנות ה-ק'. יסד בית כנסת. חיבר שירים ופירוש לתלמוד - ואבד."},{"i":23332,"n":"יחיא ן, יוסף מליסבון - הנכד","f":"דוד בן יוסף","k":"בעל תורה אור","bt":"רכח או רנו","bp":"פורטוגל או פירנצה","dt":"רצט","dp":"איטליה-צפת","b":"קרוב למלכות בספרד ולדעת רש\"י פין נולד באיטליה. חתן דודו דון גדליה ן יחיא מוירונה וישב אצלו, עבר לפיררה-רנב?, רב בבולוניה?, אימולה-איטליה. חיבר \"תורה אור\" - בולוניה רצח, ובהקדמה מתאר את קורותיו מימי גירוש ספרד. חיבר ספרים נוספים. נפטר בחיי אביו ובניו קברוהו בצפת ליד ר יוסף קארו."},{"i":23333,"n":"יחיא ן, יוסף מספרד","f":"שלמה","b":"תלמיד חבר לרשב\"א, מחכמי ספרד. חיבר פסקי הגמרא עם חדושים ושירים - ונשרפו כתביו בגזירת וינצינצו. חיבר קינה על פטירת הרשב\"א \"קרחה להרחיב כנשרים שרים\" - נדפס בשלשלת הקבלה לנכדו."},{"i":23334,"n":"יחיא ן, יוסף מפורטוגל - הזקן","f":"דוד בן שלמה","bt":"קפז","bp":"פורטוגל","dt":"רנח","dp":"פיררה","b":"מחכמי פורטוגל, לאחר הגירוש עבר לאיטליה והתישב בפיררה."},{"i":23335,"n":"יחיא ן, יוסף מקושטא","f":"תם","b":"מחכמי קושטא-ש' ורופא השולטן ומשורר. הו\"ל ספר זקנו - ר דוד ן יחיא - \"לשון למודים\" - קושטא רפח. אחיו - ר גדליה בעל \"שבעה עינים\"."},{"i":23336,"n":"יחיא ן, יעקב חיים מאיטליה","f":"ראובן","b":"רב באיטליה. חתם-תקלח עם ר שלמה למפרונטי ור ישראל גדליה קזיס. תלמיד ר ישמעאל הכהן בעל \"זרע אמת\" וכתב הקדמה לספר רבו. ר מזל טוב מודנא כתב עליו."},{"i":23337,"n":"יחיא ן, יעקב משלוניקי","f":"משה","dt":"תכג - ט כסלו","dp":"שלוניקי","b":"תלמיד ר שלמה הלוי הבחור, ר דוד טירמישי. מחכמי שלוניקי."},{"i":23338,"n":"יחיא ן, משה משלוניקי","f":"גדליה","b":"רב קהלת ליסבון בשלוניקי-שנה, על מקום אחיו ר תם. בנו - ר גדליה השלישי נפטר בחיי אביו."},{"i":23339,"n":"יחיא ן, צאלח","f":"יחיא","k":"בעל פרי צדיק,מהר\"ץ","bt":"תרה","bp":"צנעא","b":"תלמיד ר שלום צבטאני. ראש השוחטים ודיין בצנעא ומלמד תלמידים. נכדו המהרי\"ץ. חיבר גם ספר הבדיקות, והגהות לשו\"ע."},{"i":23340,"n":"יחיא ן, שלמה מפורטוגל","f":"דוד","b":"מחכמי פורטוגל, בן דורו של הרשב\"ץ. אביו ר דוד בר גדליה היה ראש הרבנים בקשטיליה."},{"i":23341,"n":"יחיא ן, שמואל מאלכסנדריה","b":"רב באלכסנדריה-שנות ה-ש'."},{"i":23342,"n":"יחיא ן, שניאור משלוניקי","dt":"תסט","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":23343,"n":"יחיא ן, תם מליסבון וקושטא - א","f":"דוד ן יחיא","k":"בעל תמת ישרים","bt":"רל","bp":"ליסבון","dt":"שב-כ","b":"גדול בתורה חכמה ורפואה, רב בקהילה הספרדית בקושטא, רופא בחצר השולטן, ראש הרבנים אחר פטירת הרא\"ם (למעשה בטלה משרת הרב הראשי אחרי הרא\"ם) ור אליהו הלוי על מקומו אחריו. רוב חיבוריו אבדו בשריפה, ונכדו ר תם הו\"ל עם ר בנימין מוטאל \"תמת ישרים\" הכולל \"אהלי תם\", ו\"דרך תמים\" ממנו ומבנו ר גדליה. בניו ר יוסף - רופא השולטן, ור גדליא משלוניקי."},{"i":23344,"n":"יחיא ן, תם משלוניקי","f":"גדליה בן תם","dt":"שנה","b":"נכד ר תם מקושטא. גביר ומשורר בשלוניקי, רב קהלת ליסבון ואחיו ר משה על מקומו אחריו. החזיק עם אחיו - ר משה בספרייתו הגדולה של אביהם. חיבר \"אהלי תם\" ונדפס בתוך \"תמת ישרים\" ונציה שפב."},{"i":23345,"n":"יחיא נחום מתימן","bt":"תרלב","dt":"תשכב","b":"שליח ביה\"ד בצנעא לפקח על עניני היהדות ברחבי תימן. מתלמידיו - ר חיים בן שמעון מכפר יודערבא."},{"i":23346,"n":"יחיא, שלמה מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":23347,"n":"יחיאל","f":"אורי בן אליקום","bt":"ד'תתקע","dt":"כד - סוכות","b":"מגדולי חכמי דורו בנגלה ונסתר, מחסידי אשכנז. חתן הראב\"ן. אביו של הרא\"ש. חיבר ספר בדרכי לימוד התורה."},{"i":23348,"n":"יחיאל","f":"יקותיאל בן בנימין","k":"בעל מעלות המדות","b":"חיבר \"מעלות המדות\"."},{"i":23349,"n":"יחיאל","f":"ראובן","k":"בעל עשר יריעות","b":"רב ובקי בתכונה. חיבר \"עשר יריעות\" קושטא רצו - על חישוב המולדות."},{"i":23350,"n":"יחיאל (הלפרין) מוילנא","f":"רפאל","dt":"תקמה - כז שבט","dp":"וילנא","b":"מחכמי וילנא. כנראה מצאצאי ר יחיאל בעל סדר הדורות."},{"i":23351,"n":"יחיאל איכל המגיד ממעליץ","k":"בעל מגיד תהלות","dt":"תקפג","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ, ר מנחם מנדל מרימנוב, ור אברהם יהושע השל מאפטא. מקובל, ומגיד מישרים במעליץ. חיבר \"מגיד תהלות\" פודגורזע תרסא."},{"i":23352,"n":"יחיאל איכל מהמבורג","f":"אהרן","b":"שמש ונאמן קהלת המבורג-תקסח."},{"i":23353,"n":"יחיאל איכל מלינסק","b":"רב בלינסק."},{"i":23354,"n":"יחיאל איכל מנחם נחום","f":"יעקב","k":"בעל עמק ברכה","b":"מחכמי ברודי וקראקא, רב בפלאנטש-תקם. חיבר \"עמק ברכה\" למברג תקסח."},{"i":23355,"n":"יחיאל אשר שמואל מזאלין וירושלי","dt":"תריב - כד שבט","dp":"ירושלים","b":"רב בזאלין, עלה לירושלים"},{"i":23356,"n":"יחיאל הכהן מאנקונא","f":"יעקב","b":"ראש ישיבת אנקונה, נשא דרשה לכבוד החידא בביקורו שם. מתשובותיו בספרי חכמי דורו. עלה לירושלים וייסד בה ישיבה, האריך ימים קרוב למאה שנה. תשובות ממנו ב\"שמש צדקה\", \"פחד יצחק\" ועוד מחכמי דורו. הקים ישיבה בירושלים, האריך ימים קרוב למאה שנה. תשובה ממנו ב\"פחד יצחק\" ביחד עם ר יצחק אלקוסטנטיני, ור משה חיים מורפורגו-תקג. קונטרס ממנו בתוך \"שבת של מי\"-תקז."},{"i":23357,"n":"יחיאל הכהן מאשכנז","f":"יצחק","b":"מחכמי אשכנז-שנות ה-ק'. חתם על תקנות שו\"ם - מגנצא קמא."},{"i":23358,"n":"יחיאל הכהן מירושלים","k":"בעל תורת אדם","b":"בשליחות באמריקה-תרז, ופגש את מרדכי עמנואל נח שסייע לו בשליחותו."},{"i":23359,"n":"יחיאל הלוי סגל מאשכנז וסופיה","b":"מחכמי אשכנז, לאחר הגירוש-רל הגיע לסופיה-בולגריה. בנו - ר יוסף."},{"i":23360,"n":"יחיאל הפייטן","f":"יוסף בן מרדכי בן הלל","b":"נכדו של בעל המרדכי. חיבר קינה \"זכור איכה ארמון יפה נוף\"."},{"i":23361,"n":"יחיאל הפייטן מאיזנבך","f":"יעקב","b":"פייטן באיזנבך-שנות ה-ד'תתק', חיבר סליחה לזכר קדושי פולדא-ד'תתקצה \"ימים ברחו וטובה לא ראו עיני\"."},{"i":23362,"n":"יחיאל הפייטן מספרד","f":"אשר","k":"בעל ספר הרויה?","b":"פייטן בספרד, חיבר קינה על גזירות-קנא ובה כל בית מתחיל במילה \"תמוז\", אולי אחיו של ר יהודה בן אשר שנהרג עק\"ה. כנראה אינו ר יחיאל שחיבר ספר הרויה בשנת רנא."},{"i":23363,"n":"יחיאל הצרפתי הירושלמי","f":"יצחק","bp":"צרפת","b":"עלה מצרפת לירושלים, היה חתנו או קרובו של ר אנטולי בן יוסף מחשובי הקהלה במצרים. התגורר עם בנו ר שלמה בירושלים. לדעת י. מאן הגיע לירושלים לאחר חדוש הקהלה בימי צאלח א דין בשנת תתקמז (1187), קטעי מכתבים ממנו פרסמו י. מאן וי ברסלבי."},{"i":23364,"n":"יחיאל הרופא מאיטליה","k":"בעל מעלות המידות","b":"גדול בתורה ורפואה,מגדולי חכמי איטליה-שנת ש'"},{"i":23365,"n":"יחיאל השל מקרילביץ","f":"משלם זושא מזינקוב","k":"יחיאל העשל מקרילוויץ","b":"רב בקרילוויץ-תרל\"ה"},{"i":23366,"n":"יחיאל יוסף מראשקוב","f":"שבתי מראשקוב","k":"אדמור מראשקוב","b":"אדמור בראשקוב על מקום אביו יחד עם אחיו ר משה אברהם."},{"i":23367,"n":"יחיאל יעקב מאזמיר","f":"ישראל","b":"מדפיס באזמיר-תקסו."},{"i":23368,"n":"יחיאל ישעיה מיוזפוב","b":"רב ביוזעפוף"},{"i":23369,"n":"יחיאל מאטיניא","b":"רב באטיניא-תרכד."},{"i":23370,"n":"יחיאל מאיטליה","b":"רב - קרובו וחברו של מהר\"ם פאדובה, תשובה אליו ממהר\"ם פדובה - שהוקירו ואהבו."},{"i":23371,"n":"יחיאל מאנסבאך","f":"שמעון מיכל מפרשבורג","b":"בנו של ראש היהודים מפרשבורג. ספק החצר באנסבאך."},{"i":23372,"n":"יחיאל מהורדנא","b":"רב בהורדנא-תק. חתנו - ר אריה ליב בן צבי הירש מרובענקא, ונכדו - ר מאיר ספרא ודיינא בלובלין ואב\"ד אפטין."},{"i":23373,"n":"יחיאל מוארשא","dp":"י\"ב כסלו תרמ\"א","b":"מו\"צ בוורשה-תרי\"ט"},{"i":23374,"n":"יחיאל מווראניק","k":"בעל פירוש לרשי","b":"רב בוורניק-ש\"ל"},{"i":23375,"n":"יחיאל מוילנא","f":"מנחם נחום","dt":"תקסג","dp":"וילנא","b":"מחכמי וילנא."},{"i":23376,"n":"יחיאל מזבלטוב","b":"רב בזבלטוב, מיקוליב."},{"i":23377,"n":"יחיאל מטאטא","b":"רב בטאטא-תק\"ל"},{"i":23378,"n":"יחיאל מטויסט","b":"רב בטויסט."},{"i":23379,"n":"יחיאל מיכל","f":"ליבר מברדיטשוב","b":"רב-שנת תק\"פ"},{"i":23380,"n":"יחיאל מיכל ברוך מדובצק","b":"(יתכן שברוך - שם המשפחה). צדיק בדובצק. תלמיד ר נפתלי צבי מרופשיץ ועמד לצדו במאבקו מול רש\"ל מלנטשא (כנזכר ב\"רמתים צופים\"). נכדו - הרב פרידמן - מזכירו בספרו \"חמדה גנוזה\"). נכדו ר יחאיל מיכל - רב בדוברומיל."},{"i":23381,"n":"יחיאל מיכל דוד הלוי מקראקא","dt":"תרט - יח תשרי","b":"רב בקרקא"},{"i":23382,"n":"יחיאל מיכל הכהן מוארשא","f":"אברהם","b":"ממלא מקום רבה של וארשא."},{"i":23383,"n":"יחיאל מיכל הכהן מזאלושין","f":"שמואל לסקר מלוסק","b":"מחכמי זאלושין. בניו: ר זאב וולף הכהן-וועלויל חריף מלוסק, ר יוסף הכהן מצנסטחוב. חתנו - ר משה מזאלושין."},{"i":23384,"n":"יחיאל מיכל הכהן מזקראטשין","f":"אלעזר הכהן מפולטוסק","k":"בעל חשרת מים","b":"נכד ר יעקב מליסא בעל \"חוות דעת\". אב\"ד זקרוטשין(=זקראטשין)-תרמ. (אולי שם אביו אברהם)"},{"i":23385,"n":"יחיאל מיכל הכהן מלאסק - א","f":"אלעזר מוכיח","b":"מצאצאי ר יחיאל מיכל הקדוש מנמירוב. רב בלוסק-תקך. בניו: ר אברהם, ר שמואל, ר אלעזר."},{"i":23386,"n":"יחיאל מיכל הכהן מלאסק - ב","f":"אברהם אבלי","dt":"תקמט - כ שבט","b":"חתן ר איצק גאלדעס מלוסק. בנו - ר אברהם אבלי חריף טרויבע מלוסק."},{"i":23387,"n":"יחיאל מיכל הכהן מפרוסניץ","dt":"תנג- ב ניסן","b":"רב ברויזניץ,פרוסניץ"},{"i":23388,"n":"יחיאל מיכל הלוי מזרשין","b":"רב בזרשין-תרן."},{"i":23389,"n":"יחיאל מיכל הלוי מלאנצוט","f":"אברהם הלוי","b":"רב בלאנצוט-תק\"ל"},{"i":23390,"n":"יחיאל מיכל חסיד מברלין","f":"יהודה ליב דרשן מפרג","k":"בעל מכלל יופי","dt":"תפח - יא אדר","b":"נכד ר שמעיה בן אברהם ישכר בער-אב\"ד ברלין. חתן ר יצחק בנימין וולף מסלוצק וברלין. רב בכמה קהילות בפולין, זלוטוב(=פלאטא) ור יוסף יאסקי בן הקדוש ר יחיאל על מקומו אחריו, עבר לברלין וכיהן כר\"מ בישיבה שיסד הגביר ר יהודה ברלין עבור חתנו ר אהרן-רבה של ברלין - גיסו של ר יחיאל מיכל, ורב בברלין על מקום גיסו שעבר לפפד\"מ-תעד ואחרי פטירת ר אהרן נעשה גם רבה של פפד\"מ ונתאחדה הרבנות לשתי הערים. היה נחשב בעיני רבני דורו ור יחזקאל קצנלנבוגן אב\"ד אה\"ו נמנע מלהתיר יין חשוד אם לא שיסכים עמו ר מיכל. הניח חבורים בכת\"י גם בקבלה, וחדושים ממנו בספרי חכמי דורו. כנראה שבתחילה נטה לשבתאות ואף קירב את נחמיה חייא חיון אך לבסוף החרימם בעקבות שאר רבני אשכנז. בניו: ליפמן בעל אור נוגה - השתמד עם ילדיו, ר איצק מליסא, יעקב, חיים, חתניו: הדיין ר מנדל מפפד\"מ וברלין, הדיין ר ליב כץ מברלין, הדיין ר יואל זקש בן יקותיאל מגלוגא."},{"i":23391,"n":"יחיאל מיכל ישראל מדאטנובה","dt":"תרס - ג כסלו","b":"רב בדאטנובה"},{"i":23392,"n":"יחיאל מיכל מאוסטרהא","f":"אליקים גץ מאוסטרהא","dt":"תקח - כד אדר","dp":"אוסטרהא","b":"פרנס באוסטרהא. יחד עם ר שמואל ר יעקבס ור מרדכי הלפרין בח\"ק הראשון ועם ר מרדכי ר יעקב ר שמואלס בח\"ק השני."},{"i":23393,"n":"יחיאל מיכל מאפטא","f":"אברהם לבוב","b":"רב באפטא-ת\"ס"},{"i":23394,"n":"יחיאל מיכל מבלשנוב","b":"רב בבלשנוב-תר\"ב."},{"i":23395,"n":"יחיאל מיכל מברזן","f":"יקותיאל","b":"רב בברזן-תקמד."},{"i":23396,"n":"יחיאל מיכל מברעזנא","b":"נכד ר יצחק מברעזן. חתן נכדת ר פנחס מקוריץ ור שמעלקא הורביץ מניקלשבורג. רב בברעזנא-תרן. חתנו - ר שלום צוקר מטורטשין. (ראה גם ר יחיאל מיכל הלפרין)"},{"i":23397,"n":"יחיאל מיכל מהאזנפוט","f":"אריה","dt":"תקצה","dp":"ליבאוי","b":"חתן ר יוסף שלמה מהאזנפוט. רב בהזנפוט(=האזנפוט)-תקע על מקום חותנו, לאחר שחלה עבר לליבאוי. נזכר בשו\"ת ר עקיבא איגר. הספיד את ר חיים מוולוזין - כת\"י."},{"i":23398,"n":"יחיאל מיכל מוידוקלא","b":"חתן ר אברהם בן שלמה מכפר סיאון. אב\"ד וידוקלא-פלך קובנא."},{"i":23399,"n":"יחיאל מיכל מוילנא","f":"יצחק","b":"חתם-תטז על קיום חתימת בית דינו של בעל הש\"ך יחד עם ר אליעזר בן יעקב וערבש, חתם-תל על פסק דין."},{"i":23400,"n":"יחיאל מיכל מוישנוביץ","f":"מר'דכי מקרמניץ","b":"נכד המגיד מזלוטשוב. בנו ר ישראל - חתן ר חיים מקוסוב."},{"i":23401,"n":"יחיאל מיכל מולאדאוי","f":"שלמה זלמן","b":"מחכמי ולאדאוי(=ולאדובא). ערך והו\"ל את הגהות הב\"ח, (כנראה הוא או אחרים קנו את הש\"ס מר יואל-נכד הב\"ח."},{"i":23402,"n":"יחיאל מיכל מזלוטשוב","f":"יצחק מדרוהוביטש","k":"המגיד מזלוטשוב","bt":"תפו-צא","dt":"תקמו - כה אלול","dp":"ימפולא","b":"נכד-אבי אמו ר יוסף אשר בן ר משה מזווירש הי\"ד. תלמיד הבעשט, ור מנחם מאהן מויטקוב - שהיה מחותנו. חתן ר משה משדה לבן. מחכמי בורסילוב, ברודי (שם שרפו לפני ביתו את ספרי החסידות), מגיד בזלוטשוב, קאלק, ימפולא. מתורתו ב\"מים רבים\", \"זכרון לראשונים\", \"ישועות מלכו\" - ירושלים תשלד. ר מיכל'י קרא לחמשת בניו \"חמשה חומשי תורה\" והם: ר יוסף מימפולי, ר צבי בנימין זאב, ר משה מזוויהל, ר מרדכי מקרמניץ."},{"i":23403,"n":"יחיאל מיכל מזעטל ווילנא","f":"שרגא פיבש","b":"גביר בוילנא, הקדיש ביכ\"נ. חתם בפנקס חבורת מקרא-תקסו. בנו ר יצחק ליב-חתן ר יעקב רפפורט ממזיבוז."},{"i":23404,"n":"יחיאל מיכל מזענטא-מישל","b":"רב בזענטאמישל"},{"i":23405,"n":"יחיאל מיכל מטבריה","f":"אברהם","b":"שו\"ב עדת החסידים בטבריה. ר מנחם מנדל מויטבסק אמר עליו שהוא \"מהאנשים שלי\"."},{"i":23406,"n":"יחיאל מיכל מטבריה","f":"חיים","b":"חתם על כתב שליחות בטבריה."},{"i":23407,"n":"יחיאל מיכל מיברוב","f":"פתחיה","k":"בעל משנה לחם","b":"רב ביברוב-תק."},{"i":23408,"n":"יחיאל מיכל מימפולא","f":"יצחק דרוהוביטשר מימפ","b":"נכד המגיד מזלוטשוב. חתן האדמור ר מרדכי מטשרנוביל."},{"i":23409,"n":"יחיאל מיכל מירושלים","b":"מחכמי ירושלים, בשליחות-תסה לאחר עלית תלמידי רבי יהודה החסיד."},{"i":23410,"n":"יחיאל מיכל מלאבשוב","b":"רב בלאבשוב-תק\"צ"},{"i":23411,"n":"יחיאל מיכל ממוש","bt":"תקכח","dt":"תריב - י טבת","b":"תלמיד ר מרדכי מלכוביץ. רב במוש-ליד ברנוביץ כ-40 שנה. ר משה האדמור מקוברין היה נוסע אליו מדי שנה לחג השבועות. אחיו - ר דב בערמיסלאנימא."},{"i":23412,"n":"יחיאל מיכל ממינסק","f":"צבי בן איש ניעשוויעז","k":"בעל לזכר ישראל","dt":"תרה","dp":"מינסק","b":"גביר מחכמי מינסק, יסד ישיבה במינסק."},{"i":23413,"n":"יחיאל מיכל מנמירוב הי\"ד","f":"אליעזר אפשטין","k":"בעל שברי לוחות","dt":"תח - כ סיון","dp":"נמירוב","b":"בקי בנגלה ונסתר,רב בנמירוב. נהרג עק\"ה בגזירות תח. נספד ב\"איתן האזרחי\" לר אברהם רפפורט. אחיו - ר אליעזר מזלוטשוב הזקן?","bk":[["שברי לוחות - עה\"ת",""]]},{"i":23414,"n":"יחיאל מיכל מסקול","b":"דיין בלבוב, חתם-תסב בפנקס הקהל, ועוד."},{"i":23415,"n":"יחיאל מיכל מסקלט","f":"נחמן מסקאליט","k":"אדמור מסקאליט","dt":"תרמח","b":"רב בסקאלט-תרלה."},{"i":23416,"n":"יחיאל מיכל מפעטשי-ניידורף","b":"רב בפעטשי-ניידורף"},{"i":23417,"n":"יחיאל מיכל מקאלווריה","f":"יהודה ליב","k":"בעל מרגניתא","b":"רב בקאלווריה. חיבר גם \"דרך המלך\", ועוד."},{"i":23418,"n":"יחיאל מיכל מקאלשין","f":"צבי הירש מטשארקב","k":"יחיאל מיכל מינצקר","b":"רב בנאוי-מינסק, שעניצא, קאלושין. בנו - ר שלמה ונכדו ר מרדכי מוטיל מיכלסון בעל מאמר מרדכי."},{"i":23419,"n":"יחיאל מיכל מקומרנא","f":"אהרן אריה ליב מפרמיש","k":"אדמור מקומרנא","dt":"תקצג - ט ניסן","b":"ממשפחת אדמורי פרמישלן. חתן ר יקותיאל זלמן המגיד מקומרנא. אחיו ר מאיר ציוה עליו לנהוג אדמורות ולא קיבל, אולם בכל זאת הגיעו אליו חסידים. בניו ר מרדכי-חתן ר אליעזר זאב מבוצאץ."},{"i":23420,"n":"יחיאל מיכל מקורימא","f":"צבי מנחם מנדל מאניפו","k":"אדמור מאניפולי דינוב","bt":"תקמה","dt":"תרטז - כה סיון","b":"חתן ר יצחק הלברשטט מקונסטנטין-נכד ר יעקב עמדין. אדמור בקורימא, דינוביץ. נאסר לאחר עלילה-תקצח, לאחר שנתיים ברח לרימנוב, רב בקורימא-הונגריה."},{"i":23421,"n":"יחיאל מיכל מקראקא","dt":"תקלא - כז אדר","b":"דיין בקרקא"},{"i":23422,"n":"יחיאל מיכל משטמפן","f":"שלמה","dt":"תקו - כב-ג כסלו","dp":"שטאמפי","b":"חתן ר ליב דייטש. אב\"ד שטאמפי(=שטאמפן). בניו: ר קלמן, ר חיים שטמפי מפרשבורג-נפטר תקלא."},{"i":23423,"n":"יחיאל מיכל משעווער","b":"אב\"ד שעווער. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":23424,"n":"יחיאל מיכל סגל מגלוגא","f":"אשר לעמל מגלאגו","k":"בעל שער המים","dt":"תקעט - טז חשון","b":"מו\"צ בווינה,רב באייזנשטט"},{"i":23425,"n":"יחיאל מיכלמן הפייטן מצילפיך","f":"יצחק","b":"פייטן שנות ה-ק'. חיבר מערבית לסוכות \"ישמחו בחגיהם ידידים ונעימים\" - במחזור פולין."},{"i":23426,"n":"יחיאל מירושלים","f":"יוסף","k":"בעל מפת א\"י","b":"מחכמי ירושלים. היה בארה\"ב וחזר. חיבר מפת ארץ ישראל ויציאת מצרים ונדפסה בניו יורק-תר."},{"i":23427,"n":"יחיאל ממיקולייב","b":"תלמיד הבעשט. חתניו ר ישראל חריף מסטינוב(=סטנוב), ור יעקב בן ר ליבר מברדיטשוב."},{"i":23428,"n":"יחיאל ממנטובה","f":"ידידה שלמה מנורצי","b":"דיין במנטובה-שנת ת'"},{"i":23429,"n":"יחיאל מנורצי","f":"שלמה","b":"תשובה ממנו ב\"דבר שמואל\". בנו ר חיים המובא בתשובות הרמ\"ז."},{"i":23430,"n":"יחיאל מסגדין","b":"רב בסגדין-תקכ\"ט"},{"i":23431,"n":"יחיאל מסלוצק וירושלים","f":"יהודה","dt":"תרכח - כד כסלו","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23432,"n":"יחיאל מפדובה","f":"אליעזר","b":"נזכר בספר זכרון נשמות גאוני פדובה."},{"i":23433,"n":"יחיאל מפומפיאן","dp":"פומפיאן","b":"נכד התוי\"ט. רב בפומפיאן-שנות ה-ת'."},{"i":23434,"n":"יחיאל מפיזא","b":"גביר בפיזא-איטליה-רלב, חברו של דון יצחק אברבנל והתכתב עמו, ודון יצחק שלח אליו את ספרו \"עטרת זקנים\"."},{"i":23435,"n":"יחיאל מפריס","f":"יוסף","bp":"מיץ","dt":"כו-כח","dp":"עכו","b":"מבעלי התוספות, תלמיד ר יהודה בן יצחק מפריס המכונה סיר ליאון, ועמד בראש הישיבה בפריס אחר פטירת רבו. השתתף בויכוח לפני מלך צרפת נגד שריפת התלמוד, נאלץ לעזוב את צרפת לאחר שריפת התלמוד ועלה לעכו בראש חבורה גדולה בשנת ה'יט (1259). הקים בעכו ישיבה בשם \"בית מדרש דפריס\". חתנו ר יצחק בן יוסף מקורביל בעל סמ\"ק-\"ספר מצוות קטן\", ור מרדכי בן הלל בעל ה\"מרדכי\"."},{"i":23436,"n":"יחיאל מקאוולי","b":"תלמיד הבעש\"ט, רב בקאוולי-תקל. חתנו - ר ישכר בן דוד הלפרין מאוסטרהא."},{"i":23437,"n":"יחיאל מקלם וירושלים","dt":"תרכז - יח כסלו","dp":"ירושלים","b":"מו\"צ בציטיוואן, עלה לירושלים. מתומכי ר\"מ יאנובר בזמן המחלוקת בירושלים."},{"i":23438,"n":"יחיאל מרומא","f":"אברהם בן יואב","b":"מחכמי רומא-ד'תשס. חיבר פיוטים ומהם במחזור רומא. בניו: ר אברהם, ר דניאל, ר נתן בעל הערוך. (יש אומרים שהיה ממשפחת הענוים)."},{"i":23439,"n":"יחיאל מריגיו","b":"מגדולי רבני איטליה,רב בריגייו-ת\"מ"},{"i":23440,"n":"יחיאל משה מיאדימוב","k":"בעל מילין חדתין","b":"נכד ר צבי הירש מאופוטשנא. תלמיד ר מנחם מנדל מקוצק ובנו ר דוד. חיבר גם \"נפלאות חדשות\"."},{"i":23441,"n":"יחיאל משוטלנד","k":"חותן ה\"חיי אדם\"","b":"רב בשוטלנד-תק\"מ"},{"i":23442,"n":"יחיאל סגל מקובנא","b":"רב בקובנא-שצד."},{"i":23443,"n":"יחיאלי, י' מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":23444,"n":"יחיון ן, יוסף מאלגיר","bt":"קי","dt":"רפ - בערך","b":"רב ודיין בתלמסאן (או באגאדיר). נזכר בשו\"ת הרשב\"ץ, ואצל הרשב\"ש. היה בר פלוגתא של ר עמרם בן מרואס הדיין מווהראן."},{"i":23445,"n":"יחייא ן, דוד משלוניקי","b":"דיין בשלוניקי-שנד."},{"i":23446,"n":"יחייא ן, שלמה משלוניקי","b":"גביר בשלוניקי ותרם לת\"ת בשלוניקי-שע בערך."},{"i":23447,"n":"יחייא ן, שמואל מאלכסנדריה","b":"מחכמי אלכסנדריה-שסד, וחתם אז על קבלת עדות. תלמיד ר שלמה גאביזון, היה מחלוקת בינו לבין רבו - בשו\"ת מהר\"ם גאביזון מביא אגרת מר חיים כפוסי בענין המחלוקת."},{"i":23448,"n":"יחייא ן, תם מקושטא - ב","f":"גדליא","k":"הו\"ל תמת ישרים-לזקנו","b":"נכד ר תם הראשון. מחכמי קושטא. הו\"ל כתבי זקנו ששרדו מהשרפה, ע\"י ר בנימין מוטאל, ב\"תמת ישרים\" הכולל מפירושי זקנו וספרים נוספים."},{"i":23449,"n":"יחייא, גדליה משלוניקי","f":"משה","dp":"קושטא","b":"חתן ר שלמה סיניור. גביר מחכמי שלוניקי. הרופא אמאטוס ליזיאנוס הקדיש לו אחד מספריו - וסיפר עליו שהיה נואם מצויין, חכם ונדיב ומכניס אורחים - כאביו וחותנו."},{"i":23450,"n":"יחייא, יוסף משלוניקי","b":"מחכמי שלוניקי-שן."},{"i":23451,"n":"יטקונסקי, מרדכי","bt":"1890","bp":"יאנובה","dt":"1941","dp":"קובנא","b":"תלמיד בישיבות ליטא. עסק בהוראה. מזכיר המרכז הציוני ורכז עניני קק\"ל בקובנא. ממיסדי \"אידישע שטימע\". נציג הציונים בועד הקהילה. מנהל \"קרן היסוד\" בליטא. פעיל בעזרת לפליטי המלחמה בפולין, נספה בשואה."},{"i":23452,"n":"ייאייא ן, שלמה מאלגיר","f":"הלל","b":"רב ומשורר בתלמסאן. חיבר קינה לתשעה באב - בספר קינות בכת\"י. (כנראה שהשם - ייאייא - הוא כינוי ולא שם משפחה)."},{"i":23453,"n":"ייבין, יהודה לייב","f":"יעקב יוסף","b":"שינה שמו לייבין ע\"ש ספר אביו \"רב ייבי\". מחכמי ברדיטשוב."},{"i":23454,"n":"יידל","b":"רב בקלצק-ת\"ל"},{"i":23455,"n":"ייזיד, כליפה מירושלים","b":"מחכמי ישיבת \"בית אל\" בירושלים-תקיח."},{"i":23456,"n":"ייטב, משה מתימן","b":"דיין בביר עאוד-תימן-שעח."},{"i":23457,"n":"ייטלש, אהרן","b":"מגדולי חכמי פרג-תק\"ל"},{"i":23458,"n":"ייטלש, איגנץ מוינה","k":"בעל אעשטהמישעס לעקסי","b":"פילוסוף מחכמי וינה, חיבר ספר בסדר האלפא ביתא ובו ביאורי כל המלים בעניני חכמות היופי - וינה 1839."},{"i":23459,"n":"ייטלש, ברוך הרופא מפרג","f":"יונה","k":"בעל טעם המלך","bt":"תקכב","dt":"תקעד - כה כסלו","b":"חתן הגביר ר שמואל פורית. רופא מחכמי פרג. חיבר \"טעם המלך\" על \"שער המלך\" - ברין תקסא, אולי הוא מחבר \"האורב\" (ויש חולקים על כך) ובו על המחלוקת בינו לר שמואל לנדא. אחיו - ר יהודה ליב בעל \"עמק הבכא\" על הנודע ביהודה."},{"i":23460,"n":"ייטלש, יהודה מפרג","f":"יונה הרופא","k":"בעל מבוא הלשון הארמי","dt":"תקצח","dp":"וינה","b":"תלמיד אחיו ר ברוך. חיבר ספר דקדוק \"מבוא הלשון הארמית\", \"בני הנעורים\". פרסם מאמרים ב\"בכורי העתים\", \"כרמי חמד\"."},{"i":23461,"n":"ייטלש, יעקב זאב מפרג","f":"יהודה","dt":"תעה","dp":"ונדסבק","b":"מחכמי פרג, עבר לואנדסבק."},{"i":23462,"n":"ייטלש, שמעון מברלין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":23463,"n":"ייני, אברהם משלוניקי","b":"שאלוניקי-תק\"ל"},{"i":23464,"n":"ייני, אהרן משלוניקי","b":"דיין בשלוניקי-שנח."},{"i":23465,"n":"ייני, גבריאל משלוניקי","dt":"תסו","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":23466,"n":"ייני, גדליה משלוניקי","dt":"תקלח - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"סוכת דוד\" לר דוד שירירו-תקלח."},{"i":23467,"n":"ייני, יצחק בכור משלוניקי","dt":"תקלד","dp":"שלוניקי","b":"גביר בשלוניקי. נהרג עק\"ה-תקלד."},{"i":23468,"n":"ייני, יצחק משלוניקי","b":"רב בשלוניקי. חתום על שטר בוררות-תקם."},{"i":23469,"n":"ייני, שלמה אהרן משלוניקי","b":"מחכמי שלוניקי. הו\"ל \"מוסר השכל\"-תרמה."},{"i":23470,"n":"ייני, שמואל משלוניקי","dt":"תלט","dp":"שלוניקי","b":"רב ור\"מ בשלוניקי."},{"i":23471,"n":"ילובקר, יעקב מאיר מסלוצק","bt":"תקנד","dt":"תקפו - טו שבט","b":"נתמנה לרב בסלוצק-תקפה, אך נפטר בדרכו לשם. מתורתו בספרי תלמידיו: \"פני אריה\" לר אריה הלוי מוילקוביסק, \"קול יהודה\", ועוד."},{"i":23472,"n":"ילוז - משפחה","b":"משפחה במרוקו וטבריה."},{"i":23473,"n":"ילוז, אברהם מטבריה","k":"בעל סגולות ורפואות","dt":"תרס","dp":"טבריה?","b":"מחכמי טבריה, מחבר \"סגולות ורפואות\"."},{"i":23474,"n":"ילוז, אברהם ממרוקו וטבריה","bp":"מרוקו","dt":"תרמח","b":"תלמיד \"אביר יעקב\", עלה לטבריה, צפת"},{"i":23475,"n":"ילוז, אליהו מטבריה","f":"אברהם","k":"בעל פתח אליהו","bt":"תרך","bp":"מזגידה או תאפילאלת-מרוקו","dt":"תרפט - כב אלול","dp":"טבריה","b":"חתן ר' דוד אסודרי. עלה לארץ-תרלד דרשן מחכמי טבריה-תרמ ודיין-תרנג, ואב\"ד-תרעט, פקיעין-תרסג, בזמן מלחה\"ע ה-I גלה לכרתים וקפריסין. בשליחות במרוקו-תרן, ועוד. חיבר \"יש מאין\", ועוד. בנו - ר יוסף חיים הביא מתורתו ותולדותיו בספרו \"פתח אליהו\".","bk":[["יש מאין","שו\"ת - אחרונים"],["הלכות אישות",""],["יש מאין חלק א",""],["מעשה אליהו",""],["פתח אליהו",""]]},{"i":23476,"n":"ילוז, דוד ממרוקו וטבריה","f":"יעקב","bt":"תר","bp":"מיזגידה-ליד תפילאלת","dt":"תרצד - יט סיון","dp":"טבריה","b":"מחכמי מרוקו, בשנת תרמא עלה לטבריה והיה מחכמיה, בשליחות בתימן-תרסד."},{"i":23477,"n":"ילוז, יוסף חיים מטבריה","f":"אליהו מטבריה","k":"בעל תולדות אליהו","bt":"תרף","bp":"טבריה","b":"תלמיד ר יעקב חי זריהן, ר משה מאיר אליקים-המשמ\"ח. בשליחות במרוקו ובמצרים. בניו: ר משה אהרן, ר אברהם נסים מטבריה. חיבר גם \"אוצר יוסף\", ועוד. הו\"ל ספרי אביו ובהם \"פתח אליהו\"."},{"i":23478,"n":"ילוז, יחיא ממרוקו","k":"בעל דרושים","b":"דיין בתאפילאלת-תקצב עם ר יעקב אביחצירא. תשובה ממנו לר משה אביכזיר."},{"i":23479,"n":"ילוז, מסעוד מיפו","b":"דיין ביפו-תרי. נזכר ב\"בני בנימין\" לר מרדכי נבון."},{"i":23480,"n":"ילוז, רפאל חיים ממרוקו","dt":"תרפד - ב שבט","dp":"טבריה","b":"עלה בילדותו והתישב בטבריה. חתן ר מאיר נינייו. שו\"ב מומחה ומתלמידיו קרובו ר אליהו ילוז ראב\"ד טבריה. חיבר חדושים לתורה, ושות בענין שחיטה ומילה בכת\"י. מתורתו בספר קרובו ר אליהו ילוז \"יש מאין\". בשליחות-תרנו בבוכרה, ובשנית ב-תרס, ובגמר שליחותו נתמנה לרב בבוכרה בקונקנד וסמרקנד. חזר לטבריה-תרעא."},{"i":23481,"n":"ילוז, שלמה מטבריה וטריפולי","k":"בעל אשר לשלמה","bt":"תרסט","bp":"טבריה","dt":"תשמה - ה חשון","b":"מצאצאי ר חיים ילוז, ור מאיר ניניו. רב ראשי בטריפולי-תשו, וראש ישיבת \"נוה שלום\" בטריפולי (תלמידי הישיבה הו\"ל כתב עת \"סמדר\"-תשז), רב במרוקו ופרסם-תשי \"קול קורא\" להציל ילדי ישראל במרוקו ולחנכם על ברכי התורה. רב בטהרן-פרס. דיין בחיפה-תשכד, אשדוד."},{"i":23482,"n":"יליז, מסעוד","b":"דיין ביפו-תר\"י"},{"i":23483,"n":"ילין, דוד מירושלים - הזקן","f":"יהושע טביא","bp":"לומזה","dt":"תרכג - ח אייר","dp":"ירושלים","b":"עלה לצפת, עבר לירושלים-תקצד. עסקן צבור מחכמי ירושלים. בנו - ר יהושע חיבר לזכרו \"שער צדק\"."},{"i":23484,"n":"ילין, דוד מירושלים - הנכד","f":"יהושע","k":"בעל משה בן מימון","bt":"תרכו","bp":"ירושלים","dp":"ירושלים","b":"חתן ר יחיאל מיכל פינס. חיבר מאמרים וספרים ובהם \"משה בן מימון\" - וארשא תרנט. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט."},{"i":23485,"n":"ילין, חיים","f":"אליעזר","bt":"1913","bp":"וילקי-ליטא","dt":"1944","b":"בזמן השואה היה פעיל במחתרת בסלובודקה והיה מפקד פרטיזנים. נספה בשואה."},{"i":23486,"n":"ילין, יהושע מירושלים","f":"דוד (שלום שכנא?)","k":"בעל זכרונות לבני ירו","bt":"תרג","bp":"ירושלים","dt":"תרפד - ז אייר","dp":"ירושלים","b":"אחד משבעת המתישבים הראשונים בשכונת \"נחלת שבעה\" בירושלים. נסע עם אביו לחלב לרשום את ה\"מסורה\" מתוך כתר ארם צובא."},{"i":23487,"n":"ילין, לימא מאמדור","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":23488,"n":"ילין, מאיר","f":"אליעזר","k":"בעל פארטיזאנער אין","bt":"1910","bp":"סראדניק","b":"מהנדס, ניצל מהשואה בגיטו קובנא. הקים בית מחסה לילדים יתומים אחרי השואה. פרסם סיפורים ומאמרים על השואה בליטא. חיבר \"פארטיזאנער אין קאונאסער געטא\" מוסקבה 1948. חיבר גם ספרים בליטאית על השואה."},{"i":23489,"n":"ילין, מרדכי משדה לבן","f":"צבי הירש","bt":"תרמ","b":"רב בשדה לבן-פלך קיוב-תרסז."},{"i":23490,"n":"ילין, צבי הירש","b":"רב-שנת תר\"ס"},{"i":23491,"n":"ילין, שלום שכנא מירושלים","bt":"תקן","dt":"תרלד","b":"תלמיד ר חיים מוולוזין. מחכמי סקידל-מחוז גרודנא, עלה לירושלים. מגיה ספרי תנ\"ך ובקי במסורה, ונשלח ע\"י חכמי ירושלים לחלב לעבור על \"כתר ארם צובא\" ולהעתיק משם את ה\"מסורה\", בעזרת בנו ר יהושע, והשלים את המלאכה חתנו - ר משה יהושע קמחי."},{"i":23492,"n":"ילינסקי, אשר זאב מירושלים","b":"חתם עם מנהלי הועד הכללי של כוללות ירושלים-תרסו."},{"i":23493,"n":"ילינק אהרן בן יצחק יהודה","k":"בעל קאנצעל פארטראגא","bt":"1821","bp":"דריסלביץ-ליד אונגר בראד","dt":"ה'תרנג 1893","b":"מטיף ריפורמי בלייפציג, וינה-1856 לצד יצחק נח מנהיימר ועל מקומו אחריו. ראש ביהמ\"ד לרבנים בוינה. חיבר ספרים רבים בחכמת ישראל.","bk":[["אמרי שפר",""],["בית המדרש א",""],["בית המדרש ב",""],["בית המדרש ג",""],["בית המדרש ד",""],["בית המדרש ה",""],["בית המדרש ו",""],["גנזי חכמת הקבלה",""],["קונטרס הכללים",""],["קונטרס המגיד",""],["קונטרס המזכיר",""],["קונטרס המספיד",""],["קונטרס המפרש",""],["קונטרס המפתח",""],["קונטרס המקונן",""],["קונטרס הרמב''ם",""],["קונטרס ווירמייזא וקהל ווינא",""],["קונטרס תריג (תרי\"ג)",""]]},{"i":23494,"n":"ילקוט, חיים ראצקר מירושלים","dt":"תרכו - תשרי","dp":"ירושלים","b":"מחכמי ירושלים, נפטר במגפת הכולירה בירושלים-תרכו. בנו - ר ליב, חתנו - ר מנחם משה ריבלין."},{"i":23495,"n":"ימין הכהן מאלגיר","bt":"תקע","dt":"תרן","b":"רב בפירנדא-אלגיר. שאלה ממנו לר אברהם אנקאוא ב\"כרם חמר\"."},{"i":23496,"n":"ימין הכהן ממראקש","b":"מו\"ץ במראקש, חתם על פס\"ד-תרמא."},{"i":23497,"n":"ימין, כמוס מלוב","bt":"תרי","bp":"עמרוץ-לוב","dt":"תרף-ץ - כג ניסן","b":"מקובל מחכמי טריפולי. רב בכפר עמרוץ(=עמרוס)-לוב, והיה מלומד בנסים. חיבר ספר בקבלה בכת\"י. (נולד ונפטר באסרו חג פסח)."},{"i":23498,"n":"ימיני, משה סקרובון מליטא וירוש","f":"יצחק","k":"בעל לקץ הימין","bp":"מיר","dp":"ירושלים","b":"עלה לירושלים. חיבר גם\"משא בערב\" ירושלים תרצו, ועוד."},{"i":23499,"n":"ימיני, צבי הירש מוילאן","f":"אברהם","bt":"תרל","dt":"תשג","b":"תלמיד ישיבת וולוזין, איישישוק, כולל קובנא. חתן ר השל (מעשיל) מוישקעס - המכונה \"העילוי מסוואלק\". רב בווילאן-פלך ויטבסק-תרס. נסמך מאת ר מאיר שמחה הכהן מדוינסק."},{"i":23500,"n":"ימפל, דוד","b":"תשובה אליו בקונטרס התשובות-תרלד."},{"i":23501,"n":"ימפל, דוד מיבלונוב","b":"רב ביבלונוב-תרמט."},{"i":23502,"n":"ימפל, יהודה ממיידן","f":"ירוחם פישל ממיידן","b":"עבר לשוסבורג, בוארשא. הו\"ל \"עמר נקא\" לברטנורה, ובסופו מגילת יחוס המשפחה."},{"i":23503,"n":"ימפל, יחיאל מיכל מדולינא","b":"חתן ר יצחק שטעג מדולינא ועבר לשם."},{"i":23504,"n":"ימפל, ירוחם פישל מוולובה","f":"מרדכי","dp":"בודפשט","b":"רב במיידן-וולובה."},{"i":23505,"n":"ימפל, מרדכי ממיידאן","f":"יחיאל מיכל","dt":"תרנט - יד אדר","b":"חתן ר חיים שמואל פיקסלר. רב במיידאן-תרלה."},{"i":23506,"n":"ינובסקי, חיים עוזר","b":"רב-שנת ת\"ש"},{"i":23507,"n":"ינובסקי, יעקב צבי מקיוב","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן, \"הפלס\" - ברלין תרסא-תרסה."},{"i":23508,"n":"ינובסקי, יצחק יעקב מאוטואצק","b":"פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו."},{"i":23509,"n":"ינובסקי, ישראל יצחק מקאמינקא","f":"אליהו","k":"בעל טהרת ישראל","b":"רב בקארסשוב, אב\"ד קאמינקא בפראגא-ליד וארשא. חיבר גם \"אור ישראל\" על הלכות פסח."},{"i":23510,"n":"ינובסקי, שלמה מפיעטרקוב","f":"חיים חייקל","k":"בעל גן בשמים","b":"מ\"מ בפיעטרקוב, וארשא. חיבר גם \"קנין טוב\", ועוד."},{"i":23511,"n":"ינוסביץ, נתן","f":"יוסף","bt":"1892","bp":"יאנובה","dt":"1944","dp":"קובנא","b":"תלמיד ישיבת סלובודקה, וילנא וליבאו. מזכיר ועד הקהילה בקובנא. פרסם מאמרים לתולדות יהודי ליטא בחתימת \"ינאי\". הו\"ל \"יאר איין יאר אויס\". נספה בשואה."},{"i":23512,"n":"יניי הפייטן","b":"פייטן קדמון."},{"i":23513,"n":"ינייסי, יהודה שלום מאיטליה","k":"בעל בן ישי","b":"מחכמי איטליה. חיבר ספר בחכמת העיבור - וינה תקפז."},{"i":23514,"n":"ינישוק = יאנישוק = קהילה","b":"ליטא - מחוז שאוולי. בליטאית \"יונישקיס\". ב-1897 ישבו בה כ-2200 יהודים, לפני השואה כ-600 יהודים. שימשה כמרכז לסחר בפשתן. רבנים: ר שלום בן אשר איזראלסון בעל \"דברי שלום\", ר יחיאל מיכל בעל \"שפת הים\", ר דוד טבלי קצנלנבוגן, ר נחום בצלאל דזימיטרובסקי הי\"ד - רבה האחרון נספה בשואה. מו\"צ: ר אליהו ישכר יפה."},{"i":23515,"n":"ינצ'וק, שמואל חיים מקובנא","bt":"תרטז","bp":"שטוצ'ין","dt":"תרצז","dp":"קובנא","b":"תלמיד הכולל בקובנא. יסד ישיבה בקובנא בביהמ\"ד של חייטים, ועמד בראשה - כ-50 שנה."},{"i":23516,"n":"ינקילוב, צבי יעקב מואשקי","dt":"תשג","b":"רבה האחרון של ואשקי, בזמן הכיבוש הרוסי - סגרו הרוסים את ביה\"ס היהודי ולימד תורה את הילדים בביתו תוך מסירות נפש. נספה בשואה."},{"i":23517,"n":"ינקלביץ, גרשון מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":23518,"n":"ינקלביץ, יוסף מבולטרימנץ","dt":"תרפא - י אלול","b":"דיין וראש ישיבה בבלטרומנץ(=בוטרימנץ, באלטערמאנץ)-פלך וילנא לפני מלחה\"ע ה-I."},{"i":23519,"n":"ינקלביץ, שמואל","dt":"תרנו - כב אלול","b":"מו\"צ באלכסנדרבסקה"},{"i":23520,"n":"ינקלבסקי, עקיבא מראמני","f":"אליהו","bt":"תרכא","b":"חתן ר אליעזר ארלוזרוב מראמני, רב בראמני-פלך פולטובה-תרסא על מקום חותנו."},{"i":23521,"n":"ינר, אברהם נפתלי הרץ מקראקא","f":"מרדכי צבי הירש לרנר","k":"בעל צלותא דאברהם","bt":"תקסה","bp":"יאנוב","dt":"תרלו - יא תמוז","dp":"קראקא","b":"חתן הנגיד ר שלמה זאלי קראשניך מקראקא. רב ביאנוב, ראב\"ד בקראקא-תקצא. חיבר גם \"ברכת אברהם\"."},{"i":23522,"n":"יסאן, יהודה ממראקש","f":"שלמה","b":"מחכמי מראקש."},{"i":23523,"n":"יסאן, שלמה ממראקש","b":"מחכמי מראקש."},{"i":23524,"n":"יסו מאופראן-מרוקו","f":"דוד","dt":"שכח","dp":"אופראן-מרוקו","b":"מחכמי מרוקו."},{"i":23525,"n":"יסינובסקי, ישראל","bt":"1842","bp":"גרודנא","dt":"1917","b":"תלמיד אוני' קאזאן. וחיבר דיסרטציה על \"מקורות תורת המשפט בתורה שבע\"פ ובכתב\". מחובבי ציון והשתתף בועידת קטוביץ. ציר בקונגרסים הציוניים. מראשי ההסתדרות הציונית ברוסיה. הרצל התאכסן בביתו בעברו דרך וארשא."},{"i":23526,"n":"יסינובסקי, פנחס מארה\"ב","k":"בעל אדוני זכרנו","b":"משורר, מלחין, חזן בארה\"ב. חיבר ספרי חזנות."},{"i":23527,"n":"יסלבסקי, יעקב","dt":"תשד","b":"רב בווראנוב"},{"i":23528,"n":"יסלוטר, מאיר ברוך מברוד","f":"ישראל","b":"רב ברוסיה, הגיע ממינסק לברודי. הדפיס \"מדרש הגדה\". חיבר מגלת אסתר עם פירוש \"פנים מאירות\" - זולקוא תקעה."},{"i":23529,"n":"יסר, יצחק אריה מברוד","b":"ראש ישיבה בברודי."},{"i":23530,"n":"יעבץ מצעדה-תימן","f":"יעקב","b":"רב בצעדה-תימן-תרעא."},{"i":23531,"n":"יעבץ, אורי מנשה מסניאטין","dp":"צפת","b":"חסיד ר מנחם מנדל מקוסוב. חתן ר חנוך זזונדל פויגל מווישווא. עלה לצפת בסוף ימיו. בנו ר משה יהודה יעבץ-מילר מצפת."},{"i":23532,"n":"יעבץ, בכור יעקב מאזמיר וירושלי","f":"חיים משה","k":"בעל צור יעקב","dt":"תרלה","dp":"ירושלים","b":"מחכמי אזמיר, עלה לירושלים. חיבר \"צור יעקב\" אזמיר תרכו."},{"i":23533,"n":"יעבץ, ברוך מאזמיר","dt":"תעה","dp":"אזמיר","b":"רב באזמיר. בנו - ר ברזילי."},{"i":23534,"n":"יעבץ, ברזילי מאזמיר","f":"ברוך","k":"בעל לשון למודים","bt":"תן - בערך","dt":"תקך -בערך (תקב)","dp":"אזמיר","b":"תלמיד ישיבת אביו באזמיר. חתן ר אליהו חאקו. דרשן, רב באיזמיר על מקום אביו, הקים ק\"ק שונצין באזמיר. חיבר \"לשון ערומים\", \"לשון למודים\". מתלמידיו - חתנו-ר יהודה אשכנזי, ר יצחק בינמנטי בעל \"שער המלך\". הספיד את: ר אליהו הכהן-תפט, ר ישראל בנבנישתי-תקך, ר אליהו חאקו-תקיד, דודו ר משה שוחמי-תקיד, ר אברהם יצחקי-תצט, ר אברהם ארדיטי, ועוד. מתלמידיו: חתנו - ר יהודה אשכנזי, ר יצחק נוניס בילמונטי. (אצל רוזניס נרשם שנת לידתו - תך - כנראה בטעות).","bk":[["לשון ערומים",""],["לשון ערומים","מפרשי רמב\"ם"],["לשון למודים - טור",""],["לשון למודים",""]]},{"i":23535,"n":"יעבץ, זוסמן","b":"בנו - ר זאב מלונדון."},{"i":23536,"n":"יעבץ, זכריה מצעדה-תימן","f":"יעקב","k":"בעל ערימת חטים","bt":"תרכ","bp":"צעדה","dt":"תשב","dp":"צעדה","b":"רב ראשי ואב\"ד בצעדה, עסק ברפואה טבעית, חיבר \"ערימת חטים\" ובו חידושי תורה, הלכה, מוסר וקבלה"},{"i":23537,"n":"יעבץ, חיים ליב מחרסקוב","b":"מצאצאי ר יעקב עמדן. חסיד ר מאיר מפרימישלן."},{"i":23538,"n":"יעבץ, יהודה ליב מירושלים","k":"ליב קאלנער","dt":"תרלד - ג ניסן","dp":"ירושלים","b":"חתן ר יצחק אריה ליב מסטאויסק. מחכמי ירושלים. עמד לצדו של ר מנדל ירושלמסקי בזמן המחלוקת. נכדו - הסופר זאב יעבץ."},{"i":23539,"n":"יעבץ, יהודה משלוניקי","dt":"שעה - כג אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":23540,"n":"יעבץ, יוסף החסיד (הדורש) מספרד","f":"חיים או אברהם","k":"בעל אור החיים","bp":"ספרד","b":"מחכמי ספרד, ליסבון. תלמיד ר יוסף חיון. לאחר הגירוש עבר למנטובה-רנג. ממתנגדי הפילוסופיה. חיבר גם \"יסוד האמונה\", \"מאמר האחדות\"."},{"i":23541,"n":"יעבץ, יוסף משלוניקי","f":"יצחק בן יוסף בן חיים","dt":"שם - תשרי","dp":"שלוניקי","b":"הקים דפוס באדרינופול-שיד, שלוניקי-שך, ובקושטא - עם אחיו ר שלמה."},{"i":23542,"n":"יעבץ, יעקב הלוי משפיירא","f":"יצחק סגן לויה","b":"תלמיד רבנו קלונימוס, מבעלי התוספות, מרביץ תורה בוורמייזא-ד'תתנו."},{"i":23543,"n":"יעבץ, יצחק מאיטליה","f":"שלמה","k":"בעל תורת חסד","b":"נכד ר יוסף יעבץ. מחכמי איטליה ממשפחה ממגורשי ספרד. חיבר גם \"קהלת משה\" פירוש למקרא, ועוד."},{"i":23544,"n":"יעבץ, יצחק מספרד","f":"יוסף החסיד","dt":"שח","b":"ממגורשי ספרד, והתישב באיטליה עם אביו, מדפיס בשלוניקי. בניו - ר יוסף המדפיס משלוניקי, ור שלמה אביו של ר יצחק בעל \"תורה חסד\"."},{"i":23545,"n":"יעבץ, ישראל איסר מהרובשיב","f":"יוסף מאיר","bt":"תרכא","b":"רב בפישטשץ, הרובאשוב(=הרובשיב)-פלך לובלין-תרנה."},{"i":23546,"n":"יעבץ, ישראל יעקב מקרמנצוג וא\"י","k":"בעל תשובות מהריש","b":"רב בקרמנצוג-תר\"ל,עלה לא\"י"},{"i":23547,"n":"יעבץ, מיכאל מירושלים","f":"אברהם","k":"בעל שבחות לאל","b":"מחכמי ירושלים."},{"i":23548,"n":"יעבץ, מנחם מנדל מקופיטשיניץ","b":"נכד ר מאיר מקונסטנטין בן ר יעקב עמדין. תלמיד ר חיים מקוסוב, ר מנחם מנדל מויזניץ. רב בקופיטשיניץ. עלה לצפת-תרטו, והיה ממונה \"כולל אסטרויק\"."},{"i":23549,"n":"יעבץ, משה (יאכנעס)","f":"איזיק מקוריץ","b":"תלמיד הבעשט. בנו ר יוסף מפולנאה, ונכדו ר הלל משומסק."},{"i":23550,"n":"יעבץ, משה זאב וולף מהורדנא","f":"ראה: מרגליות, משה זא"},{"i":23551,"n":"יעבץ, עובדיה מתימן","dt":"תשא","dp":"תימן","b":"אב\"ד בצפון תימן. בנו - ר יעקב, ונכדו - ר עובדיה מקרית עקרון. אולי הוא שהעתיק-תרצט בכתב ידו את הספר \"גורלות לאחיתופל\"."},{"i":23552,"n":"יעבץ, עובדיה מתימן וקרית עקרון","f":"יעקב","k":"בעל אפיקי מים","bt":"תרפב","dt":"תשעא - יב שבט","b":"רב בצעדא-תימן על מקום אביו וזקנו, עלה לארץ-תשט וכיהן כרב בקרית עקרון. מראשי יהדות תימן."},{"i":23553,"n":"יעבץ, שמואל (שלמה) משלוניקי","b":"מחכמי שלוניקי-שלא. הקים דפוס עם אחיו - ר יוסף בשלוניקי-שך ובקושטא."},{"i":23554,"n":"יעבץ, שמואל יצחק מוילנא","f":"משה זאב וולף מרגליות","dt":"תרמג - כא ניסן","dp":"וילנא","b":"חתן ר הלל פינקלשטין אלקסטר, ובזיוו\"ש חתן הגביר ר יוסף בן יונה ברוידא-ר יאסיל יונה'ס. גביר מחכמי וילנא. עסק בהדפסת ספר אביו - אגודת אזוב, ואחר שנפטר המשיך בנו ר דוד את ההדפסה."},{"i":23555,"n":"יעבץ-מילר, משה יהודה מצפת","f":"אורי מנשה יעבץ מצפת","dt":"תרעג - ל סיון","dp":"צפת","b":"חתן ר חנוך זנידל פוגל מוישווא. אב\"ד סניטין, עלה לצפת וכיהן כדיין."},{"i":23556,"n":"יעוונין, אברהם יונה","k":"בעל חדושי מהרא\"י","bt":"ה'תקעג","dt":"ה'תרח","b":"חתן ר בצלאל מהורדנא. חיבר גם \"נימוקי מהרא\"י\", ו\"גליון מהרא\"י\".","bk":[["נמוקי מהרא\"י [על המשניות והרמב\"ם]",""],["נמוקי מהרא\"י",""]]},{"i":23557,"n":"יעיש - משפחה","b":"פירוש השם יעיש בערבית הוא יחיא. משפחת רבנים בצפון אפריקה ובתורכיה."},{"i":23558,"n":"יעיש מאופראן-מרוקו","f":"משה","dp":"אופראן-מרוקו","b":"מחכמי מרוקו-תם."},{"i":23559,"n":"יעיש, אברהם מאלגיר","b":"רב בתלמסאן. נזכר בפנקס ר סעדיה בן סידון (ברשימת ר\"י רוש)."},{"i":23560,"n":"יעיש, אברהם מברושה- הנכד","b":"נכד ר אברהם ן יעיש מקושטא. תלמיד ר יוסף קארו. רב בברוסה(=ברושה)-ש' ור יוסף אביוב על מקומו אחריו (לפי רוזניס - גם ר אברהם אלגזי על מקומו), עבר לקושטא, היה במחלוקת עם ר יהודה ן בולאט ועם ר תם ן יחיא. נזכר בתשובות חכמי דורו ובהם בשו\"ת מהרשד\"ם. בניו: ר יו\"ט, ר יוסף, שהיו גבירים בקושטא והחזיקו את מהרי\"ט ובית מדרשו. נפטר סמוך לפטירת זקנו שעל שמו נקרא. אחיו - ר שלמה מברושה וקושטא."},{"i":23561,"n":"יעיש, אברהם מירושלים","b":"מצאצאי דון יחיא בן יעיש סוכן מלך פורטוגל (בשנת ד'תתקמה 1185 ) חתום בירושלים על הסכמת המסים משנת שכו. אולי הוא תלמיד ר יוסף קארו שהיה מקודם בברוסא, ומופיע בשו\"ת ר יוסף קארו ובאבקת רוכל קכו. משערים שהיה נכדו של ר אברהם בן יעיש הזקן מקושטא שחתם על \"ברכת אברהם\" לר אברהם צרפתי."},{"i":23562,"n":"יעיש, אברהם מקושטא","f":"יום טוב","b":"גביר מחכמי קושטא-שנות ה-ת'. אחיו - הגביר ר משה מקושטא."},{"i":23563,"n":"יעיש, אברהם מקושטא","f":"יהודה","b":"מחכמי קושטא-שנות ה-ת'."},{"i":23564,"n":"יעיש, אברהם מקושטא - הזקן","f":"יוסף בן אברהם","dt":"רצב?","b":"פוסק, מחכמי פורטוגל, עבר לקושטא בגירוש-רנז. תלמיד הרא\"ם. מגיה בדפוס קושטא-רסט. מתשובותיו בספרי חכמי דורו ובהם בשו\"ת הרא\"ם, ב\"אהלי תם\" לחברו ר תם ן יחיא. הסכים על \"ברכת אברהם\" למהר\"א טריויש. נספד עם נכדו - שנפטר מיד לאחריו בידי ר יוסף ן לב."},{"i":23565,"n":"יעיש, אברהם משלוניקי","dt":"שיד - כא תשרי","dp":"שלוניקי","b":"רב בשאלוניקי"},{"i":23566,"n":"יעיש, אברהם משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":23567,"n":"יעיש, אברהם משלוניקי - ב","dt":"תנא - כח חשון","dp":"שלוניקי","b":"דיין-תכה עם ר משה חיים שבתי ור בנימין עשאל. רב הכולל בשלוניקי על מקום ר בנימין עשאל. אצל רוזניס תאריך פטירתו - תכא."},{"i":23568,"n":"יעיש, ברוך משלוניקי","f":"יצחק","k":"בעל מקור ברוך","b":"רב בשלוניקי-שלז, איטליה, מתרגם ספרים מערבית ומלאטינית לעברית. חיבר \"מקור ברוך\" - פירוש על שיר השירים קהילת ואיוב - קושטא שלו."},{"i":23569,"n":"יעיש, דוד - ב","f":"שלמה","b":"חתם שמו על שו\"ת יכין ובועז - ליוורנו תקמב."},{"i":23570,"n":"יעיש, דוד משלוניקי","dt":"תקטו","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":23571,"n":"יעיש, חיים מירושלים","b":"מחכמי ירושלים-שנות ה-תק'."},{"i":23572,"n":"יעיש, יהודה מאלגיר","dt":"תרץ - בערך","b":"רב בווהראן, מיסד חברת צדקה וחסד ע\"ש אליהו הנביא."},{"i":23573,"n":"יעיש, יהודה מאלגיר","dt":"תץ - בערך","b":"מוקאדם(=זקן הקהל) בקהלת אלגיר-תן-תס. נזכר בשו\"ת \"בית יהודה\" ליוורנו תקו."},{"i":23574,"n":"יעיש, יום טוב מברושה וקושטא","f":"אברהם","b":"גביר מחכמי קושטא יחד עם אחיו ר יוסף (שנפטר צעיר), ממונה על החזקות-שסב עם ר משה משלם הלוי ועוד, עשיר מופלג, סייע לר יוסף בן משה טרני בבואו לקושטא ורב ראשי על מקומו אחריו. תשובות ממנו ב\"פני משה\" לר משה בנבנשתי."},{"i":23575,"n":"יעיש, יעקב מקושטא","b":"מחכמי קושטא-שנות ה-ש'-ת'."},{"i":23576,"n":"יעיש, יצחק ממידיאה-אלגיר","b":"מגדולי חכמי פאס-ש\"נ"},{"i":23577,"n":"יעיש, ישראל מאלגיר","bt":"תמ","dt":"תקי","b":"רב בלמדייא(=מידיאה). דיין עם ר מסעוד אשורקי. שאלה ממנו לר מימון יאפיל."},{"i":23578,"n":"יעיש, ישראל מאלגיר","f":"שלמה","b":"רב בתלמסאן. ונזכר בפנקס ר סדיה בן סידון, ורשימת ר יצחק רוש."},{"i":23579,"n":"יעיש, מאיר מאלגיר","bt":"תרסז","bp":"למדייא(=מידיאה)-אלגיר","dt":"תשנג","dp":"פאריס","b":"רב בהגנאו-צרפת, רב צבאי בצרפת, רב בפאריס מטעם הקונסיסטואר. חיבר ספר דקדוק עברי - בכת\"י."},{"i":23580,"n":"יעיש, מאיר מקושטא","b":"רב בקושטא. נזכר כבעל דין בבאלאט-תקצט, ממונה על איסור והיתר-תרו ואב\"ד איסור והיתר-תריח, רב הכולל-תרלה. חתם על תקנות והסכמות רבות מטעם רבנות קושטא. הסכים על \"מעשה נסים\" לר משה יצחק הלוי מסופיה."},{"i":23581,"n":"יעיש, מרדכי מארץ ישראל","b":"מחכמי ארץ ישראל, בשנת תקז חתם על כתב שליחות ר שלמה עבדי ויצא עמו בשליחות לתימן והודו."},{"i":23582,"n":"יעיש, משה מאלגיר","k":"בעל שיח משה","b":"כנראה היה רב באלגיר. מחבר \"שיח משה\" (נדפס עם \"בני שלמה\" לר שלמה זוראפה - ליוורנו תקפב)."},{"i":23583,"n":"יעיש, משה מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק',"},{"i":23584,"n":"יעיש, משה מקושטא","f":"יום טוב","b":"גביר מחכמי קושטא-שנות ה-ת'. יסד ישיבה בירושלים ובראשה עמד ר משה ן חביב בעל \"גט פשוט\". אחיו - הגביר ר אברהם מקושטא."},{"i":23585,"n":"יעיש, משה משלוניקי - א","b":"ר\"מ בק\"ק \"מאיור\" בשלוניקי. חתם על \"הסכמות הקהל\" בשלוניקי-רצג. אחיו או קרובו של ר אברהם."},{"i":23586,"n":"יעיש, משה משלוניקי - ב","dt":"תלא - כג תמוז","dp":"שלוניקי","b":"תלמיד ר אליהו גאולטיל. רב ודיין בשלוניקי-תיח. נזכר ב\"עדות ביעקב\" לר יעקב די בוטון."},{"i":23587,"n":"יעיש, נסים ממצרים","b":"דיין במצרים-רפז בזמן הרדב\"ז, וחתם על הסכם השלום שערך הרדבז בין קהילת \"מסתערב\" לק\"ק \"מערבים\"."},{"i":23588,"n":"יעיש, שלמה","f":"דוד","b":"דיין בספרד, נזכר ב\"זכרון יהודה\" לר יהודה בן הרא\"ש."},{"i":23589,"n":"יעיש, שלמה מספרד","b":"מחכמי ספרד, אחיו של ר אברהם מברושה, ולאחר הגירוש התישב בברוסה-תורכיה, קושטא. נזכר בתשובות הרמ\"א."},{"i":23590,"n":"יעיש, שלמה משלוניקי","dt":"תיט - יג אב","dp":"שלוניקי","b":"מחכמי שלוניקי, יסד ישיבה בביתו, נספד ע\"י ר אהרן פרחיה הכהן."},{"i":23591,"n":"יעלון, שלום אברהם יהודה משדליץ","b":"רב בשדליץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":23592,"n":"יעליגוביץ, אהרן מויסאקי-דוואר","dt":"תשג","b":"מרבני ויסאקי-דוואר"},{"i":23593,"n":"יענער, אברהם מקראקא","b":"ראב\"ד בקרקא-תר\"כ"},{"i":23594,"n":"יעסעל ( דזעסעל), גיאורג מלונדו","f":"צדוק אהרן","bt":"תקפד","bp":"לונדון","dt":"תרלג - ו אד\"ב","b":"אב בתי המשפט באנגליה. נשיא חברת היהודים באנגליה, פעל לטובת יהודי רומניה."},{"i":23595,"n":"יעקב","f":"דוד","b":"רב-שנת תק\"ל"},{"i":23596,"n":"יעקב","f":"שמעיה","k":"בעל קהלת יעקב","b":"רב-שנת ת\"ק"},{"i":23597,"n":"יעקב","f":"מאיר מהמגרב","b":"תשובה ממנו ב\"אורח לצדיק\" לר אברהם רודריגס."},{"i":23598,"n":"יעקב","f":"עזריאל מוילנא","k":"בעל טורי זהב","b":"אחיו של ר צבי הירש בעל \"לחם יהודה\". חתן ר יצחק בנימין וולף מסלוצק בעל \"נחלת בנימין\"."},{"i":23599,"n":"יעקב","f":"מאיר","b":"חכם שלם, עסק במסחר, העיד-תקס בשירון בענין עגונה."},{"i":23600,"n":"יעקב (ניקול) מאופן","b":"שתדלן יהודי, היה במשלחת-קצו בפני זיגמונד מלך הונגריה בקשר לזכויות היהודים."},{"i":23601,"n":"יעקב (רוטרדם) מלבוב","f":"אברהם מרוטרדם","dt":"תסב - כט שבט","dp":"לבוב","b":"חתן ר דוד לידא מאמשטרדם בעל \"עיר מקלט\". מרביץ תורה בלבוב."},{"i":23602,"n":"יעקב - השלישי","f":"ראובן","k":"בעל מלחמות השם","b":"חכם ופילוסוף קדמון. אולי הוא שחיבר גם \"היכל השם\" ונזכר אצל ר משה בוטרילי בפירושו לספר יצירה."},{"i":23603,"n":"יעקב - השני","f":"ראובן","k":"בעל העושר","b":"חכם תורני (אינו ר יעקב הקראי). חיבר או תרגם \"העושר בסגולות האבנים הטובות\"."},{"i":23604,"n":"יעקב אביגדור מאדרינופול","b":"רב באדרינופולי-עד תרכ\"ג"},{"i":23605,"n":"יעקב אבינו","dt":"טו תשרי"},{"i":23606,"n":"יעקב אברהם ז\"ש מקראקא ולייפניק","f":"רפאל","k":"בעל נחלת יעקב","b":"חתן ר דוד מואדיסלב-בנו של ר יצחק לנדא מאפטא. רב בראקוב, לייפניק-תנ. בספריו הביא מחדושי חותנו זקנו. הסכים על \"ויכתב משה\" תנד, \"גבורת אנשים\" דעסוי תנז, ועוד. בנו - ר שמריה זלמן בעל \"אבני שהם\". וחתנו - ר הלל מינץ על מקומו אחריו בלייפניק."},{"i":23607,"n":"יעקב אברהם מלבוב","f":"יצחק מזולקוא","b":"חתן ר יעקב שור בעל \"בית יעקב\". מנהיג, רב בלבוב, זולקוא חתם בפנקס קראקא-תסח עם רבני הגליל, חתם בועד ירוסלב-תעח."},{"i":23608,"n":"יעקב אברהם מפוזנא ולאסק","f":"נחמן מלאסק","dt":"תקע - יא אדר","dp":"לאסק","b":"רב בעיר חדש-מחוז פוזנא, לאסק. נזכר ב\"פערגאנגעהייט אונד געגעגווארט\" לר\"ד העפנער."},{"i":23609,"n":"יעקב אהרן מאלכסנדר","f":"משה מזלושין-יאנוב","k":"בעל בית יעקב","b":"תלמיד החוזה מלובלין, המגיד מקוזניץ, היהודי הקדוש מפשיסחא, ור שמחה בונם מפשיסחא. ותלמידו בנגלה של ר יעקב מליסא. אב\"ד זאלושין, קאריב, טומשוב, אלכסנדר. חיבר \"בית יעקב\"."},{"i":23610,"n":"יעקב אהרן מבריסק","f":"ישראל איסרל מבריסק","b":"מחכמי בריסק-תקכח. בנו - ר משה בעל \"אבן משה\"."},{"i":23611,"n":"יעקב אורי שרגא פיבש מזלוטוב","f":"מנחם נחום","k":"בעל תהלת יעקב","b":"רב בזלאטאווא(=זלוטוב)-תקכ. חיבר גם \"בית יעקב אש\", \"רשפי אש\"."},{"i":23612,"n":"יעקב אל מצרי","f":"אבולעפיה, יעקב","b":"רב בדמשק-ת\"כ"},{"i":23613,"n":"יעקב אלחנן","k":"מפפד\"מ","dt":"שעז","b":"מחכמי פפד\"מ."},{"i":23614,"n":"יעקב אליהו הכהן מברעזי וסעלץ","f":"דב בער מברסטביץ","k":"בעל מנחת כהן","b":"רב בקארטוז-ברזי(=ברעזי)-תרל, סעלץ. בנו - ר יוסף ממזריטש. נספד מאת ר חיים מאיר נח ממוסקבה."},{"i":23615,"n":"יעקב אליהו חריף מזלוטשוב","f":"משה מאך משאראגרד","dt":"תלד - ד אייר","b":"רב בזלוטשוב, בוצאץ?. חתן ר חיים מקאלין ופיהם."},{"i":23616,"n":"יעקב אליהו מוינה","b":"גביר מראשי קהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\"."},{"i":23617,"n":"יעקב אליעזר מבריסק","f":"משה ליזרס","b":"גביר מחכמי בריסק-שפז עד תל. חתן נכדת הרמ\"א וסייע בהוצאת שו\"ת הרמ\"א-ת'. מחותן עם ר נתן שפירא בעל מגלה עמוקות - חתנו - ר משה שפירא."},{"i":23618,"n":"יעקב אליעזר מקולומיי","dt":"תרצז - כז שבט","b":"מו\"צ בקולומיי"},{"i":23619,"n":"יעקב אליעזר מראסיין","dt":"תרלט","dp":"ראסיין","b":"שמש ביהמ\"ד ומחכמי ראסיין."},{"i":23620,"n":"יעקב אליקים געטשליק כץ מלבוב","b":"חתם בלבוב-שפג-ד על תקנות קהלת זולקווא, ר אברהם כהן בעל \"איתן האזרחי\", ר זאב וולף קאליש מלבוב."},{"i":23621,"n":"יעקב אריה","b":"מחכמי ארץ ישראל ונקרא בעל הנס על שום נס שאירע לו. בשנת תלט בשליחות בבגדד, והביא משם עותק של ספר הפרכוס לר האי גאון. לדעת ריבלין הוא אביו של ר אברהם בעל הנס (וכנראה שהשם אריה היה שמו ולא על שם הנס)."},{"i":23622,"n":"יעקב אריה ליב מוילנא","f":"מרדכי","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":23623,"n":"יעקב אריה ליב מלבאשוב","f":"יצחק","b":"רב בלובעשאוו(=לובאשוב)-תרמ על מקום אביו, וחתנו ר אליעזר ליפא קלפפיש על מקומו אחריו-תרסז."},{"i":23624,"n":"יעקב אריה מוידין","b":"גביר מחכמי וידין, פעל בענין יהודי סאמאקוב-תקסא (שהיתה קהלה חדשה אז)."},{"i":23625,"n":"יעקב אריה מוישניצה","f":"מרדכי","k":"בעל תולדות יעקב","b":"רב בוישניצה. חיבר \"תולדות יעקב\" למברג תרכב."},{"i":23626,"n":"יעקב אריה מירושלים","b":"מחכמי ישיבת בית יעקב פיררה בירושלים-תקו."},{"i":23627,"n":"יעקב אריה מסופיה","b":"רב בסופיה-שנות ה-ת'."},{"i":23628,"n":"יעקב אשכנזי הכהן מאלגיר","bt":"קס","dt":"רל - בערך","b":"הגיע מאשכנז לאלגיר בזמן הרשב\"ש. רב דיין ומלמד תורה בתלמסאן - ומתלמידיו ר ישועה הלוי בעל \"הליכות עולם\" המביא מתורתו בספרו. נזכר אצל ר\"י ששפורטש."},{"i":23629,"n":"יעקב בחור מלבוב","dt":"קח - כב אלול","dp":"לבוב","b":"מחכמי לבוב. נפטר צעיר."},{"i":23630,"n":"יעקב בכור הלוי מירושלים","dt":"תרעז - ט ניסן","b":"מגדולי חכמי ירושלים"},{"i":23631,"n":"יעקב בכור נחום משלוניקי","b":"מחכמי שלוניקי-תקס."},{"i":23632,"n":"יעקב בן אשר","f":"הרא\"ש","r":"הטור","bt":"1270","dt":"ה'ק 1340","b":"מגדולי הפוסקים הראשונים,עמוד ההוראה לכל הדורות,דיין בטולידו","bk":[["ארבעה טורים",""],["בעל הטורים עה''ת",""],["הלכות ארץ ישראל",""],["טור",""],["פירוש הטור הארוך",""],["פרוש התורה",""],["בעל הטורים","מפרשי תורה"],["ארבעה טורים \\ טור",""],["ארבעה טורים \\ טור , בעל הטורים עה\"ת",""],["קיצור פסקי הרא\"ש",""]],"e":"כ\"ט~-ק\"ג"},{"i":23633,"n":"יעקב בן יעקב משה מליסה","bt":"1770","dt":"ה'תקצב 1832","bk":[["אמרי ישר",""],["אמת ליעקב",""],["דרך החיים",""],["חוות דעת",""],["חמשה ספרים נפתחים",""],["מגלת סתרים",""],["מילי דאגדתא ושו\"ת",""],["מקור חיים",""],["מקור חיים ומגן אלף",""],["מקור חיים ומגן האלף",""],["נחלת יעקב",""],["נתיבות המשפט",""],["סדור דרך החיים",""],["סדור כתר תפלה",""],["סדור תפלת ישרים",""],["סדר הגדה של פסח מעשה נסים",""],["סדר הגדה של פסח מעשה נסים מגלת ספר",""],["סדר תפלת ישראל עם דרך החיים",""],["סידור דרך החיים",""],["קהלת יעקב",""],["שושנת העמקים",""],["תורת גיטין",""],["תעלומות חכמה",""],["בית יעקב",""]]},{"i":23634,"n":"יעקב בן יצחק מינוב","bt":"1550","dt":"ה'שפח 1628","bk":[["צאינה וראינה",""]]},{"i":23635,"n":"יעקב בן מאיר (ר\"ת); אפשטין יחיאל מיכל בן אהרן יצחק","bt":"1829","dt":"ה'תרסח 1908","bk":[["ספר הישר",""]]},{"i":23636,"n":"יעקב בעל התוספות","f":"אבין","b":"נזכר בתוספות חולין."},{"i":23637,"n":"יעקב בעל התוספות","f":"יהוצדק","b":"מבעלי התוספות."},{"i":23638,"n":"יעקב בער","dt":"תקצ - כט סיון","b":"רב בטיסאבעא"},{"i":23639,"n":"יעקב בצלאל מבילהראדקיע","f":"פנחס משעפטיווקע","k":"בעל הלכות פסוקות","b":"מו\"צ בבילהראדקיע-מחוז זסלאב פלך ווהלין. חיבר גם \"שושנת יעקב\" בהלכות טריפה."},{"i":23640,"n":"יעקב ברוך מבוטען ושפאלע","f":"צבי","k":"בעל שארית יעקב","b":"מו\"צ ומ\"מ בבוטען, פאלאנקע-ליטא, מעלוב-ליטא, שפאלע(=שפולה)."},{"i":23641,"n":"יעקב ברוך מירושלים","b":"מחכמי ירושלים-תפז ועסקן העדה הספרדית, בשנת תקא חתם על כתב שליחות ר אברהם בן אשר ור יצחק זרחיה אזולאי."},{"i":23642,"n":"יעקב ברוך מרגנטהיים","b":"נציג קהילת פפד\"מ בוינה אצל הקיסר-תקס בערך. בזכות התערבותו הותר ליהודי פפד\"מ להשתתף בירידים. ויועץ הסתר של הקיסר שיבח את קהילת פפד\"מ על שבחרה אדם כזה לתפקיד."},{"i":23643,"n":"יעקב בש\"ה","b":"מחכמי בעלי התוספות-ד'תתק\"ע"},{"i":23644,"n":"יעקב גאון הכהן מסורא","f":"מרדכי","b":"גאון סורא-ד'תקסה, היה הראשון שהקל בבדיקת הריאה."},{"i":23645,"n":"יעקב דב בער מראמין וצפת","b":"חסיד ר ישראל מרוזין. רב בראמין, ואלחיי, טעריקל, פארגאס-רומניה, עלה לצפת. ממונה מטעם פקידים ואמרכלים יחד עם ר שמואל הלר והיה מחלוקת ביניהם. נזכר ב\"חוקי חיים\" ירושלים תרנג, \"אבני צדק\" לבעל ייטב לב, גביית עדות אודותיו מאת ר בצלאל ברש\"ח (בן ר שלמה חיים) בצפת-תרמד אצל הדיינים ר שמואל מחרסקוב, ר זיידא קלינגר, ר דוד באבד."},{"i":23646,"n":"יעקב דוד הכהן","f":"יודל מאוזירן","b":"חתן ר יוסף ארינשטין מקריווטש."},{"i":23647,"n":"יעקב דוד הכהן מצידון","b":"דיין בצידון-תן, אצל ר אברהם בן משה גלנטי."},{"i":23648,"n":"יעקב דוד יקותיאל הכהן","k":"בעל שלל דוד,הנכד","b":"מצאצאי ר דוד רפפורט בעל \"דעת קדושים\". מחכמי ירושלים, בשליחות בצפון אפריקה והיה בטריפולי-תקן, ואחר כך בשליחות ירושלים בשנת תקסו. הדפיס בליוורנו את ספרי זקנו - \"דעת קדושים\", ו\"בן הא הא\". חיבר \"שלל דוד\", \"לדוד אמת\"."},{"i":23649,"n":"יעקב דוד מרזישנוב ומיידאן","f":"יצחק","dt":"תרנח","b":"רב ברזישנוב, מיידאן(=מאדין)-תרל."},{"i":23650,"n":"יעקב דוד משמילויזנע","f":"ישראל יצחק","b":"רב בשמילעויזנע(=שמילויזנע). הסכים על תהלות חיים לר חיים פלטרוביץ."},{"i":23651,"n":"יעקב דיין מלובלין","f":"בנימין וולף","dt":"תקנא - א אייר","dp":"לובלין","b":"מרביץ תורה ודיין בלובלין."},{"i":23652,"n":"יעקב דניאל משלוניקי - א","dp":"צפת","b":"רופא בשלוניקי - בשנות הש'. נספד ע\"י ר סעדיה לונגו."},{"i":23653,"n":"יעקב דניאל משלוניקי ואישטיפי","bp":"שלוניקי","b":"תלמיד קרובו ר דוד קונפורטי, ישיבת ר מרדכי קלעי. ר\"מ באישטיפי-שנות ה-ת'."},{"i":23654,"n":"יעקב ה\"אופה\" מפילץ","b":"חברו של ר דוד מללוב."},{"i":23655,"n":"יעקב האלקושי","k":"בעל ספר האלקושי","b":"מגדולי בעל התוספות בצרפת-ד'תתפ\"ג"},{"i":23656,"n":"יעקב האשבטי ממרוקו","k":"בעל עץ חיים - בכת\"י","b":"מחכמי מרוקו. חיבר ספר דרושים ובו דרושים מהשנים תלו-תלח, \"עץ הדעת\". (אולי המחבר הוא ר דניאל בהלול, לפי \"נר המערב\" המחבר הוא - ר יצחק ן חיים)."},{"i":23657,"n":"יעקב ה\"חזן\" מגאליב","b":"תלמיד החוזה מלובלין, ששלחו לכהן כחזן ושו\"ב בגאליב-מחוז פוזנא. נתפרסם כצדיק."},{"i":23658,"n":"יעקב החסיד","k":"בעל שות מן השמים","b":"שואל שאלות מהשמים ומשיבים לו,מרביץ תורה במרויש-ד'תתקס\"ג"},{"i":23659,"n":"יעקב היוצר פרגאן ממרוקו","b":"כתב את זכרונותיו על נדודיו-בשנת שע ומאסרו בכפר תרודנאת, אופראן, כפר אקא."},{"i":23660,"n":"יעקב הכהן","f":"נתנאל","k":"בעל ספר מסעות לא\"י","b":"רב וחוקר, נסע לא\"י-ד'תתק\"ס וחבר ספר על מסעו."},{"i":23661,"n":"יעקב הכהן הפרנס מירושלים","b":"מחכמי ירושלים, בשנת ד'תתנא (1091) בשליחות במצרים."},{"i":23662,"n":"יעקב הכהן מאלגיר","bt":"תרך","dt":"תרץ - בערך","b":"רב ומלמד תורה בעונאבא(=בון) - תרס-תרפה. נזכר בהקדמת ר רחמים נאהורי ל\"שארית יעקב\" - ירושלים תשמג."},{"i":23663,"n":"יעקב הכהן מאנטאקליא","f":"אברהם","k":"בעל דברי חפץ","dt":"תרכו - כו ניסן","b":"דרשן, מו\"צ באנטאקליא על מקום ר ישראל זרחי, פדברעזע, וידז."},{"i":23664,"n":"יעקב הכהן מאנקונא","dt":"שיו - ז תמז","dp":"אנקונא","b":"אחד מ-24 הרוגי אנקונא על פי עדות ר שלמה חזן מאנקונא. קינה לזכרם מאת ר אברהם דוד חי."},{"i":23665,"n":"יעקב הכהן מבריסק","f":"זאב","dt":"תר - ג שבט","dp":"בריסק","b":"דיין ומו\"צ בבריסק."},{"i":23666,"n":"יעקב הכהן מג'רבה","f":"אברהם","k":"בעל מאין יבא","b":"מחכמי ג'רבא-תרן. חיבר גם \"מעיל יעקב\".","bk":[["מעיל יעקב","מסכת מעילה"]]},{"i":23667,"n":"יעקב הכהן מוואלפא אלכסנדרובסקי","k":"יעקב כהן גדול","b":"תלמיד ר יעקב יוסף הכהן מפולנאה, מחסידי ר שלמה מקרלין. רב בוואלפא, פרש מהרבנות. החזיק בכתב יחוס עד הכהן אלכסנדר הראשון שבימי שמעון הצדיק ונשרף באורליא - שינה שם משפחתו לאלכסנדרובסקי. בנו ר יצחק איזיק כץ בעל \"שערי יצחק\"."},{"i":23668,"n":"יעקב הכהן מוישטיניץ","f":"חיים פיבש","k":"בעל זרע יעקב","b":"רב בוויסטניץ(=וישטיניץ)-תקל."},{"i":23669,"n":"יעקב הכהן מונציה","dt":"שנו - יב שבט","b":"דיין בונציה אצל ר שמואל יהודה קצנלנבוגן. תשובה ממנו ב\"דבר שמואל\""},{"i":23670,"n":"יעקב הכהן מחלב","bt":"תרא","b":"רב בארם צובא-תרע."},{"i":23671,"n":"יעקב הכהן מטבריה","dt":"תקצז","dp":"טבריה","b":"מחכמי טבריה, נספה ברעש בשנת תקצז"},{"i":23672,"n":"יעקב הכהן מטיטואן","f":"דוד","b":"מחכמי טיטואן, חתם על פס\"ד-תח עם ר חנניה ארובש. בנו - ר דוד הכהן השני מטיטואן."},{"i":23673,"n":"יעקב הכהן מטנג'יר","b":"חתם בטנג'יר-תרפב עם ר יהודה אזנקוט רבה של טנג'יר."},{"i":23674,"n":"יעקב הכהן מירושלים (הקדוש)","b":"מחכמי ישיבת \"יפאר ענוים\" בירושלים-שנות ה-תק'."},{"i":23675,"n":"יעקב הכהן מליזנסק","b":"רב בליזנסק-תריז."},{"i":23676,"n":"יעקב הכהן ממגנישיאה","b":"רב במגנישיאה-שנות ה-ש'."},{"i":23677,"n":"יעקב הכהן ממוגאדור","k":"בעל זכר עשה","b":"מחכמי מוגאדור-שנות ה-התר'. חיבר גם \"יזכור לעולם\". הסכים על \"פלגי מים\" לר שמואל אביקציץ."},{"i":23678,"n":"יעקב הכהן ממוגאדור","dt":"תקס - אחרי","b":"מחכמי מוגאדור. נזכר ב\"תקפו של יוסף\"."},{"i":23679,"n":"יעקב הכהן ממוגאדור","f":"אלעזר","b":"רב במוגאדור(=אצוויר, אסואירה), חתם-תקסג עם ר חיים פינטו הגדול."},{"i":23680,"n":"יעקב הכהן ממיהלוביץ","b":"רב במיהאלוביץ"},{"i":23681,"n":"יעקב הכהן ממכנאס","b":"מחכמי מכנאס, חתם על פס\"ד-תקצד עם ר שמואל הלוי."},{"i":23682,"n":"יעקב הכהן מפאס","f":"אברהם","b":"רב בפאס, חתם על פס\"ד-שד עם ר וידאל הצרפתי, ר שם טוב אמיגו."},{"i":23683,"n":"יעקב הכהן מצפת","b":"רב בצפת, חתם-תרלז על כתב שליחות ר יעקב חיון, עם ר יהודה חכים, ר שמואל עבו, ר מרדכי מאמאן ועוד."},{"i":23684,"n":"יעקב הכהן מקאסטוריה","b":"מחכמי קאסטוריה, ממאמיני ש\"ץ, והמיר דתו בעקבותיו, ולאחר מכן חזר ליהדות וביקש לעזוב את העיר."},{"i":23685,"n":"יעקב הכהן מקטוביץ","f":"אהרן","bt":"תרד","bp":"אלטונה","b":"תלמיד ר יעקב עטלינגר, ר יעקב כץ מאלטונא, ר ישעיה הולנדר מאלטונא, ביהמ\"ד לרבנים באיזנשטט. רב בקאטוביץ(=קטוביץ)-תרלב."},{"i":23686,"n":"יעקב הכהן משגוביא","b":"מגדולי מקובלי ספרד-שנת ס',בשוריא,בדרש,נרבונה,פרובינצא,חזר לספרד לשגוביא"},{"i":23687,"n":"יעקב הכהן משירון","b":"רב בשירון-שנות ה-ת'."},{"i":23688,"n":"יעקב הכהן משלוניקי","dt":"שפא - ב אב","dp":"שלוניקי","b":"תלמיד ר שבתי יונה המזכירו בספרו \"שי למורא\". מגדולי חכמי דורו בשלוניקי-שפ. מתלמידיו - ר שמואל גאון."},{"i":23689,"n":"יעקב הכהן משערשוב","dt":"תרסא","dp":"ירושלים","b":"דיין בשארשוב אצל בעל \"ברכת ראש\", עלה לירושלים בתרנב. חתנו היה ר ישעיה אשר זליג מרגליות."},{"i":23690,"n":"יעקב הלוי","b":"רב-שנת ת\"פ"},{"i":23691,"n":"יעקב הלוי (וייל)","f":"משה בן יונה וייל","k":"חתן מהר\"ם פדובה","dt":"שלב - אלול","b":"חתן מהר\"ם פדובה. גיסו של ר זלמן רונקיל. חתנו - ר אפרים נפתלי(3112)."},{"i":23692,"n":"יעקב הלוי החסיד ממרויש","k":"בעל שו\"ת מן השמים","b":"מחכמי מרויש וקורביל-ד'תתקסג, חיבר \"שאלות ותשובות מן השמים\", אולי הוא המקובל המכונה ר יעקב מקורביל שנפטר ד'תתקצג."},{"i":23693,"n":"יעקב הלוי מאזמיר","dt":"תקמד - כא סיון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":23694,"n":"יעקב הלוי מאיפשולה","b":"רב באיפסולה-שנות ה-ת'."},{"i":23695,"n":"יעקב הלוי מאלגיר","bt":"שי","dt":"שץ - בערך","b":"רב באלגיר. ונזכר בשו\"ת הרשב\"ץ השני."},{"i":23696,"n":"יעקב הלוי מאלקורן","k":"בעל אלקורן","b":"חיבר ספר אלקורן מאיטלקית (באוצר - ר חיים מיכל)."},{"i":23697,"n":"יעקב הלוי מאניקשט","f":"אברהם מעמדין-מרכבת ה","b":"רב באניקשט על מקום ר אברהם ליכטנשטין."},{"i":23698,"n":"יעקב הלוי מבוסניה וירושלים","f":"חיים רפאל","k":"יעקב הלוי די בוסנא","dt":"תקף - כח תשרי","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23699,"n":"יעקב הלוי מברושא","b":"רב בברושא. בנו - ר משה מקושטא."},{"i":23700,"n":"יעקב הלוי מבריסק","f":"לוי","k":"בעל חדושי מהר\"י","b":"רב בבריסק."},{"i":23701,"n":"יעקב הלוי מגיילנהויזן","f":"יקותיאל זלמן מאיטליה","b":"אחיינו-בן אחיו של המהרי\"ל. מחכמי גיילנהויזן, מגנצא לצד דודו המהרי\"ל, רב באויגשפורג-קעב וראש ישיבה שם, והיה מוכר ע\"י השלטונות (הוכמייסטר) ור יעקב וייל-מהר\"י וייל על מקומו אחריו. חיבר שיר בשם \"הלכתא כמאן\" ונדפס בקראקא שן יחד עם שיר מאת - ר מרדכי שמואל שחי בגרמניה או פולין בשנת -ש' בערך."},{"i":23702,"n":"יעקב הלוי מוולברום","dt":"תקעט","b":"אב\"ד וולברום, קראקא."},{"i":23703,"n":"יעקב הלוי מונציה","f":"משה","b":"תשובה ממנו ב\"דבר שמואל\". תלמיד ר עזריה פיגו - וחיבר שיר לכבוד רבו בהקדמת \"בינה לעתים\"."},{"i":23704,"n":"יעקב הלוי מחסלוביץ וירושלים","f":"יצחק","dt":"תרכט - ו אד\"א","dp":"ירושלים","b":"מג\"מ בחסלביץ, עלה לירושלים."},{"i":23705,"n":"יעקב הלוי מטאלסן","f":"אפרים מטאלסן","b":"למד עם ר מאיר מיאנישוק-אחי הגר\"א. חתן ר ישראל מזיימל. רב בטלסן(=טאלסן)-תר כ-60 שנה. בניו - ר יקותיאל מבויסק, ר מרדכי אפראימזון ממיטאוי."},{"i":23706,"n":"יעקב הלוי מטיטואן","k":"בעל בית יעקב - בכת\"י","b":"מקובל מחכמי טיטואן, בזמן ר יעקב דנון, ר שאול סירירו ור חנניה ארובאץ. חתם-תח על מכתב לרבני פאס. חתם על פס\"ד-תעו עם ר חסדאי אלמושנינו (וזה לא מסתדר עם השנים ואולי הוא חכם אחר באותו השם?). חיבר קינות ופיוטים ובהם פזמון לפטירת משה רבנו \"היום נלקח\". נזכר \"באשר לשמה\"."},{"i":23707,"n":"יעקב הלוי מטריסק","b":"דומ\"צ בטריסק. בנו - ר שמואל ונכדו ר אברהם רוז מבוסטון."},{"i":23708,"n":"יעקב הלוי מירושלים","dt":"תרכה - כט תשרי","dp":"ירושלים","b":"רב בירושלים."},{"i":23709,"n":"יעקב הלוי מירושלים","b":"מחכמי ירושלים, נזכר ב\"חרבות ירושלים\" שסבלו בפרעות אבן פארוך. אחיו - ר יואל, ר שמואל הרופא."},{"i":23710,"n":"יעקב הלוי מסופיה","f":"אברהם","b":"רב ראשי בסופיה-סוף שנות ה-ש'."},{"i":23711,"n":"יעקב הלוי מסופיה וירושלים","dt":"תרו - ו אדר","dp":"ירושלים","b":"רב בסופיה, עלה לירושלים. (נזכר רב בשם זה בשנת תרטו - ואולי הוא רב אחר)."},{"i":23712,"n":"יעקב הלוי מסמניץ","f":"דוד סגל","dt":"תקצב - כח אלול","b":"רב בסמניץ-תקנ\"ב"},{"i":23713,"n":"יעקב הלוי מפאס","f":"יוסף","b":"מחכמי פאס-תקמה."},{"i":23714,"n":"יעקב הלוי מפוניבז","dt":"תר - ח חשון","b":"רב בפוניבז."},{"i":23715,"n":"יעקב הלוי מפפנהים","f":"יצחק הלוי","b":"רב בבערזי,בארק,פפנהיים"},{"i":23716,"n":"יעקב הלוי מקושטא","f":"שמואל","b":"מחכמי קושטא בשנות ה-תק'. נפטר צעיר."},{"i":23717,"n":"יעקב הלוי מקושטא","b":"דיין בקושטא, ישב בדין-תקעה עם ר חיים אברהם בן שלום ור יהושע עלי."},{"i":23718,"n":"יעקב הלוי משלוניקי","dt":"תקפז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":23719,"n":"יעקב הלוי משלוניקי פטרץ וונציה","f":"ישראל","k":"בעל שו\"ת מהר\"י הלוי","bt":"שכ","bp":"פטרץ","dt":"שצו","dp":"זאנטי","b":"נכד ר יעקב שמריה פאפו מפטרץ. תלמיד ר אהרן ן חסון בשלוניקי, רב בפטרץ, דיין בשלוניקי-שס, עבר לונציה, האי זאנטי. מקורב למלכות, עשיר, למדן,"},{"i":23720,"n":"יעקב הלוי קופלמן מלובלין","f":"יהודה","dt":"שא - כג סיון","dp":"לובלין","b":"רב בלובלין. נזכר בד\"מ. (יש האומרים שהוא ר יעקב פולק מפרג - אולם כנראה שהוא אחר - וכך כתב ר יוסף אב\"ד סורוצק בהערותיו בכ\"י ל\"קריה נאמנה\")."},{"i":23721,"n":"יעקב המדקדק והפייטן","f":"אלעזר","k":"בעל ספר השלם","b":"פייטן ומדקדק קדום - אולי בשנת ד'תשצג. נזכר ברד\"ק. חיבר פירוש לתנ\"ך, היה במחלוקת עם ר יונה ן ג'אנח. חיבר ספר שירים."},{"i":23722,"n":"יעקב הנגיד מירושלים","f":"משה","b":"רב בירושלים-רמא, ונזכר אצל ר משלם בן מנחם מוולטארה."},{"i":23723,"n":"יעקב הנזיר מאיטליה","f":"שאול מלוניל","b":"מגדולי המקובלים"},{"i":23724,"n":"יעקב הנזיר מלוניל","f":"אשר בן משלם הפרוש","b":"מקובל מחכמי לוניל, יש האומרים שהיה רבו של הראב\"ד - ואחרים אומרים שחי אחריו."},{"i":23725,"n":"יעקב הנסתר מיאנובא","dt":"תק","b":"תלמיד הבעשט."},{"i":23726,"n":"יעקב הסופר מפאס","b":"מחכמי פאס. נזכר ב\"עפר יעקב\" (בסוף \"דעת זקנים\")."},{"i":23727,"n":"יעקב הקטן משאנץ","f":"שמשון","dp":"חיפה","b":"עלה עם אביו לעכו בשנת ד'תתקע (1210) והיה מחכמי עכו. חתם עם רבני העיר על שאלת ר יוסף בן גרשון לר אברהם בן הרמבם. לדעת אורבך המדובר בר יעקב האחרון מבעלי התוספות."},{"i":23728,"n":"יעקב הקראי","f":"ראובן","k":"בעל העושר","b":"מחכמי הקראים-ד'תשע. חיבר \"העושר\" ובו פירוש לתנ\"ך - מלוקט מספרי חכמי הקראים."},{"i":23729,"n":"יעקב הרץ מאנטאקאליע","f":"יוסף","dt":"תרה - ה שבט","b":"מו\"ץ באנטאקאליע על מקום ר ישראל ליפשיץ, ור ישראל אידל זרחי על מקומו אחריו."},{"i":23730,"n":"יעקב וולף מליסא ולובלין","k":"בעל בית יעקב","b":"אב\"ד ליסא, לובלין-תקפ, ועזב לאחר שלא השתווה על שכרו ור יהושע השל באבד מטרנופול על מקומו אחריו. חיבר \"בית יעקב\" - עברית וגרמנית - ברלין תרו. עם הסכמת ר עקיבא איגר, ור משה מליסא."},{"i":23731,"n":"יעקב זליג הכהן ממאקווא","f":"משה הכהן","dt":"תקצא - ז אלול","b":"רבה הראשון של מאקובה(מאקווא), ור יהודה ליב סגל על מקומו אחריו."},{"i":23732,"n":"יעקב זליגמן מקרימונה","f":"גרשון","b":"תשובות ממנו ב\"נחלת יעקב\" לר יעקב אלפרון."},{"i":23733,"n":"יעקב חי הלוי מפירנצה","b":"רב בפירנצה-תקל, פגש את החיד\"א."},{"i":23734,"n":"יעקב חי משלוניקי","b":"מחכמי שלוניקי, וכונה \"ראש המגיהים\", הגיה ספרים רבים ובהם: \"פאת הנגב\" ו\"דרך הנגב\" לר נסים גבאי מקושטא וחיבר הקדמה-תקנז, \"בית המלך\", \"סוכת דוד\"-תקסד. הו\"ל שו\"ת ר משה מינץ-תקסב."},{"i":23735,"n":"יעקב חיים הכהן מירוסלב וברודי","f":"יהושע","k":"בעל חקי חיים","b":"מחכמי ירוסלב, ברודי. חיבר ספר דקדוק \"חקי חיים\" - ברלין תקנו."},{"i":23736,"n":"יעקב חיים מלובלין","f":"אברהם ר חיימש","dt":"תקכט - ח אלול","dp":"לובלין","b":"חתן ר אברהם יצחק חז\"ק, ובזיוו\"ש חתן גיסו ר יעקב יצחק הוכגלרנטר. רב בירוסלוב, לובלין. הכריז על חרם כנגד המדברים כנגד ר יהונתן איבשיץ-תקיא. בנו ר יצחק מטרנוי, חתנו ר יוסף הוכגלרנטר. לאחר פטירתו נישאה אלמנתו לר שאול מאמשטרדם בעל \"בנין אריאל\"."},{"i":23737,"n":"יעקב חיים מפדובה","f":"איסר","b":"מחכמי פדובה, מבני החבורה של הרמח\"ל."},{"i":23738,"n":"יעקב חסיד מאוסטרהא","f":"נטע מאוסטרהא","k":"רבי יוקבת","dt":"תסט - ב תמוז","dp":"אוסטרהא","b":"רב באוסטרהא. חותנו של ר יהודה כץ אביו של ר שלמה זלמן כץ מאוסטרהא."},{"i":23739,"n":"יעקב חריף מקריניק","f":"לפידות","b":"מגיד בקריניק-ליד הורדנא. מתלמידיו - ר צבי הירש-אביו של ר שמואל סלנט."},{"i":23740,"n":"יעקב טריסקר ממיטאוי","b":"מו\"ץ במיטאוי על מקום ר ישראל פרידמן-תרה, עלה לארץ."},{"i":23741,"n":"יעקב טרפון משלוניקי","b":"הקדמה ושיר ממנו ב\"אגדת שמואל\" לחכם אריפול."},{"i":23742,"n":"יעקב יאקב מברלין","f":"אריה ליב מקרוטושין","b":"ממנהיגי קהילת ברלין. חתם על מינוי ר משה בן אהרן מלבוב ולייפניק לרבה של ברלין-תפט."},{"i":23743,"n":"יעקב יאקב מהמבורג","b":"דיין בהמבורג-תקנח, חתם עם ר יוסף בן נפתלי מבינגשבורג, על זכרון עדות צוואת צוואת ר ליב כתריאל מינדן מהמבורג עבור אחייניו ר יצחק איזיק טרויב ור שלמה זלמן טריוב מקידאן."},{"i":23744,"n":"יעקב יהודה יודל מאוסטרהא","f":"צבי הירש מאוסטרהא","k":"ר יודל חסיד","dt":"תקכו - יג כסלו","dp":"אוסטרהא","b":"בן הדיין מאוסטרהא ונכד ר ישראל חריף. חתן ר מנחם מנדל בן משלם מאוסטרהא. רב וצדיק באוסטרהא ונקרא חסיד. יסד חברת משניות בביהכ\"נ של ר שמואל ר יעקב'ס-שהיה חותנו זקנו (ונקראה אח\"כ גם ביהכ\"נ רב ייבי) נספד ע\"י ר אברהם משלם זלמן ב\"דברי רב משלם\". מבניו: ר צבי הירש מאוסטרהא, ר משה מאוסטרהא - נפטר בחיי אביו."},{"i":23745,"n":"יעקב יהודה מאוטואצק","b":"מתורתו ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":23746,"n":"יעקב יהושע אליה מקניגסברג","f":"שלמה דב בעריש אברהם","dt":"תרו - ג אלול","dp":"ראויטש","b":"נכד ר יעקב יהושע פאלק בעל \"פני יהושע\" ונקרא על שמו. רב בקניגסברג, ראויטש-תקעה. הסכים על הר\"ן - דירנפורט-תקפג, תשובה ממנו ב\"אלה דברי הברית\"-תקעט בענין האיסור לנגן בכלי שיר בשבת גם בידי נוכרי."},{"i":23747,"n":"יעקב יהושע מטיטשין","b":"רב בטיטשין-תרמח."},{"i":23748,"n":"יעקב יהושע מקאוולי","dt":"תקסה - כה שבט","b":"רב בקאוולי"},{"i":23749,"n":"יעקב יום טוב מרסצ'וק","b":"רב ברסצ'וק-תר\"ז"},{"i":23750,"n":"יעקב יונה מזולקוא","f":"אליקים","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה, אולי הוא שנזכר אצל מהר\"ם מלובלין, ויש לו הסכמה בסמ\"ע."},{"i":23751,"n":"יעקב יוסף בן יהודה ליב מאוסטרה","f":"יהודה ליב מאוסטרהא","k":"בעל רב ייב\"י,ייב\"י","r":"בעל התולדות","bt":"תצח","dt":"תקנא - כ תשרי","b":"תלמיד המגיד ממזריטש, ופגש את הבעש\"ט בילדותו. רב באוסטרהא על מקום אביו. ממפיצי החסידות. חיבר גם \"מורא מקדש\", \"עין משפט\", ועוד. תולדותיו ב\"שבחי רב ייבי\". בנו ר פנחס. חתנו ר אברהם בן ר צבי מפאוויליטש. (בהיותו רב באוסטרהא קנס את הגביר ר אבלי ולקח ממנו משכון ראש משפחת הגבירים זוסמן - על כך שנכרי משרת בביתו חילל שבת - ועשה זאת בפרהסיה לעיני כל העיר והגביר קיבל את הדבר על עצמו).","bk":[["רב ייבי [עה\"ת] (אוסטראה)",""],["הנהגת אדם",""],["מורא מקדש",""],["רב ייבי",""]]},{"i":23752,"n":"יעקב יוסף הכהן מבריסק","f":"ישראל יוסף","b":"חתן התוי\"ט. מנהיג, מרביץ תורה בבריסק-תל. בנו - ר יהודה. (אצל בובר-זולקוא מופיע כר\"מ בטריסק וחתם בפנקס זולקוא-שפו בשם יעקב בן ישראל יוסף הכהן אשכנזי)."},{"i":23753,"n":"יעקב יוסף הכהן מקלאבוצק","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":23754,"n":"יעקב יוסף הלוי מבלגרד","b":"רב בקהלת שלום בבלגרד-שנות ה-ש'."},{"i":23755,"n":"יעקב יוסף הלוי מירושלים","f":"ישעיה","dt":"תקצח - כה סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":23756,"n":"יעקב יוסף הרופא מבגדד","k":"בעל שמן הטוב","bt":"תרד","b":"רב הכולל בבגדד. חיבר גם \"שיר חדש\", \"נאוה תהילה\"."},{"i":23757,"n":"יעקב יוסף מאוסטרהא","f":"אברהם-חתן ר ייב\"י","b":"נכד ר ייב\"י. מחכמי אוסטרהא."},{"i":23758,"n":"יעקב יוסף מאוסטרהא","f":"פנחס מאוסטרהא","k":"אדמור מאוסטרהא,הנכד","dp":"יאמפולא","b":"נכד ר יעקב יוסף - ייב\"י. ר\"מ ואדמור באוסטרהא-תקע, נסע כל שנה ליאמפולי ושם נפטר. (היתה כנגדו מלשינות שפעל נגד הקיסר ניקולאי הראשון יחד עם המגיד מטריסק - ובחקירה באוסטרהא התברר כי שקר הדבר והמלשין נשלח למאסר בזוויהל). מבניו: ר אברהם, אליקים גצל - נקראו בשם המשפחה ספרד - כך אצל אלפסי, חתניו: ר ברוך מקונסטנטין בן יוסף מאוסטילע, ר חיים בן משה מקרשטשוב, ר דב בר מלחוביץ ונכדתו מרת אססתר הנגידה הצדקנית אשת ר זלמן הארינשטין."},{"i":23759,"n":"יעקב יוסף מאוסטרהא","f":"אליקים געץ","b":"רב באוסטרהא"},{"i":23760,"n":"יעקב יוסף מאורזיסטשוב","f":"אברהם מאורזיסטשוב","k":"אדמור מאורזיסטשוב","dt":"תשא - ג-יג אלול","dp":"קיוב","b":"חתן ר דן השני מראדויל (זלוטשוב), ובזיוו\"ש חתן ר ישראל שיינברג מקישינוב. אדמור באורזיסטשוב על מקום אחיו ר ישעיה בתקופת הקומוניסטים."},{"i":23761,"n":"יעקב יוסף מברדיטשוב","b":"גביר, נדבן בברדיטשוב."},{"i":23762,"n":"יעקב יוסף מירושלים","f":"משלם אברהם","b":"מחכמי ירושלים, מוזכר בספרו של ר משולם מוולטרא כאחד הדיינים בשנת רמא."},{"i":23763,"n":"יעקב יוסף ממילניצה","b":"שו\"ב במילניצה."},{"i":23764,"n":"יעקב יוסף מניקלשבורג","b":"רב בניקלשבורג-שנות ה-ת'. חתנו - ר יואל הלפרין הגדול מאוסטרהא (בזיוו\"ש, שם בתו - עלקה)."},{"i":23765,"n":"יעקב יוסף מסוקולוב","b":"רב בסוקולוב."},{"i":23766,"n":"יעקב יוסף מקאזין","f":"אליקים גץ מקאזין","k":"אדמור מקאזין","b":"חתן ר אברהם שמואל מברזנא (סטפין). אדמור בקאזין, סטעפניץ, בוהיסלוב."},{"i":23767,"n":"יעקב יוסף מקוסוב","b":"רב בקוסוב-תרסג."},{"i":23768,"n":"יעקב יוסף מראפשוויר","f":"מאיר סופר מראפשוויר","k":"בעל אבן ישראל","b":"מחכמי ראפשוויר-אלזס. חיבר \"אבן ישראל\" - מיץ תקכו."},{"i":23769,"n":"יעקב יוקיל מאוסטרהא","f":"אליעזר הלוי","dt":"תקעה - י אד\"ב","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":23770,"n":"יעקב יוקיל מצורטקוב","b":"רב בצורטקוב-תרכו."},{"i":23771,"n":"יעקב יושע בן צבי הירש","bt":"1680","dt":"ה'תקיו 1756","bk":[["חידושי פני יהושע",""],["פני יהושע",""]]},{"i":23772,"n":"יעקב יחזקאל הלוי מאושפיצין","k":"בעל תספורת לוליינית","bt":"תקעד","bp":"הוצנפלוץ","dt":"תרכה - כא חשון","b":"תלמיד ר ברוך פרנקל בלייפניק, ר וולף מטפלטשאן בעל \"שערי תורה\", ר יעקב אורנשטין בלבוב. אב\"ד אושפיצין-תרו, בייטהען (מדינת שלזיה)-תריד. חיבר \"תספורת לוליינית\" ברלין תקצט - (ספר שעורר מחלוקת בגלל שהתיר גילוח בחול המועד). פרסם מאמרים ב\"המגיד\", \"המליץ\", ועוד."},{"i":23773,"n":"יעקב יחזקאל ממאטעמאלקא","f":"דוד מאיר","k":"בעל מכתבים נבחרים","bp":"באלקאני","b":"מדפיס במאטעמאלקא-תשב (בזמן השואה)."},{"i":23774,"n":"יעקב יחיאל מיכל מאודסה","b":"דיין באודסה אצל ר יחיאל צבי הלפרין. הסכים-תרכד על \"קרית ספר\" לר מאיר מלר."},{"i":23775,"n":"יעקב יעקבקא יהודה","b":"רב מרומאנוב,קליינוורדיין"},{"i":23776,"n":"יעקב יעקיל מחוליוב","b":"רב בחוליוב-תריח."},{"i":23777,"n":"יעקב יעקל מוילנא","f":"אריה ליב מוילנא","k":"ר יעקעלע ר ליבעלעס","dt":"תקלג - יד סיון","dp":"פלנגי-קורלנד","b":"מצאצאי ר משה קרמר, ר אליהו פעסעלעס, ובעל \"באר הגולה\". חתן ר דב בר ממזריטש-בנו של ר נפתלי הרץ מדובנא (לא המגיד), ובזיוו\"ש חתן הגביר ר צדוק מארשלקוביץ מדובנא, ובזיוו\"ש חתן ר מאיר מטיקטין. גביר מחכמי וילנא ופרנס בוילנא. גבאי א\"י. בניו: ר אליהו, המכונה \"ר אלינקע יעקילס\"-חתנו של ר אריה ליב ברוידא מקאלווריה, ר מרדכי צבי-חתן דודו ר יצחק אליהו לנדא, ר חיים אליאש, ר דב בר אלי'ס מקאוולי. חתנו - ר יעקב בן ר זיסל רפפורט ממינסק."},{"i":23778,"n":"יעקב יעקל מוילנא","f":"אריה ליב מוילנא","dt":"תקצח - ט אב","dp":"פלנגי-קורלנד","b":"נכד ר דב בער מוילנא. ובנו של הגביר שהיה אחד האחים הגבירים (ר ליב ור צבי הירש) בוילנא. (יש בלבול בינו לבין ר יעקב בן אריה ליב בן ר אליהו פעסעלעס)."},{"i":23779,"n":"יעקב יעקל מלבוב","f":"מהר\"מ מלבוב","b":"דיין בלבוב, חתם-תסז בפנקס הקהלה, ועוד."},{"i":23780,"n":"יעקב יעקלי גר צדק מלובלין","dt":"תקעח - ח אלול","dp":"לובלין"},{"i":23781,"n":"יעקב יצחק","b":"רב-שנת תר\"מ"},{"i":23782,"n":"יעקב יצחק היהודי הקדוש מפשיסחא","f":"ראה: רבינוביץ, יעקב"},{"i":23783,"n":"יעקב יצחק הכהן ממיינץ(=מגנצא)","b":"עק\"ה,רב במאינץ(מגנצא)-ק\"ל"},{"i":23784,"n":"יעקב יצחק הלוי משטרים-ליטא","k":"בעל בית לוי","dt":"תמג","b":"פוסק,מגדולי חכמי דורו, רב בשטרים, ליסא-תטו ור אריה ליב בכרך על מקומו אחריו."},{"i":23785,"n":"יעקב יצחק ממאזיר","b":"רב במאזיר-תר\"ס"},{"i":23786,"n":"יעקב יצחק מסנדומיר","k":"בעל פירוש המסורה","b":"תלמיד ר עקיבא פרנקפורטר בפפד\"מ. רב בסנדומיר-פולין-שמ."},{"i":23787,"n":"יעקב יצחק מקאלושין","f":"מרדכי דוד דומברובר","b":"רב בקאלושין-תר\"ל"},{"i":23788,"n":"יעקב יקובקי מירושלים ובריסק","f":"מרדכי","b":"חתם-תד בסטנוב על קבלת עדות בענין עגונה."},{"i":23789,"n":"יעקב יקותיאל הכהן מצפת","f":"דוד","bp":"ירושלים","b":"רב בצידון-תנב, צפת-תס בערך על מקום ר אברהם בן משה גלנטי. בנו - ר דוד - רב בצפת."},{"i":23790,"n":"יעקב יקותיאל משלוניקי","b":"מדפיס בדפוס המנוח בצלאל אשכנזי בשלוניקי-תקכו."},{"i":23791,"n":"יעקב ירוסלבסקי טוגנהולד","f":"אהרן מירולסב","bt":"תפה","bp":"ירוסלב","dt":"תקנט","dp":"ברסלוי","b":"מראשי הקהלה בברסלוי, שלח את בנו לקראקא כדי להרחיקו מהשפעת תורת רמבמ\"ן (מנדלסון) שפשטה בברסלוי. (לפי המסורה קיבל את שם משפחתו טוגנהולד לאחר שהציל נוצרי מטביעה)."},{"i":23792,"n":"יעקב ישראל","b":"מגדולי בעלי התוספות בצרפת-ד'תת\"ע"},{"i":23793,"n":"יעקב ישראל","k":"מפפד\"מ","b":"מראשי קהילת פפד\"מ-תקך, ונמנה על קבוצת הרבנים שמילאו את מקומו של ר יעקב יהושע בעל ה\"פני יהושע\"."},{"i":23794,"n":"יעקב ישראל מאוסטרהא","f":"עוזר","dt":"תקלט - ד אב","dp":"אוסטרהא","b":"פרנס באוסטרהא-תצח יחד עם ר שמואל ר יעקב'ס, ועם ר מרדכי הלפרין. חתם כמה פעמים בפנקס הח\"ק."},{"i":23795,"n":"יעקב ישראל מגריידינג","b":"שו\"ב בגריידינג."},{"i":23796,"n":"יעקב ישראל מלובלין","f":"בנימין מבלזיץ","k":"בעל ילקוט חדש","b":"רב בבלזיץ, סלוצק-שנת ת, לובלין. חיבר גם \"תפארת ישראל\". ניצל מגזירות תח - וחיבר דרשה והספדים על הנספים."},{"i":23797,"n":"יעקב ישראל מקושטא","b":"רב בקושטא-ש'."},{"i":23798,"n":"יעקב ישראל משלוניקי","f":"ישראל","b":"חתן ר יהושע דאטו. מחכמי שלוניקי-רץ."},{"i":23799,"n":"יעקב כץ מטיטשין","f":"ראה כהנא שפירא, יעקב"},{"i":23800,"n":"יעקב כץ מיאנוב","f":"משה","k":"בעל מנחות יעקב","b":"חיבר \"מנחות יעקב\" פיורדא."},{"i":23801,"n":"יעקב ליב מאוזירן","b":"רב באוזירן-תרלב."},{"i":23802,"n":"יעקב ליברמן","f":"צבי הירש מלוקטש-חמדת","b":"בנו של ר צבי הירש מלוקאטש בעל \"חמדת ימים\"."},{"i":23803,"n":"יעקב מאוסטרהא","f":"שמואל","k":"ר יעקב ר שמואל'ס","b":"אביו של ר שמואל המכונה \"ר שמואל ר יעקבס\". פרנס ומנהיג באוסטרהא. מצאצאיו ר יוזפא אוסטרר, ר מרדכי ר יעקב ר שמואלס מאוסטרהא."},{"i":23804,"n":"יעקב מאוסטרהא","f":"יוסף יוזפא מאוסטרהא","dt":"תקטז-יז - א אב","dp":"אוסטרהא","b":"בנו של פרנס מדינת ואהלין. חתן ר ישראל הלפרין מזסלב ואוסטרהא. גביר עשיר ופרנס באוסטרהא. נפטר בחיי אביו. מבניו: ר ישראל רב החייטים באוסטרהא, ר אליעזר ליפמן פרנס באוסטרהא."},{"i":23805,"n":"יעקב מאוסטרהא","f":"חנוך הניך","dt":"תקנו - ב סיון","dp":"אוסטרהא","b":"מצדיקי אוסטרהא. אולי הוא אחיו של ר שמשון מולטשיסק בן חנוך מאוסטרהא שהסכים על \"מנחה חדשה\" אלקסניץ תקלד. אולי בנו הוא ר ישראל שלום בן שמשון מאוסטרהא."},{"i":23806,"n":"יעקב מאוסטרהא","f":"אליעזר","dt":"תקיט - טז אלול","dp":"אוסטרהא","b":"מצאצאי ר יקותיאל מלודמיר. פרנס באוסטרהא."},{"i":23807,"n":"יעקב מאוסטרהא","f":"אברהם אבא מפולנאה","dt":"תקך - כו תשרי","dp":"אוסטרהא","b":"פרנס באוסטרהא-תצח יחד עם ר מרדכי הלרפין הרופא."},{"i":23808,"n":"יעקב מאוסטרהא","f":"צבי","dt":"תקמו - ב חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":23809,"n":"יעקב מאורליאן","k":"יעקב הקדוש מאורליינש","dt":"ד'תתקג","dp":"אנגליה","b":"עק\"ה,מגדולי בעלי התוספות,מרביץ תורה באורליינש"},{"i":23810,"n":"יעקב מאורשי","b":"רב באורשי-תק\"ס,עבר לקרילאוו"},{"i":23811,"n":"יעקב מאיווניץ","f":"ברוך","b":"מגיה מחכמי איווניץ-ליד וולוזין. שאל ספר \"מסורת סייג לתורה\" מר חיים מוולוזין לצורך העתקתו."},{"i":23812,"n":"יעקב מאיסקיס","dt":"תרצ - כה סיון","b":"דיין באיסקיס"},{"i":23813,"n":"יעקב מאיר הלוי מסטריקוב","f":"אפרים","b":"חתן ר ישכר ויינגוט מטשנסטחוב. תלמיד ר אפרים פישל מסטריקוב. רב בסטירקוב, וירשוב, פייזר."},{"i":23814,"n":"יעקב מאיר ישורון מוארשא","k":"בעל אמרי יעקב","dt":"תרכו - יד שבט","b":"מו\"צ בוארשא","bk":[["אמרי יעקב",""]]},{"i":23815,"n":"יעקב מאיר מיאלובקה וסלוצק","k":"בעל בית יעקב","bt":"תקנד - בערך","dt":"תקפו","b":"תלמיד ר חיים מוולוזין. אב\"ד סלוצק-תקפה. גיסו של ר שלמה אהרן מקאדני בעל \"כרם שלמה\". מתלמידיו: ר גרשון חן טוב בעל \"מנחה חדשה\", בעל \"פני אריה\", ר מרדכי זקהיים מפינסק, ועוד. נפטר צעיר. אחיינו - ר אפרים פישל ניימן מניו יורק הו\"ל את ספרו \"בית יעקב\"."},{"i":23816,"n":"יעקב מאיר מירקדו מירושלים","f":"כלב מאיר","bt":"תרטז","bp":"ירושלים","dt":"תרצט","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תרמב בשליחות בבוכרה והיה השליח הראשון שם, נבחר ע\"י אחת הסיעות לראשל\"צ בירושלים-תרסה אך סיעה אחרת בחרה בר משה פאניז'יל, ובשנת תרסז רב ראשי בשלוניקי, ראשון לציון בירושלים-תרפא לצידו של הרב קוק. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו, \"שערי ציון\" - ירושלים תרפא. חתנו - ר רפאל עזריאל-בנו של בעל כפי אהרן."},{"i":23817,"n":"יעקב מאיר מניעשאווא","f":"מנחם","b":"אב\"ד ניעשאווא-פלך וארשא, תשובה ממנו-תרלח לר יהושע סיגל משערפטץ(=שפעס) בעל \"אזני יהושע\"."},{"i":23818,"n":"יעקב מאלג'יר","f":"ישי","dt":"ד'תשכג","b":"מגדולי ראשוני חכמי אלג'יר,מרביץ תורה בתאג'ורה-טריפולי"},{"i":23819,"n":"יעקב מאליק","f":"עזריאל מווילנה","b":"רב באליק-תפ\"ב,עבר לברודי והתעשר"},{"i":23820,"n":"יעקב מאלסק","dt":"תקסא - יח חשון","b":"רב באלעסק"},{"i":23821,"n":"יעקב מאניפו-חתן ר צבי בן הבעשט","f":"מנחם מן מנלי מקרלין","b":"בן דודו של ר אהרן הגדול מקרלין. חתן ר צבי בן הבעשט. מקורב לקרובו ר אשר מסטולין. עלה לארץ והתגורר בטבריה."},{"i":23822,"n":"יעקב מאניפולי","dp":"מזריטש","b":"מתלמידי הבעש\"ט והמגיד ממזריטש. רב באניפולי-תקכ. כשהגיע המגיד לראשונה אל הבעשט ביקש את ר יעקב שיזכירו לפני הבעשט. הכין לעצמו קבר באניפולי - אולם נפטר ונקבר במזריטש - ואילו בקברו שהכין נטמן רבו המגיד ממזריטש."},{"i":23823,"n":"יעקב מאסטרוב","b":"רב באסטרוב,קויל"},{"i":23824,"n":"יעקב מאסכולא","f":"אברהם","b":"רופא ופייטן מחכמי אסכולא-שנות ה-ק'. חיבר רשויות ליו\"כ ולסוכות, אולי הוא שנזכר אצל ר משה ריאטי ב\"מקדש מעט\"."},{"i":23825,"n":"יעקב מאפטא","b":"רב באפטא-תק\"י"},{"i":23826,"n":"יעקב מאשכנז","f":"מנחם","b":"מחכמי אשכנז או צרפת, נזכר בפירוש רש\"י."},{"i":23827,"n":"יעקב מבודון","f":"צבי","b":"רב בבודון-שנות ה-ת'. מתומכי ש\"ץ."},{"i":23828,"n":"יעקב מבודון","f":"מרדכי","b":"נשיא הח\"ק בבודון בזמן ש\"ץ, המיר דתו בעקבות ש\"ץ, וחזר לדת ישראל."},{"i":23829,"n":"יעקב מבונא -","b":"מגדולי חכמי אשכנז הקדמונים,מרביץ תורה בבונא-ד'תת\"ק. אביו של רבינו גרששום, רבינו קלונימוס, רבינו אפרים ורבינו הלל."},{"i":23830,"n":"יעקב מברדיטשוב","f":"ליבר הגדול מברדיטשוב","bt":"תקך","dt":"תקנו","b":"חתן ר יחיאל ממיקולייב."},{"i":23831,"n":"יעקב מברודניק","b":"רב ברודניק-תקצב."},{"i":23832,"n":"יעקב מבריסק","b":"דיין בבריסק. חותנו הראשון של הגדול ממינסק."},{"i":23833,"n":"יעקב מבריסק","f":"יואל","k":"בעל שארית יעקב","b":"רב בבריסק. חיבר \"שארית יעקב\" - אלטונא תפז."},{"i":23834,"n":"יעקב מבריסק ולובלין (שור?)","f":"אפרים נפתלי הירש","k":"ר' יעקב מלובלין","dt":"תד - טז כסלו","dp":"לובלין","b":"חתן ר מאיר וייל-קצנלנבוגן((12968). תלמיד המהרש\"ל. מגדולי דורו, רב בבריסק-שצא (ור אברהם אפשטין על מקומו אחריו), לובלין. מתלמידיו ר חיים חייקא בן שמואל הורביץ מגרודנה. הסכים על \"ספר הזכרון\" לר יצחק שפירא - תג, ועוד. מתלמידיו - ר אהרן שמואל קאידנובר בעל \"תפארת שמואל\", ר חיים חייקא הלוי מהורבשוב והורדנא. התכתב עם הב\"ח, תשובה ממנו ב\"גאון צבי\". הגיה \"עין יעקב\" -תמד עם הערות ממנו. הסכים על \"שער השמים\" לשל\"ה. (בהיותו בבריסק הגיע בעל תוי\"ט לחתונת בנו - ור יעקב כבדו לדרוש בשבת תשובה). בנו ר יהושע השל מלובלין ובריסק (הרבי ר השל) ר\"מ לצד אביו."},{"i":23835,"n":"יעקב מברעזין","f":"אפרים פישל מסטריקוב","b":"סירב לאדמורות."},{"i":23836,"n":"יעקב מגינצבורג","b":"מגדולי חכמי אשכנז-שנת ס'"},{"i":23837,"n":"יעקב מגרובין","f":"אליעזר","b":"ש\"ץ ושו\"ב בגרובין, מכתב המלצה ממנו לשוחט-תרסג."},{"i":23838,"n":"יעקב מגרידץ וגלוגא","f":"צבי הירש מפינטשוב","b":"אב\"ד בגרידץ, ראב\"ד בגלוגא-תקיג אצל ר אשר לעמיל. בתגובה לבקשת ר יחזקאל לנדא בעל \"נודע ביהודה\" כתב לר אריה ליב מאמשטרדם-גיסו של היעב\"ץ ובו מבקשו לפנות ליעב\"ץ ולשכנעו לסיים את המחלוקת עם ר יהונתן איבשיץ. הסכים על \"טוב טעם\" דירנפורט תקג, \"זבח שמואל\" לר שמואל בן משה שוחט מליסא."},{"i":23839,"n":"יעקב מדוברומיל","f":"מאיר זאב סופר מחירוב","k":"בעל ספורי יעקב","bt":"תרא","bp":"חירוב","dt":"תרעז","b":"נכדו של ר זושא מחירוב שנהרג על קדוש השם. חיבר \"ספורי יעקב\" ספורים ששמע מגדולי הצדיקים בדורו - הוסיאטין תרסד."},{"i":23840,"n":"יעקב מדינוב","f":"פנחס אריה","b":"רב בדינוב-תר\"כ"},{"i":23841,"n":"יעקב מדלטין","f":"פנחס יוסף","b":"רב בדלטין-תר\"מ"},{"i":23842,"n":"יעקב מדרויא","dt":"תקסט - י אב","b":"מו\"צ בווילנה"},{"i":23843,"n":"יעקב מהורדנא ווילנא","f":"מהורי\"ל מהורדנא","k":"הו\"ל צהר התיבה","dt":"תרא - ג סיון","dp":"וילנא?","b":"מדקדק מחכמי וילנא. הו\"ל צהר התיבה לר שלמה זלמן הענע-תקף עם ביאור והערות. אחיו - ר אברהם."},{"i":23844,"n":"יעקב מהרובשוב","b":"רב בהרובאשוב-תק\"ס. בנו - ר ברוך מדוברומיל."},{"i":23845,"n":"יעקב מווידאמע","k":"אדמור מוידאמא","bt":"תקנו","dt":"תרמו - כז שבט","b":"תלמיד ר ישעיה מפשעדבורז, ר ישכר דב מראדושיץ, ור שלמה מרדומסק. אדמור בוידאמא(=ווידאמע)-תרכו."},{"i":23846,"n":"יעקב מויטקוב","dt":"תפד - יא כסלו","b":"רב בויטקוב"},{"i":23847,"n":"יעקב מוילון","b":"רב בוילון, ור משה בצלאל לוריא על מקומו אחריו."},{"i":23848,"n":"יעקב מוילנא","f":"משה מדרויע","dt":"תקפא - כה תמוז","dp":"וילנא","b":"מחכמי וילנא."},{"i":23849,"n":"יעקב מוילנא","f":"שמואל","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה."},{"i":23850,"n":"יעקב מוילנא","f":"דב בער","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":23851,"n":"יעקב מוילנא","f":"קלונימוס קלמן מדרויע","dt":"תקסט - י אב","dp":"וילנא","b":"מחכמי וילנא. נקבר ליד דודו ר ישראל איסר."},{"i":23852,"n":"יעקב מוילנא (גינצבורג)","f":"דב בער מהמבורג","b":"גביר מחכמי וילנא. בנו - ר יצחק זעלקא מוילנא."},{"i":23853,"n":"יעקב מוילנא ואמשטרדם","f":"נפתלי","b":"שם אביו הירש ר יאקב איסרלש. חתן ר אביגדור קרא מגלוגא. מחכמי וילנא, עבר לאמשטרדם והיה מגיה אצל ר שבתי משורר. מחותן עם ר הלל בעל בית הלל והגיה את ספרו-נדפס בשנת תנא. (ראה גם: ר יעקב אלישר בן בנימין מירושלים שיש שהחליפו ביניהם)"},{"i":23854,"n":"יעקב מוינה","dt":"תח - ב תשרי","b":"מקובל,רב בווינה"},{"i":23855,"n":"יעקב מוישגראד","bp":"י\"ד תמוז תצ\"ב","dt":"תצב - יד תמוז","b":"רב בוישגראד."},{"i":23856,"n":"יעקב מוישניץ","dt":"תרמ - טז חשון","b":"רב בוישניץ"},{"i":23857,"n":"יעקב מונגרוב","b":"רב בוונגרוב-ת\"פ"},{"i":23858,"n":"יעקב מורמייזא","f":"יהודה ליוואי הזקן","b":"מגדולי חכמי אשכנז,רב בוורמייזא-ר\"ל"},{"i":23859,"n":"יעקב מורמייזא","f":"חיים מוורמייזא","k":"קיסר'ס רב","dt":"שכג","b":"תלמיד המהרש\"ל. אחיו של ר בצלאל-אבי המהר\"ל. רב בוורמייזא ובמדינות הקיסר, וחתם על פסק דין בפפד\"מ-שכד."},{"i":23860,"n":"יעקב מזאבלין","f":"משה","dt":"תרמז - ז אב","dp":"ירושלים","b":"רבה של מוטלה, עלה לירושלים וכיהן בבית הדין."},{"i":23861,"n":"יעקב מזברז","f":"יהודה אריה","b":"רב בזברד-תקצז."},{"i":23862,"n":"יעקב מזולקוא","f":"אהרן זליג","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":23863,"n":"יעקב מזולקוא","f":"משה","b":"מחכמי זולקוא, חתם-תיט על תקנת הקהלה (ראה גם: יעקב אליהו חריף בן משה מאך - כך לדעת בובר-זולקוא)."},{"i":23864,"n":"יעקב מזולקוא","f":"ר\"ש מקראקא","b":"מחכמי זולקוא, חתם-תמא בירוסלב על תקנה של ועד ארבע ארצות, עם ר יהודה אברהם בן יצחק סגל מלבוב, ר יצחק כהנא מבריסק ועוד. (לפי בובר הוא ר יעקב במהר\"ם מטיקטין - מנהיג בארבע ארצות)."},{"i":23865,"n":"יעקב מזולקוא","f":"דוד נתן מבוצאץ","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה, ובשנת תנא על בחירת ראשי הקהלה, ועוד."},{"i":23866,"n":"יעקב מזולקוא","b":"מחכמי זולקוא, חתם-תסה בפנקס הקהלה, בנו - ר ברך, חתנו - ר אליקים כץ - ונתקבלו כלם לחזקת הקהלה-תמח. ראה גם ר יעקב בן דוד נתן מזולקוא."},{"i":23867,"n":"יעקב מזולקוא","f":"דב בער","b":"מחכמי זולקוא, חתם-תקם על תקנה שלא לתת שכירות למשרתי הקהלה בלי כתב מראשי הקהל."},{"i":23868,"n":"יעקב מזייגורא","b":"כנראה מבעלי התוספות שעלו לירושלים בשנת ד' תתקעא (1211), תלמיד הרמבן מזכיר את קברו בתחתית הכרמל."},{"i":23869,"n":"יעקב מזלוטשוב","f":"יוסף","dt":"תקעא - ו סיון","b":"רב בזלאטשוב,רב באיטינגא והמדינה"},{"i":23870,"n":"יעקב מזלין","b":"רב בזלין. תשובה אליו \"תפארת יוסף\"."},{"i":23871,"n":"יעקב מזמיגראד","dt":"תפז - כז שבט","b":"רב בזמיגראד"},{"i":23872,"n":"יעקב מחוסט","f":"אברהם","bp":"זידיטשוב","dt":"תקפב-ג - א אדר","dp":"בריד","b":"נכד ר\"ש מניישטט. רבה הראשון של חוסט-תקעב."},{"i":23873,"n":"יעקב מחנטשין","b":"רב בחנטשין-ת\"כ (ראה גם ר יעקב מצוזמיר)."},{"i":23874,"n":"יעקב מטומשוב","b":"עק\"ה,מרביץ תורה בטאמשוב,צויזמיר,סלוצק"},{"i":23875,"n":"יעקב מטומשוב וארץ ישראל","f":"שמעון","k":"בעל אהל יעקב","bp":"פולין","b":"רב בטומשוב. ברח מגזרות תח ותט בפולין, הגיע לונציה להדפיס את ספרו \"אהל יעקב\" ונציה תכז. עלה לארץ. חיבר \"תולדות יעקב\" בכת\"י."},{"i":23876,"n":"יעקב מטוריצין","dt":"תקמח - יט סיון","b":"רב בטורצ'ין"},{"i":23877,"n":"יעקב מטיטשין","f":"ברוך מפודהייץ","k":"בעל ברכת יעקב","dt":"תפג - אחרי","b":"רב בטיטשין (ליד רישא). חיבר \"ברכת יעקב\" למברג תקמד, נכדו ר ברוך בן אברהם משה מרישא הדפיס את ספרו \"ברכת יעקב\". ומצאציו ר יעקב מטיטשין חותנו של האוהב ישראל."},{"i":23878,"n":"יעקב מטיקטין ופוזנא","f":"יצחק מפוזנא","dt":"תנט - טו סיון","b":"חתן ר נפתלי כץ בעל \"סמיכת חכמים\". רב בטיקטין-תלז, פוזנא. חתם ביריד ירוסלב-תמז. חתניו: ר יצחק דב מרגליות, ר פישל מלודמיר."},{"i":23879,"n":"יעקב מטישוויץ - א","k":"בעל אור חכמים","b":"מ\"מ בטישוויץ. חיבר פירוש ל\"בחינת עולם\" בשם \"אור חכמים\" - הורדנא תקנה."},{"i":23880,"n":"יעקב מטרייל מספרד וירושלים","bp":"ספרד","dt":"רסט","dp":"ירושלים","b":"ממגורשי ספרד הגיע מהעיר טרייל בקשטיליה לירושלים. חבר בית דינו של המגיד קודם במצרים ואחר בירושלים. חדושים ממנו בקונטרס \"חדושי דינים לרבני ירושלים הקדמונים\". חתם על התקנה לשחרור תלמידי חכמים ברס\"ט. היה רבה של ירושלים. חיבר ספר \"מקוה ישראל\" על מקוואות."},{"i":23881,"n":"יעקב מירושלים","f":"עמרם","dt":"תי - לפני","b":"מחכמי איטליה?, עלה לירושלים, רופא ועמד בראש הקהלה בימי אבן פארוך וסבל רבות. בשנת שפו רצה להתפטר מן הרבנות אך השלטונות סרבו להכיר בכך. יש המזהים אותו עם ר יעקב אבוהב הרופא."},{"i":23882,"n":"יעקב מירושלים","f":"שמואל במצפה","b":"מחכמי ירושלםי בשנת קל (1370), חתם במכתב חרם הנשיא בבבלץ"},{"i":23883,"n":"יעקב מירושלים","f":"יעקב","b":"ראש עדת האשכנזים בירושלים. נזכר ב\"שער אפרים\" שהסכים עמו על מכירת ההקדשות כדי לשלם את חובות הקהלה."},{"i":23884,"n":"יעקב מירושלים","f":"משה שלמה זלמן","dt":"תריז - ב טבת","dp":"ירושלים","b":"חתן האדמור מלובאביץ."},{"i":23885,"n":"יעקב מירושלים","f":"יוסף הרופא","k":"בעל נאוה תהלה","b":"מחכמי ירושלים. חיבר פירוש לתהלים בשם \"נאוה תהלה\"-וינה תרטז."},{"i":23886,"n":"יעקב מירושלים","f":"אהרן דב","bt":"תריב","bp":"ירושלים","dt":"תרפד - ג תשרי","dp":"ירושלים","b":"מחכמי ירושלים. פגש את הקיסר פרנץ יוזף."},{"i":23887,"n":"יעקב מכווית","f":"דוד","b":"רב בכווית, שאלה ממנו לרבני בגדד-תרע."},{"i":23888,"n":"יעקב מלאמז","f":"משה","b":"רב בלאמז-תקמ"},{"i":23889,"n":"יעקב מלבוב","f":"יהודה ליב","dt":"תל - יט אדר","dp":"לבוב","b":"מגיד בלבוב על מקום אחיו - ר משה גולדין. נזכר בספר אחיינו \"שבט מיהודה\"."},{"i":23890,"n":"יעקב מלבוב","b":"עניו,ר\"מ בלבוב-ש\"צ"},{"i":23891,"n":"יעקב מלבוב","b":"דיין בלבוב-תקל\"ו"},{"i":23892,"n":"יעקב מלבוב","b":"דיין ומו\"צ בלבוב. בנו - ר שמחה מבורברקא."},{"i":23893,"n":"יעקב מלבוב","f":"שבתי","b":"תלמיד מהר\"ם מלובלין ונזכר בספרו (בובר מפקפק בזיהוי). רב בלבוב."},{"i":23894,"n":"יעקב מלבוב","f":"משה","b":"מראשי קהלת לבוב, חתם-תקד על כרוז ותקנה."},{"i":23895,"n":"יעקב מלבוב","f":"שמשון וולף","b":"מנהיג בלבוב, חתם-תקי על שטר מתנה ובשנת תקלז על תקנת עונשים."},{"i":23896,"n":"יעקב מלבוב","f":"שלמה זלמן","b":"דיין בלבוב, חתם-תקלו על פסק דין."},{"i":23897,"n":"יעקב מלבוב","f":"דב בער","b":"רב בלבוב, חתם-תקלו על פס\"ד, נזכר בשו\"ת ר חיים רפפורט. בנו - ר שמחה מבוברקא."},{"i":23898,"n":"יעקב מלבוב וזולקוא","b":"מו\"צ בזולקוא, הסכים על \"פרי מגדים\" פפד\"א תקמז."},{"i":23899,"n":"יעקב מלבוב מטרעמבליא","f":"ישכר בער","dt":"תצח - כ שבט","dp":"לבוב","b":"רב בטרעמבוולע, ראב\"ד בלבוב. (אצל בובר-לבוב מופיע שאולי הוא שהיה על מקום אחיו - ר משה גולדין - אך זה לא מסתדר עם תאריכי פטירתם ושם אביהם, ראה גם: ר משה בן יהודה ליב מלבוב)"},{"i":23900,"n":"יעקב מלובלין","f":"נפתלי הרש","dt":"תכז - ו אלול","b":"מגדולי חכמי לובלין, נפטר בטביעה. בנו ר נפתלי הרץ מלובלין. נכדו-בן בתו ר צבי הלברשטט."},{"i":23901,"n":"יעקב מלובלין","b":"מחדושיו על התנ\"ך ב\"מטה אהרן\"."},{"i":23902,"n":"יעקב מלובלין","f":"מרדכי","dt":"שכט - כא תמוז","b":"פרנס מראשי קהילת לובלין"},{"i":23903,"n":"יעקב מלובלין","b":"דיין בלובלין-תס ומראשי הח\"ק."},{"i":23904,"n":"יעקב מלובלין","dt":"תמ - ח טבת","dp":"לובלין","b":"חתן ר שמואל. ממנהיגי קהילת לובלין."},{"i":23905,"n":"יעקב מלובמלא","b":"רב בלובמעלא(=לובמלא)-ת\"מ"},{"i":23906,"n":"יעקב מלודווינאווי","f":"פנחס","k":"בעל גופי הלכות","b":"רב בלודווינאווי-תק\"ס"},{"i":23907,"n":"יעקב מלודמיר","f":"אפרים פישל לודמיר","b":"רב בלודמיר-תעג. בנו - ר שלמה זלמן מביאלא."},{"i":23908,"n":"יעקב מלויצק ולובלין","f":"אריה ליב מסלוצק","k":"בעל כוכבי יעקב","b":"חתן ר יהושע משידלוב. רב בלוצק-תקכ, לענטשני, לובלין. הסכים על \"זרע בירך\", ועוד. חתם בפינקס וילנא-תז. בנו - ר יוסף מביאלא."},{"i":23909,"n":"יעקב מלוצין וירושלים","f":"מנדל","dt":"תרלב - יט טבת","dp":"חברון","b":"תלמיד ישיבת וולוזין, עלה לירושלים, מדקדק. חתם-תרז בחברת \"משמורים\", על כתב שליחות ר אברהם ניסן-תרטו, בשליחות \"ביקור חולים\"-תרכג באירופה, בשליחות ר יעקב ממיר לחלב כדי לחקור את ספרי התורה שם ובהם \"כתר ארם צובא\"."},{"i":23910,"n":"יעקב מלוקניק","f":"אברהם אביש מפפד\"מ","dt":"תקלז - יח אדר","b":"רב בלוקניק"},{"i":23911,"n":"יעקב ממגלניצא","b":"רב במגלניצא-תק\"ע"},{"i":23912,"n":"יעקב ממגנצא","f":"יקר","dt":"ד'תתל","b":"תלמיד רבנו גרשום, רבו של רש\"י המזכירו בפירושיו בשם \"מורי הזקן\"."},{"i":23913,"n":"יעקב ממדבידובקא","b":"רב במדבידובקא(=מידבידובקא)-ליד אומן."},{"i":23914,"n":"יעקב ממהרן","b":"ראש מדינה במהרן-ת\"צ"},{"i":23915,"n":"יעקב ממוטלה וירושלים","b":"רב במטלה,דיין בירושלים-תר\"נ"},{"i":23916,"n":"יעקב ממזבוז","b":"תלמיד הבעשט, שימש כש\"ץ אצלו והיה עמו בעת פטירתו. עלה לארץ."},{"i":23917,"n":"יעקב ממיטאוי","f":"צבי הירש חריף ממיטאו","b":"מחכמי מיטאוי."},{"i":23918,"n":"יעקב ממייסטרי","f":"שמשון","b":"מחכמי איטליה, בשנת רכז רב בעיר מיישטרי ולאחר מיכן בקרימונה, בשנת רלד התארח בביתו בעל \"לקט יושר\", בהמשך עלה לירושלים."},{"i":23919,"n":"יעקב ממינסק","f":"יוסף","dt":"תקפו - כא חשון","dp":"מינסק","b":"מחכמי מינסק."},{"i":23920,"n":"יעקב ממינסק וירושלים","f":"דובער","b":"מחכמי ירושלים, חתם-תרכג כנגד ר\"מ ירושלמסקי, חתם על שטר \"התקשרות\"-תרל."},{"i":23921,"n":"יעקב ממיקלוש","b":"רב במיקלוש-תקפ\"ו"},{"i":23922,"n":"יעקב ממיר ווילנא","f":"צבי הירש","k":"בעל עטרת צבי","b":"רב במיר, וילנא-תקצד."},{"i":23923,"n":"יעקב ממצרים","f":"יוסף","b":"מחכמי ספרד, דיין במצרים-רפז אצל הרדב\"ז."},{"i":23924,"n":"יעקב ממצרים","f":"חיים","b":"שר-ג'יליבי במצרים-שמד בערך ור אלעזר אב\"א בן אברהם סכנדרי על מקומו אחריו, סייע לפתוח את ביהכ\"נ של המסתערבים שנסגר-שה."},{"i":23925,"n":"יעקב מנארול","b":"רב בנארול-תק\"ס"},{"i":23926,"n":"יעקב מנדרזין","b":"אדמו\"ר בנדרזין-תר\"ס"},{"i":23927,"n":"יעקב מנוברדוק","f":"צבי הירש","k":"בעל שמע יעקב","b":"מו\"צ בנוברדוק-תקפ."},{"i":23928,"n":"יעקב מנוסטרישץ","b":"רב בנוסטרישץ."},{"i":23929,"n":"יעקב מנחם מנדל מסמבור","b":"רב בסמבור-תרך."},{"i":23930,"n":"יעקב מניישטטל","dt":"תקמו - י טבת","b":"רב בניישטטל"},{"i":23931,"n":"יעקב מנפולי","f":"שמשון","k":"בעל מלמד התלמידים","bt":"ד'תתקס","b":"פילוסוף,דרשן ומתרגם בנאפולי"},{"i":23932,"n":"יעקב מנשה משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"שיטת המאירי\", ו\"באר מים חיים\"-תקנד."},{"i":23933,"n":"יעקב מנשכיז","b":"רב בנשכיז"},{"i":23934,"n":"יעקב מסאלקא","b":"רב בסאלקא-תקע\"ה"},{"i":23935,"n":"יעקב מסוואנציאן ווליקומיר","b":"רב בוילקומיר, פומפיאן. (נזכר ב\"עלילות אליהו\" ע' 56)."},{"i":23936,"n":"יעקב מסוכטשוב","f":"יואל","b":"רב בסוכטשוב, סוקלוב. בנו - ר יהושע השל."},{"i":23937,"n":"יעקב מסטשעגאווי","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":23938,"n":"יעקב מסינוביץ","b":"רב בסינוביץ-תק\"ס"},{"i":23939,"n":"יעקב מסלונים","b":"חתן ר דובער שניאורסון האדמור האמצעי. נכד ר אליעזר בעל \"משנת דרבי אליעזר\"."},{"i":23940,"n":"יעקב מסלוצק","dt":"תפ","b":"רב בסלוצק"},{"i":23941,"n":"יעקב מסלץ","f":"יוסף","k":"בעל זרע ישראל","b":"רב בסעלץ-ת\"פ"},{"i":23942,"n":"יעקב מסמוליאן","f":"אריה ליב","b":"גבאי מעות ארץ ישראל - תקמב-תקסה. איש אמונם של ראשי הקהלה החסידית בארץ. אליו מכוון מכתבו של ר מנחם מנדל מויטבסק ובו כתב כי אין הוא יכול להושיע בבנים - אחד היה הבעש\"ט."},{"i":23943,"n":"יעקב מסמילא","b":"רב בסמילא"},{"i":23944,"n":"יעקב מסעוד","b":"מחכמי צפת מתלמידי הארי, חתום בשטר התקשרות משנת תלה. נזכר ברשימת התלמידים ב\"שער הגלגולים\"."},{"i":23945,"n":"יעקב מסערעד","f":"ברוך","dt":"תרכט","b":"חתן ר משה מייזלש מסערעד. דיין בסערעד כ-40 שנה."},{"i":23946,"n":"יעקב מפאנו","f":"יואב אליה","k":"בעל שלטי הגבורים","b":"רב בפאנו, פיררה. רבו של ר אברהם שער אריה בעל \"שלטי הגבורים\" - על תלאות היהודים במדינת האפיפיור. (לדברי פין - הוא מחבר הספר). חיבר קיצור חובות הלבבות - ונציה תצו."},{"i":23947,"n":"יעקב מפאסטא","dt":"תקנד - כט אדר","b":"רב בפאסטא"},{"i":23948,"n":"יעקב מפאריס","b":"תלמיד ר יחיאל מפאריס, בשליחות ר יחיאל במזרח לטובת הישיבה בפאריס, בהיותו בארץ רשם את קברות הצדיקים."},{"i":23949,"n":"יעקב מפאריס","f":"שמשון","k":"בעל האלקושי","b":"מבעלי התוספות בצרפת-ד'תת."},{"i":23950,"n":"יעקב מפביאניעמשי","b":"רב בפיאבניטש-תר\"ע. אחיו של ר ליב מוולצלאוועק."},{"i":23951,"n":"יעקב מפוזנא","f":"יצחק בן אברהם מפוזנא","k":"בעל מנחת יעקב","b":"חתן ר נפתלי כץ מאוסטרהא, רב בפוזנא-תכ על מקום חותנו שעבר לפפד\"מ. הסכים על \"חקי דרך\" - תעז. חתנו ר יצחק דב מביאזליויץ בעל \"באר יצחק\". תיקן יום תענית - ה אב וחיבר סליחה - לזכר הפרעות שהיו בפוזנא-תעו, ועל השרפה שהיתה בשנת תעז."},{"i":23952,"n":"יעקב מפולאנגן","b":"רב בפולאנגן-ליטא-תעט."},{"i":23953,"n":"יעקב מפולנאי","f":"יקותיאל זלמן מדרוהוב","b":"רב בפולנאי. אחד מ-7 אחים רבנים (ואולי טעות - אחד האחים ר יעקב יצחק דוקלא מפרשבורג)."},{"i":23954,"n":"יעקב מפיאסק","b":"חתן ר אורי שרגא פיבל מדובנקא-קריסנפולי."},{"i":23955,"n":"יעקב מפינטשוב","f":"ר\"פ מקרמניץ","dt":"תח","b":"תלמיד המהר\"ם מלובלין. רב בפינטשוב, חברו של בעל \"ברכת טוב\" שהביא ממנו בספרו. נהרג על קדוש השם בגזירות תח ותט."},{"i":23956,"n":"יעקב מפלנצא","k":"בעל ישועות יעקב","b":"רב בפלענצא-תק\"כ"},{"i":23957,"n":"יעקב מפפד\"מ","dt":"תקמח - ז ניסן","b":"עניו,דיין בפפד\"מ"},{"i":23958,"n":"יעקב מפפד\"מ","f":"יודא","b":"מחכמי פפד\"מ-שכה, חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ."},{"i":23959,"n":"יעקב מפרג","f":"יצחק מפרג","b":"רב בעדנבורג-ר\"מ"},{"i":23960,"n":"יעקב מפרוזין","b":"דיין בפרוזין בזמן הגדול ממינסק."},{"i":23961,"n":"יעקב מפרשבורג","b":"מחכמי פרשבורג-רה, ונזכר ב\"לקט יושר\" שהיה במו\"מ הלכתי עם ר ישראל איסרלין בעל \"תרומת הדשן\"."},{"i":23962,"n":"יעקב מפרשבורג","dt":"תקמו","dp":"פרשבורג","b":"מחכמי פרשבורג, גבאי חברא קדישא."},{"i":23963,"n":"יעקב מצוזמיר","f":"יצחק הקדוש מחנטשין","k":"בעל פירוש על המסורה","b":"רב בצוזמיר-שנות ה-ש'. תלמיד בעל \"עבודת הבורא\". חיבר פירוש על המסורה-לובלין שעו, ובנו ר יצחק יודא הו\"ל את ספרו עם הוספות ממנו. חיבר פירוש על המסורה ועל חידת ראב\"ע."},{"i":23964,"n":"יעקב מצפרו-מרוקו","f":"שמואל","b":"מחכמי צפרו-מרוקו שנות ה-ת'."},{"i":23965,"n":"יעקב מצפת","f":"שמעון","dt":"תקצז","dp":"צפת","b":"מחכמי צפת, חתום על אגרות משנת תקצה, נהרג ברעש."},{"i":23966,"n":"יעקב מקאזאווא","b":"רב בקאזאווא-תר\"ס"},{"i":23967,"n":"יעקב מקאלין","b":"רב בקאלין-תק\"מ"},{"i":23968,"n":"יעקב מקאליש","b":"תלמיד המגיד ממזריטש. היה החסיד הראשון בקאליש. נסע גם אל החוזה מלובלין. בנו ר משה אב\"ד סוכטשוב."},{"i":23969,"n":"יעקב מקוצי","b":"מגדולי בעלי התוספות-ד'תתק\"צ. אביו של הסמ\"ג."},{"i":23970,"n":"יעקב מקורביל הקדוש","dt":"ד'תתקצב","b":"מגדולי בעלי התוספות. נהרג עק\"ה."},{"i":23971,"n":"יעקב מקורשן","f":"שלמה","b":"תלמיד ר שמשון משאנץ. חיבר נמוקים הנזכרים ב\"הגהות מימוניות\"."},{"i":23972,"n":"יעקב מקושטא","f":"יצחק","b":"רב בקושטא-שנות ה-תק."},{"i":23973,"n":"יעקב מקושטא","f":"חיים","b":"מדפיס בקושטא-תעח. עם האומן הרופא ר חיים טוויל. הדפיס את \"יאיר נתיב\" לר אברהם הלוי."},{"i":23974,"n":"יעקב מקזאלי","f":"יצחק הלוי","k":"בעל דבר אגור","b":"חיבר \"דבר אגור\" ונציה."},{"i":23975,"n":"יעקב מקטילבורג","b":"רב בקאטילבורג-תק\"פ"},{"i":23976,"n":"יעקב מקידאן","k":"יעקל קאדאנער-ויכוחא","b":"תלמיד ר אהרן מסטראשלא, ר דב בר וחתנו הצמח צדק. הו\"ל \"מצרף העבודה\" בשם \"ויכוחא רבא\", חיבר גם \"ספורים נוראים\" על חסידות חב\"ד."},{"i":23977,"n":"יעקב מקיוסטנדיל","f":"יהודה אלעזר","b":"דיין בקיוסטנדיל-תקסז אצל ר יצחק שמואל חרבון, יחד עם ר דוד אוליבירו."},{"i":23978,"n":"יעקב מקיליקוב ולבוב","dt":"תק - כג כסלו","dp":"לבוב","b":"רב בקוליקוב(=קיליקוב), לבוב."},{"i":23979,"n":"יעקב מקינון","b":"תלמיד ר יצחק בן אברהם-הריצב\"א). מבעלי התוספות בצרפת-ד'תתקע."},{"i":23980,"n":"יעקב מקראקא","b":"דיין בקרקא-שי\"ט"},{"i":23981,"n":"יעקב מקרוז'","f":"מנחם","dp":"ירושלים","b":"חתן ר אליהו בן מאיר מקרוז'-גיסו של הגר\"א. רב בקרוז על מקום גיסו ר בנדיט כ-40 שנה. עלה לירושלים."},{"i":23982,"n":"יעקב מקרוז' וז'אזמיר","dt":"תרלז","b":"תלמיד ר חיים מוולוזין. רב בז'אזמיר ובנו ר יקותיאל ליב עליון על מקומו אחריו. עלה לארץ-תרלד. אחיו היה ר מרדכי הורביץ רבה של קרוז'."},{"i":23983,"n":"יעקב מקרוטושין","dt":"תצד - כה אד\"ב","b":"רב בקאראטשין,דמברשיץ"},{"i":23984,"n":"יעקב מקריספולי(=קריסנפולי)","f":"יהודה ליב מוילנא","k":"בעל פדויות יעקב","b":"רב בקריספולי(=קריסנפולי)-תקם. חתן ר נתן נטע מפיליפאווי-ליטא, רב בפיליפאווי. חיבר \"פדויות יעקב\" פפדא תקנו."},{"i":23985,"n":"יעקב מקרלין","f":"אהרן הגדול מקרלין","bt":"תקך - לפני","b":"חתן ר אברהם מקרלין. תלמיד המגיד ממזריטש. עלה עם חותנו לארץ והתישב בצפת. חתנו ר שמואל אלעזר רוקח בן ר מאיר מלובלין. נפטר צעיר."},{"i":23986,"n":"יעקב מרגנטהיים","k":"ופפד\"מ","b":"מראשי קהילת פפד\"מ-תקס."},{"i":23987,"n":"יעקב מרדכי הלוי","f":"נסים רפאל","bt":"תרכג","bp":"ירושלים","dt":"תרעז","dp":"ירושלים","b":"מחכמי ירושלים, חיבר הלכות שחיטה בכתב יד."},{"i":23988,"n":"יעקב מרדכי מפוזנא","f":"יצחק מפוזנא","dt":"תצ","b":"חתן ר משלם זלצבורגר מלבוב. רב בפוזנא והמדינה-תעד. יש אומרים שחתנו - ר יעקב עמדין (ראה גם: ר מרדכי כץ מפוזנא)"},{"i":23989,"n":"יעקב מרדכי מפלטשין","b":"רב בפלטשין-תרכו."},{"i":23990,"n":"יעקב מרוזליה","b":"רב בונדיזיגולה על מקום ר קלמן רבין, שקוד."},{"i":23991,"n":"יעקב מרחמניבוצה","dt":"תקיא - יז כסלו","b":"רב ברחמניבוצה"},{"i":23992,"n":"יעקב מרימנוב","b":"תלמיד ר מנחם מנדל מרימנוב. אחד משלושת התלמידים שנשארו ברימנוב ונחשבו לממלאי מקומו של האדמור - עד שהחל ר צבי הירש לנהוג אדמורות."},{"i":23993,"n":"יעקב מרעזיצא וירושלים","b":"דיין בירושלים, חתם-תרנד אחרי ר אריה ליב הורביץ."},{"i":23994,"n":"יעקב משברשין (שברשינר)","f":"אליעזר מזלוטשוב"},{"i":23995,"n":"יעקב משה בן נתן","dt":"ה'תקל 1770","bk":[["חידושי הלכות",""],["חידושי רבינו יעקב",""]]},{"i":23996,"n":"יעקב משה הלוי","b":"רב בסובוטה"},{"i":23997,"n":"יעקב משה הלוי משלוניקי","b":"מדפיס בשלוניקי-תקטו אצל מרדכי נחמן ורפאל קלעי."},{"i":23998,"n":"יעקב משה מאמשטרדם","f":"שאול מדובנא ואמשטרדם","b":"חתן דודו ר צבי הירש מברלין. רב באמשטרדם-תקנג על מקום אביו."},{"i":23999,"n":"יעקב משה מהליטש","b":"רב בהאליטש-תקל\"ד"},{"i":24000,"n":"יעקב משה מטימשואר","dt":"תקא או תקט","b":"הגיע מבלגרד, רב בקהלה הספרדית בטימישואר-תצט."},{"i":24001,"n":"יעקב משה מנחם מנדל מטורקא","f":"דוד שמואל שמלקא","b":"רב בטורקא-תקכ\"ה,פרעמישלא-תקל\"א"},{"i":24002,"n":"יעקב משה מסלוצק","b":"רב בסלוצק"},{"i":24003,"n":"יעקב משה מקיטוב","b":"רב בקיטוב, קוסוב-תרך."},{"i":24004,"n":"יעקב משוטהפארט-אנגליה","b":"פרסם מאמרים ב\"אהל יצחק\" סטמר - תרסג - תרעד."},{"i":24005,"n":"יעקב משימבורג","b":"שו\"ב בשימבורג-תקץ בערך, הביא לשם את ר מרדכי בן יקותיאל זלמן הלוי כרב, ולאחר שעבר ליאקובשטט היה באופן זמני גם מו\"צ יחד עם ר השל."},{"i":24006,"n":"יעקב משלוניקי","f":"יהודה עוזיאל","b":"מחכמי שלוניקי."},{"i":24007,"n":"יעקב משלוניקי","f":"שמואל","b":"ראש ישיבת אירירה בשלוניקי, וחבר בועד ביהמ\"ד לרבנים בשלוניקי, ו\"הקדש קובו\". אחיו של הדיין ר בנבנישתי שמואל."},{"i":24008,"n":"יעקב משלוניקי","f":"עוזיאל שלמה","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תע."},{"i":24009,"n":"יעקב משלוניקי","f":"אברהם יקותיאל","b":"מדפיס בשלוניקי-תקך אצל מרדכי נחמן ורפאל קלעי."},{"i":24010,"n":"יעקב משלם מלבוב וירושלים","dp":"ירושלים","b":"(האם ר יעקב אורנשטין הישועות יעקב? לפי פרומקין-ריבלין נפטר בירושלים?)"},{"i":24011,"n":"יעקב משצושצין","b":"מג\"מ ומו\"צ בשעצושצין-תק\"א"},{"i":24012,"n":"יעקב משקלוב","f":"יהודה מקלצק ומיצט","k":"בעל מורה צדק","bt":"[תפג]","dt":"תקלה - ד תשרי","b":"רב בשקלוב, סלוצק. בנו ר אהרן הו\"ל את ספרו \"מורה צדק\", ומזכיר בספרו את בן דודו ה\"שאגת אריה\". והניח עוד חדושים בכת\"י. בניו - ר ברוך משקלוב שהו\"ל ספר אוקלידס בהוראת רבו הגר\"א, ור אהרן מפראפאיסק.","bk":[["מורה צדק – בציעת הפת",""]]},{"i":24013,"n":"יעקב משקלוב","f":"שלמה פריידס","b":"תלמיד בעל התניא ובנו ר דב בער מליובאויטש. התפרסם בתפילותיו הארוכות."},{"i":24014,"n":"יעקב ן, בונג'אה מקושטא","b":"מגדולי חכמי קושטא-ש\"נ"},{"i":24015,"n":"יעקב ן, יעקב משלוניקי","dt":"שכד - תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24016,"n":"יעקב ן, שלום מאלגיר","f":"שלום בן סעיד בן שלום","b":"רב ומשורר באלגיר-בשנות ה-ת' בערך."},{"i":24017,"n":"יעקב נח מבלוזוב","b":"רב בבלוזוב-תרכג (היתה מחלוקת עם ר אברהם יצחק)."},{"i":24018,"n":"יעקב נסים מדובניצה","bp":"ארץ ישראל","b":"רב בדובניצה-תקס בערך."},{"i":24019,"n":"יעקב נפתלי הלוי מזולקוא","f":"שלמה בן יצחק אברהם","b":"מחכמי זולקוא, חתם-תיט על תקנת הקהלה."},{"i":24020,"n":"יעקב נפתלי מסופיה","b":"רב הקהלה האשכנזית בסופיה-(שעו?) או תכה על מקום ר אסטרוק שאנג'י (שיצא לקושטא בדרכו לירושלים). נוטה לשבתאות ובזנת תכז חגגו בסופיה את יום תשעה באב."},{"i":24021,"n":"יעקב נתן הכהן כץ מפינטשוב","f":"שלמה זלמן","dt":"תקכז - ב אדר","b":"רב בבוליחוב-תקכו, פינטשוב."},{"i":24022,"n":"יעקב סגל מבריסק","f":"מאיר","b":"פרנס בבריסק, חתם-תקיב עם כמה מחבריו על מכתב לר יונתן איבשיץ בענין הקמיעות."},{"i":24023,"n":"יעקב סגל מוילנא","b":"שמש קהלת וילנא-תיא."},{"i":24024,"n":"יעקב סגל מזולקוא","f":"אהרן","b":"מחכמי זולקוא, חתם-תנד על תקנת הקהלה."},{"i":24025,"n":"יעקב סגל מפדובה","f":"משה","dt":"שלב - ח אלול","b":"רב בפדובה. חתן מהר\"ם פאדובה. מוזכר ב\"אבני זכרון\"."},{"i":24026,"n":"יעקב סופר מפמורן","b":"רב וסופר בפמורן-תרך."},{"i":24027,"n":"יעקב סקלאווער מאוסטרהא","f":"צבי הירש החסיד","dt":"תקלב - ז תשרי","dp":"אוסטרהא","b":"בנו של ר צבי הירש מבית אהרן. מחכמי אוסטרהא, מיושבי הקלויז הגדולה. הסכים על \"מפלגי ראובן\". בנו ר שמחה שנפטר-תקם."},{"i":24028,"n":"יעקב עובדיה מאדרינופול","b":"רב עדת קשטיליה באדרינופול על מקום קרובו ר יעקב עובדיה."},{"i":24029,"n":"יעקב עוזיאל מקושטא","k":"בעל תקון סעודת פורים","b":"רופא מחכמי קושטא-תקך. חיבר תיקון סעודת פורים בספרדית בשם \"או קופלאש\" ונדפס בתוך \"תוכחת סגולה\"-קושטא תקטז."},{"i":24030,"n":"יעקב עזרה משלוניקי","dt":"תב - תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי, מחותמי הסכמות הקהל."},{"i":24031,"n":"יעקב עזריאל מטעפליק","b":"חסיד ר משה צבי מסאווראן. רב בטעלעפין(=טעפליק)-תרכ."},{"i":24032,"n":"יעקב פנחס מלטיטשוב","f":"אברהם דב מחמלניק","b":"נכד ר יעקב יוסף בעל \"תולדות יעקב יוסף\". רב בלעטישוב. בנו ר ישראל ממזבוז."},{"i":24033,"n":"יעקב פרץ מאישפלאטו","b":"דיין באישפלאטו-תקד עם ר אברהם מאיסטרו, ר יהושע יצחק מאג'ורו."},{"i":24034,"n":"יעקב פרץ מוילנא","f":"אברהם קליאצקא","dt":"תקס - ג תמוז","dp":"וילנא","b":"מראשי קהילת וילנא. גיסו של ר אשר בן קלונימוס גינצבורג. בנו - הגביר ר מרדכי מוילנא."},{"i":24035,"n":"יעקב צבי אשכנזי מניקלשבורג","dt":"תסג - כח אב","dp":"פיליבי","b":"גביר בניקלשבורג, עלה לארץ ונפטר בדרכו בפיליפופולי."},{"i":24036,"n":"יעקב צבי הירש מנוברדוק","b":"רב בנוברדוק על מקום ר מרדכי מרקיל ור ישראל בעל \"אבן בוחן\" על מקומו אחריו. מתורתו ב\"תולדות אדם\" דירנפורט תקסא."},{"i":24037,"n":"יעקב צבי מאוסציא","f":"יהודה ליב","b":"רב באוסציא, מינקוביץ-תקנב."},{"i":24038,"n":"יעקב צבי מבערשיד","f":"יצחק","b":"רב בבערשיד"},{"i":24039,"n":"יעקב צבי מברלין","b":"פרנס, מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב. אירח את הגר\"א בביתו בהיותו בברלין."},{"i":24040,"n":"יעקב צבי מוילנא","f":"אהרן מקראקא","b":"גביר מראשי קהלת וילנא, חתם-תע בפנקס הקהלה. מחותן עם ר משה דרשן מוילנא."},{"i":24041,"n":"יעקב צבי מלובלין","dt":"תקכא - כא שבט","b":"מו\"צ בלובלין"},{"i":24042,"n":"יעקב צבי מסויסלאץ","b":"בן אחותו של ר יעקב המגיד מדובנא. רב בסויסלאץ."},{"i":24043,"n":"יעקב צבי מפודקמין","b":"רב בפודקמין-תק\"ס"},{"i":24044,"n":"יעקב צדוק משלוניקי","dt":"תרסח","dp":"שלוניקי","b":"רופא בשלוניקי-תרס, בחברת \"ביקור חולים\"."},{"i":24045,"n":"יעקב קופל (קאפילעטיס) מקולומיא","f":"נחמיה פייבל","dt":"תקמז - טו אלול","dp":"טיסמניץ","b":"מצאצאי ר עובדיה מברטנורא. חתן דודו-אחי אביו ר זלמן חתן בעל הט\"ז. הבעשט פגשו בקולומיא וקירבו, והפקיד בידיו את מחוז מארמרוש. כשהיה אצל הבעשט שימש כש\"ץ בבית מדרשו, ונוסח התפלה שלו מקובל ב\"חצר\" ויזניץ, כונה בפי הגויים \"שיוויתניק\" - מהיותו מעביר ידיו על עינו ואומר \"שויתי ה' לנגדי תמיד\". עבר לטיסמניץ. תולדותיו ב\"אבן שתיה\", ו\"תפארת שבמלכות\". בנו ר מנחם מנדל הגר מקוסוב."},{"i":24046,"n":"יעקב קופל הכהן מלבוב ופרמישלא","f":"אשר מלבוב","dt":"שץ - כז תשרי","dp":"לבוב","b":"אב\"ד לבוב - חוץ לעיר וחתנו - ר זאב וולף הכהן על מקומו אחריו. היה במחלוקת עם חכמי לבוב בענין אילנות בבית הקברות האם נחשבים לאהל לענין טומאת כהנים, ונזכר ב\"איתן האזרחי\", חתם-שן על תקנות יריד גרמניץ בלובלין, ועוד חתימות רבות ממנו. בנו - ר אברהם מטארלי, חתנו - ר זאב וולף הכהן כץ מלבוב-בן משה מרדכי."},{"i":24047,"n":"יעקב קופל הכהן מלובלין","f":"שמשון","dt":"ת - כט אדר","b":"גביר ופרנס בלובלין."},{"i":24048,"n":"יעקב קופל זסלבר","f":"אהרן","k":"בעל נחלת יעקב","b":"מו\"צ בכמה קהילות באוסטריה, לאחר הגירוש הגיע למדינת פיהם."},{"i":24049,"n":"יעקב קופל מאייזנשטט","b":"ראב\"ד באייזנשטט"},{"i":24050,"n":"יעקב קופל מברודשין","b":"רב בברודשין-תרלב."},{"i":24051,"n":"יעקב קופל מלבוב","f":"ישכר בער","b":"מראשי קהלת לבוב, חתם-תקלו עם ר יעקב בן שמשון וולף."},{"i":24052,"n":"יעקב קופל מלובלין","b":"אב\"ד לובלין-תקכט. נזכר ב\"תיבת גומא\"."},{"i":24053,"n":"יעקב קופל מליקובא","k":"ר' יעקב קופל מליקובה","dt":"תקכט - טו אדר","b":"גדול בנגלה ונסתר בליקובא."},{"i":24054,"n":"יעקב קופל מצפת","f":"בנימין","dt":"תקעד","dp":"צפת","b":"עלה לצפת עם ר מנחם מנדל משקלוב, והיה אחד הרבנים בקהלה עם אחיו - ר שמחה."},{"i":24055,"n":"יעקב קופל מקרלסבורג","b":"דיין בקרלסבורג-תקע בערך."},{"i":24056,"n":"יעקב קופל מקרקוביץ","b":"רב בקרקוביץ."},{"i":24057,"n":"יעקב קופל סגל מזולקוא","f":"דוד","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":24058,"n":"יעקב קופלמן מפרייבורג","f":"שמואל בונם","k":"בעל עומק הלכה","bt":"שי-שטו","b":"תלמיד ר מרדכי יפה בעל הלבוש. מחכמי פרייבורג(=ברייסטגויא), רב בפפד\"מ-שמה, בזמן המגפה וחיבר \"אהל יעקב\" - פירוש לספר העקרים - למען הזכיר שמו אם ימות בנגף. חיבר ספר בחשבון \"עומק הלכה\", תרגם את התרגום שני למגילות ללשון אשכנז."},{"i":24059,"n":"יעקב קלונימוס ממונטיינא","f":"אליעזר","b":"רב במנטובה-שי. תשובה ממנו בתשובות מהרמא\"י לטובת הר\"ר מ\"ץ - בנוגע לפסילת גט."},{"i":24060,"n":"יעקב קלונימוס קלמן מורמייזא","dt":"שכ - ב אייר","dp":"לבוב","b":"מראשוני רבני ומרביצי התורה בפולין ורייסן בזמנו של ר שכנא, רב בלבוב-רעח למעלה מ-40 שנה. מתלמידיו - הרמ\"א שהביא תשובה ממנו בספרו. תשובה ממנו גם ב\"שארית יוסף\" - קראקא שן, נזכר גם בשו\"ת המהרש\"ל והסכים על הספר. חתנו - ר אליעזר בן מנוח."},{"i":24061,"n":"יעקב קפיל מורמיזא","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":24062,"n":"יעקב ראובן מלביטש","b":"רב בלביטש-תריט, דלטין. חותנו של ראי\"ה טברסקי משטודנוב."},{"i":24063,"n":"יעקב רפאל הכהן מלונדון וקנדה","bp":"צפון אפריקה","dt":"תקעא","b":"רב בלונדון-תקלח, מונטריאול-קנדה - והיה שם הרב הראשון בקהל \"שארית ישראל\", פילדלפיה-תקמג בק\"ק \"מקוה ישראל\"."},{"i":24064,"n":"יעקב שאול מאזמיר","f":"שאול","k":"בעל קול יעקב","dt":"תקיח - כט ניסן","dp":"אזמיר","b":"דיין ומו\"צ באזמיר-תקט ור חיים בן דוד אבולעפיה על מקומו אחריו-תקכא."},{"i":24065,"n":"יעקב שאול משלוניקי","b":"רב בשאלוניקי-תק\"ס"},{"i":24066,"n":"יעקב שלום מונציה","b":"בן אחותו של ר שמואל הקהן די פיזא לוזיטאנו המביא ממנו בספרו \"צפנת פענח\"."},{"i":24067,"n":"יעקב שלום מראאב","b":"רב בראאב-תקפ\"ג"},{"i":24068,"n":"יעקב שלמה הכהן מפשמישל","b":"רב בפשמישל-תרך."},{"i":24069,"n":"יעקב שם טוב הכהן משלוניקי","dt":"תרכד","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":24070,"n":"יעקב שמואל משוורצוולד","f":"שמעון שוואבך מפיורדא","b":"חתן ר דוד דישבק בעל פרדס דוד, מתורתו בספרו חותנו (בקונטרס בסוף הספר)."},{"i":24071,"n":"יעקב שמחה בוים (בונם?) מטומשוב","b":"רב בטומשוב."},{"i":24072,"n":"יעקב שמעון \"סופר\" מקראקא","k":"ר שמעון חסיד","dt":"תקצז - טז שבט","b":"חתן ר יצחק מקולבוסוב. חברו של ר קלונימוס קלמיש בעל \"מאור ושמש\". אשתו מרים היתה מפורסמת כבעלת מופת."},{"i":24073,"n":"יעקב שמריה משלוניקי","dt":"שפט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24074,"n":"יעקב שמשון מאודסה","f":"יצחק יוסף","b":"דיין באודסה, חתם-תרמד עם ר יוסף ישראל הלפרין."},{"i":24075,"n":"יעקב שמשון מהנאו","dt":"תלז - כא אדר","b":"רב בהאנוי"},{"i":24076,"n":"יעקב שמשון משיפיטובקה","dt":"ה'תקסא 1801","bk":[["דברי צדק",""],["מעשה רבי יעקב שמשון משיפיטובקה",""]]},{"i":24077,"n":"יעקב שנה טובה","f":"שלמה","b":"רב בשנת תל\"ח. מופיע בשו\"ת ר יצחק לוי ואלי."},{"i":24078,"n":"יעקב שרגא פיבל","b":"רב בלעכוויץ"},{"i":24079,"n":"יעקב תמרלש מלובלין","k":"בעל ספרא דצניעותא","dt":"תכו","dp":"וינא","b":"נכד המהרם מרוטנבורג. רב בקרמניץ, וינא. חיבר \"ספרא דצניעותא דיעקב\". חתנו של ר אברהם חיים מאפטא מניקלשבורג."},{"i":24080,"n":"יעקב, אהרן","b":"אב\"ד בדמשק"},{"i":24081,"n":"יעקב, גדליה","b":"מקובל, דיין באגאדיר(מרוקו)"},{"i":24082,"n":"יעקבי, דוד","f":"סעדיה","k":"בעל מזבח הזהב","b":"רב בתימן, חיבר \"מזבח הזהב\""},{"i":24083,"n":"יעקבי, משה דב מארה\"ב","f":"יעקב יהושע","k":"בעל קונטרס החיוב","b":"מחסידי חב\"ד בניו יורק."},{"i":24084,"n":"יעקבי, סעדיה מתימן","f":"דוד","k":"בעל מחזק בדק","b":"מחכמי תימן-תריט. חיבר קונטרס בהלכות שחיטה בשם \"מחזק בדק\" - \"בדק המזבח\" בכת\"י. בנו כנראה ר דוד בן סעדיה יעקבי."},{"i":24085,"n":"יעקבס, דוד מאנגליה","bt":"תרכט","bp":"וארשא","b":"תלמיד ישיבת וולוזין. רב בפנטפריד-אנגליה-תרנא, לונדון בקהלת דלסטון, פלימות-תרע."},{"i":24086,"n":"יעקבקא","b":"רב בגלוגא,ניקלסבורג-ת\"מ"},{"i":24087,"n":"יעקבקא מברודי","f":"דניאל מלובלין","dt":"תצז - יח אלול","b":"פרנס ברודי. חתניו: הנודע ביהודה, ר אברהם מרדכי הלפרין מזולקווא."},{"i":24088,"n":"יעקבקא, אהרן יעקב","f":"יחזקאל","dt":"תלא - כ ניסן","b":"רב בלודמיר,רב המדינה בניקלסבורג"},{"i":24089,"n":"יעקבקא, יחזקאל","f":"יעקב משה יעקובקא","b":"רב בלודמיר,דומ\"צ בפוזנא-שצ\"ג-ת\"ד"},{"i":24090,"n":"יעקבקא, יעקב משה","f":"יחזקאל","b":"רב-שנת ש\"מ"},{"i":24091,"n":"יעקבקי מאוסטרהא","f":"יהושע י\"פ מאוסטרהא","dt":"תקכה - יט אדר","dp":"אוסטרהא","b":"פרנס באוסטרהא-תקג. בנו ר בריש."},{"i":24092,"n":"יעקבש, אליעזר מסטניסלב","b":"רב בסטאניסלאוו"},{"i":24093,"n":"יעקובוביץ, אהרן מירושלים","f":"אלחנן מביאליסטוק","bp":"תרעד","dp":"תשלג","b":"חתן ר אריה לוין - הצדיק הירושלמי. מעורכי \"אוצר הפוסקים\"."},{"i":24094,"n":"יעקובוביץ, אלחנן מירושלים","k":"בעל אבן שמעון","bt":"תרלה","bp":"גרייבה-ליד דוינסק","dt":"תשא","b":"מכונה חנן גריווער.תלמיד ישיבות ראדין, סלובודקה, ונבחר בין בחירי התלמידים מיסדי ישיבת סלוצק, מקורב לסבא מקלם. ר\"מ ומשפיע מוסרי בכמה ישיבות, ואח\"כ במיר וביאליסטוק. עלה לארץ-תרצג. מכתבים ממנו ב\"תבונה\" - ירושלים תשא-תשח, פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":24095,"n":"יעקובוביץ, אלתר יוסף מאלכסנדר","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"כרם בית שמואל\" - פיעטרקוב תרצא, \"כרמנו\" - אלכסנדר-לודז תרצג, \"נהור שרגא\" - אלכסנדר תרצט."},{"i":24096,"n":"יעקובוביץ, אריה יהודה","b":"תלמיד ר יעקב הורביץ מדלטין."},{"i":24097,"n":"יעקובוביץ, ברוך מטרנוב","f":"מאיר","bt":"תריד","dt":"תרפו","b":"מחכמי טרנוב ועסקן ציבורי. חתן ר אברהם אליעזר וואהל."},{"i":24098,"n":"יעקובוביץ, חיים אורי מטיסא סלק","k":"אדמור מהאדאס טיסא סל","dt":"תשד - כח אדר","b":"חתן ר יחזקיה פיש מהאדאס. רב בפאביאנהאז-תרצא. אדמור בטיסא סלקא. נספה בשואה. חיבר \"בית אברהם\"."},{"i":24099,"n":"יעקובוביץ, יואל מלונדון","f":"שלמה זלמן מלקנבך","b":"תלמיד הדעת סופר, ור דוד פרידמן מצעהלים, וביהמ\"ד לרבנים בברלין. חתן ר יעקב יהודה ורשנר מבאד-הומבורג. רב בקניגסברג, ברלין-תרפב, לונדון. בנו ר ישראל עמנואל - הרב הראשי לבריטניה."},{"i":24100,"n":"יעקובוביץ, יחזקאל מואדקרט","b":"ראב\"ד בואדקערט-הונגריה."},{"i":24101,"n":"יעקובוביץ, יעקב","b":"פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":24102,"n":"יעקובוביץ, ישראל עמנואל","f":"יואל מלונדון","b":"תלמיד הדעת סופר. רב ראשי בבריטניה, אירלנד."},{"i":24103,"n":"יעקובוביץ, משה יהודה מקעלין","f":"שלמה זלמן מלקנבך","k":"בעל זכרון משה,ארה\"ב","bt":"תרן","bp":"לקנבך","dt":"תשי - כט אב","dp":"ניו יורק","b":"תלמיד הדעת סופר, ור מרדכי מאיר בנט משטינמאנגר, ועוד. חתן ר מרדכי ליפשטאט מהמבורג. רב בקעלין-תרעג, שטרסבורג-תרצה. ניצל מהשואה וברח לשוייץ. רב בניו יורק-תשז.","bk":[["זכרון משה - חידושים על רוב מסכתות הש\"ס",""],["זכרון משה",""]]},{"i":24104,"n":"יעקובוביץ, מתתיהו מודוביצה","f":"ברוך","bt":"תרלג","bp":"טרנוב","dt":"תשב","b":"איש עסקים, ראש קהילת ודוביצה. חתן ר יצחק אהרן שנקר. נספה בשואה."},{"i":24105,"n":"יעקובוביץ, שלמה","dt":"תשג","b":"מרבני פולין"},{"i":24106,"n":"יעקובוביץ, שלמה זלמן מלקנבך","b":"חתן ר טוביה שוורץ מלקנבך, רב בלקנבך על מקום חותנו. בניו - ר יואל דיין בלונדון, ר משה יהודה דיין בקעלין."},{"i":24107,"n":"יעקובוביץ, שלמה ליב מלודז","f":"ישראל יצחק","k":"בעל קשות מיושב","dt":"תרפג - לפני","b":"מחכמי לודז. חיבר \"קשות מיושב\" על \"חלקת יואב והערות על ספרי ר ישעיה פיק. ונדפס ע\"י בניו אחר פטירתו."},{"i":24108,"n":"יעקובוביץ, שמעון מואדקערט","b":"תלמיד ר משה פורהאנד, ר שמואל רוזנברג, ור יהושע בוקסבוים. עסק במסחר. ניצל מהשואה, ואחריה רב בואדקערט וראש ישיבה - אחרי השואה, במרד-1956 הותקף בנין הישיבה ונאלץ לסוגרה - עלה עם חלק מתלמידיו לארץ וחלקם עברו לאמריקה."},{"i":24109,"n":"יעקובזון, אברהם דוד מירושלים","b":"רב בירושלים-תר\"ע"},{"i":24110,"n":"יעקובזון, אברהם ישראל משבדיה","dt":"תשטו","b":"רב בשטוקהולם"},{"i":24111,"n":"יעקובזון, אליהו ממיטאוי","f":"דוד יחזקאל ממיטאוי","dt":"תריד - יב אלול","b":"חתן ר חיים חייקל. רב בוינדאוי, שאבילן, מיטאוי על מקום ר ישראל פרידמן (שנבחר לכהן לפניו - על מקום אביו ר דוד יחזקאל)."},{"i":24112,"n":"יעקובזון, אפרים יעקב ממיטאוי","f":"ישראל מליסא","dt":"תקצא","b":"מו\"ץ במיטאוי."},{"i":24113,"n":"יעקובזון, בן ציון יוסף","f":"יעקב","b":"חתן ר אריה ליב ולפרט מגרינקישק. ר\"מ בניעזין-פלך צרניגוב-תרע."},{"i":24114,"n":"יעקובזון, בנימין זאב","bt":"תרנד","dt":"תשלג - כב סיון","b":"רב פעלים לחזוק היהדות,רב בקופנהגן-תרצ\"ז,עלה לירושלים"},{"i":24115,"n":"יעקובזון, בנימין זאב","bt":"1861","bp":"וילנא","dt":"1918","dp":"מוסקבה","b":"עו\"ד בסלונים ועסקן ציוני. ציר בדומה. חבר ועדת החקירה שנשלחה ע\"י הדומה לביאליסטוק לחקור את הפרעות שנערכו שם, והאשים בנאום בסיים את הצבא בשותפות בפרעות. חתם על מנשר ויבורג ונידון למאסר. השתתף בועידה הציונית בפטרבורג."},{"i":24116,"n":"יעקובזון, דוד מליובאוויטש","f":"בן ציון","bt":"תריב","b":"רב בליובוויטש(=ליובאוויטש)-תרמב. בנו ר יוסף חיים מבויגאמליא."},{"i":24117,"n":"יעקובזון, יוחנן מליבאוי","dt":"תרנג","b":"גביר בליבאוי, הניח בצוואתו כסף לת\"ת."},{"i":24118,"n":"יעקובזון, יוסף חיים מבויגאמליא","f":"דוד מליובאויטש","b":"חתן ר שאול בלוך מקובליץ. רב בבוגמאליא(=לוקאמליע)-תרע."},{"i":24119,"n":"יעקובזון, יוסף מאיר מבוסטון","f":"ישעיה יעקב","k":"בעל יסוד השבת","bt":"תרמ","bp":"קאלנע-פלך לומזה","b":"תלמיד ישיבות ראדין, נוברדוק, כולל וילנא אצל ר חיים עוזר גרודזינסקי. נסמך מאת: ר שלמה הכהן מוילנא, ר בנימין אנטיקאלער. חתן ר שמואל אידל-שלאפאבערסקא מזאסלע. היגר לארה\"ב וכיהן כרב בקהלת \"בני יעקב\" בסעלעם-תרסד, ניו-בדפורד-תרסז, חזר לסעלעם, בוסטון-תשד, יסד ביכנ\"ס \"אפריון\". יסד חברה \"יסוד השבת\", וחיבר ספר באותו השם. תרגם לאידיש \"צפית לישועה\" לחפץ חיים עם תוספת ממנו בשם \"שופר של משיח\". חבר אגודת הרבנים באמריקה, ותנועת \"אגודת ישראל\"."},{"i":24120,"n":"יעקובזון, יחזקאל מקליקול","dt":"תרסה - ג טבת","dp":"קליקול","b":"מחכמי קליקול. חתנו - ר יהודה הירשנזון מפרוינבורג."},{"i":24121,"n":"יעקובזון, יעקב מגריווא","f":"אברהם","b":"מחכמי גריווא, יסד ביכנ\"ס בגריווא-תקצא, עם ר שמריה הלרמן."},{"i":24122,"n":"יעקובזון, יצחק","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":24123,"n":"יעקובזון, ישראל","bt":"תקכח","bp":"הלברשטט","dt":"1828","dp":"ברלין","b":"גביר בברוינשוייג. חתן ר הרץ שמשון מברוינשוייג, בנקאי הנסיך על מקום חותנו. הקים בי\"ס משותף ליהודים ונוצרים, ולידו בית כנסת, ודרש בו בלשון אשכנז (כנראה הדרוש הראשון בלשון אשכנז). פנה במכתב אל נפוליאון בנוגע למצב היהודים ואולי הוא שעורר את נפוליאון להקמת הסנהדרין-1807. מראשי הקהל בזמן נפוליאון. עבר לברלין."},{"i":24124,"n":"יעקובזון, מאיר דוב","b":"רב הקהלה החקלאית - נאווא-פלטובקה(=נאווא-פאלטאייקא)-פלך חרסון-תרם."},{"i":24125,"n":"יעקובזון, מנחם מהמבורג","dt":"תרסו","dp":"המבורג","b":"תלמיד בימ\"ד ר מתתיה עלזאס בהמבורג על מקום ר ליב אדלר."},{"i":24126,"n":"יעקובזון, משה יצחק מארה\"ב","f":"ישכר","bt":"תרמט","bp":"לומזה","b":"תלמיד ישיבות מאלטש, ראדין, ר משה לנדינסקי. נסמך מאת: ר יהודה ליב גורדון, ר יצחק טיקוצינסקי. רב בגאטש-פלך לומזה-תרעח, היגר לארה\"ב-תרפא וכיהן כרב בקהלת \"חבת ירושלים\" בקליבלנד-תרפא, סירקוז-תרפג. חבר אגודת הרבנים באמריקה, ותנועת המזרחי."},{"i":24127,"n":"יעקובזון, משה מגנעזן","f":"ישכר יעקבזון מהמבורג","bt":"תריג","bp":"המבורג","dt":"תרץ","dp":"המבורג","b":"תלמיד השב\"ס, ור יצחק דב במברגר מוירצבורג. חתן ר מרדכי עמרם הירש מהמבורג. רב בשרים-תרמב, גנעזען-תרמט."},{"i":24128,"n":"יעקובזון, משה מהזנפוט ותל אביב","f":"יצחק","bt":"תרלח","bp":"טאלסען","dt":"תשיג","b":"רב בהאזנפוט-קורלנד-תרסח על מקום ר יוסף רבינוביץ, עלה לארץ והתישב בתל אביב-תרפד."},{"i":24129,"n":"יעקובזון, ש' מירושלים","b":"עורך \"מוריה\" - ירושלים תשג."},{"i":24130,"n":"יעקובזון, שלמה מלבוב","f":"ישראל מקראקא","k":"בעל שירי שלמה","dt":"תרכו - טו אדר","dp":"קובנא","b":"חתן הגביר ר יואל בן בנימין ולדנברג. ממשכילי לבוב. נפטר בביקורו בליטא."},{"i":24131,"n":"יעקיל מלמד מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":24132,"n":"יעקיליש, צבי הירש מרוזניאטוב","b":"רבה של רוזניאטוב."},{"i":24133,"n":"יערוויץ, משה","k":"חותן החתם סופר","b":"רב בפרוסטיץ-תק\"מ"},{"i":24134,"n":"יפאר ענוים - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה בידי האחים יוסף, רפאל ואברהם בני משה פרנקו מליוורנו."},{"i":24135,"n":"יפה - משפחה","b":"לדברי ר יוסף כהן צדק בעל \"שבת אחים\", מקור המשפחה בר יוסף יפה פרנס קהילת פרג, בניו: ר יצחק שעבר לקושטא - אביו של ר שמואל יפה בעל \"יפה תואר\", ר אברהם אביו של ר מרדכי בעל הלבושים, ור משה דיין בקראקא בעל \"סדר גיטין\" וזקנו של הב\"ח."},{"i":24136,"n":"יפה אשכנזי, יצחק מברוסה","f":"[יוסף מפרג]","bt":"רל","dt":"שיט - סיון","b":"גביר בעל חסד מחכמי ברוסה. עקב עלילה נידון לשרפה אך ניצל, עלה לארץ ונאלץ לחזור. בניו ר יהודה - נפטר שלו, ור שמואל בעל יפה תואר - מפרש המדרשים."},{"i":24137,"n":"יפה אשכנזי, שלמה מאזמיר","f":"יעקב-יעקב סלה","k":"בעל אשר לשלמה","b":"רב באזמיר, בזמן ר אברהם פלאג'י."},{"i":24138,"n":"יפה זוטא, ישראל משקלוב","f":"אהרן יפה","b":"מגדולי חכמי שקלוב-תקל\"ד"},{"i":24139,"n":"יפה, אברהם","b":"אביו של בעל הלבושים. תלמיד ר אברהם בן אביגדור מפרג. יש אומרים שאביו הוא ר אליעזר בן אברהם בן יוסף נכד ר משה יפה הראשון, וי\"א שהוא בנו של ר יוסף יפה בן אליעזר בן אברהם בן משה יפה."},{"i":24140,"n":"יפה, אברהם","f":"צבי","k":"בעל משנת אברהם","b":"בניו - ר מרדכי צבי מזיטומיר ור יהושע זלמן הו\"ל את ספרו \"משנת אברהם\" - זיטומיר תרכח."},{"i":24141,"n":"יפה, אברהם אבלי מוקשנא","f":"ישראל מיאנישוק","k":"בעל אגרת הפורים-כת\"י","bp":"יאנישוק","dt":"תקף","b":"מצאצאי ר מרדכי יפה בעל הלבושים. רב בואקשנה, פוניבז, מיטאוי(=לוטובה) ובנו ר שבתי על מקומו אחריו בואקשנה, פוניביז ומיטאו. חיבר גם \"בית ישראל\", ברכת אברהם\", ועוד. בנו ר יצחק מואקשנה וירושלים, ור ידידיה מבויסק-קורלנד. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":24142,"n":"יפה, אברהם אבלי מראסיין","f":"שמואל מוילנא","dt":"תרסב - כא אד\"א","dp":"ראסיין","b":"רב מטעם מראסיין והגליל כ-38 שנה ור דב מנשה אברמוביץ על מקומו אחריו. אחיו - ר ישראל פיעסקער מחרסון."},{"i":24143,"n":"יפה, אברהם אברל","f":"פרץ בן מרדכי בעל הלב"},{"i":24144,"n":"יפה, אברהם אליהו מירושלים","f":"אהרן","bt":"תרכד","bp":"ירושלים","b":"שליחא דדיינא."},{"i":24145,"n":"יפה, אברהם יהושע מארה\"ב","b":"תלמיד ר יונתן מזעלובא, ישיבת וולוזין, וילנא ונתמך בידי הגביר ר עקיבא בלטרמנץ. ד\"ר לפילוסופיה מאוניברסיטת ברלין. היגר לארה\"ב וכיהן כראש מורי התלמוד בביהמ\"ד לרבנים - שכטר בניו יורק."},{"i":24146,"n":"יפה, אברהם מבוהמיה ופולין","b":"רב על כל מדינות בהמן ופולין-ר\"ס"},{"i":24147,"n":"יפה, אברהם מוילקומיר","f":"עזריאל הכהן","k":"בעל שרשי הגר\"א","b":"מחכמי וילקומיר. הניח חדושים בכת\"י - ואבדו בזמן מלחה\"ע ה-I. חיבר \"שרשי הגר\"א\" ובו ליקוטים מכתבי הגר\"א ותלמידיו בעניני דקדוק ולשון, הספר אבד - נזכר אצל אחיו ר צבי הירש בעל \"כתר כהונה\". בנו ר יעקב ישראל ממנצסטר בעל \"כנסת ישראל\"."},{"i":24148,"n":"יפה, אברהם מירושלים","f":"נתן","b":"בשנת תקכג חתום עם רבני ירושלים על פניה לחכמי מיץ. אחיו - ר מרדכי מירושלים."},{"i":24149,"n":"יפה, אברהם מניקלשבורג","f":"מרדכי - בעל הלבוש","dt":"תז","dp":"ניקלשבורג","b":"אב\"ד ניקלשבורג. (והוא כנראה טעות והכוונה לנכד בעל הלבוש ולא היה בניקלשבורג - לקורות היהודים בלובלין)."},{"i":24150,"n":"יפה, אברהם ניסן מוילנא","f":"רפאל דב","k":"בעל ביכורי ניסן","b":"מחכמי וילנא."},{"i":24151,"n":"יפה, אברהם עבר מלאזדי","f":"שלום שכנא","k":"בעל מחזה אברהם","bt":"תקפג","bp":"קידאן","dt":"תרסז-עא","b":"רב בראגולה, לאזדיי ובנו ר יהודה ליב על מקומו אחריו, סובאלק."},{"i":24152,"n":"יפה, אהרן","f":"מרדכי מלכוביץ","dt":"תקסו - ג שבט","b":"חתן ר אשר מסטולין. נפטר בחיי אביו."},{"i":24153,"n":"יפה, אהרן דוד מקאשדור","dt":"תש","b":"תלמיד בכולל סלובודקה. רב בקאשדור. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב."},{"i":24154,"n":"יפה, אהרן מאומן","f":"ישראל משקלוב","b":"בנו - ר ישראל זוטא."},{"i":24155,"n":"יפה, אהרן מאומן","f":"אפרים גאון מפרג","b":"רב באומן(אוקראינה). בניו - ר ישראל משקלוב בעל \"אור ישראל\", ר אפרים מפרג. מצאצאי משפחות מנדלך וקלמנקש (מלבוב?)."},{"i":24156,"n":"יפה, אורי פיבוש מאיטליה","f":"משה","b":"מחכמי איטליה-ש'."},{"i":24157,"n":"יפה, אלחנן הלוי מארה\"ב","k":"בעל שאילת שלום","b":"רב בסט לואיס, ניו יורק."},{"i":24158,"n":"יפה, אליהו","b":"מחכמי איזמיר"},{"i":24159,"n":"יפה, אליהו ישכר מיאנובה","b":"מו\"צ ביאנישוק-ליטא."},{"i":24160,"n":"יפה, אליהו שמואל משובאץ","f":"מרדכי אריה","dt":"תרנד","b":"בקי בקבלה. רב בשובאץ על מקום אביו כ-43 שנה. חתנו ר משה רבינוביץ מפסוואל ר\"מ בשובאץ ועל מקום חותנו אחריו-תרנד. ציוה שלא לכתוב על מצבתו שום תואר. חתנו גם - ר משה משובאץ (חתן שני באותו השם)."},{"i":24161,"n":"יפה, אליעזר ממנטובה","f":"משה","b":"מחכמי מנטובה-רצא, עם חבריו ר קלמן ור משה סגל. תשובה מהם בשו\"ת מהר\"ם פאדובה."},{"i":24162,"n":"יפה, אליעזר מפרג","f":"אברהם","b":"מחכמי פרג-ר'. אביו של ר יוסף ויש אומרים אביו של ר אברהם אביו של בעל הלבוש."},{"i":24163,"n":"יפה, אליעזר משה","b":"מו\"צ בדאבאש-תרל\"ו"},{"i":24164,"n":"יפה, אפרים מפרג","f":"אהרן מאומן","b":"רב בפרג. אחיו של ר ישראל משקלוב בעל \"אור ישראל\"."},{"i":24165,"n":"יפה, אריה ליב","b":"מקובל,מג\"מ בזוואניץ"},{"i":24166,"n":"יפה, אריה ליבוש מנמירוב","f":"דוד יפה-ולרשטין","b":"חתן ר יעקב ריינמן מנרול. רב בנמירוב-תקמב, הולשיץ-תקן. הגהותיו בשולי שו\"ע מהדורת למברג תקפט."},{"i":24167,"n":"יפה, בצלאל מתל אביב","f":"דב","bt":"1868","bp":"גרודנא","dt":"1926","dp":"תל אביב","b":"נכד ר מרדכי גימפל יפה מרוז'נוי. תלמיד ישיבות ליטא. עסקן חובב ציון בגליל גרודנא. יסד בגרודנא \"חדר מתוקן\". ביקר בארץ-1903 עם אוסישקין, דרוינוב ועוד. עלה לארץ-1909. ניהל עם דיזנגוף את הועד הזמני ליהודי א\"י בזמן מלחמ\"ה ה-I.."},{"i":24168,"n":"יפה, ברוך הקראי מקושטא","b":"מראשי עדת הקראים בקושטא-ת'."},{"i":24169,"n":"יפה, ברוך מטוואר","dt":"תשג","b":"רבה האחרון של טווער(=טוואר). נספה בשואה."},{"i":24170,"n":"יפה, דב בר טורטשר מטוריץ ואוטי","f":"יעקב מקרליץ","k":"ר בעריל קארעליטשער","dt":"תקפט - טו שבט","dp":"וילנא","b":"אחיין האדמור מטשרנוביץ. תלמיד ר חיים מוולוזין. מ\"מ ומו\"צ בקרליץ, ליובטש(=לובצי), טוריץ, אוטיאן. חברם של ר יעקב מקרלין בעל \"משכנות יעקב\", ר דוד טבלי ממינסק בעל \"נחלת דוד\", ר יוסף מסלוצק, ור יוסף זונדל מסלנט וירושלים. רבו-ר חיים מוולוזין אמר עליו כי הוא \"נורא כאחד מהראשונים בסברא והלכה\". חיבר חדושים לסדר מועד, ועל התנ\"ך. בניו - ר מרדכי גימפל מראזאני, ר יוסף יהושע מטאריגען(=טארגין), ר יעקב מאוטיאן, ר חיים זלמן מירושלים. חתנו - ר נחום הכהן קוק - זקנו של ר הראי\"ה קוק."},{"i":24171,"n":"יפה, דב בר מפלונגיאן","b":"ממשפחת הגר\"א (מכנהו בכתביו - דודי). תלמיד ר יהונתן משה דב וואלינר. רב בדאברזין(=דווארזין), פלונגיאן-תרי. חיבר כתבים רבים ורובם אבדו ונשאר חיבור על הירושלמי (ונדפס בחלקו בקובץ \"נר מערבי\"). מתורתו ב\"מגן שאול\" לר שאול קצנלנבוגן משילעל. החזיק בכתב היד של ספר רבו \"מרגניתא טובא\" וממנו הדפיסו ר ישראל מאיר הכהן בעל ה\"חפץ חיים\"."},{"i":24172,"n":"יפה, דוד אהרן מקושידאר","dt":"תש..","b":"רבה האחרון של קושידאר. נספה בשואה."},{"i":24173,"n":"יפה, דוד טבל מקראקא","f":"יעקב","k":"בעל ויקונן דוד","bt":"תקפט","bp":"בריגל","dt":"תרס","b":"רב בקראקא, חתנו ר מרדכי ליב קלין על מקומו אחריו. חיבר \"ויקונן דוד\" קראקא תרנב."},{"i":24174,"n":"יפה, דוד מארץ ישראל","b":"בשליחות קהילת החסידים-תקסו בצפון אפריקה."},{"i":24175,"n":"יפה, דוד מדרהוטשין","b":"רב בדרהוטשין"},{"i":24176,"n":"יפה, דניאל איציג מברלין","dt":"תקנט - טז אייר","b":"ראש הקהל בברלין-תקמ יחד עם גיסו הגביר ר איזיק דעסוי בן שמחה בונם. יסד בית ספר מתוקן בשם \"בית חנוך נערים\" והקים בית דפוס לצדו. היו לו ארבע בנים ו-9 בנות ומהם: בנו ר יצחק איצק, וחתנו דוד פרידלנדר."},{"i":24177,"n":"יפה, זאב וולף מגורזד","f":"יוסף משוואקשנא","b":"אב\"ד גורזד."},{"i":24178,"n":"יפה, חיים אבא","f":"אשר צבי מרוסטוב","k":"בעל יפה לבשמים","b":"עלה לארץ והתישב בחיפה.","bk":[["יפה לבשמים","שו\"ת ודרשות"]]},{"i":24179,"n":"יפה, חיים זאב וולף משקוד","f":"צבי הירש משקוד","dt":"תרכט - כא אייר","dp":"שקוד","b":"רב בראסיין, אב\"ד בשקוד."},{"i":24180,"n":"יפה, חיים חייקל מירושלים","f":"אריה ליב מפריאסלוב","dt":"תריז - ב שבט","dp":"ירושלים","b":"מחכמי ירושלים ומראשוני הגבאים של \"עץ חיים\" בשנת תרטו, חתם על תקנת המשמורים-תריב, וחתם על כתב שליחות ר\"ז וולפנהאוזן."},{"i":24181,"n":"יפה, חיים יוסף","k":"המגיד מואקשנה","bt":"1821","bp":"זאגר חדש","dt":"1901","dp":"ירושלים","b":"מטיף ציוני שנדד ברחבי רוסיה למען ישוב הארץ. עלה לארץ-תרנג והתישב ברחובות, והמונים נקהלו לשמוע את דרשותיו."},{"i":24182,"n":"יפה, חיים מרדשקוביץ","f":"שמואל","k":"בעל שנות חיים","b":"מחכמי רדושקביץ"},{"i":24183,"n":"יפה, חיים שלמה","bt":"1884","bp":"ליטא","dt":"1936","b":"תלמיד ישיבת סלובודקה. היגר לדרום אפריקה והיה מראשי התנועה הציונית. עלה לארץ-1928 ויסד את \"גן רוה\" ליד נס ציונה."},{"i":24184,"n":"יפה, חנוך זונדל מאלינקה","f":"מרדכי ר זונדל מוילקו","b":"רב באלינקה-תק\"ל. בנו ר פנחס מקלוואריה. חתנו ר אברהם מסערהיי(117)."},{"i":24185,"n":"יפה, חנוך זונדל מקאלווריה","f":"פנחס מקלוואריה","b":"רב בקאלוואריע(=קלוואריה)."},{"i":24186,"n":"יפה, טוביה מאמדור וטיקטין","f":"מרדכי יפה","b":"רב באמדור,מו\"צ בטיקטין-תקכ\"ט"},{"i":24187,"n":"יפה, ידידיה מבויסק","f":"אברהם אבלי מואקשנה","b":"חתנו - ר חיים אהרן שפר מבויסק, ונכדו ר אבא שבתי מבולטימור-ארה\"ב."},{"i":24188,"n":"יפה, ידידיה מלייפניק","b":"תלמיד דודו זקנו בעל התניא."},{"i":24189,"n":"יפה, יהודה אריה ליב","f":"מרדכי יפה הלבוש","bt":"שטו","dt":"שפ"},{"i":24190,"n":"יפה, יהודה ליב מלאזדי","f":"אברהם עבר מלאזדי","k":"בעל אבן לב","bt":"תרכב או תרב","bp":"קידאן","b":"רב בלאזדי-פלך סובאלק-תרסח על מקום אביו (ולפי \"ליטא\" - סירב לרבנות על מקום אביו)."},{"i":24191,"n":"יפה, יום טוב מניקלשבורג","f":"אברהם אברל יפה","b":"רב בניקלסבורג-ת\"מ"},{"i":24192,"n":"יפה, יוסף זונדל מפלונגיאן","b":"נכד ר טוביה מטיקטין, ובעל הלבוש. רב בפלונגיאן-תפ. בנו - ר מרדכי(13848)."},{"i":24193,"n":"יפה, יוסף חיים מארה\"ב","k":"בעל לידער - נ\"י 1914","bt":"1866","bp":"סלנט","dt":"1938","b":"ממשפחת ר מרדכי יפה בעל הלבושים. היגר לארה\"ב-1892 ופרסם שירים ב\"ארבייטער צייטונג\", וב\"צוקונפט\". חיבר גם \"זעזאנגען\" נ\"י 1936."},{"i":24194,"n":"יפה, יוסף חיים מחברון ויפו","f":"דוד ליב","k":"בעל מאור של תורה","bp":"חברון","b":"מחכמי ירושלים, יפו."},{"i":24195,"n":"יפה, יוסף יהושע מטארגין","f":"דב בר מאוטיאן","b":"רב בטארגין-ליד אוטיאן. נזכר ב\"נחלת אבות\"."},{"i":24196,"n":"יפה, יוסף מוילנא","f":"אליעזר ליפמן","k":"בעל סדר הניקור","b":"שו\"ב בפאדברעזא, וילנא."},{"i":24197,"n":"יפה, יוסף מסלונים ומנצסטר","f":"משה מגורזד","k":"בעל יוסף ביאור","bt":"תרה","bp":"וילקומיר","dt":"תרנח - ל סיון","dp":"מנצסטר","b":"רב בסלונים, פוקרוי-תרלד, סלנט, גורזד-תרמט. הגיע לאנגליה וכיהן כרב במנצסטר-תרנג, והיה פעיל בתנועת חו\"צ. חיבר גם \"עלים לתרופה\", \"אהבת ציון וירושלים\".","bk":[["פתחי דין",""]],"e":"תר\"ה-תרנ\"ח"},{"i":24198,"n":"יפה, יוסף מקושטא","f":"שמואל","b":"רב ורופא בקושטא-שנות ה-ש', חתם עם רבני קושטא על הסכמה ל\"יפה תואר\" לאביו, וחיבר שיר לכבוד הספר. תשובה ממנו בשו\"ת ראנ\"ח. היה מחלוקת כנגד מינויו לרב-שנג מאת הפרנס ר מנחם קאלמאני, ור יוסף טרני פסק לטובתו."},{"i":24199,"n":"יפה, יוסף משוואקשנא","f":"משה משוואקשנא","b":"אב\"ד שוואקשנא. בניו - ר צבי הירש משקוד, ר זאב וולף מגורזד."},{"i":24200,"n":"יפה, יחזקאל אשר","f":"לייב","bt":"1858","bp":"רוגובה","dt":"1910","dp":"וארשא","b":"חתן הגביר ר בנימין נטע ריבלין מסובאלק, גיסו של ר אליעזר שמחה רבינוביץ מקאלואריה. עבר לקובנא ועסק בלימוד תורה והיה מחשובי העסקנים בקובנא. גבאי במוסדות צבור רבים. ביתו היה מקום כינוס לחכמים ולרבנים. חתנו ד\"ר ה. י. עציון (הולצברג)."},{"i":24201,"n":"יפה, יחיאל מיכל מוישינטה","f":"הלל יפה","dt":"תרנט","b":"רב בוישינטה-תרלב."},{"i":24202,"n":"יפה, יעקב מלידוינוב","f":"פנחס בן חנוך זונדל","k":"בעל גופי הלכות","b":"חתן ר שמואל מקרלין ואנטפאליא. רב בלידווינוב(=לודוינאוי)-תקס. בניו - ר חנוך זונדל יפה-גרודזנסקי, ר מרדכי צבי גרודזנסקי."},{"i":24203,"n":"יפה, יעקב מקוברין","f":"ישעיה יפה","b":"רב בקברין-תר\"כ"},{"i":24204,"n":"יפה, יעקב משקוד","f":"חיים זאב וולף משקוד","b":"רב בשקוד-תרנב, גאוורי-פלך קובנא."},{"i":24205,"n":"יפה, יעקב שמואל","f":"יחיאל שלזינגר","b":"רב-שנת תר\"ל"},{"i":24206,"n":"יפה, יעקב שמואל","f":"ישראל","bt":"1886","bp":"קופישוק","dt":"1963","dp":"חיפה","b":"פעיל במחתרת המהפכנית, הגיע לארה\"ב-1907 ולמד בבית ספר חקלאי מיסודו של הברון הירש ופגש תלמידים מארץ ישראל והפך לציוני. הפך למומחה בתחום חקר הקרקע ועמד בראש הקולג' החקאלי בניו ג'רסי על מקום ד\"ר גדליה ליפמן. ביקר בארץ-1935 ועוד. פרסם מאמרים רבים בנושאי הקרקע ובנושאים יהודיים. מראשי המגבית של האיגודים המקצועיים בארה\"ב למען ישראל."},{"i":24207,"n":"יפה, יצחק","f":"מרדכי מלכוביץ","b":"לא כיהן כאדמור."},{"i":24208,"n":"יפה, יצחק","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":24209,"n":"יפה, יצחק איצק מברלין","f":"דניאל מברלין","b":"בנו של ראש הקהל מברלין. חברו וגיסו של דוד פרידלנדר ומקורבים למשה מנדלסון, סייעו בהדפסת \"מצפה יקותיאל\" - שהפצתו נאסרה בידי ביה\"ד באה\"ו - שם כיהן ר רפאל הכהן שכנגדו פנה הספר."},{"i":24210,"n":"יפה, יצחק מאופינע","dt":"תשג","b":"רב באופינע"},{"i":24211,"n":"יפה, יצחק מאזמיר","f":"שמואל","b":"דיין באזמיר-שעז ונזכר בשו\"ת מהריט\"ץ, הו\"ל את ספרי אביו, ובנו ר מנחם קיבל את כתבי סבו מאביו, והדפיס מהם \"יפה עינים\" עם הקדמה."},{"i":24212,"n":"יפה, יצחק מאניפולה וירושלים","f":"זליג","dt":"תרסח","dp":"ירושלים","b":"רב באניפולה, עלה לירושלים."},{"i":24213,"n":"יפה, יצחק מדרויא וירושלים","b":"מחכמי ירושלים."},{"i":24214,"n":"יפה, יצחק מואקשנה וירושלים","f":"אברהם אבלי מואקשנה","dt":"תרכג - א שבט","dp":"ירושלים","b":"חוקר, מהנדס, מחכמי ירושלים."},{"i":24215,"n":"יפה, יצחק ממאגניסיאה","b":"רב במאגניסיאה-שנות ה-ת'."},{"i":24216,"n":"יפה, ישעיה","f":"דוד יפה"},{"i":24217,"n":"יפה, ישעיה","f":"הלבוש","b":"מגדולי דורו-שנת ת'"},{"i":24218,"n":"יפה, ישעיה מהמבורג","f":"נחמיה","k":"ישעיה ברעסלא","bp":"ברסלוי","dt":"תקלד - א תשרי","dp":"אלטונא","b":"חתן ר ברוך בנדיט מאניש מהמבורג. ר\"מ, ראב\"ד באה\"ו-תד על מקום חותנו, וממלא מקום הרב על מקום ר דוד ברלין (שאחר פטירתו לא מונה אב\"ד) עד למינוי ר יונתן איבשביץ, ועמד לצדו בזמן המחלוקת עם היעב\"ץ והיה בשלום גם עם היעב\"ץ."},{"i":24219,"n":"יפה, ישראל יעקב הכהן מאנגליה","f":"אברהם בן עזריאל ואלק","k":"בעל כנסת ישראל","bt":"תרלד","bp":"וילקומיר","dt":"תרצד - כג אייר","dp":"אלכסנדריה - ירושלים","b":"נכד ר עזריאל הכהן ואלק (אביו שינה שמו ל\"יפה\" להימנע מגיוס לצבא). תלמיד ישיבות טלז וסלובודקה וכונה \"העילוי מוילקומיר\", תלמיד ר חיים יהודה ליב סוסניצר מסמרגון, ר יונתן אליאשברג מולקוביסק, דודו ר מנחם מנדל ואלק מולקוביסק, כולל קובנא. חתן ר אבא יעקב בורוכוב בעל \"חבל יעקב\". רב במנצסטר-תרנז ויסד ישיבה. חבר ה\"מזרחי\" וציר בקונגרס הציוני. חיבר גם \"הדרת ישראל\", ועוד. נפטר בדרכו לארץ במצרים. (באוצר מופיע פעמיים - וב-12233 מופיע כחתן ר יוסף יפה וכבנו של ר עזריאל ולק). פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב, \"המגיד\" - סטמר תרפח, \"שערי ציון\" - ירושלים תרפא. נסמך מאת: ר אליעזר גורדון מטלז, ר צבי הירש רבינוביץ מקובנא, ר יהודה ליפשיץ בעל \"דרך אמונה\"."},{"i":24220,"n":"יפה, ישראל מבלז","f":"שניאור זלמן","bt":"תריח","b":"רב בבלז-בסרביה-תרמח."},{"i":24221,"n":"יפה, ישראל מחברון","b":"ראש חבורת העולים מחסידי חב\"ד לחברון-תקפג, עלו עמו בניו ר אפרים, ר מרדכי ור משה."},{"i":24222,"n":"יפה, ישראל מלאזני","f":"חיים","k":"בעל שארית ישראל","b":"חסיד חב\"ד. רב בלאזני. נכדו - ר ישראל בן שניאור זלמן אהרן - הו\"ל את ספרו, והוסיף לו את תולדות המחבר."},{"i":24223,"n":"יפה, ישראל משקלוב","f":"אהרן מאומן","k":"בעל אור ישראל","bp":"אומן","dp":"פפד\"א","b":"עבר מאומן (מקום רבנות אביו) לאחר פרעות תח, למד בהלוסק, מקובל, רב בשקלוב-תכח. היה בחבורה עם ר אריה ליב אפשטין, ור יעקב חיים - להתחזק בעבודת השם. חיבר ספרים כדי לתקן את עם ישראל ולקרב את הגאולה ובהם \"אור ישראל\" - והיה מחלוקת כנגדו מצד שחשדוהו בשבתאות. נכדו - ר ישראל המכונה זוטא (להבדילו מזקנו) הו\"ל קיצור מספרו בשם \"תפארת ישראל\" ובו מביא בשם זקנו שדברי השבתאות שנכנסו לספרו הוכנסו בידי אחרים ולא מידיו. מאמר עליו מאת דוד כהנא ב\"השחר\" בשם \"אבן אפל\"."},{"i":24224,"n":"יפה, לואי נתנאל","bt":"1883","bp":"שקוד-ליטא","dt":"1944","dp":"ניו יורק","b":"עורך דין. היגר לארה\"ב-1899 והיה נשיא חברת סרטים וחבר ביה\"ד העירוני של ניו יורק. פעיל במוסדות חסד תרבות ודת."},{"i":24225,"n":"יפה, ליב","f":"דב","k":"בעל תקופות - תשח","bt":"1876","bp":"גרודנא","dt":"1948","b":"ציר בקונגרס הציוני, פעיל ובעזרה לפליטים בזמן מלחמ\"ה ה-I בוילנא. עורך \"יאוורייסקאיה ז'יזן\"יו\"ר ההסתדרות הציונית במוסקבה. חזר לוילנא וערך את \"לעצטע נייס\". נאסר-1919 ע\"י הפולנים שכבשו את וילנא יחד עם חבריו וייטנר וניגר, הפולנים הוציאו להורג את וייטנר, והוא וניגר שוחררו לאחר השתדלות עסקנים יהודים. עלה לארץ-1919. בשליחות \"קרן היסוד\" לארצות שונות, והיה אהוב במיוחד על המוני היהודים בפולין, ליטא ועוד. נהרג בפיצוץ בירושלים. עורך ספר הקונגרס-תרפג."},{"i":24226,"n":"יפה, ליב חיים","bt":"1894","bp":"קובנא","dt":"1941","b":"התפרסם בילדותו כעילוי. מפקח על בתי הספר של אורט ברוסיה בזמן מלחמ\"ה ה-I. מורה בגימנסיה העברית בקובנא. פרסם מאמרים, ספרי לימודבאידיש ובעברית. נספה בשואה."},{"i":24227,"n":"יפה, מיכאל","f":"יצחק","bt":"תרכו","dt":"תרעט","b":"לזכרו \"מיכאל השר הגדול\" מאת דוד דב דוידוביץ."},{"i":24228,"n":"יפה, מיכל מוישינטא","dt":"תרס","b":"רב בווישינטא"},{"i":24229,"n":"יפה, מנחם","b":"רב-שנת תק\"ע"},{"i":24230,"n":"יפה, מנחם","f":"יצחק","b":"נכד ר שמואל בעל \"יפה תואר\", החזיק בכתבי זקנו, והדפיס \"יפה עינים\" עם הקדמה ממנו."},{"i":24231,"n":"יפה, מנחם נחום מהורדנא","f":"בנימין מיכל","k":"בעל תשובת מהר\"ן יפה","dt":"תרלה - כז תשרי","b":"תלמיד ר אליהו רגולר. מו\"צ בהורדנא.","bk":[["שו\"ת מהר\"ן יפה",""]]},{"i":24232,"n":"יפה, מנחם נחום מקאפוסט","b":"אחד משלשה אחים שותפים מדפסים בקאפוסט, חסידי בעל התניא."},{"i":24233,"n":"יפה, מרדכי אריה משובאץ","b":"רב בשובאץ-ת\"ר, ובנו ר אליהו שמואל על מקומו אחריו."},{"i":24234,"n":"יפה, מרדכי אשכנזי מירושלים","f":"נתן","bp":"פולין","b":"עלה לארץ ישראל דרך מצרים, ושם רכש כתבי יד רבים, בשנת תקי יצא לקושטא להדפיס כתבי יד ובדרך עבר בארם צובא ובבגדד. הדפיס חדושים על מסכת קדושין לאחד הראשונים קושטא תקיא. בשנת תקכג חתום על בקשת עזרה מקהילת מיץ. אחיו - ר אברהם מירושלים."},{"i":24235,"n":"יפה, מרדכי גימפל מרוזינוי","f":"דב בר מאוטיאן","k":"בעל זכרונות מרדכי","r":"אב\"ד רוז'ינוי ויהוד","bt":"תקף","bp":"אוטיאן (ליטא)","dt":"תרנב - כה חשון","dp":"פתח תקוה","b":"לאחר שנתייתם גדל אצל דודו ר יצחק יהושע-דיין במיר וראש ישיבת סלונים, ולמד עם גיסו ר נתן נטע לוריא מקרקנוביה. מצאצאי ר מרדכי בעל הלבוש. תלמיד ר חיים מוולוזין - אחד מ-10 התלמידים הראשונים בישיבת וולוזין וכונה ה\"עילוי מאוטיאן\". כיהן כרב בדרטשין(=דראצ'ין), רוז'נוי(=ראזנוי) כ-36 שנה וראש ישיבה שם. הגיש תזכיר למונטיפיורי בנוגע למצבם הכלכלי של יהודי רוסיה, התכתב עם הברונים הורץ ודוד גינצבורג בענין הסמינר לרבנים שעמד לקום ע\"י חברת \"מפיצי השכלה\". מראשוני תנועת \"חובבי ציון\" וייסד ברוז'נוי \"חברה לישוב א\"י\". השפיע על מחותנו ר פישל לאפין מגרודנא לעלות לארץ. עלה לירושלים-תרמח והתישב בשכונת מזכרת משה, עבר למושבה יהוד-ליד פתח תקוה עם 8 אברכים מתלמידיו - דבר שעשה רושם בזמנו גם ביישוב בארץ וגם בחו\"ל. היה מנהיג רוחני במושבות החדשות עד לפטירתו. מתלמידיו ר יחיאל מיכל פינס. חיבר יחד עם גיסו ר נתן לוריא מקרקינובה - \"אלף המגן\" ורשה תרעב, ועוד. פרסם מאמרים ב\"הלבנון\" - ירושלים-פאריס תרכג-תרמב, \"תבונה\" - ממל-קניגסברג תרכא. מחותן גם עם ר אפרים ביאליסטוצקי מדרעטשין. בנו - ר יעקב רבינוביץ מלוצין. חתניו - ר יוסף זכריה שטרן משאוויל, ר צבי הירש ואלק מפינסק.","bk":[["תכלת מרדכי",""],["הגדת מרדכי",""],["מבחר כתבים",""],["תכלת מרדכי – רמב\"ן עה\"ת",""]]},{"i":24236,"n":"יפה, מרדכי מזעלוי","b":"רב בזעלוי-תק\"י"},{"i":24237,"n":"יפה, מרדכי מחרקוב","b":"רב בחארחוב-תק\"ע"},{"i":24238,"n":"יפה, מרדכי מיכאל מהמבורג","f":"מנחם","k":"בעל בית מנחם","bt":"תקסג","bp":"קרוטושין-ליד פוזנא","dt":"תרכח - ח אייר","dp":"המבורג","b":"מגדולי תלמידי ר עקיבא איגר (למד אצלו כ-8 שנים). חתן ר דוד מקרוטושין. רב בזאדון-ליד קרוטושין, שמיגל(=שניידמיהל)-ליד פוזנא-תקצד, ר\"מ בקלויז בהמבורג-תרט על מקום ר מאיר האס (כדי ללמוד וללמד ללא עול הרבנות) יחד עם ר אליקים גטשליק שלזינגר (הם היו גם מחותנים), חתנו - ר דוד בן אליקים שלזינגר. חיבר שו\"ת מהר\"מ יפה. הו\"ל שו\"ת \"אור זרוע\", הביא לדפוס \"אור זרוע\" לבקשת ר יהודה רוזנברג.","bk":[["בית מנחם",""],["תשובות מר\"מ יפה",""]]},{"i":24239,"n":"יפה, מרדכי מליטא וניו יורק","k":"בעל אן א זייט - 1927","bt":"1894","bp":"דוסיאט","dt":"1961","b":"אביו היה \"רב מטעם\" בדוסיאט. תלמיד ישיבות ליטא. חיבר שירים ב\"אונער וועגס\", ועוד. חיבר גם מאמרים שונים. היגר לארה\"ב ועסק בספרות ושירה ותרגום באידיש ועברית. עלה לארץ-1953. חיבר גם \"אנטאלאגיע פון דער העברעאישער פאעזיע\" נ\"י 1948."},{"i":24240,"n":"יפה, מרדכי מלכוביץ","k":"אדמור מלכוביץ","r":"ראש ישיבת טלז בארצות הברית","bt":"תקב","dt":"תקע - יג שבט","b":"מצאצאי \"בעל הלבושים\". תלמיד ר שלמה מקרלין ור ברוך ממזבוז. נאסר יחד עם ר שניאור זלמן בעל התניא. נשיא \"כולל רייסין\" על מקום ידידו ר אברהם מקאליסק-שעלה לארץ. מתורתו ב\"אור ישרים\" ו\"תורת אבות\". חתנו ר משה מוילייקא."},{"i":24241,"n":"יפה, מרדכי מפרג","f":"אברהם יפה","k":"בעל הלבושים","bt":"רצ","bp":"פרג","dt":"שעב - ג אד\"ב","dp":"פוזנא","b":"תלמיד המהרש\"ל והרמ\"א, למד קבלה אצל ר מתתיהו בן שלמה דיליקראט. מגדולי הפוסקים ומגדולי חכמי דורו, ראש ישיבת פרג-עד שכא, יצא בראש הגולים בגזירת הגלות של הקיסר פרדיננד והגיע לאיטליה, ושהה כ-10 שנים בונציה, וענעדיג, רב בהורדנא-שלב, לובלין-שמח על מקום המהר\"ם, בהשתדלותו הצטרפה ליטא לועד ג ארצות שהפכה לועד ארבע ארצות. רב בקרמניץ, חזר לפרג-שנב ועל מקומו אחריו המהר\"ל, פוזנא-שנט. נאמר עליו \"ממרדכי עד מרדכי לא קום כמרדכי\". חיבר עשרה ספרים בשם \"לבושים\". בתחילה שיתף פעולה עם ר יוסף בן מנחם ישראל - יוסף הלבן שתכנן להוציא ספר דומה - אולם לאחר מכן הוציא את ספרו לבד. בנו ר אברהם מניקלשבורג, וחתנו - הרופא ר יחיאל מיכל הלוי אפשטין."},{"i":24242,"n":"יפה, מרדכי מקידאן","f":"יוסף(8352)","b":"מצאצאי בעל הלבוש. חתן ר חנוך זונדל(6671). ראש הגליל בקידאן-תקז. בניו - ר חנוך זונדל(6671), ר טוביה(6748)."},{"i":24243,"n":"יפה, מרדכי מראגובה","dp":"ירושלים","b":"גביר בראגאווע(=ראגובה)-פלך קובנא, עלה לירושלים. חתנו - ר פנחס שיק מקוברין."},{"i":24244,"n":"יפה, מרדכי משווערן","b":"רב בשווערן-תקנ. חתניו - ר שמואל זנויל הנובר מהמבורג, ר יעקב בן ברוך עוזר מהמבורג."},{"i":24245,"n":"יפה, משה דב מטראשקין","f":"שלמה דוד","k":"בעל זכרון דוד","b":"מחכמי טראשקין-ליד וילקומיר."},{"i":24246,"n":"יפה, משה יונה משמילג","b":"רב בשמילג-תר\"ל"},{"i":24247,"n":"יפה, משה יעקב מהמבורג","dt":"תקפג","dp":"אלטונא","b":"מחכמי ברלין, דיין בהמבורג אצל ר רפאל הכהן שהביאו מברלין, והיה נציג הקהלה בזמן פירוש קהלות אה\"ו-תקעב, פעל נגד הטמפל הריפורמי-תקעט. הסכים על \"דמשק אליעזר\"."},{"i":24248,"n":"יפה, משה ליב מפרשבורג","dt":"תקפו - יב ניסן","dp":"פרשבורג","b":"חתן ר בנימין וולף טעבן מפרשבורג. מחכמי פרשבורג. חתם על תקנות הח\"ק-תקס, ועל כתב מנוי רבנות לחת\"ס-תקסז. בנו - ר צבי הירש מפרשבורג - מוהל מפורסם."},{"i":24249,"n":"יפה, משה מאזמיר","dt":"תקכג - ג אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":24250,"n":"יפה, משה מגורז'ד","dt":"תרמט","b":"רב בגורזד-תר-תרמה במשך 45 שנה, בנו ר יוסף על מקומו אחריו."},{"i":24251,"n":"יפה, משה מחברון","f":"ישראל","b":"מחכמי חברון, מחסידי חבד, בשליחות חבד במצרים תימן הודו וסין."},{"i":24252,"n":"יפה, משה מפיזשיץ","f":"יעקב מקוברין","bt":"תריח","b":"רב בפיזשיץ(=פישטשאץ)-פלך שדליץ-תרנח. נסמך מאת: ר יוסף רוזין מסלונים, ר טוביה גוטמן מקיעלץ בעל \"ברכת כהן\", ר פתחיה הורנבלום מוארשא. בנו - ר יעקב בן ציון, חתנו - ר אהרן דב הכהן, ר אריה ליבש-נכד השר שלום מבלז."},{"i":24253,"n":"יפה, משה מקראקא","b":"דיין בקראקא-שנת ש'. מצאצאיו בעל הב\"ח. אחיינו - ר יוסף כץ בעל שארית יוסף."},{"i":24254,"n":"יפה, משה מקראקא ואויסא","f":"ישכר","k":"בעל פני משה","b":"נכד ר מרדכי בעל הלבוש. אב\"ד אויסא."},{"i":24255,"n":"יפה, משה משקודוויל ופיקאלן","f":"אליעזר","b":"רב בשקודוויל-תריט עד תרמט, רב בפיקאלן-ליטא-לפני תרמח."},{"i":24256,"n":"יפה, משה צבי מהנובר","dt":"תקנב - יט אדר","b":"מצאצאי בעל הלבוש. אב\"ד שוואקשנא ובנו ר יוסף על מקומו אחריו, אב\"ד וארנא."},{"i":24257,"n":"יפה, נח מלכוביץ","f":"מרדכי מלכוביץ","k":"אדמור מלכוביץ","bt":"תקלד","dt":"תקצג - ח תשרי","b":"תלמיד ר ברוך ממזבוז. פרסום כרוז-תקפא לתמיכה במתישבים בא\"י. מתורתו ב\"אור ישרים\", \"תורת אבות\"."},{"i":24258,"n":"יפה, נחום","b":"רב-שנת תק\"מ"},{"i":24259,"n":"יפה, נחום מירושלים","f":"מאיר","b":"מחכמי ירושלים, בשנת תיז בשליחות באיטליה יחד עם ר יוסף בן מרדכי."},{"i":24260,"n":"יפה, נחמיה מברסלוי","b":"רב בברסלוי-ת\"ק"},{"i":24261,"n":"יפה, נפתלי","b":"מחכמי ארץ ישראל, בשנת תנט בשליחות עם ר עובדיה בן ישכר בר מהלישוי."},{"i":24262,"n":"יפה, נתן נטע מפומפיאן","b":"למדן מופלג בפומפיאן, עסק בעניני צבור ותורה. בנו משה מנהל ביה\"ס במאז'ייק."},{"i":24263,"n":"יפה, פרץ","f":"הלבוש","dt":"תז - כא סיון"},{"i":24264,"n":"יפה, צבי הירש מוארשא","f":"מרדכי גימפל מרוזינוי","bt":"תריג","bp":"אמנסטרישציזנא","b":"מחכמי בריסק ומקורב לר יוסף דב סולוביציק בעל \"בית הלוי\". בקי בחשבון והנדסה. חיבר מאמר ב\"הצפירה\"-1877 אודות סבוב הארץ היומי, ועוד מאמרים רבים בנושאי תכונה וחשבון. הגיע למוסקבה והתפרסם, המציא מכונת חישוב-1882. עבר לוארשא."},{"i":24265,"n":"יפה, צבי הירש משקוד","f":"יוסף משוואקשנא","b":"אב\"ד שקוד. בנו - ר חיים זאב וולף משקוד. אחיו - ר זאב וולף מגארזד."},{"i":24266,"n":"יפה, צבי הרש מפרשבורג","f":"ליב יפה","bt":"תקלט","bp":"פרשבורג","dt":"תרז - אחרי","b":"נכד-אבי אמו - ר בנימין וולף מפרשבורג. מוהל בפרשבורג. חתם על כתב הרבנות של החת\"ס-תקסז, והיה ממקורביו, כשהוצע לחת\"ס רבנות פיורדא-תקף - שכנע את החת\"ס לבל יעזוב את פרשבורג."},{"i":24267,"n":"יפה, קלונימוס מלובלין","f":"מרדכי","b":"מדפיס בלובלין. הדפיס ש\"ס-שלו יחד עם בנו ר חיים."},{"i":24268,"n":"יפה, רפאל מפייזר","f":"יעקב","k":"בעל אור לישרים","b":"מצאצאי בעל הלבוש. דיין בפייזר. חיבר גם \"גולת תחתיות\"."},{"i":24269,"n":"יפה, שאול אלחנן מניו יורק","f":"אברהם","b":"מחכמי ירושלים, דיין בבית דין אשכנזים בשנת תרסז. פרסם מאמרים ב\"המאסף\" - ירושלים תרנו."},{"i":24270,"n":"יפה, שבתי מואקשנה","f":"אברהם אבלי מפוניבז","dt":"תריז - כז כסלו","dp":"ירושלים","b":"אב\"ד פוניבז ומיטאוי על מקום אביו, רב בעיר ואקשנא על מקום אביו 53 שנה - עד תר. חיבר ספרים רבים בכתב יד. מעט תשובות ממנו בספר \"פרי אשל\" של קרובו ר שלום אלחנן לוי. אחיהם של - ר ידידיה מבויסק, ר יצחק מואקנשא. חתנו - ר בן ציון שלעז בעל \"שארית ציון\". (יש רושמים תאריך פטירתו - תריד)."},{"i":24271,"n":"יפה, שלום אלחנן מובולניק וארה\"","f":"שמעון פרץ הלוי","k":"בעל שואל כענין","bt":"תריח","bp":"ואבולניק(=וולבוניק)-ליטא","dt":"תרפד - ז כסלו","dp":"ניו יורק","b":"תלמיד ישיבת וולוזין. רב באופינא-פלך קובנא-תרלט, זיימל-תרמו, באמריקה-תרמט לביקור משפחתו שם, רב בואבולניק-תרן על מקום ר יצחק, עבר לארה\"ב וכיהן כרב בסט לואיס-תרנא, והדפיס שם את ספריו \"שואל כענין\" ו\"שיחה שלמה\", רב בניו יורק. ממיסדי אגודת הרבנים וכיהן כיו\"ר. כשכיהן בסט לואיס היה במחלוקת עם ר זכריה יוסף רוזנפלד שהיה רב שם בענין כתיבת שם העיר בגט - סט \"לואיס\" או \"לואיז\" ושם הנהר מיסיסיפי או מיססיססיפי, ותשובת ר שמואל סלנט ב\"שואל כענין\". פרסם מאמרים ב\"בית ועד לחכמים\" - נ\"י תרסג, \"יגדיל תורה\" - נ\"י תרעו."},{"i":24272,"n":"יפה, שלמה","f":"אברהם","bt":"1894","bp":"גרודנא","dt":"1949","dp":"תל אביב","b":"מצאצאי ר מרדכי יפה בעל הלבושים. היה שליח הפירמה י.ל. גולדברג מוילנא בסיביר. עסקן ציוני, עורך \"סיביר פלשתינה\". עלה לארץ-1923 ויסד את \"חברת מסחר ותעשיה\". הו\"ל \"מסחר ותעשיה\"."},{"i":24273,"n":"יפה, שלמה","bt":"1847","bp":"וילנא","dt":"1905","dp":"ראשון לציון","b":"איש ביל\"ו. תלמיד ביהמ\"ד לרבנים בזיטומיר. פתח בי\"ס פרטי באלכסנדרובסק-אוקראינה. עלה לארץ-1886 והתישב בנס ציונה.","bk":[["אשר לשלמה","מפרשי רמב\"ם"]]},{"i":24274,"n":"יפה, שמואל אשכנזי מקושטא","f":"יצחק","k":"בעל יפה תואר","bt":"רפה","bp":"ברוסה","dt":"שנה - יט אלול","b":"מגדולי הדרשנים והחכמים בדורו, רב בקהילת האשכנזים בקושטא-שמ\"ז. תלמיד ר יצחק ן לב, ר שלמה אלקבץ, תלמיד חבר לר שמואל סבע (גיסו של ר יוסף קארו). בנו ר יוסף רב ורופא בקושטא, ר יצחק מעתיק ספרי אביו ודיין באזמיר, וחתנו ר אלעזר פסח מקושטא. הספר \"יפה תאר\" היה לדברי בניהו הספר הגדול ביותר בכמותו מכל הספרים הנדפסים בעברית, חיבר גם \"יפה ענף\", \"יפה קול\", \"יפה מראה\", ועוד. התערב במחלוקת בענין חשבון השמיטה ופסק כדעת החולקים על הרמב\"ם. ר חיים בנבנשתי בעל \"כנסת הגדולה\" כותב בהקדמה כי את מלאכת איסוף דברי הפוסקים החל ר שמואל יפה. בנו - ר יוסף.","bk":[["יפה תואר","מפרשי מדרש"],["יפה תואר [על מדרש רבה]",""]]},{"i":24275,"n":"יפה, שמואל יצחק מתל אביב","f":"צבי","bt":"תרמד","bp":"סלובודקה","dt":"תשיג - יז ניסן","b":"מצאצאי ר מרדכי בעל הלבושים. חתן ר יוסף דב סולוביציק מבריסק. תלמיד ישיבות סלובודקה ובריסק - אצל גיסו ר חיים סולוביציק. רב בבוריסוב-תרעד, עלה לארץ-תרצד והתישב בתל אביב וכיהן כחבר הרבנות שם. חותנו של ר יצחק איזיק הרצוג. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא."},{"i":24276,"n":"יפה, שמחה זלמן","dt":"תשג","b":"רב בדיסנה"},{"i":24277,"n":"יפה, שמעון פרץ הלוי","k":"בעל אמרי שפר","b":"רב בניו יורק, עלה לירושלים-תרסח. בנו - ר שלום אלחנן."},{"i":24278,"n":"יפה, שרה מלובלין","b":"אשת ר שלמה בן יעקב. בעלת בית דפוס בלובלין - תכה-תלד."},{"i":24279,"n":"יפה-גרודזינסקי, פנחס מקאלווריה","f":"חנוך זונדל בן מרדכי","b":"רב בקלוואריה(=קאלווריה). בנו ר יעקב בעל גופי הלכות ונכדו ר חנוך זונדל."},{"i":24280,"n":"יפה-גרודזיסקי, חנוך זונדל מסער","f":"יעקב","bt":"תקעט","dt":"תרנא - יא אדר","b":"תלמיד ר אליהו רגולר, ר ליב שפירא מקובנא, ר יהודה בכרך. רב בראצקי, סערעצק, זמברובה, וישקובה, פולטוסק-תרלב (היה רב ליטאי בעיירה חסידית). חתם ב'נפש חיה' למען אתרוגי ארץ ישראל."},{"i":24281,"n":"יפה-גרודזנסקי, מרדכי צבי מקלוו","f":"יעקב","dt":"תרכט - ב תמוז","b":"רב בקלוואריע(=קלווריה)."},{"i":24282,"n":"יפה-ואלשטין, אריה ליביש מהליש","b":"תלמיד ר מנחם מנדל מרימנוב. רב בהאלישץ."},{"i":24283,"n":"יפה-מ\"ץ, יעקב מאוטיאן","f":"דב בער מטוריץ","b":"רב באוטיאן - התנה שלא יקרא רב אלא מ\"ץ (מורה צדק) ונשאר השם מ\"ץ ככינוי לכל המשפחה."},{"i":24284,"n":"יפה-מרגליות-שלזינגר","f":"ראה שלזינגר"},{"i":24285,"n":"יפה-שלזינגר, אברהם מגעף","f":"מרדכי מאיזנשטט - ת\"א","b":"חתן ר בצלאל שטרן ממלבורן-וינה. אב\"ד גענף."},{"i":24286,"n":"יפה-שלזינגר, מרדכי מאיזנשטט","f":"שמואל מארניאש-מארוטה","k":"בעל שפת המעיל","bt":"תרסט","bp":"ארניאש-מארוטה","dt":"תשנח - יח אייר","dp":"ירושלים","b":"תלמיד הדעת סופר, וזקנו ר משה ליב יוסף יפה-שלזינגר מרגנדורף, ור יהושע בוקסבוים מגאלאנטא. חתן ר עקיבא הכהן קליין מאיזנשטט. רב באיזנשטט-תרצא על מקום חותנו, ולאחר גירוש היהודים באיזנשטט רב אראניאש-מארוטה-תרצח על מקום אביו. עלה לירושלים-תרצט. דיין בתל אביב-תשיב ורב חוג חתם סופר שם.","bk":[["משברי ים – נושאים שונים בהלכה",""]]},{"i":24287,"n":"יפה-שלזינגר, עקיבא משטרסבורג","f":"מרדכי מאיזנשטט - ת\"א","b":"אב\"ד שטרסברוג."},{"i":24288,"n":"יפה-שפר, אבא שבתי מבולטימור","f":"חיים אהרן מבויסק","k":"בעל דין ומשפט ומעמדו","bt":"תרכב","bp":"בויסק-קורלנד","b":"נכד ר ידידיה יפה מבויסק. תלמיד ר זאב בשאלאט, ישיבת שאוויל אצל ר אלעזר לונץ, ישיבת ר משה פערלס בוועקשנא, ישיבת איישישוק, ר הלל כץ קליין-רב עדת ההונגרים בניו יורק, ביהמ\"ד לרבנים בברלין, ובעל תואר ד\"ר בפילוסופיה. חתן ר אלכסנדר משה לפידות מראסיין. רב בקהלת \"שארית ישראל\" בבולטימור-ארה\"ב-תרף. נסמך מאת: ר עזריאל הילדסהימר, הרב הופמן, ר אברהם דיאמנט מיורבורג, ר זאב להמן מערזוילאק, ר אלכסנדר משה לפידות, ר יצחק אלחנן מקובנא."},{"i":24289,"n":"יפה'ן, אברהם מנוברדוק","k":"בעל דרך איתן - תשיח","bt":"תרמו","bp":"קרינקי","dt":"תשל - כב אב","b":"חתן ר יוסף יוזל הורביץ הסבא מנוברדוק. ראש ישיבות \"בית יוסף\"-נוברדוק על מקום חותנו בנוברדוק, הומל, בביאליסטוק, ארה\"ב-תשא, עלה לירושלים-תשכד. (יש רושמים פטירתו ביד ניסן)."},{"i":24290,"n":"יפה'ן, זלמן","b":"פרסם מאמר ב\"אוהל יוסף\" נ\"י תשו."},{"i":24291,"n":"יפה'ן, יעקב חיים","b":"פרסם מאמר ב\"אהל יוסף\" נ\"י תשו."},{"i":24292,"n":"יפית, ברוך הלוי מטהארנאה","b":"שו\"ב בטהארנאה. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":24293,"n":"יפנזי, ש' ממרוקו","b":"רב במרוקו-תק. חיבר ספר דרשות - בכת\"י."},{"i":24294,"n":"יפרח, אברהם","bt":"תרמב","bp":"אלג'יריה","dt":"תשז","dp":"קזבלנקה","b":"דיין בקזבלנקה"},{"i":24295,"n":"יפרח, משה מטבריה","bp":"טבריה","dt":"תרצד - אייר","dp":"טבריה","b":"מחכמי טבריה. טבע בשיטפון הגדול בתרצד יחד עם אשתו ואמו. חיבר ביאור על התורה בכת\"י."},{"i":24296,"n":"יפרח, סלימאן מאלגיר","f":"יפרח","bt":"[רי]","dt":"רצ - בערך","b":"תלמיד ר יהודה כלץ. רב וסופר בתלמסאן. העתיק עבור רבו \"משיח אלמים\" - על פירוש רש\"י לתורה."},{"i":24297,"n":"יפת (אלמושנינו?) הכהן משלוניקי","b":"מגדולי חכמי הקבלה בצובא, שלוניקי, ירושלים. (אולי הוא אחיו של ר משה אלמושנינו - שהספידו). (ראה גם ר יפת המצרי - אולי הם זהים)."},{"i":24298,"n":"יפת החזן","f":"אברהם החזן","b":"חתם על גט בשנת ד' תתלז (1077)."},{"i":24299,"n":"יפת הלוי הקראי","f":"עלי","k":"בעל שפה ברורה","b":"מחכמי הקראים הקדומים-שנות ה-ד'תש-תת. תרגם את כתבי הקדש לערבית וגם פירשם. היה במחלוקת עם רס\"ג."},{"i":24300,"n":"יפת המצרי","bp":"מצרים?","b":"מחכמי מצרים. תלמיד ר חיים ויטאל. מקובל, מחכמי חלב, שלוניקי-שצד. מתלמידיו - ר דוד קונפורטי. (ראה גם ר יפת הכהן אלמושנינו - אולי הם זהים)"},{"i":24301,"n":"יפת הרופא הקראי","f":"סעיד","b":"מחכמי הקראים-שנות ה-ד'תתק. חיבר פירוש לתורה, ונזכר אצל הראב\"ע."},{"i":24302,"n":"יפת כהן","b":"תלמיד ר חיים ויטאל, היה בארם צובא ועבר לשלוניקי, רבו של בעל \"קורא הדורות\", בשנת שנז חתם על התקנה לשחרר תלמידי חכמים ממס."},{"i":24303,"n":"יפת מאשקלון","f":"ישועה","b":"חתום על שטר חכירה מאשקלון בשנת ד' תתצה (1135)."},{"i":24304,"n":"יפת מירושלים","f":"דוד בן שכניה","b":"סופר בית הדין בירושלים במאה ה-11. אגרת משנת ד תשפז (1027) ובה מתמנה ר יפת ע\"י ר אפרים העזתי לממונה על הכשרות בקהילת ירושלים בפוסטאט כיורשו של אביו."},{"i":24305,"n":"יפת מעכו","f":"אליהו","b":"דיין בעכו וראש הקהלה בתקופה שעלה לעכו ר מימון הספרדי ובנו הרמב\"ם. בקובץ תשובות הרמבם מצויה אגרת הרמבם אליו. ר בנמין מטודלה מזכירו בשנת תתקכה (1165)."},{"i":24306,"n":"יפת מעכו","f":"יונה","b":"מראשי הקהלה בעכו בשנת ד' תתקכח (1168) בזמן ביקור ר בנימין מטודלה."},{"i":24307,"n":"יצו ן, אברהם מאלגיר","bt":"תקע - בערך","dt":"תרם - בערך","b":"גביר משכיל מחכמי ווהראן. שאלה ממנו לר חיים פלאגי ב\"שו\"ת חיים\"."},{"i":24308,"n":"יצו ן, חיים מאלגיר","dt":"תרכז","b":"רב ודיין בווהראן וסגנו של האב\"ד ר מסעוד דרמון. ר אברהם אנקאווא מדבר עליו בספרו \"מלל לאברהם\". בשנת פטירתו-תרכז נפטרו בווהראן 9 רבנים."},{"i":24309,"n":"יצו ן, יהודה ממרוקו ואלגיר","bp":"מרוקו","dt":"תרכז","b":"הגיע ממרוקו לתלמסאן, עלה לארץ והתישב בצפת, איבד את משפחתו ברעש-תקצז ונותרה בת אחת, חזר לאלגיר והתישב בווהראן התעשר מעסקיו והיה גם מו\"ץ. תשובה ממנו ב\"כרם חמר\", \"טהרת כסף\". היה בעד הידברות ופשרה עם רבני הקונסיסטואר שפעלו להפצת תרבות צרפת."},{"i":24310,"n":"יצו ן, יוסף מאלגיר","f":"אברהם","bt":"תקס - בערך","dt":"תרם - בערך","b":"רב בקנאדסא-ליד בשאר (באזור הסהרה)-אלגיר."},{"i":24311,"n":"יצו ן, יעקב מאלגיר","bt":"תף","dt":"תקע - בערך","b":"רב בתלמסאן והיה דיין אצל ר נתן ג'ייאן. הסכים על מחזור תלמסאן - ליוורנו תקס. הניח כתבים רבים ובהם רשימת רבני תלמסאן ומדינת אלגיר. נזכר בשטרות מהשנים תק, תקכב."},{"i":24312,"n":"יצו ן, ישועה מאלגיר","f":"יעקב","b":"רב בתלמסאן - שנות הת-תק. נזכר ב\"מלכי רבנן\"."},{"i":24313,"n":"יצו ן, מרדכי מאלגיר","bt":"תקך","dt":"תקץ - בערך","b":"רב ודיין בווהראן-תקנב בזמן ארגונה מחדש של הקהלה."},{"i":24314,"n":"יצחק","b":"מגדולי דורו ש\"כ"},{"i":24315,"n":"יצחק","k":"ר' יצחק הדיין"},{"i":24316,"n":"יצחק","k":"בעל שער שמעון","b":"חיבר פירוש לפרקי שירה בשם - \"שער שמעון\" ו\"שיח יצחק\" יחד עם ר שמעון בן מאיר."},{"i":24317,"n":"יצחק","f":"מאיר - מהר\"ם מלובלין","b":"חיבר הקדמה לספר אביו."},{"i":24318,"n":"יצחק","f":"ראובן","b":"חיבר אזהרות. נדפס עם פירוש ר שאול הכהן מגרבה ב\"קרן דוד\" - גרבה תרעו."},{"i":24319,"n":"יצחק","f":"אליעזר","k":"בעל ספר הגן","b":"תלמיד ר משה בן אליעזר הדרשן-שנות ה-ר'. חיבר ספר הגן - פרג שעב."},{"i":24320,"n":"יצחק","f":"ידעיה","b":"חיבר פירוש לאגדות הש\"ס בדרך משל. לדעת ר יעקב ן חביב בעל \"עין יעקב\" אולי הוא בנו של ר ידעיה הבדרשי, ויש אומרים שהמדובר בטעות בשם והכוונה לר ידעיה בן אברהם בן יצחק הבדרשי."},{"i":24321,"n":"יצחק","f":"שלום מניישטט וינה","b":"בנו - הגביר ר יוסף ונכדו ר שלום שכנא מלובלין."},{"i":24322,"n":"יצחק (איטשע) נטע מפרוזין","b":"ראש ישיבה בפרוזין בזמן כהונת הגדול ממינסק שם."},{"i":24323,"n":"יצחק (טולדנו)","f":"יוסף","dt":"תעד"},{"i":24324,"n":"יצחק (טולדנו)","f":"יוסף דוד","dt":"תמד"},{"i":24325,"n":"יצחק אבינו ע\"ה","dt":"טו ניסן"},{"i":24326,"n":"יצחק אברהם הכהן מירושלים","b":"דיין בירושלים-תר\"ל"},{"i":24327,"n":"יצחק אברהם מלבוב","f":"אברהם","b":"מחכמי לבוב, חתם-תכד על תקנת קהלת זולקוא עם גדולי הרבנים ובהם בעל הט\"ז."},{"i":24328,"n":"יצחק אברהם שלמה ס\"ט","k":"בעל זרע יהודה"},{"i":24329,"n":"יצחק אהרן מלובלין וירושלים","f":"מאיר","k":"בעל פרישת יצחק","bt":"תקס","bp":"מזריטש","dt":"תרמא - כ כסלו","dp":"ירושלים","b":"מחכמי פולין עבר ללובלין ועלה לירושלים. חיבר פירוש לספרי בשם \"פרישת יצחק\" ירושלים תרלד."},{"i":24330,"n":"יצחק אהרן ממיטאוי","bt":"תקנח","bp":"מיטאוי","dt":"תרב","dp":"חרסון","b":"מורה לשפות במיטאוי, פלאצק-תקץ, חזר למיטאוי-תר, עבר עם למעלה מ-800 מיהודי מיטאוי לפלך חרסון."},{"i":24331,"n":"יצחק אור זרוע מוינה","f":"משה","k":"בעל אור זרוע","dt":"כ (1260)","b":"תלמיד רבנו יואל בן יצחק הלוי ובנו ר אליעזר-ראבי\"ה, ר יהודה מפאריס, ורבנו שמחה. מגדולי הפוסקים הראשונים, מרביץ תורה בוירצבורג, רגנסבורג, וינה."},{"i":24332,"n":"יצחק איזיק","k":"מאה\"ו","b":"חתם באה\"ו-תקל על פס\"ד של ר דוד ברלין, יחד עם ר משה אמשטרדם (אולי הם דיינים אצלו)."},{"i":24333,"n":"יצחק איזיק","f":"אליהו","k":"בעל פני יצחק","b":"חיבר פני יצחק-תץ."},{"i":24334,"n":"יצחק איזיק אברהם סגל מלמברג","f":"יואל","k":"בעל שיח יצחק","bt":"תקכ","dt":"תקפב","b":"רב בלמברג, לאבין-תקס. חיבר \"שיח יצחק\" סדילקוב תקפה."},{"i":24335,"n":"יצחק איזיק הכהן ממיץ","b":"רב במיץ-ת\"ק"},{"i":24336,"n":"יצחק איזיק הכהן מפרוסטיץ","f":"נפתלי כץ","b":"רב בפרוסטיץ-ת\"ק"},{"i":24337,"n":"יצחק איזיק הלוי מגינזבורג","b":"מרביץ תורה בגנזבורג-ש\"כ"},{"i":24338,"n":"יצחק איזיק חריף (קמינקר)","f":"אביגדור חריף מרוזנוי","b":"רב בכמה קהילות-תק\"ס. בנו - ר שמואל קמינקר."},{"i":24339,"n":"יצחק איזיק ליב מרייטץ","b":"רב ברייטץ(=רייץ)-תקעד על מקום ר משלם הורביץ ור אליהו מרייטץ על מקומו אחריו. נזכר בשו\"ת החת\"ס."},{"i":24340,"n":"יצחק איזיק מבארשא(=בורשה)","b":"תלמיד ר יעקב מליסא, חסיד ר מנחם מנדל מקוסוב ובנו חיים. רבה הראשון של בורשה-תקפ-צ, במינוי גיסו - ר מנחם מנדל שטרן מסיגט."},{"i":24341,"n":"יצחק איזיק מבוטושאן","b":"חתן ר חיים טירר מטשרנוביץ. רב בבוטושאן על מקום חותנו."},{"i":24342,"n":"יצחק איזיק מגיד מואראנאוי וטבר","b":"מחכמי עדת החסידים בטבריה בזמן ר אברהם מקאליסק."},{"i":24343,"n":"יצחק איזיק מגלינא","dt":"תקיט - יז שבט","b":"רב בגלינא"},{"i":24344,"n":"יצחק איזיק מהאמיה","b":"מו\"צ בהאמיה-תקצ\"ה"},{"i":24345,"n":"יצחק איזיק מהורדנא","f":"אברהם חיים פולק מאפט","dt":"תד או תנ","b":"רב בהורדנא-שצד על מקום ר אברהם אפשטין שעבר לבריסק (ויחד עמו כיהן ר יהושע בעל \"מגיני שלמה\"). אולי הוא שהיה בנו של ר אברהם חיים מאפטא, ואחיו של ר צבי הירש מלובלין, וגיסו של ר יעקב טעמרילש בעל \"ספרא דצניעותא דיעקב\". הסכים על ספר זכרון לר יצחק בן נח כץ שפירא."},{"i":24346,"n":"יצחק איזיק מהיבנוב","b":"רב בהיבנוב. מדברי תורתו בספר נכדו ר יהושע אברהם בן ישראל\" - גאולת ישראל\"."},{"i":24347,"n":"יצחק איזיק מהראדני","dt":"תג","b":"נספד מאת ר אברהם רפפורט ב\"איתן האזרחי\"."},{"i":24348,"n":"יצחק איזיק מויטבסק","f":"ישעיה","bt":"תרכז","b":"תלמיד בעל התניא, וראה 4 דורות של אדמורי חב\"ד - נפטר בן למעלה מ-100. רב באוסטראוונא, ויטבסק כ-60 שנה. תשובותיו ב\"פני יצחק\". בנו - ר יוסף."},{"i":24349,"n":"יצחק איזיק מוילנא וקרוז'","b":"מחכמי קרוז'. חתן ר בנדט מקרוז'. הוזמן לוילנא \"כדי להרים את גודל התורה והאמונה\" בזמן גזירות ניקולאי הראשון, וכדי לעשות את וילנא למרכז רוחני, חזר לקרוז' ולאחר שביתו נשרף בדליקה הגדולה, עבר לעסוק בחקלאות ליד קרוז'. אשתו-בת הרב - שרה צירל (תקע-תרלח) היתה למדנית ידועה - נכדת ר אליהו בן מאיר - שהיה גיסו של הגר\"א."},{"i":24350,"n":"יצחק איזיק מויניק","k":"ופפד\"מ","b":"מחכמי פפד\"מ-שכה, תמך אך לא חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ - בגלל שהוא חדש בעיר."},{"i":24351,"n":"יצחק איזיק מזולקוא","f":"נתן","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":24352,"n":"יצחק איזיק מזולקוא","f":"עזריאל זליג מקאליש","b":"חתם בפנקס זולקוא בועד ירוסלב-תנט."},{"i":24353,"n":"יצחק איזיק מזולקוא","f":"אברהם","dt":"תצז - טו שבט","dp":"זולקוא","b":"מחכמי זולקוא, חברו של ר אלכסנדר סנדר בעל תבואות שור וכך נרשם על מצבתו - שהיה חברו של בעל תבואות שור). (נרשם שהיה גם חברו של ר שלמה קלוגר?)"},{"i":24354,"n":"יצחק איזיק מזורוביץ","f":"יעקב הלוי","k":"בעל רזא מהימנא","bt":"תצה","dt":"תקמג","b":"מקובל מחכמי פשמישל ועבר לכפר זורוביץ (ליד פשמישל). נפגש עם הבעשט אך לא היה חסיד. נחשב לאחד מל\"ו צדיקים. חיבר \"רזא מהימנא\" למברג תקנא, \"יסוד יצחק\", ועוד."},{"i":24355,"n":"יצחק איזיק מחיטאוויץ וילנא","f":"יוסף","b":"רב בחיטאביץ(=חיטוביץ), מראשי קהלת וילנא-תקסא, חתם על מינוי 5 רבנים ובהם ר אברהם בן הגר\"א ור אברהם דנציג בעל חיי אדם כאחראים על תקנות הקהל."},{"i":24356,"n":"יצחק איזיק מחמלניק","b":"מצאצאי המהר\"ל. רב בחמלניק-תק\"צ. חתנו - ר שאול שטרנברג."},{"i":24357,"n":"יצחק איזיק מטירהאווצא","b":"תלמיד ר יקותיאל יהודה לנדא המגיד מטירהאווצא, ור נחמן מברסלב שהפליג בשבחו. רב בטוראווצע(=טירהאווצא)-תקס."},{"i":24358,"n":"יצחק איזיק מטירנוי","k":"בעל מנהגים","b":"רבה הראשון של טירנוי-שנות הש'. חיבר ספר מנהגים ליהודי הונגריה מוראביה ואוסטריה - ונציה שנא - הספר הראשון שנתחבר ע\"י רב מהונגריה."},{"i":24359,"n":"יצחק איזיק מטרנוב","f":"יהודה ליב מראקוב וקר","b":"רב בטרנוב(=טארנאוו)-תקך. נזכר ב\"רגלא דאמוראי\" בכורים-תרכו. חתם על החרם נגד הרמח\"ל יחד עם אחיו ר דוד שמואל מקראקא."},{"i":24360,"n":"יצחק איזיק מטרנוב","f":"נתן","b":"רב בטרנוב."},{"i":24361,"n":"יצחק איזיק מטשיטש","b":"אב\"ד טשיטש-תרצה."},{"i":24362,"n":"יצחק איזיק מיורבורג-ליטא","f":"אליעזר","b":"רב ביורבורג-שנות התק.."},{"i":24363,"n":"יצחק איזיק מישאל הלוי","f":"גדליה או גרשון מפאסט","dt":"תר - אחרי","b":"רב בנאדי-קאניזשא-תקצד, על מקום ר מאיר סענטא. (אביו היה רבה של פאסטאכא)."},{"i":24364,"n":"יצחק איזיק מלבוב","b":"דרשן,מגיד בלבוב-ת\"מ"},{"i":24365,"n":"יצחק איזיק מלבוב","f":"אלקנה","dt":"תמט - ד אייר","b":"דיין בלבוב."},{"i":24366,"n":"יצחק איזיק מלבוב","f":"יחיאל הקדוש","dt":"שנט - יט תשרי","dp":"לבוב","b":"רב בלבוב,מראשי ועד דד\"א. חתם על כרוז ועד ד ארצות-שמז - שלא לקנות רבנות בכסף. הסכים על \"מדרש רבה\". נזכר ב\"צידה לדרך\"."},{"i":24367,"n":"יצחק איזיק מלבוב","f":"יוחנן","dt":"שפא - יט אלול","dp":"לבוב","b":"רב בלבוב."},{"i":24368,"n":"יצחק איזיק מלבוב","b":"מתורתו בספר \"כבוד חכמים\"."},{"i":24369,"n":"יצחק איזיק מלובלין","f":"יהודה אריה ליב","dt":"תצה - יג טבת","dp":"לובלין","b":"מחכמי זולקוא וחתם שם-תעד, אב\"ד לובלין-תצג. הסכים על \"בית לחם יהודה\". נספד בספר החיים לר חיים רפפורט."},{"i":24370,"n":"יצחק איזיק מלובלין","f":"מאיר","dt":"תקטז - ח כסלו","dp":"לובלין","b":"מחכמי לובלין."},{"i":24371,"n":"יצחק איזיק מלכוביטש","b":"רב בלכוביטש, נוברדוק על מקום ר ראןבן בן משה, ור אריה ליב בעל \"דברי אמת\" על מקומו אחריו."},{"i":24372,"n":"יצחק איזיק מלענטשנא","f":"שמואל זנוויל","k":"אדמור מלענטשנא","dt":"תקפז - יח תשרי","b":"חתן ר יקותיאל מינץ מקראסנוברד. תלמיד החוזה מלובלין וגדל בביתו, אחר פטירתו חסיד ר יהודה ליב מזקילקוב. אדמור בלנעטשנא-תקפא. היה במחלוקת עם היהודי הקדוש מפשיסחא."},{"i":24373,"n":"יצחק איזיק מניישטט-אוסטריה","f":"יואל","dt":"רך","b":"תלמיד מהרי\"ו(=ר יעקב וייל), מהרי\"א בעל תרומת הדשן. מחכמי ניישטט-ליד וינה. חברו של מהר\"י ברונא, ור יוזמן כץ. אחיינו של ר טבלי מנירנברג. נזכר בתשובות רבו - ר ישראל איסרלן. ב\"לקט יושר\" חדושים ממנו וממה שהביא מרבותיו, ומאמר ממנו בשם \"קטפה לחניכה\" ."},{"i":24374,"n":"יצחק איזיק מסובאלק וסלונים ראה","f":"חבר, יצחק איזיק","b":"תלמיד ר מנחם מנדל משקלוב-תלמיד הגר\"א"},{"i":24375,"n":"יצחק איזיק מסטנוב","b":"רב בסטאנוב-שצ\"ט"},{"i":24376,"n":"יצחק איזיק מסטרי","f":"ישראל מהולשיץ","dt":"תר - ט שבט","b":"חתן ר צבי יוסף מרידניק. רב גדול בנגלה ונסתר בסטרי. מפורסם כבעל רוח הקודש."},{"i":24377,"n":"יצחק איזיק מסיקסא","b":"רב בסיקסא-תר\"י"},{"i":24378,"n":"יצחק איזיק מסלוצק וירושלים","b":"מחכמי ירושלים, בשליחות-תמח עם ר משה בן יעקב הכהן מפרג וירושלים."},{"i":24379,"n":"יצחק איזיק מעלקיש","b":"רב בעלקיש-תק\"ל"},{"i":24380,"n":"יצחק איזיק מעמריר","b":"רב לאשכנזים באמסטרדם-שנת ת'"},{"i":24381,"n":"יצחק איזיק מפינסק ובריסק","f":"ישראל","dt":"תרט - יז טבת","dp":"בריסק","b":"רב בפינסק-תקך, חתנו - ר אליעזר בן יעקב יסו\"ד. ולפי עיר תהלה בריסק - רב בבריסק על מקום ר אריה ליב קצנלנבוגן-תקצח עד תר ור אהרן קצנלנבוגן בעל מנחת אהרן על מקומו אחריו. (ואולי שני רבנים שונים)."},{"i":24382,"n":"יצחק איזיק מפרמישלא","f":"שמואל שמלקא מאוסטרהא","b":"חתן ר יהושע חריף בעל \"מגיני שלמה\". דיין בפרעמיסלא-תן, קרקא. בנו ר יהודה ליב מקראקא, חתנו ר אריה ליב תאומים."},{"i":24383,"n":"יצחק איזיק מצפת","f":"הרב מאטיק","b":"מחכמי צפת, חתם-תקץ עם רבני צפת, חתם-תקפט על ההסכמה בין הפרושים לחסידים."},{"i":24384,"n":"יצחק איזיק מקאפולי","f":"יקותיאל זלמן","k":"בעל באר יצחק","b":"מקובל,רב בקאפולי,מאהליב-תק\"נ"},{"i":24385,"n":"יצחק איזיק מקושטא ולבוב","f":"מרדכי","b":"מגיד ודרשן וראב\"ד בלבוב-לפני תן. נזכר ב\"עיר דוד\" לר דוד לידא וב\"דברי חכמים\" לר יהודה ליב פוחויצר. חיבר דרשות על ההפטרות, וספר על \"אל תקרא\" ו\"מאי דכתיב\" שבש\"ס - בכת\"י. אחיו - ר יהודה ליב מקושטא."},{"i":24386,"n":"יצחק איזיק מקראקא","f":"אשר","k":"איזיק ר יעקלש","dt":"תיג - כו סיון","dp":"קראקא","b":"חתן ר ישראל יחיאל רפפורט מקראקא. גביר מחכמי קראקא. בנה בית כנסת-בשנת תד ונקרא על שמו."},{"i":24387,"n":"יצחק איזיק מקרוז ווילנא","f":"אליעזר מקאסווי","b":"חתן ר משה הדרשן מוילנא. רב בקרוז' ובנו ר אליעזר על מקומו אחריו, פומפיאן, אב\"ד ודרשן בוילנא-תפז על מקום חותנו. העתיק את כתבי חותנו ואביו - ר הלל בן נפתלי הרץ בעל \"בית הלל\". עסק בקבלה והיה במחלוקת עם ר נתן נטע מראדזיויל. נזכר ב\"מקום שמואל\" למחותנו ר שמואל בן אלקה, וב\"עמודי בית יהודה\" לר יהודה בן מרדכי הורביץ. חתם על תוקף נדבות היסו\"ד, ועל כתב רבנות ר שמואל אב\"ד האחרון. העתיק את כתבי חותנו וחותנו זקנו-בעל בית הלל, עם חדושים ממנו ומאביו."},{"i":24388,"n":"יצחק איזיק מקרוטשין","b":"רב בקורטשין-תרלו."},{"i":24389,"n":"יצחק איזיק מקרומא-אשכנז","b":"רב באשכנז-ק'. נזכר ב\"תרומת הדשן\", ובמהרי\"ל."},{"i":24390,"n":"יצחק איזיק מקרימזא","b":"מגדולי חכמי אוסטרייך"},{"i":24391,"n":"יצחק איזיק מראוונא","f":"יוסף יוזפא אוסטרר","b":"נכד ר שמואל ר יעקב'ס מאוסטרהא. חתן ר אריה ליב רב בראוונע-תקס."},{"i":24392,"n":"יצחק איזיק מראוונא וקוריץ","f":"שמואל ר יעקב'ס","b":"רב בקוריץ, ראוונא, אולי הוא שהיה גם רב בטוטשין והסכים על \"הלכה פסוקה\"-תקכג (ואולי הוא בנו של ר יוזפא אחיו של ר יצחק איזיק)."},{"i":24393,"n":"יצחק איזיק קריצעווער מקרמנצוג","dp":"קרימנצוג","b":"רב בקרימנצוג(=קרמנצוג). נפטר בגיל 106. מצאצאיו ר שמואל גור אריה מחוראץ."},{"i":24394,"n":"יצחק אייזיק","dt":"תלד - א אב","b":"מחכמי לובלין"},{"i":24395,"n":"יצחק אייזיק הלוי מגינצבורג","b":"מזקני מרביצי התורה באשכנז,רב בגינזבורג-ש\"כ"},{"i":24396,"n":"יצחק אייזיק ליב מראצקי","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":24397,"n":"יצחק אייזיק מביאלי","f":"אהרן","b":"רב בביאלי"},{"i":24398,"n":"יצחק אייזיק מבלשקי","b":"חתן ר איצק גאלדעס מלוסק. רב בבלשקי-תקל, וחתנו - ר יהודה ליב ליפשיץ על מקומו אחריו. נכדו - בעל \"זר זהב\"."},{"i":24399,"n":"יצחק אייזיק מדוברוונה","b":"חתן ר אברהם ישראל הענדילש מקראקא. רב הגליל בדוברוונה. מחותן עם ר משה לימא בעל חלקת מחוקק - חתנו - ר רפאל סופר-לימא (17771). נכדו ר דב מרדכי חייקין (4628)."},{"i":24400,"n":"יצחק אייזיק מוונגרוב","b":"רב בוונגרוב"},{"i":24401,"n":"יצחק אייזיק צבי מקוברין","dt":"תרלב - י אדר","b":"רב בקוברין"},{"i":24402,"n":"יצחק איציק מזולקוא","f":"שמואל זנויל","b":"נכד(-אבי אמו) ר נפתלי כץ מלובלין-נכד המהר\"ל, ונכד(-אבי אביו) ר יצחק מזולקוא. גביר מחכמי זולקוא. חתניו - ר חיים (וחתן חתנו - ר מאיר מרגליות בעל מאיר נתיבים), ר אלחנן מבוטשט וסטרי, ר מרדכי גינצבורג מבריסק, ר צבי הירש ממזריטש, ר אברהם אבלי הלפרין מזולקוא (בן ר מרדכי ליבשס). בניו - ר אברהם דעס רב'ס, ר גומפריך מפפד\"מ."},{"i":24403,"n":"יצחק איציק מקאלין","b":"הגיע מקאלין. תלמיד החת\"ס בפרשבורג. החת\"ס המליץ עליו לחברו חיים דייטשמן מקאלין - לסמוך אותו."},{"i":24404,"n":"יצחק איצק","f":"צבי הירש פרץ","k":"מאה\"ו","b":"שמש קהילת אה\"ו. חתם על הכרוז שהוכרז בביהכ\"נ באלטונא-תקמט כנגד הספר \"מצפה יקותיאל\" - שפנה נגד ר רפאל הכהן מהמבורג."},{"i":24405,"n":"יצחק איצק גאלדס מלאסק","b":"גביר מחכמי לוסק. בנו - ר שמעון, ונכדו ר יוסף מלאסק. חתניו: ר שמואל לסקר מלוסק, ר אלעזר הכהן מלוסק, ר יחיאל מיכל הכהן מלוסק, ר יצחק איזיק מבלשקי, ר מאיר הנדלס מלוסק."},{"i":24406,"n":"יצחק איצק הלוי מהמבורג","f":"משה","dt":"תקיב - כד כסלו","dp":"אלטונא","b":"שו\"ב בהמבורג, נודה ע\"י ר יונתן איבשיץ, ובנו הלשין על ר יונתן והיה מחלוקת על כך."},{"i":24407,"n":"יצחק איצק ליב מטשוז","b":"רב בטשוז-תקפ\"ד"},{"i":24408,"n":"יצחק איצק מבאייא","b":"רב בבאייא-תק\"מ"},{"i":24409,"n":"יצחק איצק מגייא","f":"ליזר","dt":"תקכא - י תשרי","dp":"פרשבורג","b":"אב\"ד גייא."},{"i":24410,"n":"יצחק איצק מחאדזיטץ","f":"משה","b":"דיין בחאדזיטש(=חאדזייש)-תקסט, אצל ר גדליה ליפשיץ, וחתם-תקסט עמו ועם הדיין ר שמואל זנויל בן משה יהודה ליב."},{"i":24411,"n":"יצחק איצק מליסא","b":"רב בליסא-ת\"ס"},{"i":24412,"n":"יצחק איצק מלעמגו","k":"בעל תולדות יצחק","bt":"תקח","dt":"תקסא","b":"תלמיד ר שאול אב\"ד אמשטרדם. ר\"מ בביהמ\"ד \"עץ חיים\" של ק\"ק אשכנזים באמשטרדם, רב בגרונינגן-הולנד. חיבר \"תולדות יצחק\" - וכתב היד היה בידי אחיינו ר יצחק בן מרדכי מלעמגו. תלמידו המובהק - ר אברהם פרינץ."},{"i":24413,"n":"יצחק איצק מפאקש","b":"רב בפאקש-תק\"מ"},{"i":24414,"n":"יצחק איצק מפלונסק","b":"רב בפלונסק-תקס\"ה"},{"i":24415,"n":"יצחק איצק משוטלסדורף","b":"רב בשוטלסדורף-תקצ\"ו"},{"i":24416,"n":"יצחק איש אוסטרייך מלבוב","dt":"תט - יד אב","dp":"לבוב","b":"ראב\"ד בלבוב. תשובה ממנו ב\"איתן האזרחי\", חתם-תג עם ר יוסף ר סענדרש ור יעקב בן יוסף יעקב אברהם קצנלנבוגן."},{"i":24417,"n":"יצחק אליהו","f":"משלם איגרא","bt":"תקכח","dt":"תקמח - ו חשון"},{"i":24418,"n":"יצחק אליהו מפאקריי","f":"זאב","b":"דיין בפאקריי, חתם-תרטז עם ר אריה זאב בן שלום, ור יהודה אריה בן ראובן."},{"i":24419,"n":"יצחק אלעזר מירושלים","b":"עסקן מחכמי ירושלים-תרסה."},{"i":24420,"n":"יצחק אמידער","k":"איצעלע סמארגאנער","b":"תלמיד ר חיים מוולוזין (אחד מה-4 שזרק בהם מרה). היה בדחן מפורסם בזמנו."},{"i":24421,"n":"יצחק אפרים משלוניקי","dt":"שעז - יד אלול","dp":"שלוניקי","b":"נהרג ליד שלוניקי בדרכו מיריד דולייא-שפח עם רבים מישראל."},{"i":24422,"n":"יצחק אריה הכהן מבוגוניצה","b":"נכדו של בעל הקצות. רב בבוגוניצה (ליד טרנוב)."},{"i":24423,"n":"יצחק אריה מירושלים","dt":"תקעד - ד כסלו","dp":"ירושלים","b":"גביר מחכמי ירושלים. (אולי המדובר ב-2 רבנים שונים)."},{"i":24424,"n":"יצחק אריה מסוקוליבקה","b":"סופר בסוקוליבקה. תשובה אליו \"לקוטי צבי\"."},{"i":24425,"n":"יצחק אשכנזי מלמברג","f":"פייבל מלכוביץ","b":"תלמיד ר לייב שרה'ס, ור קהת מועריש. פירנס את הצדיקים הנסתרים. ומפורסם בנסים."},{"i":24426,"n":"יצחק אשר מטיטשין","b":"אב\"ד טיטשין."},{"i":24427,"n":"יצחק בונם מנאואקראנקא","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":24428,"n":"יצחק בכר דוד מקושטא","f":"דוד","k":"בעל דברי אמת","bt":"תנ-ה","bp":"קושטא","dt":"תקטו","dp":"קושטא","b":"תלמיד ר שמואל הלוי מקושטא. רב בקושטא. חתנו - ר אברהם ב\"ר אביגדור. חיבר \"דברי אמת\" (ובשם הספר רמז שמו ושם אביו), ונדפס ע\"י בנו ר דוד - בתמיכת הגביר יעקב בונפיל, ה\"נודע ביהודה\" וה\"שואל ומשיב\" לר שאול נתנזון משבחים מאוד את ספרו. בניו - ר יעקב, ר דוד, ר אברהם.","bk":[["דברי אמת - חלק הקונטרסים","מערכות"],["דברי אמת [שו\"ת, ענינים שונים ודרשות]",""]]},{"i":24429,"n":"יצחק בכר חיים מירושלים","f":"חיים?","b":"מחכמי ירושלים, חתם-תרכא על \"חדושי הר\"ן\", ועל \"חמשה קונטרסים\"-תרכג."},{"i":24430,"n":"יצחק בכר שבתי","f":"שבתי","k":"מאר\"ץ","b":"מרבני ארם צובה-תק\"ה"},{"i":24431,"n":"יצחק בן אברהם שלמה מבגדאד","bt":"1835","dt":"ה'תרפ 1920","bk":[["אקים את יצחק",""],["צלח רכב",""]]},{"i":24432,"n":"יצחק בן אליעזר","bt":"1300","dt":"ה'קכ 1360","bk":[["הגן",""],["הגן ודרך משה",""],["ספר הגן",""]]},{"i":24433,"n":"יצחק בן אליעזר מארץ הגר","dt":"ה'תקצ 1830","bk":[["אהל יצחק",""],["אהל יצחק השלם",""],["בית יצחק",""],["לקיטת יצחק",""]]},{"i":24434,"n":"יצחק בן ציון מלבוב","f":"וואלפש","dp":"לבוב","b":"ראב\"ד בלבוב."},{"i":24435,"n":"יצחק בן ראובן אלברגלוני","dt":"ד'תתג 1043","bk":[["אזהרות",""],["אזהרות להגאון רבינו יצחק",""],["מנחת בכורים",""]]},{"i":24436,"n":"יצחק בנימין וולף הלוי מזולקוא","f":"בצלאל","b":"מחכמי קראקא, חתם-תקכו בפנקס הקהלה. (ואולי שמו רצחק בן וולף בן בצלאל)."},{"i":24437,"n":"יצחק בנימין וולף מסלוצק וברלין","f":"אליעזר ליפמן מגטינגן","k":"בעל נחלת בנימין","bp":"אשכנז","dt":"תמג-ט - כח חשון","b":"תלמיד ר יצחק בן אברהם מוילנא ופוזנא. חתן ר אהרן. רב בברלין, לנדסברג, סלוצק-תמז, אליק, לובלין-תמ. היה מעורב במחלוקת גיסו-ר ניסן בן יהודה ליב עם רבני אמשטרדם ונזכר ב\"אוהל יעקב\" לר יעקב ששפורטש. אחיו - ר יהודא (יודא) פרנס ומנהיג בברלין. הניח כתבים וחדושים בכת\"י. בניו: ר אליעזר ליפמן מקובלנץ, ר אהרן מברלין. חתניו: ר מיכל חסיד מברלין, ר יעקב בן עזריאל מוילנא."},{"i":24438,"n":"יצחק בעל התוספות","f":"אברהם","k":"הריצב\"א או הריב\"א","dt":"ד'תתקם","b":"מכונה הבחור - ור יצחק בן שמואל מדנפיר נקרא הזקן. מבעלי התוספות, רב בדנפייר-ד'תתקס ואולי גם בראמרו. אחיו של ר שמשון בן אברהם. מתורתו בספר הגן, ועוד. חיבר פירוש לתורה."},{"i":24439,"n":"יצחק בעל התוספות","f":"ברוך","b":"מגדולי בעלי התוספות-ד'תתק\"מ"},{"i":24440,"n":"יצחק בעל התוספות","f":"יצחק","b":"מבעלי התוספות, אולי הוא ר יצחק מקינון שנזכר ב\"שיטה מקובצת\". חיבר פיוטים לחגים וחתם - יצחק בן יצחק בן מרדכי בן ישי בן שלמה."},{"i":24441,"n":"יצחק בער מביסהיים","b":"מו\"צ בביסהיים-תר\"ל"},{"i":24442,"n":"יצחק ברוך יובעלירער מוילנא","b":"ממיסדי ותומכי ישיבת מייליס בוילנא."},{"i":24443,"n":"יצחק ברוך ממצרים וצפת","k":"בעל חק לישראל","b":"מחכמי מצרים, צפת בשנת תק. חיבר ספר \"חוק לישראל\" (החיד\"א הוסיף לו מדור הנקרא יוסף לחוק). אולי הוא שהתכתב עם ר משה ריבקש בעל באר הגולה."},{"i":24444,"n":"יצחק ברוך מקובנא וירושלים","b":"מחכמי ירושלים, בשנת תקף בשליחות בקושטא יחד עם ר שלמה זלמן שפירא - בענין חוב הקהלה האשכנזית."},{"i":24445,"n":"יצחק ברכיה מפאנו","f":"יהודה אריה","k":"בעל חנוך לנער","b":"פייטן. בן אחותו, תלמידו, וחתנו של הרמ\"ע מפאנו. רב בלוגו-איטליה-תפז. תלמידו - ר שבתי בעל \"באר עשק\" שהביא מתורתו בספרו. חיבר פיוטים שנדפסו בסידור של ברכה, \"חנוך לנער\" בכת\"י. הסכים-תצו על פסק נכדו - ר שבתי דיל ויקייו."},{"i":24446,"n":"יצחק גר צדק","k":"בעל זרע יצחק","dt":"תקסז - ל אד\"א","b":"דיין באמסטרדם"},{"i":24447,"n":"יצחק גרשון מצפת","dt":"שע","b":"תלמיד ר משה אלשיך בצפת. עבר לונציה והיה מגיה ספרים אצל די גארה, ואחרים. נזכר בשו\"ת יו\"ט צהלון."},{"i":24448,"n":"יצחק דוד הרופא מקושטא","dt":"תקז - בערך","dp":"ירושלים","b":"רופא ודיין מחכמי קושטא-תק, סייע לר אברהם גרשון קיטובר-גיסו של הבעש\"ט בהיותו בקושטא, ועלה עמו לירושלים."},{"i":24449,"n":"יצחק דוד מזורובנא","b":"רב בזורובנא-תריג."},{"i":24450,"n":"יצחק דוד מירושלים","b":"מחכמי ירושלים, בשנת תקסג בשליחות בפולין ואשכנז. הביא לדפוס \"חדושי דינים\" - מנהגי ירושלים בענין פסח, בעיר מזירוב. הביא לדפוס \"ארבע מאות שקל כסף\" לר חיים ויטאל קוריץ תקסד."},{"i":24451,"n":"יצחק דוד מנעסכיז","k":"בעל תנובות שדי","dt":"תרמד - ב שבט","b":"רב באיוונסק,נסכיז"},{"i":24452,"n":"יצחק די ליאון די, דוד מהאג","b":"מגדולי חכמי הספרדים בהאג-תק\"מ"},{"i":24453,"n":"יצחק דידיע אבא משלוניקי","f":"יהודה","k":"בעל לחם יהודה","b":"רב באזמיר, שלוניקי. חיבר ספרים בספרדית. חיבר גם \"יביא בפריו\", \"מעם לועז\" על ישעיה ונקרא גם \"לחם יהודה\", ועוד."},{"i":24454,"n":"יצחק דיין המסתערבים","b":"מחכמי ירושלים, מוזכר במכתב הנוסע האלמוני משנת רפב, כנשיא העדה. לדעת רבלין הוא השיך יצחק שהוזכר בתשובת הרלבח, במכתב ר אברהם טרביט (\"קובץ על יד\" ד) מסופר על בחור אחד... והוא בן הדיין של המסתערבים וכנראה הוא החכם הזקן מירושלים המוזכר בתשובות מהרי בירב ויתכן שהוא ר יצחק אלבו."},{"i":24455,"n":"יצחק דמן עכו","f":"שמואל","k":"בעל מאירת עינים","bt":"י (1250)","bp":"ארץ ישראל","dt":"ק (1340)","dp":"טולידו (ספרד)","b":"מקובל, איש מופת, מגדולי דורו בח\"ן, תלמיד ר שלמה פטיט מעכו, למד גם אצל הרמב\"ן. בזמן כבוש עכו על ידי הערבים נלקח בשבי ונפדה ואז עבר לאיטליה ואחר כך לספרד-סה והיה מחכמי ספרד בדור העשירי, תלמיד הרשב\"א. עסק בחקר מחבר הזהר ונפגש עם ר משה די ליאון וכתב זאת בספרו \"דברי הימים\" שפרסם בחלקו וחלקו אבד , חיבר גם פירוש לספר יצירה, ועוד."},{"i":24456,"n":"יצחק דניאל משלוניקי","f":"יהודה","bt":"תרכג","dt":"תרנא","dp":"שלוניקי","b":"למד רפואה בצרפת. רופא בשלוניקי."},{"i":24457,"n":"יצחק הגדול ממגנצא - א","f":"רבינו יהושע הגדול","k":"רבינו יצחק הגדול","b":"מגדולי חכמי מגנצא-ד'תש\"פ"},{"i":24458,"n":"יצחק הגדול ממגנצא - ב","f":"אליעזר הגדול","k":"רבינו יצחק הגדול","dt":"ד'תתנו","b":"עק\"ה,מגדולי הראשונים בחכמי מגנצא"},{"i":24459,"n":"יצחק הגר-ויסקונטי","k":"רבינו יצחק מארץ הגר","b":"מגדולי בעלי התוספות,תלמיד רבינו תם,מרביץ תורה-ד'תתק\"מ"},{"i":24460,"n":"יצחק הזקן","k":"הר\"י","dt":"א - כז תשרי","b":"גדול בעלי התוספות בצרפת. בנו - רבנו אלחנן"},{"i":24461,"n":"יצחק החבר מדמשק","b":"רופא ורב לקהילת הסיציליאנים בדמשק-רפב. בנו ר חיים - שתשובה ממנו באבקת רוכל לר יוסף קארו."},{"i":24462,"n":"יצחק הטרוקי הקראי","f":"אברהם","k":"בעל חזוק אמונה","dt":"רצג","b":"תלמיד החכם הקראי ר צפניה בן מרדכי מטרוקי. בקי בשפות, פילוסופיה. חיבר ספר \"חזוק אמונה\" והוא פולמוס עם האמונה הנוצרית - שתורגם לשפות שונות וזכה להתיחסות רבה מצד הנוצרים."},{"i":24463,"n":"יצחק הכהן","f":"ישועה -מעיני הישועה","k":"בעל יצחק בנו","b":"חיבר \"פתח הדביר ויצחק ירנן\", ו\"יצחק בנו\" נדפס עם ספר אביו \"מעיני הישועה\". הו\"ל \"חוקי חיים\" למהרא\"ח בורגל, ו\"זרעו של אברהם\" - תונס תרפח."},{"i":24464,"n":"יצחק הכהן","f":"ברכה","k":"בעל מנחת יצחק,המכונה חוגא","b":"מחכמי תונס בזמן ר מסעוד חביב, ר יהודה אלגז, ר יעקב לומברזו ועוד. בספרו מביא חדושים מר דוד בן בארון לימים ראב\"ד בתונס, ור דוד ג'אוי מסוסא לימים עלה לארץ. חיבר \"מנחת יצחק\" ונדפס בסוף \"מעייני הישועה\" - תונס תרסה."},{"i":24465,"n":"יצחק הכהן החבר הפייטן","b":"פייטן קדום. חיבר \"אדון בפקדך אנוש לבקרים\"."},{"i":24466,"n":"יצחק הכהן מאוסטרהא","f":"נפתלי הירץ בוקינג","k":"בעל קיצור מזרחי","bp":"קראקא","b":"תלמיד ר שלמה בן יהודה ליב = \"מהרש\"ל השני\" שהיה רבם של הב\"ח והשל\"ה. מגדולי אוסטרהא-שן בזמן השל\"ה."},{"i":24467,"n":"יצחק הכהן מאוסטרהא","f":"אליעזר","dt":"תקנה - כג תשרי","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":24468,"n":"יצחק הכהן מאלגיר","f":"סעדיה","bt":"קמ","dt":"רי - בערך","b":"רב וספרא דדיינא מתנס-אלגיר. שאלות ממנו לרשב\"ץ בעניני תורת הנסתר, בדקדוק ועוד - ונזכר בשו\"ת הרשב\"ש. מאמר עליו ב\"ספונות\" מאת ר נח עמינח."},{"i":24469,"n":"יצחק הכהן מאשכנז וסופיה","b":"מחכמי אשכנז, לאחר הגירוש-רל הגיע לסופיה-בולגריה. עם בנו - נפתלי הרץ."},{"i":24470,"n":"יצחק הכהן מברודשין","b":"רב בברודשין-תרלח."},{"i":24471,"n":"יצחק הכהן מדרויסק גאמרוב","f":"מנחם מניש","k":"בעל מנחם יצחק","b":"רב בדרויסק גאמרוב. חיבר גם \"ליקוטי יצחק\", ועוד."},{"i":24472,"n":"יצחק הכהן מהמבורג","f":"זליגמן יהודה מהמבורג","b":"נכד ר ישכר בער הכהן מהמבורג. רכש את הקלויז שהקדיש זקנו והיה במחלוקת עם בן דודו ר פיבש הכהן מקופנהגן וגם עם ר רפאל הכהן אב\"ד המבורג."},{"i":24473,"n":"יצחק הכהן מויטרבו","b":"רב בסיינה-שלד, רב בויטרבו בזמן ר\"מ פרובנצאלי, ור יחיאל טרבוט. תשובה ממנו ב\"פחד יצחק\" - ובה העיד שראה בקטנותו ברומא אחד שייבם את אשת אחיו במעמד רבנים חשובים."},{"i":24474,"n":"יצחק הכהן מוירז","b":"מגיד בווירז-תק\"פ"},{"i":24475,"n":"יצחק הכהן מזולקוא","f":"דוד יוסף כץ מקאליש","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה, ועל בחירת ראשי העדה-תסה."},{"i":24476,"n":"יצחק הכהן מחברון - א","b":"מחכמי חברון, בשנת תקיח חתם על הסכמה ל\"אורים גדולים\" לר אברהם חיים זאבי. בשנים תקכג ותקלה על כתב בקשת עזרה לקהלה. בשנת תקיד בשליחות בצפון אפריקה, בשליחות-תקכו באמריקה, ונזכר בפנקס קהילת קורסאו, וכן חתם על כמה כתבי שליחות."},{"i":24477,"n":"יצחק הכהן מחברון - ב","dt":"תקסד","dp":"ירושלים","b":"דיין בירושלים, חברון, בשנת תקיד חתם על תקנת הצניעות, בשנת תקלב על מכתב רבני חברון. נספד בספר \"מערכי לב\" עם ר\"י בורלא."},{"i":24478,"n":"יצחק הכהן מיוזיל-היסאר","dt":"תץ - בערך","b":"שר האוצר של הפחה ביוזיל-היסאר-שנות ה-ת'."},{"i":24479,"n":"יצחק הכהן מירושלים","b":"דיין בירושלים-תרס."},{"i":24480,"n":"יצחק הכהן ממגנישיאה","b":"רב במגנישיאה-שנות ה-ש'."},{"i":24481,"n":"יצחק הכהן ממונשטיר","f":"אלעזר","b":"רב במונשטיר-שמח."},{"i":24482,"n":"יצחק הכהן ממנטובה","b":"מגדולי חכמי איטליה,מרביץ תורה במנטובה-ש\"כ"},{"i":24483,"n":"יצחק הכהן ממרוקו","f":"אברהם","k":"בעל גנת ביתן","dt":"שעח - בערך","b":"מחכמי מרוקו. תלמיד ר משה בן מימון אלבז. (בחיד\"א - נאמר על הספר שאולי מחברו ר טודרוס הלוי)."},{"i":24484,"n":"יצחק הכהן ממרוקו וטבריה","f":"מימון","bt":"תריט","bp":"מכנאס","dt":"תרסב - ג אב","dp":"טבריה","b":"עלה בילדותו ממרוקו לטבריה, רב בטבריה. בשליחות בעירק-תרסא."},{"i":24485,"n":"יצחק הכהן ממרסיליא","b":"הרביץ תורה במרשיליא-שנת ס'"},{"i":24486,"n":"יצחק הכהן מסופיה","b":"גביר בסופיה-תקן, תמך ברבנים ובהדפסת ספרים."},{"i":24487,"n":"יצחק הכהן מסטאשוב","f":"שלמה זלמן","k":"בעל פני יצחק","b":"רב בסטאשוב. חיבר \"פני יצחק\" למברג תקנה."},{"i":24488,"n":"יצחק הכהן מספרד","b":"מגדולי המקובלים הראשונים בספרד-שנת ס',רב בשוריא,פרובינצה,נרבונה,ארלס,בדרש"},{"i":24489,"n":"יצחק הכהן מספרד","f":"חיים","b":"מחכמי ספרד, לאחר הגירוש הגיע לאיטליה, ואח\"כ לקושטא, בשנת רעח היה בחיים ולאחר מכן לא נודעו עקבותיו. חיבר שירים פירוש לשיר השירים, קינה על הגירוש ועוד. כתב היד נמצא בספרית המוזיאון הבריטי. נדפס בשם \"מקונן אבלנו\" ע\"י ד\"ר מרדכי דרכסלר מטימישואר, עם הקדמה והערות ממנו."},{"i":24490,"n":"יצחק הכהן מפרובנס","b":"מגדולי הראשונים, מרביץ תורה בפרובאנס-ד'תתקצ. מתלמידיו - ר ראובן בן חיים. נזכר במאירי."},{"i":24491,"n":"יצחק הכהן מצפרו-מרוקו","k":"יצחק מול למילה","dp":"צפרו","b":"רב ומוהל בצפרו-מרוקו, לקברו עלו להתפלל בזמן עצירת גשמים."},{"i":24492,"n":"יצחק הכהן מצפת","f":"יחזקאל","bt":"תרט","bp":"צפת","dt":"תרצד - ג שבט","dp":"צפת - מירון","b":"מחכמי צפת ומגדולי המקובלים."},{"i":24493,"n":"יצחק הכהן מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":24494,"n":"יצחק הכהן מקושטא","f":"שלמה","b":"מחכמי קושטא. חיבר פירוש על איוב - קושטא שכח."},{"i":24495,"n":"יצחק הכהן מקושטא","b":"דיין בקושטא-תקסה יחד ר חיים פריסקו ור משה זונאנא"},{"i":24496,"n":"יצחק הכהן מקסטיליא","f":"יעקב משוריא-קסטיליא","bp":"שוריא-קסטיליא","b":"מקובל מחכמי ספרד בקסטיליא בסוף המאה ה-13, התגורר בפרובינציא - בנרבונא, ארלס, דרש. אחיו של ר יעקב הכהן. בן דורו של ר יצחק אלבלג - מעיד עליו כי הוא אחד משלושת גדולי המקובלים שבדור. תלמידו ר משה מבורגוס. הניח חבורים בקבלה בכת\"י (חלקים נתפרסמו ב\"תרביץ\" ועוד)."},{"i":24497,"n":"יצחק הכהן מקראקא","b":"דרשן בקרקא-תכ\"ה"},{"i":24498,"n":"יצחק הכהן מראבאט","b":"מחכמי ראבאט-מרוקו, מכתב אליו משנת - תקפב."},{"i":24499,"n":"יצחק הכהן משלוניקי","k":"אבי התעודה","dt":"תעה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24500,"n":"יצחק הכהן משלוניקי","dt":"שסט - ה טבת","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":24501,"n":"יצחק הכהן משלוניקי","dt":"שצה - יז תמוז","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":24502,"n":"יצחק הכהן מתונס","f":"יוסף אברי\"ש","k":"בעל בארות יצחק","b":"מחכמי תונס, חברו של ר חיים טייב. חיבר \"בארות יצחק\" ישראל תשסה."},{"i":24503,"n":"יצחק הלבן","k":"רבינו יצחק הלבן","b":"תלמיד רבנו תם, מגדולי בעלי התוספות בוורמייזא, מחכמי ביהם-פרג, מרביץ תורה ברגנשבורג-ד'תתק\"מ. אולי הוא מחבר הפיוט \"אמונת מלכים נתתה\", ואולי הוא אחיו של ר פתחיה המסובב."},{"i":24504,"n":"יצחק הלוי","f":"אשר","k":"ריב\"א הלוי,ריב\"א","dt":"ד'תתצב","b":"חתן ר אליקום בן משלם. ראש לבעלי התוספות באשכנז בשפיירא. אחיו של ר אליקים הלוי. והוא סתם ריב\"א המופיע בתוס' שלפנינו."},{"i":24505,"n":"יצחק הלוי","b":"מגדולי הראשונים-שנת ס'"},{"i":24506,"n":"יצחק הלוי","b":"רב בזמן ר יצחק ן גיאת. חיבר סדר עבודה ליו\"כ - הזכירו הר\"י קמחי בספרו \"עבודת ישראל\"."},{"i":24507,"n":"יצחק הלוי","f":"בנימין","b":"רב שנות ה-ת', הניח קובץ שו\"ת בכת\"י, נזכר ב\"כהונת עולם\"."},{"i":24508,"n":"יצחק הלוי אסיר התקוה","dt":"קנה - לפני","dp":"ירושלים","b":"מחכמי גרמניה בשנת קט, עלה לירושלים בשנת קיט, בדרכו לארץ ישראל נמצא בפמגוסטה בקפריסין אצל הקהלה היהודית שם שבראשה עמד ר אליעזר פירנא. מתלמידיו ר אליעזר בן שמשון ור יעקב בן שמואל. נזכר במרדכי כמורי ורבי גדול הדור. מזוהה עם ר יצחק הלוי בילשטיין."},{"i":24509,"n":"יצחק הלוי מאזילא-מרוקו","f":"ששון או שטון?","b":"מו\"ץ באזילא-מרוקו - שנות ה-תק'."},{"i":24510,"n":"יצחק הלוי מאלגיר","bt":"קן - בערך","dt":"רך - בערך","b":"רב במסתגאנים-אלגיר, תלמסאן. נזכר בשו\"ת הרשב\"ץ, והרשב\"ש. החיזר בספר \"כפאייה אל עאבדין\" - חיבור בעניני הלכות הזמן הזה ועניני שבע חכמות."},{"i":24511,"n":"יצחק הלוי מבבל וספרד","f":"אלעזר","k":"בעל ספר הרקמה","b":"מדקדק מחכמי ספרד, חיבר ספר דקדוק בשם הרקמה לתועלת תלמידו - ר אהרן בן אברהם געגא שהגיע מבבל לספרד."},{"i":24512,"n":"יצחק הלוי מגיברלטר","k":"בעל פת לחם","b":"רב בגיברלטר-תקצו, בעל \"פת לחם\" וינה תרמא, ו\"דת יהודית\" שחיברו עם ר אברהם לארידו. בנו ר ישועה - רב בליסבון."},{"i":24513,"n":"יצחק הלוי מגרונה -","f":"זכריה","k":"בעל מגילת הנחמה","b":"מחכמי גרונה - ספרד במאה ה-יב. חיבר פיוטים שנכנסו למחזור הספרדים."},{"i":24514,"n":"יצחק הלוי מורמייזא","f":"אשר או אלעזר","k":"לוי\"ה,רבו של רש\"י","dt":"ד'תתל","b":"תלמיד רבנו גרשם ורבו של רש\"י. מגדולי חכמי דורו, מרביץ תורה בוורמייזא. חיבר גם פיוטים. בנו - ר יעקב יעבץ."},{"i":24515,"n":"יצחק הלוי מחעלמא ולבוב","b":"רב בחעלמא. בנו - ר מרדכי-חתנו של ר יעקב בן יצחק כהנא-שפירא."},{"i":24516,"n":"יצחק הלוי מטיטואן וגיברלטר","k":"בעל פת לחם?","b":"רב בטיטואן-מרוקו, גיברלטר, נזכר ב\"משפט וצדקה ביעקב\", חתם על פס\"ד-תץ עם ר שלמה אבודרהם, ועם ר דוד כלפון - בשנת תף. (ישנו רב נוסף באותו השם מגיברלטר שגם עליו נאמר שחיבר \"פתח לחם\" - וחי בשנת תקץ - האם המדובר באותו הרב ויש טעות בשנים באחד מהם?). גיסו - ר אברהם מונסון מטיטואן."},{"i":24517,"n":"יצחק הלוי מירושלים","dt":"תרלח","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תקצט חתם על כתב שליחות ר מנחם בורלה ור יוסף אליעזר. נספד בספר \"קול שחל\"."},{"i":24518,"n":"יצחק הלוי מירושלים","f":"משה","b":"דיין בירושלים-שנות ה-ת' - בזמן ר יעקב חגיז."},{"i":24519,"n":"יצחק הלוי מלבוב","f":"יעקב","dt":"תפב - ו סיון","dp":"לבוב","b":"מחכמי לבוב. חתם-תנד בפנקס הקהלה, וחתם-תנז על פס\"ד בענין ביהכ\"נ בק\"ק זידיטשוב."},{"i":24520,"n":"יצחק הלוי מלבוב","f":"נטע","b":"דיין בלבוב, הסכים על \"שערי בנימין\"-תקיב עם ר חיים רפפורט ובנו ר אריה ליב רפפורט (כנראה היה דיין אצל ר חיים)."},{"i":24521,"n":"יצחק הלוי מלודמיר וחעלמא","f":"שמואל","k":"בעל ברית הלוי","bp":"לבוב","b":"אחיו ורבו של ר דוד בעל הט\"ז, רב בלודמיר-שסד, חעלמא, ר\"מ בפוזנא-שפז, רב בלבוב. חיבר גם \"שיח יצחק\", \"ברית הלוי\", \"אלה תולדות יצחק\", ועוד."},{"i":24522,"n":"יצחק הלוי מלעשנוב וחעלמא","f":"מרדכי","dt":"תקנט - יא סיון","dp":"קראקא?","b":"מגדולי חכמי דורו. חתן ר אריה ליב אב\"ד אמשטרדם. אב\"ד לעשנוב-תקטו, חעלמא(=חלם)-תקכט, קראקא-תקלח על מקום ר אריה ליב בן שמואל (הטיל בה חרם על החסידים) ור שלמה זלמן מוארשא על מקומו אחריו. הסכים על \"גבעת שאול\"-תקכט, \"ברכת יעקב\"-תקלו, \"קרבן ראשית\"-תקלח (נרשם בטעות יעקב במקום יצחק), ועוד. נזכר בספר קרובו בעל \"כתר כהונה\". בניו: ר צבי הירש דוד רב בקראקא על מקום אביו, ר מרדכי מזאלאזיץ. גיסו - ר שאול מאמשטרדם ושהה בבית גיסו והסכים שם על \"תכונות השמים\"-תקטז, \"סאה סולת ומרפא לנפש\","},{"i":24523,"n":"יצחק הלוי ממכנאס","b":"מחכמי מכנאס, נזכר ב\"תקפו של יוסף\"."},{"i":24524,"n":"יצחק הלוי ממנטובה","f":"יהודה","dt":"שץ","dp":"מנטובה","b":"רב במנטובה-שפב. נרצח בזמן גירוש מנטובה-שץ."},{"i":24525,"n":"יצחק הלוי מניקלשבורג","k":"בעל ברכת יצחק","b":"רב-שנת ת\"ק"},{"i":24526,"n":"יצחק הלוי מסופיה","f":"משה יצחק מסופיה","b":"רב הכולל בסופיה-תקץ בערך (על מקום אביו?)."},{"i":24527,"n":"יצחק הלוי מסטרטין","b":"רב בסטרטין, זורובנא-תר."},{"i":24528,"n":"יצחק הלוי מספרד","f":"מרוון","b":"ראש ישיבת נרבונא, מגדולי חכמי ספרד. מתלמידיו - ר אברהם בן יצחק בעל \"האשכול\"."},{"i":24529,"n":"יצחק הלוי מספרד","f":"מרן","b":"מגדולי הראשונים,רבוותא קמאי"},{"i":24530,"n":"יצחק הלוי מספרד","k":"בעל תורת הבית","b":"בן אחיו של הרא\"ה. חיבר \"תורת הבית\" בדיני ממונות. מוזכר ב\"נימוקי יוסף\" לר יוסף חביבה."},{"i":24531,"n":"יצחק הלוי מפליבנה","b":"תלמיד ר אברהם שלום משלוניקי. רב קהלת הספרדים בפליבנה-שנות ה-ש'."},{"i":24532,"n":"יצחק הלוי מצפת","f":"משה","b":"מחכמי צפת בזמן ר יוסף קארו, חתם בשנת שיח על פסק דין. בשנת תח חתם על התקנה לשחרור תלמידי חכמים ממס."},{"i":24533,"n":"יצחק הלוי מצרפת","f":"יהודה","k":"בעל פענח רזא","b":"מחכמי צרפת-שנות ה-ק'. חיבר \"פענח רזא\" והוא לקוטים מפירושי הקדמונים ובהם בעלי התוספות. חיבר גם פיוטים."},{"i":24534,"n":"יצחק הלוי מקארוב","b":"רב בקארוב-תק\"מ"},{"i":24535,"n":"יצחק הלוי מקושטא","f":"משה","b":"נכד ר שמואל הלוי הזקן. רב בקושטא-תצ לאחר מהר\"י רוזניס. אחיו - ר שמואל הלוי מקושטא. נפטר צעיר."},{"i":24536,"n":"יצחק הלוי מקושטא","b":"משורר מחכמי קושטא-שנות ה-תק'. חיבר שירים שנדפסו בספרי חכמי דורו ובהם ב\"מעם לועז\", ו\"אותיות דרבי עקיבא\"."},{"i":24537,"n":"יצחק הלוי מקושטא הזקן","k":"בעל רב דגן","dt":"תקצב","b":"רב ודיין בקושטא-תקפד. תשובותיו בספרי חכמי דורו, וביניהם \"שמן המשחה\". חיבר שיטה שנדפסה ע\"י נכדו ר יצחק הלוי - תרכח."},{"i":24538,"n":"יצחק הלוי משלוניקי","f":"שלמה הלוי הזקן","k":"בעל באר מים חיים","dt":"שעו-ח - יח אלול","dp":"שלוניקי","b":"רב וראש ישיבה בק\"ק \"עץ חיים\" בשלוניקי-שע. הו\"ל את ספרי אביו. חתם על הסכמות הקהל-שעח. אחיו - ר יוסף-חתנו של ר יוסף הלוי. בנו - ר שלמה (השלישי). חיבר גם \"חשק שלמה\". נכדיו - ר מיכאל בן אברהם, ור מנחם בכור בן יעקב - הו\"ל את ספרו עם הקדמה מהם-תקמו. (לפי רוזניס תאריך פטירתו - שפא ובמקום אחר שפט)."},{"i":24539,"n":"יצחק הלוי משלוניקי","dt":"תה - כא תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24540,"n":"יצחק הלוי משלוניקי","f":"יעקב","k":"בעל באר מים חיים,מהר\"י סגל","dt":"תקיח - כג ניסן","dp":"שלוניקי","b":"דיין בשלוניקי, רב הכולל-תקיז על מקום ר יוסף ן ארדיט. תיקן תקנות רבות, הסכים על 12 ספרים. חיבר דרשות שאבדו. נכדיו הו\"ל מחדושיו בשם \"באר מים חיים\"."},{"i":24541,"n":"יצחק הלוי משלוניקי","dt":"תקצא - אחרי","b":"דיין בשלוניקי-תקצא."},{"i":24542,"n":"יצחק הלוי משלוניקי","f":"שלמה משלוניקי","dt":"שכו","dp":"שלוניקי","b":"רב קהלת פורטוגל בשלוניקי. נספד ע\"י הפייטן לונגו. אחיו: ר יעקב (שנזכר במכתב של ר יוסף קארו), ר יוסף-נפטר צעיר. בנו - ר שלמה הזקן משלוניקי."},{"i":24543,"n":"יצחק הלוי משלוניקי","f":"יעקב","k":"בעל באר מים חיים","dt":"תצח - בערך","dp":"שלוניקי","b":"נכד ר יצחק בעל באר מים חיים. דיין בשלוניקי. חיבר \"באר מים חיים\" (למעשה זהו ספר זקנו) ונדפס בידי נכדיו ר מנחם בן יעקב הלוי, ור מיכאל בן אברהם הלוי. בניו - ר יעקב, ר אברהם."},{"i":24544,"n":"יצחק הלוי סגל מלבוב","f":"שלמה חריף מלבוב","k":"חתן המהרש\"א","b":"נכד בעל \"שארית יוסף\". רב בלוצק-שץ, רימאנוב, לבוב-שצח על מקום אביו. נזכר ב\"טיב גיטין\". חתנו ר אליעזר מזלוטשוב."},{"i":24545,"n":"יצחק ה\"ן דוד ויוסף מפאס","b":"מחכמי פאס - שנות ה-ת'."},{"i":24546,"n":"יצחק הנזיר מספרד","b":"מגדולי המקובלים בתקופת הראשונים בספרד-ד'תת\"ק"},{"i":24547,"n":"יצחק הסופר","f":"יוסף","bp":"פורטוגל","b":"עלה לירושלים, העתיק ספר פירוש התורה לר יעקב בעל הטורים (בקולופון: התחיל בירושלים וסיים בצפת בשנת ה'קמט (כ\"י קהילת מנטובה)."},{"i":24548,"n":"יצחק הספרדי","f":"שמואל חיים","b":"תלמיד ודיין אצל בעל ספר האגור."},{"i":24549,"n":"יצחק הפייטן","f":"יוסף בן יצחק","b":"פייטן בצרפת-ד'תת. חיבר קרובות לשביעי של פסח, ומהם במחזור צרפת."},{"i":24550,"n":"יצחק הפייטן","f":"יקר","b":"פייטן קדמון, חיבר פיוטים וסליחות ובהם - \"אריד בשיחי בשיחי לנוחי\"."},{"i":24551,"n":"יצחק הפייטן","f":"שלום","b":"פייטן באשכנז-שנות ה-ד'תתק, חיבר פיוט \"אין כמוך באלמים\" על גזרות ד'תתקז. בנו - ר משה ונכדו - ר יצחק בעל אור זרוע."},{"i":24552,"n":"יצחק הפייטן","f":"סעדיה","b":"פייטן-שנות ה-ד'תתק. חיבר פיוט על צרות יהודי ירושלים מידי הנוצרים, אולי הוא מחבר הפיוט \"ידידי רבו כצמחי חקלי\"."},{"i":24553,"n":"יצחק הפייטן מנורבא","f":"מאיר","b":"פייטן-שנות ה-ד'תתק."},{"i":24554,"n":"יצחק הצרפתי מספרד","k":"בעל זרע אברהם","b":"מחכמי ספרד בזמן הריב\"ש. תלמיד ר פרץ הכהן, והיה במשא ומתן עם הריב\"ש."},{"i":24555,"n":"יצחק הקדוש מאשכנז","f":"אשר (הבחור השני)","b":"מחכמי אשכנז-שנות ה-ד'תתק. נזכר במרדכי, והגהות מימוניות. נהרג עק\"ה בוירצבורג. נולד ביום שנפטר ר יצחק בן אשר-הריב\"א וקראו עליו \"וזרח השמש ובא השמש\"."},{"i":24556,"n":"יצחק הקראי מקושטא","f":"תשבי","k":"בעל כליל יופי","b":"מחכמי הקראים בקושטא, הו\"ל \"כליל יופי\" לאהרן בן יוסף הרופא הקראי עם הוספות ממנו."},{"i":24557,"n":"יצחק הרופא","f":"מוקאתיל","b":"רופא חכם ופילוסוף, נזכר אצל ר ידעיה הבדרשי."},{"i":24558,"n":"יצחק הרופא משלוניקי","f":"אליהו","b":"רופא בשלוניקי-שנות ה-ש'."},{"i":24559,"n":"יצחק השנירי הפייטן משניר","f":"יהודה בן נתנאל מבלקי","b":"פייטן בבלקירי-ליד נרבונה, שניר-ד'תתקסח. נזכר אצל אלחריזי, ואצל ר אברהם בדרשי."},{"i":24560,"n":"יצחק זאב מיוזפוף","b":"רב ביוזעפאף-ת\"ר"},{"i":24561,"n":"יצחק זולקאוור","f":"יהודה ליב מוינא","b":"מחכמי זולקווא. אביו של ר אלחנן מבוצאץ."},{"i":24562,"n":"יצחק זליגמן הכהן מרוטרדם","f":"אברהם","k":"בעל מנחת עני","b":"ר\"מ ברוטרדם. בן דודו - ר יצחק זליג מברניבורג."},{"i":24563,"n":"יצחק זליגמן מירושלים","b":"מחכמי ירושלים, חתם על הסכמת המסים-רסט."},{"i":24564,"n":"יצחק זלקינד ממנוסטרישץ","b":"גביר במנוסטרישץ-תרד, פעל לטובת היהודים אצל הקיסר."},{"i":24565,"n":"יצחק זעלקא מבירז","f":"זאב","k":"בעל ים התלמוד","b":"מחכמי בירז-תק בערך. חיבר \"ים התלמוד\" זולקווא תקטו."},{"i":24566,"n":"יצחק זעלקא מוילנא","f":"דב בער","dt":"תקעז - ה סיון","dp":"וילנא","b":"נכד ר יעקב-בן דודו של בעל שאגת אריה, ונכד(-אבי אמו) ר בנימין בן בנימין מדיסנא. מצאצאי ר אלחנן ברלינר. חתן ר עוזר מבאבירשק - ואשתו היה בקיאה בדקדוק וחברה שירים. מראשי קהלת וילנא. בנו - ר אלחנן מוילנא-חותנו של ר יחזקאל פיבל מוילנא בעל \"תולדות אדם\". נכדו - ר שלמה זלמן זלקינד בן ר יהושע בן זעלקא."},{"i":24567,"n":"יצחק חבר משלוניקי","b":"רב בשלוניקי. בשנת שמב היה מחלוקת בגלל שסירב לדרוש מדי שבת כרבנים שקדמו לו ר יעקב סמו\"ט ור שמואל קלעי - מוזכר ברשד\"מ."},{"i":24568,"n":"יצחק חבר משלוניקי","b":"דיין בשלוניקי-שנח, וסופר."},{"i":24569,"n":"יצחק חיים דוד עזרא","b":"מחכמי חברון בשנת תריא."},{"i":24570,"n":"יצחק חיים מירושלים","b":"מגדולי הדיינים בירושלים-ת\"ר"},{"i":24571,"n":"יצחק חיים מרוזוודוב","b":"רב ברוזוודוב-תרנד."},{"i":24572,"n":"יצחק יהודה ליב מגיד מפרוסניץ","f":"ישעיה","dt":"תקמט","b":"רב בגויטיין, מיזלאב, מיסליץ-תקכא. מתורתו בקובץ 'פעמי יעקב'-תשנא."},{"i":24573,"n":"יצחק יהודה ליב מוילנא","f":"יחיאל מיכל מזעטל","dt":"תריד - ה חשון","dp":"וילנא","b":"חתן ר יעקב רפפורט ממזיבוז בן ר זלמן פרלס מברוד. בנו הגביר ר זלמן זעטל. חתנו ר יצחק לנדא וארשעווער (ואחר שנפטר נישאה לרש\"ש מוילנא), ר שלמה משה בן יעקב לוטצינר, ר ברוך בן משה ישעיה פריווער, ר אליעזר-בנו חורגו של ר אריה ליב צונץ, ר מנחם אליעזר בן לוי דוד גינסטלינג."},{"i":24574,"n":"יצחק יהודה מטפליק","b":"נהג באדמורות, התקרב לר נחמן מברסלב והפך לחסידו ועזב אדמורותו. \"אהל\" נבנה על קברו."},{"i":24575,"n":"יצחק יהושע מקרליץ","k":"בעל בית ישראל","b":"רב בקרליץ,מיר תק\"פ"},{"i":24576,"n":"יצחק יוסף הכהן מירושלים","f":"אברהם","dt":"תרך - ו תמוז","dp":"ירושלים","b":"מחכמי ירושלים. כנראה הוא שהיה הבורר מטעם המדפיס ישראל בק במחלוקת עם משפחת אלקלעי, ונזכר ב\"זכרון לחובבים הראשונים\" יא."},{"i":24577,"n":"יצחק יוסף משלוניקי","dt":"תפו","dp":"שלוניקי","b":"רב בשלוניקי."},{"i":24578,"n":"יצחק יעקב מגרנוב","f":"מרדכי מקרמניץ","k":"אדמור מגרנוב","b":"נכד המגיד מזלוטושוב. חתן ר שלום שכנא מפרוהביטש (ריזין). בנו ר שלום - חתןר אליעזר זאב מבוצאץ."},{"i":24579,"n":"יצחק יעקב מוילנא","f":"עקיבא","b":"דיין בוילנא, חתם-תפח עם ר יהודה מטיקטין."},{"i":24580,"n":"יצחק יעקב מטומשפיל","k":"אדמור מטומשפיל","b":"תלמיד ר משה צבי מסאווראן, אדמור בטומשפיל אחר פטירת רבו. מתורתו ב\"צבי לצדיק\"."},{"i":24581,"n":"יצחק יעקב מירושלים (וחסלביץ?)","f":"מאיר","b":"מחכמי ירושלים, חתם-תרכג כנגד ר\"מ ירושלמסקי, נזכר ב\"אמת ומשפט\". בשליחות \"עץ חיים\"-תרלג, ותרלט בסיביר ואנגליה."},{"i":24582,"n":"יצחק יעקב מפוריצק","f":"יוסף יאסקי","b":"רב בפאריצק-תק\"מ"},{"i":24583,"n":"יצחק יעקב מקראקא","b":"שו\"ב בקראקא בזמן הרמ\"א. חיבר יחד עם חברו ר שמואל מזייא - הגהות ל\"שחיטות ובדיקות\" להר\"י ווייל. בנו ר צבי הזכירו בהערותיו לשחיטות ובדיקות."},{"i":24584,"n":"יצחק יעקב קאפיל מלובלין","f":"יוסף אהרן פרץ יהודה","dt":"תז - א ניסן","dp":"לובלין","b":"אביו היה מלויצק. מחכמי לובלין."},{"i":24585,"n":"יצחק ישורון מהמבורג","k":"בעל פנים חדשות","dp":"המבורג","b":"רב קהלת הספרדים בהמבורג- שנות ה-ת', תשובה אליו ב\"דבר שמואל\". נוסח מצבתו בידי ר יוסף פרנסיס מהמבורג."},{"i":24586,"n":"יצחק ישכר מזולקוא","f":"חנוך אברהם","dt":"שצח - יב ניסן","dp":"זולקוא","b":"ר\"מ בזולקוא. חתן ר שלמה."},{"i":24587,"n":"יצחק ישראל איסר אוריסזאהן","f":"משלם זלמן מוילנא","k":"יצחק ר זלמן ר אורי'ס","dt":"תריח - יז שבט","dp":"וילנא","b":"בן לר זלמן ר אורי'ס-פרנס בוילנא, ונותר יחיד לאביו מ-23 בנים שמתו על פניו. חתן ר צבי הירש המכונה - \"ר הירש ר בערש\" מוילנא, ובזיוו\"ש חתן ר הירש עטיאש מוילנא. מחכמי וילנא וגבאי ביה\"ח הגדול. היה נאמן על כל הציבור והפקידו אצלו פקדונות בסך כ-300,000 רובל וקראוהו \"ארון ברזל\". בניו ר דב בער, מוילנא ר אברהם מדוברוונא. חתניו: ר אברהם שיסקעס, הגביר ר שלום יונה שחור, ר זלמן זאב מוילנא."},{"i":24588,"n":"יצחק לאזדינער מאיוויניץ","b":"תלמיד ר חיים מוולוזין. חתנו - ר שמואל חיים סלומונוב, ונכדו ר מרדכי סולומונוב ממינסק."},{"i":24589,"n":"יצחק לוי ממודנא","b":"מגדולי חכמי איטליה במודנא"},{"i":24590,"n":"יצחק לוי ממרוקו","dp":"תאמאינת אל-פוקיא","b":"מחכמי ארץ ישראל, הגיע למרוקו בתחילת המאה ה-19, ונרצח בידי ערבים בדרכו בתארודאנת-מרוקו."},{"i":24591,"n":"יצחק לינץ או לינק","f":"אליקים","k":"מפפד\"מ","b":"רב בפפד\"מ-אחרי רסו, ור אליעזר טריווש על מקומו אחריו. השתתף באסיפת רבנים בוורמייזא-שב ושם קיבלו החלטה שלא ניתן לבן קהילה אחד לתבוע את חברו בן הקהילה בבי\"ד שמחוץ לקהילה. בזמנו-רסט היתה החרמת ספרי קדש בכמה קהילות ובהם פפד\"מ - ולבסוף הוחזרו."},{"i":24592,"n":"יצחק מאדרינופול","f":"מרדכי","b":"דיין באדרינופול, חתם-תקעח עם ר יהושע גירון ור אהרן קניטי."},{"i":24593,"n":"יצחק מאוזרוב","b":"מג\"מ באוזרוב-תק\"ע"},{"i":24594,"n":"יצחק מאוזרוב","b":"תלמיד ר אלימלך מליזנסק. החוזה מלובלין והמגיד מקוזניץ היה נוהגים לנסוע אליו."},{"i":24595,"n":"יצחק מאוסטרהא","f":"יעקא","dt":"תן - כח תמוז","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":24596,"n":"יצחק מאוסטרהא","f":"יהודה","dt":"תק.. - כא ניסן","dp":"אוסטרהא","b":"פרנס באוסטרהא-תפט עם ר מרדכי בן ר יעקב ר שמואל'ס ור נפתלי הרץ בן יואל פיבש. היה גם ר יצחק בן יהודה סגל שהיה לוי וכנראה לא אותו האיש."},{"i":24597,"n":"יצחק מאוסטרהא","f":"מנחם מנדל מאוסטרהא","dt":"תקן - א אלול","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אביו של ר מנחם מנדל יאנויווער מאוסטרהא."},{"i":24598,"n":"יצחק מאוסטרהא","f":"יעקב הקדוש","dt":"תקף - יד אייר","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אולי בנו של ר יעקב בן חנוך הניך מאוסטרהא או בנו של ר יעקב הקדוש הנזכר בפנקס ח\"ק ולא ידוע עליו."},{"i":24599,"n":"יצחק מאוסטרהא","f":"דוד מקראקא","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":24600,"n":"יצחק מאופנהיים","k":"רבינו יצחק מאופנהיים","b":"מגדולי חכמי אשכנז-ד'תתק\"צ"},{"i":24601,"n":"יצחק מאורבילי","k":"בעל ספר מנהל","b":"תלמיד ר חיים מבלויאש. מגדולי חכמי צרפת-שנת פ', פוסק, מרביץ תורה."},{"i":24602,"n":"יצחק מאיברא","b":"מגדולי חכמי נורמנדיה-שנת כ',מבעלי התוספות"},{"i":24603,"n":"יצחק מאיווניץ","b":"רב באיווניץ-תק\"מ"},{"i":24604,"n":"יצחק מאיר מגלוגא","dt":"תקפד - א אדר","b":"רב בגלוגא"},{"i":24605,"n":"יצחק מאיר מקאפוטשניץ","f":"אברהם יהושע העשל","k":"יצחק מאיר מקאפוטשניץ","b":"רב בקאפוטשניץ"},{"i":24606,"n":"יצחק מאיר מקאפוטשניץ","f":"זושא מזינקוב","bt":"תרכב","dt":"תרצו - ב תשרי","b":"אדמו\"ר מקאפיטשניץ"},{"i":24607,"n":"יצחק מאיר מראשקוב","f":"שלמה זלמינא"},{"i":24608,"n":"יצחק מאלגיר","bt":"קל","dt":"ר - בערך","b":"רב בתנס-אלגיר. נזכר בשו\"ת הריב\"ש."},{"i":24609,"n":"יצחק מאלגיר","bt":"ש","dt":"שע - בערך","b":"רב באלגיר. שאלות ממנו לר אברהם ן טוואה ונזכר ב\"חוט המשולש\"."},{"i":24610,"n":"יצחק מאליסנה","k":"מפרש המקרא","b":"מגדולי חכמי ספרד-ד'תש\"ל,משורר,מפרש מקרא"},{"i":24611,"n":"יצחק מאליסנה-ספרד","f":"לוי בן שאול","b":"מדקדק מחכמי ספרד-שנות ה-ד'תש, נזכר אצל ר יונה ן ג'נאח. חיבר בקשה \"אלוה אל תדינני\" ונכנסה למחזורים."},{"i":24612,"n":"יצחק מאסאראן","b":"דיין בשלוניקי אצל ר יצחק ן שאנגי - שהביא מתורתו בספרו \"באר לחי רואי\"."},{"i":24613,"n":"יצחק מאפטא","k":"בעל מכלל יופי","b":"מג\"מ באפטא-תק\"ל"},{"i":24614,"n":"יצחק מאפטא","f":"בן ציון","k":"בעל מכלל יופי","b":"מגיד באפטא."},{"i":24615,"n":"יצחק מאפימין משלוניקי","dt":"שפא - יא ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24616,"n":"יצחק מאשכנז","f":"מנחם","b":"מגדולי רבני אשכנז-שנת ל'"},{"i":24617,"n":"יצחק מבאקוי-רומניה","b":"רב בבאקוי-רומניה-תרטז."},{"i":24618,"n":"יצחק מבגדד","f":"ישראל","b":"גדול בחכמה ופיוט,ראש ישיבת בגדד-שנת כ'"},{"i":24619,"n":"יצחק מבגדד","b":"גביר מחכמי בגדד-תצו, עוזרו של ר משה בנימין - רבה של בגדד. (אולי בן למשפחת יהודה)."},{"i":24620,"n":"יצחק מבורשטשוב","f":"חיים","b":"רב בבורשטשוב-תריז."},{"i":24621,"n":"יצחק מביאליסטוק","f":"חיים","k":"הו\"ל ברית עולם","b":"נכד ר יצחק אשכנזי מבעליצא, והו\"ל את ספר זקנו \"ברית עולם\"-וילנא תקף."},{"i":24622,"n":"יצחק מביטשעטשי וצפת","b":"דיין בצפת-תרלב אצל ר רפאל זילברמן."},{"i":24623,"n":"יצחק מבילקמין","f":"בנימין בונם מטרניגרד","dt":"תקכג - ז אייר","dp":"לובלין","b":"אב\"ד בילקמין."},{"i":24624,"n":"יצחק מבלז","b":"אב\"ד בלז. תלמידו - ר משה הכהן בוכנר בעל \"קרן אור\". זקנו של רח\"ה מאלסק."},{"i":24625,"n":"יצחק מברוד","f":"מנשה","b":"רב בברודי. תשובה אליו \"בית אפרים\"."},{"i":24626,"n":"יצחק מברוכזלדה","b":"רב בפפד\"מ. חתם-מח על תעודה עם חברו ר אנזלם."},{"i":24627,"n":"יצחק מבריסל","b":"רב בבריסל-שנות ה-תק', פגש את החיד\"א שעבר שם."},{"i":24628,"n":"יצחק מבריסק","f":"חיים מקמניץ","k":"בעל עלי הדס","bt":"תקנג","dt":"תרלה - כו ניסן","dp":"בריסק","b":"ראב\"ד בבריסק-תרו בזמן רבנות ר צבי הירש אורנשטין. חיבר גם \"ענפי הדס\" - בכת\"י."},{"i":24629,"n":"יצחק מבריסק ולבוב","b":"דיין בלבוב, חתם-תנה בפנקס הקהלה."},{"i":24630,"n":"יצחק מגריידינג","f":"דוד קמניצר"},{"i":24631,"n":"יצחק מדורא","f":"מאיר","k":"בעל שערי דורא","b":"מגדולי הפוסקים וממעצבי ההלכה בחכמי אשכנז, מרביץ תורה בדורא-שנת ה'צב."},{"i":24632,"n":"יצחק מדמשק","f":"דוד מסעוד","b":"מחכמי דמשק, עלה לצפת והיה חבר בבית דינו של ר יוסף קארו."},{"i":24633,"n":"יצחק מדמשק וירושלים","f":"חיים","b":"מחכמי דמשק, עלה לירושלים. חברו של ר יעקב בירב."},{"i":24634,"n":"יצחק מדנפייר","f":"שמואל","k":"ר\"י הזקן","dt":"ד'תתקנ","b":"על תקופת ר' יצחק דמן עכו, נלמד מכך שהעידו לפניו על אמיתות הזוהר בשנת ה'סה. היה תלמיד הרמב\"ן והרשב\"א והריטב\"א.","bk":[["ר\"י הזקן (ריב\"ש)",""],["מאירת עינים (רבינו יצחק דמן עכו)",""]]},{"i":24635,"n":"יצחק מדנפירא","b":"עק\"ה,מגדולי הראשונים,גדול דורו בחכמה וקדושה-ד'תתקמ\"ד. נכד אחות רש\"י."},{"i":24636,"n":"יצחק מדרוהוביטש","f":"יוסף ספראוידליוער","dt":"תקד-יב - ז ניסן","dp":"הורחוב","b":"מחכמי הקלויז של ברוד - היה מעשרה בטלנים שהחזיק ר יוסף יוזפא, מ\"מ בביהכ\"נ ר יוזפא. מגדולי תלמידי הבעשט. חתן נכדת ר מאיר פאפירש. אביו של המגיד מזלוטשוב. דיין אצל ה\"נודע ביהודה\". רב באוסטרהא, ברודי, מוכיח בדרוהוביטש, הורחוב(=חארחוב). מתורתו בספר \"תולדות יצחק\" בתוך \"תורת חסידים הראשונים\". תולדותיו ב\"תועפות הרים\"."},{"i":24637,"n":"יצחק מהאזנפוט","b":"רב בהאזנפוט-תקצה בערך על מקום ר יחיאל מיכל בן אריה, ועזב בגלל מחלוקת."},{"i":24638,"n":"יצחק מהאנוי","f":"ישראל","b":"רב בהענוי-תקכ."},{"i":24639,"n":"יצחק מהמבורג","f":"נתן","dt":"תפג - טז תשרי","dp":"אלטונא","b":"דיין בהמבורג (זמני) על מקום ר משה רוטנבורג ור יחזקאל קצנלנבוגן על מקומו."},{"i":24640,"n":"יצחק מואבולניק","b":"רב בואבולניק על מקום ר משה חריף-בשנות הת\"ר.."},{"i":24641,"n":"יצחק מואלאדובה ולבוב","f":"אברהם","b":"ספרא ודיינא בולאדיווי(=ולאדובה), חתם-תקכח על שטר מכירה בלבוב."},{"i":24642,"n":"יצחק מוארט, המבורג","k":"יצחק וארטר","dt":"תקמח - יב ניסן","dp":"אלטונא","b":"רב בפולין, ווארט, מחכמי הקלויז של ר יחיאל ואליך בהמבורג (אחד משלושת הלומדים הראשונים)."},{"i":24643,"n":"יצחק מוארשא","b":"מו\"צ בוורשה-תר\"מ"},{"i":24644,"n":"יצחק מוולוזין הנכד","f":"חיים מוולוזין","k":"בעל מילי דאבות","bt":"תקמ","bp":"וולוזין","dt":"תרט - כו אייר","dp":"איוווניץ","b":"אב\"ד ראש ישיבת וולוזין על מקום אביו. מנהיג יהודי רוסיה, וראש המדברים באספות בעניני הכלל. השתתף בועדת הרבנים-תרד שהוקמה ע\"י הממשלה הרוסית. חיבר גם \"פה קדוש. מחתניו: ר מאיר גינצבורג."},{"i":24645,"n":"יצחק מוולוזין הסבא","dt":"תקמ - יב אב","dp":"וילנא","b":"מגדולי חכמי וילנא. אביו של ר חיים מוולוזין, ר שמחה מנישויז, ר שלמה זלמן מוילנא, ר יוסף מפאריץ, ר נחמן מפאהאסט. חתן ר יוסף רפפורט מפיעסק."},{"i":24646,"n":"יצחק מוונגרוב-מזריטש","k":"אדמור מוונגרוב","dt":"תקפו - יד אב","b":"תלמיד החוזה מלובלין, ואחריו חסיד ר שמואל מקאריב. רב ואדמור בוונגרוב."},{"i":24647,"n":"יצחק מווראניק","b":"רב בוורניק-תקמ, מחכמי ביהמ\"ד של ר יחיאל ואליך בהמבורג."},{"i":24648,"n":"יצחק מויטקוב","b":"אב\"ד ויטקוב."},{"i":24649,"n":"יצחק מוילנא","f":"בנימין בינוש","bt":"תקעב","dt":"תרכד - יג אד\"ב","dp":"וילנא?","b":"ר\"מ בישיבת מייליס בוילנא."},{"i":24650,"n":"יצחק מוילנא","f":"שמואל","dt":"תקנא","dp":"וילנא","b":"גביר נדבן בוילנא."},{"i":24651,"n":"יצחק מוילנא","f":"יהודה ליב","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":24652,"n":"יצחק מוילנא","f":"אריה ליב הקדוש","dt":"תקנב - כו סיון","dp":"וילנא","b":"מחכמי וילנא."},{"i":24653,"n":"יצחק מוילנא","f":"יהודה","dt":"תקסג - ט שבט","dp":"וילנא","b":"מחכמי וילנא."},{"i":24654,"n":"יצחק מוילנא","f":"שבתי שעפסיל","dt":"תקסב - יח ניסן","dp":"וילנא","b":"מחכמי וילנא."},{"i":24655,"n":"יצחק מוינה","f":"יחזקאל (יחיאל)","b":"בנו - ר יחיאל ונכדו ר מרדכי יולס מקראקא."},{"i":24656,"n":"יצחק מורמייזא","b":"מגדולי חכמי וורמס-ש\"כ"},{"i":24657,"n":"יצחק מזאמושט","f":"אברהם","b":"מחכמי זאמושט. מתורתו בספר בנו - ר אברהם הכהן מטורלא בעל \"בית אברהם\" - \"מנחה בלולה\"."},{"i":24658,"n":"יצחק מזולקוא","f":"יעקב","b":"מגדולי חכמי זלקווא-ת\"ל"},{"i":24659,"n":"יצחק מזולקוא","f":"יונה","dt":"תז - כא חשון","dp":"זולקוא","b":"מחכמי זולקוא."},{"i":24660,"n":"יצחק מזולקוא","f":"שמעון וולף","b":"מחכמי זולקוא, חתם-תעו בפנקס הקהלה על תקנה שלא יהיה אחד מקרובי האב\"ד ממנהיגי הקהלה."},{"i":24661,"n":"יצחק מזולקוא","f":"שמואל זנויל מזולקוא","b":"נכד(-אבי אמו) ר נפתלי כץ מלובלין. בנו - ר נחמן מהורודנקא. חתנו - ר אברהם אבלי-אב\"ד זולקוא."},{"i":24662,"n":"יצחק מז'וסלי(=זאסלי) - וילנא","f":"שלמה זלמן","b":"מקובל, רב בזסלי-תקמ ובנו ר דוד על מקומו אחריו, וילנא. הניח חבור על התורה - בכת\"י ובה חישב את זמן הגאולה - תקעב."},{"i":24663,"n":"יצחק מזמוטשט","b":"דיין באמסטרדם-תס\"ז"},{"i":24664,"n":"יצחק מחווידאן","b":"רב בחווידאן(=קונסטנטינובה)-תרמג."},{"i":24665,"n":"יצחק מחומסק","b":"רב בחומסק. בנו - ר יוסף - \"חומסקער עילוי\"."},{"i":24666,"n":"יצחק מחטשיוואטע","b":"תלמיד ר נחמן מברסלב."},{"i":24667,"n":"יצחק מחסלביץ וצפת","k":"יצחק חסלביצר","dt":"תקצ","b":"מראשוני העולים לצפת"},{"i":24668,"n":"יצחק מטוטשין","dt":"תקעב - יח ניסן","b":"רב בטוטשין"},{"i":24669,"n":"יצחק מטולדו","f":"ישוש","k":"בעל הצרופים","b":"מחכמי ספרד ובקי בדקדוק, נזכר בפירוש הראב\"ע וסיפר שחיבר ספר הצרופים."},{"i":24670,"n":"יצחק מטורנא","f":"יעקב חיים מלובלין","b":"חתן ר משה מלבוב. רב בטארנא-תק\"ל. חתניו - ר חיים הוכגלרנטר אב\"ד הרובשוב, ר יעקב רובין."},{"i":24671,"n":"יצחק מטיסמניץ","b":"רב בטיסמניץ"},{"i":24672,"n":"יצחק מטיקטין","b":"רב בברעסלו-תק\"ע"},{"i":24673,"n":"יצחק מטריפולי","k":"בעל זרע יצחק","b":"רב בטריפולי-תרל\"ה"},{"i":24674,"n":"יצחק מטרמבובלה","f":"אברהם","b":"רב בטרמבובלה."},{"i":24675,"n":"יצחק מיאנוב","f":"דוד","k":"בעל בני יצחק זוטא","dp":"תקו - אחרי","b":"רב ביאנוב-תס, ובנו ר זאב וולף על מקומו אחריו."},{"i":24676,"n":"יצחק מיאניוויטש","dp":"אולע","b":"תלמיד בעל התניא. בנו ר שמריהו זוקובר מדוברומיסלא-מחשובי חסידי חב\"ד."},{"i":24677,"n":"יצחק מיולאווע","b":"רב ביולאווע-תרמ\"ב"},{"i":24678,"n":"יצחק מיכל אליהו הכהן מירושלים","f":"אליעזר מיאסווין-זאמו","bt":"תקצט","bp":"יוסוואין","dt":"תרעד - אלול","dp":"ירושלים","b":"אביו היה רבה של יוסוואין. עלה לירושלים-תרח עם הוריו וגדל אצל קרובו ר דב הכהן שהיה ראש השוחטים בירושלים, ולמד מלאכת השו\"ב. סופר כולל וילנא וזאמוט, וסופר \"משגב לדך\". מעורכי \"הלבנון\", ו\"האריאל\", סופר \"כולל וילנא וזאמוט\", סופר ב\"משגב לדך\". הו\"ל \"הלבנון\" עם בריל וסלומון. היה מבין שבעת מיסדי שכונת נחלת שבעה בירושלים."},{"i":24679,"n":"יצחק מירושלים","k":"שיך יצחק","b":"רב קהלת המסתערבים בירושלים-רפב, היה החכם הרשמי בזמן השלטון המצרי."},{"i":24680,"n":"יצחק מירושלים","f":"יוסף","dt":"תר - יז תשרי","dp":"ירושלים","b":"חתן ר ישיעה מסלונים. מחכמי ירושלים."},{"i":24681,"n":"יצחק מלאריסה","f":"דוד","b":"רב בלאריסה - בדור שלאחר הגירוש."},{"i":24682,"n":"יצחק מלבוב","f":"שמואל","dt":"תכד - ח אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה (באוצר הרבנים תאריך פטירתו - ה סיון)."},{"i":24683,"n":"יצחק מלבוב","f":"חלפון יצחק לבטון","b":"דרשן,רב בלבוב"},{"i":24684,"n":"יצחק מלבוב","f":"יעקב","dt":"תכד - ח אייר","dp":"לבוב","b":"מחכמי לבוב. נהרג עק\"ה עם אחיו זכריה. (היו עוד 2 חכמים שנקראו באותו השם שנהרגו גם הם באותו היום בלבוב)."},{"i":24685,"n":"יצחק מלבוב","f":"אליהו ד\"ש","dt":"תכד - יד אייר","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה עם אחיו ר אליעזר."},{"i":24686,"n":"יצחק מלבוב","f":"שמואל","dt":"תסג - ג כסלו","dp":"לבוב","b":"ר\"מ בלבוב. נהרג עק\"ה."},{"i":24687,"n":"יצחק מלבוב","f":"יהודה ליב מירושלים","dt":"תג - יב חשון","dp":"לבוב","b":"גביר מחכמי לבוב. חתנו - ר אהרן בן בנימין סגל."},{"i":24688,"n":"יצחק מלבוב","f":"מרדכי","dt":"תכד - ה סיון","dp":"לבוב","b":"רב בלבוב."},{"i":24689,"n":"יצחק מלבוב","f":"אשר למל","dp":"לבוב","b":"ר\"מ בכמה קהלות, מרביץ תורה בלבוב."},{"i":24690,"n":"יצחק מלבוב","f":"יוסף","b":"מו\"צ ואב\"ד בלבוב, חתם-תסא על תקנות הקהלה (זולקוא) עם ראשי קהלת לבוב."},{"i":24691,"n":"יצחק מלבוב","f":"מנחם מאניש","b":"מראשי קהלת לבוב (אחד משבעת טובי העיר), חתם-תצג בפנקס הקהלה."},{"i":24692,"n":"יצחק מלבוב","f":"שמעיה","b":"פרנס ומנהיג בלבוב, חתם-תקד על כרוז ותקנה."},{"i":24693,"n":"יצחק מלבוב","f":"אברהם","b":"דרשן בלבוב. נזכר בשו\"ת מהר\"ם מלובלין, ובמגן אברהם. בנו - ר נפתלי צבי הירש ונכדו - ר בנימין ביניש מפוזנא, ומצאצאיו גם - ר דוד טבלי בעל \"שערי ציון\". יש אומרים שבנו גם - ר זכריה מנדל."},{"i":24694,"n":"יצחק מלבוב","f":"שמעון","b":"מנהיג בלבוב, חתם-תקד על כרוז ותקנה, ועוד."},{"i":24695,"n":"יצחק מלובאוונא","b":"תלמיד ר מרדכי מנסכיז."},{"i":24696,"n":"יצחק מלובאשוב","f":"אברהם יוסף אבא מלובא","b":"רב בליבעשוב(=לובאשוב)-פלך מינסק-תרי על מקום אביו. בנו - ר אריה ליב מלובאשוב."},{"i":24697,"n":"יצחק מלובלין","f":"חנוך הניך","dt":"תקח - יח כסלו","b":"דרשן,מגיד בלובלין"},{"i":24698,"n":"יצחק מלובלין","f":"פנחס","dt":"תצט - ט ניסן","b":"מחכמי לובלין."},{"i":24699,"n":"יצחק מלובלין","f":"צבי הירש","dt":"תקלא - ז טבת","dp":"לובלין","b":"מחכמי לובלין."},{"i":24700,"n":"יצחק מלודמיר","f":"בצלאל","k":"ר יצחק בצלאלש","b":"מגדולי חכמי דורו ,רב בלודמיר-שנות ה-ש'. הסכים על כמה מפסקי המהרש\"ל. זקנו של הט\"ז."},{"i":24701,"n":"יצחק מלויצק ולבוב","b":"מראשי קהלת לבוב (אחד משבעת טובי העיר), חתם-תצז בענין חזקת מבוא."},{"i":24702,"n":"יצחק מלוניל","f":"זרחיה","b":"פילוסוף ומשורר מחכמי לוניל. היה מתומכי הרמב\"ם בזמן המחלוקת של ר שלמה מן ההר. חיבר שיר כנגד ר מאיר נורבוני שיצא כנגד הרמב\"ם, ונגד ר משולם בן שלמה דפיירה, והנשיא ר יהודה אלפכר ממתנגדי הרמב\"ם."},{"i":24703,"n":"יצחק מלייזעווע","b":"רב בלייזעווע-תרמ\"ב"},{"i":24704,"n":"יצחק מלעכוויץ","f":"פייבל","b":"רב בלעכוויץ"},{"i":24705,"n":"יצחק מלשקוביץ","b":"שו\"ב בלשקוביץ-תרס."},{"i":24706,"n":"יצחק ממאראטש-ליטא","b":"רב במאראטש, ור דוד ולפה על מקומו אחריו."},{"i":24707,"n":"יצחק ממגניסיאה","f":"דוד","b":"מחכמי מגניסיאה-שנות ה-ת' (אחר פטירת ר משה עוזיאל)."},{"i":24708,"n":"יצחק ממגנצא","f":"רבינו אבון הגדול","k":"ר' יצחק החסיד","b":"מגדולי חכמי מגנצא-ד'תש\"כ"},{"i":24709,"n":"יצחק ממגנצא","f":"יהודה","b":"תלמיד ר אליעזר הגדול. מגדולי חכמי התורה באשכנז, מגאוני לותר, מחכמי וורמייזא, ראש ישיבת מגנצא-ד'תתי. אולי תלמיד רבנו גרשום מאור הגולה. רבו וקרובו של רש\"י ונזכר בפירושיו."},{"i":24710,"n":"יצחק ממוגנדורף","b":"רב במוגנדורף-תרכ\"ד"},{"i":24711,"n":"יצחק ממזריטש","f":"נח","k":"בעל ספר זכרון על שוע","b":"חיבר ספר זכרון על שו\"ע."},{"i":24712,"n":"יצחק ממיטאוי","f":"יהודה","b":"פעל להקמת חברא קדישא במיטאוי-תץ. (היה יהודי נוסף בשם זה במיטאוי - נפטר בתקפב)."},{"i":24713,"n":"יצחק ממיטאוי","f":"יהודה","b":"מחכמי מיטאוי. פעל לקבלת רשיון ליסוד בית קברות וחברא קדישא במיטאוי."},{"i":24714,"n":"יצחק ממינסק","f":"צבי הירש","dt":"תרכד - כח אדר","dp":"מינסק","b":"רב במינסק."},{"i":24715,"n":"יצחק ממצרים","f":"ששון","b":"דיין בבית דינו של הרמבם במצרים, חתם על חרם הרמבם בד'תתקמז נגד פרצות בטהרת המשפחה. בנו ר מנחם."},{"i":24716,"n":"יצחק ממצרים","f":"ראובן","b":"ג'יליבי במצרים-תיב על מקום ר יעקב ביבאס, והוסר ממשרתו, ור רפאל יוסף ברהין על מקומו אחריו."},{"i":24717,"n":"יצחק מנחם","f":"ישראל מלעטשוב","b":"רב בלעטשוב-תר\"כ"},{"i":24718,"n":"יצחק מנחם הכהן","f":"שלום צבי הכהן","b":"מו\"צ בזאגרש-תר\"ס"},{"i":24719,"n":"יצחק מנחם משלוניקי","dt":"תב - ו ניסן","dp":"שלוניקי","b":"תלמיד ישיבת ר שלמה ן מאיור. מחכמי שלוניקי."},{"i":24720,"n":"יצחק מנרבונה","f":"שמואל","b":"חיבר פירוש לדברי הימים המיוחס לרש\"י, אולי הוא הפייטן שחיבר יוצר לחנוכה ופסח וסליחות, ואולי הוא שחיבר לוחות בחשבון המולדות."},{"i":24721,"n":"יצחק מנרבונה","f":"אברהם","b":"מחכמי נרבונה-שנות ה-ה'א. חיבר פירוש על הלכות רב אלפס, ונזכר במאירי."},{"i":24722,"n":"יצחק מנשה","b":"נזכר בפירוש המכילתא לר רפאל ביטראן."},{"i":24723,"n":"יצחק מנשה ממצרים","b":"ג'יליבי במצרים."},{"i":24724,"n":"יצחק מסאוורי","k":"חתן ר' ישראל מרוזין","b":"רב בסאוורי-תר\"כ"},{"i":24725,"n":"יצחק מסאסלב וזולקוא","b":"אב\"ד סאסלב-ווהלין, עבר לזולקוא וכיהן כמניד ובנו ר פסח על מקומו אחריו. גיסו - ר שמשון אוסטרופולר."},{"i":24726,"n":"יצחק מסוקולוב","b":"רב-שנת תר\"מ"},{"i":24727,"n":"יצחק מסימפונטי","f":"מלכי צדק","b":"חיבר פירוש למשנה, בזמן רש\"י."},{"i":24728,"n":"יצחק מסלונים","b":"חתן ר אלעזר קעלין בעל \"אור חדש\". אב\"ד באמסטיבאווע, סלונים-תקצ. אחיו - ר צבי הירש-אביו של ר אריה ליב פינס מראזינאי."},{"i":24729,"n":"יצחק מספרד","f":"אליעזר","b":"פוסק,מרביץ תורה בספרד"},{"i":24730,"n":"יצחק מספרד","f":"טודרוס","b":"מגדולי המקובלים בחכמי ספרד-שנת ע'"},{"i":24731,"n":"יצחק מספרד","f":"יהודה","b":"מגדולי ספרד-שנת ע'"},{"i":24732,"n":"יצחק מספרד","f":"ברכיה","b":"מחכמי ספרד בדור השביעי, אביו ר ברכיה היה אחיו של הרז\"ה בעל המאור, ושל הריב\"ב (ר יהודה בר ברכיה). הסכמה ממנו על אגרת הרמבן."},{"i":24733,"n":"יצחק מספרד","f":"ישראל","b":"פייטן בספרד-שנות ה-ק'. חיבר תוכחה \"הנשמה לך והגוף פעל צור אין דומה לך\", מפיוטיו במחזור אלגיר."},{"i":24734,"n":"יצחק מספרד וקושטא","f":"משה עלי","k":"בעל ספר החשבון","bt":"רלה","bp":"אוריאלה-ספרד","dt":"שיד - אחרי","b":"מחכמי ספרד, עבר לאחר הגירוש לקושטא."},{"i":24735,"n":"יצחק מסקוליע","b":"שו\"ב בסקוליע-תרכו."},{"i":24736,"n":"יצחק מסקידל","f":"ברוך כץ","k":"בעל בית יצחק","b":"רב בוואלפא, סקידל, אוסטרהא. חתם-תקמה עם ר שבתי איזנשטט משערשוב. חתנו - ר חיים הלפרין משארשוב, בנו - ר חיים."},{"i":24737,"n":"יצחק מעדנבורג","b":"רב בעדנבורג-ר\"ס"},{"i":24738,"n":"יצחק מעיר חדש","f":"משה חיים אפרים","dt":"תכ - כ חשון","b":"רב בעיר חדש,ראב\"ד בקרקארב בקאליס-תק\"ס"},{"i":24739,"n":"יצחק מעכו","f":"יצחק","b":"מחכמי עכו, בשנת ד'תתקצד (1234) חתם בהסכמה לתקנות ר אברהם בן הרמבם."},{"i":24740,"n":"יצחק מפאס","f":"שלום (שלם)","k":"בעל פסקי דינים","b":"רב בפאס, חתם על פס\"ד-שנא. נזכר ב\"זכות אבות\", ו\"כרם חמר\"."},{"i":24741,"n":"יצחק מפדובה","f":"יעקב מתתיה","b":"נזכר בספר זכרון נשמות גאוני פדובה."},{"i":24742,"n":"יצחק מפוזנא","f":"יעקב מרדכי מפוזנא","b":"דיין בפוזנא-תק\"י"},{"i":24743,"n":"יצחק מפוזנא","f":"חיים","k":"בעל שו\"ע מהאר\"י","b":"ליקט שולחן ערוך מדברי האר\"י."},{"i":24744,"n":"יצחק מפוזנא","f":"אליקום","k":"בעל לב טוב","b":"חיבר ספר מוסר בלשון אשכנז \"לב טוב\" - פרג שפ."},{"i":24745,"n":"יצחק מפוזנא הגדול","f":"אברהם","k":"בעל באר יצחק","r":"רבו של המג\"א","bt":"שעה בערך","dt":"תמה - טו סיון","dp":"פוזנא","b":"חתן ר נפתלי כץ בעל \"סמיכות חכמים\". גדול בנגלה ונסתר,פוסק,דיין בבריסק אצל ר אברהם אפשטין, ואולי גם אצל בעל \"חלקת מחוקק\". רב בלויצק,הורדנא-תכ\"ב,ווילנה-תכד ור נחמן מלודמיר על מקומו אחריו, פוזנא ומדינת פולין הגדולה-תכ\"ז. היה ראשון רבני וילנא בועד ארבע ארצות. חברו של ר משה זכות שלמד עמו בפולין. בעל אוצר כתבי יד של ראשונים. מתלמידיו בעל \"אבן השהם\". בניו: ר יעקב על מקומו אחריו בפוזנא. חתניו: ר שמואל בן אברהם מרישא אב\"ד מזריטש, ר יחזקאל מקרוטשין בן מאיר סגל מזאמוטש, ר מנחם נחום ז\"ק מפילא ופלוצק, ר יהונתן בן יהודה ליב מפינסק. השיב לבעל מגן אברהם.","bk":[["איל יצחק – חד גדיא",""],["באר יצחק – שו\"ת רבי' יצחק הגדול מפוזנא",""],["באר יצחק – שו\"ת רבי' יצחק הגדול מפוזנא, איל יצחק – חד גדיא",""],["שו\"ת ר' יצחק מפוזנא",""]]},{"i":24746,"n":"יצחק מפולין","f":"מרדכי","b":"תלמיד הרמ\"ע מפאנו. חיבר פסק לאישור דברי רבו ב\"ימין ה' רוממה\" כנגד פסק מהר\"י סאמיגה ב\"דרך ימין\". תשובה ממנו בשות הרמ\"ע, וב\"תולדות אדם\" לר שמואל אלגזי."},{"i":24747,"n":"יצחק מפולנאה","f":"שמואל","b":"דומ\"צ בפולנאה-תק\"כ"},{"i":24748,"n":"יצחק מפומפיאן","f":"חיים או אביגדור","dt":"תרלז","dp":"ירושלים","b":"רב בפומפיאן. עלה לירושלים והיה מחכמי ירושלים, בשנת תרו חתם בפולמוס גגין ובשנת תרלד בקונטרס \"כנסיה לשם שמים\". בנו - ר יוסף זונדל בעל \"זיר יצחק\"."},{"i":24749,"n":"יצחק מפיליפופולי","f":"יונה","b":"רב בפיליפופולי-שנות ה-ש'."},{"i":24750,"n":"יצחק מפינסק","f":"מרדכי","b":"דיין בפינסק-תרן אצל ר אלעזר משה הורביץ."},{"i":24751,"n":"יצחק מפלטשין","dt":"תקעו","b":"אב\"ד פלטשין."},{"i":24752,"n":"יצחק מפלשטיין","dt":"תקעו - כז שבט","b":"רב בפלשטיין"},{"i":24753,"n":"יצחק מפפד\"מ","f":"נתן","dt":"א-יג סיון","b":"רב בפפד\"מ, נהרג עק\"ה עם בני משפחתו ורבים מבני עדתו-ה'א, כנראה הוא המחבר קינה לזכר הרוגי פולדה-ד'תתקצה (או לזכר הרוגי לאודה)."},{"i":24754,"n":"יצחק מפרג","f":"זלמן רבי משה'ס","b":"דיין ומו\"ש בפרג-תנ\"ו-תפ\"ו"},{"i":24755,"n":"יצחק מפרג","f":"שאול","b":"דיין בפרג"},{"i":24756,"n":"יצחק מפרג","b":"מגדולי חכמי פרג-שנת ר'"},{"i":24757,"n":"יצחק מפרג","b":"בנו - ר דוד כתבן"},{"i":24758,"n":"יצחק מפרוסטיץ","f":"יעקב","dt":"שצט - טז כסלו","dp":"לבוב","b":"רב בפרושטיץ(=פרוסטיץ)."},{"i":24759,"n":"יצחק מפרשבורג","f":"אבי העזרי","b":"דיין בפרשבורג-רמח - במינוי זמני של ר אליקים בן קלונימוס, ודן בענין כתובת אלמנה."},{"i":24760,"n":"יצחק מפשווארסק","f":"אהרן מהובנוב","dt":"תנח - ט חשון","dp":"לבוב","b":"רב בפשעוורסק"},{"i":24761,"n":"יצחק מפשיטיק","b":"תלמיד היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא, ור מנחם מנדל מקוצק. אב\"ד פשיטיק."},{"i":24762,"n":"יצחק מצפון אפריקה וירושלים","f":"מוסא","b":"מחכמי ארץ ישראל, עלה מצפון אפריקה והתיישב בגליל ואחר כך בירושלים. כתב אגרת לאביו בשנת ש\"א (רי\"מ טולידנו בH.U.C.A. שנה ד)."},{"i":24763,"n":"יצחק מצפת","f":"ברוך","k":"בעל חק לישראל","b":"מקובל,רב פעלים,מגדולי צפת-שנת ת'"},{"i":24764,"n":"יצחק מצפת","f":"חיים","b":"מחכמי צפת-שכ."},{"i":24765,"n":"יצחק מצפת","f":"שלמה זלמן הכהן מוילנ","k":"יצחק השחור","dt":"תקפו - יח אד\"א","b":"אחיו של ר אברהם פנחס מצפת. בשליחות קהילת החסידים-תקעא."},{"i":24766,"n":"יצחק מצפת","f":"ישראל","b":"דיין בצפת-תרנז. חתם עם ר רפאל זילברמן-תרנז."},{"i":24767,"n":"יצחק מצפת","f":"צבי","b":"מחכמי קהלת הפרושים בצפת. חתם-תקעה על מינוי הגבאים ר ישראל משקלוב, ר צבי הירש כץ, ר משה בן יוסף."},{"i":24768,"n":"יצחק מצרפת","f":"מנחם","b":"מחכמי אורליאנס-צרפת, בן דורו של ר יוסף טוב עלם, נזכר בפירושי רש\"י."},{"i":24769,"n":"יצחק מקאזין","b":"רב בקאזין, דוברומיל."},{"i":24770,"n":"יצחק מקאליס","b":"רב בקאליס-תק\"ס"},{"i":24771,"n":"יצחק מקאליש - ב","f":"ישראל מאייר מקאלוש","k":"אדמור מקאלוש","b":"ממשפחת אדמורי פרמישלן. אדמור בקאלוש על מקום אביו."},{"i":24772,"n":"יצחק מקובנא וירושלים","f":"מרדכי","b":"מחכמי ירושלים, פעל יחד עם ר מנחם מנדל משקלוב לביסוס הישוב בירושלים. עליו במאמר \"שאר ישוב\" לר\"י גולדמן - האסיף 11."},{"i":24773,"n":"יצחק מקוידנוב","b":"תלמיד המגיד ממזריטש, ואחריו ר מנחם מנדל מויטבסק ועלה עם רבו לארץ-תקלז. בשליחות הקהלה בחו\"ל."},{"i":24774,"n":"יצחק מקולבסוב","f":"ישעיה","dt":"תקסג - לפני","b":"רב בקולבסוב. נהרג עק\"ה."},{"i":24775,"n":"יצחק מקומרנא ולבוב","b":"אב\"ד בקומרנא, חתם-תמז בפנקס הקהלה בלבוב, חתם-שצז על העתק תקנה של ועד ארבע ארצות (ואולי הוא חכם אחר)."},{"i":24776,"n":"יצחק מקונסטנטין ישן","f":"צבי הירש","dt":"תקצח","b":"אדמו\"ר בקונסטנטין ישן"},{"i":24777,"n":"יצחק מקוסוב","f":"יהושע","dt":"תקפג","b":"רב ביגלניצה."},{"i":24778,"n":"יצחק מקושטא","f":"נפתלי","b":"גביר מחכמי קושטא-שנות ה-תק'."},{"i":24779,"n":"יצחק מקידאן","f":"אריה יהודה ליב","b":"מו\"ץ ומ\"מ בקידאן, חתם-תקעד בערך בענין עגונה."},{"i":24780,"n":"יצחק מקישינוב","b":"נזכר ב\"דעת קדושים\"-נדבורנא."},{"i":24781,"n":"יצחק מקסטינין","f":"צבי","dt":"תקצה - יד ניסן","b":"רב בקסטינין"},{"i":24782,"n":"יצחק מקראקא","f":"יעקב","k":"ר' יצחק הדרשן","dt":"תעו - ח כסלו","b":"דרשן בקרקא"},{"i":24783,"n":"יצחק מקראקא","f":"יואל","k":"בעל שיח יצחק","dt":"תקעג - כז טבת","b":"דיין בקרקא","bk":[["שיח יצחק",""]]},{"i":24784,"n":"יצחק מקראקא","f":"דוד","dt":"תצד - כא שבט","dp":"קראקא","b":"מחכמי קראקא. נהרג עק\"ה."},{"i":24785,"n":"יצחק מקרוז'","f":"בנדט מקרוז'","b":"נכדו של ר אליהו בן מאיר - שהיה גיסו של הגר\"א. מחכמי קרוז', רב וצדיק גדול. יסד בואיגובה \"חדר מיוחד\", ובין אורחיו הקבועים היו דודו ר יעקב רבה של קרוז', (והירשל מארזווילקי שהיה לימים לפרופ' הרמן שפירא בהיידלברג)."},{"i":24786,"n":"יצחק מקרייליסום","b":"ש\"ץ ונאמן בקרייליסום-תנט."},{"i":24787,"n":"יצחק מקרילוב","f":"אליקים געץ","b":"רב בקרילוב"},{"i":24788,"n":"יצחק מקריסנפאלי","k":"בעל סוד ברית יצחק","b":"רב בקריסנפולי-תקם. חיבר \"סוד ברית יצחק\" זולקוא, תקנט."},{"i":24789,"n":"יצחק מקרמניץ","dt":"תג","b":"רב בקרמניץ, נספד מאת ר אברהם רפפורט בספרו \"איתן האזרחי\"."},{"i":24790,"n":"יצחק מרגנשבורג","f":"רבינו מאיר (מרדכי?)","k":"הריב\"ם","b":"מגדולי בעלי התוספות, ראש חכמי רגנשבורג-ד'תתקס. אחיהם של רבנו תם והרשב\"ם."},{"i":24791,"n":"יצחק מרדיויל","f":"המגיד מזלוטשוב","k":"אדמור מרדיויל-אור יצ","bt":"תקד","dt":"תקפה - יא אייר","b":"חתן ר משה שוהם מדולינה, ובזיוו\"ש חתן ר צבי הירש מנדבורנא בעל \"צמח ה\", ובזיוו\"ש חתן אלמנת ר משה ראש הישיבה בברדיטשוב. רב בנדבורנה על מקום חותנו, אופוטשנה, בוטושאן, פולטושאן, רימנוב-תקעו, רדיויל. בתורתו הביא גילויים שגילו לו מן השמים. אחד מ\"חמשה חומשי תורה\" - כפי שכונו בני המגיד מזלוטשוב."},{"i":24792,"n":"יצחק מרדכי מגריידיץ","k":"בעל חדושי ר מרדכי","bt":"תץ","dt":"תקעג","b":"תלמיד ר יונתן איבשיץ, תלמיד וחתן ר גדליה טיקטין משוערזנץ. רב בגריידיץ-תקנה. לאחר פטירת חותנו גידל את גיסו היתום - ר אברהם טיקטין מברסלוי. מכתביו נדפס 'חדושי ר מרדכי מגריידיץ' - ירושלים תשמא."},{"i":24793,"n":"יצחק מרדכי מסובוטיטש","b":"רב בסאבאטיטש(=סובוטיטש)-תק\"ז"},{"i":24794,"n":"יצחק מרודוס וירושלים","b":"עלה מרודוס בזמן מהר\"ם גלנטי הזקן, ונזכר בספרו."},{"i":24795,"n":"יצחק מרוזניאטוב-קאלוש","f":"אהרן אריה ליב מרוזני","k":"אדמור מקאלוש-רוזניאט","b":"ממשפחת אדמורי פרמישלן. חתן דודו ר יהודה מקאלוש. אדמור ברוזניאטוב על מקום אביו, עבר לקאלוש. וישב גם במגדנבורג-גרמניה. חיבר \"גדולים צדיקים\", \"דרשת הרי\"מ\"."},{"i":24796,"n":"יצחק מרחמנוב","f":"שמואל","k":"בעל העיטור","dt":"תב - א אד\"א","dp":"לבוב","b":"אב\"ד ומו\"צ ברחמנוב."},{"i":24797,"n":"יצחק מרעזיצה","k":"איצעלע רעזיצער","b":"רב ברעזיצה-תר\"י. חתנו - ר חיים צבי הירש ברוידא בעל \"שארית חיים\"."},{"i":24798,"n":"יצחק משה ברוך מירושלים","b":"חתן האדמו\"ר ר יעקב צדיק. עסקן מחכמי ירושלים-תרסה."},{"i":24799,"n":"יצחק משה הכהן מפרוביזנא","b":"רב בפרוביזנא, שאץ-תקפב."},{"i":24800,"n":"יצחק משה מיאס","f":"שמואל","dt":"תרכא - יז ניסן","b":"תלמיד בעל התניא ובנו ר דב בער. ראש חסידי ליובאוויטש ביאס."},{"i":24801,"n":"יצחק משה מירושלים","dt":"תץ - בערך","dp":"ירושלים","b":"מחכמי ירושלים. נספד ב\"יקרא דשכבי\"-תץ."},{"i":24802,"n":"יצחק משה ממילניצה","b":"רב במילניצה-תריג."},{"i":24803,"n":"יצחק משה מפאנימוניק-ליטא","f":"הרב מפונידאל","b":"רב בפאנימוניק."},{"i":24804,"n":"יצחק משטיפי","f":"משה","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":24805,"n":"יצחק משידלוב","f":"מנחם מן","b":"רב בשידלוב-שנת ת'"},{"i":24806,"n":"יצחק משלוניקי","f":"שלמה הכהן","b":"רב בשלוניקי. גיסו של ר אהרן ששון, נזכר בספרי בנו."},{"i":24807,"n":"יצחק משלוניקי","f":"אברהם יצחק","dt":"תצד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24808,"n":"יצחק משלוניקי","f":"חנניה שאול-מגן שאול","dt":"תקיט","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר הקדמה לספר אביו \"מגן שאול\"-תקב."},{"i":24809,"n":"יצחק משלוניקי וירושלים","b":"מחכמי ישיבת ר אברהם מיוחס בירושלים-תקיח."},{"i":24810,"n":"יצחק משלם מקושטא","b":"גביר בקושטא-שנות ה-ת', סייע ללומדי תורה."},{"i":24811,"n":"יצחק משפיירא","k":"רבינו יצחק משפירא","b":"מגדולי חכמי אשכנז הקדמונים,מרביץ תורה בשפירא-ד'תתק\"פ"},{"i":24812,"n":"יצחק משקוד","f":"צבי הירש","k":"בעל פרי יצחק","b":"רב ומקובל-תקץ."},{"i":24813,"n":"יצחק מתאזא","f":"מימון בן אלחנן","b":"מו\"ץ בתאזא-מרוקו - בזמן הרשב\"א, ונשא ונתן עמו."},{"i":24814,"n":"יצחק מתימן","f":"עודד בן יצחק","b":"סופר בתימן, כתב ספר תאג'-תרלז."},{"i":24815,"n":"יצחק מתתיהו","b":"דיין במינסק,קרלין-תק\"פ"},{"i":24816,"n":"יצחק מתתיהו מצפת","b":"רב בצפת, בשנת שע חתם עם רבני צפת על מכתב בקשה לר אהרן ברכיה ממודנא."},{"i":24817,"n":"יצחק נחמיה מצידון","b":"דיין בצידון-תל בערך אצל ר שלמה בן בנימין הלוי עם ר שמעון ראובן."},{"i":24818,"n":"יצחק נחמיה'ס מוילנא","f":"נחמיה","b":"ממיסדי וגבאי ישיבת מייליס בוילנא. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר."},{"i":24819,"n":"יצחק נתן נטע מלובלין","f":"משה פרץ","dt":"תקפב - כח שבט","dp":"לובלין","b":"מחכמי לובלין."},{"i":24820,"n":"יצחק סגי נהור מפרובנס","f":"הראב\"ד","k":"בעל פירוש ליצירה","b":"מראשוני המקובלים בפרובאנס-ד'תתקע. מתלמידיו - ר עזרא ור עזריאל ומהם נמשכה הקבלה לרמב\"ן. חיבר פירוש על ספר יצירה."},{"i":24821,"n":"יצחק סגל הלוי מלויצק ולבוב","f":"שלמה סגל חריף מלבוב","b":"נכד(-אבי אמו) ר יוסף כץ בעל \"שארית יוסף\". חתן המהרש\"א. רב בלוצק-שצ, לבוב על מקום אביו."},{"i":24822,"n":"יצחק סגל מהובנוב","dt":"תקמ - כח שבט","b":"רב בהובנוב"},{"i":24823,"n":"יצחק סגל מפשוורסק","b":"רב בפשוורסק-תקנד."},{"i":24824,"n":"יצחק סולמן משלוניקי","dt":"רעו - תשרי","b":"מחכמי שלוניקי"},{"i":24825,"n":"יצחק סופר ממזריטש","f":"ישכר בער","b":"תלמיד הבעשט. אחיו של ר יוסף מקמינקא."},{"i":24826,"n":"יצחק סירווינטער מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":24827,"n":"יצחק ספרדי","dp":"ירושלים","b":"מחכמי ספרד, הגיע לפרג, ועלה לירושלים. רבו של ר חיים בר בצלאל - אחי המהרל - המזכירו ב\"אגרת הטיול\""},{"i":24828,"n":"יצחק עובדיה מאיטליה","k":"בעל איגרת דופי הזמן","b":"מחכמי איטליה בזמן מהר\"ם פאודבה."},{"i":24829,"n":"יצחק עלי ממזיתרא","b":"רב במזיתרא-שנות ה-ש'."},{"i":24830,"n":"יצחק פסח מלנצהוט","b":"רב בלנצהוט-תריב."},{"i":24831,"n":"יצחק פרצ'עס","f":"יחיאל מיכל","dt":"תר - ו חשון","dp":"וילנא","b":"נכד ר יהודה ליב אב\"ד הורודשיץ. חתן ר חיים הכהן אב\"ד פינסק. גביר בוילנא."},{"i":24832,"n":"יצחק צבי הירש למליר","f":"משה מאייבנשיץ","dt":"תקפד","b":"נכד ר אשר למיל מאייבנשיץ ומכאן שמו. שמש דרשן ודיין בביהכ\"נ של ר איזיק ר יעקילש. מתלמידיו גיסו ר יקותיאל זלמן דמביצר."},{"i":24833,"n":"יצחק צבי הירש מאיוויניץ ומינסק","f":"זאב וולף מהלברשטט","dt":"תרכה - א אד\"א","dp":"מינסק","b":"מחכמי איוויניץ, מינסק. אחיינו - ר דובער בלימוביץ."},{"i":24834,"n":"יצחק צבי הירש מטיסאבעא","f":"משה בודק","dt":"תר - טו ניסן","b":"רב בטיסאבעא"},{"i":24835,"n":"יצחק צבי הירש מלובלין","f":"שמואל זנויל","dt":"תקלה - כג אב","dp":"לובלין","b":"מחכמי לובלין."},{"i":24836,"n":"יצחק צבי הכהן מבוצאץ","b":"דיין בבוצאץ-תרטו - אחרי \"הדעת קדושים\"."},{"i":24837,"n":"יצחק צבי זאב מצורטקוב","b":"רב בצורטקוב-תרה."},{"i":24838,"n":"יצחק צבי כ\"ץ מאונגואר","k":"בעל מצפה אריה","b":"ש\"ץ באונגואר, מכתב ממנו-תרכז לר ישראל אולמן ממאקובה ובו מציע עצמו לש\"ץ במאקובה בהמלצת ר מנחם א\"ש מאונגואר המוסיף דברים משלו בשולי המכתב."},{"i":24839,"n":"יצחק צבי מגוליגור","b":"רב בגוליגור."},{"i":24840,"n":"יצחק צבי מנחם אוירבך מלעשנוב","f":"ישראל בן יעקב פנחס","b":"חתן ר בנימין זאב מזברז."},{"i":24841,"n":"יצחק צבי מסמיאטיץ","b":"רב בסמיאטיש(=סמיאטיץ)-תר\"מ חתנו - מאיר זאב סמלטינסקי."},{"i":24842,"n":"יצחק צבי מקראקא","dt":"תקפד - כו ניסן","b":"דיין בקרקא"},{"i":24843,"n":"יצחק צבי סגל הלוי מסאויסק","f":"משה","dt":"תשד","b":"מחכמי ירושלים, חתנו של ר יצחק אייזיק חבר מטיקטין, הוציא את ספרו של חותנו \"עמודי התורה - מעלות התורה\" עם הוספות משלו ירושלים תרם"},{"i":24844,"n":"יצחק קוסובר מיאגלניצא","f":"יהושע קאך","dt":"תקפג - יז טבת","b":"חתן ר יוסף אהרן מיאגלניצא. תלמיד ר זאב וולף מטשרני, ור צבי הירש מנדבורנא. נזכר ב\"אגרת לגדולי ארץ ישראל\"."},{"i":24845,"n":"יצחק קלמן מוישנוביצק ג'מייקה","dt":"תרצד - כא טבת","b":"רב בווישנובציק-תרס\"ד,ד'אמיקה"},{"i":24846,"n":"יצחק ראובן ממצרים","b":"ג'יליבי במצרים-תך בערך."},{"i":24847,"n":"יצחק רבי בונימש מקראקא","b":"מגדולי חכמי קרקא-שס. בניו - ר משה בעל מהדורא בתרא, ר זאב וולף"},{"i":24848,"n":"יצחק רופא מלובלין","f":"בירך מקלימנטוב ויברו","b":"נכד ר אליקים גצל חתן ר ברכיהו בירך בעל \"זרע בירך\". פרנס ועד ארבע ארצות."},{"i":24849,"n":"יצחק רפאל מירושלים","b":"מחכמי ירושלים, הסכים-תרא על דפוס ישראל בק, ועל \"תפלת ישראל\"-תרב."},{"i":24850,"n":"יצחק שאול","f":"שמואל זנויל מפפד\"א","k":"מפפד\"א","dt":"תקו-תקיא","b":"פרנס בפפד\"א. נזכר לשבח עם אביו ב\"באור ישראל\" לר ישראל יפה-תסב. בניו: ר יהודה ליב-חתן ר אהרן בן יצחק בנימין - רבה של ברלין, ר זנויל מפפד\"מ, ר משה מברלין, ר אהרן מפפד\"מ-חותנו של ר אנשיל בן בנימין יפה. וחתנו - ר יהודה בער (פער) בן ר נפתלי הרץ פער מברלין."},{"i":24851,"n":"יצחק שו\"ב מירושלים","b":"שו\"ב מחכמי ירושלים, חתם-תקצז על כתב שליחות ר אברהם מאיר."},{"i":24852,"n":"יצחק שלמה מזליחוב","f":"יחיאל מיכל מזוויהל","k":"אדמור מזליחוב","bt":"תקעג","dt":"תרלב - כט חשון","b":"חתן ר משה אליקים בריעה מקוזניץ. אדמור בזוויהל על מקום אביו, עבר למגינשוב, זליחוב."},{"i":24853,"n":"יצחק שמואל","f":"יוסף","b":"מחכמי ירושלים, מוזכר בספר המסע של ר משולם מוולטרא בשנת רעט."},{"i":24854,"n":"יצחק שמעון הלוי מוילנא","f":"חיים","dt":"תקעג-ז - כ טבת","dp":"וילנא","b":"מו\"ץ בוילנא. הסכים על \"תולדות אדם\", \"שבט יהודה\"-תקעג."},{"i":24855,"n":"יצחק שמעון מרווה","f":"משה","b":"אב\"ד ראווה-תקמה."},{"i":24856,"n":"יצחק שמעיה מונציה","b":"רב ומקובל בונציה. מוזכר ב\"באר עשק\"."},{"i":24857,"n":"יצחק שמעיה מירושלים","dt":"תף","dp":"ירושלים?","b":"מחכמי ירושלים. נספד ב\"טירת כסף\" לר אברהם גטניו."},{"i":24858,"n":"יצחק שמשון מראווע וזולקוא","f":"פסח","b":"אב\"ד ראווע, מגיד מישרים בזולקוא אצל ר צבי הירש מייזלש. הסכים על \"נפש יהודה\"-תקנה, ועל זהר חדש-תקסז."},{"i":24859,"n":"יצחק ש\"ץ מירושלים","f":"מאיר","dt":"תריח - ב אלול","dp":"ירושלים","b":"מחכמי ירושלים, וש\"ץ דקהלת הפרושים."},{"i":24860,"n":"יצחק שרגא מבגדד","b":"רב וראש ישיבה בבגדד-[רס..]"},{"i":24861,"n":"יצחק שתדלן","f":"משה","b":"מחכמי ירושלים, בשנת תסא נשלח לר דוד אופנהיים בוינה עם כתב הרבנות של ירושלים."},{"i":24862,"n":"יצחק שתדלן מלובלין","b":"מגבאי הח\"ק בלובלין-תסז, וחתם בפנקס הח\"ק כמה פעמים."},{"i":24863,"n":"יצחקוף, משה הכהן מבוכרה","bt":"תרכה","bp":"בוכרה","dt":"תשג - כה אייר","dp":"ירושלים","b":"רב בבוכרה, עלה לירושלים-תרפג ולימד בישיבת \"מדרש שלמה\", וכיהן כרב העדה בירושלים על מקום ר אברהם אמינוף."},{"i":24864,"n":"יצחקי, אברהם הכהן מתונס","k":"בעל משמרות כהונה","b":"מגדולי דייני תונס, חיבר גם \"מצות כהונה\", \"שלחנו של אברהם\". חתן ר' דוד הכהן (ואח\"כ חתן ר' יעקב סאלאמא)"},{"i":24865,"n":"יצחקי, אברהם משלוניקי","b":"מרבני שלוניקי-שנת-ת'"},{"i":24866,"n":"יצחקי, אברהם משלוניקי","k":"בעל אחות קטנה","bp":"קושטא","b":"דיין מחכמי שלוניקי-שן בבית דינו של ר שלמה הלוי, וראש הסופרים בשלוניקי. חתם בתשובת מהר\"א ששון-שנז. חיבר \"אחות קטנה\" - דיני גט לקטנה - ונדפס בסוף \"הלכות קטנות\", חיבר גם קונטרס על בדיקת הריאה ונזכר אצל ר יוסף מולכו ב\"שלחן גבוה\". אחיו - ר מאיר."},{"i":24867,"n":"יצחקי, אליעזר מקושטא","b":"רב בקושטא - בשנים תק-תקן."},{"i":24868,"n":"יצחקי, דוד מאזמיר","b":"ממאמיני שבתי צבי באזמיר-תכח."},{"i":24869,"n":"יצחקי, דוד מירושלים","bt":"שע - אחרי","bp":"שלוניקי","dt":"תנד-ס","dp":"ירושלים","b":"עלה לחברון והיה תלמיד וחתן ר אברהם אזולאי בעל \"חסד לאברהם\". בשנת תמז הגיע לירושלים והיה ראב\"ד אצל ר משה גלנטי, ולאחר פטירתו של ר משה התמנה לרב הראשי-תמט. חתם בראש חכמי ירושלים על פסק הקדש של טבריה וצפת (\"זרע אנשים\"), בשליחות ביון, תשובה שלו בספר \"בית שלמה\" לר שלמה חסון שלוניקי תפ. פסק שלו בתשובות ר יעקב פאראג'י. (לדעת גרץ - היה נוטה לשבתאות בתקופה מסוימת). חתם-תמח עם ר משה גלנטי בענין קהלת טבריה. בניו היו ר אברהם שהיה רב ראשי בירושלים, ר יצחק. (אולי הוא שכתב לרבני ליוורנו בשבחו של ש\"ץ). (לדעת רוזניס היה חתן ר יצחק אזולאי, ור יצחק היה אחיו - ולא בנו?)"},{"i":24870,"n":"יצחקי, חנן בכור מירושלים","dt":"תרנא - יא אד\"ב","b":"מחכמי ירושלים"},{"i":24871,"n":"יצחקי, ידידיה","f":"אברהם","b":"ידידו של ר' יצחק הכהן בעל \"בתי כהונה\""},{"i":24872,"n":"יצחקי, יהודה הכהן","b":"מחכמי טוניס"},{"i":24873,"n":"יצחקי, יעקב מדגסטן","f":"יצחק","k":"בעל אהל יעקב","bt":"תרו","bp":"דרבנט-דאגסטן","dt":"תרעז - כא סיון","dp":"ירושלים","b":"היה רב בעירו כ-40 שנה, ביקר בארץ בשנת תרלו ואחר כך בשנת תרמז, בשנת תרסז עלה עם משפחתו, על שמו המושבה \"באר יעקב\". בשנת תרסח הוציא מחזור \"אהל יעקב\" עם פירוש ונוסח מדויק עם הסכמות רבות. נהרג ברעש בירושלים. פרסם מאמרים ב\"מסעות קוקז\" לד\"ר יוסף טשרני."},{"i":24874,"n":"יצחקי, יצחק מחברון","f":"דוד","b":"מחכמי חברון, נכד ר אברהם אזולאי. תלמיד ר משה גלנטי ואחיו של ר אברהם יצחקי. החיד\"א ראה ספר דרושים שלו בכתב יד, מתורתו בספר אחיו ר אברהם יצחקי. (לפי רוזניס היה אחיו של ר דוד ולא בנו)."},{"i":24875,"n":"יצחקי, יצחק משלוניקי","f":"אברהם","b":"דיין בשלוניקי-שצג, וסופר מומחה כאביו."},{"i":24876,"n":"יצחקי, מאיר חיים מקושטא","f":"עמנואל","k":"בעל אור יקרות","bt":"1685?","bp":"שלוניקי","dt":"תקיג-ד","b":"רב בשלוניקי-תק, קושטא-תקח, וחתם בראש על תקנת המלבושים בירושלים ועוד. דיינים אצלו - ר אברהם בן שמואל יהודה (שעלה לירושלים), ר אליעזר משה הכהן. אחיו של ר אליעזר יצחקי.","bk":[["אור יקרות","מפרשי רמב\"ם"],["אור יקרות – רמב\"ם",""],["אור יקרות [על רמב\"ם]",""]]},{"i":24877,"n":"יצחקי, מאיר מקושטא","b":"רב בקושטא-שנות ה-ש'."},{"i":24878,"n":"יצחקי, מאיר משלוניקי","b":"מחכמי שלוניקי-שנה, נתמנה ע\"י ר תם ן יחיא להדפיס את ספרו יחד עם ר אליעזר שושן."},{"i":24879,"n":"יצחקי, מאיר משלוניקי","b":"רב בשלוניקי-שן, אחיו - ר אברהם."},{"i":24880,"n":"יצחקי, משה יוסף מירושלים","f":"דוד?","dp":"ירושלים","b":"מחכמי ירושלים-שנות ה-ת'. כנראה אחיהם של ר אברהם ור יצחק."},{"i":24881,"n":"יצחקי, משה מקושטא","b":"רב בקושטא-תקי\"ב"},{"i":24882,"n":"יצחקי, משה מקושטא","b":"רב בקושטא, הסכים-תקיב ל\"חיי עולם\" לר רפאל משה בולה."},{"i":24883,"n":"יצחקי, נסים הרופא מיוון","b":"רב ורופא ביוון בזמן המהרש\"ל."},{"i":24884,"n":"יצחקי, שלמה","f":"יצחק","k":"רש\"י","r":"רב ופוסק - רב בטרוייש","bt":"ד'תת","bp":"טרוייש","dt":"ד'תתסה","dp":"טרוייש","b":"ספרי רש\"י: פירושו לתנ\"ך; פירושו לתלמוד בבלי; איסור והיתר לרש\"י; תשובות רש\"י [ניו יורק תש\"ג, על הספר נמתחה ביקורת שהוא כולל גם תשובות שאינן של רש\"י]. להלן פירושים המיוחסים לרש\"י ואינם ממנו: פירושי רש\"י לדברי הימים, למס' נדרים, למס' נזיר, למס' תמיד, לפרק חלק (סנהדרין), להגדש\"פ, רש\"י על הרי\"ף [לקט מפירושיו על הש\"ס ע\"י אחד הקדמונים]. על פירושי רש\"י למס' אבות ולמדרש רבה, נחלקו אחרונים: לדעת היעב\"ץ (עץ אבות, הקדמה ללחם שמים) פירושים אלו אינם של רש\"י, אולם לדעת החיד\"א (שם הגדולים ע' רש\"י) הם פירושיו של רש\"י [וראה שם, על אודות הפי' לאבות - שכן דעת גדולי הפרשנים, ועל הפי' למדרש רבה - שכן דעת חכמי צפת]. על מהדורות שונות לפירושו, על \"ספרי דבי רש\"י\", ועל רבותיו, ראה נספח ה.","bk":[["רש\"י","מפרשי תנ\"ך"],["איסור והיתר לרש\"י",""],["ספר האורה",""],["תשובות רש\"י (שו\"ת)",""],["הסדרים לרש\"י",""],["כת''י רש''י",""],["כת''י רש''י ושאר ראשונים עה''ת הפטרות ונ''ך",""],["לקוטי הפרדס",""],["סדור רש\"י",""],["ספר הפרדס",""],["ספר הפרדס לרש\"י",""],["עמוד די רש\"י ז\"ל",""],["פיוטי רשי (רש\"י)",""],["פירוש רש\"י",""],["פרוש המקרא לרש\"י",""],["פרוש רש\"י",""],["פרשנדתא",""],["האורה","הלכה ומנהג - ראשונים"],["סידור רש\"י","הלכה ומנהג - ראשונים"],["איסור והיתר לרש\"י","הלכה ומנהג - ראשונים"],["הסדרים לרש\"י","הלכה ומנהג - ראשונים"]],"e":"ד'ת\"ת~-ד'תתס\"ה","rb":"טרוייש","co":{"a":"48.2997,4.07917","d":"48.2997,4.07917","b":"48.2997,4.07917"}},{"i":24885,"n":"יצחקי, שלמה מצפת","f":"דוד","b":"רב בצפת-תנח אצל ר שמעון גויזו."},{"i":24886,"n":"יצחקי, שמואל הכהן מתונס","f":"יוסף","r":"ראש ישיבת בית יוסף","dt":"תקסד - כג אב","dp":"כפר נאבל-תונס","b":"דיין בתונס אצל אביו הראב\"ד-תקמא, וחתם עמו. זקנו של ר אברהם בעל \"משמרות כהונה\". ראב\"ד-תקסג על מקום אביו. נספד ע\"י חברו הדיין ר עוזיאל אלחאייך בספרו \"מערתא דדייני\". מצאצאי ר אברהם הכהן הנקרא \"באבא רבי\" והדיינים ר שמואל הכהן ור יצחק הכהן שהיו דיינים בשנות ה-ת'."},{"i":24887,"n":"יצחקי, שמואל מטבריה","b":"מחכמי טבריה וצפת. בשליחות באמריקה-תקפה, והיה גם בקורסאו ונזכר בפנקס הקהלה. תשובה ממנו לר אברהם בלעיש מניצא ב\"יד אבישלום\""},{"i":24888,"n":"יצליח ן, חפץ","k":"חפץ בן יצליח האשורי","b":"סגי נהור,דיין במוסול-ד'ת\"ש. חיבר ספר חפץ."},{"i":24889,"n":"יצ'ס, נחום אריה יהודה ליב מקיט","b":"רב בקיטוב-תרפט. נספה בשואה."},{"i":24890,"n":"יצקן, שמואל","f":"פנחס מהוניאד","k":"בעל פניני היהדות","bt":"1874","bp":"ואבולניק","dt":"1936","b":"תלמיד ישיבות ליטא. פרסם מאמרים ב\"המליץ\", ועוד ובחלקם חתם - \"אבי דור\". יסד את \"אידישע טאגעבלאט\"-1906 עם ל. פינקלשטין, ואת \"היינט\" בוארשא עם נ. פינקלשטין, ו\"אידישע וואכענבלאט\" עם ר הלל צייטלין. חיבר גם \"רבנו אליהו מוילנא\" וארשא תרסה."},{"i":24891,"n":"יקואל, אברהם משלוניקי","dt":"תט - כט אדר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24892,"n":"יקואל, דוד משלוניקי","b":"דיין בשלוניקי-תק."},{"i":24893,"n":"יקואל, יוסף יצחק משלוניקי","k":"בעל מטה יוסף","dt":"תקמט - טו תשרי","b":"מחכמי שלוניקי, רב באישטיפ, סופיה-תקמא."},{"i":24894,"n":"יקואל, ישועה אברהם מסופיה","dt":"תקסח - כו שבט","dp":"סופיה","b":"מחכמי סופיה."},{"i":24895,"n":"יקואל, שלמה משלוניקי","dt":"תח - כה אלול","dp":"שלוניקי","b":"מחכמי שלוניקי-סוף שנות ה-ש'."},{"i":24896,"n":"יקושיק, לוי","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":24897,"n":"יקותיאל","b":"בנו - ר אורי שרגא פיביש, נכדיו - ר אהרן מאיויא, ר נח בלוך (פעטליצער)."},{"i":24898,"n":"יקותיאל - תלמיד ר אלימלך","b":"תלמיד ר אלימלך מליזנסק. נזכר ב\"תפארת שלמה\" - רדמוסק."},{"i":24899,"n":"יקותיאל הכהן ממנטובה","f":"הלל","dt":"תקסב","b":"רב במנטובה-תקכד."},{"i":24900,"n":"יקותיאל הלוי מורמייזא","b":"מבעלי התוספות-ד'תתקס."},{"i":24901,"n":"יקותיאל הפייטן","f":"משה בן קלונימוס","b":"נכד ר קלונימוס בן ר משלם הגדול. פייטן בשפיירא-ד'תתק, חיבר הפיוט \"יראתי בפצותי שיח\" והוא הקדמה לפיוטו של הקליר. נזכר בהגהות מיימוניות."},{"i":24902,"n":"יקותיאל הפייטן","f":"יוסף","b":"פייטן מחכמי אשכנז-שנות ה-ד'תתק. חיבר מערבית לפסח \"אשר באור החיים\"."},{"i":24903,"n":"יקותיאל הפייטן","f":"יצחק","b":"פייטן מחכמי אשכנז, חיבר סליחה \"מה יקרו רעיך רב מחולל\" על גזירות קס, נמצא בסליחות מנהג ליטא לצום גדליה."},{"i":24904,"n":"יקותיאל הרופא מוילנא (גורדון)","f":"ליב מוילנה","k":"בעל אוצר בלום","bp":"וילנא","b":"רופא ומקובל. התכונן לעלות לארץ ונסע לפדובה כדי לפגוש את המקובל ר שמואל רוקח - שנפטר בטרם הגיעו. הצטרף לישיבת \"אור תורה\" שיסד ר שמואל בפדובה ופגש שם את הרמח\"ל והצטרף לחוגו והיה מתלמידיו בקבלה, ושלח מכתב אל ר יהושע השל מוילנא אודות הרמח\"ל. רצה לעזוב את הרפואה ולהתמסר לקבלה וכשהודיע על כך לר יהושע אב\"ד וילנא, ור מרדכי יפה - וענו לו \"אחוז בזה וגם מזה אל תנח את ידיך\". התמסר להפצת תורת הרמח\"ל באשכנז, חזר לליטא ולימד את חכמת הנסתר, ישב בשקלוב, מינסק. בשליחות קהילת בריסק בהולנד-תקיב. חיבר ספרים בכת\"י שנדפסו ב\"אוצר בלום\", חיבר פירוש למגלת אסתר שהו\"ל ע\"י שלוסברג. חיבר גם \"מראה המוסר\", ועוד."},{"i":24905,"n":"יקותיאל זאב זלמן וולף מאונסדור","f":"יוסף יוזל","k":"בעל עמק המלך-תקסח","bt":"1750","bp":"ניקלשבורג","dt":"תקעח - ג סיון","dp":"אונסדורף","b":"יש להבדיל בין \"עמק המלך\" לר' יקותיאל זאב זלמן וולף [מרבני הונגריה], לבין הגהות \"עמק המלך\" לר' אברהם אבוש [מפרנקפורט, ראה בערכו], שנדפס כתוספת לרמב\"ם מהדו' ורשא תרמ\"א. על אודות שנת הפטירה - אמנם בהספד של המהר\"ם א\"ש באמרי יושר (דף ס ע\"א) נכתב תקע\"ז, אולם בדרשות חתם סופר ח\"ב (דף שפ ע\"א) נכתב תקע\"ח, ונראה שבאמרי יושר נפלה טעות, שכן הוא מספיד שם גם את ר' וואלף באסקוויץ שנפטר בי' ניסן תקע\"ח.","bk":[["עמק המלך","מפרשי רמב\"ם"],["עמק המלך – רמב\"ם",""],["עמק המלך [על הרמב\"ם נשים וקדושה]",""]]},{"i":24906,"n":"יקותיאל זוסמן (זוסיא) מאוסטרהא","f":"ראה: זוסמן, יקותיאל"},{"i":24907,"n":"יקותיאל זוסמן הלוי מאוסטרהא","f":"יצחק","dt":"תקנח - יא שבט","dp":"אוסטרהא","b":"אבי משפחת זוסמן באוסטרהא - נקראו על שמו. פרנס באוסטרהא-תקקל יחד עם ר שמואל בן צבי הירש. חתנו ר אבא בן פסח הכהן מאוסטרהא, ונכדו ר משלם זלמן מאוסטרהא."},{"i":24908,"n":"יקותיאל זוסמן מראדאליא","b":"רב ברזליה(=ראזאליא). חתניו: ר שמואל שר משובאץ, ר נפתלי הרץ מרדיוילשוק, ר ליפמן משאקאי-ליד שעוול."},{"i":24909,"n":"יקותיאל זיסל מקליקול","f":"משה","bt":"תקעו","dt":"תרנז - ו תשרי","b":"נכד (אבי אמו) ר ראובן רובינזון. תלמיד ישיבת וולוזין, למד עם ר מרדכי אליאשברג מבויסק ור אלכסנדר משה לפידות. רב בקליקול כ-40 שנה. בנו - ר ראובן יצחק איליאן בעל \"שדה יצחק\" על מקומו אחריו."},{"i":24910,"n":"יקותיאל זיסקינד הכהן מליפלנד","b":"רב בליפלנד(=איפלנד) הגדולה-תפ. בנו - ר רפאל הכהן מהמבורג."},{"i":24911,"n":"יקותיאל זיסקינד הלוי","f":"שלמה זלמן","k":"בעל דת יקותיאל","b":"פייטן-שנות ה-ת'. ישב במאסר וחיבר \"דת יקותיאל\" על תריג מצוות, ונדפס ע\"י נכדו - ר מנחם מאניש בן יונה. בנו - ר אלעזר."},{"i":24912,"n":"יקותיאל זיסקינד מזולקוא","f":"יעקב","b":"מחכמי זולקוא, חתם-תקם על תקנת הקהלה."},{"i":24913,"n":"יקותיאל זלמן (לויטס) מזאגר","dt":"תרח","b":"תלמיד ר חיים מוולוזין. רב בזאגר ישן, ואקשנה. בנו - ר צבי הירש לויטס מלינקובא, ונכדו ר יקותיאל זלמן לויטס."},{"i":24914,"n":"יקותיאל זלמן באב\"ד מלבוב","f":"מהר\"י","b":"מחכמי לבוב, חתם-תסא על תקנות קהלת זולקוא."},{"i":24915,"n":"יקותיאל זלמן הכהן הנקדן","f":"יהודה","k":"בעל עין הקורא,יהב\"י","b":"נקדן מחכמי פרג-שנות ה-ק'. ניקד והעמיד טעמים לתורה ומגלת אסתר. נזכר אצל גדולי המדקדקים."},{"i":24916,"n":"יקותיאל זלמן הלוי מדרוהוביטש","f":"יוסף חריף מפרמישלא","k":"ר זלמן הנביא","dt":"תצא - יז חשון","b":"חתן ר מרדכי גינצבורג מבריסק-חתנו של ר יצחק מזולקוא (ויש אומרים שהיה חתן ר יצחק מזולקוא). נכד ר משה חריף-אב\"ד לבוב. מקובל, רבה הראשון של דרוהוביטש. היו לו שבעה בנים רבנים ונקרא שבעה קני מנורה - ר יעקב יצחק לנדא מפרשבורג, ר מרדכי מדוברומיל, ר משה, ר נטע מאלסק, ר יהודה ליב, ר מאיר, וחתנו ר שמחה מסלמינה."},{"i":24917,"n":"יקותיאל זלמן יהודה ליב מטבריה","bt":"תקכח","dt":"תריג - ז טבת","b":"תלמיד ר זאב וולף מטשרני. עלה לארץ עם רבו-תקנח. ראש חסידי וואהלין בטבריה על מקום רבו. אבי משפחת ברז\"ל (בני רבי זלמן לייב)."},{"i":24918,"n":"יקותיאל זלמן מאייבניץ","b":"סופר סת\"ם, כתב ספר תהלים עבור קהלת שטמפן-תץ."},{"i":24919,"n":"יקותיאל זלמן מבאר","b":"רב בבאר"},{"i":24920,"n":"יקותיאל זלמן מלבוב","f":"חנוך","dt":"שצא - ב תמוז","dp":"לבוב","b":"מרביץ תורה בלבוב."},{"i":24921,"n":"יקותיאל זלמן מלבוב","f":"נח יחיאל","dt":"תכו - כח טבת","dp":"לבוב","b":"רב בלבוב."},{"i":24922,"n":"יקותיאל מאיספהאן-פרס","f":"נוריאל","b":"רב באיספהאן-פרס-תקץ, עם חברו ר שלמה בן דוד."},{"i":24923,"n":"יקותיאל מגריידיץ","f":"משה מלובלין","b":"דיין בגריידיץ, חתם-תקעב עם ר יצחק מרדכיור יקותיאל בן משה."},{"i":24924,"n":"יקותיאל מואקשנא","b":"רב בוועקשנא-תק\"צ"},{"i":24925,"n":"יקותיאל מירושלים","b":"מחכמי ירושלים. בשליחות במרוקו-תלח, ונזכר בשו\"ת ר משה ן חביב."},{"i":24926,"n":"יקותיאל מלובלין","b":"רב בחעלמא-תל\"א,לודמיר-תנ\"ד"},{"i":24927,"n":"יקותיאל מלובלין","f":"אלעזר","dt":"תקע - טו שבט","dp":"לובלין","b":"מחכמי לובלין."},{"i":24928,"n":"יקותיאל מלודמיר","f":"יושיע אהרן מחעלמא","b":"נכד ר מאיר ז\"ק מלבוב. רב בחלם, לודמיר. מראשי ועד ארבע ארצות והיה בועד בירוסלב-תמז. הסכים על \"מים חיים\" לר חיים הורביץ, \"אדרת אליהו\", ועוד."},{"i":24929,"n":"יקותיאל מספרד","f":"חסאן","b":"שר וחשוב בספרד (אולי סרגוסה)-שנות ה-ד'תת. איש חסדו של המשורר ר שלמה ן גבירול שכתב לו שירים וקינה על פטירתו. נהרג עק\"ה."},{"i":24930,"n":"יקותיאל מפדובה","f":"מוהרי\"ל מוילנא","b":"מחכמי פדובה, מבני החבורה של הרמח\"ל."},{"i":24931,"n":"יקותיאל מצפת או טבריה","f":"יחיאל","b":"חתם על כתב שליחות-תקמח."},{"i":24932,"n":"יקותיאל מקידאן","f":"שלמה זלמן","b":"דיין בקידאן. חתם-תקעד בערך בענין עגונה."},{"i":24933,"n":"יקותיאל משה הכהן מדבדו","b":"מחכמי דבדו-תקמה."},{"i":24934,"n":"יקימובסקי, יעקב בנימין זאב","f":"בן ציון הכהן","b":"מצאצאי ר ישעיה מזכוביץ."},{"i":24935,"n":"יקיר אסתרוק מאדרינופול (גירון","k":"בעל מירא דכיא","b":"רב באדרינופולי-תק\"ס"},{"i":24936,"n":"יקיר מקושטא","f":"יוסף","bt":"תרן","bp":"אדרינופול","b":"מזכיר לשכת \"בני ברית\" בקושטא, עורך \"המנורה\", ופרסם מאמרים רבים, סייע בהקמת ביהמ\"ד לרבנים ברודוס, עבר למילנו, עלה לארץ והתישב בתל אביב. אחיו של בנימין בכר יוסף - מו\"ל בקושטא."},{"i":24937,"n":"יקיר ן, אהרן","dt":"תקפד - בערך","dp":"כפר גומינג'ה","b":"מחכמי שלוניקי? נהרג בכפר גומינג'ה, נספד מאת ר יעקב רפאל מנשה משלוניקי."},{"i":24938,"n":"יקיר ן, משה מירושלים","dt":"שצז","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":24939,"n":"יקיתלן, מאיר מפרשבורג","f":"אנשיל","dt":"תקיט - י אייר","dp":"פרשבורג","b":"מחכמי פרשבורג"},{"i":24940,"n":"יקר","k":"ראה: אפרים","b":"על שם הפסוק \"הבן יקיר לי אפרים\"."},{"i":24941,"n":"יקר הלוי משפיירא - א","f":"שמואל","b":"מחכמי שפיירא-שנות ה-ד'תת. שאלה ממנו לר קלונימוס מרומא, נזכר במרדכי."},{"i":24942,"n":"יקר הלוי משפיירא - ב","f":"שמואל","b":"תלמיד ר יחיאל מפאריס. מחכמי קולוניא, מגנצא מגדולי הראשונים בחכמי אשכנז-ל'. קרוב משפחה של המהר\"ם מרוטנבורג. חיבר פיוט \"אזכרה אלקים נגינתי בלילה\" על גזרות הפורצין(=פפרצהיים)-ה'לא."},{"i":24943,"n":"יקר ן, אליעזר מנחם","b":"אין נתונים."},{"i":24944,"n":"יקר ן, אפרים הפייטן","b":"פייטן קדום, ומובא ממנו במחזורים קדומים. חיבר פתיחה למוסף \"אין פה להשיב\" ונמצאה במחזור משנת ה'מ."},{"i":24945,"n":"יקר ן, דון מפורטוגל ושלוניקי","b":"מאנוסי פורטוגל, הגיע לשלוניקי - שנות ה-ש'."},{"i":24946,"n":"יקר ן, חיים יעקב מקושטא","b":"אב\"ד בקושטא ורב הכולל-תקע על מקום ר אליהו פאלומבו (ומשנהו - ר עובדיה נתן), רבה של חברון בשנים תקץ-תקצג, חתם על אגרת שליחות של ר יוסף מולכו בתקפב. חתם על כתב שליחות ר יוסף דוד עייאש."},{"i":24947,"n":"יקר ן, חנניה מקושטא","k":"בעל תהלי תהלים","bp":"קושטא","dt":"שסב - אחרי","dp":"קושטא","b":"פייטן ומשורר מחכמי קושטא-שנז, ומחברי בית המדרש לשירה בשלוניקי, עבר לאדרינופול, וחזר לקושטא. פוסק מובהק, תלמיד ר יוסף ן לב-מהריב\"ל והסכמה ושיר ממנו בספר רבו. חיבר ספר \"תהלי תהלים\". חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא. הסכים גם על \"אגרת המוסר\", \"מסורת התלמוד\" לר יהודה ן גדליה."},{"i":24948,"n":"יקר ן, יאיר","b":"מחכמי קושטא"},{"i":24949,"n":"יקר ן, יהודה משלוניקי","dt":"רצח - חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":24950,"n":"יקר ן, יום טוב מקושטא","f":"חנניה","b":"רב בקושטא-שנות ה-ת' - בזמן ש\"ץ. מינה משלחת לחקור אודות נתן העזתי - עם חבריו ר משה שאנג'י ור כלב בן שמואל."},{"i":24951,"n":"יקר ן, יוסף מאזמיר","b":"דיין באזמיר-תקסא, סידר גט למומר עם ר יום טוב דנון ור אברהם ן עזרא."},{"i":24952,"n":"יקר ן, יוסף מאלגיר","bt":"רי","dt":"רפ - בערך","b":"רב באלגיר, נזכר בשו\"ת ר שמעון בן הרשב\"ש."},{"i":24953,"n":"יקר ן, יצחק רפאל מקושטא","b":"מחכמי קושטא-שנות ה-ת'-תק'. (אולי הוא שהיה רב בחברון)."},{"i":24954,"n":"יקר ן, נסים יהודה מקושטא","b":"תלמיד ר בנימין קאזיש וכתב הקדמה לספר רבו \"מגילת ספר\", חיבר מפתחות ל\"משנה למלך\" עם חדושים ממנו."},{"i":24955,"n":"יקר ן, רפאל יצחק מחברון","b":"מחכמי חברון. מהחותמים על יסוד ישיבת \"מגן אבות\"."},{"i":24956,"n":"יקר ן, רפאל שבתי מקושטא","dt":"תריד - יט אלול","dp":"קושטא","b":"ממונה איסור והיתר בקושטא-תקעח, ראב\"ד ומאשר הסכמות-תרג. נספד ע\"י אחיינו ר שלמה קמחי ממעליס ב\"מלאכת שלמה\", וע\"י ר חיים מודעי מאזמיר."},{"i":24957,"n":"יקר, משה","b":"רב-שנת ת'"},{"i":24958,"n":"ירא, יוסף חיים מאיטליה","bt":"תר","bp":"מנטובה-איטליה","b":"תלמיד ישיבת פדובה, תלמיד ר שלמה דוד לוצטו-שד\"ל. רב במנטואה(=מנטובה), פירארה(=פיררה)-תרלט. חיבר ספרים באיטלקית, ומאמרים בכתבי עת."},{"i":24959,"n":"ירא, מרדכי ממנטובה","f":"ברכיה ראובן","b":"שו\"ב ומשורר במנטובה-תס. הו\"ל \"איילת השחר\", וחיבר פיוטים."},{"i":24960,"n":"יראם המגדיאלי","b":"תלמיד רב סעדיה גאון. מחכמי בבל."},{"i":24961,"n":"ירביץ, משה מפרוסניץ","b":"רב בפרוסניץ(=פרוסטיץ). חתנו - החת\"ס."},{"i":24962,"n":"ירדני (זקהיים), משה","f":"אברהם","bt":"1881","bp":"וילקי","dt":"1960","dp":"תל אביב","b":"אביו היה רבה של וילקי-ליטא. מנהל הגימנסיה העברית בוילקוביסק, מיסד ביה\"ס המקצועי העברי הראשון בליטא. חבר \"תרבות\" וקאני לדיבור עברי ומייסד מסדר \"בן יהודה\"."},{"i":24963,"n":"ירו, אברהם הקראי מקושטא","k":"בעל כללי הדקדוק","b":"מחכמי הקראים בקושטא-תקס."},{"i":24964,"n":"ירו, יצחק הכהן הקראי מקושטא","f":"שמואל","b":"מחכמי הקראים בקושטא, סייע בהדפסת \"פתח התיבה\"-תקסד. בנו - שמואל נפטר בחייו."},{"i":24965,"n":"ירוזלמסקי, מנחם זאב מקוצק","dt":"תרו - יב אדר","b":"גיסו של ר אברהם מטשכנוב. תלמיד ר מנחם מנדל מקוצק. רב בזגרז, לודז, יאנובא, קוצק. בנו ר רפאל פנחס הכהן, וחתנו ר יהושע שמואל בן ר צבי הירש מטומשוב."},{"i":24966,"n":"ירוחם","f":"יוסף מבלז","b":"נזכר בשו\"ת מהרש\"ל. בנו - ר יוסף מזולקוא."},{"i":24967,"n":"ירוחם הכהן מדוביסאר","b":"רב בדוביסאר-תרכ\"ה"},{"i":24968,"n":"ירוחם חיים סגל הלוי מדולינא","f":"יוסף מדולינא","k":"בעל בית הלוי","dt":"תקפב - כג תשרי","b":"מצאצאי בעל הט\"ז. מחסידי ר צבי הירש מנדבורנא, ור צבי הירש מזידיטשוב. עלה לארץ - אך נפטר בדרכו (כמו גם אביו לפניו שנפטר בדרכו לארץ בעיירה וינקוביץ בהיותו כבן 80). חיבר \"בית הלוי\" תקפא (בשער תקסג)."},{"i":24969,"n":"ירוחם מבאטקא","b":"רב בבאטקא. הסכים-תקצב על \"אבות דרבי נתן\" לר אליהו בן אברהם מדליטיץ."},{"i":24970,"n":"ירוחם מספרד","k":"ירוחם טמירא","b":"תלמיד הרא\"ש,מגדולי הפוסקים באחרוני הראשונים בספרד-צ\"ד,בעל \"תולדות אדם וחוה\". כונה בשם טמירא = כי הספרים שנתחברו עליו - נעלם הספר או מחברו."},{"i":24971,"n":"ירוחם מסקידל","b":"רב בסקידל-תקכ. בנו - ר דב בער מוילנא."},{"i":24972,"n":"ירוחם פישל מוילנא","f":"פסח","bt":"תקלח","dt":"תרא - ו אדר","dp":"וילנא?","b":"גביר מחכמי וילנא, גבאי בקור חולים יחד עם ר אברהם בן הגר\"א. חתניו - ר אריה ליב נתנזון המכונה ר ליבלי פישעלס, ר בנימין נתנזון בן נתן נטע מפלונגיאן. עליו ב\"פרחי צפון\" לר מרדכי אהרן גינצבורג."},{"i":24973,"n":"ירוחם פישל מסקלט","b":"רב בסקלט-תקעט."},{"i":24974,"n":"ירוחם פישל מפלוצק","b":"גדול בדורו,רב בפלאצק-תק\"מ"},{"i":24975,"n":"ירוחם שרגא פיבל","dt":"תשג","b":"רב באלשטט"},{"i":24976,"n":"ירוחם, אהרן מוינה ונ\"י","f":"חיים יצחק מאלטשטאט","k":"בעל האם בישראל","bt":"תרסד","bp":"לימנוב","dt":"תשל","dp":"בוסטון","b":"תלמיד אביו ואחיו - ר שרגא זאב מאלטשטט, ישיבת ר יעקב יחזקיה בצהלם. נסמך מאת: ר חנוך הניך לוין מבנדין, ר נחום וידנפלד מדומברובא, ר שמואל פירר מקרוסנא הי\"ד. חתן ר דוד הלברשטם מסוקולוב. רב בקהלת \"אהבת תורה\", \"מחזיקי תודה\" בוינה, היגר לארה\"ב-תש וכיהן כרב בניו יורק, יסד קהלת יראים \"סיני\", סגן נשיא הסתדרות האדמורים, וחבר אגודת הרבנים באמריקה. חיבר \"האם בישראל\" ציריך תרצט, \"אהל רחל\" - השלמת חסרונות מחדושי הרמב\"ן - ניו יורק תשב."},{"i":24977,"n":"ירוחם, חיים יצחק מלימנוב","f":"שרגא זאב","k":"בעל ברכת יצחק","bt":"תרכד-ה","bp":"מעליץ","dt":"תשג","b":"נכד (בן בתו) ר נתן גולדברג מלימנוב בעל \"מאורות נתן\". מגדולי הפוסקים בדורו, רב בסמבור ישן אלטשטט-תרסז. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב. מאמר ממנו בשם השב\"ס ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":24978,"n":"ירוחם, שרגא זאב ממעליץ","f":"אפרים אריה","bt":"תקפט","dt":"תרנב","b":"רב במעליץ. פרסם מאמרים ב\"שערי תורה\" - קראקא תרפה."},{"i":24979,"n":"ירוחם, שרגא זאב פיבל מאלטשטט","f":"חיים יצחק","k":"בעל שרגא טהורה","bt":"תרנט","dt":"תשג","b":"חתן ר מנשה יחזקאל פרנקל מלימנוב. רב באלטשטט-תרפט. חיבר \"שרגא טהורה\" בסוף \"ברכת חיים\" לאביו."},{"i":24980,"n":"ירוטשינר, אברהם","f":"יהודה","dt":"תסח או לפניה","b":"בשנת תסב שליח ירושלים בברסלוי, בשנת תסז חתום על כתב רבנות לר דוד אופנהיים שנחתם בירושלים, בשנה זו שליח בפולין."},{"i":24981,"n":"ירושלים (1993-2005)","bk":[["פסקי דין ירושלים (א",""]]},{"i":24982,"n":"ירושלמי - משפחה","b":"משפחה בקושטא."},{"i":24983,"n":"ירושלמי, אברהם - הנכד","f":"יו\"ט","b":"נכד ר אברהם ירושלמי הזקן. מחכמי דורו-שן והוצא בספרי חכמי דורו ובהם בשו\"ת ר בצלאל אשכנזי. (אצל רוזניס מחליף בינו לבין זקנו)"},{"i":24984,"n":"ירושלמי, אברהם מקושטא - הזקן","f":"יום טוב","bt":"רכ-ן","dt":"שיח","b":"תלמיד הרא\"ם. רב קהלת הרומנים בקושטא, עלה לירושלים-ש' וחתם שם על תקנת המסים, חזר לקושטא. חתם על החרם של ר יוסף ן לב כנגד העיר אנקונא, הוציא לאור חומש עם הפטרות ומחזור כמנהג בני רומניאה עם מנהגי הקהלה - ונציה רפב. ר יוסף קארו בתשובה כותב כי ר אברהם רצה לנדות את המבי\"ט בגלל שהורה שלא לדעתו - אלא שחילו פניו ומחל לו. קרוב משפחה של ר אליעזר ירושלמי. נכדו - ר אברהם-תלמיד ר בצלאל אשכנזי."},{"i":24985,"n":"ירושלמי, אורי פיבש","f":"אורי פיבש מירושלים","b":"דרשן מחכמי ירושלים-שנות ה-ר'-ש', בשליחות בקראקא וישב שם כ-40 שנה. נזכר ב\"איתן האזרחי\"."},{"i":24986,"n":"ירושלמי, אליעזר","f":"יוסף","k":"בעל פנקס שאוולי","bt":"1900","bp":"הורודושץ-פלך מינסק","dt":"1962","dp":"חיפה","b":"למד היסטוריה בקובנא. בזמן השואה היה בגיטו שאוולי ושם עסק בהוראה במחתרת וריכז חומר רב על המאורעות. ניצל מהשואה, ואחריה מסר את החומר לצבא הרוסי - חלקו שימש במשפטי נירנברג, עבר לאיטליה והיה פעיל במחנות העקורים. עלה לארץ-1949 ופרסם מאמרים בעתונים וקבצים שונים. חיבר \"פנקס שאוולי\" - יומן הגיטו - ירושלים תשיח, \"ילדי השואה\", ועוד."},{"i":24987,"n":"ירושלמי, אליעזר מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'."},{"i":24988,"n":"ירושלמי, בנימין הנוסע הקראי","f":"אליהו","b":"נוסע קראי, היה בקושטא-תמו וכתב על כך."},{"i":24989,"n":"ירושלמי, ברוך מקושטא","f":"רפאל דוד","k":"בעל ברוך מבנים","dt":"תרנט - י אלול","dp":"ירושלים","b":"מחכמי קושטא שעלה לירושלים, חיבר \"ברוך מבנים\" ירושלים תרס","bk":[["ברוך מבנים",""]]},{"i":24990,"n":"ירושלמי, חיים יצחק אלתר","f":"מ\"ש מזדונסקוואלי"},{"i":24991,"n":"ירושלמי, יהודה מטשמליץ","b":"רב בטשמליץ-הונגריה. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":24992,"n":"ירושלמי, יום טוב מירושלים","b":"מחכמי ירושלים-שנות ה-ר'-ש', בקי ברפואה."},{"i":24993,"n":"ירושלמי, יחיאל מפרג","f":"יוסף בן קלונימוס","dt":"שנח - יז שבט","dp":"פרג","b":"מרביץ תורה בפרג."},{"i":24994,"n":"ירושלמי, יצחק אלימלך מירושלים","f":"רפאל מאיר","k":"בעל היא שיחתי","b":"מחכמי אזמיר, חלב, ירושלים. חיבר \"היא שיחתי\" קושטא תקצב."},{"i":24995,"n":"ירושלמי, יצחק הכהן מירושלים","f":"יוסף","k":"בעל פירוש על רות","b":"מחכמי ירושלים, ממשמיעי הגאולה. חיבר פירוש על מגלת רות ובו מגלה סוד הגאולה."},{"i":24996,"n":"ירושלמי, יצחק עזריאל מפיזרו","b":"מחכמי ירושלים-רפב, נזכר ב\"אבקת רוכל\"."},{"i":24997,"n":"ירושלמי, לוי מירושלים ובלגרד","f":"יצחק גרשון","k":"בעל בן אבות הלוי-כתי","r":"רב בקהילה האשכנזית בטמשוואר","bt":"תמא","bp":"ירושלים","dt":"תקיב - א אלול","dp":"טימישואר","b":"נמנה על חבורת ר יהודה החסיד שעלו לירושלים. חתם על כתב הרבנות של ר דוד אופנהיים. רב בבלגרד-תס - לשתי הקהלות האשכנית והספרדית (לפי רוזניס התחיל כרב הקהלה האשכנזית ובהמשך נתמנה לרב העדה הספרדית), ודרש גם באידיש וגם בלדינו ור נתן גינצבורג על מקומו אחריו, רב בטימישואר-תצט (לאחר שהתורכים כבשו את בלגרד מידי האוסטרים). בספר \"פנים מאירות\" לר מאיר אייזזנשטט מופיעים תשובות מר לוי ירושלמי מהשנים תצו-תצח, וכנראה שר' לוי היה בתקופה זו רב בבלגרד ומשם נשא ונתן עם ר מאיר.","bk":[["בן אבות הלוי - כנראה על פרקי אבות (כת\"י)",""]]},{"i":24998,"n":"ירושלמי, משה הלוי הקראי","f":"אליהו","b":"נוסע קראי, היה בירושלים בתחילת שנות ה-ת'."},{"i":24999,"n":"ירושלמי, נסים שמריה מקושטא","b":"דיין בקושטא וחתם עם דייני איסור והיתר-תקפד."},{"i":25000,"n":"ירושלמי, עמנואל מקושטא","f":"יום טוב","b":"גביר בקושטא. סייע בהדפסת \"דברי חפץ\"-תקנה לר אהרן טולידו."},{"i":25001,"n":"ירושלמי, רפאל דוד מקושטא","k":"בעל אהבת דוד","b":"רב בבאלאט-קושטא. חיבר \"אהבת דוד\" ונדפס בתוך ספר חברו ר רפאל שאקי - \"שמן ראש\". הספר נדפס ע\"י בנו ר ברוך ירושלמי."},{"i":25002,"n":"ירושלמי, רפאל יצחק מקושטא","dt":"תקלג - אחרי","b":"דיין איסור והיתר בקושטא-תקכט, אב\"ד. חיבר הקדמה ל\"מעם לועז\" ח\"ב-תצג, \"עין משפט\"-תקל, \"בני אברהם\"-תקלג. חתם על כתב שליחות ר חיים מודעי, ועוד."},{"i":25003,"n":"ירושלמי, שלום (שלם) מירושלים","f":"שלמה","k":"בעל אהלי קדר (קדש?)","b":"מחכמי ירושלים, בשנת רסט חתום על תקנת המס. חיבר \"אהלי קדש\" על חישוב תקופות ומזלות, ישב גם בצפת? יתכן והוא ר שלום בן שלמה בעל \"שבח שלמה\". בשנת רמב היה בעיר סרגוסה באי סקאליא ובמצוותו נכתב שם ספר \"יסוד עולם\" לר יצחק הישראלי ונגמרה כתיבתו בשנת רמד."},{"i":25004,"n":"ירושלמי, שלמה יצחק מירושלים","f":"מנחם זעקל","k":"בעל פירוש על רות","b":"מחכמי ירושלים, בשנת שי בשליחות, בשנת שיא הדפיס בשלוניקי את ספרו של ר יוסף כהן ירושלמי על רות ובשנת שיד את \"פרדס רמונים\" לר שם טוב ן שפרוט."},{"i":25005,"n":"ירושלמי, תנחום מארץ ישראל","f":"יוסף","k":"אבן עזרא של המזרח","b":"מחכמי ארץ ישראל במאה ה-13, מפרש המקרא, מדקדק. בקי בשפות ובמדעים. בזמן פלישת המונגולים ה'כ ברח למצרים, והיה מחכמיה. חיבר פירוש לתורה, מילון עברי ערבי בשם \"ספר המספיק\" - כתאב אלמרשד אלכאפי, ובו גם מנהגי ארץ ישראל בתקופתו."},{"i":25006,"n":"ירושלמסקי, אליעזר מקוריץ","f":"יחיאל מיכל מקוריץ","dt":"תשב - ה סיון","dp":"קוריץ","b":"אחיו של האדמור ר ברוך בן ציון יוזפוב מדובנא. נספה בשואה."},{"i":25007,"n":"ירושלמסקי, יוסף מקישינוב","f":"יחיאל מיכל מקוריץ","k":"אדמור מקישינוב","dt":"תשא","b":"אחיו של האדמור ר ברוך בן ציון יוזפוב מדובנא. אדמור בקישינוב כ-40 שנה. נספה בשואה."},{"i":25008,"n":"ירושלמסקי, יחיאל מיכל מקוריץ","f":"יוסף האדמור מברזנא","k":"אדמור מקוריץ ברזנא","bt":"תריח","dt":"תרעז - ז תשרי","b":"חתן ר אברהם יהושע השל מברדיטשוב (קמינקא). אדמור בקוריץ-והכתירו זקנו ר אהרן מטשרנוביל. נודע בקולו האדיר ובתפלותיו."},{"i":25009,"n":"ירושלמסקי, יעקב משה ממוש","k":"דירקטור,יעקב משה","bt":"תקעא או תקעה-ט","dt":"תרלט - כ אדר","b":"חסיד אדמורי לכוביץ. תלמידו בקבלה של ר יהונתן משה וואלינער בעל \"מרגניתא טבא\". רב בסטולוביץ, מוש-תריז (כך באלפסי), ומתוך קטלוג - תלמיד ר יצחק מוולוזין בישיבת וולוזין. חתן ר שמואל מייזל-אחיו של ר אליהו חיים. רב בשטאויץ(=שטלאויטש)-ליד נוברדוק, מוש-תריז. מקובל. נשא ונתן עם גדולי דורו ובהם ר יצחק אלחנן ור דוד טעביל ממינסק. החזיק בכתבי יד של הגר\"א בקבלה ועסק בהם רבות. נודע כאיש מופת ונזכר שמו בענין הוצאת דיבוק ב\"מגן וצנה\". בנו - ר ישראל יהונתן ירושלמסקי (נקרא ע\"ש רבו - בעל \"מרגניתא טבא\"), וחתניו: ר אברהם יצחק צימרמן מהלוסק, ובעל \"חלקת יעקב\" (נרשם שם תאריך פטירתו - תרלה)."},{"i":25010,"n":"ירושלמסקי, ישראל יהונתן מאיהומ","f":"יעקב משה דירקטור ממו","bt":"תרכ","b":"נקרא ע\"ש ר יהונתן משה וואלינער בעל \"מרגניתא טבא\" - שהיה רבו של אביו. חתן ר הרידב\"ז. רב בארלא-תרנב, איהומן-פלך מינסק. חתנו - ר יחזקאל אברמסקי בעל \"חזון יחזקאל\"."},{"i":25011,"n":"ירושלמסקי, משה נחום מאוסטרלנ","f":"בנימין","k":"בעל באר משה","r":"אב\"ד קאמינקא וקילעץ","bt":"תרטו","bp":"בערשיד-פודוליה","dt":"תרעו - כט סיון","b":"חתן הגביר ר יונה רוזנבלום מקראסילוב-ווהלין. מקורב ל\"דברי חיים\" מצאנז. פוסק ומשיב, רב בקמינקא-פלך קיוב-תרמ, אוסטרלנקה-פלך לומז'ה-תרנא, קיעלץ(=קילץ)-תרסב. בגיל 17 החתימו בעל השו\"מ על היתר 100 רבנים. חיבר גם \"מנחת משה\", ועוד. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"כנסת הגדולה\" - וארשא תרן, \"כנסת הגדולה\" - וארשא תרן, מאמר ממנו ב\"הפוסק\" - תל אביב תש-תשיד. הניח חבורים רבים בכת\"י, וכן ספריה גדולה ובה תשובות ומכתבים מגדולי דורו - רוב הכתבים נמצאים במכון שוקן בירושלים. בניו - ר דוד יונה, ר יהושע השל, שמשון דב.","bk":[["באר משה [ירושלימסקי]","שו\"ת - אחרונים"],["לשד השמן",""],["באר משה",""],["ברכת משה - שו\"ת",""],["יפה לבדיקה - שחיטה ובדיקת הריאה",""],["לשד השמן – על הרמב\"ם",""],["מנחת משה – שו\"ת",""],["משחת שמן הטוב - שבת",""],["ברכת משה",""],["מנחת משה",""],["לשד השמן","מפרשי רמב\"ם"]]},{"i":25012,"n":"ירושלמסקי, נחמיה מליובאן","f":"ישראל","bt":"תריד","dt":"תרץ","dp":"ירושלים","b":"רב בשמזיווא-פלך מינסק-תרמא, ליבן(=ליובאן)-פלך מינסק-תרנו, עלה לירושלים בשנת תרפא."},{"i":25013,"n":"ירחם אהרן בן חיים יצחק","bt":"1904","dt":"ה'תשכח 1968","bk":[["אהל רחל",""]]},{"i":25014,"n":"ירחמיאל הלוי מליסביק","f":"יעקב משה הלוי","b":"רב בליסביק-תר\"צ"},{"i":25015,"n":"ירחמיאל הפייטן","f":"שלמה","b":"פייטן, חיבר פיוטי קדושה לאמרם במקום שאין עשרה למנין, אולי הוא שחיבר \"מעשה כלי הנחשת\" על חכמת החשבון והתכונה."},{"i":25016,"n":"ירחמיאל יהודה מאיר","f":"האדמו\"ר מאפוצ'ינה","dt":"תשג"},{"i":25017,"n":"ירחמיאל מבוטשטש","b":"מחכמי זולקוא, חתם-תנא בזולקוא."},{"i":25018,"n":"ירחמיאל מהוסקוב","dt":"תקפו","dp":"צפת"},{"i":25019,"n":"ירחמיאל מוילנא","f":"מרדכי בן יעקב ישראל","dt":"תקעב - כט תמוז","b":"מחכמי וילנא. בניו: ר אברהם אליהו ר\"מ בוילנא, ר אריה הנאמן לצדקה בוילנא (הלבנון שנה ה), ר מרדכי פינס-אביו של ר ישראל יוסף. (לפי ריבלין תוח\"י - בנו של ר מרדכי בן ר מרדכי ר צמח'ס)."},{"i":25020,"n":"ירחמיאל מוילנא","f":"מרדכי","dt":"תקעג - כח תשרי","dp":"וילנא","b":"מחכמי וילנא, חתם בפנקס הקלויז הישן."},{"i":25021,"n":"ירחמיאל מויניגרד","b":"חתן ר מרדכי אריה ברמשנקה. רב בויניגרד-פלך קיוב-תרע."},{"i":25022,"n":"ירט, אליעזר ליבר מקשאנוב","f":"בנימין","bt":"תרם","dt":"תשב","b":"רב בקשאנוב. נספה בשואה."},{"i":25023,"n":"ירט, בנימין מבוכניה","b":"רב בבוכניה. נסמך מהחתם סופר. חתן משפחת ר ישראל סלנטר."},{"i":25024,"n":"ירמיה הלוי מחוליוב","b":"שו\"ב בחוליוב-תרטז, ברודי."},{"i":25025,"n":"ירמיה מאסאד","b":"רב באסאד"},{"i":25026,"n":"ירמיה מהלברשטט וברלין","f":"נפתלי הירש מהלברשטט","dt":"תקמב - ד אדר","b":"דיין בברלין."},{"i":25027,"n":"ירמיה מוורגונטו","b":"ממשפחה ותיקה בקנדיאה=כרתים, עלה לצפת ולמד אצל ר יוסף קארו (כמסופר ע\"י ר דוד קונפורטי), ועבר לקושטא וכיהן כממונה על החזקות-שסב, עם חבריו ר משה משלם הלוי, ר יום טוב ן יעיש ועוד. חי כמאה שנה. אגרת ממנו לר אליהו דלמידיגו ובה מספר כי למד בצפת גם אצל ר בצלאל אשכנזי ור שלמה סאגיש ור\"ז ן זיזא. תשובות ממנו בשות ר יחיאל באסן. (כנראה היה רב קדום יותר בעל אותו השם - ונזכר אצל ר אליהו קפשלי)."},{"i":25028,"n":"ירמיה מוילנא","f":"נחום","dt":"תקסה","dp":"וילנא","b":"שתדלן מחכמי וילנא."},{"i":25029,"n":"ירמיה מוילנא וירושלים","f":"מאיר","b":"מחכמי וילקומיר, וילנא, עלה עם ר סעדיה לירושלים. בנו - ר אברהם מאיר מירושלים."},{"i":25030,"n":"ירמיה מלייפניק","b":"רב בלייפניק"},{"i":25031,"n":"ירמיה ממטרסדורף וסנטוב","f":"יצחק איזיק","b":"רב במטרסדורף, סנטוב. חיבר עם בנו ר יואב פירוש על \"מודעה ואונס\" לר שבתי משלוניקי."},{"i":25032,"n":"ירמיה מקוניץ רוסטיץ ולייפניק","f":"אליקים גטשליק ואניפר","dt":"תקכו","dp":"ליפניק","b":"בן ר אליקים געטשליק וואניפרידן. תלמיד ר יונתן איבשיץ. אב\"ד רויסטיץ, ליפניק. נזכר ב\"גדולת יהונתן\". חתם בראש על החרם ברויסטיץ - \"על הנלחמים באדמ\"ו ר יהונתן איבשיץ\"."},{"i":25033,"n":"ירמיה מרימנוב","b":"תלמיד ר מנחם מנחם מנדל מרימנוב, והיה אחד מהשלושה שנשארו ברימנוב ונחשבו לממלאי מקום רבם - עד שר צבי הירש החל לנהוג אדמורות."},{"i":25034,"n":"ירמיה משלוניקי","dt":"תלח","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ. נספד ע\"י ר שלמה אמריליו."},{"i":25035,"n":"ירמיה מתתיה","f":"יעקב","k":"מפפד\"מ","dt":"תיא - כא אדר","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ-תא, בזמן ר שבתי הורביץ-בנו של השל\"ה."},{"i":25036,"n":"ירמיה סגל מברלין","f":"אפרים מאלטונא והמבור","dt":"תקמז - כט אלול","b":"מחכמי ברלין. החליף אגרות עם חברו ר אברהם מהלברשטט בענין התפשטות ההשכלה, ונדפסו ב\"געשיכטא דער יודען אין הלברשטט\" לר אוירבך מהלברשטט. אחיו של יהודה הלוי - זקנה של אדלייד אשת המשכיל יו\"ט ליפמן צונץ מברלין."},{"i":25037,"n":"ירמיה שארלין משקלוב וירושלים","dt":"תרטז - א אד\"א","dp":"ירושלים","b":"שו\"ב מחכמי ירושלים."},{"i":25038,"n":"ירמיהו מוילנא וטבריה","f":"יוסף","dt":"תקנה - לפני","b":"עלה מוילנא והיה מקהלת החסידים בטבריה בראשות ר אברהם מקאליסק. בשליחות קהילת החסידים-תקנא."},{"i":25039,"n":"ישבי, עזרא הכהן מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'."},{"i":25040,"n":"ישונסקי, יוסף","bt":"1881","bp":"גרודנא","dt":"1943","dp":"וארשא","b":"עסקן ציוני וציר בקונגרס החמישי, התרחק מהתנועה-1904. פרסם מאמרים בעונות היהודית-רוסית, תרגם ללרוסית. מעורכי האנציקלופדיה של ברוקהאוז-עפרון. מנהל הגימנסיה האידית בוילנא. פעיל ב\"ייווא\". נספה בשואה בגיטו וארשא."},{"i":25041,"n":"ישועה","f":"יפת","b":"מחכמי ארץ ישראל, ראש ישיבת \"גאון יעקב\" בשנת ד' תתעא (1111) כתב מכתב לר אליהו בן אביתר הכהן."},{"i":25042,"n":"ישועה","f":"נתן","b":"מחכמי ארץ ישראל, חתום על מכתבים מעזה למצרים \"ישועה בירבי נתן נין גור אריה\". חכם קהילת עזה וסופרה, חתם בשנים תשע-תת (1010-1040) בענין תביעת הירושה של מבורך בן נתן העזתי, חיבר קינה על פטירת בנו יחידו יאשיהו."},{"i":25043,"n":"ישועה הלוי החזן הפייטן","b":"פייטן, ומפיוטיו במחזור טריפולי, חיבר \"יערב שיחי לפני קדוש\". אולי הוא שאסף את שירי ר יהודה הלוי."},{"i":25044,"n":"ישועה הלוי מגיברלטר","f":"יצחק בעל פת לחם","k":"בעל לי לישועה","bt":"תקצו","bp":"גיברלטר","dt":"תרסו","dp":"ירושלים","b":"מחכמי גיברלטר בנו של הרב הראשי שם, רב בליסבון-פורטוגל-תרכה, היה מחכמי הקבלה כפי שהעיד ר מסעוד אלחדאד ראש ישיבת המקובלים \"בית אל\" בירושלים. חיבר גם \"אוצר החיים\"."},{"i":25045,"n":"ישועה הלוי מספרד","f":"אליהו","b":"מחכמי ספרד, אסף את שירי ר יהודה הלוי בדיוואן, עם הערות והקדמה ממנו בלשון ערבית."},{"i":25046,"n":"ישועה הלוי מספרד ואלגיר","f":"יוסף","k":"בעל הליכות עולם","bt":"קץ","bp":"תלמסן","dt":"רע - בערך","b":"תלמיד ר יעקב הכהן אשכנזי מאלגיר. מחכמי תלמסאן-אלגיר, ברח מעירו בגלל הפרעות ביהודי אלגיר-רכז, והתישב בטולידו. נתמך שם בידי הגביר דון וידאל בר לביא שסייע בידו להתפנות לכתיבת ספרו \"הליכות עולם\". חיבר גם שיטות לתלמוד ונזכר ע\"י ר בצלאל אשכנזי ב\"שיטה מקובצת\". ברשימת ר יצחק רוש נאמר כי הוא ר ישועה בן יוסף פרובנצאל - ואם כן חזר מטולדו לאלגיר והתישב בהוניין ומשם שאל את ר צמח דוראן."},{"i":25047,"n":"ישועה זרח מתונס","k":"בעל קול התור","b":"מחכמי תונס-[תק..] חברו של ר יוסף גג' בעל \"פי המדבר\"."},{"i":25048,"n":"ישועה מאלגיר","f":"שלמה","bt":"צ - בערך","dt":"קס - בערך","b":"רב במסתגאנם. העתיק-קכד \"ספר המשקל\" לר משה די ליאון, וספר המנהגות לר אשר בן שאול מוניל. עליו ב\"אסופות\" מאת בנימין ריצלר."},{"i":25049,"n":"ישועה מדמשק וחלב","b":"פייטן מחכמי חלב, עבר לדמשק-ת' בערך. גיסו - ר אברהם ן מיגש מדמשק."},{"i":25050,"n":"ישועה ממצרים","f":"צדקה","b":"רב במצרים בדור שאחר הרמבן, והיה מחותמי החרם נגד ר שלמה פטיט - שהיה מראשי החולקים על הרמבם."},{"i":25051,"n":"ישועה ממראקש","f":"יאיר","b":"רב במראקש במאה השביעית. (תר..?)"},{"i":25052,"n":"ישועה משטיפי","f":"אברהם","b":"מראשי קהלת שטיפי-שנות ה-ר'-ש'."},{"i":25053,"n":"ישועה סימון משלוניקי","b":"רב בשלוניקי-שנות ה-ש'."},{"i":25054,"n":"ישועה צבי","dt":"תקצז","dp":"צפת","b":"מחכמי צפת, בשנת תקמו בשליחות בצפון אפריקה, נהרג ברעש בתקצז"},{"i":25055,"n":"ישועה, שמואל מתימן","f":"יוסף","k":"בעל נחלת יוסף","b":"רב בעדן(תימן)-תרמ."},{"i":25056,"n":"ישורון - משפחה","b":"משפחת סוחרים עשירה בקושטא."},{"i":25057,"n":"ישורון, בנימין מקושטא","b":"גביר בקושטא-שנות ה-ת'. אחיו - יהודה."},{"i":25058,"n":"ישורון, דניאל מקושטא","dt":"שצח","dp":"קושטא","b":"גביר בקושטא."},{"i":25059,"n":"ישורון, חיים","k":"בעל \"אב. קאהן ביבליא","bt":"1885","bp":"וילנא","b":"היגר לארה\"ב-1907 והיה נשיא ה\"ארבעייטער רינג\" וציר בקונגרסים סוציאליסטים. פרסם ביוגרפיות של סופרי אידיש. עורך הקובץ \"ווילנע\" נ\"י 1935, ו\"דער ווילנער\" נ\"י 1929."},{"i":25060,"n":"ישורון, יהודה מקושטא","b":"גביר בקושטא-שנות ה-ת'. אחיו - בנימין."},{"i":25061,"n":"ישורון, יעקב דוד מקושטא","b":"גביר בקושטא-שנות ה-ת'."},{"i":25062,"n":"ישורון, ישראל מיכל ממינסק","f":"חיים מקרליץ","b":"תלמיד ר דובער מקרליץ. ר\"מ ודיין במינסק-תקפה בערך, הסכים על \"דרך תבונות\" מינסק תקצה עם ר שואל בן שלמה ור יהודה ליב די בוטין."},{"i":25063,"n":"ישורון, מרדכי מקושטא","b":"גביר בקושטא-שנות ה-ת', נודע בצדקותיו."},{"i":25064,"n":"ישורן, משה חיים מהמבורג","b":"רב קהילת הספרדים בהמבורג-תלח, בנו ר רפאל רב בקורסאו. מחותן עם ר יעקב ששפורטש מאמשטרדם."},{"i":25065,"n":"ישורן, רפאל מקורסאו","f":"משה חיים מהמבורג","bt":"תלח","bp":"[המבורג]","dt":"תקח - ו תשרי","dp":"קורסאו","b":"אביו היה רב קהילת הספרדים בהמבורג. תלמיד ר שלמה אאיליון מאמשטרדם. חתן ר יעקב ששפורטש מאמשטרדם. רב בקורסאו-תעה."},{"i":25066,"n":"ישי הכהן ממצרים","b":"חתן הגביר שמואל מונטקיו ממצרים, גביר במצרים-שנות ה-תק'. סייע לר ידידיה שלמה ישראל בהדפסת ספרי אביו. חתנו - הגביר ר ישי הכהן."},{"i":25067,"n":"ישי הפייטן","f":"מרדכי","b":"פייטן קדום, חיבר \"איש חסיד היה\" למוצ\"ש ונכנס למחזור ויטרי."},{"i":25068,"n":"ישי מאלגיר","f":"יעקב","dt":"ד'תשכג (963)","b":"רב בתאג'ורה-טריפולי, ובאלגיר."},{"i":25069,"n":"ישי מדמשק","f":"חזקיה בן ישי","b":"רב בדמשק-מו, בזמן ר דוד הנגיד נכד הרמב\"ם. היה מתומכי הרמב\"ם והמורה נבוכים וכתב אגרת לר דוד הנגיד בעכו ובה הסכמות מ-12 רבנים, וכן איים על רבנים שהוציאו דיבה על הרמבם."},{"i":25070,"n":"ישי מטריפולי","f":"יעקב","dt":"ד'תשכג","dp":"טריפולי - אדר","b":"רב בטריפולי. נוסח מצבתו ב\"הגיד מרדכי\" ירושלים תשלט."},{"i":25071,"n":"ישיא ן, אברהם","f":"שלמה","b":"פייטן-שנות ה-ק'. חיבר פיוט \"אדון שוכן מעוני\"."},{"i":25072,"n":"ישיבת אברהם מיוחס בירושלים","b":"ישיבה בירושלים-תקיח."},{"i":25073,"n":"ישייביץ-בן ישי, מ' חנ '","k":"בעל אור המאיר","bt":"תרלג","dt":"תש - טו אייר","b":"רב בטורצין-תרנ\"ה,בוואליה,ראב\"ד בטשנסטחוב-תרס\"ד,עלה לתל אביב-תרפ\"ה,רב שכונת נוה שאנן"},{"i":25074,"n":"ישכר בער הכהן מהמבורג","f":"זליג מן","bp":"ורמיזא","dt":"תפה - פסח","dp":"אלטונא","b":"נכד ר יעקב יוסף מוורמייזא. רב בהמבורג, ומיסד הקלויז בראשות ר שמשון בלוך. מבניו: ר זליגמן יהודה, ר מאיר מהנובר, חתניו: ר אליהו אופנהיים, ר יהושע השל סגל מקידאן. נזכר במגילת ספר על הסכם שעשה עם ר יחזקאל קצנלנבוגן - שימונה לרב באה\"ו ובתמורה ידאג למינוי חתנו ר יהושע לרב בקידאן."},{"i":25075,"n":"ישכר בער מבירז","f":"אליהו מעיר חדש","b":"רב בבירז"},{"i":25076,"n":"ישכר בער מבריסק","b":"ספרא ודיינא בבריסק. חתם-שפו בהוראת הר\"מ וייל."},{"i":25077,"n":"ישכר בער מדאברא","dt":"תשג","b":"רב בדאברא"},{"i":25078,"n":"ישכר בער מוילנא","f":"אברהם","dt":"תקטו","dp":"וילנא","b":"מראשי קהלת וילנא. אחיו - ר יהודה ליב מוילנא."},{"i":25079,"n":"ישכר בער מוילנא-אחי","f":"שלמה זלמן מוילנא","k":"בעל צוף דב\"ש,הגר\"א","dt":"תקסז - יט אלול","dp":"וילנא","b":"חתן ר אשר גינצבורג. גדול בתורה ומדעים, מגדולי וילנא. חיבר \"צוף דב\"ש\" בכת\"י - והיה בידי נכדו ר ישכר בער קלצקי מוילנא. בנו ר קלמן, חתניו: ר בנימין וולף קלצקי-בן ר שמעון גינצבורג, יעקב בן אברהם כהנא."},{"i":25080,"n":"ישכר בער מוילנא-זקנו של הגר\"א","f":"אליהו חפץ חסיד","b":"נכד ר משה קרמר מוילנא. מחכמי וילנא. אחיו - ר משה מקובנא, ר צבי הירש מוילנא. בנו - ר שלמה זלמן אביו של הגר\"א."},{"i":25081,"n":"ישכר בער מולאדובה","f":"ישראל","b":"דיין בולאדאווי(=ולאדובה), חתם-תקכה בפנקס קהלת לבוב."},{"i":25082,"n":"ישכר בער מזאבני","b":"רב בזאבני-תפ\"ה"},{"i":25083,"n":"ישכר בער מזבראז","b":"תלמיד ר מנחם מנדל מפרמישלן, והביא מתורת רבו ונדפסו ב\"יושר דברי אמת\" לר משולם פיבש מזבאריז."},{"i":25084,"n":"ישכר בער מזולקוא","f":"משה ברוך","b":"מחכמי זולקוא, חתם-תסד בפנקס הקהלה."},{"i":25085,"n":"ישכר בער מזסלב","f":"שמחה בונם-נכד המהרשא","dt":"תקנד","dp":"טבריה","b":"תלמיד הבעשט, המגיד ממזריטש. אב\"ד זסלב. גזבר \"מעות ארץ ישראל\" ו\"כולל רייסין\" בוואהלין. עלה לארץ והתישב בטבריה."},{"i":25086,"n":"ישכר בער מחדרקוב","b":"רב בחדרקוב-תק\"ס"},{"i":25087,"n":"ישכר בער מטולטשין ואוסטרהא","f":"פנחס מלודמיר ואוסטרה","dt":"תקלט - ב שבט","dp":"אוסטרהא","b":"אב\"ד טולטשין, עבר לאוסטרהא - מקום מושבם של אביו ואחיו ר אריה ליב. נפטר בחיי אביו."},{"i":25088,"n":"ישכר בער מיארטשוב","f":"עזריאל מיארטשוב","dt":"תקנד - כט שבט","b":"פרנס,מנהיג ביארטשוב"},{"i":25089,"n":"ישכר בער מירושלים","b":"מחכמי ירושלים, בשליחות-תקיד באיזנשטט - שם נפטר בנו ר איזיק ליב."},{"i":25090,"n":"ישכר בער מלבוב","f":"ראובן","b":"דיין בלבוב, חתם-תקסו על פסק דין בענין עזבון לטובת יתומים. אחיו - ר מרדכי גימפל מלבוב בעל \"מפלגי ראובן\"."},{"i":25091,"n":"ישכר בער מלבוב - א","dt":"תכו - יג אד\"א","b":"גדול בנגלה ונסתר,רב בלבוב"},{"i":25092,"n":"ישכר בער מלבוב - ב","b":"מנהיג בלבוב, חתם-תקד על כרוז ותקנה, ועוד."},{"i":25093,"n":"ישכר בער מלובלין","f":"אלחנן הקדוש","dt":"ת - ו אדר","b":"גביר ופרנס בלובלין."},{"i":25094,"n":"ישכר בער מלוברנץ","b":"רב בלוברנץ."},{"i":25095,"n":"ישכר בער מליובאוויטש","dt":"תקמו","b":"תלמיד המגיד ממזריטש, ופגש גם את הבעשט, רבו של ר שניאור זלמן מליאדי בילדותו בליובאוויטש. בשנת תקלה הנהיג עדת חסידים אך פרש וקיבל את מרותו של ר מנחם מנדל מויטבסק. בנו ר יוסף מחשובי חסידי ליובאוויטש."},{"i":25096,"n":"ישכר בער מנאחוד","b":"רב בנאחוד-תפ\"ה"},{"i":25097,"n":"ישכר בער מסלוצק","b":"רב בסלוצק-תקמ\"ג"},{"i":25098,"n":"ישכר בער מסקול","b":"רב בסקאהל-תרי\"ט"},{"i":25099,"n":"ישכר בער מפרוסטיץ","b":"רב בפרוסטיץ-תק\"י"},{"i":25100,"n":"ישכר בער מצילץ והוצנפלוץ","f":"עובדיה הקדוש","k":"בער סאטאניא","dt":"תסא - ח סיון","dp":"קרעמזיר","b":"רב בביהנדין, צילץ, הוצנפלוץ(=האטצינפלאץ), גלוגא, זולקוא, קרעמזיר-תנז. הסכים על \"מגיני ארץ\", \"דרך שיח\"-תנב, \"תפארת הקדש\"-תסג, \"בית יהודה\"-תנח. נזכר ב\"לקוטי שושנים\" לר מאיר מזולקוא, חתם-תנד בפנקס הקהלה בזולקוא, נזכר במכתב הרופא שמחה מנחם בן יוחנן ברוך מיונה."},{"i":25101,"n":"ישכר בער מקובלניק","b":"רב ומוכיח בלובביץ-תקי\"ג"},{"i":25102,"n":"ישכר בער מקרוטושין","b":"תלמיד ר צבי הירש בושקא מגלאגוי ואה\"ו. ראב\"ד בקאראטשין-תקנ."},{"i":25103,"n":"ישכר בער מרוסטיץ","f":"פרץ דיין","k":"בעל בית פרץ","b":"רב ברוסטיץ,דיין בניקלסבורג-ת\"פ"},{"i":25104,"n":"ישכר בער מריטאווע","f":"שלמה זלמן","b":"דרשן,מגיד בריטאווע"},{"i":25105,"n":"ישכר בער משקלוב","b":"דיין בשקלאב-תקמ\"ג"},{"i":25106,"n":"ישכר בער מתמיד ממינסק","b":"ר\"מ במינסק-תר."},{"i":25107,"n":"ישכר בר מניקלשבורג ונייטרא","b":"אב\"ד נייטרא-תקנז. תשובה ממנו לבעל \"אור חדש\" בשו\"ת מהרנ\"ש - מונטריאול תשד."},{"i":25108,"n":"ישכר בריש הכהן מזלוזיץ","b":"רב בזלוזיץ"},{"i":25109,"n":"ישכר בריש הלוי מטשכנוב","f":"יהושע הלוי","b":"רב בטשעכנאווא-תקי\"ב,נאמן דד\"א"},{"i":25110,"n":"ישכר בריש מטרנוב","b":"רב בטרנוב-תרעג."},{"i":25111,"n":"ישכר בריש מסאליץ","b":"רב בסאליץ"},{"i":25112,"n":"ישכר בריש משקלוב","b":"רב ביאברוב-תר\"מ"},{"i":25113,"n":"ישכר ברמן הלוי סגל","k":"בעל מטה יששכר","bt":"תך - בערך","bp":"וינה","dt":"תסט - טז תשרי","b":"רב בגלילות שוואבך-תקל, שנייטוך-תקנה, פיורדא וראש ישיבה שם. (התאריכים לא מסתדרים - אולי היו שני רבנים)."},{"i":25114,"n":"ישכר ברמן מאויבן","b":"רב באויבן-שנת ת'"},{"i":25115,"n":"ישכר ברצי מנדבורנא","f":"יצחק מקאליש","dt":"תרח - ב אלול","b":"איש מופת,רב בנדבורנא"},{"i":25116,"n":"ישכר דב - תלמיד ר לוי יצחק","b":"תלמיד ר לוי יצחק מברדיטשוב. הו\"ל \"הזכירה\" עם הערות ר לוי יצחק, ועם הקדמה ממנו."},{"i":25117,"n":"ישכר דב בער מירושלים","f":"ישעיה","dt":"תקפח","b":"מחכמי ירושלים. בנו - ר ישעיה ברדקי."},{"i":25118,"n":"ישכר דב בר מברזן","f":"אהרן ליב מפרעמישלן","bt":"תקסח","dt":"תר - כו טבת","b":"נכד האדמור ר מאיר מפרמישלן. רב בברזן."},{"i":25119,"n":"ישכר דב בר מפרשבורג","f":"אורי שרגא פיבל מליסא","k":"בעל באר טוב","dt":"תקע - ח כסלו?","dp":"פרשבורג","b":"תלמיד ר יעקב כץ בעל \"שב יעקב\", ור מאיר א\"ש בעל \"פנים מאירות\". חתן ר וולף וואלנער מפוזנא. ממגורשי ליסא, נדד רבות בפולין ואשכנז, מחכמי פרשבורג - ונתמך בידי ר אליהו אופנהיים, ור אברהם גוגנהיים. חיבר \"באר טוב\" אלטונה. בנו ר יצחק - נפטר בחייו. (ספרו נדפס בשנת תצז - תאריך פטירתו מתוך אוצר הרבנים והוא טעות - זהו תאריך פטירתו של נכדו ר שמואל בן דוד). בניו - ר איצק, ר דוד, ונכדו ר שמואל והוא שנפטר ב-ח כסלו תקע. בין המסכימים על ספרו - ר משה חגיז מירושלים."},{"i":25120,"n":"ישכר דב בר מקרמניץ","f":"פתחיה משה","k":"בעל יש שכר","b":"מקובל-שנות ה-ש'. חיבר \"יש שכר\", פירוש על הזהר עם הסכמה מהרמ\"ע, \"אמרי בינה\"."},{"i":25121,"n":"ישכר דב בר מרדושיץ","f":"יצחק","k":"סבא קדישא מרדושיץ","bt":"תקכה","dt":"תרג - יח סיון","b":"תלמיד החוזה מלובלין, ור ישראל המגיד מקוזניץ, ור אברהם יהושע השל מאפטא. גדול בעלי המופת בדורו, סיפר ש\"שימש מאה ועשרים בעלי רוח הקודש\". רב ברדושיץ-תקצא, פשדבורז. מתורתו ב\"דברות חיים\", ומתולדותיו ב\"נפלאות הסבא קדישא\". בנו ר ישראל יצחק בארון."},{"i":25122,"n":"ישכר דב בריש מקראקא","f":"אברהם יהושע השל מקרא","dt":"תנא - כט תשרי","b":"חתן ר דוד כתבן (ולפי איזנר-תולדות ר דוד לידא - היה חתן ר מרדכי יולס מקראקא. פרנס הדור בקראקא, ראש ועד ארבע ארצות. בניו ר יצחק מקראקא אבי משפחת באב\"ד, ר אלעזר באב\"ד, ר משה, ר יהשע השל באבד. חתניו - ר שלמה בעל \"מגלה עמוקות\" (לדעת צונץ - קראקא זו טעות וחתנו - ר גבריאל אשקלס מניקלשבורג), ר יהושע הלוי."},{"i":25123,"n":"ישכר דב ברנארד","f":"צבי הירש","k":"בעל אמרי יושר","bt":"תקסא","bp":"דרזדן","dt":"תרכא - כג תמוז","b":"משכיל בדרזדן, דרש בגרמנית, יסד בית ספר מתוקן ברוח מנדלסון. חיבר ספרים ופרסם מאמרים בכתב עת. מקורב לר זכריה פרנקל בדרזדן. בעל ספריה גדולה והורישה לביהמ\"ד לרבנים בברסלוי."},{"i":25124,"n":"ישכר דב הלוי מסינער וארלי","b":"חתן ר יחזקאל בנט. רב בסינער-ואראלי(=וואראהל) על מקומו אחריו-אחרי תרעג."},{"i":25125,"n":"ישכר דב חסיד מלבוב","f":"משה","dt":"תכד - ג אד\"א","dp":"לבוב","b":"מקובל, דיין בלבוב."},{"i":25126,"n":"ישכר דב מדרוהוביטש","f":"אריה ליב","k":"בעל חוט המשולש","b":"רב בדרוהביטש-ת\"ר"},{"i":25127,"n":"ישכר דובער ממינסק","f":"אליהו","k":"בער מתמיד","dt":"תרלט - טז תשרי","dp":"מינסק","b":"מחכמי מינסק."},{"i":25128,"n":"ישכר ישראל ממרוקו","dp":"אקק'א בנוף סוס-מרוקו","b":"מחכמי מרוקו ומלומד בנסים. ובמקום קברו יש מעין ומימיו מבורכים."},{"i":25129,"n":"ישכר מליבאוי","b":"רב בליבאוי."},{"i":25130,"n":"ישכר מקישינוב","k":"ר ישכר הגדול","b":"תלמיד הבעשט. חתן ר מרדכי משאריגראד. ממפיצי החסידות בבסרביה."},{"i":25131,"n":"ישכר סגל מנביליץ","dt":"תרל","dp":"רישא","b":"רב בנביליץ."},{"i":25132,"n":"ישכר סופר מפשוורסק","b":"רב בפשוורסק."},{"i":25133,"n":"ישכר עוזיאל מאזמיר","bp":"מאגנישיאה","b":"ראש השוב\"ים באזמיר-תכב."},{"i":25134,"n":"ישמעאל הכהן מיזד-פרס","f":"פנחס-מולא המאיון","bt":"תריא","bp":"יזד-פרס או האמדאן","dt":"תרפט - כד אב","dp":"צפת","b":"בן לרב של יזד-פרס, יצא עם הוריו בדרכם לארץ - אך בגלל פטירת אביו נשאר בבגדד אצל דודו העשיר אג'א הומאיון. תלמיד ר יוסף חיים הבן איש חי בישיבתו, ר יעקב הכהן פקלי מצפת. עלה לארץ עם דודו והתישבו בצפת ודודו רכש חצר שהקדישה לבימ\"ד. חתן ר משה הכהן נהר בעל \"כסא דברכתא\" מתירייא. תלמיד ר יעקב הכהן סקילי מטבריה. דיין בצפת-תרלו. בשליחות הקהלה בצפון אפריקה ומצרים והודו-תרנד. בזיוו\"ש חתן ר חיים דוד צוריאנו מאיידין (ליד אזמיר). רב ראשי בצפת-תרס, טיריא-ליד אזמיר-תרסו, מגנסיא(=מגניסיא)-תורכיה, וחזר לכהן כרב בצפת. נרצח ע\"י ערבים עק\"ה."},{"i":25135,"n":"ישמעאל הכהן מצפת","b":"ראב\"ד בצפת-תרסה"},{"i":25136,"n":"ישמעאל חזק","k":"בעל סופר מהיר","b":"חיבר \"סופר מהיר\" ובסופו \"מגילת ספר\" לר מלאכי קולורני (חיים מיכל - אוצרות חיים)."},{"i":25137,"n":"ישמעאל חנינא מוואלמונטו","b":"רב בפיררה-שנות ה-ש'-ת'. רבו של הרמ\"ע מפאנו. מוזכר ב\"באר עשק\", תשובה ממנו ב\"פחד יצחק\"."},{"i":25138,"n":"ישמעאל יואל (רוזנבלט)","f":"משה מאייבנשיץ","dt":"תקפה","b":"ספרא דמתא ודיין על מקום אביו. חיבר-תקמו את נוסח החרם על החסידים."},{"i":25139,"n":"ישמעאל ממצרים","f":"חכמון","b":"מחכמי מצרים, חיבר פירוש על הרמב\"ם."},{"i":25140,"n":"ישעיה (סעדיה) מבריסק","f":"משה ליזרס","b":"גביר מחכמי בריסק-שצט. שליח קהלת וילנא יחד עם אחיו ר יעקב אליעזר לברך את המלך בקראקא."},{"i":25141,"n":"ישעיה אורי","b":"מחכמי צפת, מתלמידי הארי, אחד משלושת מנהיגי קהילת האשכנזים בצפת בשנת שע."},{"i":25142,"n":"ישעיה באוזירן","b":"רב באוזירן-תרכא."},{"i":25143,"n":"ישעיה הכהן ייאיש"},{"i":25144,"n":"ישעיה הכהן מבאייא","b":"רב בבאייא"},{"i":25145,"n":"ישעיה הכהן מויטבסק","b":"חתן ר אהרן שמואל קיידנובר בעל \"תפארת שמואל\"."},{"i":25146,"n":"ישעיה הכהן מחברון","b":"מקובל,רב בחברון-ת\"כ"},{"i":25147,"n":"ישעיה הכהן מטאפיא-סעלא ובאייה","f":"ישראל","b":"רב בטאפיא-סעלא ור פנחס ליב הכהן על מקומו אחריו, ביאה על מקום ר טוביה הארשיץ ור מאיר א\"ש על מקומו אחריו-תקסג. היה במחלוקת עם ר פנחס ליב הכהן שמילא את מקומו בטאפיא-סעלא אודות גט."},{"i":25148,"n":"ישעיה הכהן מטריפולי-לבנון","f":"יוסף מטריפולי-לבנון","b":"גביר ומשורר בטריפולי, עבר לביירות, חלב. תמך בר ישראל נג'ארה שחיבר שיר לכבודו."},{"i":25149,"n":"ישעיה הכהן ממראקש","f":"יוסף","dt":"תקט - בערך","b":"תלמיד ר אברהם אזולאי. מחכמי מראקש בתחילת המאה ה-18. תלמידו ר שלום בוזגלו מספר עליו בהקדמה ל\"מקדש מלך\". חתם על פס\"ד-תצב. יסד ביכ\"נ במראקש ונקראת על שמו."},{"i":25150,"n":"ישעיה הלוי","b":"מגדולי חכמי בהמן"},{"i":25151,"n":"ישעיה הלוי","f":"אברהם מזולקוא","k":"בעל באר היטב הראשון","dt":"תפג","b":"נכד הט\"ז. נשרף במלון בדרך לארץ(עם משפחתו). חיבר \"באר היטב\" על או\"ח. (שם אביו ע\"פ בובר-זולקוא - לא מסתדר עם היותו נכד הט\"ז)."},{"i":25152,"n":"ישעיה הלוי מברודי","k":"בעל חרב פיפיות","b":"מקובל,מחכמי ברוד-תק\"כ"},{"i":25153,"n":"ישעיה הלוי מניו יורק","bt":"תרמב","dt":"תרצא - ו חשון","b":"רב בניו יורק"},{"i":25154,"n":"ישעיה וילנער","b":"תלמיד ר חיים חייקא מאמדור ור מרדכי מלכוביץ. רב בוילנא."},{"i":25155,"n":"ישעיה זוחאוויצר","b":"צדיק מפורסם, הוערך מאוד ע\"י הגר\"א."},{"i":25156,"n":"ישעיה יעקב מברוד","f":"יהודה ליב הלוי","k":"בעל בית המלכות","bt":"תק","dt":"תקסז","b":"רב בטשיהאן, אלעסק. חיבר \"וחרב פיפיות\" למברג תקמו, \"בית המלכות\" קראקא תרנב."},{"i":25157,"n":"ישעיה יעקב מדמביץ","b":"רב בדמביץ-תרכג."},{"i":25158,"n":"ישעיה ירוסלב","f":"יעקב ירוסלבסקי","k":"בעל דברי ישעיה","bt":"תקטו","bp":"דזיאלושיץ","dt":"תקצא","b":"ממשכילי דזאלשיץ-ליד קראקא. גיסו של ר צבי הירש אב\"ד וושניצע. היה חסידו של רמבמ\"ן (מנדלסון)."},{"i":25159,"n":"ישעיה ליב מעיר חדש","b":"דיין בעיר חדש-תקעה."},{"i":25160,"n":"ישעיה מאורזיסטשוב","f":"אברהם מאורזיסטשוב","k":"אדמור מאורזיסטשוב","dt":"תרעט - יז חשון","b":"חתן ר פנחס מסוקוליבקא (ליניץ). נפטר בצעירותו."},{"i":25161,"n":"ישעיה מאידליץ","b":"רב באיידליץ-תק\"ל"},{"i":25162,"n":"ישעיה מבוריסוב","b":"אב\"ד בוריסוב."},{"i":25163,"n":"ישעיה מבוריסלב","b":"מו\"צ בבוריסלב"},{"i":25164,"n":"ישעיה מברידא ונייטרא","b":"רב בנייטרא-תקכט, חתם לפני ר אהרן ברלין מנייטרא."},{"i":25165,"n":"ישעיה מדינוביץ","k":"אדמור מדינוביץ","b":"מראשוני החסידות בדינוביץ"},{"i":25166,"n":"ישעיה מויטקוב","dt":"תפד - יא כסלו","b":"רב בוויטקוב"},{"i":25167,"n":"ישעיה מוילנא","f":"משה","dt":"תקע - כו אלול","dp":"וילנא","b":"מחכמי וילנא."},{"i":25168,"n":"ישעיה מוילנא","f":"יצחק","dt":"תקפא - יג אלול","dp":"וילנא","b":"מחכמי וילנא."},{"i":25169,"n":"ישעיה מזברז","f":"אליעזר ליפמן","b":"רב בזברז-תקנד."},{"i":25170,"n":"ישעיה מזולקוא ולבוב","f":"יצחק","dt":"תכה - ל שבט","dp":"לבוב","b":"ראב\"ד בזולקווא, ר\"מ בלבוב. חתם-תכד בפנקס קהלת לבוב עם בעל הט\"ז על פס\"ד."},{"i":25171,"n":"ישעיה מטפלטשאן","b":"רב בטאפאלטשאן-תקפ\"ח"},{"i":25172,"n":"ישעיה מטרני","f":"מהרימ\"ט"},{"i":25173,"n":"ישעיה מיאנוב-דינוביץ","dt":"תקנד - כב אייר","b":"תלמיד הבעשט וכתב את צוואתו, ור ליבר מברדיטשוב. חתן ר יעקב יהודה יודל מאוסטראה. רב ביאנוב-תקל. החזיק בכת\"י של \"צוואת הריב\"ש. מכתבים ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":25174,"n":"ישעיה מיריסלב","f":"נתן נטע","b":"אב\"ד יריסלב(=יעריסלא), חתם-תנז על תקנה בענין מדפיסי זולקוא."},{"i":25175,"n":"ישעיה מלבוב","f":"אהרן משלם","dt":"תצג - ט תשרי","b":"דומ\"צ בלבוב"},{"i":25176,"n":"ישעיה מלבוב","f":"יוסף","dt":"תיג - כה כסלו","dp":"לבוב","b":"מרביץ תורה, רב בלבוב, חתם-תט עם ר נפתלי הרץ בן יהודה זעלקל, ר נחמן בן מאיר רפפורט, ר יוסף בן יצחק."},{"i":25177,"n":"ישעיה מלבוב","f":"מנחם מנדל","b":"רב בלבוב? חתם ראשון על פסק דין של ועד ארבע ארצות יחד עם ר משה פנחס חריף - תנז."},{"i":25178,"n":"ישעיה מלויצק","f":"אהרן (משה) משלם","dt":"תפח - אחרי","b":"דיין ור\"מ ומו\"צ בלבוב, חתם-תנז על תקנה בענין מדפיסי זולקוא, חתם-תפח על פסק דין."},{"i":25179,"n":"ישעיה ממוש מויגובה","b":"רב בויגובה על מקום ר חיים הירש שולביץ."},{"i":25180,"n":"ישעיה מנדל מפפד\"מ - ב","k":"מנדל ר אביגדורס","b":"תשובה ממנו ב\"חוט השני\" משנת תכב (ואינו ר ישעיה מנחם ר אביגדורס מקראקא)"},{"i":25181,"n":"ישעיה מנחם מנדל ר אביגדורס מקר","f":"יצחק","k":"בעל עמודי גולה","dt":"שנט - כה אב","dp":"קראקא","b":"פוסק ומרביץ תורה, ר\"מ בשברשין, רב בלודמיר, קראקא על מקום המהר\"ם מלובלין. מחבר \"היתר עיסקא\" - הטופס המקובל להלוואות. הסכים על \"מתנות כהונה\". חיבר גם \"ביאורים כבדו ה' על התורה\", \"תיקון שטרות\". בניו - ר משה ר מנדלש מפפד\"מ, ר יוסף, ר אברהם.","bk":[["באורים כבדו ה', תקנת היתר עיסקא",""]]},{"i":25182,"n":"ישעיה מנשה מאיסטריה","b":"סוחר מראשוני היהודים באיסטריה(=מיליסטרה)-תקסו."},{"i":25183,"n":"ישעיה מסלנט וקרוז'","f":"אליהו","b":"דיין בקרוז'. רב בסלנט. צדיק מפורסם, ממתנגדי שיטת המוסר."},{"i":25184,"n":"ישעיה מספרד","f":"אבא מארי אשטרוק","b":"מחכמי ספרד, תלמיד ר מתתיה טריווש בפאריס, רב בברישא במדינת סבוי-קלה - שלא ברשות רבו - ר מתתיה ובנו ר יוחנן - והיה מחלוקת על כך, והובאה לפני הריב\"ש."},{"i":25185,"n":"ישעיה מפשדבורז","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט. (אולי הוא ר ישעיה ולטפרויד)"},{"i":25186,"n":"ישעיה מקוולא","f":"נתן נטע","b":"רב בקוולא-תע\"ב-תפ\"ב"},{"i":25187,"n":"ישעיה מקוידנוב","b":"תלמיד ר מרדכי מלכוביץ. בנו ר צבי מיכל מטבריה."},{"i":25188,"n":"ישעיה מקולבסוב","dt":"תקכד - ד אלול","b":"רב בקולבסוב"},{"i":25189,"n":"ישעיה מקמניץ","b":"רב בקמניץ-תר\"ל"},{"i":25190,"n":"ישעיה משאוולי","f":"נח","b":"שו\"ב בשאוולי-תרסד, חתם על סמיכה לשוחט."},{"i":25191,"n":"ישעיה משה מקושטא","f":"אליהו","b":"רב בקושטא. נזכר ב\"רב דגן\" לר יצחק הלוי."},{"i":25192,"n":"ישעיה משלוניקי וירושלים","f":"שמואל בכר משה","bt":"תרד","bp":"סופיה-בולגריה","dt":"תרפח - ו תמוז","dp":"ירושלים","b":"גביר מחכמי שלוניקי, עלה לירושלים. רכש את חצר הרב מרדישקביץ בירושלים והקים שם ישיבה וביכ\"נ, חבר בכולל עדת הספרדים, פעיל צבור ואיש חסד."},{"i":25193,"n":"ישעיה ן, אברהם מברצלונה","f":"יהודה","b":"מחכמי ברצלונה-ן' וחתם בתשובות הרשב\"א עם חכמי ברצלונה."},{"i":25194,"n":"ישעיה סגל מירושלים","f":"יהודה (החסיד?)","b":"מחכמי ירושלים, חתם על מכתב רבני ירושלים לברסלוי-תעז ולר דוד אופנהיימר."},{"i":25195,"n":"ישעיה סגל מלבוב","f":"יחיאל","dt":"תח - יג אדר","dp":"לבוב","b":"תלמיד מהר\"ם מלובלין. מרביץ תורה, דיין בלבוב."},{"i":25196,"n":"ישעיה סעדיה","f":"ישראל מירקין","b":"רב בבעליצא"},{"i":25197,"n":"ישעיה פרץ","b":"שו\"ב מומחה, היה באזמיר-תכה ונשאל שם בענין שחיטה."},{"i":25198,"n":"ישעיה פרץ מבלגרד","b":"גביר מחכמי בלגרד-שנות ה-ת'."},{"i":25199,"n":"ישעיה ריישעס","dt":"תקע","b":"תלמיד ר שלמה מקרלין, ור מרדכי מלכוביץ."},{"i":25200,"n":"ישעיה שלום ממדבידובקא","f":"יהודה מדאשיב","b":"רב במבידובקא על מקום אביו. עלה לצפת בסוף ימיו."},{"i":25201,"n":"ישעיהו, אביתר","bt":"תקצט","dt":"תרפז - יח אב","b":"עלה מדגיסטן,רב בא\"י לבני עדתו"},{"i":25202,"n":"ישעיעויץ, מאיר חנוך מצנסטחוב","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":25203,"n":"ישפה, ירחמיאל מוישינטה","dt":"תשג","b":"רב בבוגסלבישק, רבה האחרון של וישינטה. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":25204,"n":"ישראל","k":"חתן ר אלימלך מליזנסק","b":"רב-שנת תק\"צ"},{"i":25205,"n":"ישראל","f":"יהודה","b":"רב-שנת תק\"פ. בנו ר יהודה."},{"i":25206,"n":"ישראל","f":"יונתן","k":"בעל אור ישראל","b":"חיבר \"אור ישראל\" - אמשטרדם."},{"i":25207,"n":"ישראל (שכנא) מלובלין (כץ)","f":"שלום שכנא מלובלין","dt":"שנט - א כסלו","b":"מגדולי חכמי דורו, ראש ישיבה בלובלין. בניו - ר משה חריף מקרמניץ(14711) חתניו - ר נפתלי הירש שור מבריסק ולובלין, ר שפטל הורביץ מוינה(18052)."},{"i":25208,"n":"ישראל - בנימין השני","f":"יוסף בנימין","k":"בעל מסעי ישראל","bp":"פלטשיני-מולדובה","dt":"תרכד - כח ניסן","dp":"לונדון","b":"חוקר קהלות ישראל, פרסם ספרים על מסעותיו בקהלות המזרח."},{"i":25209,"n":"ישראל - נין הבעשט","f":"שמחה","k":"רבי ישראל מת","b":"נינו של הבעשט - מצד אמו ואחיו של ר נחמן מברסלב. חתן נכדת ר משה מקיטוב-תלמיד הבעשט. כינויו \"רבי ישראל מת\" ע\"ש מעשה שהיה בילדותו - שפרחה נשמתו, ואמו - נינת הבעשט התפללה על קברו ונתעורר. נתמנה לאדמור על מקום ר נח מלכוביץ - אך סירב. בנו ר ישכר דב."},{"i":25210,"n":"ישראל אבא משלוניקי","b":"חברו של ר דוד קונפורטי הזקן. גיסו של ר מרדכי קלעי (היו נשואים לשתי אחיות). רב ודיין בשלוניקי-שסח יחד עם ר חיים שבתי ור יהודה עוזיאל. רב באישקופיה (ליד שלוניקי)-שעז."},{"i":25211,"n":"ישראל אביגדור מספיזישוק","b":"רב בספיזישוק-ליטא."},{"i":25212,"n":"ישראל אבליש מזולקוא","f":"משה","b":"חתם-שפו על תקנת קהלת זולקוא."},{"i":25213,"n":"ישראל אברהם מטשרני-אוסטרהא","f":"זושא מאניפאלי","r":"נדפ' בתקיפא דארעא דישראל","bt":"תקלב","dt":"תקעד - כא טבת","b":"חתן ר זאב וולף מטשרני-אוסטרהא. אדמור בטשרני-אוסטרהא על מקום חותנו שעלה לארץ. הו\"ל את ספר דודו \"נועם אלימלך\". לאחר שנפטר נהגה אלמנתו באדמורות, ועלתה לארץ-תקצד - נספתה ברעש בצפת-תקצז. מתורתו ב\"נזר ישראל ועטרת אברהם\". בניו ר מיכל מזל, ר אלימלך.","bk":[["נזר ישראל ועטרת אברהם",""]]},{"i":25214,"n":"ישראל אברהם מנמירוב","b":"רב בנמירוב."},{"i":25215,"n":"ישראל אהרן מלעבעדאווע","k":"העילוי מפרוזין","b":"מחכמי פרוזין, ומבאי ביתו של הגדול ממינסק בכהנו בפרוזין, רב בלעבעדאווע. נפטר צעיר."},{"i":25216,"n":"ישראל אהרן ממזריטש","dt":"תרע - בערך","b":"נכד ר ישראל-חתן ר אהרן הגדול מקרלין. רב במזריטש-ווהלין-תרם, ובנו ר אשר זילברשטין על מקומו אחריו-תרע."},{"i":25217,"n":"ישראל אוזלאנר ממינסק וירושלים","f":"יהושע","dt":"תרכח - ל אד\"א","dp":"ירושלים","b":"מו\"צ במינסק, עלה לירושלים. גבאי ומנהל ב\"ת \"עץ חיים\"-תריט."},{"i":25218,"n":"ישראל אוריה הלוי","f":"אהרן","bt":"תקפא","b":"חיבר פירוש לתורה - בכת\"י, חדושים על הש\"ס - ליקוטי מאמרים' - בכת\"י."},{"i":25219,"n":"ישראל איסר חריף מפאריליציא","b":"תלמיד החוזה מלובלין."},{"i":25220,"n":"ישראל איסר מאפטא","f":"שמחה בונם מוילנא וקר","dt":"תה - טז תשרי","dp":"לבוב","b":"תלמיד בעל הב\"ח. מרביץ תורה, רב באפטא, ר\"מ בקראקא, לבוב. בנו - ר שמחה בונם מלבוב."},{"i":25221,"n":"ישראל איסר מבריסק ופינסק","f":"אברהם אבא מארי","dt":"תקכט - ח כסלו","b":"נכד ר יעקב מוינה. רב בבריסק-תפד, פינסק-תפז. בניו: ר אברהם אשר הלפרין מאליק ונארול(-אשר בנו היה ר יו\"ט בעל ליפמן בעל \"קדושת יום טוב\"), ר אברהם שמואל מטשאווס ומוהילוב. אחיו - ר אליהו מצורטקוב."},{"i":25222,"n":"ישראל איסר מדראגאטשין","dt":"תקל - כה תשרי","b":"רב בסמבור"},{"i":25223,"n":"ישראל איסר מוילנא","f":"נפתלי הרץ","dt":"תקצא - יט סיון","dp":"וילנא","b":"חתן ר טוביהו פייגעש-אחיו של ר אורי פייגעש מוילנא. גביר מראשי קהילת וילנא. אשתו שרה תרמה בתים לישיבת מייליס בוילנא."},{"i":25224,"n":"ישראל איסר מוילנא","dt":"תקסח","dp":"ארץ ישראל","b":"תלמיד הגר\"א, ונשלח לבדוק אחר ר שניאור זלמן מלאדי, ולאחר ששהה אצלו ואף למד אצלו כמה חדשים חזר לוילנא, ולשאלת הגר\"א השיב לו כי הרב דומה למלאך ותורת אמת בפיו, הגר\"א הקפיד עליו ור ישראל נאלץ לעזוב את וילנא. עלה לארץ. (ראה גם ר ישראל מויטבסק)"},{"i":25225,"n":"ישראל איסר מוילנא וצפת","dp":"צפת","b":"מחכמי וילנא, עלה לצפת-שנות ה-תקל בערך."},{"i":25226,"n":"ישראל איסר מויניצא","f":"זאב וולף","k":"בעל שער המשפט","b":"רב בויניצא-תקס?."},{"i":25227,"n":"ישראל איסר מזולקוא","f":"אשר זליג","b":"חתם-שפו על תקנה בזולקוא."},{"i":25228,"n":"ישראל איסר מזולקוא (לובלין?)","f":"מרדכי ר ליפשס הלפרין","dt":"תקם","b":"נכד ר ישראל איסר הפרנס מלובלין. פרנס בזולקוא, נזכר ב\"ברוך מבנים אשר\", חתם-תקב בועד ארבע ארצות בטשליץ (האם זה הוא?). חתניו - ר נפתלי הרץ בן משה, ר פנחס משה, ר יהושע השל באבד בעל ספר יהושע, ר יוסף לנדא מגריידינג."},{"i":25229,"n":"ישראל איסר מלובלין","f":"אברהם הקטן ר איסלרש","k":"ר איסר ר אבלש","dt":"תקם - ג ניסן","dp":"לובלין","b":"נזכר בהקדמת \"קדושת יו\"ט\". בנו - ר מאיר."},{"i":25230,"n":"ישראל איסר מליסא","k":"בעל תרגום איוב לאשכנ","b":"תרגם ספר איוב ללשון אשכנז - פרג תקנא. הסכים על \"חבל להחיות\"."},{"i":25231,"n":"ישראל איסר מפינסק","f":"משה - המהדורא בתרא","dp":"לובלין","b":"נכד המהרש\"א. מגדולי דורו, רב בלומבלא, פינסק, לובלין, ראש דד\"א-ת\"נ. בניו: ר אברהם אבלי (אברהם הקטן ר איסרלש מלובלין), ר מרדכי. חתנו ר אליעזר ליפמן הלפרין, ר אברהם אבא מארי, ר אליעזר הלוי, ר משה מברדיטשוב. (בקורות היהודים בלובלין - יש שם בילבול). ראה גם: ישראל הכהן מלובלין וירושלים."},{"i":25232,"n":"ישראל איסר מפרצוב","f":"ישראל איסר","dt":"תקפח - ח תשרי","dp":"לובלין","b":"רב בפרצוב."},{"i":25233,"n":"ישראל איסר מקלימטוב","f":"עוזר","dt":"תקסג - כד תשרי","b":"רב בקלימטוב,ריטשוואל"},{"i":25234,"n":"ישראל איסר משווקסנא ווילנא","b":"רב בשווקסנא,מו\"צ בווילנה-תר\"מ"},{"i":25235,"n":"ישראל איסר משטרסבורג וירושלים","f":"אליקים גץ","k":"בעל תפלות כמנהג ספרד","b":"רב בשטרסבורג, עלה לירושלים בשנת תס דרך ונציה, עבר לחלב, היה מקובל וכן בקי במשניות, התיישב בצפת ויצא בשליחותה, הגיע לוינה ומסר כתב מנוי לר שמשון ורטהיים, היה גם בפויזן ונהרג בשליחותו. הביא לדפוס בונציה משניה מוגהת ומנוקדת. בניהו פרסם מכתב ממנו ובו מספר שברח מירושלים בגלל המגפה-תסב והגיע לחלב ופגש שם את גדולי העיר ובמיוחד ר שמואל בן דניאל פינטו. חיבר פירוש למשנה."},{"i":25236,"n":"ישראל אלימלך הלוי מבלוזוב","b":"רב בבלוזוב."},{"i":25237,"n":"ישראל אריה יהודה ליב מטבריה","f":"חיים מקרוסנא","b":"חתן ר יעקב שמשון משפיטובקא. עלה לארץ והתישב בטבריה."},{"i":25238,"n":"ישראל אריה ליב","dt":"תקנד - ד תשרי","b":"רב בקאלקו"},{"i":25239,"n":"ישראל אריה מליסעץ","b":"רב בליסעץ."},{"i":25240,"n":"ישראל אשר ממינסק","f":"עוזר","bp":"הורדנא","dt":"תרנז - כה סיון","dp":"מינסק","b":"רב ודרשן ומ\"מ במינסק-תר בערך."},{"i":25241,"n":"ישראל בועז מירושלים","k":"ווארדער גראסייל","b":"גר צדק, נולד כגוי בפנסילבניה-ארה\"ב, הגיע ללונדון ופעל ליסוד מושבות חקלאיות בארץ ישראל, עלה לירושלים והתגייר."},{"i":25242,"n":"ישראל בכור מאדרינופול","f":"חיים","b":"מחכמי אדרינופול, בלגרד, וינה."},{"i":25243,"n":"ישראל בן משה הלוי מזמושץ’","f":"משה","k":"בעל נצח ישראל","bt":"תס","bp":"בוברקא","dt":"תקלב - יז ניסן","dp":"ברודי","b":"ר\"מ בזאמושט, ישב בביהמ\"ד של ר דניאל יפה בברלין, מחכמי ברודי. מקורב לר יואל בעל שם מזאמושט. חיבר גם \"טוב הלבנון\" , \"אבן ישראל\", \"נזר הדמע\", ועוד.","bk":[["נזד הדמע",""],["נצח ישראל",""]]},{"i":25244,"n":"ישראל בן ציון מוישקאוי","b":"אב\"ד וישקאוי. הסכים על תהלות חיים לר חיים פלטרוביץ."},{"i":25245,"n":"ישראל בנימין מירושלים","f":"ברוך","k":"הנכד","b":"דיין בירושלים-תן."},{"i":25246,"n":"ישראל בנימין ממצרים וירושלים","f":"אליקים בנימין","bt":"שכ-שכה","bp":"מצרים","dt":"תה","dp":"ירושלים","b":"אבי משפחת ישראל מרודוס וירושלים. מקובל, תלמיד ר אליעזר מונזאלו (ממנלואנואי), ור יוסף ן טבול-תלמיד האר\"י. חברו של ר שמואל ן סיד סיריליו. רב באלכסנדריה, עלה לירושלים - לפני שפג, רב בירושלים ותיקן כמה תקנות - וביניהם שלא לומר והוא רחום בפסוקי דזמרה של שבת. נזכר ב\"חרבות ירושלים\" כאחד הסובלים בפרעות אבן פארוך-שפה. חתם על כתב שליחות ר שמואל רימון-שץ. בנו ר ברוך בנימין, ונכדו ר ישראל בנימין - גם הוא מחכמי ירושלים."},{"i":25247,"n":"ישראל בנימין מסטופצי","f":"שמואל [שמחה] מסטופצי","b":"אב\"ד סטופצי. עלה לירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":25248,"n":"ישראל בעל שם טוב","f":"אליעזר","k":"הבעש\"ט","bt":"תס או תנח","bp":"אוקופ","dt":"תקכ - ו סיון","b":"גילה את תורת החסידות במזיבוז-ת\"ק. חתן ר אפרים מקיטוב. התישב במז'בוז'.","bk":[["בעל שם טוב","חסידות"],["צוואת הריב\"ש",""],["חכמי ישראל בעל שם טוב",""],["חכמי ישראל בעש\"ט",""],["כתבי קודש",""],["כתר שם טוב",""],["כתר שם טוב השלם",""],["מדרש ריב\"ש טוב",""],["מכתבים מהבעל שם טוב ותלמידיו",""],["מכתבים מהבעש״ט ז״ל ותלמידיו",""],["מסכת אבות",""],["סדר המאיר לארץ",""],["ספר קטן",""],["עקרי אמונה",""],["צרור החיים",""],["צוואת הריב\"ש","חסידות"]],"e":"ת\"נ~-תק\"כ"},{"i":25249,"n":"ישראל בער הלוי","f":"דוד מסטעפין","b":"רב בסטעפין-תק\"צ"},{"i":25250,"n":"ישראל ברוך מירושלים","dt":"תקעד - כא ניסן","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":25251,"n":"ישראל ברוך פויזנר מליאזני","f":"שניאור זלמן או אברהם","dt":"תקנב - ח תשרי","dp":"סוליש","b":"תלמיד הבעשט (?? לבדוק). חתן ר אברהם הגנן מליאזני. מבניו: ר שניאור זלמן מליאדי בעל התניא, ר מרדכי מאוארשא, ר משה מבאייעב וליפעלי."},{"i":25252,"n":"ישראל בר\"י מעיר חדש","b":"דיין בעיר חדש-תקעה."},{"i":25253,"n":"ישראל גרשון","b":"מחכמי צפת, בשנת שע חתם על מכתב לר אהרן ברכיה ממודנא."},{"i":25254,"n":"ישראל דב בר הלוי מזיטומיר","f":"זאב וולף מזיטומיר","dt":"תקנז - ה סיון","b":"חתן ר חיים מקרוסנא. מגיד בזיטומיר על מקום אביו-תלמיד המגיד ממזריטש."},{"i":25255,"n":"ישראל דב בר מסטעפין","f":"דוד מסטעפין","k":"אדמור מסטעפין","dt":"תריב - יב חשון","b":"חתן ר אליעזר אפרתי ראה הישיבה בפינסק. אדמור מסטעפין. הניח מתורתו בכת\"י."},{"i":25256,"n":"ישראל דב הכהן","bt":"תרמ","dt":"תשח","b":"רב הכרמל בחיפה"},{"i":25257,"n":"ישראל דב מדרוהוביטש","b":"תלמיד ר צבי הירש מזידיטשוב. צדיק מפורסם בדרוהוביטש, ר צבי אלימלך מדינוב הביא מתורתו בספרו \"בני ישכר\"."},{"i":25258,"n":"ישראל דב מוילדניק","f":"יוסף מקטעלנע","k":"בעל שארית ישראל","bt":"תקמט","dt":"תרי-מ - כא טבת","b":"נתפרסם בילדותו כ\"עילוי מקאטעלנע\". תלמיד ר מרדכי מטשרנוביל, ר לוי יצחק מברדיטשוב, ור אהרן מזיטומיר. הצניע עצמו עד שנתגלה בידי ר מנחם מנדל מליובאויטש, ואז התפרסם במופתיו. חתן הגביר ר משה חפץ (מגיד). לאחר פטירת ר חיים רפאל מסטראשלא כיהן כאדמור לחסידיו. נפטר ללא ילדים. קברו הפך למקום תפילה לרבים ואף לגויים. מתולדותיו ב\"סיפורי נפלאות\" - באידיש.","bk":[["שארית ישראל","חסידות"],["שארית ישראל (וילעדניק)",""]]},{"i":25259,"n":"ישראל דובער מקאליש וירושלים","f":"יוסף","dt":"תרכט - יא תשרי","dp":"ירושלים","b":"דומ\"צ בקאליש, עלה לירושלים."},{"i":25260,"n":"ישראל דיא אחוס'ס מוילנא","b":"מחכמי \"ישיבת הארבעים\" בוילנא-תקפז."},{"i":25261,"n":"ישראל דניאל סגל מברוד","b":"דיין בברודי-תקף."},{"i":25262,"n":"ישראל הגר מאמשטרדם","f":"אברהם אבינו","k":"בעל מפתח לשון הקדש","b":"גר, מחכמי אמשטרדם. חיבר ספר דקדוק בלשון אשכנז בשם \"מפתח לשון הקדש\" והוא חלק מספר חנוך קטן - אמשטרדם תעג."},{"i":25263,"n":"ישראל הכהן","f":"שבתי כץ מאורלא","b":"גביר תלמיד חכם. חתנו - ר אברהם עבריל וייריך מביאליסטוק."},{"i":25264,"n":"ישראל הכהן מבריסק","f":"יונה","b":"פו\"מ בבריסק. מכתב ממנו לר יונתן איבשיץ בדבר מחלוקת הקמיעות."},{"i":25265,"n":"ישראל הכהן מוילנא","b":"רב בוילנא, חתם-תסט עם ר ברוך כהנא-רפפורט."},{"i":25266,"n":"ישראל הכהן מחברון","dt":"תקי - לפני","b":"מחכמי חברון, בשנת תפז חתם על כתב שליחות ר אברהם גדיליה ור יום טוב קריספו, בשנים תעח-תפה בשליחות חברון באירופה עם חברו ר דוד מלמד."},{"i":25267,"n":"ישראל הכהן מלובלין וירושלים","f":"משה","b":"מחכמי ירושלים, חתן ר משה בן שמעיה בעל \"ויכתוב משה\", היה במצרים בשנת תסב ומוזכר במכתבו של ר נפתלי הכהן משנת תעד. בשנת תסז חתם בירושלים על כתב רבנות ר דוד אופנהיים. ראה גם: ישראל איסר מפינסק."},{"i":25268,"n":"ישראל הלוי מבאקוי","f":"חיים משה מסטעפין","dt":"תרסב - ט אייר","b":"ממשפחת אדמורי סטעפין. תלמיד ר צבי אלימלך מדינוב, ור צבי הירש מרימנוב. חתן ר דוד אריה ליב בן ר צבי הירש מנדבורנא."},{"i":25269,"n":"ישראל הלוי מברזניץ","b":"רב בברזניץ. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":25270,"n":"ישראל הלוי מזלוזיץ","f":"דוד","dt":"תרלג - בערך","b":"נכד \"הלב אריה\" רב בזלוזיץ-תקעו על מקום חותנו - ר יוסף משה בן אלקנה. רב בברודי."},{"i":25271,"n":"ישראל הלוי מחברון","b":"מחכמי חברון, בשליחות בשנת תקעא באיטליה, בשנת תקפז חתם עם חכמי ישיבת \"מגן דוד\", בשנת תקצו היה בין חכמי ירושלים ר יהודה ישראל הלוי ויתכן שהם זהים."},{"i":25272,"n":"ישראל הלוי מטארניגרד","f":"צבי הירש הלוי","b":"רב בטארניגראד"},{"i":25273,"n":"ישראל הלוי מפאריצק","k":"בעל עמודי בית ישראל","bp":"קאווליע","dt":"תקמ","b":"דרשן, מפיץ תורת החסידות בליטא, אב\"ד לאשטשוב, עלה לארץ תקלז, רב בטבריה,צפת, יצא לחו\"ל לפעול לחיזוק הישוב, רב בפאריצק. חתנו - בנו חורגו - ר שמואל מייזלש מלברטוב ופאריצק הו\"ל את ספרו."},{"i":25274,"n":"ישראל הלוי משארוואר","dt":"תקכ - ו כסלו","b":"רב בשארוואר"},{"i":25275,"n":"ישראל הלוי משצריץ","b":"רב בשצריץ."},{"i":25276,"n":"ישראל זוסלין מערפורט","f":"יואל","b":"מחכמי אשכנז-ק', חיבר תוספות להלכות הרי\"ף. חיבר קינה על הגזירות והשמד שהיה בימיו ובהם קינה על 13 רבנים הנזכרים בשמותם."},{"i":25277,"n":"ישראל זוסמן","bt":"תרלד","dt":"תרפז - כג אייר","b":"רב בוואלינגפורד,בורופרק"},{"i":25278,"n":"ישראל זליג מירושלים","b":"מקובל,מחכמי ירושלים-תר\"ס"},{"i":25279,"n":"ישראל זלמן אשכנזי מפמורן","f":"דוד מיריטשוב","dt":"תקלו","b":"נכד החכם צבי. רב בפמורן, רישא - נכדו ר ישראל משולם על מקומו אחריו."},{"i":25280,"n":"ישראל חיים מלודמיר","f":"אברהם המלאך","b":"רב בלודמיר-תקס. נכד המגיד ממזריטש. לאחר שנתייתם גדל עם אחיו ר שלום שכנא אצל ר שלמה מקרלין, חתן ר שלמה האדמור מקרלין, ובזיוו\"ש חתן ר גדליה מליניץ. בניו ר אברהם שלמה - חתן שמואל בן ר ליבר מברדיטשוב, ר דב בער חתן ר צבי בן הבעשט."},{"i":25281,"n":"ישראל חריף מסטנוב","f":"שלמה","k":"בעל תפארת ישראל","bt":"תנו","dt":"תקמא - ז שבט","b":"תלמיד הבעש\"ט - למרות שבתחילה התנגד אליו. חתן ר יחיאל ממיקולייב. בניו ר דוד מסטינוב(=סטנוב) וסמאטרוטש וזוואניץ, ר אלקינה מפלטישאן, ר שלמה מזברוזא."},{"i":25282,"n":"ישראל יהודה ליב מקורסני","b":"עלה לארץ בשיירת תקלז או סמוך לכך."},{"i":25283,"n":"ישראל יהודה מלעטשנוב","f":"אברהם דוב אוירבך","k":"ישראל יהודה מלעטשוב","b":"נכד ר יעקב יוסף בעל \"תולדות יעקב יוסף\". רב בלעטשנוב-תק\"צ."},{"i":25284,"n":"ישראל יונה זאב מסקאלי","b":"רב בסקאלי."},{"i":25285,"n":"ישראל יוסף הלוי מבוצאץ","f":"יהודה","b":"רב בבוצאץ-תרנא."},{"i":25286,"n":"ישראל יוסף הלוי מהורודק","f":"וואלפצי הלוי","b":"רב בהורדק-תרכ\"ה"},{"i":25287,"n":"ישראל יוסף מדויד הורודוקש","f":"דוד מדויד הורודוק","k":"אדמור מדויד הורודוק","dt":"תרנט","b":"תלמיד ר מרדכי מטשרנוביל שהכתירו לאדמור. בנה בימ\"ד גדול וגם מתנגדים בפינסק הגיעו אליו לטיש."},{"i":25288,"n":"ישראל יוסף מסלובודקה","b":"רב בראווארי,סלובודקה-תרמ\"ח"},{"i":25289,"n":"ישראל יעקב הלוי מפלונסק","f":"שרגא","dt":"תרסב","dp":"ירושלים","b":"אב\"ד פלונסק, חתן ר משה יהודה ליב זילברברג מקוטנא, עלה לירושלים."},{"i":25290,"n":"ישראל יעקב הלוי מקושטא","b":"רב בקושטא-שנות ה-תר'."},{"i":25291,"n":"ישראל יעקב מאוסטרהא","f":"משה יהודה","dt":"תקסד - ז אייר","dp":"אוסטרהא","b":"מצאצאי הב\"ח והט\"ז. מחכמי הקלויז ודיין באוסטרהא. הסכים על \"סוד יכין ובועז\"-אוסטרהא תקנד, ועוד. חתם בפנקס הח\"ק, ועל המגילה-תקנב. בנו ר שמשון זאב מאוסטרהא."},{"i":25292,"n":"ישראל יעקב מבילקומין","f":"מנחם מנדל מרימאנוב","k":"ישראל יעקב מבילקאמין","dt":"תקפז - שבט","b":"רב בבילקאמין"},{"i":25293,"n":"ישראל יעקב מפארבאט","b":"רב בפארבאט"},{"i":25294,"n":"ישראל יעקב מקוברין","f":"משה מקוברין","b":"רב בקוברין-תר\"כ"},{"i":25295,"n":"ישראל יצחק מברוק","f":"אברהם ליב-מלאת אבן","b":"רב בברוק-פלך לומזה על מקום אביו."},{"i":25296,"n":"ישראל יצחק מיאלשווא","b":"דומ\"צ ביאלשווא-תר\"ל"},{"i":25297,"n":"ישראל יצחק מסקאהל","b":"רב בסקול-תרמו."},{"i":25298,"n":"ישראל יצחק מפובונז'ק","dt":"תרנב","b":"תלמיד ר מנחם מנדל מקוצק, בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר, ור אריה ליב מגור. רב שכונת פובונזק בוורשה-תרע."},{"i":25299,"n":"ישראל יצחק מרדושיץ","f":"ישכר דוב מרדושיץ","dt":"תריח - ב כסלו","b":"גדול בנגלה ונסתר,אדמו\"ר בראדושיץ-תר\"ג"},{"i":25300,"n":"ישראל כץ מזולקוא","f":"יהודה הקדוש","b":"חתם על תקנת זולקוא."},{"i":25301,"n":"ישראל לובלינר מירושלים","b":"רב בירושלים, היה במצרים-תמח. נזכר ב\"לחישת שרף\" בענין נחמיה חיון."},{"i":25302,"n":"ישראל ליב מברמנובקה","b":"רב בברמנובקה-תר\"מ"},{"i":25303,"n":"ישראל מאדועדיקוב","b":"פרסם מאמרים ב\"יגדיל תורה\" - בוברויסק תרפח (תחת שלטון הקומוניסטים ברוסיה)."},{"i":25304,"n":"ישראל מאוביש","f":"נפתלי הרץ מלבוב","b":"חתן ר ברוך רפפורט מוילנא ופיורדא. רב בהורדנא."},{"i":25305,"n":"ישראל מאוסטיטשקי","b":"רב באוסטיטשקי."},{"i":25306,"n":"ישראל מאוסטרהא","f":"יעקב","dt":"תקנז - יד ניסן","dp":"אוסטרהא","b":"נכד ר יוזפא-אבי אביו אסטרר פרנס מדינת ואהלין. רב דחייטים-תקכד באוסטרהא, ופרנס באוסטראה. מבניו: ר אשר, ר אריה ליב, ר דוד יוזפא. חתנו ר אפרים."},{"i":25307,"n":"ישראל מאוסטרהא","f":"יוסף","b":"מחכמי אוסטרהא. הסכים (חתם ראשון) על \"עץ חיים\"-תקמב. ואולי הוא ר ישראל נחמן דראהביטשר בעל \"חמדת ישראל\"."},{"i":25308,"n":"ישראל מאוסטרהא","f":"דוד","dt":"יט אדר","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":25309,"n":"ישראל מאזמיר וירושלים","b":"מחכמי ישיבת ר אברהם מיוחס בירושלים-תקיח."},{"i":25310,"n":"ישראל מאיווניץ","b":"חברו של ר חיים מוולוזין ומגדולי ליטא, הצטרף לעדת החסידים והתקרב לר מרדכי מלכוביץ. בהגיעו לגיל 70 ערך לעצמו סעדות בר מצוה."},{"i":25311,"n":"ישראל מאיר הכהן מראדין","f":"אריה זאב","k":"בעל החפץ חיים","r":"ראש ישיבת אמשינוב","bt":"תקצח","bp":"זאטל","dt":"תרצג - כד אלול","dp":"ראדין","b":"מגדולי הפוסקים בדורות האחרונים. למד בוילנא, לימד בואסילישוק. עבר לראדין אחר נישואיו, חיבר \"חפץ חיים\" - על לשון הרע ועבר כמגיד לעורר בענין לשון הרע. ראש ישיבה בראדין. חתנו ר צבי לוינזון עזר לו בישיבה. השתתף באסיפות רבנים חשובות, ממיסדי אגו\"י והשתתף בכנסיה הגדולה בוינה-תרפג ונבחר לנשיא העולמי של מועצת גדולי התורה.","bk":[["משנה ברורה","מפרשי שו\"ע"],["שפת תמים – שקר אונאה וכו'",""],["תורת הבית",""],["משנה ברורה (החפץ חיים)",""],["אהבת חסד",""],["אהבת ישראל",""],["בית ישראל – ענינים נחוצים",""],["גדר עולם – צניעות ונדה",""],["דבר בעתו – מאכלות אסורות",""],["זכור למרים – לשון הרע",""],["חובת השמירה – על פיו",""],["חומת הדת – חיזוק לתורה ומצו'",""],["חפץ חיים - הל' לשון הרע",""],["טהרת ישראל – שכר הטבילה",""],["כבוד שמים – לשון הרע",""],["ליקוטי הלכות - קדשים",""],["ליקוטי מאמרים ומכתבים",""],["מחנה ישראל – לאנשי הצבא",""],["מכתבי החלק ח'",""],["ספר המצות הקצר",""],["צפית לישועה",""],["שם עולם – שבת חסד ותורה",""],["שמירת הלשון",""],["תורה אור – מוסר קדשים",""],["תורת כהנים – עם פירוש",""],["חפץ חיים",""],["דבר בעתו",""],["זכור למרים",""],["חובת השמירה",""],["חומת דת",""],["כבוד שמים",""],["ליקוטי הלכות",""],["מחנה ישראל",""],["נדחי ישראל",""],["ספר המצוות הקצר",""],["שם אבותי",""],["שם עולם",""],["שפת תמים",""],["תורה אור",""],["משנה ברורה [א. בלום]","שו\"ע אורח חיים"],["אגרות ומאמרים [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["אהבת חסד [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["אהבת ישראל [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["גדר עולם [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["דבר בעתו [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["זכור למרים [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["חובת השמירה [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["חומת הדת [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["חפץ חיים [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["טהרת ישראל [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["כבוד שמים [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["ליקוטי אמרים [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["מחנה ישראל [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["נדחי ישראל [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["ספר המצוות הקצר [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["צפית לישועה [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["קונטרס מדות ומשקלות [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["קונטרס נפוצות ישראל [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["שם עולם [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["שמירת הלשון [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["שפת תמים [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["תורה אור [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"],["תורת הבית [ספרי החפץ חיים]","מחשבה ומוסר - אחרונים"]],"e":"תקצ\"ט-תרצ\"ג","rb":"ראדין, בלארוס"},{"i":25312,"n":"ישראל מאיר מצורטקוב","f":"ישכר בר","b":"רב בצורטקוב-תר."},{"i":25313,"n":"ישראל מאמשטרדם","b":"מרבני אמסטרדם-תק\"י"},{"i":25314,"n":"ישראל מארץ ישראל","f":"יהודה","b":"עלה לארץ, חתם-תקמט על מכתב."},{"i":25315,"n":"ישראל מבאהפאלי","f":"אברהם מקוריסטשוב","k":"בעל עטרת ישראל","dt":"תרז - ב אייר","b":"חתן נכדת ר יחיאל מיכל המגיד מזלוטשוב. רב בבאהפאלי."},{"i":25316,"n":"ישראל מבאניהאד","f":"יהודה אריה","dt":"תקם","b":"רב בבוניהאד(=בניהאד) על מקום ר יצחק זעקל שפיץ, ור אברהם יהודה ליב פריישטט על מקומו אחריו."},{"i":25317,"n":"ישראל מבארשא","b":"רב בבארשא-תקפ\"ט"},{"i":25318,"n":"ישראל מבומברג","b":"מגדולי חכמי אשכנז,רב בבמברג-שנת י'"},{"i":25319,"n":"ישראל מברוד","f":"דוד","b":"מחכמי ברודי עלה לצפת בשנת תץ, בשנת תצה בשליחות הקהלה."},{"i":25320,"n":"ישראל מברונא","f":"חיים","k":"בעל שו\"ת מהר\"י ברונא,מהרי\"ב","bt":"קס","dt":"רלו-רמ","b":"תלמיד ר יעקב וייל, ר ישראל איסרלן. מגדולי חכמי אשכנז, פוסק, גדול הדור,רב בברין(=ברונא), רגנשבורג-רלד, פרג-רלו?. נאסר כמה פעמים בגלל עלילה. מתלמידיו - ר דוד ורנק - הזקן.","bk":[["מהר\"י ברונא","שו\"ת - ראשונים"]]},{"i":25321,"n":"ישראל מבריסק ואליק","b":"רב בריסק-שנות ה-ת', אב\"ד אליק."},{"i":25322,"n":"ישראל מדובראוונא","b":"תלמיד בעל התניא והמנגן שלו. חסיד ר אהרן מסטראשלא. הניח כת\"י בחסידות. בנו ר שלמה גם הוא מחשובי החסידים."},{"i":25323,"n":"ישראל מדרוהוביטש","f":"נחמן בן יוסף","k":"בעל שארית ישראל","dp":"ארץ ישראל","b":"מתלמידי הבעש\"ט, התישב בליוורנו והיה מקורב לחיד\"א, עלה לארץ. חיבר גם \"פקודת המלך."},{"i":25324,"n":"ישראל מהאנוי","b":"רב בהאנוי-תק\"י"},{"i":25325,"n":"ישראל מהורודנקה","f":"יעקב מלשקוביץ","b":"רב בהורודנקה-תריח."},{"i":25326,"n":"ישראל מהנאו","f":"יעקב","b":"מחכמי הנאו. חתם על תקנות אסיפת הרבנים בפפד\"מ-שסג."},{"i":25327,"n":"ישראל מהרימלוב","f":"בנימין","k":"בעל זרע ישראל","b":"אב\"ד הרימלוב-תס, בלזיץ."},{"i":25328,"n":"ישראל מהרישוב","b":"רב בהרישוב,יאסי-תר\"נ"},{"i":25329,"n":"ישראל מואר-פאלטא","b":"רב קהילת סטטוס-קוו בואר-פאלטא-תקמב. חיבר את תקנות הקהלה והח\"ק לפני מנהגי פרג."},{"i":25330,"n":"ישראל מוונגרוב (וונגרור)","b":"תלמיד החוזה מלובלין, ר מנחם מנדל מקוצק."},{"i":25331,"n":"ישראל מויטבסק","b":"תלמיד בעל התניא. מסופר כי היה תלמיד הגר\"א שנשלח לבדוק את מעשי החסידים והתקרב אליהם. דיין בויטבסק. ותשובה מבעל התניא אליו. (ראה גם ר ישראל איסר מוילנא)"},{"i":25332,"n":"ישראל מויטבסק ולובאויטש","b":"רב בלובאוויץ-תק\"מ"},{"i":25333,"n":"ישראל מוילנא","f":"מרדכי","dt":"תקסט - פסח","dp":"וילנא","b":"דיין בוילנא. הסכים -תקנה על \"תולדות אדם\", נזכר כמה פעמים בפנקס הקהל."},{"i":25334,"n":"ישראל מוינה","f":"חיים","b":"גביר בקהלת הספרדים בוינה-תקס בערך. סייע לר יהודה ן סיד בהדפסת ספרו \"נר מצוה\". אחיו - הגביר עזריאל מוינה"},{"i":25335,"n":"ישראל מורמייזא","f":"שמואל","b":"מחכמי וורמייזא וחתם מטעמם על תקנה בפפד\"מ-שג בענין המחלוקת עם קהל שוואבן."},{"i":25336,"n":"ישראל מורמייזא","b":"רב בוורמייזא. השתתף באסיפת הרבנים בוורמייזא-שב כנציג עירו."},{"i":25337,"n":"ישראל מזארעצע","f":"אליעזר מוילנא","b":"רב בזארעצע."},{"i":25338,"n":"ישראל מזולקוא","f":"שמואל","b":"מחכמי זולקוא, חתם-תמ על תקנה בזולקוא."},{"i":25339,"n":"ישראל מזלוזיץ","b":"רב בזלוזיץ-תריז."},{"i":25340,"n":"ישראל מזלישטשיק","f":"צבי הירש","b":"רב בזלישטשיק."},{"i":25341,"n":"ישראל מזקליקוב","dt":"תקע - כה אב","b":"רב בזקליקוב"},{"i":25342,"n":"ישראל מחאזדיטש","b":"רב בחאזדיטש-תק\"פ"},{"i":25343,"n":"ישראל מחודרוב","f":"יוסף יאסקה","b":"רב בחדרוב ואגפיה-תק\"נ"},{"i":25344,"n":"ישראל מטויסט","f":"אפרים","b":"אב\"ד טויסט."},{"i":25345,"n":"ישראל מטיקטין","dt":"תקמז - ז תמוז","b":"רב בטיקטין-תצ\"ז,וישגראד"},{"i":25346,"n":"ישראל מטרנופול","b":"תלמיד הט\"ז,מגדולי חכמי דורו,מראשי ועד דד\"א,רב בלאדמיר-תל\"ג,לויצק-תמ\"ג"},{"i":25347,"n":"ישראל מטשאהן","f":"יוסף מימפולא","dt":"תרב","b":"נכד המגיד מזלוטשוב. חתן ר אהרן מקיפין-תלמיד ר פנחס מקוריץ. רב בטשאהן(=טשען)-תקע."},{"i":25348,"n":"ישראל מיאנוב","b":"רב ביאנוב, בלחוב-תריב."},{"i":25349,"n":"ישראל מיאריוויטש","f":"צבי בן הבעשט","k":"רבי ישראל השותק","dp":"יאריוויטש","b":"חברו של ר מרדכי מטשרנוביל והוריש לו את סידור הבעשט."},{"i":25350,"n":"ישראל מיכל ממינסק","f":"חיים ישורון","dt":"תריא - טז אב","dp":"מינסק","b":"רב במינסק."},{"i":25351,"n":"ישראל מירושלים","f":"ברוך בנימין","dt":"תה","dp":"ירושלים","b":"מחכמי ירושלים, מוזכר ב\"חרבות ירושלים\" כאחד הסובלים בפרעות אבן פארוך בשנת שפה. היה סגי נהור, חתם על התקנה נגד פירוד הקהלה בשנת שפג, בשנת שץ חתם על כתב שליחות ר אברהם ביטון ור שמואל רימון. (בספר \"דברי ישראל בתוגרמא\" מוזכר ר ישראל בנימין בן אליקים ויתכן שזהו אותו אדם)."},{"i":25352,"n":"ישראל מלאך מחסלביץ","b":"רב בחאסלוביטש-תר\"מ וראש ישיבה שם."},{"i":25353,"n":"ישראל מלאסק - א","b":"רבה הראשון של לאסק."},{"i":25354,"n":"ישראל מלאסק - ב","f":"שמואל","dt":"תקע - יא אב","b":"מגיד בלאסק"},{"i":25355,"n":"ישראל מלבוב","f":"ר\"ד","b":"אחד משבעה טובי העיר בלבוב, חתם-תצז על פסק דין."},{"i":25356,"n":"ישראל מלובלין","f":"שלום שכנא מלובלין","dp":"לובלין","b":"ר\"מ בלובלין בזמן המהרש\"ל-שנת שכ.. (ולדעת \"קריה נאמנה\" ראב\"ד בלובלין על מקום אביו). התכתב עם גיסו הרמ\"א. חיבר הגהות למרדכי ונזכר ב\"ברכת המים\", ו\"ברכת הזבח\". חתנו - ר הירש שור מבריסק. (בשם הגדולים מופיע שנת פטירתו שיז)."},{"i":25357,"n":"ישראל מלובלין","f":"אליהו","dt":"תכט - יא כסלו","dp":"לובלין","b":"נגיד מחכמי לובלין."},{"i":25358,"n":"ישראל מלובלין (לובלינר)","f":"משה מלובלין","k":"בעל פירוש על תהלים","b":"מחכמי לובלין. חיבר פירוש לתהלים ומשלי על דרך הקבלה-שנג. חיבר שיר בקשה \"יתן שפתי רינה...\"."},{"i":25359,"n":"ישראל מלודווינובה","f":"אברהם אבלי מוארז'אן","b":"אב\"ד לודווינובה."},{"i":25360,"n":"ישראל מלויצק ודובנא","b":"רב בלוצק,דובנא"},{"i":25361,"n":"ישראל מליטשיניץ","f":"אליקים גץ","k":"אדמור מליטשיניץ","dt":"כח שבט","b":"נכד ר יוסף מיאמפלא (שושלת זלוטשוב), חתן האוהב ישראל מאפטא. רב ואדמור בלוטשיניץ-תר-פולין, חזר לרוסיה. בנו ר אברהם יהושע השל. חתנו ר נחום."},{"i":25362,"n":"ישראל ממוהילוב","f":"יהודה ליב","b":"רב במוהילוב, נוברדוק על מקום ר יעקב צבי הירש, ור משה מאורלא על מקומו אחריו."},{"i":25363,"n":"ישראל ממינסק","f":"יעקב","dt":"תקיא - יא אב","dp":"מינסק","b":"רב במינסק."},{"i":25364,"n":"ישראל ממראקש","f":"יאיר","b":"מחכמי מראקש-תרפה, אולי הוא אביו של ר ישועה."},{"i":25365,"n":"ישראל מנדבורנה","b":"רב בנדבורנה."},{"i":25366,"n":"ישראל מנחם מנדל מטרמבובלה","f":"חיים מברודי","k":"בעל בגדי כבוד","b":"חתן ר יוסף משה שמחה רפפורט מלוביטש. רב בטרמבובלה-תקס. חיבר \"בגדי כבוד\"."},{"i":25367,"n":"ישראל מסאוורן","b":"אחיינו של ר ישראל המגיד מקוזניץ. חתן ר משה צבי גיטרמן מסאווראן. תלמיד ר ברוך ממזבוז. בנו ר לוי יצחק, חתניו: ר משלם זוסיא מזינקוב-אפטא, ר יוסף אלתר האגר מרדוביץ-קוסוב, ר יהודה אריה מבאהפאל."},{"i":25368,"n":"ישראל מסאטנוב","b":"רב בסאטנוב-תכ\"ב"},{"i":25369,"n":"ישראל מסווירז","b":"רב בסווירז, חתנו של ר זאב הכהן בראווער."},{"i":25370,"n":"ישראל מסווריז","b":"תלמיד ר אורי השרף מסטרליסק."},{"i":25371,"n":"ישראל מסופיה","f":"יעקב","b":"רב בסופיה-שע, בזמן ר אסטרוק ן שאנג'י."},{"i":25372,"n":"ישראל מסוקולוב","b":"רב בסוקולוב-תריט."},{"i":25373,"n":"ישראל מסנוק","b":"רב בסנוק-תקץ."},{"i":25374,"n":"ישראל מסקאהל","b":"רב בסקול-תרכד."},{"i":25375,"n":"ישראל מפיליפופולי","f":"ציון","b":"ראש הקהלה בפיליפופולי-תסג עם ר שמואל לפפא."},{"i":25376,"n":"ישראל מפינסק וורצבורג","dt":"יב אב","b":"רב באונגאריש-ברוד,פינסק,רב מדינה בוורצבורג"},{"i":25377,"n":"ישראל מפיעסק","f":"יעקב","b":"אב\"ד פיעסק. בנו - ר מנחם מנדל פיעסקין, ונכדו - ר יעקב דוד פיעסקין בעל \"תומת ישרים\"."},{"i":25378,"n":"ישראל מפירושא","b":"מחכמי ירושלים, אמר שיעור ברמב\"ם על מקום ר\"י אלבוטיני, בשנת רפג כתב מכתבים אל ידידו ר אברהם בפירושא, יש המזהים אותו עם ר ישראל בן יחיאל אשכנזי. בניו - ברוך, שלמה, יצחק."},{"i":25379,"n":"ישראל מפלאצק וצפת","f":"פרץ","dt":"תקמ-ד - ד שבט","dp":"פאסטוב (=חוואסטוב)","b":"התקרב לחסידות ע\"י ר אהרן הגדול מקרלין, והגיע אל המגיד ממזריטש. עלה לצפת בשיירת ר מנחם מנדל מויטבסק בשנת תקלז, בתקלח בשליחות בקושטא ומשם שלח איגרת לויטבסק, בשליחות באירופה ונפטר בשליחותו ונטמן ליד חבירו ר אברהם המלאך בפאסטוב. אגרותיו פורסמו ב\"אגרת הקודש\" חמד תרפז."},{"i":25380,"n":"ישראל מפלטישן וצפת","b":"תלמיד ר אברהם דב מאווריטש. מחכמי צפת מעדת החסידים, לאחר הרעש בשנת תקצז בשליחות הצלה, ובדרכו הדפיס את הספר \"בת עין\" לרבו ר אברהם מאבריטש. בשנת תקצז ישב בטבריה."},{"i":25381,"n":"ישראל מפפד\"מ","f":"גימפל","k":"בעל מנהגים דקהלתנו","b":"מחכמי פפד\"מ. חיבר עם אחיו קופל - ספר על מנהגי קהלת פפד\"מ - פפד\"מ תקסח."},{"i":25382,"n":"ישראל מקאליש","f":"יצחק מקאליש","dt":"כה אדר","b":"גדול בנגלה ונסתר"},{"i":25383,"n":"ישראל מקולומיא","f":"משה חי' אפ' מפרוסקרב","k":"אדמור מקולומיאה סאהל","dt":"תרעא - כא שבט","dp":"קולומייא","b":"רב ואדמור בקולומייא."},{"i":25384,"n":"ישראל מקולומיי","dt":"תקכט - כז כסלו","b":"רב בקולומיי"},{"i":25385,"n":"ישראל מקוסוב","b":"אב\"ד קוסוב."},{"i":25386,"n":"ישראל מקמינקא","f":"דוד מרבינו","k":"אדמור מקמינקא","dt":"תקע","b":"תלמיד הבעשט - אחד מ\"האחים הקדושים מקמינקא\"."},{"i":25387,"n":"ישראל מקרימזיר-אוסטריה","k":"בעל הגהות אשרי","b":"מגדולי חכמי התורה באוסטריה-קנ. לדעת גרץ הוא שהיה ראש הרבנים באשכנז בפקודת הקיסר רופרכט, והיה מחלוקת כנגדו על המינוי, עד שהקיסר הודח והמינוי בוטל. נינו - ר ישראל איסרלן בעל תרומות הדשן."},{"i":25388,"n":"ישראל מקרמניץ","f":"מרדכי מקרמניץ","b":"רב בקרמניץ-תר\"כ"},{"i":25389,"n":"ישראל מקרסילוב","f":"נחום סקאליטשר","k":"אדמור מקרסילוב","dt":"תרנו - יח כסלו","b":"חתן ר ברוך מסדילקוב בן אריה ליב מקורסיטשוב. רב ואדמור בקרסילוב(=קרוסילוב)-תרמ. בנו - ר ברוך יוסף ז\"ק האדמור מקוברין."},{"i":25390,"n":"ישראל מרדכי מוארשא","k":"בעל קול ברמה","b":"מו\"צ בוורשה-תר\"ל"},{"i":25391,"n":"ישראל מרדכי מזולקוא","f":"ברוך","b":"ראב\"ד בזולקוא, חתם-תקכא בפנקס הקהלה, חתם-תקיא על החרם לטובת ר יונתן איבשיץ, הסכים על האלשיך-תקכה, \"אותות למועדים\"-תקיב."},{"i":25392,"n":"ישראל מרישא","b":"דיין ברישא-תרמו בבית דינו של רי\"ה ולרשטין."},{"i":25393,"n":"ישראל משה","f":"אריה ליב","k":"בעל רשמי שאלה","b":"נכד(-אבי אמו) ר עזריאל מליסא."},{"i":25394,"n":"ישראל משה אליהו הלוי מקראקא","b":"דיין בקרקא-תכ\"ח"},{"i":25395,"n":"ישראל משה הכהן מוילנא","f":"בן ציון בן משה","dt":"תרלד - יד טבת","b":"תלמיד ר מאיר קארעליצער, ו\"ישיבת הארבעים\" (פערציגטלעך)-תקפז. מגדולי חכמי וילנא-תקצ. בניו - ר בצלאל הכהן מוילנא, ר שלמה בעל \"בנין שלמה\"."},{"i":25396,"n":"ישראל משה מבוצאץ","b":"חסיד בבוצאץ-תקמו."},{"i":25397,"n":"ישראל משה מקרניק וזאבלודוב","k":"בעל רשמי שאלה","b":"רב בקארניק-תמ\"ו, זאבלודוב."},{"i":25398,"n":"ישראל משה משטמפן","f":"שמואל זנויל","dt":"תצז - יא תשרי","dp":"שטמפן","b":"פרנס בשטמפן."},{"i":25399,"n":"ישראל משה מתירייא","b":"מלמד תורה בתירייא - בדור שלאחר הגירוש. התכתב עם הרא\"ם."},{"i":25400,"n":"ישראל משוראני","b":"רב בשוראני-תקנ\"ט"},{"i":25401,"n":"ישראל משלם הלוי מקלוש","b":"נכד ר וולף מרדכי מקלוש. רב בקלוש על מקום זקנו."},{"i":25402,"n":"ישראל משלם זלמן מחנטשין","dt":"תקסו - י טבת","b":"רב בחנטשין"},{"i":25403,"n":"ישראל משלם זלמן מרישא","f":"שמואל מפודהייץ","b":"רב ברישא. זקנו של הדברי חיים."},{"i":25404,"n":"ישראל משקלוב","f":"שמואל","k":"בעל תקלין חדתין","r":"מחכמי המקובלים בישיבת בית א - ל בירושלם ואח\"כ בישיבת שושנים לדוד","bt":"תקל","bp":"שקלוב","dt":"תקצט - ט סיון","dp":"טבריה","b":"מתלמידי הגר\"א, עלה בראש שיירת העולים השניה של תלמידי הגרא בשנת תקע. יצא בשליחות הקהלה ובשנת תקעג חזר לצפת ועמד בראש העדה, אחרי הרעש בתקצז עברו לירושלים והיה מנהיג הקהלה גם שם. חיבר גם \"פאת השלחן\", ועוד.","bk":[["תקלין חדתין","מפרשי ירושלמי"],["פאת השולחן",""],["אגרת מרבני ארץ ישראל לבני משה ועשרת השבטים",""],["פאת השלחן",""],["תקלין חדתין , אמת מארץ תצמח, פאת השלחן",""]],"e":"תק\"ל-תקצ\"ט"},{"i":25405,"n":"ישראל ן, יוסף מספרד ואלגיר","bt":"ק - בערך","dt":"קע - בערך","b":"דיין בטולדו. לאחר פרעות-קן עבר לאלגיר, רב במיליאנה-אלגיר. התכתב עם הרשב\"ץ ונזכר בספרו."},{"i":25406,"n":"ישראל ן, ישראל מטריפולי","b":"רב וסופר בטריפולי. נזכר ע\"י ר מנחם די לונזנו ב\"אור תורה\", וב\"תעלומות לב\" לר\"א חזן. עליו ב\"אוצר גנזים\" ירושלים תשך."},{"i":25407,"n":"ישראל נחום מטשרנוביל וירושלים","f":"צבי","dt":"תרכט - ט סיון","dp":"ירושלים","b":"מחכמי ירושלים."},{"i":25408,"n":"ישראל נחמן מדרוהוביטש וצפת","f":"ראה: דרוהוביטשר, ישר"},{"i":25409,"n":"ישראל נכד ר נחמן מברסלב","f":"יצחק איזיק מדוברוונא","b":"נכד ר נחמן מברסלב. חתן ר אהרן מטשרנוביל. נפטר צעיר ובנו ר גדליה לימים האדמור ממאלין - גדל אצל זקנו האדמור מטשרנוביל."},{"i":25410,"n":"ישראל נפתלי הרץ מדוברומיל","b":"רב בדוברומיל-תריד."},{"i":25411,"n":"ישראל נתן מליגום","b":"רב בליגום-תרסו על מקום ר מרדכי יצחק רבינוביץ."},{"i":25412,"n":"ישראל נתן מקושטא וירושלים","b":"גביר בקושטא-שנות ה-תק', עלה לירושלים."},{"i":25413,"n":"ישראל נתן משלוניקי","dt":"שצד - כו אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":25414,"n":"ישראל צבי מברנוב","f":"יוסף","b":"דיין בברנוב-תרח."},{"i":25415,"n":"ישראל קלמן מדרמשטט","k":"ישראל קלמן מגינזבורג","bt":"תקיג","dt":"תקצג","b":"רב בדרמשטט"},{"i":25416,"n":"ישראל ראובן מקיעלץ","b":"דיין בקיעלץ"},{"i":25417,"n":"ישראל ראקובר חריף","b":"תלמיד ר חיים מוולוזין (אחד מה-4 שזרק בהם מרה). היו לו 36 נשים."},{"i":25418,"n":"ישראל שלום מאוסטרהא ולברטוב","f":"יעקב","b":"נכד ר חנוך הניך רב דחייטים באוסטרהא. דיין באוסטרהא, עבר לק\"ק ליבר טוב. הסכים על חומש \"מרגליות טובה\"-תקסח, ועוד. מחותן עם רבי דב בער מליניץ בעל \"שבחי הבעשט\"."},{"i":25419,"n":"ישראל שלמה מראסיין","f":"נחום","k":"ר שלמה מתמיד","dt":"תרנג - כו שבט","dp":"פגמון-צאיוסק-ליד קובנא","b":"תלמיד ר ברכיה מאוזדא. רב בראסיין. בשליחות ישיבת לומז'ה. הניח חבור בכת\"י."},{"i":25420,"n":"ישראל שמואל הרופא מספרד","f":"שלמה רופא","k":"בעל ישמח ישראל","b":"רב ורופא בספרד (או ממגורשי ספרד)-שפד. חיבר ישמח ישראל\" - נדפס ע\"י ר משה יקותיאל קופמן. חיבר \"מגלה עמוקות\", \"כרם שלמה\", ועוד."},{"i":25421,"n":"ישראל שמואל מקאמען וצפת","f":"יוסף אליהו","dt":"תקפה - יז תשרי","dp":"צפת","b":"אב\"ד קאמען. אחיהם של ר זאב וולף מקאמען אביו של ר יוסף אליהו עליאשברג, הגביר ר יצחק איזיק איזועניצר."},{"i":25422,"n":"ישראל ש\"ץ מאוסטרהא","f":"משה מאוסטרהא","dt":"תקמה - יט אלול","dp":"אוסטרהא","b":"נכד ר ישראל ש\"ץ-נפטר תפ. מחכמי אוסטרהא."},{"i":25423,"n":"ישראל, אברהם ממרוקו","f":"שלם","b":"מחכמי ארבאט-מרוקו."},{"i":25424,"n":"ישראל, אברהם ממרוקו","b":"מו\"ץ באלקצר-מרוקו. חתם על פסק-תקסו והסכימו עמו ר מנחם נהון, ר משה ן צור, ר אברהם טולידנו, ועוד."},{"i":25425,"n":"ישראל, אליעזר יהודה מרודוס","b":"מגדולי רבני רודוס"},{"i":25426,"n":"ישראל, ברוך בנימין מירושלים","f":"ישראל בנימין ממצרים","dp":"מצרים","b":"פוסק, דיין בירושלים-תיז. בנו - ר ישראל בנימין."},{"i":25427,"n":"ישראל, וידאל מטיטואן","b":"מו\"ץ בטיטואן, ועמו כיהנו ר מנחם נהון, ר משה הלוי. חתם על הסכמה-תקמח, ועל פס\"ד-תקצב עם ר אברהם ישראל, ועל מכתב-תקצד עם ר יצחק ן ואליד."},{"i":25428,"n":"ישראל, חזקיה משה מרודוס","f":"רפאל יצחק מרודוס","b":"בניו מתתיהו אברהם, ר חיים שהיה שו\"ב ברודוס, מיכאל יעקב, שמעון ויחזקאל."},{"i":25429,"n":"ישראל, חיים אברהם מאלכסנדריה","f":"משה","k":"בעל בית אברהם","bt":"תסח","bp":"ירושלים","dt":"תקמה - ז סיון","dp":"אנקונה","b":"אביו בעל \"משאת משה\" היה רב ברודוס בשנת תעח, ור חיים עבר אתו לרודוס ובגיל 17 הרביץ תורה שם. בשנת תצג דרש ידידו ר ידידיה טריקא לכבוד חתונתו, וגם פרסם בספרו \"בן ידיד\" חדושי תורה ממנו. בשנת תקב הדפיס ספרו של אביו. רב בקנדיא-כרתים-תקג. בשליחות ירושלים-תקיא באירופה, ובהיותו בהמבורג התערב, למרות בקשות הקהלה הספרדית, במחלוקת ר יונתן אייבשיץ ור יעקב עמדין לטובת ר יונתן, ואף הבטיח שישתדל לטובתו אצל חכמי ארץ ישראל. היה רב באלכסנדריה בשנת תקיח ועד שנת תקכו. עבר לאיטליה, ושימש ברבנות בליוורנו-תקכט ואנקונה, שם קיבל את החיד\"א בשנת תקלה. חיבר תפלה מיוחדת לגשמים ור מתתיהו טרני מספר בספרו \"שפת אמת\" על קדוש השם בעיני הגויים לאחר הצלחת תפלתו שכינוהו \"ראבינו דיל אקווה\" (הרבי של המים). חיבר \"אמרות טהורות\" ליוורנו תקמו, \"בית אברהם\" ליוורנו תקמו ועוד. בניו - ר משה ישראל שמילא מקומו כרב אלכסנדריה, ור רפאל יהודה ישראל שהדפיס ספרי אביו.","bk":[["אמרות טהורות [על טור]",""],["בית אברהם [על טור]",""]]},{"i":25430,"n":"ישראל, חיים יהודה מרודוס","f":"משה ישראל","k":"בעל קול יהודה","bt":"תקכח","dt":"תקפט - ח אדר","b":"רב ברודוס-תקע\"ה"},{"i":25431,"n":"ישראל, ידידיה שלמה ממצרים","f":"אליהו","k":"בעל בן ישי","dt":"תקצא - ג סיון","dp":"נא אמון","b":"מחכמי ארץ ישראל, נתייתם בילדותו וגדל אצל דודו ר משה ישראל ואצל ר יונתן גלנטי - בעזרת קהילת אלכסנדריה, רבה של אלכסנדריה-תקעב. בשליחות קהילת חברון ובהיותו באיטליה הדפיס ספר אביו \"שני אליהו\" ו\"ארעא דישראל\", וספר סבו \"אפי משה\", תשובותיו מפוזרות בספרי אביו, חיבר שות ו\"קונטרס מזכרת הגטין\" ו\"דרשות בן ישי\" שלא נדפסו. במכון כתב יד מצוי משנה תורה לרמבם עם הערות ר ידידיה בשוליים. (יש רושמים תאריך פטירתו - תקצו - ב סיון)"},{"i":25432,"n":"ישראל, יהודה מרבאט-מרוקו","b":"מחכמי ארבאט(=רבאט)-מרוקו-שנות ה-ת'."},{"i":25433,"n":"ישראל, יוסף מראבאט","f":"יעקב","bt":"תקפב","dt":"תריד - טו תשרי","b":"מחכמי ראבאט-מרוקו."},{"i":25434,"n":"ישראל, יעקב מראבאט","b":"מחכמי אראבאט(=ראבאט)."},{"i":25435,"n":"ישראל, יצחק מרודוס","f":"משה","b":"מחכמי רודוס, קושטא-שנות ה-תק'."},{"i":25436,"n":"ישראל, מיכאל חיים משה","f":"דוד בן משה בן אליהו","dt":"תרמא - א אב","b":"נכד ר משה-(שהיה ראב\"ד ברודוס). ראב\"ד ברודוס-תריג על מקום גיסו ר מיכאל יעקב בעל \"בן ימין\", עלה לירושלים."},{"i":25437,"n":"ישראל, מיכאל יעקב מרודוס","f":"חיים יהודה או אליהו","k":"בעל שנות ימין","bt":"תקמו-תקן","bp":"רודוס","dt":"תרטז - ז אייר","dp":"ירושלים","b":"תלמיד ר אברהם הלוי מרודוס, רב ברודוס-תקפא על מקום אביו שעלה לירושלים. ביום ב כסליו נהג לעשות יום שמחה על נס שאירע לו - נסע לטפל בירושת אחי זקנו - ר ידידיה שלמה ישראל שנפטר ללא בנים-[תקצב] במצרים ושם ניצל מטביעה, וסירב להצעת רבנות שם. עלה לירושלים-תריג, ומינה את גיסיו ר מיכאל חיים משה ישראל ור רפאל יצחק ישראל, על מקומו אחריו. עלה לירושלים-תרט, רב ואב\"ד בירושלים וסירב להצעה להתמנות לראש\"ל (חבריו הדיינים: ר נסים שמואל יהודה ארואץ, ר אברהם אשכנזי, ר אהרן עזריאל, ר משה פארדו). התעשר מירושת דודו ר ידידיה שלמה ישראל. בניו - ר רחמים חיים יהודה ור ידידיה יוסף. חיבר \"שנות ימין\" אזמיר תרטו. (באוצר מופיע שם אביו - אליהו)."},{"i":25438,"n":"ישראל, משה","f":"שמואל","b":"תשובה ממנו-תקיט."},{"i":25439,"n":"ישראל, משה מאלכסנדריה","f":"חיים אברהם-בית אברהם","bp":"ירושלים","dt":"תקסא - אחרי?","b":"מחכמי ירושלים יחד עם דודו ר אליהו ישראל, תלמיד ר ברוך צאני. עבר עם דודו לאלכסנדריה-תקכז וכיהן כרב עם ר יונתן גלנטי. חיבר שות, פירושים ודרשות בכת\"י. תשובה ממנו ב\"חיים שנים\" ועוד."},{"i":25440,"n":"ישראל, משה מירושלים ורודוס","f":"אברהם בן בנימין","k":"בעל משאת משה","bt":"תלח-מ","bp":"ירושלים","dt":"תק","dp":"אלכסנדריה","b":"מחכמי ירושלים, תלמיד ר אברהם יצחקי, ותלמיד וחתן - ר משה ן חביב משלוניקי בעל \"גט פשוט\" (ובארזי הלבנון מוכיח כי המדובר ברב אחר ממשפחת ן חביב), בשנת תעא בשליחות, בדרכו חזרה עבר דרך רודוס ונתמנה שם לרב-תעד, שליח ירושלים-תפה, ואחריה רב באלכסנדריה-מצרים על מקום דודו ר אליהו ישראל. תלמידו ר ידידיה שמואל טארקיה מרודוס הספידו שם. חיבר \"משאת משה\" תפו. בניו - ר חיים אברהם, ר אליהו, ור יצחק, חתנו - ר מרדכי קריספין בעל \"מאמר מרדכי\", שכיהן כרב אחריו ברודוס. (על כתב שליחותו מצפת חתמו רבים מחכמי צפת)."},{"i":25441,"n":"ישראל, משה מפאס","b":"מחכמי פאס-שנות ה-ת'."},{"i":25442,"n":"ישראל, משה משלוניקי","b":"רופא בשלוניקי-תנו."},{"i":25443,"n":"ישראל, ראובן אליהו - חיר\"א","f":"רחמים חיים יהודה","k":"בעל אילן היחס","bt":"תרלג או תרכח","bp":"רודוס","dt":"תרצג - יט תשרי","b":"רב בקראיובה, ראב\"ד ברודוס."},{"i":25444,"n":"ישראל, רחמים חיים יהודה - רי\"ח","f":"מיכאל יעקב","k":"בעל בן ימין","bt":"תקעה","bp":"[רודוס]","dt":"תרנב - טו ניסן","dp":"רודוס","b":"רב ברודוס-תרמה, על מקום ר רפאל יצחק ישראל, ור שבתאי הלוי על מקומו אחריו-תרנא. בנו ר ראובן אליהו הוסיף הגהות לספר אביו, עוד מבניו - ר שמואל יעקב, ור ראובן אליהו רבה של רודוס, ור אשר.","bk":[["בן ימין","שו\"ת - אחרונים"]]},{"i":25445,"n":"ישראל, רפאל יהודה מרודוס","f":"חיים אברהם-בית אברהם","k":"בעל שומר מוסר","b":"מחכמי איטליה-תקן, רב ברודוס. הו\"ל \"מגן גיבורים\" לר אליעזר די אבילה."},{"i":25446,"n":"ישראל, רפאל יצחק מרודוס וירושל","f":"דוד","k":"בעל פתחי תשובה","r":"אב\"ד ור\"מ בלייפניק, וחמיו של הדברי חיים מצאנז","bt":"תקסח-ט","bp":"רודוס","dt":"תרסב - ז תמוז","dp":"ירושלים","b":"חתן ר מיכאל יעקב ישראל ובזיוו\"ש חתן ר יעקב ענתבי מדמשק, וגיסו של ר חיים שלמה אלעזר הלוי. רבה של רודוס-תרך, בשליחות קורפו באירופה לאחר הרעש. עלה לירושלים וכיהן ראבד לעדת הספרדים, חתנו של ר מיכאל יעקב ישראל ובזיווג שני של ר יעקב ענתבי מדמשק. חיבר גם \"בית היין\" בתמיכת הגביר יוסף נוטריקה מצליח, , ועוד. מפסקיו בספרי חכמי דורו וביניהם ר חיים פאלג'י. בנו ר חזקיה משה ואליו שלח צוואה מירושלים.","bk":[["בית היין",""]]},{"i":25447,"n":"ישראל, שלם מארבאט - הזקן","b":"מחכמי ארבאט-מרוקו."},{"i":25448,"n":"ישראל, שלם מארבאט - הנכד","b":"מחכמי ארבאט(=ראבאט), אולי הוא שחתם-תקמג עם ר יעקב אלמליח."},{"i":25449,"n":"ישראל, שלמה ממצרים","f":"אליהו ישראל","b":"מרבני מצרים-תק\"ס"},{"i":25450,"n":"ישראל, שמואל יעקב","f":"רחמים יהודה מרודוס","b":"אחיו - ר ראובן אליהו ישראל."},{"i":25451,"n":"ישראל, שמואל משלוניקי","b":"רב בשלוניקי-רפ."},{"i":25452,"n":"ישראלי שאול בן בנימין","bt":"1909","dt":"ה'תשנה 1995","bk":[["ארץ חמדה",""],["חוות בנימין",""],["שיעורי הגר\"ש ישראלי",""]]},{"i":25453,"n":"ישראלי, שאול מירושלים","b":"מראשי ישיבת מרכז הרב בירושלים. פרסם מאמרים ב\"תורת ירושלים\" - \"תפארת ירושלים\"- \"תורה מציון\" ירושלים תרצו."},{"i":25454,"n":"ישראליג'ה, דוד משלוניקי","b":"מדפיס בשלוניקי-תקמה עם מרדכי נחמן (שהיה לו גם דפוס עם רפאל קלעי)."},{"i":25455,"n":"ישראליגה, יעקב משלוניקי","f":"דוד","dt":"תקצג - אחרי","dp":"שלוניקי","b":"מחכמי שלוניקי-תקפה. הגיה \"בתי אבות\" לר יוסף דוד וחיבר לו הקדמה ופירות להושענות. חיבר קונטרס על הצדקה לפי הקבלה ונדפס בסוף \"ימי דוד\" לר יוסף דוד-תרו. נזכר ב\"מעט מים\" לר אברהם נחמן הכהן."},{"i":25456,"n":"ישראליג'ה, ישראל","b":"רב בירושלים."},{"i":25457,"n":"ישראליגה, שאלתיאל","dt":"שצד - יג תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":25458,"n":"יששכר בן יעקב אבינו","dt":"י אב"},{"i":25459,"n":"יששכר הלוי","f":"יקותיאל","k":"בעל קצור ספר התרומות","dt":"צב","b":"מגדולי הראשונים בחכמי אשכנז, דיין בטולידו בבית דינו של הרא\"ש."},{"i":25460,"n":"יתאח ן, יצחק מצפרו","dt":"תרכז - טו אדר","b":"מחכמי צפרו-תקפט."},{"i":25461,"n":"יתאח ן, מסעוד מצפרו","b":"מו\"ץ בצפרו-מרוקו וסופר שטרות, חתם-תקעה על פס\"ד."},{"i":25462,"n":"יתאח ן, רפאל ממרוקו","f":"מסעוד","b":"רב בצפרו-מרוקו - תקפח, וחתם אז על קבלת עדות עם ר ישראל יעקב עולייל. רב בקצנטינא-אלג'יר, בני הקהלה שלחו מכתב לרבני צפרו - ר ישראל עולייל, ר יהודה אלבאז ור עמור אביטבול, בענין שיביא את אשתו אליו לשם, ורבני צפרו פסקו שאו שישלח לה גט ע\"י שליח וישלם כתובתה, או שיפייסה על צער שנגרם לה."},{"i":25463,"n":"יתאח, מרדכי מצפרו","b":"מחכמי צפרו - שנות ה-תק'. בנו - ר יצחק."},{"i":25464,"n":"יתום, אברהם מקושטא ומצרים","b":"מדפיס בקושטא אצל יונה בן יעקב אשכנזי, עבר למצרים עם אחיו יעקב והקימו בית דפוס יחד עם הגביר ר אברהם צדיק, העביר את הדפוס לקושטא למדפיסים ראובן ונסים בני יונה אשכנזי."},{"i":25465,"n":"יתום-ערליך, דוד שמואל מאודיווק","bt":"תריז","b":"רב באבדיווקא-פלך פודוליה-תרסא."},{"i":25466,"n":"יתים, עבודי מבבל","dt":"תרנח - יט ניסן","b":"מחכמי בבל. נספד ע\"י ה\"בן איש חי\"."}];
